\set ON_ERROR_STOP on

set client_min_messages=warning;

create extension if not exists pgcrypto with schema extensions;

create extension if not exists "uuid-ossp" with schema extensions;

create extension if not exists pg_stat_statements with schema extensions;

create extension if not exists supabase_vault with schema vault;

create extension if not exists pg_cron with schema pg_catalog;

drop schema if exists erp cascade;

create schema erp authorization postgres;

create sequence "erp"."app_access_audit_id_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

alter sequence "erp"."app_access_audit_id_seq" owner to "postgres";

create sequence "erp"."audit_logs_id_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

alter sequence "erp"."audit_logs_id_seq" owner to "postgres";

create sequence "erp"."cost_recalc_queue_id_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

alter sequence "erp"."cost_recalc_queue_id_seq" owner to "postgres";

create sequence "erp"."cutting_qty_correction_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

alter sequence "erp"."cutting_qty_correction_seq" owner to "postgres";

create sequence "erp"."fg_stock_book_order_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

alter sequence "erp"."fg_stock_book_order_seq" owner to "postgres";

create sequence "erp"."production_pattern_audit_id_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

alter sequence "erp"."production_pattern_audit_id_seq" owner to "postgres";

