CREATE OR REPLACE FUNCTION erp._assert_attendance_hpp_manifest_v1(p_manifest jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_item jsonb;
begin
  perform erp._cp3_assert_closed_json_object(
    p_manifest,
    array['contract_version','operation_type','period_start','period_end','numerator_cents','denominator_qty','sources','destinations'],
    array['contract_version','operation_type','period_start','period_end','numerator_cents','denominator_qty','sources','destinations'],
    'attendance HPP manifest'
  );

  if jsonb_typeof(p_manifest->'contract_version') is distinct from 'string'
     or jsonb_typeof(p_manifest->'operation_type') is distinct from 'string'
     or jsonb_typeof(p_manifest->'period_start') is distinct from 'string'
     or jsonb_typeof(p_manifest->'period_end') is distinct from 'string'
     or jsonb_typeof(p_manifest->'numerator_cents') is distinct from 'number'
     or jsonb_typeof(p_manifest->'denominator_qty') is distinct from 'number'
     or jsonb_typeof(p_manifest->'sources') is distinct from 'array'
     or jsonb_typeof(p_manifest->'destinations') is distinct from 'array' then
    raise exception 'Attendance HPP manifest has invalid top-level types';
  end if;

  if p_manifest->>'contract_version' is distinct from 'ATTENDANCE_HPP_SEWING_TERMINAL_V1'
     or p_manifest->>'operation_type' is distinct from 'ATTENDANCE_HPP_POOL' then
    raise exception 'Attendance HPP manifest discriminator is invalid; claim/transfer/carry-forward/movement payloads are not accepted';
  end if;
  if p_manifest->>'period_start' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     or p_manifest->>'period_end' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    raise exception 'Attendance HPP manifest period dates must be canonical YYYY-MM-DD strings';
  end if;

  for v_item in select value from jsonb_array_elements(p_manifest->'sources')
  loop
    perform erp._cp3_assert_closed_json_object(
      v_item,
      array['payroll_id','contractor_id','policy_version_id','contractor_role_snapshot','attendance_required_snapshot','is_special_snapshot','policy_effective_from','original_debit_journal_line_id','original_debit_amount_cents','attendance_amount_cents'],
      array['payroll_id','contractor_id','policy_version_id','contractor_role_snapshot','attendance_required_snapshot','is_special_snapshot','policy_effective_from','policy_effective_to','original_debit_journal_line_id','original_debit_amount_cents','attendance_amount_cents'],
      'attendance HPP source'
    );
    if not (v_item ? 'policy_effective_to') then
      raise exception 'attendance HPP source requires key policy_effective_to, which may be JSON null for open-ended coverage';
    end if;
    if jsonb_typeof(v_item->'payroll_id') is distinct from 'string'
       or jsonb_typeof(v_item->'contractor_id') is distinct from 'string'
       or jsonb_typeof(v_item->'policy_version_id') is distinct from 'string'
       or jsonb_typeof(v_item->'contractor_role_snapshot') is distinct from 'string'
       or jsonb_typeof(v_item->'attendance_required_snapshot') is distinct from 'boolean'
       or jsonb_typeof(v_item->'is_special_snapshot') is distinct from 'boolean'
       or jsonb_typeof(v_item->'policy_effective_from') is distinct from 'string'
       or (v_item->'policy_effective_to' <> 'null'::jsonb
           and jsonb_typeof(v_item->'policy_effective_to') is distinct from 'string')
       or jsonb_typeof(v_item->'original_debit_journal_line_id') is distinct from 'string'
       or jsonb_typeof(v_item->'original_debit_amount_cents') is distinct from 'number'
       or jsonb_typeof(v_item->'attendance_amount_cents') is distinct from 'number' then
      raise exception 'attendance HPP source has invalid nested field types';
    end if;
    if v_item->>'contractor_role_snapshot' is distinct from 'MANDOR'
       or v_item->'attendance_required_snapshot' is distinct from 'true'::jsonb
       or v_item->'is_special_snapshot' is distinct from 'false'::jsonb then
      raise exception 'Attendance HPP source is not an eligible normal Mandor snapshot';
    end if;
    if v_item->>'policy_effective_from' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
       or (v_item->'policy_effective_to' <> 'null'::jsonb
           and v_item->>'policy_effective_to' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$') then
      raise exception 'attendance HPP source policy dates must be canonical YYYY-MM-DD strings';
    end if;
  end loop;

  for v_item in select value from jsonb_array_elements(p_manifest->'destinations')
  loop
    perform erp._cp3_assert_closed_json_object(
      v_item,
      array['sewing_terminal_event_id','source_work_completion_id','contractor_id','po_id','cutting_group_id','policy_version_id','contractor_role_snapshot','attendance_required_snapshot','is_special_snapshot','physical_at_epoch_us','sewing_qty'],
      array['sewing_terminal_event_id','source_work_completion_id','contractor_id','po_id','cutting_group_id','policy_version_id','contractor_role_snapshot','attendance_required_snapshot','is_special_snapshot','physical_at_epoch_us','sewing_qty'],
      'attendance HPP destination'
    );
    if jsonb_typeof(v_item->'sewing_terminal_event_id') is distinct from 'string'
       or jsonb_typeof(v_item->'source_work_completion_id') is distinct from 'string'
       or jsonb_typeof(v_item->'contractor_id') is distinct from 'string'
       or jsonb_typeof(v_item->'po_id') is distinct from 'string'
       or jsonb_typeof(v_item->'cutting_group_id') is distinct from 'string'
       or jsonb_typeof(v_item->'policy_version_id') is distinct from 'string'
       or jsonb_typeof(v_item->'contractor_role_snapshot') is distinct from 'string'
       or jsonb_typeof(v_item->'attendance_required_snapshot') is distinct from 'boolean'
       or jsonb_typeof(v_item->'is_special_snapshot') is distinct from 'boolean'
       or jsonb_typeof(v_item->'physical_at_epoch_us') is distinct from 'number'
       or jsonb_typeof(v_item->'sewing_qty') is distinct from 'number' then
      raise exception 'attendance HPP destination has invalid nested field types';
    end if;
    if v_item->>'contractor_role_snapshot' is distinct from 'MANDOR'
       or v_item->'attendance_required_snapshot' is distinct from 'true'::jsonb
       or v_item->'is_special_snapshot' is distinct from 'false'::jsonb then
      raise exception 'Attendance HPP destination is not an eligible normal Mandor snapshot';
    end if;
  end loop;
end;
$function$;

alter function "erp"."_assert_attendance_hpp_manifest_v1"(p_manifest jsonb) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._cp3_assert_closed_json_object(p_value jsonb, p_required_keys text[], p_allowed_keys text[], p_label text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_key text;
begin
  if p_value is null or jsonb_typeof(p_value) is distinct from 'object' then
    raise exception '% must be a JSON object', coalesce(p_label, 'payload');
  end if;

  foreach v_key in array coalesce(p_required_keys, array[]::text[])
  loop
    if not (p_value ? v_key)
       or coalesce(jsonb_typeof(p_value -> v_key), 'missing') = 'null' then
      raise exception '% requires non-null key %', coalesce(p_label, 'payload'), v_key;
    end if;
  end loop;

  select k into v_key
  from jsonb_object_keys(p_value) as x(k)
  where not (k = any(coalesce(p_allowed_keys, array[]::text[])))
  order by k
  limit 1;

  if v_key is not null then
    raise exception '% contains unexpected key %', coalesce(p_label, 'payload'), v_key;
  end if;
end;
$function$;

alter function "erp"."_cp3_assert_closed_json_object"(p_value jsonb, p_required_keys text[], p_allowed_keys text[], p_label text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._cp3_lock_business_date(p_business_date date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if p_business_date is null then raise exception 'CP3 business date lock requires a date'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'ATTENDANCE_HPP_BUSINESS_DATE|' || erp._cp3_canonical_date(p_business_date), 0
  ));
end;
$function$;

alter function "erp"."_cp3_lock_business_date"(p_business_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._cp3_lock_business_period(p_period_start date, p_period_end date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_day date;
begin
  if p_period_start is null or p_period_end is null or p_period_end < p_period_start then
    raise exception 'CP3 business period lock requires a valid date range';
  end if;
  if p_period_end - p_period_start > 366 then
    raise exception 'CP3 business period lock is bounded to 367 calendar days';
  end if;
  for v_day in
    select d::date from generate_series(p_period_start::timestamp, p_period_end::timestamp, interval '1 day') d order by 1
  loop
    perform erp._cp3_lock_business_date(v_day);
  end loop;
end;
$function$;

alter function "erp"."_cp3_lock_business_period"(p_period_start date, p_period_end date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._cp3_lock_manifest_contractors(p_period_start date, p_period_end date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_contractor_id uuid;
begin
  for v_contractor_id in
    select contractor_id
    from (
      select ps.contractor_id
      from erp.payroll_settlements ps
      where ps.status in ('APPROVED','PAID')
        and ps.period_start = p_period_start and ps.period_end = p_period_end
        and ps.attendance_total > 0
      union
      select e.contractor_id
      from erp.sewing_terminal_events e
      where e.event_kind = 'SELESAI_DIJAHIT'
        and erp._cp3_business_date(e.physical_at) between p_period_start and p_period_end
        and not exists (select 1 from erp.sewing_terminal_events rv where rv.reversal_of_id=e.id)
    ) s
    order by contractor_id
  loop
    perform pg_advisory_xact_lock(hashtextextended('CONTRACTOR_HPP_POLICY|' || v_contractor_id::text, 0));
  end loop;
end;
$function$;

alter function "erp"."_cp3_lock_manifest_contractors"(p_period_start date, p_period_end date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._cp3_parse_canonical_date(p_value text, p_label text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_date date;
begin
  if p_value is null or p_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    raise exception '% must be a canonical YYYY-MM-DD string', coalesce(p_label,'date');
  end if;
  v_date := p_value::date;
  if to_char(v_date,'YYYY-MM-DD') is distinct from p_value then
    raise exception '% is not a real canonical calendar date', coalesce(p_label,'date');
  end if;
  return v_date;
exception when datetime_field_overflow or invalid_datetime_format then
  raise exception '% is not a real canonical calendar date', coalesce(p_label,'date');
end;
$function$;

alter function "erp"."_cp3_parse_canonical_date"(p_value text, p_label text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._cp3_r4_active_pool_affects_contractor(p_contractor_id uuid, p_effective_from date, p_next_effective_from date DEFAULT NULL::date)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_sql text;
  v_hit boolean;
  v_join text;
  v_contractor_expr text;
begin
  if p_contractor_id is null or p_effective_from is null then
    raise exception 'R4 active-pool policy overlap requires contractor and effective_from';
  end if;

  for r in
    select c.table_name
    from information_schema.columns c
    where c.table_schema='erp'
      and c.column_name='pool_id'
      and c.table_name like 'attendance_hpp_pool_%'
    group by c.table_name
    order by c.table_name
  loop
    v_join:='';
    v_contractor_expr:=null;

    if exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='contractor_id') then
      v_contractor_expr:='x.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='payroll_id') then
      v_join:=' join erp.payroll_settlements ps on ps.id=x.payroll_id ';
      v_contractor_expr:='ps.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='source_payroll_id') then
      v_join:=' join erp.payroll_settlements ps on ps.id=x.source_payroll_id ';
      v_contractor_expr:='ps.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='payroll_settlement_id') then
      v_join:=' join erp.payroll_settlements ps on ps.id=x.payroll_settlement_id ';
      v_contractor_expr:='ps.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='sewing_terminal_event_id') then
      v_join:=' join erp.sewing_terminal_events ste on ste.id=x.sewing_terminal_event_id ';
      v_contractor_expr:='ste.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='destination_event_id') then
      v_join:=' join erp.sewing_terminal_events ste on ste.id=x.destination_event_id ';
      v_contractor_expr:='ste.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='source_journal_line_id') then
      v_join:=' join erp.journal_lines jl on jl.id=x.source_journal_line_id join erp.journal_entries je on je.id=jl.journal_entry_id join erp.payroll_settlements ps on ps.id=je.source_id ';
      v_contractor_expr:='ps.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='original_payroll_debit_journal_line_id') then
      v_join:=' join erp.journal_lines jl on jl.id=x.original_payroll_debit_journal_line_id join erp.journal_entries je on je.id=jl.journal_entry_id join erp.payroll_settlements ps on ps.id=je.source_id ';
      v_contractor_expr:='ps.contractor_id';
    end if;

    if v_contractor_expr is not null then
      v_sql:=format(
        'select exists(select 1 from erp.%I x join erp.attendance_hpp_pools p on p.id=x.pool_id %s where p.status=''ACTIVE'' and p.period_end >= $2 and ($3 is null or p.period_start < $3) and %s=$1)',
        r.table_name,v_join,v_contractor_expr
      );
      execute v_sql into v_hit using p_contractor_id,p_effective_from,p_next_effective_from;
      if v_hit then return true; end if;
    end if;
  end loop;

  return false;
end
$function$;

alter function "erp"."_cp3_r4_active_pool_affects_contractor"(p_contractor_id uuid, p_effective_from date, p_next_effective_from date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._cp3_r4_reverse_journal_internal(p_journal_entry_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_old erp.journal_entries%ROWTYPE;v_new_id uuid;v_lines jsonb; BEGIN PERFORM erp.require_internal(); SELECT * INTO v_old FROM erp.journal_entries WHERE id=p_journal_entry_id FOR UPDATE; IF v_old.id IS NULL OR v_old.status<>'POSTED' THEN RAISE EXCEPTION 'Only posted journal can be reversed'; END IF; SELECT jsonb_agg(jsonb_build_object('account_id',jl.account_id,'debit',jl.credit,'credit',jl.debit,'description','Reversal: '||COALESCE(jl.description,''),'customer_id',jl.customer_id,'vendor_id',jl.vendor_id,'contractor_id',jl.contractor_id,'po_id',jl.po_id,'product_id',jl.product_id)) INTO v_lines FROM erp.journal_lines jl WHERE jl.journal_entry_id=p_journal_entry_id; v_new_id:=erp.post_journal('JOURNAL_REVERSAL',p_journal_entry_id,CURRENT_DATE,'Reversal: '||v_old.description||' | '||p_reason,v_lines); UPDATE erp.journal_entries SET status='REVERSED' WHERE id=p_journal_entry_id; UPDATE erp.journal_entries SET reversal_of_id=p_journal_entry_id WHERE id=v_new_id; RETURN v_new_id; END; $function$;

alter function "erp"."_cp3_r4_reverse_journal_internal"(p_journal_entry_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._idempotency_begin(p_operation_name text, p_client_request_id uuid, p_request_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_actor text := erp._idempotency_actor_key();
  v_row erp.idempotency_requests%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;
  if coalesce(btrim(p_operation_name), '') = '' then
    raise exception 'operation_name is required';
  end if;

  insert into erp.idempotency_requests(
    actor_key, operation_name, client_request_id, request_hash
  ) values (
    v_actor, p_operation_name, p_client_request_id, p_request_hash
  )
  on conflict do nothing;

  select * into v_row
  from erp.idempotency_requests
  where actor_key = v_actor
    and operation_name = p_operation_name
    and client_request_id = p_client_request_id
  for update;

  if v_row.request_hash <> p_request_hash then
    raise exception 'client_request_id was already used with a different payload';
  end if;
  if v_row.status = 'COMPLETED' then
    return v_row.response_payload;
  end if;
  return null;
end;
$function$;

alter function "erp"."_idempotency_begin"(p_operation_name text, p_client_request_id uuid, p_request_hash text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._idempotency_complete(p_operation_name text, p_client_request_id uuid, p_response jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_actor text := erp._idempotency_actor_key();
begin
  update erp.idempotency_requests
  set status = 'COMPLETED', response_payload = p_response, updated_at = now()
  where actor_key = v_actor
    and operation_name = p_operation_name
    and client_request_id = p_client_request_id
    and status = 'IN_PROGRESS';
  if not found then
    raise exception 'Idempotency request is missing or already completed';
  end if;
  return p_response;
end;
$function$;

alter function "erp"."_idempotency_complete"(p_operation_name text, p_client_request_id uuid, p_response jsonb) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._post_cutting_qty_correction(p_cutting_batch_id uuid, p_correction_type text, p_reason_code text, p_reason text, p_lines jsonb, p_physical_at timestamp with time zone, p_reversal_of_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
DECLARE
  v_id uuid;
  v_po_id uuid;
  v_number text;
  v_total_delta bigint;
  v_line_count integer;
  v_current bigint;
  v_committed bigint;
  v_new bigint;
  v_group_batch uuid;
  r record;
BEGIN
  PERFORM erp.require_internal();

  SELECT po_id INTO v_po_id
  FROM erp.cutting_batches
  WHERE id=p_cutting_batch_id
  FOR UPDATE;
  IF v_po_id IS NULL THEN
    RAISE EXCEPTION 'Cutting batch not found';
  END IF;

  IF p_correction_type NOT IN ('RECOUNT','REDISTRIBUTION','REVERSAL','OTHER') THEN
    RAISE EXCEPTION 'Invalid cutting correction type';
  END IF;
  IF COALESCE(btrim(p_reason_code),'')='' OR COALESCE(btrim(p_reason),'')='' THEN
    RAISE EXCEPTION 'Correction reason code and reason are required';
  END IF;
  IF jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines)=0 THEN
    RAISE EXCEPTION 'Correction requires at least one line';
  END IF;

  IF p_reversal_of_id IS NULL AND p_correction_type='REVERSAL' THEN
    RAISE EXCEPTION 'REVERSAL requires a source correction';
  END IF;
  IF p_reversal_of_id IS NOT NULL THEN
    IF p_correction_type <> 'REVERSAL' THEN
      RAISE EXCEPTION 'reversal_of_id is only valid for REVERSAL';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM erp.cutting_qty_corrections c
      WHERE c.id=p_reversal_of_id AND c.cutting_batch_id=p_cutting_batch_id
    ) THEN
      RAISE EXCEPTION 'Source correction not found in this cutting batch';
    END IF;
    IF EXISTS (SELECT 1 FROM erp.cutting_qty_corrections c WHERE c.reversal_of_id=p_reversal_of_id) THEN
      RAISE EXCEPTION 'Correction has already been reversed';
    END IF;
  END IF;

  WITH parsed AS (
    SELECT
      NULLIF(x->>'cutting_group_id','')::uuid AS group_id,
      NULLIF(x->>'size_slot_id','')::uuid AS size_slot_id,
      (x->>'qty_delta_pcs')::integer AS delta
    FROM jsonb_array_elements(p_lines) x
  )
  SELECT COALESCE(SUM(delta),0)::bigint, COUNT(*)::integer
  INTO v_total_delta,v_line_count
  FROM parsed
  WHERE group_id IS NOT NULL AND delta <> 0;

  IF v_line_count=0 THEN
    RAISE EXCEPTION 'Correction contains no valid non-zero lines';
  END IF;
  IF p_correction_type='REDISTRIBUTION' AND v_total_delta<>0 THEN
    RAISE EXCEPTION 'REDISTRIBUTION must net to zero across groups';
  END IF;

  FOR r IN
    WITH parsed AS (
      SELECT NULLIF(x->>'cutting_group_id','')::uuid AS group_id,
             (x->>'qty_delta_pcs')::integer AS delta
      FROM jsonb_array_elements(p_lines) x
    )
    SELECT group_id,SUM(delta)::bigint AS delta
    FROM parsed
    WHERE group_id IS NOT NULL AND delta<>0
    GROUP BY group_id
  LOOP
    SELECT cutting_batch_id INTO v_group_batch
    FROM erp.cutting_groups
    WHERE id=r.group_id
    FOR UPDATE;
    IF v_group_batch IS NULL OR v_group_batch<>p_cutting_batch_id THEN
      RAISE EXCEPTION 'Cutting group % does not belong to correction batch',r.group_id;
    END IF;

    SELECT total_pcs INTO v_current
    FROM erp.v_cutting_group_totals
    WHERE cutting_group_id=r.group_id;
    v_current:=COALESCE(v_current,0);
    v_new:=v_current+r.delta;
    v_committed:=erp.cutting_group_downstream_committed_qty(r.group_id);

    IF v_new<0 THEN
      RAISE EXCEPTION 'Correction would make cutting group % negative: % pcs',r.group_id,v_new;
    END IF;
    IF v_new<v_committed THEN
      RAISE EXCEPTION 'Correction would reduce group % to % pcs, but % pcs are already committed downstream',r.group_id,v_new,v_committed;
    END IF;
  END LOOP;

  v_number:='CQC-'||to_char(COALESCE(p_physical_at,now()) AT TIME ZONE 'Asia/Jakarta','YYYYMMDD')||'-'||lpad(nextval('erp.cutting_qty_correction_seq')::text,6,'0');

  INSERT INTO erp.cutting_qty_corrections(
    correction_number,cutting_batch_id,correction_type,reason_code,reason,physical_at,reversal_of_id,posted_by
  ) VALUES (
    v_number,p_cutting_batch_id,p_correction_type,p_reason_code,p_reason,COALESCE(p_physical_at,now()),p_reversal_of_id,erp.current_app_user_id()
  ) RETURNING id INTO v_id;

  INSERT INTO erp.cutting_qty_correction_lines(correction_id,cutting_group_id,size_slot_id,qty_delta_pcs,notes)
  WITH parsed AS (
    SELECT NULLIF(x->>'cutting_group_id','')::uuid AS group_id,
           NULLIF(x->>'size_slot_id','')::uuid AS size_slot_id,
           (x->>'qty_delta_pcs')::integer AS delta,
           NULLIF(x->>'notes','') AS notes
    FROM jsonb_array_elements(p_lines) x
  )
  SELECT v_id,group_id,size_slot_id,SUM(delta)::integer,MAX(notes)
  FROM parsed
  WHERE group_id IS NOT NULL AND delta<>0
  GROUP BY group_id,size_slot_id
  HAVING SUM(delta)<>0;

  INSERT INTO erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  VALUES (
    'cutting_qty_corrections',v_id,'POST',
    jsonb_build_object('correction_number',v_number,'type',p_correction_type,'batch_id',p_cutting_batch_id,'net_delta_pcs',v_total_delta,'lines',p_lines),
    erp.current_app_user_id(),p_reason
  );

  IF EXISTS (SELECT 1 FROM erp.fg_lots WHERE po_id=v_po_id AND lot_origin='PRODUCTION') THEN
    PERFORM erp.rebuild_po_hpp(v_po_id,'Cutting quantity correction '||v_number);
    PERFORM erp.propagate_conversion_hpp_for_po(v_po_id);
    PERFORM erp.sync_po_hpp_to_gl(v_po_id,COALESCE(p_physical_at,now())::date);
  END IF;

  RETURN v_id;
END;
$function$;

alter function "erp"."_post_cutting_qty_correction"(p_cutting_batch_id uuid, p_correction_type text, p_reason_code text, p_reason text, p_lines jsonb, p_physical_at timestamp with time zone, p_reversal_of_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._recalculate_material_cost_core(p_material_id uuid, p_recalc_from timestamp with time zone, p_allow_checkpoint boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  r erp.material_stock_movements%rowtype;
  rr record;
  v_stock numeric(18,6):=0;
  v_avg numeric(18,6):=0;
  v_stock_before numeric(18,6);
  v_avg_before numeric(18,6);
  v_cost numeric(18,6);
  v_new_stock numeric(18,6);
  v_new_avg numeric(18,6);
  v_closed date;
  v_cp erp.material_cost_checkpoints%rowtype;
  v_use_checkpoint boolean:=false;
begin
  perform erp.require_internal();
  select closed_through into v_closed from erp.accounting_period_control where singleton_id=1 for share;
  perform 1 from erp.materials where id=p_material_id for update;
  if not found then raise exception 'Material not found'; end if;

  if p_allow_checkpoint and p_recalc_from is not null and v_closed is not null then
    select * into v_cp from erp.material_cost_checkpoints where material_id=p_material_id;
    if v_cp.material_id is not null
       and v_cp.checkpoint_date<=v_closed
       and p_recalc_from::date>v_cp.checkpoint_date then
      v_use_checkpoint:=true;
      v_stock:=v_cp.stock_qty;
      v_avg:=v_cp.moving_average_cost;
    end if;
  end if;

  if v_use_checkpoint then
    if v_cp.last_movement_id is null then
      delete from erp.material_cost_history where material_id=p_material_id;
    else
      delete from erp.material_cost_history h
      using erp.material_stock_movements msm
      where h.material_id=p_material_id and h.movement_id=msm.id
        and (msm.physical_at,msm.system_created_at,msm.id)>(v_cp.last_physical_at,v_cp.last_system_created_at,v_cp.last_movement_id);
    end if;
  else
    delete from erp.material_cost_history where material_id=p_material_id;
  end if;

  for r in
    select * from erp.material_stock_movements msm
    where msm.material_id=p_material_id
      and msm.reversal_of_id is null
      and not exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=msm.id)
      and (
        not v_use_checkpoint
        or v_cp.last_movement_id is null
        or (msm.physical_at,msm.system_created_at,msm.id)>(v_cp.last_physical_at,v_cp.last_system_created_at,v_cp.last_movement_id)
      )
    order by msm.physical_at,msm.system_created_at,msm.id
    for update
  loop
    v_stock_before:=v_stock;
    v_avg_before:=v_avg;
    if r.qty_signed>0 then
      if r.movement_type='REVERSAL' and r.reversal_of_id is not null then
        select x.unit_cost_snapshot into v_cost from erp.material_stock_movements x where x.id=r.reversal_of_id;
        v_cost:=coalesce(v_cost,r.input_unit_cost,r.unit_cost_snapshot,v_avg);
      elsif r.movement_type='CUTTING_RETURN' and r.source_type='CUTTING_GROUP_RETURN' then
        select x.unit_cost_snapshot into v_cost
        from erp.material_stock_movements x
        where x.material_id=r.material_id
          and x.source_type='CUTTING_GROUP' and x.source_id=r.source_id
          and x.movement_type='CUTTING_ISSUE'
          and x.roll_id is not distinct from r.roll_id
        order by x.physical_at desc,x.system_created_at desc,x.id desc limit 1;
        v_cost:=coalesce(v_cost,r.input_unit_cost,r.unit_cost_snapshot,v_avg);
      else
        v_cost:=coalesce(r.input_unit_cost,r.unit_cost_snapshot,v_avg);
      end if;
      v_new_stock:=v_stock+r.qty_signed;
      if v_new_stock>0 then
        v_new_avg:=((v_stock*v_avg)+(r.qty_signed*v_cost))/v_new_stock;
      else
        v_new_avg:=0;
      end if;
    else
      v_new_stock:=v_stock+r.qty_signed;
      if v_new_stock<0 then
        raise exception 'Backdate/correction would create negative material stock for material %, movement %',p_material_id,r.id;
      end if;
      v_cost:=v_avg;
      v_new_avg:=case when v_new_stock=0 then 0 else v_avg end;
    end if;

    update erp.material_stock_movements
    set original_unit_cost_snapshot=coalesce(original_unit_cost_snapshot,v_cost),
        unit_cost_snapshot=v_cost,
        is_cost_recalculated=true
    where id=r.id;

    insert into erp.material_cost_history(material_id,movement_id,physical_at,stock_before,average_before,movement_qty,movement_unit_cost,stock_after,average_after)
    values(p_material_id,r.id,r.physical_at,v_stock_before,v_avg_before,r.qty_signed,v_cost,v_new_stock,v_new_avg);
    v_stock:=v_new_stock;
    v_avg:=v_new_avg;
  end loop;

  for rr in
    select mr.id as roll_id,coalesce(sum(msm.qty_signed),0)::numeric as roll_qty
    from erp.material_rolls mr
    left join erp.material_stock_movements msm on msm.roll_id=mr.id
    where mr.material_id=p_material_id
    group by mr.id
  loop
    if rr.roll_qty<0 then raise exception 'Correction would create negative roll stock for roll %',rr.roll_id; end if;
    update erp.material_rolls
    set cached_qty=rr.roll_qty,
        status=case when rr.roll_qty=0 then 'EXHAUSTED' when rr.roll_qty<original_qty then 'HALF_USED' else 'AVAILABLE' end,
        updated_at=now()
    where id=rr.roll_id and status<>'RETURNED_SUPPLIER';
  end loop;

  update erp.cutting_group_rolls cgr
  set unit_cost_snapshot=(
    select msm.unit_cost_snapshot
    from erp.material_stock_movements msm
    where msm.material_id=p_material_id and msm.source_type='CUTTING_GROUP'
      and msm.source_id=cgr.cutting_group_id and msm.movement_type='CUTTING_ISSUE'
      and msm.roll_id is not distinct from cgr.roll_id
    order by msm.physical_at desc,msm.system_created_at desc,msm.id desc limit 1
  )
  where exists(
    select 1 from erp.material_stock_movements msm
    where msm.material_id=p_material_id and msm.source_type='CUTTING_GROUP'
      and msm.source_id=cgr.cutting_group_id and msm.movement_type='CUTTING_ISSUE'
      and msm.roll_id is not distinct from cgr.roll_id
  );

  update erp.contractor_material_issue_items ii
  set unit_cost_snapshot=(
    select msm.unit_cost_snapshot from erp.material_stock_movements msm
    where msm.material_id=p_material_id and msm.source_type='CONTRACTOR_MATERIAL_ISSUE_ITEM'
      and msm.source_id=ii.id and msm.movement_type='CONTRACTOR_ISSUE'
    order by msm.physical_at desc,msm.system_created_at desc,msm.id desc limit 1
  )
  where ii.material_id=p_material_id and exists(
    select 1 from erp.material_stock_movements msm
    where msm.material_id=p_material_id and msm.source_type='CONTRACTOR_MATERIAL_ISSUE_ITEM'
      and msm.source_id=ii.id and msm.movement_type='CONTRACTOR_ISSUE'
  );

  update erp.materials set cached_stock_qty=v_stock,moving_average_cost=v_avg,updated_at=now() where id=p_material_id;

  perform erp.sync_material_cost_revaluation(p_material_id);

  insert into erp.cost_recalc_queue(entity_type,entity_id,recalc_from,reason)
  select distinct 'PO',cg.po_id,min(msm.physical_at),'Material moving-average/backdate recalculation'
  from erp.material_stock_movements msm
  join erp.cutting_groups cg on msm.source_type in('CUTTING_GROUP','CUTTING_GROUP_RETURN') and msm.source_id=cg.id
  where msm.material_id=p_material_id
    and exists(select 1 from erp.fg_lots fl where fl.po_id=cg.po_id)
    and not exists(select 1 from erp.cost_recalc_queue q where q.entity_type='PO' and q.entity_id=cg.po_id and (q.status in('PENDING','RUNNING') or (q.status='FAILED' and q.attempt_count<3)))
  group by cg.po_id;

  insert into erp.cost_recalc_queue(entity_type,entity_id,recalc_from,reason)
  select distinct 'PO',cmi.po_id,min(msm.physical_at),'Contractor material moving-average/backdate recalculation'
  from erp.material_stock_movements msm
  join erp.contractor_material_issue_items ii on msm.source_type='CONTRACTOR_MATERIAL_ISSUE_ITEM' and msm.source_id=ii.id
  join erp.contractor_material_issues cmi on cmi.id=ii.issue_id
  where msm.material_id=p_material_id and cmi.po_id is not null
    and exists(select 1 from erp.fg_lots fl where fl.po_id=cmi.po_id)
    and not exists(select 1 from erp.cost_recalc_queue q where q.entity_type='PO' and q.entity_id=cmi.po_id and (q.status in('PENDING','RUNNING') or (q.status='FAILED' and q.attempt_count<3)))
  group by cmi.po_id;

  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('materials',p_material_id,'RECALCULATE',jsonb_build_object('cached_stock_qty',v_stock,'moving_average_cost',v_avg,'original_movement_snapshots_preserved',true,'gl_revaluation_synced',true,'checkpoint_used',v_use_checkpoint,'recalc_from',p_recalc_from),erp.current_app_user_id(),'Material chronological moving-average recalculation');

  perform erp.refresh_accessory_hpp_after_material_recost(p_material_id,'Material chronological moving-average recalculation');

  if not v_use_checkpoint and v_closed is not null then
    perform erp.refresh_material_cost_checkpoint(p_material_id,v_closed);
  end if;
end;
$function$;

alter function "erp"."_recalculate_material_cost_core"(p_material_id uuid, p_recalc_from timestamp with time zone, p_allow_checkpoint boolean) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._release_sale_draft_reservations(p_sale_id uuid, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_reversal_id uuid;
  v_released bigint := 0;
begin
  perform erp.require_internal();
  for r in
    select m.*
    from erp.fg_stock_movements m
    join erp.sales_items i on i.id = m.source_id
    where i.sale_id = p_sale_id
      and m.source_type = 'SALE_ITEM'
      and m.movement_type = 'SALE_RESERVE'
      and not exists (
        select 1 from erp.fg_stock_movements rv where rv.reversal_of_id = m.id
      )
    order by m.physical_at, m.book_order, m.id
    for update of m
  loop
    v_reversal_id := erp.post_fg_movement(
      r.product_id,r.lot_id,r.location_id,r.quality_grade,
      'REVERSAL',-r.qty_signed,r.unit_hpp_snapshot,r.customer_id,
      'FG_MOVEMENT_REVERSAL',r.id,r.physical_at,
      coalesce(nullif(btrim(p_reason),''),'Release sales Draft reservation'),false
    );
    update erp.fg_stock_movements
    set reversal_of_id = r.id
    where id = v_reversal_id;
    v_released := v_released + abs(r.qty_signed);
  end loop;

  delete from erp.sale_stock_allocations a
  using erp.sales_items i
  where a.sale_item_id = i.id
    and i.sale_id = p_sale_id;
  return v_released;
end;
$function$;

alter function "erp"."_release_sale_draft_reservations"(p_sale_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._reserve_sale_draft(p_sale_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  h erp.sales_headers%rowtype;
  item record;
  lotrow record;
  v_need integer;
  v_take integer;
  v_hpp numeric(18,6);
  v_reserved bigint := 0;
begin
  perform erp.require_internal();
  select * into h from erp.sales_headers where id = p_sale_id for update;
  if h.id is null or h.status <> 'DRAFT' then
    raise exception 'Sale must be DRAFT before reservation';
  end if;
  if h.source_location_id is null then
    raise exception 'Sale source FG location is required';
  end if;
  if not exists (select 1 from erp.sales_items where sale_id = h.id) then
    raise exception 'Sale has no items';
  end if;
  if exists (
    select 1
    from erp.fg_stock_movements m
    join erp.sales_items i on i.id = m.source_id
    where i.sale_id = h.id
      and m.movement_type = 'SALE_RESERVE'
      and not exists (select 1 from erp.fg_stock_movements rv where rv.reversal_of_id = m.id)
  ) then
    raise exception 'Active Draft reservation already exists; release it before rebuilding';
  end if;

  for item in
    select * from erp.sales_items where sale_id = h.id order by product_id,id
  loop
    insert into erp.fg_inventory_balances(product_id,location_id,quality_grade,cached_qty_pcs)
    values(item.product_id,h.source_location_id,'GRADE_A',0)
    on conflict(product_id,location_id,quality_grade) do nothing;
    perform 1
    from erp.fg_inventory_balances
    where product_id = item.product_id
      and location_id = h.source_location_id
      and quality_grade = 'GRADE_A'
    for update;

    v_need := item.qty_pcs;
    for lotrow in
      select fl.id,sum(fm.qty_signed)::integer as location_qty,fl.produced_at
      from erp.fg_lots fl
      join erp.fg_stock_movements fm on fm.lot_id = fl.id
      where fl.product_id = item.product_id
        and fm.location_id = h.source_location_id
        and fm.quality_grade = 'GRADE_A'
      group by fl.id,fl.produced_at
      having sum(fm.qty_signed) > 0
      order by fl.produced_at,fl.id
    loop
      exit when v_need <= 0;
      perform 1 from erp.fg_lots where id = lotrow.id for update;
      v_take := least(v_need,lotrow.location_qty);
      v_hpp := coalesce(erp.lock_current_hpp_per_pcs(lotrow.id),0);
      insert into erp.sale_stock_allocations(
        sale_item_id,lot_id,location_id,qty_pcs,unit_hpp_snapshot
      ) values (
        item.id,lotrow.id,h.source_location_id,v_take,v_hpp
      );
      perform erp.post_fg_movement(
        item.product_id,lotrow.id,h.source_location_id,'GRADE_A',
        'SALE_RESERVE',-v_take,v_hpp,h.customer_id,'SALE_ITEM',item.id,
        h.sale_date,'Draft invoice reserve · reduces sellable stock',false
      );
      v_need := v_need - v_take;
      v_reserved := v_reserved + v_take;
    end loop;
    if v_need > 0 then
      raise exception 'Insufficient FG stock for product %; short % pcs',item.product_id,v_need;
    end if;
  end loop;
  return v_reserved;
end;
$function$;

alter function "erp"."_reserve_sale_draft"(p_sale_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._reverse_material_purchase_stock_at_source_time(p_purchase_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare m uuid;
begin
  perform erp.require_internal();
  perform erp._stage_reverse_material_purchase_stock_at_source_time(p_purchase_id,p_reason);
  for m in select distinct material_id from erp.material_purchase_items where purchase_id=p_purchase_id loop
    perform erp.recalculate_material_cost(m);
  end loop;
end;
$function$;

alter function "erp"."_reverse_material_purchase_stock_at_source_time"(p_purchase_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._stage_reverse_material_purchase_stock_at_source_time(p_purchase_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare r record;
begin
  perform erp.require_internal();
  for r in
    select msm.*
    from erp.material_stock_movements msm
    where msm.movement_type='PURCHASE' and (
      (msm.source_type='MATERIAL_PURCHASE_ITEM' and msm.source_id in (select id from erp.material_purchase_items where purchase_id=p_purchase_id))
      or (msm.source_type='MATERIAL_PURCHASE_ROLL' and msm.source_id in (
        select mr.id from erp.material_rolls mr join erp.material_purchase_items mpi on mpi.id=mr.purchase_item_id where mpi.purchase_id=p_purchase_id
      ))
    )
    and not exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=msm.id)
    order by msm.physical_at,msm.system_created_at,msm.id
  loop
    insert into erp.material_stock_movements(material_id,roll_id,location_id,movement_type,qty_signed,input_unit_cost,unit_cost_snapshot,source_type,source_id,physical_at,system_created_at,created_by,reversal_of_id,note)
    values(r.material_id,r.roll_id,r.location_id,'REVERSAL',-r.qty_signed,
      case when -r.qty_signed>0 then r.unit_cost_snapshot else null end,r.unit_cost_snapshot,
      'MATERIAL_PURCHASE_REVERSAL',r.id,r.physical_at,clock_timestamp(),erp.current_app_user_id(),r.id,p_reason);
  end loop;
end;
$function$;

alter function "erp"."_stage_reverse_material_purchase_stock_at_source_time"(p_purchase_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._v268_financial_report_checks_pre_scope()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_catalog', 'information_schema', 'pg_temp'
AS $function$
begin
  perform erp.require_owner_admin();

  return query
  with expected_daily as(
    select je.transaction_date balance_date,jl.account_id,
           sum(jl.debit)::numeric debit_total,sum(jl.credit)::numeric credit_total
    from erp.journal_entries je
    join erp.journal_lines jl on jl.journal_entry_id=je.id
    where je.status in('POSTED','REVERSED')
    group by je.transaction_date,jl.account_id
  ), daily_mismatch as(
    select 1
    from expected_daily e
    full join erp.account_daily_balances a
      on a.balance_date=e.balance_date and a.account_id=e.account_id
    where abs(coalesce(e.debit_total,0)-coalesce(a.debit_total,0))>0.01
       or abs(coalesce(e.credit_total,0)-coalesce(a.credit_total,0))>0.01
  ), bs as(
    select
      coalesce(sum(case when ca.account_type='ASSET' then adb.debit_total-adb.credit_total else 0 end),0)::numeric assets,
      coalesce(sum(case when ca.account_type='LIABILITY' then adb.credit_total-adb.debit_total else 0 end),0)::numeric liabilities,
      coalesce(sum(case when ca.account_type='EQUITY' then adb.credit_total-adb.debit_total else 0 end),0)::numeric equity,
      coalesce(sum(case when ca.account_type in('REVENUE','EXPENSE') then adb.credit_total-adb.debit_total else 0 end),0)::numeric current_earnings
    from erp.account_daily_balances adb
    join erp.chart_accounts ca on ca.id=adb.account_id
  ), ar as(
    select
      coalesce((select sum(a.debit_total-a.credit_total) from erp.account_daily_balances a
                where a.account_id=erp.account_id('AR_CUSTOMER')),0)::numeric gl_amount,
      coalesce((select sum(greatest(
        erp.sale_net_total(h.id)-coalesce((select sum(p.amount) from erp.sales_payments p
                                           where p.sale_id=h.id and p.status='POSTED'),0),0
      )) from erp.sales_headers h
          where h.status in('POSTED','PARTIAL_PAID','PAID')),0)::numeric subledger_amount
  )
  select 'V268_DAILY_BALANCE_LEDGER_MISMATCH','CRITICAL',count(*)::bigint,
         'account_daily_balances must exactly equal posted/reversed journal lines by GL date and account'
  from daily_mismatch

  union all
  select 'V268_UNBALANCED_POSTED_JOURNAL','CRITICAL',count(*)::bigint,
         'Every posted/reversed journal entry must remain debit-equals-credit'
  from(
    select je.id from erp.journal_entries je
    join erp.journal_lines jl on jl.journal_entry_id=je.id
    where je.status in('POSTED','REVERSED')
    group by je.id having abs(sum(jl.debit)-sum(jl.credit))>0.01
  ) q

  union all
  select 'V268_BALANCE_SHEET_EQUATION','CRITICAL',
         case when abs(assets-liabilities-equity-current_earnings)>0.01 then 1 else 0 end::bigint,
         'Assets must equal liabilities plus recorded equity plus current earnings'
  from bs

  union all
  select 'V268_AR_GL_SUBLEDGER_MISMATCH','CRITICAL',
         case when abs(gl_amount-subledger_amount)>0.01 then 1 else 0 end::bigint,
         'Customer AR general ledger must equal active sales net of posted returns and customer payments'
  from ar

  union all
  select r.check_name,r.severity,r.issue_count,r.details
  from erp.run_v267_financial_truth_checks() r
  where r.check_name in('V267_GRNI_GL_SUBLEDGER_MISMATCH','V267_AP_GL_SUBLEDGER_MISMATCH')

  union all
  select 'V268_ACTIVE_SALE_MISSING_JOURNAL','CRITICAL',count(*)::bigint,
         'Every non-zero active sale requires its SALE journal'
  from erp.sales_headers h
  where h.status in('POSTED','PARTIAL_PAID','PAID')
    and(
      coalesce((select sum(i.line_total) from erp.sales_items i where i.sale_id=h.id),0)>0.005
      or coalesce((select sum(a.qty_pcs*a.unit_hpp_snapshot)
                   from erp.sale_stock_allocations a
                   join erp.sales_items i on i.id=a.sale_item_id where i.sale_id=h.id),0)>0.005
    )
    and not exists(select 1 from erp.journal_entries j
                   where j.source_type='SALE' and j.source_id=h.id and j.status='POSTED')

  union all
  select 'V268_POSTED_SALES_RETURN_MISSING_JOURNAL','CRITICAL',count(*)::bigint,
         'Every non-zero posted sales return requires its SALES_RETURN journal'
  from erp.sales_returns h
  where h.status='POSTED'
    and coalesce((select sum(i.refund_amount+i.qty_pcs*i.unit_hpp_snapshot)
                  from erp.sales_return_items i where i.return_id=h.id),0)>0.005
    and not exists(select 1 from erp.journal_entries j
                   where j.source_type='SALES_RETURN' and j.source_id=h.id and j.status='POSTED')

  union all
  select 'V268_POSTED_CUSTOMER_PAYMENT_MISSING_JOURNAL','CRITICAL',count(*)::bigint,
         'Every posted non-zero customer payment requires its SALES_PAYMENT journal'
  from erp.sales_payments p
  where p.status='POSTED' and p.amount>0.005
    and not exists(select 1 from erp.journal_entries j
                   where j.source_type='SALES_PAYMENT' and j.source_id=p.id and j.status='POSTED')

  union all
  select 'V268_PRODUCTION_FG_WITHOUT_CURRENT_HPP','CRITICAL',count(*)::bigint,
         'Every active production FG lot must have exactly one current HPP version'
  from erp.fg_lots l
  where l.lot_origin='PRODUCTION' and l.initial_qty_pcs>0
    and (select count(*) from erp.hpp_versions h where h.lot_id=l.id and h.is_current)<>1

  union all
  select 'V268_COST_RECALC_EXHAUSTED','CRITICAL',count(*)::bigint,
         'A permanently failed HPP recalc means owner profitability is not reliable'
  from erp.cost_recalc_queue q where q.status='FAILED' and q.attempt_count>=3

  union all
  select 'V268_COST_RECALC_PENDING','WARNING',count(*)::bigint,
         'Pending/running/retryable HPP recalc means profitability is provisional until the queue clears'
  from erp.cost_recalc_queue q
  where q.status in('PENDING','RUNNING') or(q.status='FAILED' and q.attempt_count<3)

  union all
  select 'V268_LIABILITY_VIEW_HELPER_PRIVILEGE','CRITICAL',count(*)::bigint,
         'Authenticated browser role needs EXECUTE on pure read helpers used by security-invoker liability views'
  from(values
    ('erp.material_purchase_grni_total(uuid)'),
    ('erp.material_purchase_final_ap_total(uuid)'),
    ('erp.material_purchase_total_liability(uuid)')
  ) f(signature)
  where not has_function_privilege('authenticated',f.signature,'EXECUTE')

  union all
  select 'V268_BROWSER_DIRECT_FINANCIAL_WRITE','CRITICAL',count(*)::bigint,
         'Browser roles must not directly mutate posted-source financial tables'
  from information_schema.role_table_grants g
  where g.table_schema='erp'
    and g.table_name in(
      'journal_entries','journal_lines','account_daily_balances',
      'material_supplier_invoices','material_supplier_invoice_lines',
      'sales_headers','sales_items','sales_returns','sales_return_items',
      'sales_payments','supplier_payments'
    )
    and g.grantee in('PUBLIC','anon','authenticated')
    and g.privilege_type in('INSERT','UPDATE','DELETE');
end;
$function$;

alter function "erp"."_v268_financial_report_checks_pre_scope"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp._validate_migration_batch_base(p_batch_id uuid)
 RETURNS TABLE(total_rows bigint, valid_rows bigint, error_rows bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare r record;e jsonb;v_required text[];k text;v_total bigint;v_valid bigint;v_error bigint;v_bt text;v_material_type text;
begin
  perform erp.require_owner_admin();
  if not exists(select 1 from erp.migration_batches where id=p_batch_id) then raise exception 'Migration batch not found'; end if;
  update erp.migration_batches set status='VALIDATING',error_message=null where id=p_batch_id;
  update erp.migration_staging_rows set validation_status='PENDING',validation_errors='[]'::jsonb,updated_at=now() where batch_id=p_batch_id;
  update erp.migration_staging_rows s set validation_status='ERROR',validation_errors=jsonb_build_array('Duplicate legacy_key inside entity type'),updated_at=now()
  where s.batch_id=p_batch_id and s.legacy_key is not null and exists(select 1 from erp.migration_staging_rows d where d.batch_id=s.batch_id and d.entity_type=s.entity_type and d.legacy_key=s.legacy_key and d.id<>s.id);

  for r in select * from erp.migration_staging_rows where batch_id=p_batch_id order by entity_type,source_row_no loop
    e:='[]'::jsonb;
    if jsonb_typeof(r.normalized_payload)<>'object' then e:=e||jsonb_build_array('normalized_payload must be a JSON object'); end if;
    v_required:=case r.entity_type
      when 'BRAND' then array['brand_code','brand_name']
      when 'SIZE' then array['size_code']
      when 'MODEL' then array['model_code','model_name']
      when 'PRODUCT' then array['sku','product_name','model_code','brand_code','color_name','size_code']
      when 'CUSTOMER' then array['customer_code','customer_name']
      when 'SUPPLIER' then array['supplier_code','supplier_name']
      when 'CONTRACTOR' then array['contractor_code','contractor_name']
      when 'ACCESSORY_CATEGORY' then array['category_code','category_name','base_uom_code']
      when 'MATERIAL' then array['material_sku','material_name','material_type','unit_code']
      when 'MATERIAL_ROLL' then array['material_sku','roll_number','opening_qty','unit_cost','location_code']
      when 'OPENING_BALANCE_ITEM' then array['balance_type']
      when 'OPEN_PO' then array['po_number','model_code','status','current_stage']
      else array[]::text[] end;
    foreach k in array v_required loop
      if nullif(trim(coalesce(r.normalized_payload->>k,'')),'') is null then e:=e||jsonb_build_array('Missing required field: '||k); end if;
    end loop;

    if r.entity_type='ACCESSORY_CATEGORY' and not exists(select 1 from erp.uom_definitions where unit_code=upper(r.normalized_payload->>'base_uom_code')) then e:=e||jsonb_build_array('Unknown base_uom_code'); end if;
    if r.entity_type='MATERIAL' then
      if upper(coalesce(r.normalized_payload->>'material_type','')) not in('FABRIC','ACCESSORY','OTHER') then e:=e||jsonb_build_array('material_type must be FABRIC, ACCESSORY or OTHER'); end if;
      if upper(coalesce(r.normalized_payload->>'material_type',''))='ACCESSORY' and nullif(trim(coalesce(r.normalized_payload->>'accessory_category_code','')),'') is null then e:=e||jsonb_build_array('ACCESSORY material requires accessory_category_code'); end if;
    end if;
    if r.entity_type='MATERIAL_ROLL' then
      if coalesce(nullif(r.normalized_payload->>'opening_qty','')::numeric,0)<=0 then e:=e||jsonb_build_array('MATERIAL_ROLL opening_qty must be positive'); end if;
      if coalesce(nullif(r.normalized_payload->>'unit_cost','')::numeric,-1)<0 then e:=e||jsonb_build_array('MATERIAL_ROLL unit_cost must be zero or positive'); end if;
      select material_type into v_material_type from erp.materials where material_sku=r.normalized_payload->>'material_sku';
      if v_material_type is null then
        select upper(s.normalized_payload->>'material_type') into v_material_type from erp.migration_staging_rows s
        where s.batch_id=p_batch_id and s.entity_type='MATERIAL' and s.normalized_payload->>'material_sku'=r.normalized_payload->>'material_sku' limit 1;
      end if;
      if coalesce(v_material_type,'')<>'FABRIC' then e:=e||jsonb_build_array('MATERIAL_ROLL requires a FABRIC material'); end if;
      if not exists(select 1 from erp.locations where location_code=r.normalized_payload->>'location_code' and location_type='RAW_MATERIAL_WAREHOUSE' and is_active=true) then e:=e||jsonb_build_array('MATERIAL_ROLL location_code must be an active raw-material warehouse'); end if;
      if nullif(trim(coalesce(r.normalized_payload->>'supplier_code','')),'') is not null
         and not exists(select 1 from erp.suppliers where supplier_code=r.normalized_payload->>'supplier_code')
         and not exists(select 1 from erp.migration_staging_rows s where s.batch_id=p_batch_id and s.entity_type='SUPPLIER' and s.normalized_payload->>'supplier_code'=r.normalized_payload->>'supplier_code') then
        e:=e||jsonb_build_array('Unknown MATERIAL_ROLL supplier_code');
      end if;
      if exists(select 1 from erp.migration_staging_rows d where d.batch_id=p_batch_id and d.entity_type='MATERIAL_ROLL' and d.id<>r.id
                and d.normalized_payload->>'material_sku'=r.normalized_payload->>'material_sku' and d.normalized_payload->>'roll_number'=r.normalized_payload->>'roll_number') then
        e:=e||jsonb_build_array('Duplicate roll_number for material inside migration batch');
      end if;
      if exists(select 1 from erp.material_rolls mr join erp.materials m on m.id=mr.material_id where m.material_sku=r.normalized_payload->>'material_sku' and mr.roll_number=r.normalized_payload->>'roll_number') then
        e:=e||jsonb_build_array('MATERIAL_ROLL conflicts with an existing roll number');
      end if;
    end if;

    if r.entity_type='OPENING_BALANCE_ITEM' then
      v_bt:=upper(coalesce(r.normalized_payload->>'balance_type',''));
      if v_bt not in('MATERIAL','FINISHED_GOODS','WIP','BS','CONTRACTOR_RECEIVABLE','CONTRACTOR_PAYABLE','CUSTOMER_RECEIVABLE','VENDOR_PAYABLE','SUPPLIER_PAYABLE','CASH_BANK') then e:=e||jsonb_build_array('Unsupported opening balance_type for migration framework'); end if;
      if v_bt='MATERIAL' and(nullif(r.normalized_payload->>'material_sku','') is null or nullif(r.normalized_payload->>'location_code','') is null or coalesce(nullif(r.normalized_payload->>'qty','')::numeric,0)<=0) then e:=e||jsonb_build_array('MATERIAL opening needs material_sku, location_code and positive qty'); end if;
      if v_bt='MATERIAL' and exists(select 1 from erp.materials m where m.material_sku=r.normalized_payload->>'material_sku' and m.material_type='FABRIC') then e:=e||jsonb_build_array('FABRIC opening stock must use MATERIAL_ROLL rows, not anonymous MATERIAL opening'); end if;
      if v_bt='FINISHED_GOODS' and(nullif(r.normalized_payload->>'product_sku','') is null or coalesce(nullif(r.normalized_payload->>'qty','')::numeric,0)<=0) then e:=e||jsonb_build_array('FINISHED_GOODS opening needs product_sku and positive qty'); end if;
      if v_bt in('CONTRACTOR_RECEIVABLE','CONTRACTOR_PAYABLE') and(nullif(r.normalized_payload->>'contractor_code','') is null or coalesce(nullif(r.normalized_payload->>'amount','')::numeric,0)<=0) then e:=e||jsonb_build_array('Contractor opening balance needs contractor_code and positive amount'); end if;
      if v_bt='CUSTOMER_RECEIVABLE' and(nullif(r.normalized_payload->>'customer_code','') is null or coalesce(nullif(r.normalized_payload->>'amount','')::numeric,0)<=0) then e:=e||jsonb_build_array('Customer receivable opening needs customer_code and positive amount'); end if;
      if v_bt='SUPPLIER_PAYABLE' and(nullif(r.normalized_payload->>'supplier_code','') is null or coalesce(nullif(r.normalized_payload->>'amount','')::numeric,0)<=0) then e:=e||jsonb_build_array('Supplier payable opening needs supplier_code and positive amount'); end if;
      if v_bt='VENDOR_PAYABLE' and(nullif(r.normalized_payload->>'vendor_code','') is null or coalesce(nullif(r.normalized_payload->>'amount','')::numeric,0)<=0) then e:=e||jsonb_build_array('Vendor payable opening needs vendor_code and positive amount'); end if;
      if v_bt='CASH_BANK' and(nullif(r.normalized_payload->>'cash_account_code','') is null or coalesce(nullif(r.normalized_payload->>'amount','')::numeric,0)<=0) then e:=e||jsonb_build_array('CASH_BANK opening needs cash_account_code and positive amount'); end if;
    end if;
    if r.entity_type='OPEN_PO' then
      if upper(coalesce(r.normalized_payload->>'status','')) not in('DRAFT','CUTTING','SEWING','LAUNDRY','QC','FINISHED','ON_HOLD','CANCELLED') then e:=e||jsonb_build_array('Invalid PO status'); end if;
      if upper(coalesce(r.normalized_payload->>'current_stage','')) not in('CUTTING','SEWING','LAUNDRY','QC','FINISHED','ON_HOLD') then e:=e||jsonb_build_array('Invalid PO current_stage'); end if;
    end if;
    if r.validation_status='ERROR' and jsonb_array_length(r.validation_errors)>0 then e:=r.validation_errors||e; end if;
    update erp.migration_staging_rows set validation_status=case when jsonb_array_length(e)=0 then 'VALID' else 'ERROR' end,validation_errors=e,updated_at=now() where id=r.id;
  end loop;
  select count(*),count(*) filter(where validation_status='VALID'),count(*) filter(where validation_status='ERROR') into v_total,v_valid,v_error from erp.migration_staging_rows where batch_id=p_batch_id;
  update erp.migration_batches set status=case when v_error=0 then 'READY' else 'DRAFT' end,validated_at=now(),error_message=case when v_error=0 then null else v_error||' staging row(s) failed validation' end where id=p_batch_id;
  return query select v_total,v_valid,v_error;
end;$function$;

alter function "erp"."_validate_migration_batch_base"(p_batch_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.accessory_category_weighted_avg_cost_at(p_category_id uuid, p_at timestamp with time zone)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_cost numeric; BEGIN PERFORM erp.require_internal(); WITH events AS (SELECT msm.physical_at,msm.system_created_at,msm.id,msm.qty_signed,msm.qty_signed*msm.unit_cost_snapshot AS value_signed FROM erp.material_stock_movements msm JOIN erp.materials m ON m.id=msm.material_id WHERE m.material_type='ACCESSORY' AND m.accessory_category_id=p_category_id AND msm.physical_at<=p_at),running AS (SELECT physical_at,system_created_at,id,SUM(qty_signed) OVER (ORDER BY physical_at,system_created_at,id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_qty,SUM(value_signed) OVER (ORDER BY physical_at,system_created_at,id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_value FROM events) SELECT running_value/running_qty INTO v_cost FROM running WHERE running_qty>0 ORDER BY physical_at DESC,system_created_at DESC,id DESC LIMIT 1;RETURN v_cost;END; $function$;

alter function "erp"."accessory_category_weighted_avg_cost_at"(p_category_id uuid, p_at timestamp with time zone) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.accessory_uom_factor(p_category_id uuid, p_uom_code text, p_at timestamp with time zone DEFAULT now())
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_base varchar(20);v_factor numeric(18,6); BEGIN PERFORM erp.require_internal();SELECT base_uom_code INTO v_base FROM erp.accessory_categories WHERE id=p_category_id; IF v_base IS NULL THEN RAISE EXCEPTION 'Accessory category not found'; END IF; IF upper(p_uom_code)=upper(v_base) THEN RETURN 1; END IF; SELECT base_qty_per_uom INTO v_factor FROM erp.accessory_category_uom_conversions WHERE category_id=p_category_id AND upper(uom_code)=upper(p_uom_code) AND effective_from<=p_at AND (effective_to IS NULL OR effective_to>p_at) ORDER BY effective_from DESC LIMIT 1; IF v_factor IS NULL THEN RAISE EXCEPTION 'No active UOM conversion for category %, UOM %, at %',p_category_id,p_uom_code,p_at; END IF;RETURN v_factor;END; $function$;

alter function "erp"."accessory_uom_factor"(p_category_id uuid, p_uom_code text, p_at timestamp with time zone) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.account_id(p_mapping_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_id uuid; BEGIN PERFORM erp.require_internal();SELECT account_id INTO v_id FROM erp.accounting_account_mappings WHERE mapping_key=p_mapping_key; IF v_id IS NULL THEN RAISE EXCEPTION 'Accounting mapping % is not configured',p_mapping_key; END IF;RETURN v_id;END; $function$;

alter function "erp"."account_id"(p_mapping_key text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.activate_attendance_hpp_pool_v1(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'activate_attendance_hpp_pool_v1';
  v_hash text;
  v_cached jsonb;
  v_pool erp.attendance_hpp_pools%rowtype;
  v_lines jsonb := '[]'::jsonb;
  v_journal_id uuid;
  v_effective_date date;
  v_line record;
  v_response jsonb;
begin
  perform erp.require_owner_admin();
  if p_pool_id is null or p_expected_version is null then
    raise exception 'pool_id and expected_version are required';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Attendance HPP activation reason is required';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'pool_id', p_pool_id,
    'reason', btrim(p_reason),
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_pool
  from erp.attendance_hpp_pools
  where id = p_pool_id
  for update;

  if v_pool.id is null then raise exception 'Attendance HPP pool not found'; end if;
  if v_pool.status <> 'DRAFT' then raise exception 'Only DRAFT attendance HPP pool can be activated'; end if;
  if v_pool.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_pool.row_version;
  end if;
  if v_pool.numerator_amount <= 0 or v_pool.denominator_qty <= 0 then
    raise exception 'Attendance HPP activation requires positive numerator and immutable SELESAI_DIJAHIT denominator';
  end if;

  perform erp._cp3_lock_business_period(v_pool.period_start, v_pool.period_end);
  perform erp._cp3_lock_manifest_contractors(v_pool.period_start, v_pool.period_end);

  if exists (
    select 1 from erp.attendance_hpp_pools p
    where p.id <> v_pool.id
      and p.period_start = v_pool.period_start
      and p.period_end = v_pool.period_end
      and p.status = 'ACTIVE'
  ) then
    raise exception 'Another ACTIVE attendance HPP pool already owns this exact period';
  end if;

  perform erp.validate_attendance_hpp_pool_v1(v_pool.id);

  select coalesce(jsonb_agg(jsonb_build_object(
    'mapping_key', 'WIP',
    'debit', amount,
    'credit', 0,
    'contractor_id', contractor_id,
    'po_id', po_id,
    'description', 'Attendance HPP destination PO ' || po_id::text
  ) order by po_id, contractor_id), '[]'::jsonb)
  into v_lines
  from (
    select po_id, contractor_id, round(sum(allocated_amount),2) amount
    from erp.attendance_hpp_pool_allocations
    where pool_id = v_pool.id
    group by po_id, contractor_id
    having round(sum(allocated_amount),2) > 0
  ) d;

  v_lines := v_lines || coalesce((
    select jsonb_agg(jsonb_build_object(
      'account_id', jl.account_id,
      'debit', 0,
      'credit', round(s.attendance_amount,2),
      'contractor_id', s.contractor_id,
      'description', 'Attendance HPP source debit line ' || s.original_debit_journal_line_id::text
    ) order by s.original_debit_journal_line_id)
    from erp.attendance_hpp_pool_sources s
    join erp.journal_lines jl on jl.id = s.original_debit_journal_line_id
    where s.pool_id = v_pool.id
  ), '[]'::jsonb);

  v_journal_id := erp.post_journal(
    'ATTENDANCE_HPP_POOL', v_pool.id, v_pool.period_end,
    'Allocate normal-Mandor attendance cost by immutable SELESAI_DIJAHIT',
    v_lines
  );
  select transaction_date into v_effective_date
  from erp.journal_entries where id=v_journal_id;

  for v_line in
    select jl.id, jl.po_id, jl.debit
    from erp.journal_lines jl
    where jl.journal_entry_id = v_journal_id
      and jl.debit > 0
      and jl.po_id is not null
  loop
    insert into erp.attendance_hpp_journal_line_links(
      pool_id, journal_line_id, link_type, po_id, amount
    ) values (
      v_pool.id, v_line.id, 'DESTINATION_DEBIT', v_line.po_id, v_line.debit
    );
  end loop;

  for v_line in
    select s.id as pool_source_id, s.original_debit_journal_line_id,
           s.attendance_amount, jl2.id as journal_line_id
    from erp.attendance_hpp_pool_sources s
    join erp.journal_lines jl2
      on jl2.journal_entry_id = v_journal_id
     and jl2.credit = round(s.attendance_amount,2)
     and jl2.description = 'Attendance HPP source debit line ' || s.original_debit_journal_line_id::text
    where s.pool_id = v_pool.id
    order by s.original_debit_journal_line_id
  loop
    insert into erp.attendance_hpp_journal_line_links(
      pool_id, journal_line_id, link_type,
      pool_source_id, original_debit_journal_line_id, amount
    ) values (
      v_pool.id, v_line.journal_line_id, 'SOURCE_CREDIT',
      v_line.pool_source_id, v_line.original_debit_journal_line_id,
      v_line.attendance_amount
    );
  end loop;

  update erp.attendance_hpp_pools
  set status = 'ACTIVE',
      post_journal_entry_id = v_journal_id,
      activated_by = erp.current_app_user_id(),
      activated_at = clock_timestamp(),
      row_version = row_version + 1
  where id = v_pool.id
  returning * into v_pool;

  perform erp.validate_attendance_hpp_pool_v1(v_pool.id);

  for v_line in
    select distinct a.po_id
    from erp.attendance_hpp_pool_allocations a
    where a.pool_id=v_pool.id
    order by a.po_id
  loop
    perform erp.rebuild_po_hpp(v_line.po_id,'Attendance HPP pool activation '||v_pool.id::text);
    perform erp.propagate_conversion_hpp_for_po(v_line.po_id);
    perform erp.sync_po_hpp_to_gl(v_line.po_id,v_effective_date);
  end loop;

  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
  values (
    'attendance_hpp_pools', v_pool.id, 'POST',
    jsonb_build_object(
      'journal_entry_id', v_journal_id,
      'numerator_amount', v_pool.numerator_amount,
      'denominator_qty', v_pool.denominator_qty,
      'manifest_sha256', v_pool.source_manifest_sha256,
      'lifecycle_action', 'ACTIVATE'
    ),
    erp.current_app_user_id(), btrim(p_reason)
  );

  v_response := jsonb_build_object(
    'pool_id', v_pool.id,
    'status', v_pool.status,
    'row_version', v_pool.row_version,
    'journal_entry_id', v_pool.post_journal_entry_id,
    'validation', 'PASS'
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."activate_attendance_hpp_pool_v1"(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.apply_bulk_rate_change(p_rate_type text, p_target_ids uuid[], p_mode text, p_value numeric, p_effective_from timestamp with time zone DEFAULT clock_timestamp(), p_note text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_type text:=upper(trim(p_rate_type));
  v_mode text:=upper(trim(p_mode));
  v_eff timestamptz:=coalesce(p_effective_from,clock_timestamp());
  id0 uuid;
  r record;
  v_old numeric;
  v_new numeric;
  v_next timestamptz;
  v_new_id uuid;
  v_count integer:=0;
begin
  perform erp.require_owner_admin();
  if v_type not in('PRODUCT_PRICE','WORK_RATE','CONTRACTOR_ACCESSORY_PRICE','CONTRACTOR_MATERIAL_PRICE','LAUNDRY_RATE') then
    raise exception 'Tipe harga/rate tidak didukung';
  end if;
  if v_mode not in('SET','DELTA','PERCENT') then raise exception 'Mode perubahan harus SET, DELTA, atau PERCENT'; end if;
  if p_target_ids is null or coalesce(array_length(p_target_ids,1),0)=0 then raise exception 'Pilih minimal satu harga/rate'; end if;
  if v_eff<clock_timestamp()-interval '5 minutes' then raise exception 'Perubahan harga/rate massal hanya boleh berlaku mulai sekarang atau tanggal mendatang'; end if;
  if nullif(trim(p_note),'') is null then raise exception 'Catatan/alasan perubahan massal wajib diisi'; end if;

  for id0 in select distinct unnest(p_target_ids) order by 1 loop
    v_new_id:=null;v_next:=null;
    if v_type='PRODUCT_PRICE' then
      select * into r from erp.product_price_versions where id=id0 for update;
      if r.id is null then raise exception 'Product price target % tidak ditemukan',id0; end if;
      v_old:=r.price;
      select min(x.effective_from) into v_next from erp.product_price_versions x where x.product_id=r.product_id and x.id<>r.id and x.effective_from>r.effective_from;
      if v_eff<=r.effective_from or (r.effective_to is not null and v_eff>=r.effective_to) or (v_next is not null and v_eff>=v_next) then raise exception 'Tanggal berlaku tidak berada di dalam periode harga SKU target %',id0; end if;
      v_new:=case v_mode when 'SET' then p_value when 'DELTA' then v_old+p_value else v_old*(1+p_value/100) end;
      if v_new<0 then raise exception 'Harga SKU hasil perubahan tidak boleh negatif'; end if;
      update erp.product_price_versions set effective_to=v_eff where id=r.id;
      insert into erp.product_price_versions(product_id,price,effective_from,effective_to,change_note,created_by)
      values(r.product_id,round(v_new,6),v_eff,coalesce(r.effective_to,v_next),concat_ws(' | ',r.change_note,p_note),erp.current_app_user_id()) returning id into v_new_id;

    elsif v_type='WORK_RATE' then
      select * into r from erp.contractor_work_rates where id=id0 for update;
      if r.id is null then raise exception 'Work rate target % tidak ditemukan',id0; end if;
      v_old:=r.rate_per_pcs;
      select min(x.effective_from) into v_next from erp.contractor_work_rates x where x.contractor_id=r.contractor_id and x.model_id=r.model_id and x.work_component_id=r.work_component_id and x.id<>r.id and x.effective_from>r.effective_from;
      if v_eff<=r.effective_from or (r.effective_to is not null and v_eff>=r.effective_to) or (v_next is not null and v_eff>=v_next) then raise exception 'Tanggal berlaku tidak berada di dalam periode rate jahit target %',id0; end if;
      v_new:=case v_mode when 'SET' then p_value when 'DELTA' then v_old+p_value else v_old*(1+p_value/100) end;
      if v_new<0 then raise exception 'Rate jahit hasil perubahan tidak boleh negatif'; end if;
      update erp.contractor_work_rates set effective_to=v_eff where id=r.id;
      insert into erp.contractor_work_rates(contractor_id,model_id,work_component_id,rate_per_pcs,effective_from,effective_to,notes)
      values(r.contractor_id,r.model_id,r.work_component_id,round(v_new,6),v_eff,coalesce(r.effective_to,v_next),concat_ws(' | ',r.notes,p_note)) returning id into v_new_id;

    elsif v_type='CONTRACTOR_ACCESSORY_PRICE' then
      select * into r from erp.contractor_accessory_price_versions where id=id0 for update;
      if r.id is null then raise exception 'Accessory price target % tidak ditemukan',id0; end if;
      v_old:=r.selling_price;
      select min(x.effective_from) into v_next from erp.contractor_accessory_price_versions x where x.contractor_id is not distinct from r.contractor_id and x.category_id=r.category_id and x.id<>r.id and x.effective_from>r.effective_from;
      if v_eff<=r.effective_from or (r.effective_to is not null and v_eff>=r.effective_to) or (v_next is not null and v_eff>=v_next) then raise exception 'Tanggal berlaku tidak berada di dalam periode harga aksesori target %',id0; end if;
      v_new:=case v_mode when 'SET' then p_value when 'DELTA' then v_old+p_value else v_old*(1+p_value/100) end;
      if v_new<0 then raise exception 'Harga aksesori hasil perubahan tidak boleh negatif'; end if;
      update erp.contractor_accessory_price_versions set effective_to=v_eff where id=r.id;
      insert into erp.contractor_accessory_price_versions(contractor_id,category_id,selling_price,selling_uom_code,effective_from,effective_to,notes)
      values(r.contractor_id,r.category_id,round(v_new,6),r.selling_uom_code,v_eff,coalesce(r.effective_to,v_next),concat_ws(' | ',r.notes,p_note)) returning id into v_new_id;

    elsif v_type='CONTRACTOR_MATERIAL_PRICE' then
      select * into r from erp.contractor_material_price_versions where id=id0 for update;
      if r.id is null then raise exception 'Material price target % tidak ditemukan',id0; end if;
      v_old:=r.selling_price;
      select min(x.effective_from) into v_next from erp.contractor_material_price_versions x where x.contractor_id is not distinct from r.contractor_id and x.material_id=r.material_id and x.id<>r.id and x.effective_from>r.effective_from;
      if v_eff<=r.effective_from or (r.effective_to is not null and v_eff>=r.effective_to) or (v_next is not null and v_eff>=v_next) then raise exception 'Tanggal berlaku tidak berada di dalam periode harga material target %',id0; end if;
      v_new:=case v_mode when 'SET' then p_value when 'DELTA' then v_old+p_value else v_old*(1+p_value/100) end;
      if v_new<0 then raise exception 'Harga material hasil perubahan tidak boleh negatif'; end if;
      update erp.contractor_material_price_versions set effective_to=v_eff where id=r.id;
      insert into erp.contractor_material_price_versions(contractor_id,material_id,selling_price,effective_from,effective_to,notes)
      values(r.contractor_id,r.material_id,round(v_new,6),v_eff,coalesce(r.effective_to,v_next),concat_ws(' | ',r.notes,p_note)) returning id into v_new_id;

    else
      select * into r from erp.laundry_vendor_rate_versions where id=id0 for update;
      if r.id is null then raise exception 'Laundry rate target % tidak ditemukan',id0; end if;
      v_old:=r.rate_per_pcs;
      select min(x.effective_from) into v_next from erp.laundry_vendor_rate_versions x where x.vendor_id=r.vendor_id and x.wash_process_id=r.wash_process_id and x.id<>r.id and x.effective_from>r.effective_from;
      if v_eff<=r.effective_from or (r.effective_to is not null and v_eff>=r.effective_to) or (v_next is not null and v_eff>=v_next) then raise exception 'Tanggal berlaku tidak berada di dalam periode rate laundry target %',id0; end if;
      v_new:=case v_mode when 'SET' then p_value when 'DELTA' then v_old+p_value else v_old*(1+p_value/100) end;
      if v_new<0 then raise exception 'Rate laundry hasil perubahan tidak boleh negatif'; end if;
      update erp.laundry_vendor_rate_versions set effective_to=v_eff where id=r.id;
      insert into erp.laundry_vendor_rate_versions(vendor_id,wash_process_id,rate_per_pcs,effective_from,effective_to,notes)
      values(r.vendor_id,r.wash_process_id,round(v_new,6),v_eff,coalesce(r.effective_to,v_next),concat_ws(' | ',r.notes,p_note)) returning id into v_new_id;
    end if;

    insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason,new_data)
    values(lower(v_type),id0,'UPDATE',erp.current_app_user_id(),p_note,
           jsonb_build_object('successor_rate_id',v_new_id,'old_value',v_old,'new_value',round(v_new,6),'effective_from',v_eff,'mode',v_mode));
    v_count:=v_count+1;
  end loop;
  return v_count;
end$function$;

alter function "erp"."apply_bulk_rate_change"(p_rate_type text, p_target_ids uuid[], p_mode text, p_value numeric, p_effective_from timestamp with time zone, p_note text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.apply_cutting_correction_and_post_laundry(p_delivery_id uuid, p_cutting_batch_id uuid, p_correction_type text, p_reason_code text, p_reason text, p_lines jsonb, p_physical_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
DECLARE v_correction_id uuid;
BEGIN
  PERFORM erp.require_internal();
  v_correction_id:=erp.post_cutting_qty_correction(
    p_cutting_batch_id,p_correction_type,p_reason_code,p_reason,p_lines,p_physical_at
  );
  PERFORM erp.post_laundry_delivery(p_delivery_id);
  RETURN v_correction_id;
END;
$function$;

alter function "erp"."apply_cutting_correction_and_post_laundry"(p_delivery_id uuid, p_cutting_batch_id uuid, p_correction_type text, p_reason_code text, p_reason text, p_lines jsonb, p_physical_at timestamp with time zone) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.apply_migration_master_rows(p_batch_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  r record;j jsonb;v_id uuid;v_model uuid;v_brand uuid;v_size uuid;v_category uuid;v_material uuid;v_supplier uuid;v_cutover timestamptz;v_count integer:=0;
  v_existing record;
begin
  perform erp.require_owner_admin();
  if (select status from erp.migration_batches where id=p_batch_id) not in ('READY','POSTING') then raise exception 'Migration batch must be READY'; end if;
  if exists(select 1 from erp.migration_staging_rows where batch_id=p_batch_id and validation_status<>'VALID') then raise exception 'Migration batch contains unvalidated/error rows'; end if;
  select cutover_at into v_cutover from erp.migration_batches where id=p_batch_id;
  update erp.migration_batches set status='POSTING',error_message=null where id=p_batch_id;
  for r in select * from erp.migration_staging_rows where batch_id=p_batch_id and validation_status='VALID'
    and entity_type in ('BRAND','SIZE','MODEL','CUSTOMER','SUPPLIER','CONTRACTOR','ACCESSORY_CATEGORY','MATERIAL','MATERIAL_ROLL','PRODUCT')
    order by case entity_type when 'BRAND' then 10 when 'SIZE' then 20 when 'MODEL' then 30 when 'CUSTOMER' then 40 when 'SUPPLIER' then 50 when 'CONTRACTOR' then 60 when 'ACCESSORY_CATEGORY' then 70 when 'MATERIAL' then 80 when 'MATERIAL_ROLL' then 85 when 'PRODUCT' then 90 else 999 end,source_row_no
  loop
    j:=r.normalized_payload;v_id:=null;
    case r.entity_type
      when 'BRAND' then insert into erp.brands(brand_code,brand_name,is_active) values (j->>'brand_code',j->>'brand_name',coalesce(nullif(j->>'is_active','')::boolean,true)) on conflict (brand_code) do update set brand_name=excluded.brand_name,is_active=excluded.is_active,updated_at=now() returning id into v_id;
      when 'SIZE' then insert into erp.sizes(size_code,sort_order,is_active) values (j->>'size_code',coalesce(nullif(j->>'sort_order','')::integer,0),coalesce(nullif(j->>'is_active','')::boolean,true)) on conflict (size_code) do update set sort_order=excluded.sort_order,is_active=excluded.is_active returning id into v_id;
      when 'MODEL' then insert into erp.product_models(model_code,model_name,description,is_active) values (j->>'model_code',j->>'model_name',j->>'description',coalesce(nullif(j->>'is_active','')::boolean,true)) on conflict (model_code) do update set model_name=excluded.model_name,description=excluded.description,is_active=excluded.is_active,updated_at=now() returning id into v_id;
      when 'CUSTOMER' then insert into erp.customers(customer_code,customer_name,phone,address,is_active) values (j->>'customer_code',j->>'customer_name',j->>'phone',j->>'address',coalesce(nullif(j->>'is_active','')::boolean,true)) on conflict (customer_code) do update set customer_name=excluded.customer_name,phone=excluded.phone,address=excluded.address,is_active=excluded.is_active,updated_at=now() returning id into v_id;
      when 'SUPPLIER' then insert into erp.suppliers(supplier_code,supplier_name,supplier_type,phone,address,is_active) values (j->>'supplier_code',j->>'supplier_name',coalesce(nullif(upper(j->>'supplier_type'),''),'MATERIAL'),j->>'phone',j->>'address',coalesce(nullif(j->>'is_active','')::boolean,true)) on conflict (supplier_code) do update set supplier_name=excluded.supplier_name,supplier_type=excluded.supplier_type,phone=excluded.phone,address=excluded.address,is_active=excluded.is_active returning id into v_id;
      when 'CONTRACTOR' then insert into erp.contractors(contractor_code,contractor_name,contractor_type,attendance_required,is_active,notes) values (j->>'contractor_code',j->>'contractor_name',coalesce(nullif(upper(j->>'contractor_type'),''),'MANDOR'),coalesce(nullif(j->>'attendance_required','')::boolean,true),coalesce(nullif(j->>'is_active','')::boolean,true),j->>'notes') on conflict (contractor_code) do update set contractor_name=excluded.contractor_name,contractor_type=excluded.contractor_type,attendance_required=excluded.attendance_required,is_active=excluded.is_active,notes=excluded.notes,updated_at=now() returning id into v_id;
      when 'ACCESSORY_CATEGORY' then insert into erp.accessory_categories(category_code,category_name,base_uom_code,is_active,notes) values (j->>'category_code',j->>'category_name',upper(j->>'base_uom_code'),coalesce(nullif(j->>'is_active','')::boolean,true),j->>'notes') on conflict (category_code) do update set category_name=excluded.category_name,is_active=excluded.is_active,notes=excluded.notes,updated_at=now() returning id into v_id;
      when 'MATERIAL' then
        v_category:=null;if nullif(trim(coalesce(j->>'accessory_category_code','')),'') is not null then select id into v_category from erp.accessory_categories where category_code=j->>'accessory_category_code';if v_category is null then raise exception 'Unknown accessory category % for material %',j->>'accessory_category_code',j->>'material_sku';end if;end if;
        insert into erp.materials(material_sku,material_name,material_type,unit_code,accessory_category_id,is_active) values (j->>'material_sku',j->>'material_name',upper(j->>'material_type'),upper(j->>'unit_code'),v_category,coalesce(nullif(j->>'is_active','')::boolean,true)) on conflict (material_sku) do update set material_name=excluded.material_name,accessory_category_id=excluded.accessory_category_id,is_active=excluded.is_active,updated_at=now() returning id into v_id;
      when 'MATERIAL_ROLL' then
        select id into v_material from erp.materials where material_sku=j->>'material_sku' and material_type='FABRIC';if v_material is null then raise exception 'MATERIAL_ROLL material % is not a FABRIC material',j->>'material_sku';end if;
        v_supplier:=null;if nullif(trim(coalesce(j->>'supplier_code','')),'') is not null then select id into v_supplier from erp.suppliers where supplier_code=j->>'supplier_code';if v_supplier is null then raise exception 'Unknown supplier % for roll %',j->>'supplier_code',j->>'roll_number';end if;end if;
        if exists(select 1 from erp.material_rolls where material_id=v_material and roll_number=j->>'roll_number') then raise exception 'Migration roll already exists for material %, roll %',j->>'material_sku',j->>'roll_number';end if;
        insert into erp.material_rolls(material_id,purchase_item_id,supplier_id,roll_number,original_qty,cached_qty,status,received_at,notes)
        values(v_material,null,v_supplier,j->>'roll_number',(j->>'opening_qty')::numeric,0,'AVAILABLE',v_cutover,coalesce(j->>'notes','Legacy roll at migration cutover')) returning id into v_id;
      when 'PRODUCT' then
        select id into v_model from erp.product_models where model_code=j->>'model_code';
        select id into v_brand from erp.brands where brand_code=j->>'brand_code';
        select id into v_size from erp.sizes where size_code=j->>'size_code';
        if v_model is null or v_brand is null or v_size is null then raise exception 'Product % has unresolved model/brand/size mapping',j->>'sku';end if;
        insert into erp.product_model_sizes(model_id,size_id) values(v_model,v_size) on conflict(model_id,size_id) do nothing;

        select p.* into v_existing
        from erp.products p
        where lower(trim(p.sku))=lower(trim(j->>'sku'))
          and p.effective_from<=v_cutover and (p.effective_to is null or p.effective_to>v_cutover)
        order by p.effective_from desc,p.id desc limit 1;

        if v_existing.id is null then
          if exists(select 1 from erp.products p where lower(trim(p.sku))=lower(trim(j->>'sku'))) then
            raise exception 'Migration product % already has identity history but no version valid at cutover %. Do not guess a historical version; fix migration mapping/effective dates first.',j->>'sku',v_cutover;
          end if;
          insert into erp.products(sku,model_id,brand_id,color_name,size_id,product_name,is_portal_visible,is_active,effective_from)
          values(j->>'sku',v_model,v_brand,j->>'color_name',v_size,j->>'product_name',coalesce(nullif(j->>'is_portal_visible','')::boolean,true),coalesce(nullif(j->>'is_active','')::boolean,true),v_cutover)
          returning id into v_id;
        else
          if v_existing.model_id is distinct from v_model or v_existing.brand_id is distinct from v_brand or lower(trim(v_existing.color_name)) is distinct from lower(trim(j->>'color_name')) or v_existing.size_id is distinct from v_size then
            raise exception 'Migration product % identity differs from the SKU version already valid at cutover. Use controlled identity-version mapping instead of overwriting history.',j->>'sku';
          end if;
          v_id:=v_existing.id;
          update erp.products set product_name=j->>'product_name',is_portal_visible=coalesce(nullif(j->>'is_portal_visible','')::boolean,true),is_active=coalesce(nullif(j->>'is_active','')::boolean,true),updated_at=now() where id=v_id;
        end if;
    end case;
    update erp.migration_staging_rows set posted_entity_type=r.entity_type,posted_entity_id=v_id,posted_at=now(),updated_at=now() where id=r.id;
    v_count:=v_count+1;
  end loop;
  return v_count;
end$function$;

alter function "erp"."apply_migration_master_rows"(p_batch_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.apply_migration_open_pos(p_batch_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE b erp.migration_batches%ROWTYPE;r record;j jsonb;v_model uuid;v_contractor uuid;v_id uuid;v_count integer:=0; BEGIN PERFORM erp.require_owner_admin();SELECT * INTO b FROM erp.migration_batches WHERE id=p_batch_id FOR UPDATE; IF b.id IS NULL THEN RAISE EXCEPTION 'Migration batch not found'; END IF; IF b.status NOT IN ('READY','POSTING') THEN RAISE EXCEPTION 'Migration batch must be READY/POSTING'; END IF; FOR r IN SELECT * FROM erp.migration_staging_rows WHERE batch_id=p_batch_id AND entity_type='OPEN_PO' AND validation_status='VALID' ORDER BY source_row_no LOOP j:=r.normalized_payload;SELECT id INTO v_model FROM erp.product_models WHERE model_code=j->>'model_code'; IF v_model IS NULL THEN RAISE EXCEPTION 'OPEN_PO row %: unknown model %',r.source_row_no,j->>'model_code'; END IF;v_contractor:=NULL; IF NULLIF(trim(COALESCE(j->>'contractor_code','')),'') IS NOT NULL THEN SELECT id INTO v_contractor FROM erp.contractors WHERE contractor_code=j->>'contractor_code'; IF v_contractor IS NULL THEN RAISE EXCEPTION 'OPEN_PO row %: unknown contractor %',r.source_row_no,j->>'contractor_code'; END IF; END IF;SELECT id INTO v_id FROM erp.production_orders WHERE po_number=j->>'po_number'; IF v_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM erp.production_orders WHERE id=v_id AND is_legacy=true AND migration_batch_id=p_batch_id) THEN RAISE EXCEPTION 'OPEN_PO row % conflicts with an existing non-migration PO number %',r.source_row_no,j->>'po_number'; END IF;v_id:=NULL;INSERT INTO erp.production_orders(po_number,model_id,contractor_id,target_qty_pcs,target_dozens,status,current_stage,physical_start_at,notes,migration_batch_id,is_legacy,legacy_reference,created_by) VALUES (j->>'po_number',v_model,v_contractor,NULLIF(j->>'target_qty_pcs','')::integer,NULLIF(j->>'target_dozens','')::numeric,upper(j->>'status'),upper(j->>'current_stage'),NULLIF(j->>'physical_start_at','')::timestamptz,COALESCE(j->>'notes','Migrated open PO'),p_batch_id,true,COALESCE(r.legacy_key,j->>'po_number'),erp.current_app_user_id()) ON CONFLICT (po_number) DO UPDATE SET contractor_id=EXCLUDED.contractor_id,target_qty_pcs=EXCLUDED.target_qty_pcs,target_dozens=EXCLUDED.target_dozens,status=EXCLUDED.status,current_stage=EXCLUDED.current_stage,physical_start_at=EXCLUDED.physical_start_at,notes=EXCLUDED.notes,migration_batch_id=EXCLUDED.migration_batch_id,is_legacy=true,legacy_reference=EXCLUDED.legacy_reference,updated_at=now() WHERE production_orders.is_legacy=true AND production_orders.migration_batch_id=p_batch_id RETURNING id INTO v_id; IF v_id IS NULL THEN RAISE EXCEPTION 'OPEN_PO row % could not be applied safely',r.source_row_no; END IF;UPDATE erp.migration_staging_rows SET posted_entity_type='PRODUCTION_ORDER',posted_entity_id=v_id,posted_at=now(),updated_at=now() WHERE id=r.id;v_count:=v_count+1; END LOOP;RETURN v_count;END; $function$;

alter function "erp"."apply_migration_open_pos"(p_batch_id uuid) owner to "postgres";

