CREATE OR REPLACE FUNCTION erp.assert_pattern_initial_assignment_allowed(p_cutting_group_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_group erp.cutting_groups%rowtype;
begin
  if p_cutting_group_id is null then
    raise exception using errcode='23502',message='CUTTING_GROUP_ID_REQUIRED_FOR_PATTERN_ASSIGNMENT';
  end if;

  select * into v_group
  from erp.cutting_groups
  where id=p_cutting_group_id
  for update;

  if v_group.id is null then
    raise exception using errcode='P0002',message='Potongan not found';
  end if;
  if v_group.pattern_id is not null then
    raise exception using errcode='23514',message='PATTERN_IDENTITY_ALREADY_BOUND';
  end if;
  if v_group.status<>'CUT'
     or v_group.picked_up_at is not null
     or v_group.material_issue_posted
     or v_group.material_return_posted then
    raise exception using errcode='23514',message='PATTERN_INITIAL_ASSIGNMENT_REQUIRES_PRISTINE_CUTTING';
  end if;

  if exists(
       select 1 from erp.production_pattern_audit a
       where a.entity_type='ASSIGNMENT' and a.entity_id=p_cutting_group_id
     )
     or exists(select 1 from erp.cutting_qty_correction_lines x where x.cutting_group_id=p_cutting_group_id)
     or exists(select 1 from erp.work_completion_events x where x.cutting_group_id=p_cutting_group_id)
     or exists(select 1 from erp.sewing_terminal_events x where x.cutting_group_id=p_cutting_group_id)
     or exists(select 1 from erp.laundry_delivery_lines x where x.cutting_group_id=p_cutting_group_id)
     or exists(select 1 from erp.qc_inspection_items x where x.cutting_group_id=p_cutting_group_id)
     or exists(select 1 from erp.fg_lots x where x.cutting_group_id=p_cutting_group_id)
     or exists(select 1 from erp.bs_cases x where x.cutting_group_id=p_cutting_group_id)
     or exists(select 1 from erp.attendance_hpp_pool_allocations x where x.cutting_group_id=p_cutting_group_id)
     or exists(select 1 from erp.wip_stage_events x where x.cutting_group_id=p_cutting_group_id)
     or exists(select 1 from erp.wip_control_flags x where x.cutting_group_id=p_cutting_group_id)
     or exists(select 1 from erp.scrap_batches x where x.source_cutting_group_id=p_cutting_group_id) then
    raise exception using errcode='23514',message='PATTERN_INITIAL_ASSIGNMENT_REQUIRES_PRISTINE_CUTTING';
  end if;
end
$function$;

alter function "erp"."assert_pattern_initial_assignment_allowed"(p_cutting_group_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.assert_product_identity_time(p_product_id uuid, p_physical_at timestamp with time zone, p_mode text DEFAULT 'NEW_STOCK'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.products%rowtype;
  v_mode text:=upper(trim(coalesce(p_mode,'NEW_STOCK')));
begin
  perform erp.require_internal();
  if p_physical_at is null then raise exception 'Tanggal/jam fisik wajib diisi'; end if;
  select * into p from erp.products where id=p_product_id;
  if p.id is null then raise exception 'SKU/produk tidak ditemukan'; end if;
  if p_physical_at<p.effective_from then
    raise exception 'SKU % belum berlaku pada tanggal/jam transaksi %. Berlaku mulai %.',p.sku,p_physical_at,p.effective_from;
  end if;
  if v_mode='NEW_STOCK' then
    if not p.is_active then raise exception 'SKU % tidak aktif dan tidak boleh menerima stok baru',p.sku; end if;
    if p.effective_to is not null and p_physical_at>=p.effective_to then
      raise exception 'Versi SKU % sudah berakhir pada %. Gunakan versi SKU yang berlaku pada tanggal/jam transaksi.',p.sku,p.effective_to;
    end if;
  elsif v_mode<>'EXISTING_STOCK' then
    raise exception 'Mode validasi identitas SKU tidak dikenal';
  end if;
end$function$;

alter function "erp"."assert_product_identity_time"(p_product_id uuid, p_physical_at timestamp with time zone, p_mode text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.assign_cutting_group_to_batch(p_cutting_group_id uuid, p_cutting_batch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
BEGIN
  PERFORM erp.require_internal();
  UPDATE erp.cutting_groups
  SET cutting_batch_id=p_cutting_batch_id,updated_at=now()
  WHERE id=p_cutting_group_id;
