END;
$function$;

alter function "erp"."assign_cutting_group_to_batch"(p_cutting_group_id uuid, p_cutting_batch_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.assign_pattern_v1(p_cutting_group_id uuid, p_pattern_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_group erp.cutting_groups%rowtype;v_pattern erp.production_patterns%rowtype;
  v_hash text;v_cached jsonb;v_response jsonb;v_actor uuid:=erp.current_app_user_id();v_old_snapshot jsonb;
begin
  if not erp.has_permission('production.cutting.edit_draft')
     and not erp.has_permission('production.wip.adjust') then
    raise exception using errcode='42501',message='PERMISSION_DENIED: production pattern assignment';
  end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'reason is required'; end if;
  if p_pattern_id is null then
    raise exception using errcode='23502',message='PATTERN_ID_REQUIRED_FOR_CUTTING_TRANSACTION';
  end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'cutting_group_id',p_cutting_group_id,'pattern_id',p_pattern_id,
    'reason',btrim(p_reason),'expected_version',p_expected_version
  ));
  v_cached:=erp._idempotency_begin('assign_pattern_v1',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_group
  from erp.cutting_groups
  where id=p_cutting_group_id
  for update;
  if v_group.id is null then raise exception 'Potongan not found'; end if;
  if v_group.row_version<>p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_group.row_version;
  end if;

  perform erp.assert_pattern_initial_assignment_allowed(v_group.id);
  select * into v_pattern from erp.production_patterns where id=p_pattern_id;
  if v_pattern.id is null or not v_pattern.is_active then
    raise exception 'Active pattern is required for new assignment';
  end if;

  v_old_snapshot:=jsonb_build_object(
    'pattern_id',v_group.pattern_id,'code',v_group.pattern_code_snapshot,
    'revision',v_group.pattern_revision_snapshot,'name',v_group.pattern_name_snapshot
  );
  update erp.cutting_groups set pattern_id=p_pattern_id,updated_at=clock_timestamp()
  where id=v_group.id returning * into v_group;
  insert into erp.production_pattern_audit(
    entity_type,entity_id,pattern_id,action,old_data,new_data,change_reason,client_request_id,actor_app_user_id
  ) values(
    'ASSIGNMENT',v_group.id,p_pattern_id,'ASSIGN',
    v_old_snapshot,
    jsonb_build_object(
      'pattern_id',v_group.pattern_id,'code',v_group.pattern_code_snapshot,
      'revision',v_group.pattern_revision_snapshot,'name',v_group.pattern_name_snapshot,
      'pattern_type_snapshot',v_group.pattern_type,'row_version',v_group.row_version
    ),
    btrim(p_reason),p_client_request_id,v_actor
  );
  v_response:=jsonb_build_object(
    'cutting_group_id',v_group.id,'pattern_id',v_group.pattern_id,
    'code_snapshot',v_group.pattern_code_snapshot,'revision_snapshot',v_group.pattern_revision_snapshot,
    'name_snapshot',v_group.pattern_name_snapshot,'pattern_type_snapshot',v_group.pattern_type,
    'row_version',v_group.row_version
  );
  return erp._idempotency_complete('assign_pattern_v1',p_client_request_id,v_response);
end
$function$;

alter function "erp"."assign_pattern_v1"(p_cutting_group_id uuid, p_pattern_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.audit_accounting_mapping_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_key text;v_old jsonb;v_new jsonb;
begin
  v_key:=case when tg_op='DELETE' then old.mapping_key else new.mapping_key end;
  v_old:=case when tg_op='INSERT' then null else to_jsonb(old) end;
  v_new:=case when tg_op='DELETE' then null else to_jsonb(new) end;
  insert into erp.audit_logs(entity_type,entity_id,action,old_data,new_data,changed_by,change_reason)
  values('accounting_account_mappings',null,tg_op,v_old,v_new,erp.current_app_user_id(),coalesce(nullif(current_setting('app.change_reason',true),''),'Accounting mapping '||v_key||' changed'));
  if tg_op='DELETE' then return old; else return new; end if;
end;
$function$;

alter function "erp"."audit_accounting_mapping_change"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.audit_manual_reminder_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_action text := coalesce(nullif(current_setting('app.manual_reminder_action', true), ''), tg_op);
  v_old jsonb;
  v_new jsonb;
begin
  -- audit_logs is shared with internal staff, so title, note, module, and the
  -- private cancellation reason are intentionally never copied into it.
  if tg_op = 'UPDATE' then
    v_old := jsonb_build_object(
      'row_version', old.row_version,
      'content_redacted', true
    );
  end if;

  v_new := jsonb_build_object(
    'row_version', new.row_version,
    'title_changed', case when tg_op = 'INSERT' then true else new.title is distinct from old.title end,
    'note_changed', case when tg_op = 'INSERT' then true else new.note is distinct from old.note end,
    'module_changed', case when tg_op = 'INSERT' then true else new.module is distinct from old.module end,
    'content_redacted', true
  );

  insert into erp.audit_logs(
    entity_type, entity_id, action, old_data, new_data, changed_by, change_reason
  ) values (
    'manual_reminders', new.id, case when tg_op = 'INSERT' then 'INSERT' else 'UPDATE' end,
    v_old, v_new, erp.current_app_user_id(),
    'Manual reminder ' || lower(v_action)
  );

  return new;
end;
$function$;

alter function "erp"."audit_manual_reminder_change"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_reason text := nullif(current_setting('app.change_reason', true), '');
  v_old jsonb;
  v_new jsonb;
  v_key jsonb;
  v_id_text text;
  v_entity_id uuid;
begin
  if tg_op <> 'INSERT' then v_old := to_jsonb(old); end if;
  if tg_op <> 'DELETE' then v_new := to_jsonb(new); end if;
  v_key := coalesce(v_new, v_old);
  v_id_text := coalesce(nullif(v_key->>'id', ''), nullif(v_key->>'material_id', ''));
  if v_id_text is not null then
    begin
      v_entity_id := v_id_text::uuid;
    exception when invalid_text_representation then
      v_entity_id := null;
    end;
  end if;

  if tg_op = 'INSERT' then
    insert into erp.audit_logs(
      entity_type, entity_id, action, new_data, changed_by, change_reason
    ) values (
      tg_table_name, v_entity_id, 'INSERT', v_new,
      erp.current_app_user_id(), v_reason
    );
    return new;
  elsif tg_op = 'UPDATE' then
    if v_old is distinct from v_new then
      insert into erp.audit_logs(
        entity_type, entity_id, action, old_data, new_data, changed_by, change_reason
      ) values (
        tg_table_name, v_entity_id, 'UPDATE', v_old, v_new,
        erp.current_app_user_id(), v_reason
      );
    end if;
    return new;
  else
    insert into erp.audit_logs(
      entity_type, entity_id, action, old_data, changed_by, change_reason
    ) values (
      tg_table_name, v_entity_id, 'DELETE', v_old,
      erp.current_app_user_id(), v_reason
    );
    return old;
  end if;
end;
$function$;

alter function "erp"."audit_row_change"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.bump_row_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  new.row_version := old.row_version + 1;
  return new;
end;
$function$;

alter function "erp"."bump_row_version"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.cancel_attendance_hpp_pool_v1(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'cancel_attendance_hpp_pool_v1';
  v_hash text;
  v_cached jsonb;
  v_pool erp.attendance_hpp_pools%rowtype;
  v_reversal_journal_id uuid;
  v_effective_date date;
  v_po_id uuid;
  v_response jsonb;
begin
  perform erp.require_owner_admin();
  if p_pool_id is null or p_expected_version is null then
    raise exception 'pool_id and expected_version are required';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Attendance HPP cancellation reason is required';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'pool_id', p_pool_id,
    'reason', btrim(p_reason),
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_pool
  from erp.attendance_hpp_pools
  where id = p_pool_id
  for update;

  if v_pool.id is null then raise exception 'Attendance HPP pool not found'; end if;
  if v_pool.status not in ('DRAFT','ACTIVE') then
    raise exception 'Only DRAFT or ACTIVE attendance HPP pool can be cancelled';
  end if;
  if v_pool.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_pool.row_version;
  end if;

  perform erp._cp3_lock_business_period(v_pool.period_start, v_pool.period_end);

  if v_pool.status = 'DRAFT' then
    update erp.attendance_hpp_pools
    set status = 'VOIDED',
        cancellation_reason = btrim(p_reason),
        cancelled_by = erp.current_app_user_id(),
        cancelled_at = clock_timestamp(),
        row_version = row_version + 1
    where id = v_pool.id
    returning * into v_pool;

    insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
    values (
      'attendance_hpp_pools', v_pool.id, 'UPDATE',
      jsonb_build_object('previous_status','DRAFT','new_status','VOIDED','lifecycle_action','VOID_DRAFT'),
      erp.current_app_user_id(), btrim(p_reason)
    );

    v_response := jsonb_build_object(
      'pool_id', v_pool.id,
      'status', v_pool.status,
      'row_version', v_pool.row_version,
      'reversal_journal_entry_id', null,
      'residue_expected', 0
    );
    return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
  end if;

  if v_pool.post_journal_entry_id is null then
    raise exception 'ACTIVE attendance HPP pool has no source journal; cancellation stopped to avoid residue';
  end if;

  if not exists (
    select 1 from erp.journal_entries je
    where je.id = v_pool.post_journal_entry_id
      and je.status = 'POSTED'
      and je.source_type = 'ATTENDANCE_HPP_POOL'
      and je.source_id = v_pool.id
  ) then
    raise exception 'Pool journal is not an active posted ATTENDANCE_HPP_POOL journal';
  end if;

  v_reversal_journal_id := erp._cp3_r4_reverse_journal_internal(v_pool.post_journal_entry_id, btrim(p_reason));
  select transaction_date into v_effective_date
  from erp.journal_entries where id=v_reversal_journal_id;

  update erp.attendance_hpp_pools
  set status = 'CANCELLED',
      cancellation_journal_entry_id = v_reversal_journal_id,
      cancellation_reason = btrim(p_reason),
      cancelled_by = erp.current_app_user_id(),
      cancelled_at = clock_timestamp(),
      row_version = row_version + 1
  where id = v_pool.id
  returning * into v_pool;

  for v_po_id in
    select distinct a.po_id
    from erp.attendance_hpp_pool_allocations a
    where a.pool_id=v_pool.id
    order by a.po_id
  loop
    perform erp.rebuild_po_hpp(v_po_id,'Attendance HPP pool cancellation '||v_pool.id::text);
    perform erp.propagate_conversion_hpp_for_po(v_po_id);
    perform erp.sync_po_hpp_to_gl(v_po_id,v_effective_date);
  end loop;

  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
  values (
    'attendance_hpp_pools', v_pool.id, 'REVERSE',
    jsonb_build_object(
      'post_journal_entry_id', v_pool.post_journal_entry_id,
      'cancellation_journal_entry_id', v_pool.cancellation_journal_entry_id,
      'previous_status', 'ACTIVE',
      'new_status', 'CANCELLED',
      'lifecycle_action', 'CANCEL_ACTIVE'
    ),
    erp.current_app_user_id(), btrim(p_reason)
  );

  v_response := jsonb_build_object(
    'pool_id', v_pool.id,
    'status', v_pool.status,
    'row_version', v_pool.row_version,
    'reversal_journal_entry_id', v_pool.cancellation_journal_entry_id,
    'residue_expected', 0
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."cancel_attendance_hpp_pool_v1"(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.cancel_my_reminder_v1(p_reminder_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'cancel_my_reminder_v1';
  v_actor uuid := erp.require_manual_reminder_actor();
  v_reason text := btrim(coalesce(p_reason, ''));
  v_hash text;
  v_cached jsonb;
  v_row erp.manual_reminders%rowtype;
  v_response jsonb;
begin
  if p_reminder_id is null or p_expected_version is null or p_expected_version < 1 then
    raise exception 'reminder_id and a positive expected_version are required';
  end if;
  if v_reason = '' or char_length(v_reason) > 1000 then
    raise exception 'Cancellation reason must contain 1 to 1000 characters';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'reminder_id', p_reminder_id,
    'reason', v_reason,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_row
  from erp.manual_reminders r
  where r.id = p_reminder_id and r.owner_user_id = v_actor
  for update;

  if v_row.id is null then raise exception 'Reminder not found'; end if;
  if v_row.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_row.row_version;
  end if;
  if v_row.status = 'CANCELLED' then raise exception 'Cancelled reminders are terminal'; end if;

  perform set_config('app.manual_reminder_write', 'on', true);
  perform set_config('app.manual_reminder_action', 'CANCEL', true);
  update erp.manual_reminders r
  set status = 'CANCELLED',
      cancelled_at = clock_timestamp(),
      cancelled_by = v_actor,
      cancellation_reason = v_reason,
      updated_at = clock_timestamp(),
      updated_by = v_actor,
      last_client_request_id = p_client_request_id
  where r.id = p_reminder_id and r.owner_user_id = v_actor
  returning * into v_row;

  perform set_config('app.manual_reminder_write', 'off', true);
  perform set_config('app.manual_reminder_action', '', true);

  v_response := jsonb_build_object(
    'reminder_id', v_row.id,
    'status', v_row.status,
    'cancelled_at', v_row.cancelled_at,
    'row_version', v_row.row_version,
    'client_request_id', p_client_request_id
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."cancel_my_reminder_v1"(p_reminder_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.cancel_product_identity_successor(p_product_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.products%rowtype;
  prev erp.products%rowtype;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan pembatalan perubahan SKU wajib diisi'; end if;

  select * into p from erp.products where id=p_product_id for update;
  if p.id is null then raise exception 'Versi SKU tidak ditemukan'; end if;
  if p.supersedes_product_id is null then raise exception 'SKU ini bukan successor. Hapus biasa hanya boleh untuk SKU baru yang benar-benar belum pernah dipakai.'; end if;
  if exists(select 1 from erp.products x where x.supersedes_product_id=p.id) then
    raise exception 'Versi SKU ini sudah memiliki successor berikutnya. Batalkan versi paling akhir terlebih dahulu.';
  end if;
  if exists(select 1 from erp.fg_lots x where x.product_id=p.id)
     or exists(select 1 from erp.sales_items x where x.product_id=p.id)
     or exists(select 1 from erp.qc_inspection_items x where x.final_product_id=p.id)
     or exists(select 1 from erp.opening_balance_items x where x.product_id=p.id)
     or exists(select 1 from erp.bs_cases x where x.product_id=p.id)
     or exists(select 1 from erp.po_accessory_bom_commitments x where x.product_id=p.id)
     or exists(select 1 from erp.product_conversions x where x.from_product_id=p.id or x.to_product_id=p.id) then
    raise exception 'Perubahan SKU ini sudah dipakai transaksi/stok/HPP dan tidak boleh dibatalkan. Buat perubahan efektif baru sebagai koreksi.';
  end if;

  select * into prev from erp.products where id=p.supersedes_product_id for update;
  if prev.id is null or prev.identity_root_id is distinct from p.identity_root_id or prev.effective_to is distinct from p.effective_from then
    raise exception 'Chain versi SKU tidak konsisten; pembatalan dihentikan agar histori tidak rusak.';
  end if;

  perform set_config('app.product_identity_controlled','on',true);
  delete from erp.products where id=p.id;
  update erp.products set effective_to=p.effective_to,updated_at=now() where id=prev.id;

  insert into erp.audit_logs(entity_type,entity_id,action,old_data,new_data,changed_by,change_reason)
  values('products',prev.id,'UPDATE',to_jsonb(prev),jsonb_build_object('cancelled_successor_product_id',p.id,'restored_effective_to',p.effective_to),erp.current_app_user_id(),p_reason);
  return prev.id;
end;
$function$;

alter function "erp"."cancel_product_identity_successor"(p_product_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.cancel_sale_draft_v2(p_sale_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  h erp.sales_headers%rowtype;
  v_released bigint;
begin
  perform erp.require_internal();
  if nullif(btrim(p_reason),'') is null then raise exception 'Cancellation reason is required'; end if;
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  v_hash := erp._request_hash(jsonb_build_object(
    'sale_id',p_sale_id,'reason',btrim(p_reason),'expected_version',p_expected_version
  ));
  v_cached := erp._idempotency_begin('cancel_sale_draft_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  select * into h from erp.sales_headers where id=p_sale_id for update;
  if h.id is null then raise exception 'Sale Draft not found'; end if;
  if h.status <> 'DRAFT' then raise exception 'Only a DRAFT sale can be cancelled'; end if;
  if h.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version;
  end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  v_released := erp._release_sale_draft_reservations(h.id,btrim(p_reason));
  update erp.sales_headers set status='CANCELLED' where id=h.id returning * into h;
  v_response := jsonb_build_object(
    'sale_id',h.id,'sale_number',h.sale_number,'status',h.status,
    'released_qty_pcs',v_released,'sellable_stock_delta_pcs',v_released,
    'row_version',h.row_version
  );
  return erp._idempotency_complete('cancel_sale_draft_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."cancel_sale_draft_v2"(p_sale_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.cancel_unpaid_payroll(p_payroll_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.payroll_settlements%rowtype;
  r record;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Cancellation reason is required'; end if;
  select * into p from erp.payroll_settlements where id=p_payroll_id for update;
  if p.id is null then raise exception 'Payroll not found'; end if;
  if p.status='PAID' then raise exception 'Paid payroll requires a dedicated financial reversal, not unpaid cancellation'; end if;
  if p.status='REVERSED' then return; end if;
  if p.status not in ('DRAFT','CALCULATED','REVIEW','APPROVED') then raise exception 'Payroll cannot be cancelled in status %',p.status; end if;
  perform erp._cp3_lock_business_period(p.period_start,p.period_end);

  if exists(
    select 1 from erp.attendance_hpp_pool_sources s
    join erp.attendance_hpp_pools hp on hp.id=s.pool_id
    where s.payroll_id=p.id and hp.status='ACTIVE'
  ) then
    raise exception 'PAYROLL_CONSUMED_BY_ACTIVE_HPP_POOL: cancel the active attendance HPP pool first';
  end if;

  for r in
    select je.id from erp.journal_entries je
    where je.source_id=p.id
      and je.source_type in ('PAYROLL_ATTENDANCE_ACCRUAL','PAYROLL_EXTRA_ACCRUAL','PAYROLL_MANUAL_REDUCTION')
      and je.status='POSTED'
    order by je.posting_at desc,je.id desc
  loop perform erp._cp3_r4_reverse_journal_internal(r.id,p_reason); end loop;

  update erp.payroll_settlements set status='REVERSED',settled_at=null,updated_at=now() where id=p.id;
  for r in select distinct pd.contractor_issue_item_id id from erp.payroll_deductions pd
           where pd.payroll_id=p.id and pd.contractor_issue_item_id is not null
  loop perform erp.refresh_contractor_issue_payroll_status(r.id); end loop;
  for r in select distinct pr.source_id id from erp.payroll_reimbursements pr
           where pr.payroll_id=p.id and pr.source_type='ACCESSORY_BOM' and pr.source_id is not null
  loop
    update erp.contractor_accessory_reimbursement_entitlements e
    set payroll_status=case
      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id
                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status='PAID') then 'SETTLED'
      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id
                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status<>'REVERSED') then 'ALLOCATED'
      else 'UNALLOCATED' end
    where e.id=r.id;
  end loop;
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('payroll_settlements',p.id,'CANCEL_UNPAID',jsonb_build_object('previous_status',p.status),erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."cancel_unpaid_payroll"(p_payroll_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.classify_bs_case_v2(p_bs_case_id uuid, p_payload jsonb, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_case erp.bs_cases%rowtype;
  v_cause text;v_contractor uuid;v_vendor uuid;
  v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_component jsonb;v_snapshot uuid;
begin
  perform erp.require_internal();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if v_reason is null then raise exception 'change_reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'bs_case_id',p_bs_case_id,'payload',p_payload,'expected_version',p_expected_version
  ));
  v_cached:=erp._idempotency_begin('classify_bs_case_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  select * into v_case from erp.bs_cases where id=p_bs_case_id for update;
  if v_case.id is null then raise exception 'BS case not found'; end if;
  if v_case.status not in('OPEN','PARTIAL','IN_REWORK') then raise exception 'Closed/cancelled BS case cannot be classified'; end if;
  if v_case.row_version<>p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_case.row_version;
  end if;
  v_cause:=upper(coalesce(nullif(p_payload->>'cause_source',''),v_case.cause_source));
  v_contractor:=case when p_payload?'responsible_contractor_id'
    then nullif(p_payload->>'responsible_contractor_id','')::uuid else v_case.responsible_contractor_id end;
  v_vendor:=case when p_payload?'responsible_vendor_id'
    then nullif(p_payload->>'responsible_vendor_id','')::uuid else v_case.responsible_vendor_id end;
  if v_cause='SEWING' and v_contractor is null then raise exception 'SEWING cause requires responsible contractor'; end if;
  if v_cause='LAUNDRY' and v_vendor is null then raise exception 'LAUNDRY cause requires responsible vendor'; end if;
  if v_cause not in('SEWING','LAUNDRY','UNKNOWN') then raise exception 'Invalid cause_source'; end if;
  perform set_config('app.change_reason',v_reason,true);
  update erp.bs_cases
  set cause_source=v_cause,responsible_contractor_id=v_contractor,
      responsible_vendor_id=v_vendor,
      notes=case when p_payload?'notes' then nullif(btrim(p_payload->>'notes'),'') else notes end,
      legacy_reference=case when p_payload?'legacy_reference' then nullif(btrim(p_payload->>'legacy_reference'),'') else legacy_reference end,
      updated_at=now()
  where id=v_case.id returning * into v_case;

  if p_payload?'components' then
    if exists(
      select 1 from erp.rework_component_lines rcl
      join erp.bs_case_components bcc on bcc.id=rcl.bs_case_component_id
      where bcc.bs_case_id=v_case.id
    ) then raise exception 'BS components are frozen after rework lines exist'; end if;
    if jsonb_typeof(p_payload->'components')<>'array' then raise exception 'components must be an array'; end if;
    delete from erp.bs_case_components where bs_case_id=v_case.id;
    for v_component in select value from jsonb_array_elements(p_payload->'components') loop
      select id into v_snapshot from erp.po_work_component_snapshots
      where po_id=v_case.po_id and work_component_id=(v_component->>'work_component_id')::uuid
      order by committed_at desc,id desc limit 1;
      insert into erp.bs_case_components(
        bs_case_id,po_component_snapshot_id,work_component_id,completed_before_bs_qty,notes
      ) values(
        v_case.id,v_snapshot,(v_component->>'work_component_id')::uuid,
        coalesce(nullif(v_component->>'completed_before_bs_qty','')::integer,0),
        nullif(btrim(v_component->>'notes'),'')
      );
    end loop;
    update erp.bs_cases set updated_at=now() where id=v_case.id returning * into v_case;
  end if;
  v_response:=jsonb_build_object(
    'bs_case_id',v_case.id,'status',v_case.status,'cause_source',v_case.cause_source,
    'row_version',v_case.row_version,'component_count',(
      select count(*) from erp.bs_case_components where bs_case_id=v_case.id
    )
  );
  return erp._idempotency_complete('classify_bs_case_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."classify_bs_case_v2"(p_bs_case_id uuid, p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.close_accounting_through(p_closed_through date, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare v_old date; v_material uuid;
begin
  perform erp.require_owner_admin();
  if p_closed_through is null then raise exception 'Tanggal tutup buku wajib diisi'; end if;
  if p_closed_through>=current_date then raise exception 'Tutup buku hanya boleh sampai tanggal sebelum hari ini'; end if;
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan tutup buku wajib diisi'; end if;
  select closed_through into v_old from erp.accounting_period_control where singleton_id=1 for update;
  if v_old is not null and p_closed_through<v_old then
    raise exception 'Untuk membuka kembali periode gunakan reopen_accounting_through(); periode saat ini sudah ditutup sampai %',v_old;
  end if;
  update erp.accounting_period_control
  set closed_through=p_closed_through,updated_at=now(),updated_by=erp.current_app_user_id(),change_reason=p_reason
  where singleton_id=1;

  for v_material in select id from erp.materials order by id loop
    perform erp.refresh_material_cost_checkpoint(v_material,p_closed_through);
  end loop;

  insert into erp.audit_logs(entity_type,entity_id,action,old_data,new_data,changed_by,change_reason)
  values('accounting_period_control',null,'UPDATE',jsonb_build_object('closed_through',v_old),jsonb_build_object('closed_through',p_closed_through,'material_cost_checkpoints_refreshed',true),erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."close_accounting_through"(p_closed_through date, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.commit_accessory_bom_for_lot(p_lot_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  l erp.fg_lots%rowtype; p erp.production_orders%rowtype; v_product_model uuid; v_root uuid; v_bom uuid; v_distinct_boms integer;
begin
  perform erp.require_internal();
  select * into l from erp.fg_lots where id=p_lot_id for update;
  if l.id is null or l.lot_origin<>'PRODUCTION' then return null; end if;
  select * into p from erp.production_orders where id=l.po_id for update;
  if p.id is null then raise exception 'Production PO untuk lot FG tidak ditemukan'; end if;
  select model_id,identity_root_id into v_product_model,v_root from erp.products where id=l.product_id;
  if v_product_model is distinct from p.model_id then raise exception 'FG SKU model does not match production order model'; end if;

  select c.bom_version_id into v_bom from erp.po_accessory_bom_commitments c where c.po_id=l.po_id and c.product_id=l.product_id;
  if v_bom is not null then return v_bom; end if;

  select count(distinct c.bom_version_id) into v_distinct_boms
  from erp.po_accessory_bom_commitments c join erp.products cp on cp.id=c.product_id
  where c.po_id=l.po_id and cp.identity_root_id=v_root;
  if coalesce(v_distinct_boms,0)>1 then raise exception 'PO memiliki lebih dari satu accessory BOM commitment untuk logical SKU yang sama. Koreksi histori commitment sebelum membuat FG baru.'; end if;
  if coalesce(v_distinct_boms,0)=1 then
    select c.bom_version_id into v_bom from erp.po_accessory_bom_commitments c join erp.products cp on cp.id=c.product_id
    where c.po_id=l.po_id and cp.identity_root_id=v_root order by c.committed_at,c.id limit 1;
  else
    perform pg_advisory_xact_lock(hashtextextended('ABOM:'||v_root::text,0));
    select abv.id into v_bom from erp.accessory_bom_versions abv
    where abv.product_id=v_root and abv.is_active=true and abv.effective_from<=l.produced_at and (abv.effective_to is null or abv.effective_to>l.produced_at)
    order by abv.effective_from desc,abv.created_at desc,abv.id desc limit 1;
    if v_bom is null then
      raise exception 'Accessory BOM SKU belum diset pada tanggal FG %. Setup BOM sebelum first HPP use. Jika produk memang tanpa aksesori, buat BOM version kosong sebagai deklarasi NO ACCESSORY.',l.produced_at;
    end if;
  end if;

  insert into erp.po_accessory_bom_commitments(po_id,product_id,bom_version_id,committed_at,commit_source,committed_by)
  values(l.po_id,l.product_id,v_bom,l.produced_at,'FIRST_FINANCIAL_USE',erp.current_app_user_id())
  on conflict (po_id,product_id) do nothing;
  select c.bom_version_id into v_bom from erp.po_accessory_bom_commitments c where c.po_id=l.po_id and c.product_id=l.product_id;
  return v_bom;
end;
$function$;

alter function "erp"."commit_accessory_bom_for_lot"(p_lot_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.complete_rework_order_v2(p_rework_order_id uuid, p_qty_good integer, p_qty_bs integer, p_completed_at timestamp with time zone, p_return_fg_location_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_order erp.rework_orders%rowtype;v_case erp.bs_cases%rowtype;
begin
  perform erp.require_internal();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'Completion reason is required'; end if;
  if p_completed_at is null or p_completed_at>clock_timestamp()+interval '5 minutes' then
    raise exception 'Valid non-future completed_at is required';
  end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'rework_order_id',p_rework_order_id,'good',p_qty_good,'bs',p_qty_bs,
    'completed_at',p_completed_at,'location',p_return_fg_location_id,
    'reason',btrim(p_reason),'expected_version',p_expected_version
  ));
  v_cached:=erp._idempotency_begin('complete_rework_order_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  select * into v_order from erp.rework_orders where id=p_rework_order_id for update;
  if v_order.id is null then raise exception 'Rework order not found'; end if;
  if v_order.row_version<>p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_order.row_version;
  end if;
  if v_order.status not in('OPEN','IN_PROGRESS','PARTIAL') or v_order.cost_posted then
    raise exception 'Only active unposted rework can be completed';
  end if;
  if coalesce(p_qty_good,0)<0 or coalesce(p_qty_bs,0)<0
     or coalesce(p_qty_good,0)+coalesce(p_qty_bs,0)<>v_order.qty_sent then
    raise exception 'Completion must reconcile exactly: GOOD + BS = qty sent';
  end if;
  if v_order.destination_type='CONTRACTOR' and not exists(
    select 1 from erp.rework_component_lines where rework_order_id=v_order.id
  ) then raise exception 'Contractor rework requires component lines'; end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  update erp.rework_orders
  set qty_good_returned=coalesce(p_qty_good,0),qty_bs_returned=coalesce(p_qty_bs,0),
      completed_at=p_completed_at,status='COMPLETED',
      return_fg_location_id=coalesce(p_return_fg_location_id,return_fg_location_id),
      notes=concat_ws(E'\n',notes,'COMPLETED: '||btrim(p_reason)),updated_at=now()
  where id=v_order.id;
  perform erp.post_rework_completion(v_order.id);
  select * into v_order from erp.rework_orders where id=v_order.id;
  select * into v_case from erp.bs_cases where id=v_order.bs_case_id;
  v_response:=jsonb_build_object(
    'rework_order_id',v_order.id,'status',v_order.status,'row_version',v_order.row_version,
    'cost_posted',v_order.cost_posted,'good_fg_lot_id',v_order.good_fg_lot_id,
    'bs_case_id',v_case.id,'bs_case_status',v_case.status,'bs_case_row_version',v_case.row_version
  );
  return erp._idempotency_complete('complete_rework_order_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."complete_rework_order_v2"(p_rework_order_id uuid, p_qty_good integer, p_qty_bs integer, p_completed_at timestamp with time zone, p_return_fg_location_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.create_attendance_hpp_pool_v1(p_payload jsonb, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'create_attendance_hpp_pool_v1';
  v_hash text;
  v_cached jsonb;
  v_period_start date;
  v_period_end date;
  v_reason text;
  v_correction_of uuid;
  v_preview jsonb;
  v_manifest jsonb;
  v_pool erp.attendance_hpp_pools%rowtype;
  v_response jsonb;
begin
  perform erp.require_owner_admin();
  perform erp._cp3_assert_closed_json_object(
    p_payload,
    array['period_start','period_end','reason'],
    array['period_start','period_end','reason','correction_of_pool_id'],
    'attendance HPP pool payload'
  );
  if jsonb_typeof(p_payload->'period_start') is distinct from 'string'
     or jsonb_typeof(p_payload->'period_end') is distinct from 'string'
     or jsonb_typeof(p_payload->'reason') is distinct from 'string'
     or (p_payload ? 'correction_of_pool_id'
         and coalesce(jsonb_typeof(p_payload->'correction_of_pool_id'), 'missing') not in ('string','null')) then
    raise exception 'Attendance HPP pool payload has invalid field types';
  end if;

  v_period_start := erp._cp3_parse_canonical_date(p_payload->>'period_start', 'attendance HPP period_start');
  v_period_end := erp._cp3_parse_canonical_date(p_payload->>'period_end', 'attendance HPP period_end');
  v_reason := nullif(btrim(p_payload->>'reason'), '');
  v_correction_of := nullif(p_payload->>'correction_of_pool_id', '')::uuid;
  if v_reason is null then raise exception 'Attendance HPP pool reason is required'; end if;

  v_hash := erp._request_hash(jsonb_build_object('payload', p_payload));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  perform erp._cp3_lock_business_period(v_period_start, v_period_end);
  perform erp._cp3_lock_manifest_contractors(v_period_start, v_period_end);

  if exists (
    select 1 from erp.attendance_hpp_pools p
    where p.period_start = v_period_start
      and p.period_end = v_period_end
      and p.status in ('DRAFT','ACTIVE')
  ) then
    raise exception 'A DRAFT/ACTIVE attendance HPP pool already exists for this exact period';
  end if;
  if v_correction_of is not null and not exists (
    select 1 from erp.attendance_hpp_pools p
    where p.id = v_correction_of
      and p.status = 'CANCELLED'
      and p.period_start = v_period_start
      and p.period_end = v_period_end
  ) then
    raise exception 'correction_of_pool_id must reference a CANCELLED pool for the same exact period';
  end if;

  v_preview := erp.preview_attendance_hpp_pool_v1(v_period_start, v_period_end);
  v_manifest := v_preview->'manifest';

  insert into erp.attendance_hpp_pools(
    pool_number, period_start, period_end, correction_of_pool_id,
    numerator_amount, denominator_qty, unit_cost_per_sewn_pcs,
    source_manifest, source_manifest_sha256,
    reason, created_by
  ) values (
    'AHPP-' || to_char(clock_timestamp() at time zone 'UTC', 'YYYYMMDDHH24MISSUS') || '-' || substr(gen_random_uuid()::text, 1, 8),
    v_period_start, v_period_end, v_correction_of,
    (v_preview->>'numerator_amount')::numeric,
    (v_preview->>'denominator_qty')::bigint,
    (v_preview->>'unit_cost_per_sewn_pcs')::numeric,
    v_manifest, v_preview->>'manifest_sha256',
    v_reason, erp.current_app_user_id()
  ) returning * into v_pool;

  insert into erp.attendance_hpp_pool_sources(
    pool_id, payroll_id, contractor_id, policy_version_id,
    original_debit_journal_line_id,
    contractor_role_snapshot, attendance_required_snapshot, is_special_snapshot,
    attendance_amount
  )
  select
    v_pool.id,
    (x->>'payroll_id')::uuid,
    (x->>'contractor_id')::uuid,
    (x->>'policy_version_id')::uuid,
    (x->>'original_debit_journal_line_id')::uuid,
    x->>'contractor_role_snapshot',
    (x->>'attendance_required_snapshot')::boolean,
    (x->>'is_special_snapshot')::boolean,
    ((x->>'attendance_amount_cents')::bigint / 100.0)::numeric(20,2)
  from jsonb_array_elements(v_manifest->'sources') x;

  with destination as (
    select
      (x->>'sewing_terminal_event_id')::uuid sewing_terminal_event_id,
      (x->>'contractor_id')::uuid contractor_id,
      (x->>'po_id')::uuid po_id,
      nullif(x->>'cutting_group_id', '')::uuid cutting_group_id,
      (x->>'sewing_qty')::integer sewing_qty,
      sum((x->>'sewing_qty')::bigint) over (
        order by (x->>'physical_at_epoch_us')::bigint,
                 (x->>'sewing_terminal_event_id')::uuid
        rows between unbounded preceding and current row
      ) cumulative_qty,
      coalesce(sum((x->>'sewing_qty')::bigint) over (
        order by (x->>'physical_at_epoch_us')::bigint,
                 (x->>'sewing_terminal_event_id')::uuid
        rows between unbounded preceding and 1 preceding
      ), 0) previous_cumulative_qty
    from jsonb_array_elements(v_manifest->'destinations') x
  ), source as (
    select s.*, round(s.attendance_amount * 100)::bigint source_cents
    from erp.attendance_hpp_pool_sources s
    where s.pool_id = v_pool.id
  )
  insert into erp.attendance_hpp_pool_allocations(
    pool_id, pool_source_id, sewing_terminal_event_id,
    contractor_id, po_id, cutting_group_id,
    sewing_qty, allocated_amount
  )
  select
    v_pool.id, s.id, d.sewing_terminal_event_id,
    d.contractor_id, d.po_id, d.cutting_group_id,
    d.sewing_qty,
    (
      floor(s.source_cents::numeric * d.cumulative_qty::numeric / v_pool.denominator_qty)
      - floor(s.source_cents::numeric * d.previous_cumulative_qty::numeric / v_pool.denominator_qty)
    ) / 100.0
  from source s cross join destination d
  order by s.id, d.cumulative_qty, d.sewing_terminal_event_id;

  if exists (
    select 1
    from erp.attendance_hpp_pool_sources s
    left join erp.attendance_hpp_pool_allocations a on a.pool_source_id = s.id
    where s.pool_id = v_pool.id
    group by s.id, s.attendance_amount
    having round(coalesce(sum(a.allocated_amount), 0), 2) is distinct from round(s.attendance_amount, 2)
  ) then
    raise exception 'Deterministic allocation failed to reconcile a source debit line exactly to cents';
  end if;

  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
  values (
    'attendance_hpp_pools', v_pool.id, 'INSERT',
    jsonb_build_object(
      'period_start', v_pool.period_start,
      'period_end', v_pool.period_end,
      'numerator_amount', v_pool.numerator_amount,
      'denominator_qty', v_pool.denominator_qty,
      'manifest_sha256', v_pool.source_manifest_sha256,
      'correction_of_pool_id', v_pool.correction_of_pool_id,
      'lifecycle_action', 'CREATE_DRAFT'
    ),
    erp.current_app_user_id(), v_reason
  );

  v_response := jsonb_build_object(
    'pool_id', v_pool.id,
    'pool_number', v_pool.pool_number,
    'status', v_pool.status,
    'row_version', v_pool.row_version,
    'numerator_amount', v_pool.numerator_amount,
    'denominator_qty', v_pool.denominator_qty,
    'unit_cost_per_sewn_pcs', v_pool.unit_cost_per_sewn_pcs,
    'manifest_sha256', v_pool.source_manifest_sha256
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."create_attendance_hpp_pool_v1"(p_payload jsonb, p_client_request_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.create_cutting_batch(p_po_id uuid, p_batch_number text, p_cut_at timestamp with time zone, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  PERFORM erp.require_internal();
  IF NOT EXISTS (SELECT 1 FROM erp.production_orders WHERE id=p_po_id) THEN
    RAISE EXCEPTION 'Production order not found';
  END IF;
  IF COALESCE(btrim(p_batch_number),'')='' THEN RAISE EXCEPTION 'Batch number is required'; END IF;
  INSERT INTO erp.cutting_batches(po_id,batch_number,cut_at,notes,created_by)
  VALUES (p_po_id,btrim(p_batch_number),p_cut_at,p_notes,erp.current_app_user_id())
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$;

alter function "erp"."create_cutting_batch"(p_po_id uuid, p_batch_number text, p_cut_at timestamp with time zone, p_notes text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.create_manual_bs_case_v2(p_payload jsonb, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_id uuid:=gen_random_uuid();
  v_type text:=upper(coalesce(p_payload->>'untracked_type',''));
  v_ref text:=nullif(btrim(p_payload->>'legacy_reference'),'');
  v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_physical timestamptz:=nullif(p_payload->>'physical_at','')::timestamptz;
  v_component jsonb;
  v_case erp.bs_cases%rowtype;
begin
  perform erp.require_internal();
  if v_type not in('LEGACY','OUT_OF_NOWHERE') then
    raise exception 'Manual BS is allowed only for LEGACY or OUT_OF_NOWHERE';
  end if;
  if v_ref is null then raise exception 'legacy_reference is required for manual BS traceability'; end if;
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if v_physical is null or v_physical>clock_timestamp()+interval '5 minutes' then
    raise exception 'Valid non-future physical_at is required';
  end if;
  if coalesce(nullif(p_payload->>'qty_pcs','')::integer,0)<=0 then raise exception 'qty_pcs must be positive'; end if;
  v_hash:=erp._request_hash(p_payload);
  v_cached:=erp._idempotency_begin('create_manual_bs_case_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',v_reason,true);
  insert into erp.bs_cases(
    id,bs_number,po_id,cutting_group_id,qc_item_id,product_id,
    detected_at_stage,cause_source,untracked_type,
    responsible_contractor_id,responsible_vendor_id,qty_pcs,status,
    physical_at,legacy_reference,notes
  ) values(
    v_id,coalesce(nullif(btrim(p_payload->>'bs_number'),''),
      'BS-MAN-'||to_char(v_physical,'YYYYMMDD')||'-'||substr(v_id::text,1,8)),
    null,null,null,nullif(p_payload->>'product_id','')::uuid,
    'UNKNOWN','UNKNOWN',v_type,
    nullif(p_payload->>'responsible_contractor_id','')::uuid,
    nullif(p_payload->>'responsible_vendor_id','')::uuid,
    (p_payload->>'qty_pcs')::integer,'OPEN',v_physical,v_ref,
    nullif(btrim(p_payload->>'notes'),'')
  ) returning * into v_case;
  if p_payload?'components' then
    if jsonb_typeof(p_payload->'components')<>'array' then raise exception 'components must be an array'; end if;
    for v_component in select value from jsonb_array_elements(p_payload->'components') loop
      insert into erp.bs_case_components(
        bs_case_id,po_component_snapshot_id,work_component_id,completed_before_bs_qty,notes
      ) values(
        v_case.id,null,(v_component->>'work_component_id')::uuid,
        coalesce(nullif(v_component->>'completed_before_bs_qty','')::integer,0),
        nullif(btrim(v_component->>'notes'),'')
      );
    end loop;
  end if;
  select * into v_case from erp.bs_cases where id=v_case.id;
  v_response:=jsonb_build_object(
    'bs_case_id',v_case.id,'bs_number',v_case.bs_number,'status',v_case.status,
    'row_version',v_case.row_version,'untracked_type',v_case.untracked_type
  );
  return erp._idempotency_complete('create_manual_bs_case_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."create_manual_bs_case_v2"(p_payload jsonb, p_client_request_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.create_migration_batch(p_batch_code text, p_cutover_at timestamp with time zone, p_source_system text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_id uuid; BEGIN PERFORM erp.require_owner_admin(); IF NULLIF(trim(p_batch_code),'') IS NULL THEN RAISE EXCEPTION 'Migration batch code is required'; END IF; IF p_cutover_at IS NULL THEN RAISE EXCEPTION 'Migration cutover time is required'; END IF;INSERT INTO erp.migration_batches(batch_code,source_system,cutover_at,notes,created_by) VALUES (trim(p_batch_code),NULLIF(trim(p_source_system),''),p_cutover_at,p_notes,erp.current_app_user_id()) RETURNING id INTO v_id;INSERT INTO erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason) VALUES ('migration_batches',v_id,'INSERT',jsonb_build_object('batch_code',p_batch_code,'cutover_at',p_cutover_at),erp.current_app_user_id(),'Create migration batch');RETURN v_id;END; $function$;

alter function "erp"."create_migration_batch"(p_batch_code text, p_cutover_at timestamp with time zone, p_source_system text, p_notes text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.deactivate_pattern_v1(p_pattern_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_pattern erp.production_patterns%rowtype;v_hash text;v_cached jsonb;v_response jsonb;v_actor uuid:=erp.current_app_user_id();
begin
  perform erp.require_permission('master.pattern.manage');
  if nullif(btrim(p_reason),'') is null then raise exception 'reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('pattern_id',p_pattern_id,'reason',btrim(p_reason),'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('deactivate_pattern_v1',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  select * into v_pattern from erp.production_patterns where id=p_pattern_id for update;
  if v_pattern.id is null then raise exception 'Pattern not found'; end if;
  if v_pattern.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_pattern.row_version; end if;
  if not v_pattern.is_active then raise exception 'Pattern is already inactive'; end if;
  update erp.production_patterns set is_active=false,updated_by=v_actor,updated_at=clock_timestamp()
  where id=v_pattern.id returning * into v_pattern;
  insert into erp.production_pattern_audit(
    entity_type,entity_id,pattern_id,action,old_data,new_data,change_reason,client_request_id,actor_app_user_id
  ) values('PATTERN',v_pattern.id,v_pattern.id,'DEACTIVATE',jsonb_build_object('is_active',true),
    to_jsonb(v_pattern),btrim(p_reason),p_client_request_id,v_actor);
  v_response:=jsonb_build_object('pattern_id',v_pattern.id,'is_active',false,'row_version',v_pattern.row_version);
  return erp._idempotency_complete('deactivate_pattern_v1',p_client_request_id,v_response);
end
$function$;

alter function "erp"."deactivate_pattern_v1"(p_pattern_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.deactivate_role_v1(p_role_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role erp.app_roles%rowtype;v_hash text;v_cached jsonb;v_response jsonb;v_actor uuid:=erp.current_app_user_id();
begin
  perform erp.require_permission('settings.access.manage');
  if nullif(btrim(p_reason),'') is null then raise exception 'reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('role_id',p_role_id,'reason',btrim(p_reason),'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('deactivate_role_v1',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  select * into v_role from erp.app_roles where id=p_role_id for update;
  if v_role.id is null then raise exception 'App role not found'; end if;
  if v_role.is_system or v_role.is_protected then raise exception 'SYSTEM_ROLE_CANNOT_BE_DEACTIVATED'; end if;
  if v_role.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_role.row_version; end if;
  if exists(select 1 from erp.app_users where role_id=v_role.id and is_active) then
    raise exception 'ROLE_HAS_ACTIVE_USERS';
  end if;
  update erp.app_roles set is_active=false,updated_by=v_actor,updated_at=clock_timestamp()
  where id=v_role.id returning * into v_role;
  insert into erp.app_access_audit(entity_type,entity_id,action,old_data,new_data,change_reason,client_request_id,actor_app_user_id)
  values('ROLE',v_role.id,'DEACTIVATE',jsonb_build_object('is_active',true),to_jsonb(v_role),btrim(p_reason),p_client_request_id,v_actor);
  v_response:=jsonb_build_object('role_id',v_role.id,'is_active',false,'row_version',v_role.row_version);
  return erp._idempotency_complete('deactivate_role_v1',p_client_request_id,v_response);
end
$function$;

alter function "erp"."deactivate_role_v1"(p_role_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.edit_product_identity_effective(p_product_id uuid, p_sku text, p_model_id uuid, p_brand_id uuid, p_color_name text, p_size_id uuid, p_product_name text, p_effective_from timestamp with time zone DEFAULT clock_timestamp(), p_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.products%rowtype; v_new uuid; v_used boolean; v_eff timestamptz:=coalesce(p_effective_from,clock_timestamp());
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan perubahan SKU wajib diisi'; end if;
  if nullif(trim(p_sku),'') is null or nullif(trim(p_color_name),'') is null or nullif(trim(p_product_name),'') is null then
    raise exception 'SKU, warna, dan nama produk wajib diisi';
  end if;
  select * into p from erp.products where id=p_product_id for update;
  if p.id is null then raise exception 'SKU tidak ditemukan'; end if;

  if row(p.sku,p.model_id,p.brand_id,p.color_name,p.size_id)
     is not distinct from row(p_sku,p_model_id,p_brand_id,p_color_name,p_size_id) then
    update erp.products set product_name=p_product_name,updated_at=now() where id=p.id;
    insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason,new_data)
    values('products',p.id,'UPDATE',erp.current_app_user_id(),p_reason,jsonb_build_object('product_name',p_product_name));
    return p.id;
  end if;

  select (
    exists(select 1 from erp.fg_lots where product_id=p.id)
    or exists(select 1 from erp.sales_items where product_id=p.id)
    or exists(select 1 from erp.qc_inspection_items where final_product_id=p.id)
    or exists(select 1 from erp.opening_balance_items where product_id=p.id)
    or exists(select 1 from erp.bs_cases where product_id=p.id)
    or exists(select 1 from erp.po_accessory_bom_commitments where product_id=p.id)
    or exists(select 1 from erp.product_conversions where from_product_id=p.id or to_product_id=p.id)
  ) into v_used;

  if not v_used and not exists(select 1 from erp.products x where x.identity_root_id=p.identity_root_id and x.id<>p.id) then
    update erp.products
    set sku=trim(p_sku),model_id=p_model_id,brand_id=p_brand_id,color_name=trim(p_color_name),size_id=p_size_id,
        product_name=trim(p_product_name),updated_at=now()
    where id=p.id;
    insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason,new_data)
    values('products',p.id,'UPDATE',erp.current_app_user_id(),p_reason,
      jsonb_build_object('sku',p_sku,'model_id',p_model_id,'brand_id',p_brand_id,'color_name',p_color_name,'size_id',p_size_id));
    return p.id;
  end if;

  if v_eff<clock_timestamp()-interval '5 minutes' then
    raise exception 'Perubahan identitas SKU yang sudah punya histori hanya boleh berlaku mulai sekarang atau tanggal mendatang';
  end if;
  if v_eff<=p.effective_from or (p.effective_to is not null and v_eff>=p.effective_to) then
    raise exception 'Tanggal mulai perubahan harus berada setelah awal versi lama dan sebelum akhir versinya';
  end if;

  perform set_config('app.product_identity_controlled','on',true);
  update erp.products set effective_to=v_eff,updated_at=now() where id=p.id;
  insert into erp.products(sku,model_id,brand_id,color_name,size_id,product_name,is_portal_visible,is_active,
                           identity_root_id,effective_from,effective_to,supersedes_product_id)
  values(trim(p_sku),p_model_id,p_brand_id,trim(p_color_name),p_size_id,trim(p_product_name),p.is_portal_visible,p.is_active,
         p.identity_root_id,v_eff,p.effective_to,p.id)
  returning id into v_new;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason,new_data)
  values('products',p.id,'UPDATE',erp.current_app_user_id(),p_reason,
    jsonb_build_object('successor_product_id',v_new,'effective_from',v_eff,'old_identity_preserved',true,'economics_shared_by_identity_root',true));
  return v_new;
end;
$function$;

alter function "erp"."edit_product_identity_effective"(p_product_id uuid, p_sku text, p_model_id uuid, p_brand_id uuid, p_color_name text, p_size_id uuid, p_product_name text, p_effective_from timestamp with time zone, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.ensure_fg_accessory_cost_snapshot(p_lot_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE l erp.fg_lots%ROWTYPE;p erp.production_orders%ROWTYPE;v_bom uuid;r record;v_category_avg numeric(18,6);v_hpp_factor numeric(18,6);v_reimburse_factor numeric(18,6);v_hpp_base numeric(18,6);v_reimburse_base numeric(18,6);v_snapshot uuid;v_commit_at timestamptz; BEGIN PERFORM erp.require_internal();SELECT * INTO l FROM erp.fg_lots WHERE id=p_lot_id FOR UPDATE; IF l.id IS NULL OR l.lot_origin<>'PRODUCTION' THEN RETURN; END IF; IF EXISTS (SELECT 1 FROM erp.fg_accessory_cost_snapshots WHERE lot_id=l.id) THEN RETURN; END IF;SELECT * INTO p FROM erp.production_orders WHERE id=l.po_id; IF p.id IS NULL THEN RETURN; END IF;v_bom:=erp.commit_accessory_bom_for_lot(l.id); IF v_bom IS NULL THEN RETURN; END IF;SELECT committed_at INTO v_commit_at FROM erp.po_accessory_bom_commitments WHERE po_id=l.po_id AND product_id=l.product_id; FOR r IN SELECT abi.*,ac.base_uom_code FROM erp.accessory_bom_items abi JOIN erp.accessory_categories ac ON ac.id=abi.category_id WHERE abi.bom_version_id=v_bom ORDER BY ac.category_code LOOP v_category_avg:=erp.accessory_category_weighted_avg_cost_at(r.category_id,l.produced_at); IF r.hpp_method='CATEGORY_MOVING_AVG' THEN IF v_category_avg IS NULL THEN RAISE EXCEPTION 'Cannot snapshot HPP: accessory category % has no moving-average valuation history at %',r.category_id,l.produced_at; END IF;v_hpp_base:=v_category_avg; ELSE v_hpp_factor:=erp.accessory_uom_factor(r.category_id,r.hpp_uom_code,l.produced_at);v_hpp_base:=r.hpp_standard_rate/v_hpp_factor; END IF;v_reimburse_factor:=erp.accessory_uom_factor(r.category_id,r.reimbursement_uom_code,l.produced_at);v_reimburse_base:=r.reimbursement_rate/v_reimburse_factor; INSERT INTO erp.fg_accessory_cost_snapshots(lot_id,po_id,product_id,bom_version_id,bom_item_id,category_id,good_qty_pcs,qty_per_good_fg_base,hpp_method,category_avg_cost_base_snapshot,hpp_unit_cost_base_snapshot,reimbursement_unit_rate_base_snapshot,costing_basis_at,costing_basis_source) VALUES (l.id,l.po_id,l.product_id,v_bom,r.id,r.category_id,l.initial_qty_pcs,r.qty_per_good_fg_base,r.hpp_method,v_category_avg,v_hpp_base,v_reimburse_base,l.produced_at,CASE WHEN v_commit_at=l.produced_at THEN 'FIRST_FINANCIAL_USE' ELSE 'FG_ACCEPTANCE' END) RETURNING id INTO v_snapshot; IF p.contractor_id IS NULL AND v_reimburse_base>0 THEN RAISE EXCEPTION 'PO % has accessory reimbursement BOM but no mandor/contractor',p.po_number; END IF; IF p.contractor_id IS NOT NULL AND v_reimburse_base>0 THEN INSERT INTO erp.contractor_accessory_reimbursement_entitlements(snapshot_id,contractor_id,po_id,lot_id,product_id,category_id,physical_at,amount) SELECT v_snapshot,p.contractor_id,l.po_id,l.id,l.product_id,r.category_id,l.produced_at,total_reimbursement FROM erp.fg_accessory_cost_snapshots WHERE id=v_snapshot; END IF; END LOOP;END; $function$;

alter function "erp"."ensure_fg_accessory_cost_snapshot"(p_lot_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.ensure_po_work_component_snapshots(p_po_id uuid, p_basis_at timestamp with time zone DEFAULT now())
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  p erp.production_orders%rowtype;
  v_bom uuid;
  r record;
  v_rate_id uuid;
  v_rate numeric(18,2);
  v_count integer;
begin
  perform erp.require_internal();
  select * into p from erp.production_orders where id=p_po_id for update;
  if p.id is null then raise exception 'PO not found'; end if;
  if p.contractor_id is null then raise exception 'PO must have a mandor/contractor before work-rate snapshot'; end if;
  select count(*) into v_count from erp.po_work_component_snapshots where po_id=p.id;
  if v_count>0 then return v_count; end if;

  perform pg_advisory_xact_lock(hashtextextended('WBOM:'||p.model_id::text,0));
  select wbv.id into v_bom
  from erp.work_bom_versions wbv
  where wbv.model_id=p.model_id and wbv.is_active=true
    and wbv.effective_from<=p_basis_at and (wbv.effective_to is null or wbv.effective_to>p_basis_at)
    and exists(select 1 from erp.work_bom_items wbi where wbi.bom_version_id=wbv.id)
  order by wbv.effective_from desc,wbv.version_no desc,wbv.id desc limit 1;
  if v_bom is null then raise exception 'No active Work BOM for PO model at %',p_basis_at; end if;

  for r in select * from erp.work_bom_items where bom_version_id=v_bom order by sequence_no,id loop
    v_rate_id:=null; v_rate:=null;
    perform pg_advisory_xact_lock(hashtextextended('WRATE:'||p.contractor_id::text||':'||p.model_id::text||':'||r.work_component_id::text,0));
    select cwr.id,cwr.rate_per_pcs into v_rate_id,v_rate
    from erp.contractor_work_rates cwr
    where cwr.contractor_id=p.contractor_id and cwr.model_id=p.model_id and cwr.work_component_id=r.work_component_id
      and cwr.effective_from<=p_basis_at and (cwr.effective_to is null or cwr.effective_to>p_basis_at)
    order by cwr.effective_from desc,cwr.id desc limit 1;
    v_rate:=coalesce(v_rate,r.default_rate);
    if v_rate is null or v_rate<0 then raise exception 'No valid work rate for component %',r.work_component_id; end if;
    insert into erp.po_work_component_snapshots(
      po_id,work_component_id,source_bom_version_id,source_bom_item_id,source_contractor_rate_id,
      sequence_no,rate_per_pcs_snapshot,committed_at
    ) values(p.id,r.work_component_id,v_bom,r.id,v_rate_id,r.sequence_no,v_rate,p_basis_at);
  end loop;
  select count(*) into v_count from erp.po_work_component_snapshots where po_id=p.id;
  if v_count=0 then raise exception 'Work BOM snapshot produced no components'; end if;
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('production_orders',p.id,'WORK_BOM_COMMIT',jsonb_build_object('bom_version_id',v_bom,'committed_at',p_basis_at,'component_count',v_count),erp.current_app_user_id(),'First work-rate/BOM use');
  return v_count;
end;
$function$;

alter function "erp"."ensure_po_work_component_snapshots"(p_po_id uuid, p_basis_at timestamp with time zone) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.ensure_po_work_component_snapshots_v2(p_po_id uuid, p_basis_at timestamp with time zone, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_count integer;
begin
  perform erp.require_internal();
  if p_basis_at is null or p_basis_at>clock_timestamp()+interval '5 minutes' then
    raise exception 'Valid non-future basis_at is required';
  end if;
  v_hash:=erp._request_hash(jsonb_build_object('po_id',p_po_id,'basis_at',p_basis_at));
  v_cached:=erp._idempotency_begin('ensure_po_work_component_snapshots_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  v_count:=erp.ensure_po_work_component_snapshots(p_po_id,p_basis_at);
  v_response:=jsonb_build_object(
    'po_id',p_po_id,'component_count',v_count,'committed_at',p_basis_at,
    'components',coalesce((
      select jsonb_agg(jsonb_build_object(
        'snapshot_id',s.id,'work_component_id',s.work_component_id,
        'sequence_no',s.sequence_no,'rate_per_pcs_snapshot',s.rate_per_pcs_snapshot
      ) order by s.sequence_no,s.id)
      from erp.po_work_component_snapshots s where s.po_id=p_po_id
    ),'[]'::jsonb)
  );
  return erp._idempotency_complete('ensure_po_work_component_snapshots_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."ensure_po_work_component_snapshots_v2"(p_po_id uuid, p_basis_at timestamp with time zone, p_client_request_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.finalize_material_purchase_invoice_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_purchase uuid:=nullif(p_payload->>'purchase_id','')::uuid;
  ph erp.material_purchase_headers%rowtype;
  ih erp.material_supplier_invoices%rowtype;
  j jsonb;i erp.material_purchase_items%rowtype;
  v_qty numeric;v_remaining numeric;v_state text;
begin
  perform erp.require_owner_admin();
  if v_purchase is null then raise exception 'purchase_id is required'; end if;
  if nullif(btrim(p_payload->>'supplier_invoice_number'),'') is null then raise exception 'supplier_invoice_number is required'; end if;
  if nullif(p_payload->>'invoice_date','') is null then raise exception 'invoice_date is required'; end if;
  if nullif(btrim(p_payload->>'reason'),'') is null then raise exception 'reason is required'; end if;
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if coalesce(jsonb_typeof(p_payload->'lines'),'null')<>'array'
     or jsonb_array_length(p_payload->'lines')=0 then raise exception 'At least one final invoice line is required'; end if;

  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('finalize_material_purchase_invoice_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',btrim(p_payload->>'reason'),true);

  select * into ph from erp.material_purchase_headers where id=v_purchase for update;
  if ph.id is null or ph.status<>'POSTED' then raise exception 'Purchase must be POSTED'; end if;
  if ph.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,ph.row_version; end if;
  if ph.supplier_id is null then raise exception 'Purchase supplier is required'; end if;

  insert into erp.material_supplier_invoices(
    invoice_number,supplier_id,invoice_date,received_at,due_date,notes,posting_reason,created_by
  ) values(
    btrim(p_payload->>'supplier_invoice_number'),ph.supplier_id,(p_payload->>'invoice_date')::date,
    coalesce(nullif(p_payload->>'received_at','')::timestamptz,clock_timestamp()),
    nullif(p_payload->>'due_date','')::date,nullif(btrim(p_payload->>'notes'),''),
    btrim(p_payload->>'reason'),erp.current_app_user_id()
  ) returning * into ih;

  for j in select value from jsonb_array_elements(p_payload->'lines') loop
    select * into i from erp.material_purchase_items
    where id=(j->>'purchase_item_id')::uuid and purchase_id=ph.id for update;
    if i.id is null then raise exception 'Final invoice line does not belong to purchase'; end if;
    v_remaining:=erp.material_purchase_invoice_capacity(i.id)-erp.material_purchase_posted_invoice_qty(i.id);
    v_qty:=coalesce(nullif(j->>'qty_invoiced','')::numeric,v_remaining);
    if v_qty<=0 then raise exception 'No unmatched quantity remains for purchase item %',i.id; end if;
    insert into erp.material_supplier_invoice_lines(
      invoice_id,purchase_item_id,qty_invoiced,unit_price,discount_amount,notes
    ) values(
      ih.id,i.id,v_qty,(j->>'final_unit_price')::numeric,
      coalesce(nullif(j->>'discount_amount','')::numeric,0),nullif(btrim(j->>'notes'),'')
    );
  end loop;

  perform erp.post_material_supplier_invoice(ih.id);
  select case when bool_and(mi.price_state='FINAL') then 'FINAL' else 'PARTIAL' end
  into v_state
  from erp.material_supplier_invoice_lines l
  join erp.material_purchase_items mi on mi.id=l.purchase_item_id
  where l.invoice_id=ih.id;
  select * into ph from erp.material_purchase_headers where id=ph.id;
  v_response:=jsonb_build_object(
    'purchase_id',ph.id,'correction_id',ih.id,'supplier_invoice_id',ih.id,
    'supplier_invoice_number',ih.invoice_number,'price_state',v_state,
    'row_version',ph.row_version
  );
  return erp._idempotency_complete('finalize_material_purchase_invoice_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."finalize_material_purchase_invoice_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.finalize_migration_batch(p_batch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare v_opening uuid;v_status text;
begin
  perform erp.require_owner_admin();select status into v_status from erp.migration_batches where id=p_batch_id for update;if v_status not in('READY','POSTING') then raise exception 'Migration batch must be READY/POSTING';end if;
  if exists(select 1 from erp.migration_staging_rows where batch_id=p_batch_id and validation_status<>'VALID') then raise exception 'Migration batch has validation errors';end if;
  if exists(select 1 from erp.migration_staging_rows where batch_id=p_batch_id and entity_type in('BRAND','SIZE','MODEL','PRODUCT','CUSTOMER','SUPPLIER','CONTRACTOR','ACCESSORY_CATEGORY','MATERIAL','MATERIAL_ROLL','OPEN_PO') and posted_entity_id is null) then raise exception 'Migration batch still has unapplied master/roll/open-PO rows';end if;
  select id into v_opening from erp.opening_balance_headers where migration_batch_id=p_batch_id order by created_at limit 1;
  if exists(select 1 from erp.migration_staging_rows where batch_id=p_batch_id and entity_type in('OPENING_BALANCE_ITEM','MATERIAL_ROLL')) then
    if v_opening is null then raise exception 'Opening stock/balance rows exist but opening document was not prepared';end if;
    if (select status from erp.opening_balance_headers where id=v_opening)<>'POSTED' then raise exception 'Migration opening balance must be POSTED before finalizing batch';end if;
  end if;
  update erp.migration_batches set status='POSTED',posted_at=now(),error_message=null where id=p_batch_id;
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason) values('migration_batches',p_batch_id,'POST',jsonb_build_object('status','POSTED'),erp.current_app_user_id(),'Finalize migration batch');
end;$function$;

alter function "erp"."finalize_migration_batch"(p_batch_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.finish_production_order(p_po_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_status text;
  v_sent bigint;
  v_returned bigint;
  v_claimed bigint;
  v_laundry_good bigint;
  v_qc_accounted bigint;
  v_fg_good bigint;
  v_open_bs bigint;
begin
  perform erp.require_internal();
  select status into v_status from erp.production_orders where id=p_po_id for update;
  if v_status is null then raise exception 'PO not found'; end if;
  if v_status='FINISHED' then return; end if;
  if v_status='CANCELLED' then raise exception 'Cancelled PO cannot be finished'; end if;

  select coalesce(sum(ldl.qty_sent_pcs),0) into v_sent
  from erp.laundry_delivery_lines ldl join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
  where ld.po_id=p_po_id and ld.status not in ('DRAFT','REVERSED');
  select coalesce(sum(lrl.qty_good_received+lrl.qty_bs_laundry),0) into v_returned
  from erp.laundry_receipt_lines lrl join erp.laundry_receipts lr on lr.id=lrl.receipt_id join erp.laundry_deliveries ld on ld.id=lr.delivery_id
  where ld.po_id=p_po_id and lr.status='POSTED' and ld.status<>'REVERSED';
  select coalesce(sum(lc.qty_claimed),0) into v_claimed
  from erp.laundry_claims lc
  where lc.delivery_id in (select id from erp.laundry_deliveries where po_id=p_po_id)
    and lc.claim_type in ('MISSING','STUCK') and lc.status in ('SETTLED','WRITTEN_OFF');
  if v_returned+v_claimed<v_sent then raise exception 'PO still has unresolved laundry outstanding qty %',v_sent-v_returned-v_claimed; end if;

  if v_sent>0 then
    select coalesce(sum(lrl.qty_good_received),0) into v_laundry_good
    from erp.laundry_receipt_lines lrl join erp.laundry_receipts lr on lr.id=lrl.receipt_id join erp.laundry_deliveries ld on ld.id=lr.delivery_id
    where ld.po_id=p_po_id and lr.status='POSTED';
    select coalesce(sum(qii.qty_good_pcs+qii.qty_bs_pcs),0) into v_qc_accounted
    from erp.qc_inspection_items qii join erp.qc_inspections qi on qi.id=qii.inspection_id
    where qi.po_id=p_po_id and qi.status='POSTED' and qii.source_laundry_receipt_line_id is not null;
    if v_qc_accounted<v_laundry_good then raise exception 'PO still has laundry GOOD pieces not yet accounted by QC: %',v_laundry_good-v_qc_accounted; end if;
  end if;

  select count(*) into v_open_bs from erp.bs_cases where po_id=p_po_id and status in ('OPEN','IN_REWORK','PARTIAL');
  if v_open_bs>0 then raise exception 'PO still has % unresolved BS case(s)',v_open_bs; end if;

  select coalesce(sum(initial_qty_pcs),0) into v_fg_good from erp.fg_lots where po_id=p_po_id and lot_origin='PRODUCTION';
  if v_fg_good<=0 then raise exception 'PO cannot finish without finished-goods output'; end if;

  perform erp.rebuild_po_hpp(p_po_id,'Final production close HPP rebuild');
  perform erp.propagate_conversion_hpp_for_po(p_po_id);
  perform erp.sync_po_hpp_to_gl(p_po_id,current_date);
  update erp.production_orders set status='FINISHED',current_stage='FINISHED',updated_at=now() where id=p_po_id;
  perform erp.sync_finished_po_wip_residual(p_po_id,current_date,'Production order final residual WIP close');
end;
$function$;

alter function "erp"."finish_production_order"(p_po_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.get_access_admin_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform erp.require_permission('settings.access.view');
  return jsonb_build_object(
    'permissions',(
      select coalesce(jsonb_agg(jsonb_build_object(
        'key',p.permission_key,'module_key',p.module_key,'module_label',p.module_label,
        'action',p.action_key,'action_label',p.action_label,'description',p.description,
        'high_risk',p.high_risk,'sort_order',p.sort_order
      ) order by p.sort_order,p.permission_key),'[]'::jsonb)
      from erp.app_permissions p where p.is_active
    ),
    'roles',(
      select coalesce(jsonb_agg(jsonb_build_object(
        'id',r.id,'code',r.role_code,'name',r.role_name,'description',r.description,
        'is_system',r.is_system,'is_protected',r.is_protected,'is_active',r.is_active,
        'row_version',r.row_version,'active_user_count',(
          select count(*) from erp.app_users u where u.role_id=r.id and u.is_active
        ),
        'permissions',erp.role_permission_keys(r.id),
        'updated_at',r.updated_at,'updated_by',ub.full_name
      ) order by case when r.role_code='OWNER' then 0 when r.is_system then 1 else 2 end,r.role_name,r.id),'[]'::jsonb)
      from erp.app_roles r left join erp.app_users ub on ub.id=r.updated_by
    ),
    'users',(
      select coalesce(jsonb_agg(jsonb_build_object(
        'id',u.id,'auth_user_id',u.auth_user_id,'full_name',u.full_name,
        'role_id',r.id,'role_code',r.role_code,'role_name',r.role_name,
        'is_active',u.is_active,'mapped',u.auth_user_id is not null,
        'row_version',u.row_version,'last_sign_in_at',au.last_sign_in_at
      ) order by u.full_name,u.id),'[]'::jsonb)
      from erp.app_users u join erp.app_roles r on r.id=u.role_id
      left join auth.users au on au.id=u.auth_user_id
    ),
    'audit',(
      select coalesce(jsonb_agg(jsonb_build_object(
        'id',a.id,'entity_type',a.entity_type,'entity_id',a.entity_id,'action',a.action,
        'old_data',a.old_data,'new_data',a.new_data,'change_reason',a.change_reason,
        'changed_at',a.changed_at,'changed_by',u.full_name
      ) order by a.changed_at desc,a.id desc),'[]'::jsonb)
      from (select * from erp.app_access_audit order by changed_at desc,id desc limit 100) a
      left join erp.app_users u on u.id=a.actor_app_user_id
    )
  );
end
$function$;

alter function "erp"."get_access_admin_v1"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.get_accessory_economics(p_from date, p_to date)
 RETURNS TABLE(metric text, amount numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_sales numeric(24,6);v_actual_cost numeric(24,6);v_reimburse numeric(24,6);v_hpp_basis numeric(24,6); BEGIN PERFORM erp.require_owner_admin();SELECT COALESCE(SUM(cmii.total_receivable),0),COALESCE(SUM(cmii.qty*cmii.unit_cost_snapshot),0) INTO v_sales,v_actual_cost FROM erp.contractor_material_issue_items cmii JOIN erp.contractor_material_issues cmi ON cmi.id=cmii.issue_id JOIN erp.materials m ON m.id=cmii.material_id WHERE cmi.status='POSTED' AND m.material_type='ACCESSORY' AND cmi.physical_at::date BETWEEN p_from AND p_to;SELECT COALESCE(SUM(e.amount),0) INTO v_reimburse FROM erp.contractor_accessory_reimbursement_entitlements e WHERE e.physical_at::date BETWEEN p_from AND p_to;SELECT COALESCE(SUM(s.total_hpp_cost),0) INTO v_hpp_basis FROM erp.fg_accessory_cost_snapshots s JOIN erp.fg_lots fl ON fl.id=s.lot_id WHERE fl.produced_at::date BETWEEN p_from AND p_to;RETURN QUERY VALUES ('MANDOR_ACCESSORY_CHARGE'::text,round(v_sales,2)),('ACTUAL_ACCESSORY_INVENTORY_COST'::text,round(v_actual_cost,2)),('GOOD_FG_REIMBURSEMENT'::text,round(v_reimburse,2)),('ACCESSORY_HPP_BASIS'::text,round(v_hpp_basis,2)),('REIMBURSEMENT_MINUS_HPP_VARIANCE'::text,round(v_reimburse-v_hpp_basis,2)),('NET_ECONOMIC_ACCESSORY_COST'::text,round(v_actual_cost+v_reimburse-v_sales,2)); END; $function$;

alter function "erp"."get_accessory_economics"(p_from date, p_to date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.get_balance_sheet(p_as_of date)
 RETURNS TABLE(account_type character varying, report_group character varying, account_code character varying, account_name character varying, amount numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_catalog', 'pg_temp'
AS $function$
begin
  perform erp.require_internal();
  if p_as_of is null then raise exception 'p_as_of is required'; end if;

  return query
  with bs as(
    select
      ca.account_type,ca.report_group,ca.account_code,ca.account_name,
      case when ca.normal_balance='CREDIT'
           then sum(adb.credit_total-adb.debit_total)
           else sum(adb.debit_total-adb.credit_total) end::numeric amount
    from erp.account_daily_balances adb
    join erp.chart_accounts ca on ca.id=adb.account_id
    where adb.balance_date<=p_as_of
      and ca.account_type in('ASSET','LIABILITY','EQUITY')
    group by ca.account_type,ca.report_group,ca.account_code,ca.account_name,ca.normal_balance
  ), current_earnings as(
    select coalesce(sum(adb.credit_total-adb.debit_total),0)::numeric amount
    from erp.account_daily_balances adb
    join erp.chart_accounts ca on ca.id=adb.account_id
    where adb.balance_date<=p_as_of
      and ca.account_type in('REVENUE','EXPENSE')
  )
  select x.account_type,x.report_group,x.account_code,x.account_name,x.amount
  from(
    select b.account_type,b.report_group,b.account_code,b.account_name,b.amount from bs b
    union all
    select 'EQUITY'::varchar,'CURRENT_EARNINGS'::varchar,'3999-CURRENT'::varchar,
           'Laba (Rugi) Berjalan / Current Earnings'::varchar,c.amount
    from current_earnings c
  ) x
  order by
    case x.account_type when 'ASSET' then 1 when 'LIABILITY' then 2 else 3 end,
    x.account_code;
end;
$function$;

alter function "erp"."get_balance_sheet"(p_as_of date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.get_fg_partial_completion_context(p_cutting_group_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_group erp.cutting_groups%rowtype;
  v_progress jsonb;
  v_sizes jsonb;
  v_unassigned_adjustment bigint;
begin
  perform erp.require_internal();

  select * into v_group
  from erp.cutting_groups
  where id = p_cutting_group_id;
  if v_group.id is null then
    raise exception 'Potongan not found';
  end if;

  select to_jsonb(p) into v_progress
  from erp.v_fg_partial_completion_progress p
  where p.cutting_group_id = v_group.id;

  with original as (
    select s.size_id, sum(y.qty_pcs)::bigint as qty_pcs
    from erp.cutting_group_size_slots s
    left join erp.cutting_roll_yields y on y.size_slot_id = s.id
    where s.cutting_group_id = v_group.id
    group by s.size_id
  ), adjustment as (
    select s.size_id, sum(l.qty_delta_pcs)::bigint as qty_pcs
    from erp.cutting_qty_correction_lines l
    join erp.cutting_group_size_slots s on s.id = l.size_slot_id
    where l.cutting_group_id = v_group.id
    group by s.size_id
  ), posted as (
    select pr.size_id,
      sum(i.qty_good_pcs)::bigint as good_qty_pcs,
      sum(i.qty_bs_pcs)::bigint as bs_qty_pcs
    from erp.qc_inspection_items i
    join erp.qc_inspections q on q.id = i.inspection_id and q.status = 'POSTED'
    join erp.products pr on pr.id = i.final_product_id
    where i.cutting_group_id = v_group.id
    group by pr.size_id
  ), size_ids as (
    select size_id from original
    union select size_id from adjustment
    union select size_id from posted
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'size_id', z.size_id,
    'size_code', sz.size_code,
    'target_qty_pcs', coalesce(o.qty_pcs, 0) + coalesce(a.qty_pcs, 0),
    'good_qty_pcs', coalesce(p.good_qty_pcs, 0),
    'bs_qty_pcs', coalesce(p.bs_qty_pcs, 0),
    'remaining_qty_pcs', greatest(
      coalesce(o.qty_pcs, 0) + coalesce(a.qty_pcs, 0)
        - coalesce(p.good_qty_pcs, 0) - coalesce(p.bs_qty_pcs, 0),
      0
    ),
    'suggested_product_id', (
      select pr.id
      from erp.products pr
      join erp.production_orders po on po.model_id = pr.model_id
      where po.id = v_group.po_id
        and pr.size_id = z.size_id
        and pr.is_active = true
        and pr.effective_from <= clock_timestamp()
        and (pr.effective_to is null or pr.effective_to > clock_timestamp())
      order by pr.effective_from desc, pr.created_at desc, pr.id desc
      limit 1
    )
  ) order by sz.sort_order, sz.size_code), '[]'::jsonb)
  into v_sizes
  from size_ids z
  join erp.sizes sz on sz.id = z.size_id
  left join original o on o.size_id = z.size_id
  left join adjustment a on a.size_id = z.size_id
  left join posted p on p.size_id = z.size_id;

  select coalesce(sum(l.qty_delta_pcs), 0)::bigint
  into v_unassigned_adjustment
  from erp.cutting_qty_correction_lines l
  where l.cutting_group_id = v_group.id
    and l.size_slot_id is null;

  return jsonb_build_object(
    'cutting_group_id', v_group.id,
    'po_id', v_group.po_id,
    'group_number', v_group.group_number,
    'row_version', v_group.row_version,
    'progress', coalesce(v_progress, '{}'::jsonb),
    'sizes', coalesce(v_sizes, '[]'::jsonb),
    'unassigned_adjustment_qty_pcs', v_unassigned_adjustment
  );
end;
$function$;

alter function "erp"."get_fg_partial_completion_context"(p_cutting_group_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.get_my_access_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_auth_user_id uuid:=auth.uid();v_user erp.app_users%rowtype;v_role erp.app_roles%rowtype;
begin
  if v_auth_user_id is null then
    return jsonb_build_object('allowed',false,'reason','AUTH_REQUIRED');
  end if;
  select * into v_user from erp.app_users where auth_user_id=v_auth_user_id limit 1;
  if v_user.id is null then
    return jsonb_build_object('allowed',false,'reason','APP_USER_NOT_FOUND');
  end if;
  if not v_user.is_active then
    return jsonb_build_object('allowed',false,'reason','APP_USER_INACTIVE');
  end if;
  select * into v_role from erp.app_roles where id=v_user.role_id;
  if v_role.id is null then
    return jsonb_build_object('allowed',false,'reason','APP_ROLE_NOT_FOUND');
  end if;
  if not v_role.is_active then
    return jsonb_build_object('allowed',false,'reason','APP_ROLE_INACTIVE');
  end if;
  return jsonb_build_object(
    'allowed',true,
    'profile',jsonb_build_object(
      'id',v_user.id,'auth_user_id',v_user.auth_user_id,'full_name',v_user.full_name,
      'role_id',v_role.id,'role_code',v_role.role_code,'role_name',v_role.role_name,
      'is_active',v_user.is_active,'row_version',v_user.row_version,
      'role_row_version',v_role.row_version
    ),
    'permissions',erp.role_permission_keys(v_role.id),
    'external_portals',jsonb_build_object('mandor','NOT CONNECTED','laundry','NOT CONNECTED','store','NOT CONNECTED')
  );
end
$function$;

alter function "erp"."get_my_access_v1"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.get_owner_financial_snapshot_v2(p_from date, p_to date, p_as_of date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_assets numeric:=0;v_liabilities numeric:=0;v_equity numeric:=0;v_current_earnings numeric:=0;
  v_cash numeric:=0;v_ar numeric:=0;v_material numeric:=0;v_wip numeric:=0;v_fg numeric:=0;
  v_ap numeric:=0;v_grni numeric:=0;
  v_sales_revenue numeric:=0;v_cogs numeric:=0;v_other_income numeric:=0;v_opex numeric:=0;v_net_profit numeric:=0;
  v_gross_sales numeric:=0;v_discounts numeric:=0;v_sales_returns numeric:=0;
  v_qc_good numeric:=0;v_qc_bs numeric:=0;
  v_laundry_good numeric:=0;v_laundry_bs numeric:=0;v_laundry_stuck numeric:=0;v_laundry_missing numeric:=0;
  v_grni_docs bigint:=0;v_grni_oldest integer:=0;v_ap_docs bigint:=0;v_ap_overdue numeric:=0;
  v_critical bigint:=0;v_warning bigint:=0;v_pending bigint:=0;
begin
  perform erp.require_owner_admin();
  if p_from is null or p_to is null or p_as_of is null then raise exception 'p_from, p_to and p_as_of are required'; end if;
  if p_from>p_to then raise exception 'p_from cannot be after p_to'; end if;
  if p_to>p_as_of then raise exception 'p_to cannot be after p_as_of'; end if;

  select
    coalesce(sum(case when ca.account_type='ASSET' then a.debit_total-a.credit_total else 0 end),0),
    coalesce(sum(case when ca.account_type='LIABILITY' then a.credit_total-a.debit_total else 0 end),0),
    coalesce(sum(case when ca.account_type='EQUITY' then a.credit_total-a.debit_total else 0 end),0),
    coalesce(sum(case when ca.account_type in('REVENUE','EXPENSE') then a.credit_total-a.debit_total else 0 end),0)
  into v_assets,v_liabilities,v_equity,v_current_earnings
  from erp.account_daily_balances a join erp.chart_accounts ca on ca.id=a.account_id
  where a.balance_date<=p_as_of;

  select coalesce(sum(a.debit_total-a.credit_total),0) into v_cash
  from erp.account_daily_balances a
  where a.balance_date<=p_as_of and a.account_id in(
    select ca.coa_account_id from erp.cash_accounts ca
    union select erp.account_id('CASH')
  );
  select coalesce(sum(a.debit_total-a.credit_total),0) into v_ar from erp.account_daily_balances a where a.balance_date<=p_as_of and a.account_id=erp.account_id('AR_CUSTOMER');
  select coalesce(sum(a.debit_total-a.credit_total),0) into v_material from erp.account_daily_balances a where a.balance_date<=p_as_of and a.account_id=erp.account_id('MATERIAL_INVENTORY');
  select coalesce(sum(a.debit_total-a.credit_total),0) into v_wip from erp.account_daily_balances a where a.balance_date<=p_as_of and a.account_id=erp.account_id('WIP');
  select coalesce(sum(a.debit_total-a.credit_total),0) into v_fg from erp.account_daily_balances a where a.balance_date<=p_as_of and a.account_id=erp.account_id('FG_INVENTORY');
  select coalesce(sum(a.credit_total-a.debit_total),0) into v_ap from erp.account_daily_balances a where a.balance_date<=p_as_of and a.account_id=erp.account_id('AP_SUPPLIER');
  select coalesce(sum(a.credit_total-a.debit_total),0) into v_grni from erp.account_daily_balances a where a.balance_date<=p_as_of and a.account_id=erp.account_id('GRNI_MATERIAL');

  select
    coalesce(sum(case when a.account_id=erp.account_id('SALES_REVENUE') then a.credit_total-a.debit_total else 0 end),0),
    coalesce(sum(case when a.account_id=erp.account_id('COGS') then a.debit_total-a.credit_total else 0 end),0),
    coalesce(sum(case when ca.account_type='REVENUE' and a.account_id<>erp.account_id('SALES_REVENUE') then a.credit_total-a.debit_total else 0 end),0),
    coalesce(sum(case when ca.account_type='EXPENSE' and a.account_id<>erp.account_id('COGS') then a.debit_total-a.credit_total else 0 end),0),
    coalesce(sum(case when ca.account_type in('REVENUE','EXPENSE') then a.credit_total-a.debit_total else 0 end),0)
  into v_sales_revenue,v_cogs,v_other_income,v_opex,v_net_profit
  from erp.account_daily_balances a join erp.chart_accounts ca on ca.id=a.account_id
  where a.balance_date between p_from and p_to;

  select coalesce(sum(i.qty_pcs*i.unit_price_snapshot),0),coalesce(sum(i.discount_amount),0)
  into v_gross_sales,v_discounts
  from erp.sales_items i join erp.sales_headers h on h.id=i.sale_id
  where h.status in('POSTED','PARTIAL_PAID','PAID') and h.sale_date::date between p_from and p_to;
  select coalesce(sum(i.refund_amount),0) into v_sales_returns
  from erp.sales_return_items i join erp.sales_returns h on h.id=i.return_id
  where h.status='POSTED' and h.physical_at::date between p_from and p_to;

  select coalesce(sum(i.qty_good_pcs),0),coalesce(sum(i.qty_bs_pcs),0)
  into v_qc_good,v_qc_bs
  from erp.qc_inspection_items i join erp.qc_inspections h on h.id=i.inspection_id
  where h.status='POSTED' and h.physical_at::date between p_from and p_to;
  select coalesce(sum(i.qty_good_received),0),coalesce(sum(i.qty_bs_laundry),0),
         coalesce(sum(i.qty_stuck),0),coalesce(sum(i.qty_missing),0)
  into v_laundry_good,v_laundry_bs,v_laundry_stuck,v_laundry_missing
  from erp.laundry_receipt_lines i join erp.laundry_receipts h on h.id=i.receipt_id
  where h.status='POSTED' and h.physical_at::date between p_from and p_to;

  select count(*)::bigint,coalesce(max(unfinalized_days),0)::integer
  into v_grni_docs,v_grni_oldest from erp.v_material_grni_aging;
  select count(*)::bigint,coalesce(sum(case when days_overdue>0 then outstanding_amount else 0 end),0)
  into v_ap_docs,v_ap_overdue from erp.v_supplier_ap_aging where outstanding_amount>0.005;

  select coalesce(sum(issue_count) filter(where severity='CRITICAL'),0)::bigint,
         coalesce(sum(issue_count) filter(where severity='WARNING'),0)::bigint
  into v_critical,v_warning from erp.run_v268_financial_report_checks();
  select count(*)::bigint into v_pending from erp.cost_recalc_queue
  where status in('PENDING','RUNNING') or(status='FAILED' and attempt_count<3);

  return jsonb_build_object(
    'basis',jsonb_build_object(
      'period_from',p_from,'period_to',p_to,'balance_sheet_as_of',p_as_of,
      'supplier_exposure_basis','CURRENT_OPERATIONAL_STATE'
    ),
    'data_confidence',jsonb_build_object(
      'status',case when v_critical>0 then 'BLOCKED'
                    when v_pending>0 then 'RECALC_PENDING' else 'READY' end,
      'critical_issue_count',v_critical,'warning_issue_count',v_warning,
      'pending_cost_recalc_count',v_pending
    ),
    'financial_position',jsonb_build_object(
      'assets',round(v_assets,2),'cash',round(v_cash,2),'customer_ar',round(v_ar,2),
      'material_inventory',round(v_material,2),'wip_inventory',round(v_wip,2),'fg_inventory',round(v_fg,2),
      'liabilities',round(v_liabilities,2),'supplier_final_ap',round(v_ap,2),
      'grni_estimated_liability',round(v_grni,2),'recorded_equity',round(v_equity,2),
      'current_earnings',round(v_current_earnings,2),
      'liabilities_plus_equity',round(v_liabilities+v_equity+v_current_earnings,2),
      'balance_difference',round(v_assets-v_liabilities-v_equity-v_current_earnings,2)
    ),
    'performance',jsonb_build_object(
      'sales_revenue_gl',round(v_sales_revenue,2),'cogs_gl',round(v_cogs,2),
      'gross_profit',round(v_sales_revenue-v_cogs,2),
      'gross_margin_pct',case when abs(v_sales_revenue)>0.005 then round((v_sales_revenue-v_cogs)*100/v_sales_revenue,4) else null end,
      'other_income',round(v_other_income,2),'operating_and_other_expense',round(v_opex,2),
      'net_profit',round(v_net_profit,2),
      'net_margin_pct',case when abs(v_sales_revenue)>0.005 then round(v_net_profit*100/v_sales_revenue,4) else null end,
      'gross_sales_before_discount',round(v_gross_sales,2),'line_discounts',round(v_discounts,2),
      'posted_sales_returns',round(v_sales_returns,2),
      'operational_net_sales',round(v_gross_sales-v_discounts-v_sales_returns,2)
    ),
    'quality',jsonb_build_object(
      'qc_good_pcs',v_qc_good,'qc_bs_pcs',v_qc_bs,
      'qc_defect_rate_pct',case when v_qc_good+v_qc_bs>0 then round(v_qc_bs*100/(v_qc_good+v_qc_bs),4) else null end,
      'laundry_good_received_pcs',v_laundry_good,'laundry_bs_pcs',v_laundry_bs,
      'laundry_bs_rate_on_resolved_receipts_pct',case when v_laundry_good+v_laundry_bs>0 then round(v_laundry_bs*100/(v_laundry_good+v_laundry_bs),4) else null end,
      'laundry_stuck_pcs',v_laundry_stuck,'laundry_missing_pcs',v_laundry_missing
    ),
    'supplier_exposure',jsonb_build_object(
      'unfinalized_receipt_count',v_grni_docs,'oldest_unfinalized_days',v_grni_oldest,
      'open_final_ap_document_count',v_ap_docs,'overdue_final_ap_amount',round(v_ap_overdue,2)
    )
  );
end;
$function$;

alter function "erp"."get_owner_financial_snapshot_v2"(p_from date, p_to date, p_as_of date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.get_wip_control_v1(p_filter text DEFAULT 'ACTIVE'::text, p_pattern_id uuid DEFAULT NULL::uuid, p_sort text DEFAULT 'PATTERN'::text, p_query text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_filter text:=upper(coalesce(nullif(btrim(p_filter),''),'ACTIVE'));
  v_sort text:=upper(coalesce(nullif(btrim(p_sort),''),'PATTERN'));v_query text:=lower(nullif(btrim(p_query),''));
begin
  perform erp.require_permission('production.wip.view');
  if v_filter not in ('ACTIVE','COMPLETED','ALL') then raise exception 'filter must be ACTIVE, COMPLETED, or ALL'; end if;
  if v_sort not in ('PATTERN','PRODUCTION','UPDATED') then raise exception 'sort must be PATTERN, PRODUCTION, or UPDATED'; end if;
  return jsonb_build_object(
    'filter',v_filter,'sort',v_sort,'pattern_id',p_pattern_id,
    'rows',coalesce((
      select jsonb_agg(to_jsonb(w) order by
        case when v_sort='PATTERN' then coalesce(w.pattern_sort_order,2147483647) end,
        case when v_sort='PATTERN' then coalesce(w.pattern_code,'~') end,
        case when v_sort='UPDATED' then w.updated_at end desc,
        w.po_number,w.group_number,w.cutting_group_id
      )
      from erp.v_wip_control_status_v1 w
      where (v_filter='ALL' or w.control_status=v_filter)
        and (p_pattern_id is null or w.pattern_id=p_pattern_id)
        and (v_query is null or lower(concat_ws(' ',w.po_number,w.group_number,w.model_code,w.model_name,
          w.pattern_code,w.pattern_name,w.executor_name,w.group_status,w.notes)) like '%'||v_query||'%')
    ),'[]'::jsonb)
  );
end
$function$;

alter function "erp"."get_wip_control_v1"(p_filter text, p_pattern_id uuid, p_sort text, p_query text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_access_catalog_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if session_user in ('postgres','supabase_admin')
     and current_setting('erp.cp45_allow_synthetic_cleanup',true)='on' then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  raise exception using errcode='42501',message='ACCESS_AUDIT_IS_IMMUTABLE';
end
$function$;

alter function "erp"."guard_access_catalog_immutability"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_accessory_bom_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended('ABOM:'||new.product_id::text,0));
  if new.is_active and exists(
    select 1 from erp.accessory_bom_versions x
    where x.product_id=new.product_id and x.id<>new.id and x.is_active
      and x.effective_from<coalesce(new.effective_to,'infinity'::timestamptz)
      and coalesce(x.effective_to,'infinity'::timestamptz)>new.effective_from
  ) then raise exception 'Overlapping active accessory BOM effective range for SKU'; end if;
  return new;
end$function$;

alter function "erp"."guard_accessory_bom_overlap"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_accessory_category_base_uom()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ BEGIN IF NEW.base_uom_code IS DISTINCT FROM OLD.base_uom_code AND EXISTS (SELECT 1 FROM erp.materials WHERE accessory_category_id=OLD.id LIMIT 1) THEN RAISE EXCEPTION 'Accessory category base UOM is frozen after material variants exist; create a new category instead'; END IF;RETURN NEW;END; $function$;

alter function "erp"."guard_accessory_category_base_uom"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_accessory_uom_conversion_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Accessory UOM conversion cannot be deleted; close effective_to and create a successor if needed'; END IF; IF NEW.category_id IS DISTINCT FROM OLD.category_id OR NEW.uom_code IS DISTINCT FROM OLD.uom_code OR NEW.base_qty_per_uom IS DISTINCT FROM OLD.base_qty_per_uom OR NEW.effective_from IS DISTINCT FROM OLD.effective_from THEN RAISE EXCEPTION 'Accessory UOM conversion economics are immutable; close effective_to and create a successor'; END IF;RETURN NEW;END; $function$;

alter function "erp"."guard_accessory_uom_conversion_history"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_accessory_uom_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ BEGIN IF EXISTS (SELECT 1 FROM erp.accessory_category_uom_conversions x WHERE x.category_id=NEW.category_id AND x.uom_code=NEW.uom_code AND x.id<>NEW.id AND x.effective_from<COALESCE(NEW.effective_to,'infinity'::timestamptz) AND COALESCE(x.effective_to,'infinity'::timestamptz)>NEW.effective_from) THEN RAISE EXCEPTION 'Overlapping accessory category UOM conversion effective range'; END IF;RETURN NEW;END; $function$;

alter function "erp"."guard_accessory_uom_overlap"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_accounting_mapping_semantics()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_expected text;v_type text;v_active boolean;
begin
  if tg_op='DELETE' then
    v_expected:=erp.expected_mapping_account_type(old.mapping_key);
    if v_expected is not null then raise exception 'Core accounting mapping % tidak boleh dihapus. Pindahkan ke akun aktif dengan tipe % jika perlu.',old.mapping_key,v_expected; end if;
    return old;
  end if;
  if tg_op='UPDATE' and new.mapping_key is distinct from old.mapping_key and erp.expected_mapping_account_type(old.mapping_key) is not null then
    raise exception 'Core accounting mapping key % tidak boleh di-rename',old.mapping_key;
  end if;
  v_expected:=erp.expected_mapping_account_type(new.mapping_key);
  select account_type,is_active into v_type,v_active from erp.chart_accounts where id=new.account_id;
  if v_type is null then raise exception 'Mapped chart account tidak ditemukan'; end if;
  if not coalesce(v_active,false) then raise exception 'Accounting mapping % harus memakai chart account aktif',new.mapping_key; end if;
  if v_expected is not null and v_type<>v_expected then raise exception 'Accounting mapping % wajib memakai account type %, bukan %',new.mapping_key,v_expected,v_type; end if;
  return new;
end;
$function$;

alter function "erp"."guard_accounting_mapping_semantics"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_attendance_after_payroll_use()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_payroll text;
begin
  if current_user in ('postgres','service_role','supabase_admin') then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  select ps.payroll_number into v_payroll
  from erp.payroll_attendance_items pai
  join erp.payroll_settlements ps on ps.id=pai.payroll_id
  where pai.attendance_record_id=old.id and ps.status<>'REVERSED'
  order by ps.created_at desc,ps.id desc limit 1;
  if v_payroll is not null then
    raise exception 'Absensi ini sudah dipakai di payroll %. Cancel/reverse payroll tersebut dulu, koreksi absensi, lalu rebuild payroll.',v_payroll;
  end if;
  if tg_op='DELETE' then return old; else return new; end if;
end;$function$;

alter function "erp"."guard_attendance_after_payroll_use"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_attendance_period_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'Attendance periods cannot be deleted; reverse them with a reason';
  end if;

  if old.status <> 'DRAFT'
     and current_setting('app.attendance_period_lifecycle', true) is distinct from 'on' then
    raise exception 'Posted attendance is immutable; use correction/reversal workflow';
  end if;

  if old.status = 'DRAFT' and new.status not in ('DRAFT','POSTED','REVERSED')
     and current_setting('app.attendance_period_lifecycle', true) is distinct from 'on' then
    raise exception 'Invalid attendance lifecycle transition';
  end if;

  return new;
end;
$function$;

alter function "erp"."guard_attendance_period_lifecycle"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_attendance_period_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended('ATTENDANCE_PERIOD|' || new.contractor_id::text, 0));

  if new.status <> 'REVERSED' and exists (
    select 1
    from erp.attendance_periods p
    where p.contractor_id = new.contractor_id
      and p.id <> new.id
      and p.status in ('DRAFT','POSTED')
      and p.id is distinct from new.correction_of_period_id
      and p.correction_of_period_id is distinct from new.id
      and daterange(p.period_start, p.period_end + 1, '[)')
          && daterange(new.period_start, new.period_end + 1, '[)')
  ) then
    raise exception 'Active attendance periods for one contractor cannot overlap';
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_attendance_period_overlap"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_attendance_record_period_and_dates()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_worker erp.contractor_workers%rowtype;
  v_period erp.attendance_periods%rowtype;
  v_existing_period_id uuid := case when tg_op = 'INSERT' then null else old.attendance_period_id end;
begin
  if tg_op = 'DELETE' then
    if v_existing_period_id is not null then
      select * into v_period from erp.attendance_periods where id = v_existing_period_id;
      if v_period.status <> 'DRAFT' then
        raise exception 'Posted attendance details cannot be deleted';
      end if;
    end if;
    return old;
  end if;

  if tg_op = 'INSERT' and new.attendance_period_id is null
     and new.record_lifecycle is not null then
    raise exception 'New attendance rows require an attendance period';
  end if;

  select * into v_worker from erp.contractor_workers where id = new.worker_id;
  if v_worker.id is null or v_worker.contractor_id <> new.contractor_id then
    raise exception 'Worker does not belong to selected contractor';
  end if;
  if not erp.worker_is_employed_on(new.worker_id, new.attendance_date) then
    raise exception 'Attendance date is outside the worker employment periods';
  end if;

  if new.attendance_period_id is not null then
    select * into v_period
    from erp.attendance_periods
    where id = new.attendance_period_id;

    if v_period.id is null then raise exception 'Attendance period not found'; end if;
    if v_period.status <> 'DRAFT'
       and current_setting('app.attendance_period_lifecycle', true) is distinct from 'on' then
      raise exception 'Posted attendance details are immutable';
    end if;
    if v_period.contractor_id <> new.contractor_id then
      raise exception 'Attendance record contractor does not match its period';
    end if;
    if new.attendance_date not between v_period.period_start and v_period.period_end then
      raise exception 'Attendance date is outside its period';
    end if;
  end if;

  if tg_op = 'UPDATE' and v_existing_period_id is not null then
    select * into v_period from erp.attendance_periods where id = v_existing_period_id;
    if v_period.status <> 'DRAFT'
       and current_setting('app.attendance_period_lifecycle', true) is distinct from 'on' then
      raise exception 'Posted attendance details are immutable';
    end if;
  end if;

  return new;
end;
$function$;

alter function "erp"."guard_attendance_record_period_and_dates"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_bs_case_component_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_used boolean:=false;
begin
  if current_user in ('postgres','service_role','supabase_admin') then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;

  if tg_op='INSERT' then
    new.lifetime_newly_completed_qty:=0;
    new.lifetime_paid_qty:=0;
    return new;
  end if;

  select exists(select 1 from erp.rework_component_lines rcl where rcl.bs_case_component_id=old.id) into v_used;

  if tg_op='DELETE' then
    if v_used then raise exception 'BS component already has rework history and cannot be deleted'; end if;
    return old;
  end if;

  if new.lifetime_newly_completed_qty is distinct from old.lifetime_newly_completed_qty
     or new.lifetime_paid_qty is distinct from old.lifetime_paid_qty then
    raise exception 'BS lifetime completion/payment counters are system-managed';
  end if;

  if v_used and (
       new.bs_case_id is distinct from old.bs_case_id
       or new.po_component_snapshot_id is distinct from old.po_component_snapshot_id
       or new.work_component_id is distinct from old.work_component_id
       or new.completed_before_bs_qty is distinct from old.completed_before_bs_qty
     ) then
    raise exception 'BS component identity/completed-before-BS quantity is frozen after rework starts';
  end if;
  return new;
end;$function$;

alter function "erp"."guard_bs_case_component_state"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_bs_case_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if current_user in ('postgres','service_role','supabase_admin') then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if tg_op='INSERT' then
    new.status:='OPEN';
    return new;
  end if;
  if tg_op='DELETE' then
    raise exception 'BS case cannot be deleted directly; use controlled correction/resolution flow';
  end if;
  if new.status is distinct from old.status then raise exception 'BS status is system-managed by rework/resolution posting'; end if;
  if new.qty_pcs is distinct from old.qty_pcs
     or new.po_id is distinct from old.po_id
     or new.cutting_group_id is distinct from old.cutting_group_id
     or new.qc_item_id is distinct from old.qc_item_id
     or new.product_id is distinct from old.product_id
     or new.detected_at_stage is distinct from old.detected_at_stage
     or new.physical_at is distinct from old.physical_at then
    raise exception 'BS quantity/lineage is immutable; use controlled correction flow';
  end if;
  return new;
end;$function$;

alter function "erp"."guard_bs_case_lifecycle"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_child_by_parent_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ DECLARE v_parent_id uuid;v_status text;v_row jsonb;v_allowed text[]; BEGIN IF current_user IN ('postgres','service_role','supabase_admin') THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;v_row:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;v_parent_id:=NULLIF(v_row->>TG_ARGV[1],'')::uuid;v_allowed:=string_to_array(TG_ARGV[2],','); IF v_parent_id IS NULL THEN RAISE EXCEPTION 'Missing parent reference for %',TG_TABLE_NAME; END IF;EXECUTE format('SELECT status::text FROM erp.%I WHERE id=$1',TG_ARGV[0]) INTO v_status USING v_parent_id; IF v_status IS NULL THEN RAISE EXCEPTION 'Parent document not found for %',TG_TABLE_NAME; END IF; IF NOT (v_status=ANY(v_allowed)) THEN RAISE EXCEPTION '% cannot be changed while parent % status is %',TG_TABLE_NAME,TG_ARGV[0],v_status; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $function$;

alter function "erp"."guard_child_by_parent_status"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_committed_work_bom_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
DECLARE v_bom uuid;
BEGIN
  v_bom:=CASE WHEN TG_OP='DELETE' THEN OLD.bom_version_id ELSE NEW.bom_version_id END;
  IF EXISTS (SELECT 1 FROM erp.po_work_component_snapshots s WHERE s.source_bom_version_id=v_bom) THEN
    RAISE EXCEPTION 'Committed Work BOM items are immutable; create a successor BOM version';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;$function$;

alter function "erp"."guard_committed_work_bom_item"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_committed_work_bom_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
DECLARE v_last timestamptz;
BEGIN
  SELECT MAX(committed_at) INTO v_last FROM erp.po_work_component_snapshots WHERE source_bom_version_id=OLD.id;
  IF v_last IS NULL THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Committed Work BOM version cannot be deleted'; END IF;
  IF NEW.model_id IS DISTINCT FROM OLD.model_id OR NEW.version_no IS DISTINCT FROM OLD.version_no OR
     NEW.effective_from IS DISTINCT FROM OLD.effective_from OR NEW.is_active IS DISTINCT FROM OLD.is_active THEN
    RAISE EXCEPTION 'Committed Work BOM identity/start/active flag is immutable; create a successor version';
  END IF;
  IF NEW.effective_to IS NOT NULL AND NEW.effective_to<=v_last THEN RAISE EXCEPTION 'Work BOM effective_to cannot invalidate a committed snapshot'; END IF;
  RETURN NEW;
END;$function$;

alter function "erp"."guard_committed_work_bom_version"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_contractor_accessory_price_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended('CAPRICE:'||coalesce(new.contractor_id::text,'GLOBAL')||':'||new.category_id::text,0));
  if exists(
    select 1 from erp.contractor_accessory_price_versions x
    where x.category_id=new.category_id and x.contractor_id is not distinct from new.contractor_id and x.id<>new.id
      and x.effective_from<coalesce(new.effective_to,'infinity'::timestamptz)
      and coalesce(x.effective_to,'infinity'::timestamptz)>new.effective_from
  ) then raise exception 'Overlapping contractor accessory selling-price effective range'; end if;
  return new;
end$function$;

