CREATE OR REPLACE FUNCTION erp.guard_contractor_delete_after_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if current_user in ('postgres','service_role','supabase_admin') then return old; end if;
  if exists(select 1 from erp.attendance_records a where a.contractor_id=old.id)
     or exists(select 1 from erp.contractor_workers w join erp.attendance_records a on a.worker_id=w.id where w.contractor_id=old.id)
     or exists(select 1 from erp.production_orders p where p.contractor_id=old.id)
     or exists(select 1 from erp.contractor_material_issues i where i.contractor_id=old.id)
     or exists(select 1 from erp.payroll_settlements p where p.contractor_id=old.id)
     or exists(select 1 from erp.work_completion_events w where w.contractor_id=old.id)
     or exists(select 1 from erp.rework_orders r where r.contractor_id=old.id)
     or exists(select 1 from erp.journal_lines j where j.contractor_id=old.id)
     or exists(select 1 from erp.opening_balance_items o where o.contractor_id=old.id)
     or exists(select 1 from erp.opening_subledger_balances o where o.contractor_id=old.id)
     or exists(select 1 from erp.contractor_accessory_reimbursement_entitlements e where e.contractor_id=old.id)
  then
    raise exception 'Mandor sudah memiliki histori operasional/absensi/keuangan dan tidak boleh dihapus. Nonaktifkan mandor; histori transaksi harus tetap utuh.';
  end if;
  return old;
end;
$function$;

alter function "erp"."guard_contractor_delete_after_history"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_contractor_material_price_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended('CMPRICE:'||coalesce(new.contractor_id::text,'GLOBAL')||':'||new.material_id::text,0));
  if exists(
    select 1 from erp.contractor_material_price_versions x
    where x.material_id=new.material_id and x.contractor_id is not distinct from new.contractor_id and x.id<>new.id
      and x.effective_from<coalesce(new.effective_to,'infinity'::timestamptz)
      and coalesce(x.effective_to,'infinity'::timestamptz)>new.effective_from
  ) then raise exception 'Overlapping contractor material price effective range'; end if;
  return new;
end$function$;

