 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_root uuid;
begin
  select identity_root_id into v_root from erp.products where id=new.product_id;
  if v_root is null then raise exception 'SKU/produk master economics tidak ditemukan'; end if;
  if new.product_id<>v_root then
    raise exception 'Harga jual/BOM accessory untuk successor SKU mengikuti logical SKU root. Edit economics dari master logical SKU, bukan membuat copy pada versi identitas.';
