CREATE OR REPLACE FUNCTION erp.guard_finished_po_source_accounting()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  r record;
begin
  if new.status = 'FINISHED' and old.status is distinct from 'FINISHED' then
    select
      p.cutting_group_id,
      p.group_number,
      p.effective_qty_pcs,
      p.source_accounted_qty_pcs,
      p.remaining_source_qty_pcs
    into r
    from erp.v_fg_partial_completion_progress p
    where p.po_id = new.id
      and p.effective_qty_pcs > 0
      and p.source_accounted_qty_pcs is distinct from p.effective_qty_pcs
    order by p.group_number, p.cutting_group_id
    limit 1;

    if found then
      raise exception
        'PO belum boleh FINISHED. Potongan % baru terjelaskan % dari % pcs; sisa sumber % pcs.',
        r.group_number,
        r.source_accounted_qty_pcs,
        r.effective_qty_pcs,
        r.remaining_source_qty_pcs;
    end if;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_finished_po_source_accounting"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_initial_lifecycle_insert_v263e()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if current_user in ('postgres', 'service_role', 'supabase_admin') then
    return new;
  end if;

  if tg_table_name = 'payroll_settlements' then
    if new.status <> 'DRAFT'
       or coalesce(new.labor_total, 0) <> 0
       or coalesce(new.attendance_total, 0) <> 0
       or coalesce(new.reimburse_total, 0) <> 0
       or coalesce(new.deduction_total, 0) <> 0
       or new.settled_at is not null
    then
      raise exception 'Payroll must be created as a zero-value DRAFT; use payroll RPCs for calculation and settlement';
    end if;
  elsif tg_table_name = 'production_orders' then
    if new.status <> 'DRAFT' or new.current_stage <> 'CUTTING' then
      raise exception 'Production order must be created DRAFT at CUTTING; lifecycle follows operational RPCs';
    end if;
  elsif tg_table_name = 'scrap_batches' then
    if new.status <> 'AVAILABLE' then
      raise exception 'Scrap batch must be created AVAILABLE; sale/disposal requires a domain RPC';
    end if;
  else
    raise exception 'Unsupported lifecycle guard target %.%', tg_table_schema, tg_table_name;
  end if;

  return new;
end;
$function$;

alter function "erp"."guard_initial_lifecycle_insert_v263e"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_last_active_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old_owner boolean;v_new_owner boolean:=false;
begin
  -- A postgres-only, transaction-local escape hatch exists solely so the
  -- hosted synthetic Auth proof can return an otherwise-empty UAT to its exact
  -- zero-user baseline. It is unreachable through the Data API and does not
  -- weaken application/service-role lifecycle calls.
  if session_user in ('postgres','supabase_admin')
     and current_setting('erp.cp45_allow_synthetic_cleanup',true)='on' then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  select (r.role_code='OWNER' and old.is_active and old.auth_user_id is not null)
  into v_old_owner from erp.app_roles r where r.id=old.role_id;
  if not coalesce(v_old_owner,false) then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('erp.active_owner_roster',0));
  if tg_op='UPDATE' then
    select (r.role_code='OWNER' and new.is_active and new.auth_user_id is not null)
    into v_new_owner from erp.app_roles r where r.id=new.role_id;
  end if;
  if not coalesce(v_new_owner,false) and not exists(
    select 1 from erp.app_users u join erp.app_roles r on r.id=u.role_id
    where u.id<>old.id and u.is_active and u.auth_user_id is not null
      and r.role_code='OWNER' and r.is_active
  ) then
    raise exception using errcode='42501',message='LAST_ACTIVE_OWNER_PROTECTED';
  end if;
  if tg_op='DELETE' then return old; else return new; end if;
end
$function$;

alter function "erp"."guard_last_active_owner"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_last_owner_auth_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if session_user in ('postgres','supabase_admin')
     and current_setting('erp.cp45_allow_synthetic_cleanup',true)='on' then
    return old;
  end if;
  if exists(
    select 1 from erp.app_users u join erp.app_roles r on r.id=u.role_id
    where u.auth_user_id=old.id and u.is_active and r.role_code='OWNER' and r.is_active
  ) then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('erp.active_owner_roster',0));
    if not exists(
      select 1
      from erp.app_users u
      join erp.app_roles r on r.id=u.role_id
      join auth.users au on au.id=u.auth_user_id
      where u.auth_user_id<>old.id and u.is_active
        and r.role_code='OWNER' and r.is_active
    ) then
      raise exception using errcode='42501',message='LAST_ACTIVE_OWNER_AUTH_DELETE_PROTECTED';
    end if;
  end if;
  return old;
end
$function$;

alter function "erp"."guard_last_owner_auth_delete"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_laundry_claim_capacity_on_resolution()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_sent bigint;
  v_returned bigint;
  v_claimed bigint;
  v_bs bigint;
begin
  if new.status in ('SETTLED','WRITTEN_OFF') and old.status is distinct from new.status then
    if new.claim_type in ('MISSING','STUCK') then
      perform 1 from erp.laundry_deliveries where id=new.delivery_id for update;
      select coalesce(sum(qty_sent_pcs),0) into v_sent from erp.laundry_delivery_lines where delivery_id=new.delivery_id;
      select coalesce(sum(lrl.qty_good_received+lrl.qty_bs_laundry),0) into v_returned
      from erp.laundry_receipt_lines lrl join erp.laundry_receipts lr on lr.id=lrl.receipt_id
      where lr.delivery_id=new.delivery_id and lr.status='POSTED';
      select coalesce(sum(qty_claimed),0) into v_claimed
      from erp.laundry_claims
      where delivery_id=new.delivery_id and claim_type in ('MISSING','STUCK') and status<>'REJECTED';
      if v_claimed>greatest(v_sent-v_returned,0) then
        raise exception 'Laundry claim resolution exceeds physical outstanding quantity. Outstanding %, active claims %. Reject/correct duplicate claim first.',greatest(v_sent-v_returned,0),v_claimed;
      end if;
    elsif new.claim_type='DAMAGE' then
      if new.receipt_line_id is null then raise exception 'Laundry DAMAGE claim must reference a receipt line'; end if;
      select qty_bs_laundry into v_bs from erp.laundry_receipt_lines where id=new.receipt_line_id for update;
      select coalesce(sum(qty_claimed),0) into v_claimed
      from erp.laundry_claims
      where receipt_line_id=new.receipt_line_id and claim_type='DAMAGE' and status<>'REJECTED';
      if v_claimed>coalesce(v_bs,0) then
        raise exception 'Laundry DAMAGE claim resolution exceeds BS quantity on source receipt. BS %, active claims %. Reject/correct duplicate claim first.',coalesce(v_bs,0),v_claimed;
      end if;
    end if;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_laundry_claim_capacity_on_resolution"() owner to "postgres";

