alter function "erp"."guard_laundry_claim_insert_status"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_laundry_claim_resolution()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if current_user in ('postgres','service_role','supabase_admin') then if tg_op='DELETE' then return old; else return new; end if; end if;
  if tg_op='DELETE' then
    if old.status in ('SETTLED','WRITTEN_OFF') then raise exception 'Resolved laundry claim cannot be deleted directly'; end if;
    return old;
  end if;
  if old.status in ('SETTLED','WRITTEN_OFF') then raise exception 'Resolved laundry claim is frozen'; end if;
  if new.status in ('SETTLED','WRITTEN_OFF') and new.status is distinct from old.status then
    raise exception 'Use resolve_laundry_claim() for final claim settlement/write-off';
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_laundry_claim_resolution"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_laundry_delivery_posting_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_effective bigint;
  v_prior_sent bigint;
  v_current bigint;
  v_pickup timestamptz;
begin
  if not (old.status='DRAFT' and new.status is distinct from 'DRAFT') then
    return new;
  end if;

  for r in
    select l.cutting_group_id,sum(l.qty_sent_pcs)::bigint current_qty
    from erp.laundry_delivery_lines l
    where l.delivery_id=new.id
    group by l.cutting_group_id
    order by l.cutting_group_id
  loop
    select cg.picked_up_at into v_pickup
    from erp.cutting_groups cg
    where cg.id=r.cutting_group_id and cg.po_id=new.po_id
    for update;

    if not found then
      raise exception 'Potongan pada pengiriman laundry tidak belongs to PO pengiriman';
    end if;
    if v_pickup is null then
      raise exception 'Potongan % belum diambil mandor dan belum boleh dikirim ke laundry',r.cutting_group_id;
    end if;
    if new.physical_at<v_pickup then
      raise exception 'Tanggal/jam kirim laundry tidak boleh lebih awal dari tanggal/jam Potongan diambil mandor';
    end if;

    select coalesce(v.total_pcs,0) into v_effective
    from erp.v_cutting_group_totals v
    where v.cutting_group_id=r.cutting_group_id;

    select coalesce(sum(l2.qty_sent_pcs),0)::bigint into v_prior_sent
    from erp.laundry_delivery_lines l2
    join erp.laundry_deliveries d2 on d2.id=l2.delivery_id
    where l2.cutting_group_id=r.cutting_group_id
      and d2.id<>new.id
      and d2.status not in('DRAFT','REVERSED');

    v_current:=coalesce(r.current_qty,0);
    if v_prior_sent+v_current>coalesce(v_effective,0) then
      raise exception 'Qty laundry melebihi Potongan efektif. Potongan %, efektif %, sudah dikirim %, pengiriman ini %. Koreksi Potongan/downstream terlebih dahulu.',
        r.cutting_group_id,coalesce(v_effective,0),v_prior_sent,v_current;
    end if;
  end loop;

  return new;
end;
$function$;

alter function "erp"."guard_laundry_delivery_posting_consistency"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_laundry_delivery_source_capacity_on_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_effective bigint;
  v_prior bigint;
  v_current bigint;
  v_group_po uuid;
begin
  if new.status='SENT' and old.status is distinct from 'SENT' then
    for r in
      select ldl.cutting_group_id,sum(ldl.qty_sent_pcs)::bigint as current_qty
      from erp.laundry_delivery_lines ldl
      where ldl.delivery_id=new.id
      group by ldl.cutting_group_id
      order by ldl.cutting_group_id
    loop
      select cg.po_id into v_group_po
      from erp.cutting_groups cg
      where cg.id=r.cutting_group_id
      for update;

      if v_group_po is null or v_group_po is distinct from new.po_id then
        raise exception 'Laundry delivery cutting group does not belong to this PO at posting time';
      end if;

      select coalesce(v.total_pcs,0)::bigint into v_effective
      from erp.v_cutting_group_totals v
      where v.cutting_group_id=r.cutting_group_id;

      select coalesce(sum(x.qty_sent_pcs),0)::bigint into v_prior
      from erp.laundry_delivery_lines x
      join erp.laundry_deliveries xd on xd.id=x.delivery_id
      where x.cutting_group_id=r.cutting_group_id
        and xd.id<>new.id
        and xd.status not in('DRAFT','REVERSED');

      v_current:=coalesce(r.current_qty,0);
      if v_prior+v_current>coalesce(v_effective,0) then
        raise exception 'Laundry sent quantity exceeds effective cutting quantity at posting. Effective %, already sent %, this delivery %. Correct/reverse the related laundry delivery first.',
          coalesce(v_effective,0),v_prior,v_current;
      end if;
    end loop;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_laundry_delivery_source_capacity_on_post"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_laundry_rate_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended('LRATE:'||new.vendor_id::text||':'||new.wash_process_id::text,0));
  if exists(
    select 1 from erp.laundry_vendor_rate_versions x
    where x.vendor_id=new.vendor_id and x.wash_process_id=new.wash_process_id and x.id<>new.id
      and x.effective_from<coalesce(new.effective_to,'infinity'::timestamptz)
      and coalesce(x.effective_to,'infinity'::timestamptz)>new.effective_from
  ) then raise exception 'Overlapping laundry vendor rate effective range'; end if;
  return new;
end$function$;

alter function "erp"."guard_laundry_rate_overlap"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_laundry_receipt_physical_date()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_delivery_at timestamptz;
begin
  select physical_at into v_delivery_at from erp.laundry_deliveries where id=new.delivery_id;
  if v_delivery_at is not null and new.physical_at<v_delivery_at then
    raise exception 'Tanggal/jam barang kembali dari laundry tidak boleh lebih awal dari tanggal/jam kirim laundry';
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_laundry_receipt_physical_date"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_laundry_receipt_post_date()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if new.status='POSTED' and old.status is distinct from 'POSTED'
     and new.physical_at>clock_timestamp()+interval '5 minutes' then
    raise exception 'Tanggal/jam barang kembali dari laundry berada di masa depan. Periksa tanggal sebelum posting.';
  end if;
  return new;
end$function$;

alter function "erp"."guard_laundry_receipt_post_date"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_laundry_receipt_posting_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_sent integer;
  v_line_delivery uuid;
  v_prior_returned bigint;
  v_current bigint;
begin
  if not (old.status='DRAFT' and new.status='POSTED') then
    return new;
  end if;

  for r in
    select lrl.delivery_line_id,
           sum(lrl.qty_good_received+lrl.qty_bs_laundry)::bigint current_qty
    from erp.laundry_receipt_lines lrl
    where lrl.receipt_id=new.id
    group by lrl.delivery_line_id
    order by lrl.delivery_line_id
  loop
    select ldl.qty_sent_pcs,ldl.delivery_id
      into v_sent,v_line_delivery
    from erp.laundry_delivery_lines ldl
    where ldl.id=r.delivery_line_id
    for update;

    if v_sent is null then
      raise exception 'Laundry delivery line sumber tidak ditemukan';
    end if;
    if v_line_delivery is distinct from new.delivery_id then
      raise exception 'Receipt line tidak berasal dari laundry delivery yang sama';
    end if;

    select coalesce(sum(x.qty_good_received+x.qty_bs_laundry),0)::bigint
      into v_prior_returned
    from erp.laundry_receipt_lines x
    join erp.laundry_receipts xr on xr.id=x.receipt_id
    where x.delivery_line_id=r.delivery_line_id
      and xr.id<>new.id
      and xr.status='POSTED';

    v_current:=coalesce(r.current_qty,0);
    if v_prior_returned+v_current>v_sent then
      raise exception 'Penerimaan laundry melebihi qty yang dikirim. Dikirim %, sudah diterima %, receipt ini %. Koreksi receipt/downstream terlebih dahulu.',
        v_sent,v_prior_returned,v_current;
    end if;
  end loop;

  return new;
end;
$function$;

alter function "erp"."guard_laundry_receipt_posting_consistency"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_laundry_receipt_source_capacity_on_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_sent bigint;
  v_prior bigint;
  v_current bigint;
  v_source_delivery uuid;
begin
  if new.status='POSTED' and old.status is distinct from 'POSTED' then
    for r in
      select lrl.delivery_line_id,
             sum(lrl.qty_good_received+lrl.qty_bs_laundry)::bigint as current_qty
      from erp.laundry_receipt_lines lrl
      where lrl.receipt_id=new.id
      group by lrl.delivery_line_id
      order by lrl.delivery_line_id
    loop
      select ldl.qty_sent_pcs,ldl.delivery_id
        into v_sent,v_source_delivery
      from erp.laundry_delivery_lines ldl
      where ldl.id=r.delivery_line_id
      for update;

      if v_sent is null or v_source_delivery is distinct from new.delivery_id then
        raise exception 'Laundry receipt line source does not belong to this delivery at posting time';
      end if;

      select coalesce(sum(x.qty_good_received+x.qty_bs_laundry),0)::bigint
        into v_prior
      from erp.laundry_receipt_lines x
      join erp.laundry_receipts xr on xr.id=x.receipt_id
      where x.delivery_line_id=r.delivery_line_id
        and xr.id<>new.id
        and xr.status='POSTED';

      v_current:=coalesce(r.current_qty,0);
      if v_prior+v_current>v_sent then
        raise exception 'Laundry physical return exceeds quantity sent at posting. Sent %, already returned %, this receipt %. Correct/reverse the related laundry receipt first.',
          v_sent,v_prior,v_current;
      end if;
    end loop;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_laundry_receipt_source_capacity_on_post"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_location_identity_and_deactivation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_mat numeric(24,6):=0;
  v_fg bigint:=0;
begin
  if old.location_type is distinct from new.location_type then
    if exists(select 1 from erp.material_stock_movements m where m.location_id=old.id)
       or exists(select 1 from erp.fg_stock_movements f where f.location_id=old.id) then
      raise exception 'Jenis lokasi/gudang sudah mempunyai histori stok dan tidak boleh diubah langsung. Buat lokasi baru agar histori fisik tetap jelas.';
    end if;
  end if;

  if old.is_active=true and new.is_active=false then
    select coalesce(sum(m.qty_signed),0) into v_mat
    from erp.material_stock_movements m where m.location_id=old.id;
    select coalesce(sum(f.qty_signed),0) into v_fg
    from erp.fg_stock_movements f where f.location_id=old.id;
    if abs(v_mat)>0.000001 or v_fg<>0 then
      raise exception 'Lokasi masih memiliki stok. Material % dan FG % pcs. Pindahkan/koreksi stok sampai nol sebelum menonaktifkan gudang.',v_mat,v_fg;
    end if;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_location_identity_and_deactivation"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_manual_reminder_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'Manual reminders cannot be deleted; use erp_cancel_my_reminder_v1';
  end if;

  -- A custom GUC is only routing context, never authority. Browser/API roles,
  -- including service_role, cannot authorize direct table DML by spoofing it.
  if current_user <> 'postgres'
     or current_setting('app.manual_reminder_write', true) is distinct from 'on' then
    raise exception 'Manual reminders are write-protected; use the reminder RPC facade';
  end if;

  if tg_op = 'UPDATE' then
    if (new.id, new.owner_user_id, new.created_at, new.created_by)
       is distinct from
       (old.id, old.owner_user_id, old.created_at, old.created_by) then
      raise exception 'Reminder identity, owner, and creation facts are immutable';
    end if;
    if old.status = 'CANCELLED' then
      raise exception 'Cancelled reminders are terminal';
    end if;
  end if;

  return new;
end;
$function$;

alter function "erp"."guard_manual_reminder_write"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_mapped_chart_account_semantics()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare r record;v_expected text;
begin
  if tg_op='DELETE' then return old; end if;
  if new.account_type is distinct from old.account_type or new.is_active is distinct from old.is_active then
    for r in select mapping_key from erp.accounting_account_mappings where account_id=old.id loop
      v_expected:=erp.expected_mapping_account_type(r.mapping_key);
      if v_expected is not null and (new.account_type<>v_expected or not coalesce(new.is_active,false)) then
        raise exception 'Akun % sedang dipakai mapping %. Pindahkan mapping dahulu sebelum mengubah tipe/nonaktifkan akun.',old.account_code,r.mapping_key;
      end if;
    end loop;
    if exists(select 1 from erp.cash_accounts c where c.coa_account_id=old.id and c.is_active=true)
       and (new.account_type<>'ASSET' or not coalesce(new.is_active,false)) then
      raise exception 'Akun % dipakai cash/bank aktif; harus tetap ASSET dan aktif',old.account_code;
    end if;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_mapped_chart_account_semantics"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_material_accessory_category_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ BEGIN IF EXISTS (SELECT 1 FROM erp.material_stock_movements WHERE material_id=OLD.id LIMIT 1) THEN IF NEW.material_type IS DISTINCT FROM OLD.material_type OR NEW.unit_code IS DISTINCT FROM OLD.unit_code OR (OLD.accessory_category_id IS NOT NULL AND NEW.accessory_category_id IS DISTINCT FROM OLD.accessory_category_id) THEN RAISE EXCEPTION 'Material category/base UOM is frozen after stock history exists; create a new material variant for a different category'; END IF; END IF;RETURN NEW;END; $function$;

alter function "erp"."guard_material_accessory_category_history"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_material_cached_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if current_user in ('postgres','service_role','supabase_admin') then return new; end if;
  if new.cached_stock_qty is distinct from old.cached_stock_qty or new.moving_average_cost is distinct from old.moving_average_cost then
    raise exception 'Material cached stock and moving-average cost are system-managed';
  end if;
  return new;
end;
$function$;

