CREATE OR REPLACE FUNCTION erp.guard_material_negative_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare v_available numeric(24,6);
begin
  if new.qty_signed>=0 then return new; end if;
  if new.location_id is null then raise exception 'Material OUT movement requires location_id'; end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'MATSTOCK|'||new.material_id::text||'|'||coalesce(new.roll_id::text,'NO_ROLL')||'|'||new.location_id::text,0
  ));

  if new.source_type='MATERIAL_PURCHASE_REVERSAL'
     and current_setting('erp.allow_source_replacement_negative',true)='on' then
    return new;
  end if;

  if new.roll_id is not null then
    select coalesce(sum(qty_signed),0) into v_available from erp.material_stock_movements
    where material_id=new.material_id and roll_id=new.roll_id and location_id=new.location_id;
  else
    select coalesce(sum(qty_signed),0) into v_available from erp.material_stock_movements
    where material_id=new.material_id and roll_id is null and location_id=new.location_id;
  end if;
  if v_available+new.qty_signed < -0.000001 then
    raise exception 'Material stock would become negative at selected location/roll. Available %, requested out %',v_available,abs(new.qty_signed);
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_material_negative_stock"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_material_reversal_chronology()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_source_at timestamptz;
BEGIN
  IF NEW.movement_type='REVERSAL' AND NEW.reversal_of_id IS NOT NULL THEN
    SELECT physical_at INTO v_source_at
    FROM erp.material_stock_movements
    WHERE id=NEW.reversal_of_id;
    IF v_source_at IS NULL THEN
      RAISE EXCEPTION 'Material reversal source movement not found';
    END IF;
    IF NEW.physical_at < v_source_at THEN
      RAISE EXCEPTION 'Material reversal physical_at cannot precede source movement';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

alter function "erp"."guard_material_reversal_chronology"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_material_roll_after_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_locked boolean:=false;
  v_purchase_status text;
begin
  if current_user in ('postgres','service_role','supabase_admin') then if tg_op='DELETE' then return old; else return new; end if; end if;
  if old.purchase_item_id is not null then
    select mph.status into v_purchase_status
    from erp.material_purchase_items mpi join erp.material_purchase_headers mph on mph.id=mpi.purchase_id
    where mpi.id=old.purchase_item_id;
    v_locked:=coalesce(v_purchase_status,'')<>'DRAFT';
  end if;
  if exists (select 1 from erp.material_stock_movements msm where msm.roll_id=old.id) then v_locked:=true; end if;
  if not v_locked then if tg_op='DELETE' then return old; else return new; end if; end if;
  if tg_op='DELETE' then raise exception 'Material roll with posted/history movement cannot be deleted'; end if;
  if new.material_id is distinct from old.material_id
     or new.supplier_id is distinct from old.supplier_id
     or new.purchase_item_id is distinct from old.purchase_item_id
     or new.original_qty is distinct from old.original_qty
     or new.cached_qty is distinct from old.cached_qty
     or new.status is distinct from old.status
     or new.roll_number is distinct from old.roll_number then
    raise exception 'Posted material roll core fields are system-managed/frozen; only notes may be edited';
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_material_roll_after_post"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_material_transfer_item_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_transfer_id uuid := case when tg_op = 'DELETE' then old.transfer_id else new.transfer_id end;
  v_status text;
  v_material_type text;
begin
  select status into v_status
  from erp.material_transfers
  where id = v_transfer_id
  for update;
  if v_status is null then raise exception 'Material transfer not found'; end if;
  if v_status <> 'DRAFT' then
    raise exception 'Posted/reversed material transfer lines are immutable';
  end if;

  if tg_op <> 'DELETE' then
    select material_type into v_material_type
    from erp.materials
    where id = new.material_id and is_active = true;
    if v_material_type is null then raise exception 'Active material is required'; end if;
    if v_material_type = 'FABRIC' and new.roll_id is null then
      raise exception 'FABRIC transfer requires concrete roll lineage';
    end if;
    if v_material_type <> 'FABRIC' and new.roll_id is not null then
      raise exception 'Only FABRIC may use roll_id in a warehouse transfer';
    end if;
    if new.roll_id is not null and not exists (
      select 1 from erp.material_rolls r
      where r.id = new.roll_id and r.material_id = new.material_id
    ) then
      raise exception 'Transfer roll does not belong to material';
    end if;
  end if;

  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$function$;

alter function "erp"."guard_material_transfer_item_parent"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_multi_receipt_invoice_header_compat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_purchase_count bigint;
begin
  if new.supplier_invoice_number is distinct from old.supplier_invoice_number
     and new.supplier_invoice_number is not null then
    select count(distinct pi.purchase_id) into v_purchase_count
    from erp.material_supplier_invoices ih
    join erp.material_supplier_invoice_lines il on il.invoice_id=ih.id
    join erp.material_purchase_items pi on pi.id=il.purchase_item_id
    where ih.supplier_id=new.supplier_id
      and lower(btrim(ih.invoice_number))=lower(btrim(new.supplier_invoice_number))
      and ih.status='POSTED';
    if v_purchase_count>1 then
      new.supplier_invoice_number:=old.supplier_invoice_number;
      new.due_date:=old.due_date;
    end if;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_multi_receipt_invoice_header_compat"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_no_future_physical_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if new.physical_at is null then raise exception 'Tanggal/jam fisik wajib diisi'; end if;
  if new.physical_at>clock_timestamp()+interval '5 minutes' then
    raise exception 'Tanggal/jam fisik % berada di masa depan. Periksa tanggal/jam transaksi sebelum posting.',new.physical_at;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_no_future_physical_event"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_no_physical_stage_post_on_finished_po()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_po uuid;
  v_status text;
begin
  -- Only guard the transition that makes a physical-stage document active.
  if tg_table_name='laundry_deliveries' then
    if not (old.status='DRAFT' and new.status is distinct from 'DRAFT') then return new; end if;
    v_po:=new.po_id;
  elsif tg_table_name='laundry_receipts' then
    if not (old.status='DRAFT' and new.status='POSTED') then return new; end if;
    select ld.po_id into v_po
    from erp.laundry_deliveries ld
    where ld.id=new.delivery_id;
  elsif tg_table_name='qc_inspections' then
    if not (old.status='DRAFT' and new.status='POSTED') then return new; end if;
    v_po:=new.po_id;
  else
    return new;
  end if;

  if v_po is null then return new; end if;

  -- Serialize physical-stage activation against FINISH/REOPEN and any other
  -- lifecycle writer. If FINISH already started, wait and then see FINISHED;
  -- if this posting gets the lock first, FINISH waits until this posting ends.
  select status into v_status
  from erp.production_orders
  where id=v_po
  for update;

  if v_status='FINISHED' then
    raise exception 'PO sudah FINISHED. Reopen PO secara terkontrol terlebih dahulu sebelum posting proses fisik % agar final WIP close, HPP, dan histori tetap konsisten.',tg_table_name;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_no_physical_stage_post_on_finished_po"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_opening_balance_post_date()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if new.status='POSTED' and old.status is distinct from 'POSTED' and new.opening_date>current_date then
    raise exception 'Tanggal saldo awal berada di masa depan. Periksa tanggal cutover/opening sebelum posting.';
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_opening_balance_post_date"() owner to "postgres";

