CREATE OR REPLACE FUNCTION erp.guard_pattern_assignment_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_pattern erp.production_patterns%rowtype;
begin
  if tg_op='INSERT' and new.pattern_id is not null
     and (new.status<>'CUT'
       or new.picked_up_at is not null
       or new.material_issue_posted
       or new.material_return_posted) then
    raise exception using errcode='23514',message='PATTERN_INITIAL_ASSIGNMENT_REQUIRES_PRISTINE_CUTTING';
  end if;

  if tg_op='UPDATE' then
    -- Once bound, the identity and every historical display snapshot are
    -- append-only. This also blocks direct unbind and privileged SQL rebind.
    if old.pattern_id is not null then
      if new.pattern_id is distinct from old.pattern_id
         or new.pattern_code_snapshot is distinct from old.pattern_code_snapshot
         or new.pattern_name_snapshot is distinct from old.pattern_name_snapshot
         or new.pattern_revision_snapshot is distinct from old.pattern_revision_snapshot
         or new.pattern_type is distinct from old.pattern_type then
        raise exception using errcode='42501',message='PATTERN_ASSIGNMENT_SNAPSHOT_IMMUTABLE';
      end if;
      return new;
    end if;

    if new.pattern_id is null then
      if new.pattern_code_snapshot is distinct from old.pattern_code_snapshot
         or new.pattern_name_snapshot is distinct from old.pattern_name_snapshot
         or new.pattern_revision_snapshot is distinct from old.pattern_revision_snapshot
         or new.pattern_type is distinct from old.pattern_type then
        raise exception using errcode='42501',message='PATTERN_ASSIGNMENT_SNAPSHOT_IMMUTABLE';
      end if;
      return new;
    end if;

    perform erp.assert_pattern_initial_assignment_allowed(old.id);
  end if;

  if new.pattern_id is null then
    new.pattern_code_snapshot:=null;
    new.pattern_name_snapshot:=null;
    new.pattern_revision_snapshot:=null;
    new.pattern_type:=null;
    return new;
  end if;

  select * into v_pattern
  from erp.production_patterns
  where id=new.pattern_id and is_active;
  if v_pattern.id is null then
    raise exception using errcode='23503',message='ACTIVE_PATTERN_REQUIRED_FOR_NEW_ASSIGNMENT';
  end if;
  new.pattern_code_snapshot:=v_pattern.pattern_code;
  new.pattern_name_snapshot:=v_pattern.pattern_name;
  new.pattern_revision_snapshot:=v_pattern.revision;
  new.pattern_type:=v_pattern.pattern_name;
  return new;
end
$function$;

alter function "erp"."guard_pattern_assignment_snapshot"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_payroll_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
BEGIN
  IF current_user IN ('postgres','service_role','supabase_admin') THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
  IF TG_OP='DELETE' THEN
    IF OLD.status<>'DRAFT' THEN RAISE EXCEPTION 'Non-draft payroll cannot be deleted directly'; END IF;
    RETURN OLD;
  END IF;
  IF NEW.labor_total IS DISTINCT FROM OLD.labor_total OR NEW.attendance_total IS DISTINCT FROM OLD.attendance_total OR
     NEW.reimburse_total IS DISTINCT FROM OLD.reimburse_total OR NEW.deduction_total IS DISTINCT FROM OLD.deduction_total OR
     NEW.settled_at IS DISTINCT FROM OLD.settled_at THEN
    RAISE EXCEPTION 'Payroll calculated/settlement fields are system-managed';
  END IF;
  IF OLD.status IN ('APPROVED','PAID','REVERSED') THEN RAISE EXCEPTION 'Approved/paid payroll is frozen; use controlled posting/reversal'; END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (OLD.status='CALCULATED' AND NEW.status='REVIEW') THEN
    RAISE EXCEPTION 'Payroll status transition must use payroll RPC';
  END IF;
  IF OLD.status<>'DRAFT' AND (NEW.contractor_id IS DISTINCT FROM OLD.contractor_id OR NEW.period_start IS DISTINCT FROM OLD.period_start OR NEW.period_end IS DISTINCT FROM OLD.period_end) THEN
    RAISE EXCEPTION 'Payroll identity/period is frozen after draft';
  END IF;
  RETURN NEW;
END;$function$;

alter function "erp"."guard_payroll_lifecycle"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_payroll_period_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if new.status='REVERSED' then return new; end if;
  perform pg_advisory_xact_lock(hashtextextended(new.contractor_id::text,0));
  if exists (
    select 1 from erp.payroll_settlements ps
    where ps.contractor_id=new.contractor_id and ps.id<>new.id and ps.status<>'REVERSED'
      and new.period_start<=ps.period_end and new.period_end>=ps.period_start
  ) then
    raise exception 'Payroll period overlaps another active payroll for this contractor';
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_payroll_period_overlap"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_posted_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
BEGIN
  IF current_user IN ('postgres','service_role','supabase_admin') THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  IF TG_OP='INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'DRAFT' THEN
      RAISE EXCEPTION 'Document must be created as DRAFT; use the ERP posting RPC to post it';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP='DELETE' THEN
    IF OLD.status<>'DRAFT' THEN
      RAISE EXCEPTION 'Posted/non-draft document cannot be deleted directly; use reversal/correction';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status<>'DRAFT' THEN
    RAISE EXCEPTION 'Posted/non-draft document cannot be edited directly; use reversal/correction';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    RAISE EXCEPTION 'Document status cannot leave DRAFT by direct table update; use the ERP posting/cancellation RPC';
  END IF;
  RETURN NEW;
END;
$function$;

alter function "erp"."guard_posted_document"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_posted_qc_item_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_status text;
begin
  if tg_op in ('UPDATE','DELETE') then
    select q.status into v_status
    from erp.qc_inspections q where q.id=old.inspection_id;
    if v_status is not null and v_status<>'DRAFT' then
      raise exception using errcode='42501',message='POSTED_FINAL_SKU_IDENTITY_IMMUTABLE';
    end if;
  end if;
  if tg_op in ('INSERT','UPDATE') then
    select q.status into v_status
    from erp.qc_inspections q where q.id=new.inspection_id;
    if v_status is not null and v_status<>'DRAFT' then
      raise exception using errcode='42501',message='POSTED_FINAL_SKU_IDENTITY_IMMUTABLE';
    end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$;

alter function "erp"."guard_posted_qc_item_immutable"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_product_delete_after_identity_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if current_user in ('postgres','service_role','supabase_admin')
     or coalesce(current_setting('app.product_identity_controlled',true),'')='on' then
    return old;
  end if;

  if old.supersedes_product_id is not null
     or exists(select 1 from erp.products x where x.identity_root_id=old.identity_root_id and x.id<>old.id)
     or exists(select 1 from erp.fg_lots x where x.product_id=old.id)
     or exists(select 1 from erp.sales_items x where x.product_id=old.id)
     or exists(select 1 from erp.qc_inspection_items x where x.final_product_id=old.id)
     or exists(select 1 from erp.opening_balance_items x where x.product_id=old.id)
     or exists(select 1 from erp.bs_cases x where x.product_id=old.id)
     or exists(select 1 from erp.po_accessory_bom_commitments x where x.product_id=old.id)
     or exists(select 1 from erp.product_conversions x where x.from_product_id=old.id or x.to_product_id=old.id) then
    raise exception 'SKU sudah punya histori/version chain dan tidak boleh dihapus langsung. Gunakan Batalkan Perubahan SKU untuk successor yang belum dipakai, atau nonaktifkan SKU.';
  end if;
  return old;
end;
$function$;

alter function "erp"."guard_product_delete_after_identity_history"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_product_identity_after_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  if row(old.sku,old.model_id,old.brand_id,old.color_name,old.size_id)
     is distinct from row(new.sku,new.model_id,new.brand_id,new.color_name,new.size_id) then
    if exists(select 1 from erp.fg_lots fl where fl.product_id=old.id)
       or exists(select 1 from erp.po_accessory_bom_commitments pc where pc.product_id=old.id)
       or exists(select 1 from erp.bs_cases bc where bc.product_id=old.id) then
      raise exception 'Identitas SKU sudah punya histori stok/HPP/BS dan tidak boleh ditulis ulang langsung. Gunakan Edit SKU efektif-tanggal agar histori lama tetap memakai identitas lama.';
    end if;
  end if;
  return new;
end$function$;

alter function "erp"."guard_product_identity_after_history"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_product_identity_version_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if current_user in ('postgres','service_role','supabase_admin')
     or coalesce(current_setting('app.product_identity_controlled',true),'')='on' then
    return new;
  end if;

  if tg_op='INSERT' then
    if new.supersedes_product_id is not null
       or new.effective_to is not null
       or (new.identity_root_id is not null and new.identity_root_id<>new.id) then
      raise exception 'Metadata versi SKU tidak boleh diisi langsung. Gunakan Edit SKU efektif-tanggal.';
    end if;
    return new;
  end if;

  if new.identity_root_id is distinct from old.identity_root_id
     or new.effective_from is distinct from old.effective_from
     or new.effective_to is distinct from old.effective_to
     or new.supersedes_product_id is distinct from old.supersedes_product_id then
    raise exception 'Periode/chain versi SKU dikelola sistem. Gunakan Edit SKU atau Batalkan Perubahan SKU.';
  end if;
  return new;
end;
$function$;

