CREATE OR REPLACE FUNCTION erp.guard_production_order_cost_identity_after_use()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_model_used boolean:=false; v_contractor_used boolean:=false;
begin
  if current_user in ('postgres','service_role','supabase_admin') then return new; end if;

  if new.model_id is distinct from old.model_id then
    v_model_used:=
         exists(select 1 from erp.cutting_groups cg where cg.po_id=old.id)
      or exists(select 1 from erp.po_work_component_snapshots s where s.po_id=old.id)
      or exists(select 1 from erp.po_accessory_bom_commitments c where c.po_id=old.id)
      or exists(select 1 from erp.fg_lots f where f.po_id=old.id)
      or exists(select 1 from erp.work_completion_events w where w.po_id=old.id and w.status<>'DRAFT')
      or exists(select 1 from erp.qc_inspections q where q.po_id=old.id and q.status<>'DRAFT');
    if v_model_used then
      raise exception 'Model PO sudah dipakai Potongan/BOM/output dan tidak boleh diganti langsung. Hapus Potongan yang benar-benar belum dipakai atau koreksi/reverse downstream terlebih dahulu.';
    end if;
  end if;

  if new.contractor_id is distinct from old.contractor_id then
    v_contractor_used:=
         exists(select 1 from erp.cutting_groups cg where cg.po_id=old.id and (cg.picked_up_at is not null or cg.material_issue_posted or cg.status<>'CUT'))
      or exists(select 1 from erp.contractor_material_issues i where i.po_id=old.id and i.status<>'DRAFT')
      or exists(select 1 from erp.work_completion_events w where w.po_id=old.id and w.status<>'DRAFT')
      or exists(select 1 from erp.payroll_work_items pwi where pwi.po_id=old.id and exists(select 1 from erp.payroll_settlements ps where ps.id=pwi.payroll_id and ps.status<>'REVERSED'))
      or exists(select 1 from erp.po_work_component_snapshots s where s.po_id=old.id)
      or exists(select 1 from erp.contractor_accessory_reimbursement_entitlements e where e.po_id=old.id and e.payroll_status<>'CANCELLED')
      or exists(select 1 from erp.rework_orders r join erp.bs_cases b on b.id=r.bs_case_id where b.po_id=old.id and r.status not in('CANCELLED'));
    if v_contractor_used then
      raise exception 'Mandor PO sudah dipakai pickup/issue/upah/payroll dan tidak boleh diganti langsung. Koreksi/batalkan transaksi yang mengikat mandor terlebih dahulu agar hak bayar dan piutang mandor tidak pindah orang.';
    end if;
  end if;

  return new;
end;
$function$;

alter function "erp"."guard_production_order_cost_identity_after_use"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_production_order_delete_after_use()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if current_user in ('postgres','service_role','supabase_admin') then return old; end if;

  if old.status <> 'DRAFT'
     or exists(
       select 1 from erp.cutting_groups cg
       where cg.po_id=old.id
         and (
           cg.picked_up_at is not null
           or cg.material_issue_posted
           or cg.material_return_posted
           or cg.status<>'CUT'
           or exists(select 1 from erp.material_stock_movements msm where msm.source_id=cg.id and msm.source_type in ('CUTTING_GROUP','CUTTING_GROUP_RETURN'))
           or exists(select 1 from erp.wip_stage_events w where w.cutting_group_id=cg.id)
           or exists(select 1 from erp.laundry_delivery_lines l where l.cutting_group_id=cg.id)
           or exists(select 1 from erp.work_completion_events w where w.cutting_group_id=cg.id)
           or exists(select 1 from erp.qc_inspection_items q where q.cutting_group_id=cg.id)
           or exists(select 1 from erp.fg_lots f where f.cutting_group_id=cg.id)
           or exists(select 1 from erp.bs_cases b where b.cutting_group_id=cg.id)
           or exists(select 1 from erp.scrap_batches s where s.source_cutting_group_id=cg.id)
         )
     )
     or exists(select 1 from erp.fg_lots f where f.po_id=old.id)
     or exists(select 1 from erp.journal_lines jl where jl.po_id=old.id)
     or exists(select 1 from erp.work_completion_events w where w.po_id=old.id and w.status <> 'DRAFT')
     or exists(select 1 from erp.contractor_material_issues c where c.po_id=old.id and c.status <> 'DRAFT')
     or exists(select 1 from erp.laundry_deliveries l where l.po_id=old.id and l.status <> 'DRAFT')
     or exists(select 1 from erp.qc_inspections q where q.po_id=old.id and q.status <> 'DRAFT')
     or exists(select 1 from erp.bs_cases b where b.po_id=old.id)
  then
    raise exception 'PO produksi sudah dipakai operasional/biaya dan tidak boleh dihapus. Potongan draft yang belum dipakai boleh dihapus/bagi ulang; bila sudah pickup/issue/downstream gunakan koreksi atau reversal agar stok, HPP, dan histori tidak rusak.';
  end if;
  return old;
end;
$function$;

alter function "erp"."guard_production_order_delete_after_use"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_production_terminal_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_expected text;
  v_has_activity boolean;
begin
  if current_user in ('postgres','service_role','supabase_admin') then return new; end if;

  if old.status='FINISHED' and (new.status is distinct from old.status or new.current_stage is distinct from old.current_stage) then
    raise exception 'Finished PO lifecycle is frozen';
  end if;

  if new.status='FINISHED' and old.status is distinct from 'FINISHED' then
    raise exception 'Use finish_production_order() to finish a PO';
  end if;
  if new.current_stage='FINISHED' and old.current_stage is distinct from 'FINISHED' then
    raise exception 'Use finish_production_order() to finish a PO';
  end if;

  if new.status is not distinct from old.status and new.current_stage is not distinct from old.current_stage then
    return new;
  end if;

  -- ON_HOLD is an owner/admin operational flag and may be set manually.
  if new.status='ON_HOLD' and new.current_stage='ON_HOLD' then return new; end if;

  -- Determine the latest stage supported by real operational evidence.
  if exists(select 1 from erp.qc_inspections q where q.po_id=old.id and q.status='POSTED')
     or exists(select 1 from erp.laundry_receipts lr join erp.laundry_deliveries ld on ld.id=lr.delivery_id where ld.po_id=old.id and lr.status='POSTED' and ld.status<>'REVERSED') then
    v_expected:='QC';
  elsif exists(select 1 from erp.laundry_deliveries ld where ld.po_id=old.id and ld.status not in('DRAFT','REVERSED')) then
    v_expected:='LAUNDRY';
  elsif exists(select 1 from erp.cutting_groups cg where cg.po_id=old.id and cg.picked_up_at is not null) then
    v_expected:='SEWING';
  elsif exists(select 1 from erp.cutting_groups cg where cg.po_id=old.id) then
    v_expected:='CUTTING';
  else
    v_expected:='DRAFT';
  end if;

  v_has_activity:=v_expected<>'DRAFT'
    or exists(select 1 from erp.contractor_material_issues i where i.po_id=old.id and i.status<>'DRAFT')
    or exists(select 1 from erp.work_completion_events w where w.po_id=old.id and w.status<>'DRAFT')
    or exists(select 1 from erp.fg_lots f where f.po_id=old.id and f.lot_origin<>'VOIDED_PRODUCTION');

  if new.status='CANCELLED' then
    if v_has_activity then
      raise exception 'PO sudah punya aktivitas operasional dan tidak boleh CANCELLED manual. Reverse/koreksi transaksi downstream terlebih dahulu.';
    end if;
    return new;
  end if;

  -- Leaving ON_HOLD is allowed only to the stage justified by evidence.
  if old.status='ON_HOLD' then
    if v_expected='DRAFT' then
      if new.status='DRAFT' and new.current_stage='CUTTING' then return new; end if;
    elsif new.status=v_expected and new.current_stage=v_expected then
      return new;
    end if;
    raise exception 'PO hanya boleh dilanjutkan ke stage yang didukung transaksi aktual: %',v_expected;
  end if;

  if v_expected='DRAFT' then
    -- A blank PO may remain DRAFT; it cannot be promoted by status edit alone.
    if new.status='DRAFT' and new.current_stage='CUTTING' then return new; end if;
    raise exception 'PO belum memiliki bukti proses fisik; stage tidak boleh diubah manual ke %',new.current_stage;
  end if;

  if new.status=v_expected and new.current_stage=v_expected then return new; end if;

  raise exception 'Stage PO mengikuti transaksi aktual. Stage yang didukung saat ini adalah %. Posting/reverse proses terkait, jangan ubah status manual.',v_expected;
end;
$function$;

alter function "erp"."guard_production_terminal_state"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_protected_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_code text;v_new_code text;
begin
  if tg_table_name='app_roles' then
    v_code:=old.role_code;
  elsif tg_op='INSERT' then
    select role_code into v_code from erp.app_roles where id=new.role_id;
  elsif tg_op='DELETE' then
    select role_code into v_code from erp.app_roles where id=old.role_id;
  else
    select role_code into v_code from erp.app_roles where id=old.role_id;
    select role_code into v_new_code from erp.app_roles where id=new.role_id;
  end if;
  if v_code='OWNER' or v_new_code='OWNER' then
    raise exception using errcode='42501',message='PROTECTED_OWNER_ROLE_CANNOT_BE_CHANGED';
  end if;
  if tg_op='DELETE' then return old; else return new; end if;
end
$function$;

alter function "erp"."guard_protected_role"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_qc_laundry_source_matches_group()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_source_group_id uuid;
begin
  if new.source_laundry_receipt_line_id is null then
    return new;
  end if;

  select dl.cutting_group_id
  into v_source_group_id
  from erp.laundry_receipt_lines rl
  join erp.laundry_delivery_lines dl on dl.id = rl.delivery_line_id
  where rl.id = new.source_laundry_receipt_line_id;

  if v_source_group_id is null then
    raise exception 'QC laundry receipt source was not found';
  end if;
  if new.cutting_group_id is null or v_source_group_id is distinct from new.cutting_group_id then
    raise exception 'QC laundry source belongs to a different Potongan';
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_qc_laundry_source_matches_group"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_qc_posting_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_effective bigint;
  v_prior bigint;
  v_current bigint;
  v_source_good bigint;
  v_source_po uuid;
  v_source_status text;
begin
  if new.status='POSTED' and old.status is distinct from 'POSTED' then
    if new.physical_at>clock_timestamp()+interval '5 minutes' then
      raise exception 'Tanggal/jam QC berada di masa depan. Periksa tanggal/jam sebelum posting.';
    end if;

    if exists(select 1 from erp.qc_inspection_items i where i.inspection_id=new.id and i.cutting_group_id is null) then
      raise exception 'Setiap item QC produksi wajib terkait Potongan agar qty FG, HPP, dan histori dapat divalidasi.';
    end if;

    for r in
      select i.cutting_group_id,sum(i.qty_good_pcs+i.qty_bs_pcs)::bigint current_qty
      from erp.qc_inspection_items i
      where i.inspection_id=new.id
      group by i.cutting_group_id
      order by i.cutting_group_id
    loop
      perform 1 from erp.cutting_groups cg where cg.id=r.cutting_group_id and cg.po_id=new.po_id for update;
      if not found then raise exception 'Potongan item QC tidak belongs to PO QC'; end if;

      select coalesce(v.total_pcs,0) into v_effective
      from erp.v_cutting_group_totals v where v.cutting_group_id=r.cutting_group_id;

      select coalesce(sum(i2.qty_good_pcs+i2.qty_bs_pcs),0)::bigint into v_prior
      from erp.qc_inspection_items i2
      join erp.qc_inspections q2 on q2.id=i2.inspection_id
      where i2.cutting_group_id=r.cutting_group_id
        and q2.status='POSTED'
        and q2.id<>new.id;

      v_current:=coalesce(r.current_qty,0);
      if v_effective<=0 then
        raise exception 'Potongan item QC tidak memiliki qty efektif yang dapat menghasilkan FG/BS.';
      end if;
      if v_prior+v_current>v_effective then
        raise exception 'Qty QC melebihi Potongan efektif. Potongan %, efektif %, QC sebelumnya %, QC ini %. Koreksi qty QC/Potongan sebelum posting.',
          r.cutting_group_id,v_effective,v_prior,v_current;
      end if;
    end loop;

    for r in
      select i.source_laundry_receipt_line_id as source_id,
             sum(i.qty_good_pcs+i.qty_bs_pcs)::bigint as current_qty
      from erp.qc_inspection_items i
      where i.inspection_id=new.id
        and i.source_laundry_receipt_line_id is not null
      group by i.source_laundry_receipt_line_id
      order by i.source_laundry_receipt_line_id
    loop
      select lrl.qty_good_received,ld.po_id,lr.status
        into v_source_good,v_source_po,v_source_status
      from erp.laundry_receipt_lines lrl
      join erp.laundry_receipts lr on lr.id=lrl.receipt_id
      join erp.laundry_delivery_lines ldl on ldl.id=lrl.delivery_line_id
      join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
      where lrl.id=r.source_id
      for update of lrl;

      if v_source_po is distinct from new.po_id or v_source_status<>'POSTED' then
        raise exception 'QC laundry source must still be a POSTED receipt from the same PO at posting time';
      end if;

      select coalesce(sum(i2.qty_good_pcs+i2.qty_bs_pcs),0)::bigint into v_prior
      from erp.qc_inspection_items i2
      join erp.qc_inspections q2 on q2.id=i2.inspection_id
      where i2.source_laundry_receipt_line_id=r.source_id
        and q2.status='POSTED'
        and q2.id<>new.id;

      v_current:=coalesce(r.current_qty,0);
      if v_prior+v_current>coalesce(v_source_good,0) then
        raise exception 'QC accounted quantity exceeds GOOD quantity physically returned from laundry at posting. Received %, already QC %, this QC %',
          coalesce(v_source_good,0),v_prior,v_current;
      end if;
    end loop;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_qc_posting_consistency"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_rework_posted_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
BEGIN
  IF current_user IN ('postgres','service_role','supabase_admin') THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
  IF TG_OP='INSERT' THEN
    IF COALESCE(NEW.cost_posted,false) OR NEW.good_fg_lot_id IS NOT NULL THEN RAISE EXCEPTION 'Rework posting fields are system-managed'; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN
    IF OLD.cost_posted THEN RAISE EXCEPTION 'Posted rework cannot be deleted directly'; END IF;
    RETURN OLD;
  END IF;
  IF OLD.cost_posted THEN RAISE EXCEPTION 'Posted rework is frozen; use controlled correction/reversal'; END IF;
  IF NEW.cost_posted IS DISTINCT FROM OLD.cost_posted OR NEW.good_fg_lot_id IS DISTINCT FROM OLD.good_fg_lot_id THEN
    RAISE EXCEPTION 'Rework cost/FG posting fields are system-managed';
  END IF;
  RETURN NEW;
END;$function$;

alter function "erp"."guard_rework_posted_state"() owner to "postgres";

