CREATE OR REPLACE FUNCTION erp.guard_scrap_batch_after_sale()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if current_user in ('postgres','service_role','supabase_admin') then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if exists(select 1 from erp.scrap_sales ss where ss.scrap_batch_id=old.id and ss.status='POSTED') then
    if tg_op='DELETE' then raise exception 'Scrap batch with posted sales cannot be deleted'; end if;
    if new.weight_kg is distinct from old.weight_kg
       or new.material_id is distinct from old.material_id
       or new.source_cutting_group_id is distinct from old.source_cutting_group_id
       or new.location_id is distinct from old.location_id then
      raise exception 'Scrap batch source/weight is frozen after first posted sale';
    end if;
  end if;
  if tg_op='DELETE' then return old; else return new; end if;
end;$function$;

