CREATE OR REPLACE FUNCTION erp.guard_stock_policy_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_key text;
begin
  if current_setting('app.stock_policy_write', true) is distinct from 'on' then
    raise exception 'Stock policy history is write-protected; use erp_set_fg_stock_policy_v1';
  end if;

  if tg_op = 'DELETE' then
    raise exception 'Stock policy history cannot be deleted';
  end if;

  if tg_op = 'UPDATE'
     and (new.subject_type, new.product_id, new.material_id, new.location_id,
          new.basis_source, new.manual_reorder_point_qty,
          new.manual_target_stock_qty, new.minimum_sample_days,
          new.effective_from, new.reason, new.formula_version,
          new.approved_by, new.created_by, new.created_at)
         is distinct from
         (old.subject_type, old.product_id, old.material_id, old.location_id,
          old.basis_source, old.manual_reorder_point_qty,
          old.manual_target_stock_qty, old.minimum_sample_days,
          old.effective_from, old.reason, old.formula_version,
          old.approved_by, old.created_by, old.created_at) then
    raise exception 'Existing stock policy facts are immutable; only effective_to may be closed';
  end if;

  v_key := new.subject_type || '|' ||
    coalesce(new.product_id::text, new.material_id::text) || '|' ||
    coalesce(new.location_id::text, '*');
  perform pg_advisory_xact_lock(hashtextextended('STOCK_POLICY|' || v_key, 0));

  if exists (
    select 1
    from erp.stock_policy_versions p
    where p.subject_type = new.subject_type
      and p.id <> new.id
      and p.product_id is not distinct from new.product_id
      and p.material_id is not distinct from new.material_id
      and p.location_id is not distinct from new.location_id
      and daterange(p.effective_from, coalesce(p.effective_to + 1, 'infinity'::date), '[)')
          && daterange(new.effective_from, coalesce(new.effective_to + 1, 'infinity'::date), '[)')
  ) then
    raise exception 'Stock policy periods cannot overlap for the same item/location';
  end if;

  return new;
end;
$function$;

alter function "erp"."guard_stock_policy_version"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_supplier_return_not_before_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_bad record;
begin
  if new.status = 'POSTED' and old.status is distinct from 'POSTED' then
    select mph.purchase_number,
           mph.physical_at as purchase_physical_at,
           mr.roll_number,
           mr.received_at as roll_received_at
      into v_bad
    from erp.material_supplier_return_items ri
    join erp.material_purchase_items mpi on mpi.id=ri.purchase_item_id
    join erp.material_purchase_headers mph on mph.id=mpi.purchase_id
    left join erp.material_rolls mr on mr.id=ri.roll_id
    where ri.return_id=new.id
      and (
        new.physical_at < mph.physical_at
        or (mr.id is not null and new.physical_at < mr.received_at)
      )
    order by greatest(mph.physical_at,coalesce(mr.received_at,mph.physical_at)) desc
    limit 1;

    if v_bad.purchase_number is not null then
      raise exception 'Tanggal retur supplier (%) lebih awal dari barang sumber diterima pada pembelian % (%). Periksa tanggal retur; barang tidak dapat diretur sebelum secara fisik diterima.',
        new.physical_at,
        v_bad.purchase_number,
        greatest(v_bad.purchase_physical_at,coalesce(v_bad.roll_received_at,v_bad.purchase_physical_at));
    end if;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_supplier_return_not_before_source"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_supplier_return_source_capacity_on_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_purchased numeric(18,6);
  v_prior_posted numeric(18,6);
  v_current numeric(18,6);
begin
  if new.status='POSTED' and old.status is distinct from 'POSTED' then
    for r in
      select ri.purchase_item_id
      from erp.material_supplier_return_items ri
      where ri.return_id=new.id
      group by ri.purchase_item_id
      order by ri.purchase_item_id
    loop
      if r.purchase_item_id is null then
        raise exception 'Supplier return line must reference the source purchase item';
      end if;

      select mpi.qty into v_purchased
      from erp.material_purchase_items mpi
      join erp.material_purchase_headers mph on mph.id=mpi.purchase_id
      where mpi.id=r.purchase_item_id and mph.status='POSTED'
      for update of mpi;

      if v_purchased is null then
        raise exception 'Source purchase item must belong to a POSTED purchase';
      end if;

      select coalesce(sum(ri.qty),0) into v_prior_posted
      from erp.material_supplier_return_items ri
      join erp.material_supplier_returns rh on rh.id=ri.return_id
      where ri.purchase_item_id=r.purchase_item_id
        and rh.id<>new.id
        and rh.status='POSTED';

      select coalesce(sum(ri.qty),0) into v_current
      from erp.material_supplier_return_items ri
      where ri.return_id=new.id
        and ri.purchase_item_id=r.purchase_item_id;

      if v_prior_posted+v_current>v_purchased+0.000001 then
        raise exception 'Supplier return exceeds source purchase quantity at posting. Purchased %, already returned %, this return %. Correct/reverse the related supplier return first.',
          v_purchased,v_prior_posted,v_current;
      end if;
    end loop;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_supplier_return_source_capacity_on_post"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_system_managed_table()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ BEGIN IF current_user IN ('postgres','service_role','supabase_admin') THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF; RAISE EXCEPTION '% is system-managed; use ERP posting/reversal functions',TG_TABLE_NAME; END; $function$;

alter function "erp"."guard_system_managed_table"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_used_accessory_bom_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ DECLARE v_id uuid;v_bom uuid; BEGIN v_id:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;SELECT bom_version_id INTO v_bom FROM erp.accessory_bom_items WHERE id=v_id; IF EXISTS (SELECT 1 FROM erp.fg_accessory_cost_snapshots WHERE bom_item_id=v_id) OR EXISTS (SELECT 1 FROM erp.po_accessory_bom_commitments WHERE bom_version_id=v_bom) THEN RAISE EXCEPTION 'Accessory BOM item is financially committed by a PO/SKU; create a new effective-dated BOM version instead'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;END; $function$;

alter function "erp"."guard_used_accessory_bom_item"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_used_accessory_bom_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_last_basis timestamptz; BEGIN v_last_basis:=erp.accessory_bom_last_committed_at(OLD.id); IF v_last_basis IS NULL THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF; IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Financially committed accessory BOM version cannot be deleted'; END IF; IF NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.effective_from IS DISTINCT FROM OLD.effective_from OR NEW.is_active IS DISTINCT FROM OLD.is_active THEN RAISE EXCEPTION 'Committed accessory BOM identity/start/active flag is immutable; close it after commitment and create a successor version'; END IF; IF NEW.effective_to IS NOT NULL AND NEW.effective_to<=v_last_basis THEN RAISE EXCEPTION 'Accessory BOM effective_to cannot precede/equal its financial commitment time'; END IF;RETURN NEW;END; $function$;

alter function "erp"."guard_used_accessory_bom_version"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_used_accessory_price_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ DECLARE v_last_use timestamptz; BEGIN SELECT MAX(cmi.physical_at) INTO v_last_use FROM erp.contractor_material_issue_items cmii JOIN erp.contractor_material_issues cmi ON cmi.id=cmii.issue_id WHERE cmii.accessory_price_version_id=OLD.id; IF v_last_use IS NULL THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF; IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Used accessory price version cannot be deleted'; END IF; IF NEW.contractor_id IS DISTINCT FROM OLD.contractor_id OR NEW.category_id IS DISTINCT FROM OLD.category_id OR NEW.selling_price IS DISTINCT FROM OLD.selling_price OR NEW.selling_uom_code IS DISTINCT FROM OLD.selling_uom_code OR NEW.effective_from IS DISTINCT FROM OLD.effective_from THEN RAISE EXCEPTION 'Used accessory selling-price economics are immutable; create a successor price version'; END IF; IF NEW.effective_to IS NOT NULL AND NEW.effective_to<=v_last_use THEN RAISE EXCEPTION 'Accessory selling-price effective_to cannot invalidate a posted physical issue'; END IF;RETURN NEW;END; $function$;

alter function "erp"."guard_used_accessory_price_version"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_used_contractor_material_price_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_last_use timestamptz;
begin
  select max(i.physical_at) into v_last_use
  from erp.contractor_material_issue_items ii
  join erp.contractor_material_issues i on i.id=ii.issue_id
  where ii.material_price_version_id=old.id
    and i.status<>'REVERSED';

  if v_last_use is null then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;

  if tg_op='DELETE' then
    raise exception 'Harga material mandor yang sudah dipakai transaksi tidak boleh dihapus. Tutup periodenya dan buat harga baru.';
  end if;

  if new.contractor_id is distinct from old.contractor_id
     or new.material_id is distinct from old.material_id
     or new.selling_price is distinct from old.selling_price
     or new.effective_from is distinct from old.effective_from then
    raise exception 'Harga material mandor yang sudah dipakai transaksi tidak boleh ditulis ulang. Buat successor price version.';
  end if;

  if new.effective_to is not null and new.effective_to<=v_last_use then
    raise exception 'Tanggal akhir harga material mandor tidak boleh memotong transaksi yang sudah memakai harga ini.';
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_used_contractor_material_price_version"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_used_contractor_work_rate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
DECLARE v_last timestamptz;
BEGIN
  SELECT MAX(committed_at) INTO v_last FROM erp.po_work_component_snapshots WHERE source_contractor_rate_id=OLD.id;
  IF v_last IS NULL THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Used contractor work rate cannot be deleted'; END IF;
  IF NEW.contractor_id IS DISTINCT FROM OLD.contractor_id OR NEW.model_id IS DISTINCT FROM OLD.model_id OR
     NEW.work_component_id IS DISTINCT FROM OLD.work_component_id OR NEW.rate_per_pcs IS DISTINCT FROM OLD.rate_per_pcs OR
     NEW.effective_from IS DISTINCT FROM OLD.effective_from THEN
    RAISE EXCEPTION 'Used contractor work-rate economics are immutable; create a successor rate version';
  END IF;
  IF NEW.effective_to IS NOT NULL AND NEW.effective_to<=v_last THEN RAISE EXCEPTION 'Contractor work-rate effective_to cannot invalidate committed snapshot'; END IF;
  RETURN NEW;
END;$function$;

alter function "erp"."guard_used_contractor_work_rate"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_used_po_work_component_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ DECLARE v_id uuid; BEGIN IF current_user IN ('postgres','service_role','supabase_admin') THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;v_id:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; IF EXISTS (SELECT 1 FROM erp.work_completion_lines WHERE po_component_snapshot_id=v_id) THEN RAISE EXCEPTION 'PO work-component snapshot is already used by work completion and is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $function$;

alter function "erp"."guard_used_po_work_component_snapshot"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_used_product_price_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_last_use timestamptz;
begin
  select max(x.used_at) into v_last_use
  from (
    select sh.sale_date as used_at
    from erp.sales_items si
    join erp.sales_headers sh on sh.id=si.sale_id
    where si.product_id=old.product_id
      and sh.status<>'DRAFT'
      and sh.sale_date>=old.effective_from
      and (old.effective_to is null or sh.sale_date<old.effective_to)
    union all
    select fl.produced_at
    from erp.fg_lots fl
    where fl.product_id=old.product_id
      and fl.lot_origin='OPENING'
      and fl.produced_at>=old.effective_from
      and (old.effective_to is null or fl.produced_at<old.effective_to)
  ) x;

  if v_last_use is null then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;

  if tg_op='DELETE' then
    raise exception 'Harga jual historis yang sudah dipakai transaksi/opening tidak boleh dihapus. Tutup periodenya dan buat harga successor.';
  end if;

  if new.product_id is distinct from old.product_id
     or new.price is distinct from old.price
     or new.effective_from is distinct from old.effective_from then
    raise exception 'Harga jual historis yang sudah dipakai tidak boleh ditulis ulang. Buat successor price version dengan tanggal berlaku baru.';
  end if;

  if new.effective_to is not null and new.effective_to<=v_last_use then
    raise exception 'Tanggal akhir harga jual tidak boleh memotong transaksi/opening yang sudah memakai periode harga ini.';
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_used_product_price_version"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_vendor_invoice_post_date()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if new.status in ('POSTED','PARTIAL_PAID','PAID') and old.status is distinct from new.status
     and new.invoice_date>current_date then
    raise exception 'Tanggal invoice vendor laundry berada di masa depan. Periksa tanggal invoice sebelum posting.';
  end if;
  return new;
end$function$;

alter function "erp"."guard_vendor_invoice_post_date"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_work_bom_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended('WBOM:'||new.model_id::text,0));
  if new.is_active and exists(
    select 1 from erp.work_bom_versions x
    where x.model_id=new.model_id and x.id<>new.id and x.is_active
      and x.effective_from<coalesce(new.effective_to,'infinity'::timestamptz)
      and coalesce(x.effective_to,'infinity'::timestamptz)>new.effective_from
  ) then raise exception 'Overlapping active work BOM effective range'; end if;
  return new;
end$function$;

alter function "erp"."guard_work_bom_overlap"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_work_completion_posting_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_pickup timestamptz;
  v_effective bigint;
  r record;
  v_prior_completed bigint;
  v_prior_payable bigint;
begin
  if new.status='POSTED' and old.status is distinct from 'POSTED' then
    if new.cutting_group_id is null then
      raise exception 'Hasil kerja mandor wajib terkait Potongan. Pilih Potongan sebelum posting agar qty/upah/HPP tidak masuk ke grup yang salah.';
    end if;

    -- Serialize all work postings for the same Potongan so two tabs cannot both
    -- consume the same remaining component entitlement concurrently.
    perform 1 from erp.cutting_groups cg where cg.id=new.cutting_group_id for update;
    if not found then raise exception 'Potongan sumber hasil kerja tidak ditemukan'; end if;

    select cg.picked_up_at,coalesce(v.total_pcs,0)
      into v_pickup,v_effective
    from erp.cutting_groups cg
    left join erp.v_cutting_group_totals v on v.cutting_group_id=cg.id
    where cg.id=new.cutting_group_id and cg.po_id=new.po_id;

    if v_pickup is null then
      raise exception 'Potongan belum diambil mandor. Hasil kerja/upah tidak boleh dipost sebelum assignment/pickup fisik.';
    end if;
    if new.physical_at < v_pickup then
      raise exception 'Tanggal hasil kerja (%) lebih awal dari tanggal Potongan diambil mandor (%). Periksa tanggal sebelum posting.',new.physical_at,v_pickup;
    end if;
    if new.physical_at > clock_timestamp()+interval '5 minutes' then
      raise exception 'Tanggal/jam hasil kerja berada di masa depan. Periksa tanggal/jam sebelum posting.';
    end if;
    if v_effective<=0 then
      raise exception 'Potongan tidak memiliki qty efektif yang dapat menjadi dasar upah.';
    end if;

    for r in
      select l.id,l.work_component_id,l.qty_completed,l.qty_payable,wc.component_name
      from erp.work_completion_lines l
      join erp.work_components wc on wc.id=l.work_component_id
      where l.completion_id=new.id
      order by l.work_component_id,l.id
    loop
      select coalesce(sum(l2.qty_completed),0),coalesce(sum(l2.qty_payable),0)
        into v_prior_completed,v_prior_payable
      from erp.work_completion_lines l2
      join erp.work_completion_events e2 on e2.id=l2.completion_id
      where e2.cutting_group_id=new.cutting_group_id
        and l2.work_component_id=r.work_component_id
        and e2.status='POSTED'
        and e2.id<>new.id;

      if v_prior_completed+r.qty_completed>v_effective then
        raise exception 'Qty selesai komponen % melebihi Potongan efektif. Potongan %, sudah dipost %, input %, maksimum %.',
          r.component_name,new.cutting_group_id,v_prior_completed,r.qty_completed,v_effective;
      end if;
      if v_prior_payable+r.qty_payable>v_effective then
        raise exception 'Qty bayar komponen % melebihi Potongan efektif. Sudah menjadi hak bayar %, input %, maksimum %. Koreksi hasil kerja, jangan membayar dua kali.',
          r.component_name,v_prior_payable,r.qty_payable,v_effective;
      end if;
    end loop;
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_work_completion_posting_consistency"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_worker_daily_rate_cache()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if new.daily_rate is distinct from old.daily_rate
     and current_setting('app.worker_rate_write', true) is distinct from 'on' then
    raise exception 'contractor_workers.daily_rate is a current cache; use erp_set_worker_daily_rate_v1';
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_worker_daily_rate_cache"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_worker_daily_rate_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_worker_id uuid := case when tg_op = 'DELETE' then old.worker_id else new.worker_id end;
begin
  if current_setting('app.worker_rate_write', true) is distinct from 'on' then
    raise exception 'Worker rate history is write-protected; use erp_set_worker_daily_rate_v1';
  end if;

  if tg_op = 'DELETE' then
    raise exception 'Worker rate history cannot be deleted';
  end if;

  if tg_op = 'UPDATE'
     and (new.worker_id, new.daily_rate, new.effective_from, new.change_reason,
          new.created_by, new.created_at)
         is distinct from
         (old.worker_id, old.daily_rate, old.effective_from, old.change_reason,
          old.created_by, old.created_at) then
    raise exception 'Existing worker rate facts are immutable; only effective_to may be closed';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('WORKER_RATE|' || v_worker_id::text, 0));

  if exists (
    select 1
    from erp.worker_daily_rate_versions r
    where r.worker_id = v_worker_id
      and r.id <> coalesce(new.id, gen_random_uuid())
      and daterange(r.effective_from, coalesce(r.effective_to + 1, 'infinity'::date), '[)')
          && daterange(new.effective_from, coalesce(new.effective_to + 1, 'infinity'::date), '[)')
  ) then
    raise exception 'Worker daily-rate periods cannot overlap';
  end if;

  return new;
end;
$function$;

alter function "erp"."guard_worker_daily_rate_version"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.guard_worker_employment_period()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_worker_id uuid := case when tg_op = 'DELETE' then old.worker_id else new.worker_id end;
begin
  if current_setting('app.worker_employment_write', true) is distinct from 'on' then
    raise exception 'Worker employment history is write-protected; use erp_save_worker_roster_v1';
  end if;
  if tg_op = 'DELETE' then
    raise exception 'Worker employment history cannot be deleted';
  end if;
  if tg_op = 'UPDATE'
     and (new.worker_id, new.started_on, new.start_reason, new.created_by, new.created_at)
         is distinct from
         (old.worker_id, old.started_on, old.start_reason, old.created_by, old.created_at) then
    raise exception 'Existing employment starts are immutable; only the stop fact may be added';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('WORKER_EMPLOYMENT|' || v_worker_id::text, 0));
  if exists (
    select 1
    from erp.worker_employment_periods e
    where e.worker_id = v_worker_id
      and e.id <> new.id
      and daterange(e.started_on, coalesce(e.ended_on + 1, 'infinity'::date), '[)')
          && daterange(new.started_on, coalesce(new.ended_on + 1, 'infinity'::date), '[)')
  ) then
    raise exception 'Worker employment periods cannot overlap';
  end if;
  return new;
end;
$function$;

alter function "erp"."guard_worker_employment_period"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.has_permission(p_permission_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_jwt_role text;v_allowed boolean:=false;
begin
  begin
    v_jwt_role:=coalesce(auth.jwt()->>'role','');
  exception when others then
    v_jwt_role:='';
  end;
  if v_jwt_role='service_role' then return true; end if;
  select case
    when r.is_protected and r.role_code='OWNER' then true
    else exists(
      select 1
      from erp.app_role_permissions rp
      join erp.app_permissions p on p.permission_key=rp.permission_key and p.is_active
      where rp.role_id=r.id and rp.permission_key=p_permission_key
    ) end
  into v_allowed
  from erp.app_users u
  join erp.app_roles r on r.id=u.role_id and r.is_active
  where u.auth_user_id=auth.uid() and u.is_active
  limit 1;
  return coalesce(v_allowed,false);
end
$function$;

alter function "erp"."has_permission"(p_permission_key text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.list_my_reminders_v1(p_filter text DEFAULT 'ACTIVE'::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid := erp.require_manual_reminder_actor();
  v_filter text := upper(coalesce(nullif(btrim(p_filter), ''), 'ACTIVE'));
  v_items jsonb;
  v_counts jsonb;
begin
  if v_filter not in ('ACTIVE','OPEN','DONE','CANCELLED','ALL') then
    raise exception 'Reminder filter must be ACTIVE, OPEN, DONE, CANCELLED, or ALL';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 200 then
    raise exception 'Reminder limit must be between 1 and 200';
  end if;

  select coalesce(jsonb_agg(q.item order by q.status_rank, q.priority_rank, q.sort_at, q.id), '[]'::jsonb)
  into v_items
  from (
    select
      r.id,
      case r.status when 'OPEN' then 0 when 'DONE' then 1 else 2 end as status_rank,
      case r.priority when 'URGENT' then 0 when 'NORMAL' then 1 else 2 end as priority_rank,
      case when r.status = 'OPEN' then r.due_at else r.updated_at end as sort_at,
      jsonb_build_object(
        'id', r.id,
        'title', r.title,
        'note', r.note,
        'due_at', r.due_at,
        'priority', r.priority,
        'module', r.module,
        'status', r.status,
        'completed_at', r.completed_at,
        'cancelled_at', r.cancelled_at,
        'cancellation_reason', r.cancellation_reason,
        'created_at', r.created_at,
        'updated_at', r.updated_at,
        'row_version', r.row_version
      ) as item
    from erp.manual_reminders r
    where r.owner_user_id = v_actor
      and (
        v_filter = 'ALL'
        or (v_filter = 'ACTIVE' and r.status in ('OPEN','DONE'))
        or r.status = v_filter
      )
    order by
      case r.status when 'OPEN' then 0 when 'DONE' then 1 else 2 end,
      case r.priority when 'URGENT' then 0 when 'NORMAL' then 1 else 2 end,
      case when r.status = 'OPEN' then r.due_at else r.updated_at end,
      r.id
    limit p_limit
  ) q;

  select jsonb_build_object(
    'open', count(*) filter (where r.status = 'OPEN'),
    'done', count(*) filter (where r.status = 'DONE'),
    'cancelled', count(*) filter (where r.status = 'CANCELLED')
  ) into v_counts
  from erp.manual_reminders r
  where r.owner_user_id = v_actor;

  return jsonb_build_object(
    'items', v_items,
    'counts', v_counts,
    'read_at', statement_timestamp()
  );
end;
$function$;

alter function "erp"."list_my_reminders_v1"(p_filter text, p_limit integer) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.list_patterns_v1(p_status text DEFAULT 'ACTIVE'::text, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_status text:=upper(coalesce(nullif(btrim(p_status),''),'ACTIVE'));
  v_query text:=lower(nullif(btrim(p_query),''));
begin
  if not erp.has_permission('master.pattern.view')
     and not erp.has_permission('production.cutting.view')
     and not erp.has_permission('production.wip.view') then
    raise exception using errcode='42501',message='PERMISSION_DENIED: master.pattern.view or production lookup access';
  end if;
  if v_status not in ('ACTIVE','INACTIVE','ALL') then raise exception 'status must be ACTIVE, INACTIVE, or ALL'; end if;
  if p_limit is null or p_limit<1 or p_limit>200 then raise exception 'limit must be between 1 and 200'; end if;
  if p_offset is null or p_offset<0 then raise exception 'offset must be nonnegative'; end if;
  return jsonb_build_object(
    'status',v_status,'query',v_query,'limit',p_limit,'offset',p_offset,
    'total',(
      select count(*) from erp.production_patterns p
      where (v_status='ALL' or p.is_active=(v_status='ACTIVE'))
        and (v_query is null or lower(concat_ws(' ',p.pattern_code,p.revision,p.pattern_name)) like '%'||v_query||'%')
    ),
    'rows',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',x.id,'code',x.pattern_code,'revision',x.revision,'name',x.pattern_name,
        'sort_order',x.sort_order,'is_active',x.is_active,'row_version',x.row_version,
        'updated_at',x.updated_at,'updated_by',x.updated_by_name,'usage_count',x.usage_count
      ) order by x.sort_order,x.pattern_code,x.revision,x.id)
      from (
        select p.*,u.full_name as updated_by_name,(
          select count(*) from erp.cutting_groups g where g.pattern_id=p.id
        ) usage_count
        from erp.production_patterns p left join erp.app_users u on u.id=p.updated_by
        where (v_status='ALL' or p.is_active=(v_status='ACTIVE'))
          and (v_query is null or lower(concat_ws(' ',p.pattern_code,p.revision,p.pattern_name)) like '%'||v_query||'%')
        order by p.sort_order,p.pattern_code,p.revision,p.id
        limit p_limit offset p_offset
      ) x
    ),'[]'::jsonb)
  );
end
$function$;

alter function "erp"."list_patterns_v1"(p_status text, p_query text, p_limit integer, p_offset integer) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.lock_current_hpp_per_pcs(p_lot_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
