CREATE OR REPLACE FUNCTION erp.lock_supplier_return_source_purchases(p_return_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare r record;
begin
  perform erp.require_internal();
  for r in
    select distinct mpi.purchase_id
    from erp.material_supplier_return_items ri
    join erp.material_purchase_items mpi on mpi.id=ri.purchase_item_id
    where ri.return_id=p_return_id
