CREATE OR REPLACE FUNCTION erp.material_purchase_current_unit_cost(p_purchase_item_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  i erp.material_purchase_items%rowtype;
  v_basis_qty numeric;
  v_invoice_delta numeric;
  v_cost numeric;
begin
  select * into i from erp.material_purchase_items where id=p_purchase_item_id;
  if i.id is null then return null; end if;

  if exists(
    select 1 from erp.material_supplier_invoice_lines l
    join erp.material_supplier_invoices h on h.id=l.invoice_id
    where l.purchase_item_id=i.id and h.status='POSTED'
  ) then
    v_basis_qty:=erp.material_purchase_invoice_capacity(i.id);
    if v_basis_qty<=0 then return i.unit_price; end if;
    select coalesce(sum(l.net_amount-(l.qty_invoiced*i.unit_price)),0)
    into v_invoice_delta
    from erp.material_supplier_invoice_lines l
    join erp.material_supplier_invoices h on h.id=l.invoice_id
    where l.purchase_item_id=i.id and h.status='POSTED';
    return greatest(((v_basis_qty*i.unit_price)+v_invoice_delta)/v_basis_qty,0);
  end if;

  select ci.new_unit_price into v_cost
  from erp.material_purchase_cost_correction_items ci
  join erp.material_purchase_cost_corrections c on c.id=ci.correction_id
  where ci.purchase_item_id=i.id and c.status='POSTED'
  order by c.post_seq desc,c.posted_at desc,c.id desc limit 1;
  return coalesce(v_cost,i.unit_price);
end;
$function$;

alter function "erp"."material_purchase_current_unit_cost"(p_purchase_item_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.merge_eligible_work_into_payroll_v2(p_payroll_id uuid, p_lines jsonb, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_payroll erp.payroll_settlements%rowtype;
  v_line jsonb;
  v_eligible record;
  v_qty integer;
  v_added_qty integer:=0;
  v_added_amount numeric(24,2):=0;
begin
  perform erp.require_internal();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if coalesce(jsonb_typeof(p_lines),'null')<>'array' then
    raise exception 'Eligible lines must be a JSON array';
  end if;
  if jsonb_array_length(p_lines)=0 then raise exception 'At least one eligible line is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'payroll_id',p_payroll_id,'lines',p_lines,'expected_version',p_expected_version
  ));
  v_cached:=erp._idempotency_begin('merge_eligible_work_into_payroll_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_payroll from erp.payroll_settlements where id=p_payroll_id for update;
  if v_payroll.id is null then raise exception 'Nota payroll not found'; end if;
  if v_payroll.status not in ('DRAFT','CALCULATED','REVIEW') then
    raise exception 'APPROVED/PAID/REVERSED Nota is locked; use reversal/correction';
  end if;
  if v_payroll.row_version<>p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_payroll.row_version;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_payroll.contractor_id::text,0));

  for v_line in
    select value from jsonb_array_elements(p_lines)
    order by value->>'source_type',value->>'source_id'
  loop
    if upper(v_line->>'source_type')='PRODUCTION' then
      perform 1 from erp.work_completion_lines
      where id=(v_line->>'source_id')::uuid for update;
    elsif upper(v_line->>'source_type')='REWORK' then
      perform 1 from erp.rework_component_lines
      where id=(v_line->>'source_id')::uuid for update;
    else
      raise exception 'Unknown eligible source_type';
    end if;

    select * into v_eligible
    from erp.v_payroll_eligible_work_lines e
    where e.source_type=upper(v_line->>'source_type')
      and e.source_id=(v_line->>'source_id')::uuid;
    if v_eligible.source_id is null then raise exception 'Selected work line is no longer eligible'; end if;
    if v_eligible.contractor_id<>v_payroll.contractor_id then
      raise exception 'Eligible work belongs to a different Mandor';
    end if;
    if v_eligible.eligible_at::date>v_payroll.period_end then
      raise exception 'Eligible work is after the Nota period end';
    end if;
    v_qty:=coalesce(nullif(v_line->>'qty','')::integer,v_eligible.remaining_qty);
    if v_qty<=0 or v_qty>v_eligible.remaining_qty then
      raise exception 'Requested qty % exceeds remaining eligible qty %',v_qty,v_eligible.remaining_qty;
    end if;
    insert into erp.payroll_work_items(
      payroll_id,po_id,work_component_id,source_type,source_id,qty_payable,rate_snapshot
    ) values(
      v_payroll.id,v_eligible.po_id,v_eligible.work_component_id,
      v_eligible.source_type,v_eligible.source_id,v_qty,v_eligible.rate_snapshot
    )
    on conflict (payroll_id,source_type,source_id,work_component_id) do update
    set qty_payable=erp.payroll_work_items.qty_payable+excluded.qty_payable,
        rate_snapshot=excluded.rate_snapshot;
    v_added_qty:=v_added_qty+v_qty;
    v_added_amount:=v_added_amount+round(v_qty*v_eligible.rate_snapshot,2);
  end loop;

  perform erp.recalculate_payroll(v_payroll.id);
  select * into v_payroll from erp.payroll_settlements where id=v_payroll.id;
  v_response:=jsonb_build_object(
    'payroll_id',v_payroll.id,'status',v_payroll.status,
    'row_version',v_payroll.row_version,'added_qty',v_added_qty,
    'added_amount',v_added_amount,'net_payable',v_payroll.net_payable
  );
  return erp._idempotency_complete('merge_eligible_work_into_payroll_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."merge_eligible_work_into_payroll_v2"(p_payroll_id uuid, p_lines jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.move_fg_stock_card_row(p_movement_id uuid, p_direction text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_dir text:=upper(trim(coalesce(p_direction,'')));
  v_pos integer;
  v_count integer;
begin
  perform erp.require_internal();
  if v_dir not in ('UP','DOWN') then raise exception 'Arah urutan Mutasi Stok harus UP atau DOWN'; end if;
  perform pg_advisory_xact_lock(hashtextextended('FGBOOK|GLOBAL',0));
  select row_no into v_pos from (
    select id,row_number() over(order by book_order,id)::integer row_no from erp.fg_stock_movements
  ) x where id=p_movement_id;
  if v_pos is null then raise exception 'Baris Mutasi Stok tidak ditemukan'; end if;
  select count(*) into v_count from erp.fg_stock_movements;
  if v_dir='UP' then
    if v_pos>1 then perform erp.move_fg_stock_card_row_to_position(p_movement_id,v_pos-1); end if;
  else
    if v_pos<v_count then perform erp.move_fg_stock_card_row_to_position(p_movement_id,v_pos+1); end if;
  end if;
end;
$function$;

alter function "erp"."move_fg_stock_card_row"(p_movement_id uuid, p_direction text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.move_fg_stock_card_row_to_position(p_movement_id uuid, p_target_row_no integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_cur erp.fg_stock_movements%rowtype;
  v_old_pos integer;
  v_target integer;
  v_count integer;
  v_prev_order bigint;
  v_next_order bigint;
  v_new_order bigint;
  r record;
begin
  perform erp.require_internal();
  if p_target_row_no is null or p_target_row_no<1 then
    raise exception 'Posisi tujuan Mutasi Stok harus minimal 1';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('FGBOOK|GLOBAL',0));
  select * into v_cur from erp.fg_stock_movements where id=p_movement_id for update;
  if v_cur.id is null then raise exception 'Baris Mutasi Stok tidak ditemukan'; end if;

  select count(*) into v_count from erp.fg_stock_movements;
  if v_count<=1 then return; end if;
  v_target:=least(p_target_row_no,v_count);

  select row_no into v_old_pos
  from (
    select id,row_number() over(order by book_order,id)::integer row_no
    from erp.fg_stock_movements
  ) x where id=v_cur.id;

  if v_old_pos=v_target then return; end if;

  -- Neighbours in the final list after removing the dragged row.
  select max(case when pos=v_target-1 then book_order end),
         max(case when pos=v_target then book_order end)
    into v_prev_order,v_next_order
  from (
    select book_order,row_number() over(order by book_order,id)::integer pos
    from erp.fg_stock_movements
    where id<>v_cur.id
  ) q;

  if v_target=1 then v_prev_order:=null; end if;
  if v_target=v_count then v_next_order:=null; end if;

  if v_prev_order is null then
    v_new_order:=v_next_order-1000000;
  elsif v_next_order is null then
    v_new_order:=v_prev_order+1000000;
  elsif v_next_order-v_prev_order>1 then
    v_new_order:=v_prev_order + ((v_next_order-v_prev_order)/2);
  else
    -- Rare rebalance when repeated inserts consume the rank gap.
    for r in
      select id,row_number() over(order by book_order,id)::bigint rn
      from erp.fg_stock_movements
      order by book_order,id
    loop
      update erp.fg_stock_movements set book_order=r.rn*1000000 where id=r.id;
    end loop;
    select max(case when pos=v_target-1 then book_order end),
           max(case when pos=v_target then book_order end)
      into v_prev_order,v_next_order
    from (
      select book_order,row_number() over(order by book_order,id)::integer pos
      from erp.fg_stock_movements
      where id<>v_cur.id
    ) q;
    if v_target=1 then v_prev_order:=null; end if;
    if v_target=v_count then v_next_order:=null; end if;
    if v_prev_order is null then v_new_order:=v_next_order-1000000;
    elsif v_next_order is null then v_new_order:=v_prev_order+1000000;
    else v_new_order:=v_prev_order+((v_next_order-v_prev_order)/2);
    end if;
  end if;

  update erp.fg_stock_movements set book_order=v_new_order where id=v_cur.id;

  -- Keep future inserted movements at the end of the global presentation book.
  perform setval(
    'erp.fg_stock_book_order_seq',
    greatest(coalesce((select max(book_order) from erp.fg_stock_movements),0)+1000000,1),
    false
  );

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason,new_data)
  values('fg_stock_movements',v_cur.id,'UPDATE',erp.current_app_user_id(),
    'Urutan tampilan buku Mutasi Stok FG dipindah global dengan drag/drop; chronology, saldo resmi, FIFO/HPP, dan jurnal tidak berubah',
    jsonb_build_object('old_book_row',v_old_pos,'new_book_row',v_target,'presentation_only',true,'scope','GLOBAL_FG_MUTATION_BOOK'));
end;
$function$;

alter function "erp"."move_fg_stock_card_row_to_position"(p_movement_id uuid, p_target_row_no integer) owner to "postgres";

