CREATE OR REPLACE FUNCTION erp.normalize_accessory_purchase_uom()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_type varchar(20);v_base varchar(20);v_cat uuid;v_at timestamptz;v_factor numeric(18,6);v_dimension varchar(20); BEGIN SELECT material_type,unit_code,accessory_category_id INTO v_type,v_base,v_cat FROM erp.materials WHERE id=NEW.material_id; IF v_type<>'ACCESSORY' THEN RETURN NEW; END IF; IF v_cat IS NULL THEN RAISE EXCEPTION 'Accessory material must have a category before purchase'; END IF;SELECT physical_at INTO v_at FROM erp.material_purchase_headers WHERE id=NEW.purchase_id; IF v_at IS NULL THEN RAISE EXCEPTION 'Purchase header must exist before accessory lines'; END IF; IF NEW.purchase_qty_entered IS NULL THEN IF NEW.qty IS NULL OR NEW.qty<=0 THEN RAISE EXCEPTION 'Accessory purchase quantity must be positive'; END IF;NEW.purchase_qty_entered:=NEW.qty;NEW.purchase_uom_code:=v_base;v_factor:=1; ELSE IF NEW.purchase_qty_entered<=0 THEN RAISE EXCEPTION 'Accessory purchase entered quantity must be positive'; END IF;NEW.purchase_uom_code:=COALESCE(NEW.purchase_uom_code,v_base);v_factor:=erp.accessory_uom_factor(v_cat,NEW.purchase_uom_code,v_at);NEW.qty:=NEW.purchase_qty_entered*v_factor; END IF;NEW.purchase_uom_factor_snapshot:=v_factor; IF NEW.purchase_price_per_uom_snapshot IS NOT NULL THEN IF NEW.purchase_price_per_uom_snapshot<0 THEN RAISE EXCEPTION 'Accessory purchase price cannot be negative'; END IF;NEW.unit_price:=NEW.purchase_price_per_uom_snapshot/v_factor; ELSE IF NEW.unit_price IS NULL OR NEW.unit_price<0 THEN RAISE EXCEPTION 'Accessory purchase price is required'; END IF;NEW.purchase_price_per_uom_snapshot:=NEW.unit_price*v_factor; END IF;SELECT dimension INTO v_dimension FROM erp.uom_definitions WHERE unit_code=v_base; IF v_dimension='COUNT' AND ABS(NEW.qty-round(NEW.qty))>0.000001 THEN RAISE EXCEPTION 'Count-based accessory purchase converts to fractional base pieces'; END IF;RETURN NEW;END; $function$;

alter function "erp"."normalize_accessory_purchase_uom"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.normalize_attendance_paid_fraction()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ BEGIN IF NEW.status IN ('ABSENT','OFF') THEN NEW.paid_fraction:=0; ELSIF NEW.status='HALF_DAY' THEN IF TG_OP='INSERT' AND NEW.paid_fraction=1 THEN NEW.paid_fraction:=0.5; END IF; IF NEW.paid_fraction>0.5 THEN RAISE EXCEPTION 'HALF_DAY paid_fraction cannot exceed 0.5'; END IF; END IF; RETURN NEW; END; $function$;

alter function "erp"."normalize_attendance_paid_fraction"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.normalize_contractor_issue_item_uom_price()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_type varchar(20);
  v_base_uom varchar(20);
  v_category uuid;
  v_contractor uuid;
  v_at timestamptz;
  v_price record;
  v_factor numeric(18,6);
  v_dimension varchar(20);
begin
  select material_type,unit_code,accessory_category_id
    into v_type,v_base_uom,v_category
  from erp.materials where id=new.material_id;
  if v_type is null then raise exception 'Material not found'; end if;

  select contractor_id,physical_at into v_contractor,v_at
  from erp.contractor_material_issues where id=new.issue_id;
  if v_contractor is null or v_at is null then
    raise exception 'Contractor issue header must exist before adding lines';
  end if;

  if v_type='ACCESSORY' then
    if v_category is null then
      raise exception 'Accessory material % must be assigned to an accessory category before issue',new.material_id;
    end if;

    perform pg_advisory_xact_lock(hashtextextended('CAPRICE:'||v_contractor::text||':'||v_category::text,0));
    select x.* into v_price
    from erp.contractor_accessory_price_versions x
    where x.category_id=v_category
      and x.contractor_id is not distinct from v_contractor
      and x.effective_from<=v_at
      and (x.effective_to is null or x.effective_to>v_at)
    order by x.effective_from desc limit 1;

    if v_price.id is null then
      perform pg_advisory_xact_lock(hashtextextended('CAPRICE:GLOBAL:'||v_category::text,0));
      select x.* into v_price
      from erp.contractor_accessory_price_versions x
      where x.category_id=v_category
        and x.contractor_id is null
        and x.effective_from<=v_at
        and (x.effective_to is null or x.effective_to>v_at)
      order by x.effective_from desc limit 1;
    end if;

    if v_price.id is null then
      raise exception 'No active mandor selling price for accessory category % at %',v_category,v_at;
    end if;

    v_factor:=erp.accessory_uom_factor(v_category,v_price.selling_uom_code,v_at);
    if new.transaction_qty is null then
      if new.qty is null then raise exception 'Accessory issue requires transaction quantity'; end if;
      new.transaction_qty:=new.qty/v_factor;
    end if;
    if new.transaction_qty<=0 then raise exception 'Transaction quantity must be positive'; end if;
    new.transaction_uom_code:=v_price.selling_uom_code;
    new.base_qty_per_transaction_uom:=v_factor;
    new.qty:=new.transaction_qty*v_factor;

    select u.dimension into v_dimension
    from erp.accessory_categories ac
    join erp.uom_definitions u on u.unit_code=ac.base_uom_code
    where ac.id=v_category;
    if v_dimension='COUNT' and abs(new.qty-round(new.qty))>0.000001 then
      raise exception 'Count-based accessory issue must convert to a whole base-unit quantity; calculated %',new.qty;
    end if;

    new.unit_sale_price_snapshot:=v_price.selling_price;
    new.accessory_price_version_id:=v_price.id;
    new.material_price_version_id:=null;
  else
    if new.qty is null or new.qty<=0 then raise exception 'Issue base quantity must be positive'; end if;

    perform pg_advisory_xact_lock(hashtextextended('CMPRICE:'||v_contractor::text||':'||new.material_id::text,0));
    select x.* into v_price
    from erp.contractor_material_price_versions x
    where x.material_id=new.material_id
      and x.contractor_id is not distinct from v_contractor
      and x.effective_from<=v_at
      and (x.effective_to is null or x.effective_to>v_at)
    order by x.effective_from desc limit 1;

    if v_price.id is null then
      perform pg_advisory_xact_lock(hashtextextended('CMPRICE:GLOBAL:'||new.material_id::text,0));
      select x.* into v_price
      from erp.contractor_material_price_versions x
      where x.material_id=new.material_id
        and x.contractor_id is null
        and x.effective_from<=v_at
        and (x.effective_to is null or x.effective_to>v_at)
      order by x.effective_from desc limit 1;
    end if;

    if v_price.id is null then
      raise exception 'Harga jual material ke mandor belum diset untuk material % pada tanggal/jam %. Set harga material mandor dulu sebelum posting.',new.material_id,v_at;
    end if;

    new.transaction_qty:=coalesce(new.transaction_qty,new.qty);
    new.transaction_uom_code:=coalesce(new.transaction_uom_code,v_base_uom);
    new.base_qty_per_transaction_uom:=coalesce(new.base_qty_per_transaction_uom,1);
    if abs(new.qty-(new.transaction_qty*new.base_qty_per_transaction_uom))>0.000001 then
      raise exception 'Issue transaction UOM quantity does not reconcile to base quantity';
    end if;

    new.unit_sale_price_snapshot:=v_price.selling_price;
    new.material_price_version_id:=v_price.id;
    new.accessory_price_version_id:=null;
  end if;

  if new.unit_sale_price_snapshot is null or new.unit_sale_price_snapshot<0 then
    raise exception 'Issue selling price snapshot is required and cannot be negative';
  end if;
  return new;
end;
$function$;

alter function "erp"."normalize_contractor_issue_item_uom_price"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.normalize_cutting_group_pickup()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_contractor uuid;
begin
  if new.picked_up_at is not null then
    if new.picked_up_at<new.cut_at then
      raise exception 'Tanggal/jam diambil mandor tidak boleh lebih awal dari tanggal/jam potong';
    end if;
    if new.picked_up_at>clock_timestamp()+interval '5 minutes' then
      raise exception 'Tanggal/jam diambil mandor berada di masa depan';
    end if;
    select contractor_id into v_contractor from erp.production_orders where id=new.po_id;
    if v_contractor is null then raise exception 'Assign a mandor to the PO before marking cutting group as picked up'; end if;
    if new.status='CUT' then new.status:='PICKED_UP'; end if;
  end if;

  if tg_op='UPDATE' and old.picked_up_at is not null and new.picked_up_at is null then
    if old.material_issue_posted
       or exists(select 1 from erp.laundry_delivery_lines ldl join erp.laundry_deliveries ld on ld.id=ldl.delivery_id where ldl.cutting_group_id=old.id and ld.status not in('DRAFT','REVERSED'))
       or exists(select 1 from erp.work_completion_events w where w.cutting_group_id=old.id and w.status='POSTED')
       or exists(select 1 from erp.fg_lots fl where fl.cutting_group_id=old.id and fl.lot_origin<>'VOIDED_PRODUCTION') then
      raise exception 'Pickup date cannot be cleared after downstream use';
    end if;
    new.status:='CUT';
  end if;

  if new.picked_up_at is not null and tg_op='UPDATE' and old.picked_up_at is not null and new.status='CUT' then
    raise exception 'Picked-up cutting group cannot return to CUT status directly';
  end if;
  return new;
end;
$function$;

alter function "erp"."normalize_cutting_group_pickup"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.normalize_fg_adjustment_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_product uuid;
  v_origin text;
  v_hpp numeric(18,6);
begin
  select fl.product_id,fl.lot_origin,coalesce(ch.hpp_per_pcs,0)
    into v_product,v_origin,v_hpp
  from erp.fg_lots fl
  left join erp.v_current_hpp ch on ch.lot_id=fl.id
  where fl.id=new.lot_id;
  if v_product is null then raise exception 'FG lot adjustment tidak ditemukan'; end if;
  if v_origin='VOIDED_PRODUCTION' then raise exception 'Lot produksi ini sudah dibatalkan/void dan tidak boleh dipakai FG adjustment'; end if;
  if new.product_id is distinct from v_product then raise exception 'SKU adjustment tidak sama dengan SKU pada lot'; end if;
  new.unit_hpp_snapshot:=v_hpp;
  return new;
end;
$function$;

alter function "erp"."normalize_fg_adjustment_item"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.normalize_material_purchase_invoice_match_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if tg_op='INSERT' then
    new.receipt_price_source_snapshot:=new.price_source;
  elsif new.invoice_match_state in('UNMATCHED','DIRECT_FINAL')
        and old.invoice_match_state in('UNMATCHED','DIRECT_FINAL') then
    new.receipt_price_source_snapshot:=new.price_source;
  end if;

  if new.invoice_match_state in('PARTIAL','MATCHED') then
    new.price_source:='SUPPLIER_INVOICE';
    new.price_state:=case when new.invoice_match_state='MATCHED' then 'FINAL' else 'PARTIAL' end;
  elsif new.price_state='FINAL' then
    new.invoice_match_state:='DIRECT_FINAL';
  else
    new.invoice_match_state:='UNMATCHED';
  end if;
  return new;
end;
$function$;

alter function "erp"."normalize_material_purchase_invoice_match_state"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.normalize_sales_return_item_from_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_return_sale uuid;
  v_return_customer uuid;
  v_alloc_sale uuid;
  v_alloc_customer uuid;
  v_product uuid;
  v_lot uuid;
  v_hpp numeric(18,6);
  v_alloc_qty integer;
  v_sale_item_qty integer;
  v_sale_line_total numeric(24,6);
  v_max_refund numeric(24,6);
begin
  select sr.sale_id,sr.customer_id into v_return_sale,v_return_customer
  from erp.sales_returns sr where sr.id=new.return_id;
  if v_return_sale is null then raise exception 'Sales return must reference an original sale'; end if;

  select si.sale_id,sh.customer_id,si.product_id,ssa.lot_id,ssa.unit_hpp_snapshot,ssa.qty_pcs,si.qty_pcs,si.line_total
  into v_alloc_sale,v_alloc_customer,v_product,v_lot,v_hpp,v_alloc_qty,v_sale_item_qty,v_sale_line_total
  from erp.sale_stock_allocations ssa
  join erp.sales_items si on si.id=ssa.sale_item_id
  join erp.sales_headers sh on sh.id=si.sale_id
  where ssa.id=new.sale_stock_allocation_id;

  if v_alloc_sale is null then raise exception 'Original sale stock allocation not found'; end if;
  if v_alloc_sale<>v_return_sale then raise exception 'Return allocation does not belong to the selected original sale'; end if;
  if v_alloc_customer is distinct from v_return_customer then raise exception 'Return customer does not match original sale customer'; end if;
  if new.qty_pcs>v_alloc_qty then raise exception 'Return qty % exceeds qty % sold from this lot allocation',new.qty_pcs,v_alloc_qty; end if;
  if not exists (select 1 from erp.locations l where l.id=new.location_id and l.is_active=true and l.location_type='FG_WAREHOUSE') then
    raise exception 'Sales return destination must be an active FG warehouse';
  end if;

  v_max_refund:=case when v_sale_item_qty>0 then (v_sale_line_total/v_sale_item_qty)*new.qty_pcs else 0 end;
  if new.refund_amount>v_max_refund+0.01 then
    raise exception 'Refund amount % exceeds original net sales value % for returned qty',new.refund_amount,round(v_max_refund,2);
  end if;

  select coalesce(ch.hpp_per_pcs,v_hpp) into v_hpp
  from (select 1) x
  left join erp.v_current_hpp ch on ch.lot_id=v_lot;

  new.product_id:=v_product;
  new.lot_id:=v_lot;
  new.unit_hpp_snapshot:=v_hpp;
  return new;
end;
$function$;

alter function "erp"."normalize_sales_return_item_from_allocation"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.populate_payroll_draft(p_payroll_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.payroll_settlements%rowtype;
  r record;
  v_remaining numeric(24,6);
  v_apply numeric(24,6);
  v_budget numeric(24,6) := 0;
  v_attendance_required boolean;
begin
  perform erp.require_internal();
  select * into p from erp.payroll_settlements where id = p_payroll_id for update;
  if p.id is null or p.status not in ('DRAFT','CALCULATED','REVIEW') then
    raise exception 'Payroll draft cannot be rebuilt in current status';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p.contractor_id::text, 0));

  delete from erp.payroll_work_items where payroll_id = p.id;
  delete from erp.payroll_attendance_items where payroll_id = p.id;
  delete from erp.payroll_deductions
    where payroll_id = p.id and contractor_issue_item_id is not null;
  delete from erp.payroll_reimbursements
    where payroll_id = p.id and source_type = 'ACCESSORY_BOM';

  insert into erp.payroll_work_items(
    payroll_id, po_id, work_component_id, source_type, source_id,
    qty_payable, rate_snapshot
  )
  select p.id, e.po_id, e.work_component_id, e.source_type, e.source_id,
         e.remaining_qty, e.rate_snapshot
  from erp.v_payroll_eligible_work_lines e
  where e.contractor_id = p.contractor_id
    and e.eligible_at::date <= p.period_end
    and e.remaining_qty > 0
  order by e.eligible_at, e.source_type, e.source_id;

  select attendance_required into v_attendance_required
  from erp.contractors where id = p.contractor_id;

  if v_attendance_required then
    insert into erp.payroll_attendance_items(
      payroll_id, worker_id, attendance_record_id,
      paid_fraction_snapshot, daily_rate_snapshot,
      worker_rate_version_id, attendance_date_snapshot,
      worker_name_snapshot, job_description_snapshot
    )
    select
      p.id,
      ar.worker_id,
      ar.id,
      ar.paid_fraction,
      erp.require_worker_daily_rate_at(ar.worker_id, ar.attendance_date),
      erp.worker_daily_rate_version_id_at(ar.worker_id, ar.attendance_date),
      ar.attendance_date,
      cw.worker_name,
      cw.job_description
    from erp.attendance_records ar
    join erp.contractor_workers cw on cw.id = ar.worker_id
    left join erp.attendance_periods ap on ap.id = ar.attendance_period_id
    where ar.contractor_id = p.contractor_id
      and ar.attendance_date between p.period_start and p.period_end
      and cw.pay_scheme in ('DAILY','HYBRID')
      and ar.paid_fraction > 0
      and (ar.attendance_period_id is null or ap.status = 'POSTED')
      and coalesce(ar.record_lifecycle, 'POSTED') = 'POSTED'
    order by ar.attendance_date, ar.id;
  end if;

  insert into erp.payroll_reimbursements(
    payroll_id, amount, description, source_type, source_id, po_id
  )
  select p.id, round(e.amount, 2),
         'Accessory reimbursement from accepted GOOD FG',
         'ACCESSORY_BOM', e.id, e.po_id
  from erp.contractor_accessory_reimbursement_entitlements e
  where e.contractor_id = p.contractor_id
    and e.amount > 0
    and e.payroll_status <> 'CANCELLED'
    and e.physical_at::date <= p.period_end
    and not exists (
      select 1
      from erp.payroll_reimbursements pr
      join erp.payroll_settlements ps2 on ps2.id = pr.payroll_id
      where pr.source_type = 'ACCESSORY_BOM'
        and pr.source_id = e.id
        and ps2.id <> p.id
        and ps2.status <> 'REVERSED'
    )
  order by e.physical_at, e.id;

  update erp.contractor_accessory_reimbursement_entitlements e
  set payroll_status = 'ALLOCATED'
  where exists (
    select 1
    from erp.payroll_reimbursements pr
    where pr.payroll_id = p.id
      and pr.source_type = 'ACCESSORY_BOM'
      and pr.source_id = e.id
  );

  perform erp.recalculate_payroll(p.id);
  select greatest(net_payable, 0) into v_budget
  from erp.payroll_settlements where id = p.id;

  for r in
    select
      cmii.id,
      cmii.total_receivable,
      cmi.physical_at,
      cmii.total_receivable - coalesce((
        select sum(pd.amount)
        from erp.payroll_deductions pd
        join erp.payroll_settlements ps2 on ps2.id = pd.payroll_id
        where pd.contractor_issue_item_id = cmii.id
          and ps2.id <> p.id
          and ps2.status <> 'REVERSED'
      ), 0) as remaining_amount
    from erp.contractor_material_issue_items cmii
    join erp.contractor_material_issues cmi on cmi.id = cmii.issue_id
    where cmi.contractor_id = p.contractor_id
      and cmi.status = 'POSTED'
      and cmi.physical_at::date <= p.period_end
    order by cmi.physical_at, cmii.id
  loop
    exit when v_budget <= 0;
    v_remaining := greatest(r.remaining_amount, 0);
    v_apply := least(v_remaining, v_budget);
    if v_apply > 0 then
      insert into erp.payroll_deductions(
        payroll_id, deduction_type, contractor_issue_item_id, amount, notes
      ) values (
        p.id, 'MATERIAL_KASBON', r.id, round(v_apply, 2),
        'Auto capped outstanding material/accessory kasbon (FIFO)'
      );
      v_budget := greatest(v_budget - round(v_apply, 2), 0);
    end if;
  end loop;

  perform erp.recalculate_payroll(p.id);
  for r in
    select cmii.id
    from erp.contractor_material_issue_items cmii
    join erp.contractor_material_issues cmi on cmi.id = cmii.issue_id
    where cmi.contractor_id = p.contractor_id
      and cmi.status = 'POSTED'
  loop
    perform erp.refresh_contractor_issue_payroll_status(r.id);
  end loop;
end;
$function$;

alter function "erp"."populate_payroll_draft"(p_payroll_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_accessory_reimbursement_accrual(p_lot_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE l erp.fg_lots%ROWTYPE;p erp.production_orders%ROWTYPE;v_hpp numeric(24,6);v_reimburse numeric(24,6);v_variance numeric(24,6);v_lines jsonb:='[]'::jsonb; BEGIN PERFORM erp.require_internal();PERFORM erp.ensure_fg_accessory_cost_snapshot(p_lot_id);SELECT * INTO l FROM erp.fg_lots WHERE id=p_lot_id; IF l.id IS NULL OR l.lot_origin<>'PRODUCTION' THEN RETURN; END IF;SELECT * INTO p FROM erp.production_orders WHERE id=l.po_id;SELECT COALESCE(SUM(total_hpp_cost),0),COALESCE(SUM(total_reimbursement),0) INTO v_hpp,v_reimburse FROM erp.fg_accessory_cost_snapshots WHERE lot_id=l.id; IF v_hpp=0 AND v_reimburse=0 THEN RETURN; END IF; IF EXISTS (SELECT 1 FROM erp.journal_entries WHERE source_type='ACCESSORY_REIMBURSE_ACCRUAL' AND source_id=l.id AND status='POSTED') THEN RETURN; END IF; IF v_reimburse>0 AND p.contractor_id IS NULL THEN RAISE EXCEPTION 'Accessory reimbursement requires PO contractor'; END IF; IF v_hpp>0 THEN v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','WIP','debit',round(v_hpp,2),'credit',0,'contractor_id',p.contractor_id,'po_id',p.id,'product_id',l.product_id)); END IF;v_variance:=v_reimburse-v_hpp; IF v_variance>0.005 THEN v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','ACCESSORY_REIMBURSE_VARIANCE','debit',round(v_variance,2),'credit',0,'contractor_id',p.contractor_id,'po_id',p.id,'product_id',l.product_id)); ELSIF v_variance< -0.005 THEN v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','ACCESSORY_REIMBURSE_VARIANCE','debit',0,'credit',round(abs(v_variance),2),'contractor_id',p.contractor_id,'po_id',p.id,'product_id',l.product_id)); END IF; IF v_reimburse>0 THEN v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',0,'credit',round(v_reimburse,2),'contractor_id',p.contractor_id,'po_id',p.id,'product_id',l.product_id)); END IF; IF v_reimburse=0 AND v_hpp>0 THEN RAISE EXCEPTION 'Accessory HPP snapshot has cost but zero mandor reimbursement; configure reimbursement or use normal material issue flow'; END IF; IF jsonb_array_length(v_lines)>=2 THEN PERFORM erp.post_journal('ACCESSORY_REIMBURSE_ACCRUAL',l.id,l.produced_at::date,'Accessory HPP basis + mandor reimbursement entitlement from GOOD FG',v_lines); END IF; END; $function$;

alter function "erp"."post_accessory_reimbursement_accrual"(p_lot_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_attendance_period_v1(p_period_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'post_attendance_period_v1';
  v_hash text;
  v_cached jsonb;
  v_period erp.attendance_periods%rowtype;
  v_original erp.attendance_periods%rowtype;
  v_response jsonb;
  v_missing_count bigint;
  v_uncovered_rate_count bigint;
begin
  perform erp.require_internal();
  if p_period_id is null or p_expected_version is null then
    raise exception 'period_id and expected_version are required';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Attendance posting reason is required';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'period_id', p_period_id,
    'reason', p_reason,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_period
  from erp.attendance_periods
  where id = p_period_id
  for update;

  if v_period.id is null then raise exception 'Attendance period not found'; end if;
  if v_period.status <> 'DRAFT' then raise exception 'Only DRAFT attendance can be posted'; end if;
  if v_period.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_period.row_version;
  end if;

  if v_period.correction_of_period_id is not null then
    perform erp.require_owner_admin();
  end if;

  if (select attendance_required from erp.contractors where id = v_period.contractor_id)
     and not exists (
       select 1 from erp.attendance_records a where a.attendance_period_id = v_period.id
     ) then
    raise exception 'Attendance-required contractor needs attendance details before posting';
  end if;

  if (select attendance_required from erp.contractors where id = v_period.contractor_id) then
    select count(*) into v_missing_count
    from erp.contractor_workers w
    cross join lateral generate_series(
      v_period.period_start::timestamptz,
      v_period.period_end::timestamptz,
      interval '1 day'
    ) day_value
    where w.contractor_id = v_period.contractor_id
      and w.pay_scheme in ('DAILY','HYBRID')
      and erp.worker_is_employed_on(w.id, day_value::date)
      and not exists (
        select 1
        from erp.attendance_records a
        where a.attendance_period_id = v_period.id
          and a.worker_id = w.id
          and a.attendance_date = day_value::date
          and a.record_lifecycle = 'DRAFT'
      );

    if v_missing_count > 0 then
      raise exception 'Attendance period has % unrecorded eligible worker/day cells; blanks are not ABSENT or OFF',
        v_missing_count;
    end if;

    select count(*) into v_uncovered_rate_count
    from erp.contractor_workers w
    cross join lateral generate_series(
      v_period.period_start::timestamptz,
      v_period.period_end::timestamptz,
      interval '1 day'
    ) day_value
    where w.contractor_id = v_period.contractor_id
      and w.pay_scheme in ('DAILY','HYBRID')
      and erp.worker_is_employed_on(w.id, day_value::date)
      and erp.worker_daily_rate_at(w.id, day_value::date) is null;

    if v_uncovered_rate_count > 0 then
      raise exception 'Attendance period has % eligible worker/day cells without an effective daily rate',
        v_uncovered_rate_count;
    end if;
  end if;

  perform set_config('app.change_reason', p_reason, true);
  perform set_config('app.attendance_period_lifecycle', 'on', true);

  if v_period.correction_of_period_id is not null then
    select * into v_original
    from erp.attendance_periods
    where id = v_period.correction_of_period_id
    for update;

    if v_original.status <> 'POSTED' then
      raise exception 'Correction source is no longer POSTED';
    end if;
    if exists (
      select 1
      from erp.payroll_attendance_items pai
      join erp.payroll_settlements ps on ps.id = pai.payroll_id
      join erp.attendance_records ar on ar.id = pai.attendance_record_id
      where ar.attendance_period_id = v_original.id
        and ps.status <> 'REVERSED'
    ) then
      raise exception 'Attendance correction requires its consuming payroll to be reversed first';
    end if;
    if exists (
      select 1
      from erp.attendance_records source_row
      where source_row.attendance_period_id = v_original.id
        and not exists (
          select 1
          from erp.attendance_records replacement
          where replacement.attendance_period_id = v_period.id
            and replacement.worker_id = source_row.worker_id
            and replacement.attendance_date = source_row.attendance_date
            and replacement.supersedes_attendance_record_id = source_row.id
        )
    ) then
      raise exception 'Correction does not explicitly supersede every source attendance row';
    end if;

    update erp.attendance_records
    set record_lifecycle = 'CORRECTED',
        change_reason = p_reason,
        updated_by = erp.current_app_user_id()
    where attendance_period_id = v_original.id;

    update erp.attendance_periods
    set status = 'CORRECTED', posting_reason = p_reason
    where id = v_original.id;
  end if;

  if exists (
    select 1
    from erp.attendance_records draft_row
    join erp.attendance_records current_row
      on current_row.worker_id = draft_row.worker_id
     and current_row.attendance_date = draft_row.attendance_date
     and current_row.id <> draft_row.id
     and coalesce(current_row.record_lifecycle, 'POSTED') = 'POSTED'
    where draft_row.attendance_period_id = v_period.id
  ) then
    raise exception 'Another posted attendance fact already exists for worker/date';
  end if;

  update erp.attendance_records
  set record_lifecycle = 'POSTED',
      change_reason = p_reason,
      updated_by = erp.current_app_user_id()
  where attendance_period_id = v_period.id;

  update erp.attendance_periods
  set status = 'POSTED',
      posting_reason = p_reason,
      posted_at = clock_timestamp(),
      posted_by = erp.current_app_user_id()
  where id = v_period.id
  returning * into v_period;

  v_response := jsonb_build_object(
    'period_id', v_period.id,
    'status', v_period.status,
    'row_version', v_period.row_version,
    'posted_at', v_period.posted_at,
    'correction_of_period_id', v_period.correction_of_period_id
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."post_attendance_period_v1"(p_period_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_contractor_material_issue(p_issue_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.contractor_material_issues%rowtype;
  r record;
  v_accessory_cost numeric(24,6):=0;
  v_other_cost numeric(24,6):=0;
  v_receivable numeric(24,6):=0;
  v_line_cost numeric(24,6);
  v_line_receivable numeric(24,6);
begin
  perform erp.require_internal();
  select * into h from erp.contractor_material_issues where id=p_issue_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Contractor material issue must be DRAFT'; end if;
  if h.location_id is null then raise exception 'Issue location is required'; end if;
  if not exists (select 1 from erp.contractor_material_issue_items where issue_id=h.id) then raise exception 'Contractor material issue has no lines'; end if;

  if h.po_id is not null and not exists(
    select 1 from erp.production_orders po where po.id=h.po_id and po.contractor_id=h.contractor_id
  ) then
    raise exception 'Mandor issue tidak sama dengan mandor pada PO. Pilih PO milik mandor yang sama agar biaya, piutang mandor, dan HPP tidak silang.';
  end if;

  if h.po_id is null and exists(
    select 1
    from erp.contractor_material_issue_items cmii
    join erp.materials m on m.id=cmii.material_id
    where cmii.issue_id=h.id and m.material_type<>'ACCESSORY'
  ) then
    raise exception 'Material non-accessory yang diberikan ke mandor wajib terkait ke PO supaya biaya WIP dapat masuk ke HPP produksi. Pilih PO sebelum posting.';
  end if;

  update erp.contractor_material_issue_items set transaction_qty=transaction_qty where issue_id=h.id;
  for r in
    select cmii.*,m.material_type
    from erp.contractor_material_issue_items cmii
    join erp.materials m on m.id=cmii.material_id
    where cmii.issue_id=h.id
    order by cmii.id
  loop
    insert into erp.material_stock_movements(material_id,roll_id,location_id,movement_type,qty_signed,source_type,source_id,physical_at,created_by)
    values (r.material_id,r.roll_id,h.location_id,'CONTRACTOR_ISSUE',-r.qty,'CONTRACTOR_MATERIAL_ISSUE_ITEM',r.id,h.physical_at,erp.current_app_user_id());
    perform erp.recalculate_material_cost(r.material_id);
    update erp.contractor_material_issue_items
    set unit_cost_snapshot=coalesce((
      select unit_cost_snapshot from erp.material_stock_movements
      where source_type='CONTRACTOR_MATERIAL_ISSUE_ITEM' and source_id=r.id
      order by system_created_at desc limit 1
    ),0)
    where id=r.id;
    select qty*unit_cost_snapshot,total_receivable into v_line_cost,v_line_receivable
    from erp.contractor_material_issue_items where id=r.id;
    if r.material_type='ACCESSORY' then v_accessory_cost:=v_accessory_cost+coalesce(v_line_cost,0);
    else v_other_cost:=v_other_cost+coalesce(v_line_cost,0); end if;
    v_receivable:=v_receivable+coalesce(v_line_receivable,0);
  end loop;

  update erp.contractor_material_issues set status='POSTED' where id=h.id;
  if v_accessory_cost>0 then
    perform erp.post_journal('CONTRACTOR_ACCESSORY_STOCK_COST',h.id,h.physical_at::date,'Actual inventory cost of accessories physically sold/issued to mandor',jsonb_build_array(
      jsonb_build_object('mapping_key','ACCESSORY_RECOVERY_COGS','debit',round(v_accessory_cost,2),'credit',0,'contractor_id',h.contractor_id,'po_id',h.po_id),
      jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',0,'credit',round(v_accessory_cost,2),'contractor_id',h.contractor_id,'po_id',h.po_id)));
  end if;
  if v_other_cost>0 then
    perform erp.post_journal('CONTRACTOR_NONACCESSORY_MATERIAL_COST',h.id,h.physical_at::date,'Non-accessory material issued to contractor',jsonb_build_array(
      jsonb_build_object('mapping_key','WIP','debit',round(v_other_cost,2),'credit',0,'contractor_id',h.contractor_id,'po_id',h.po_id),
      jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',0,'credit',round(v_other_cost,2),'contractor_id',h.contractor_id,'po_id',h.po_id)));
  end if;
  if v_receivable>0 then
    perform erp.post_journal('CONTRACTOR_MATERIAL_RECEIVABLE',h.id,h.physical_at::date,'Material/accessory charge to mandor at configured selling price',jsonb_build_array(
      jsonb_build_object('mapping_key','CONTRACTOR_RECEIVABLE','debit',round(v_receivable,2),'credit',0,'contractor_id',h.contractor_id,'po_id',h.po_id),
      jsonb_build_object('mapping_key','MATERIAL_RECOVERY','debit',0,'credit',round(v_receivable,2),'contractor_id',h.contractor_id,'po_id',h.po_id)));
  end if;
end;
$function$;

alter function "erp"."post_contractor_material_issue"(p_issue_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_contractor_material_issue_v2(p_issue_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare v_hash text;v_cached jsonb;v_response jsonb;h erp.contractor_material_issues%rowtype;
begin
  perform erp.require_internal();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'Posting reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('id',p_issue_id,'expected_version',p_expected_version,'reason',btrim(p_reason)));
  v_cached:=erp._idempotency_begin('post_contractor_material_issue_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  select * into h from erp.contractor_material_issues where id=p_issue_id for update;
  if h.id is null then raise exception 'Contractor material issue not found'; end if;
  if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
  perform erp.post_contractor_material_issue(h.id);
  select * into h from erp.contractor_material_issues where id=h.id;
  v_response:=jsonb_build_object('contractor_material_issue_id',h.id,'status',h.status,'row_version',h.row_version);
  return erp._idempotency_complete('post_contractor_material_issue_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."post_contractor_material_issue_v2"(p_issue_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_cutting_material_issue(p_cutting_group_id uuid, p_location_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE g erp.cutting_groups%ROWTYPE;r record;v_total numeric(24,6):=0; BEGIN PERFORM erp.require_internal(); SELECT * INTO g FROM erp.cutting_groups WHERE id=p_cutting_group_id FOR UPDATE; IF g.id IS NULL THEN RAISE EXCEPTION 'Cutting group not found'; END IF; IF g.material_issue_posted THEN RAISE EXCEPTION 'Cutting material issue already posted'; END IF; FOR r IN SELECT cgr.*,mr.material_id FROM erp.cutting_group_rolls cgr JOIN erp.material_rolls mr ON mr.id=cgr.roll_id WHERE cgr.cutting_group_id=p_cutting_group_id LOOP INSERT INTO erp.material_stock_movements(material_id,roll_id,location_id,movement_type,qty_signed,source_type,source_id,physical_at,created_by) VALUES (r.material_id,r.roll_id,p_location_id,'CUTTING_ISSUE',-r.qty_issued,'CUTTING_GROUP',p_cutting_group_id,g.cut_at,erp.current_app_user_id()); PERFORM erp.recalculate_material_cost(r.material_id); UPDATE erp.cutting_group_rolls SET unit_cost_snapshot=(SELECT unit_cost_snapshot FROM erp.material_stock_movements WHERE source_type='CUTTING_GROUP' AND source_id=p_cutting_group_id AND roll_id=r.roll_id AND movement_type='CUTTING_ISSUE' ORDER BY system_created_at DESC LIMIT 1) WHERE id=r.id; v_total:=v_total+(r.qty_issued*COALESCE((SELECT unit_cost_snapshot FROM erp.material_stock_movements WHERE source_type='CUTTING_GROUP' AND source_id=p_cutting_group_id AND roll_id=r.roll_id AND movement_type='CUTTING_ISSUE' ORDER BY system_created_at DESC LIMIT 1),0)); END LOOP; UPDATE erp.cutting_groups SET material_issue_posted=true WHERE id=p_cutting_group_id; IF v_total>0 THEN PERFORM erp.post_journal('CUTTING_MATERIAL_ISSUE',p_cutting_group_id,g.cut_at::date,'Material issued to cutting',jsonb_build_array(jsonb_build_object('mapping_key','WIP','debit',round(v_total,2),'credit',0,'po_id',g.po_id),jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',0,'credit',round(v_total,2),'po_id',g.po_id))); END IF; END; $function$;

alter function "erp"."post_cutting_material_issue"(p_cutting_group_id uuid, p_location_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_cutting_material_returns(p_cutting_group_id uuid, p_location_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  g erp.cutting_groups%rowtype;
  r record;
  v_value numeric(24,6);
begin
  perform erp.require_internal();
  select * into g from erp.cutting_groups where id=p_cutting_group_id for update;
  if g.id is null or not g.material_issue_posted then raise exception 'Cutting issue must be posted first'; end if;
  if g.material_return_posted then raise exception 'Cutting return already posted'; end if;
  if p_location_id is null or not exists(select 1 from erp.locations where id=p_location_id and is_active=true and location_type='RAW_MATERIAL_WAREHOUSE') then
    raise exception 'Lokasi return cutting harus gudang bahan aktif';
  end if;
  if exists(select 1 from erp.cutting_group_rolls where cutting_group_id=p_cutting_group_id and qty_physically_returned>0 and coalesce(return_destination,'NONE')<>'WAREHOUSE') then
    raise exception 'Positive cutting returns with destination other than WAREHOUSE require a dedicated supplier/scrap flow; they cannot be silently posted as warehouse returns';
  end if;
  if exists(select 1 from erp.cutting_group_rolls where cutting_group_id=p_cutting_group_id and qty_physically_returned>0 and return_destination='WAREHOUSE' and returned_at is null) then
    raise exception 'Tanggal/jam fisik return cutting wajib diisi untuk setiap roll yang kembali ke gudang';
  end if;

  for r in
    select cgr.*,mr.material_id
    from erp.cutting_group_rolls cgr join erp.material_rolls mr on mr.id=cgr.roll_id
    where cgr.cutting_group_id=p_cutting_group_id and cgr.qty_physically_returned>0 and cgr.return_destination='WAREHOUSE'
    order by cgr.returned_at,cgr.id
  loop
    insert into erp.material_stock_movements(material_id,roll_id,location_id,movement_type,qty_signed,input_unit_cost,source_type,source_id,physical_at,created_by)
    values(r.material_id,r.roll_id,p_location_id,'CUTTING_RETURN',r.qty_physically_returned,r.unit_cost_snapshot,'CUTTING_GROUP_RETURN',p_cutting_group_id,r.returned_at,erp.current_app_user_id());
    perform erp.recalculate_material_cost(r.material_id);
    v_value:=r.qty_physically_returned*coalesce(r.unit_cost_snapshot,0);
    if abs(v_value)>0.005 then
      perform erp.post_journal('CUTTING_MATERIAL_RETURN_LINE',r.id,r.returned_at::date,'Unused cutting material physically returned',jsonb_build_array(
        jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',round(v_value,2),'credit',0,'po_id',g.po_id),
        jsonb_build_object('mapping_key','WIP','debit',0,'credit',round(v_value,2),'po_id',g.po_id)
      ));
    end if;
  end loop;
  update erp.cutting_groups set material_return_posted=true where id=p_cutting_group_id;
end;
$function$;

alter function "erp"."post_cutting_material_returns"(p_cutting_group_id uuid, p_location_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_cutting_qty_correction(p_cutting_batch_id uuid, p_correction_type text, p_reason_code text, p_reason text, p_lines jsonb, p_physical_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  perform erp.require_internal();
  if coalesce(p_physical_at,now())>clock_timestamp()+interval '5 minutes' then raise exception 'Tanggal/jam Koreksi Potongan berada di masa depan'; end if;
  return erp._post_cutting_qty_correction(p_cutting_batch_id,upper(p_correction_type),upper(p_reason_code),p_reason,p_lines,p_physical_at,null);
end$function$;

alter function "erp"."post_cutting_qty_correction"(p_cutting_batch_id uuid, p_correction_type text, p_reason_code text, p_reason text, p_lines jsonb, p_physical_at timestamp with time zone) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_cutting_qty_correction_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_batch erp.cutting_batches%rowtype;
  v_batch_id uuid := nullif(p_payload->>'cutting_batch_id', '')::uuid;
  v_type text := upper(nullif(btrim(p_payload->>'correction_type'), ''));
  v_reason_code text := upper(nullif(btrim(p_payload->>'reason_code'), ''));
  v_reason text := nullif(btrim(p_payload->>'reason'), '');
  v_lines jsonb := p_payload->'lines';
  v_physical_at timestamptz;
  v_correction_id uuid;
  v_correction_number text;
  v_net_delta bigint;
  v_totals record;
begin
  perform erp.require_internal();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if v_batch_id is null then raise exception 'cutting_batch_id is required'; end if;
  if v_type is null then raise exception 'correction_type is required'; end if;
  if v_reason_code is null then raise exception 'reason_code is required'; end if;
  if v_reason is null then raise exception 'Correction reason is required'; end if;
  if jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 then
    raise exception 'Correction requires at least one line';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'payload', p_payload,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(
    'post_cutting_qty_correction_v2', p_client_request_id, v_hash
  );
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason', v_reason, true);

  select * into v_batch
  from erp.cutting_batches
  where id = v_batch_id
  for update;
  if v_batch.id is null then raise exception 'Cutting batch not found'; end if;
  if v_batch.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',
      p_expected_version, v_batch.row_version;
  end if;

  v_physical_at := coalesce(
    nullif(p_payload->>'physical_at', '')::timestamptz,
    clock_timestamp()
  );
  if v_physical_at > clock_timestamp() + interval '5 minutes' then
    raise exception 'Tanggal/jam Koreksi Potongan berada di masa depan';
  end if;
  v_correction_id := erp._post_cutting_qty_correction(
    v_batch_id, v_type, v_reason_code, v_reason,
    v_lines, v_physical_at, null
  );

  -- Touching the aggregate root makes every successful correction invalidate
  -- stale browser drafts through the existing row-version trigger.
  update erp.cutting_batches
  set updated_at = clock_timestamp()
  where id = v_batch_id
  returning * into v_batch;

  select c.correction_number, coalesce(sum(l.qty_delta_pcs), 0)::bigint
  into v_correction_number, v_net_delta
  from erp.cutting_qty_corrections c
  join erp.cutting_qty_correction_lines l on l.correction_id = c.id
  where c.id = v_correction_id
  group by c.correction_number;

  select original_pcs, adjustment_pcs, effective_pcs
  into v_totals
  from erp.v_cutting_batch_totals
  where cutting_batch_id = v_batch_id;

  v_response := jsonb_build_object(
    'correction_id', v_correction_id,
    'correction_number', v_correction_number,
    'cutting_batch_id', v_batch_id,
    'correction_type', v_type,
    'net_delta_pcs', v_net_delta,
    'original_pcs', coalesce(v_totals.original_pcs, 0),
    'adjustment_pcs', coalesce(v_totals.adjustment_pcs, 0),
    'effective_pcs', coalesce(v_totals.effective_pcs, 0),
    'row_version', v_batch.row_version,
    'status', 'POSTED'
  );
  return erp._idempotency_complete(
    'post_cutting_qty_correction_v2', p_client_request_id, v_response
  );
end;
$function$;

alter function "erp"."post_cutting_qty_correction_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_fg_adjustment(p_adjustment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.fg_adjustments%rowtype;
  r record;
  lk record;
  v_value numeric(24,6);
  v_hpp numeric(18,6);
  v_lines jsonb:='[]'::jsonb;
  v_po uuid;
  v_native boolean;
begin
  perform erp.require_owner_admin();
  select * into h from erp.fg_adjustments where id=p_adjustment_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'FG adjustment harus DRAFT'; end if;
  if nullif(trim(h.reason),'') is null then raise exception 'Alasan FG adjustment wajib diisi'; end if;
  if not exists(select 1 from erp.locations where id=h.location_id and is_active=true and location_type='FG_WAREHOUSE') then
    raise exception 'Lokasi FG adjustment harus gudang barang jadi yang aktif';
  end if;
  if not exists(select 1 from erp.fg_adjustment_items where adjustment_id=h.id) then raise exception 'FG adjustment belum memiliki item'; end if;

  update erp.fg_adjustment_items set qty_signed=qty_signed where adjustment_id=h.id;

  for lk in
    select distinct product_id,quality_grade
    from erp.fg_adjustment_items
    where adjustment_id=h.id
    order by product_id,quality_grade
  loop
    insert into erp.fg_inventory_balances(product_id,location_id,quality_grade,cached_qty_pcs)
    values(lk.product_id,h.location_id,lk.quality_grade,0)
    on conflict(product_id,location_id,quality_grade) do nothing;
    perform 1 from erp.fg_inventory_balances
    where product_id=lk.product_id and location_id=h.location_id and quality_grade=lk.quality_grade
    for update;
  end loop;

  for r in
    select fai.*,fl.po_id,fl.lot_origin
    from erp.fg_adjustment_items fai
    join erp.fg_lots fl on fl.id=fai.lot_id
    where fai.adjustment_id=h.id
    order by fai.product_id,fai.quality_grade,fai.lot_id,fai.id
  loop
    perform 1 from erp.fg_lots where id=r.lot_id for update;
    v_hpp:=coalesce(erp.lock_current_hpp_per_pcs(r.lot_id),0);
    update erp.fg_adjustment_items set unit_hpp_snapshot=v_hpp where id=r.id;
    v_native:=r.po_id is not null and r.lot_origin in ('PRODUCTION','CONVERSION');

    perform erp.post_fg_movement(r.product_id,r.lot_id,h.location_id,r.quality_grade,'ADJUSTMENT',r.qty_signed,v_hpp,null,'FG_ADJUSTMENT_ITEM',r.id,h.physical_at,h.reason||coalesce(' - '||r.notes,''),false);
    v_value:=abs(r.qty_signed*v_hpp);

    if v_native then
      v_po:=r.po_id;
    elsif v_value>0.005 then
      if r.qty_signed<0 then
        v_lines:=v_lines||jsonb_build_array(
          jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',round(v_value,2),'credit',0,'product_id',r.product_id),
          jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',round(v_value,2),'product_id',r.product_id));
      else
        v_lines:=v_lines||jsonb_build_array(
          jsonb_build_object('mapping_key','FG_INVENTORY','debit',round(v_value,2),'credit',0,'product_id',r.product_id),
          jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',round(v_value,2),'product_id',r.product_id));
      end if;
    end if;
  end loop;

  update erp.fg_adjustments set status='POSTED' where id=h.id;
  if jsonb_array_length(v_lines)>=2 then
    perform erp.post_journal('FG_ADJUSTMENT',h.id,h.physical_at::date,'Controlled FG stock adjustment: '||h.reason,v_lines);
  end if;

  for v_po in
    select distinct fl.po_id
    from erp.fg_adjustment_items fai join erp.fg_lots fl on fl.id=fai.lot_id
    where fai.adjustment_id=h.id and fl.po_id is not null and fl.lot_origin in ('PRODUCTION','CONVERSION')
  loop
    perform erp.sync_po_hpp_to_gl(v_po,h.physical_at::date);
  end loop;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values ('fg_adjustments',h.id,'POST',erp.current_app_user_id(),h.reason);
end;
$function$;

alter function "erp"."post_fg_adjustment"(p_adjustment_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_fg_adjustment_v2(p_adjustment_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare v_hash text;v_cached jsonb;v_response jsonb;h erp.fg_adjustments%rowtype;
begin
  perform erp.require_owner_admin();
  if p_expected_version is null then raise exception 'expected_version is required';end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'Posting reason is required';end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'id',p_adjustment_id,'expected_version',p_expected_version,'reason',btrim(p_reason)
  ));
  v_cached:=erp._idempotency_begin('post_fg_adjustment_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached;end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  select * into h from erp.fg_adjustments where id=p_adjustment_id for update;
  if h.id is null then raise exception 'FG adjustment not found';end if;
  if h.row_version<>p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version;
  end if;
  perform erp.post_fg_adjustment(h.id);
  select * into h from erp.fg_adjustments where id=h.id;
  v_response:=jsonb_build_object('fg_adjustment_id',h.id,'status',h.status,'row_version',h.row_version);
  return erp._idempotency_complete('post_fg_adjustment_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."post_fg_adjustment_v2"(p_adjustment_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_fg_movement(p_product_id uuid, p_lot_id uuid, p_location_id uuid, p_quality_grade text, p_movement_type text, p_qty_signed integer, p_unit_hpp numeric, p_customer_id uuid, p_source_type text, p_source_id uuid, p_physical_at timestamp with time zone, p_note text DEFAULT NULL::text, p_allow_negative boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_id uuid;
  v_balance integer;
  v_lot_qty integer;
  v_lot_product uuid;
  v_lot_produced_at timestamptz;
begin
  perform erp.require_internal();
  if p_qty_signed=0 then raise exception 'FG movement qty cannot be zero'; end if;
  if p_physical_at is null then raise exception 'Finished-goods movement physical date/time is required'; end if;
  if p_location_id is null or not exists (
    select 1 from erp.locations l
    where l.id=p_location_id and l.is_active=true and l.location_type='FG_WAREHOUSE'
  ) then
    raise exception 'Finished-goods movement location must be an active FG warehouse';
  end if;

  insert into erp.fg_inventory_balances(product_id,location_id,quality_grade,cached_qty_pcs)
  values (p_product_id,p_location_id,coalesce(p_quality_grade,'GRADE_A'),0)
  on conflict (product_id,location_id,quality_grade) do nothing;

  select cached_qty_pcs into v_balance
  from erp.fg_inventory_balances
  where product_id=p_product_id
    and location_id=p_location_id
    and quality_grade=coalesce(p_quality_grade,'GRADE_A')
  for update;

  if not p_allow_negative and v_balance+p_qty_signed<0 then
    raise exception 'Finished goods stock cannot become negative';
  end if;

  if p_lot_id is not null then
    select cached_qty_pcs,product_id,produced_at
      into v_lot_qty,v_lot_product,v_lot_produced_at
    from erp.fg_lots where id=p_lot_id for update;
    if v_lot_qty is null then raise exception 'FG lot not found'; end if;
    if v_lot_product is distinct from p_product_id then
      raise exception 'FG lot product does not match movement product';
    end if;
    if p_physical_at<v_lot_produced_at then
      raise exception 'Tanggal mutasi FG % lebih awal dari tanggal barang/lot tersedia %. Koreksi tanggal transaksi atau sumber barang terlebih dahulu.',p_physical_at,v_lot_produced_at;
    end if;
    if not p_allow_negative and v_lot_qty+p_qty_signed<0 then
      raise exception 'FG lot stock cannot become negative';
    end if;
  end if;

  insert into erp.fg_stock_movements(
    product_id,lot_id,location_id,quality_grade,movement_type,qty_signed,
    unit_hpp_snapshot,customer_id,source_type,source_id,physical_at,created_by,notes
  ) values (
    p_product_id,p_lot_id,p_location_id,coalesce(p_quality_grade,'GRADE_A'),p_movement_type,p_qty_signed,
    coalesce(p_unit_hpp,0),p_customer_id,p_source_type,p_source_id,p_physical_at,erp.current_app_user_id(),p_note
  ) returning id into v_id;

  if not p_allow_negative then
    perform erp.assert_fg_chronological_nonnegative(p_product_id,p_lot_id,p_location_id,coalesce(p_quality_grade,'GRADE_A'));
  end if;

  update erp.fg_inventory_balances
  set cached_qty_pcs=cached_qty_pcs+p_qty_signed,updated_at=now()
  where product_id=p_product_id
    and location_id=p_location_id
    and quality_grade=coalesce(p_quality_grade,'GRADE_A');

  if p_lot_id is not null then
    update erp.fg_lots
    set cached_qty_pcs=cached_qty_pcs+p_qty_signed,
        is_open=(cached_qty_pcs+p_qty_signed)>0
    where id=p_lot_id;
  end if;
  return v_id;
end;
$function$;

alter function "erp"."post_fg_movement"(p_product_id uuid, p_lot_id uuid, p_location_id uuid, p_quality_grade text, p_movement_type text, p_qty_signed integer, p_unit_hpp numeric, p_customer_id uuid, p_source_type text, p_source_id uuid, p_physical_at timestamp with time zone, p_note text, p_allow_negative boolean) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_fg_partial_completion_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_mode text := upper(coalesce(nullif(btrim(p_payload->>'completion_mode'),''),'ALL_READY'));
  v_result jsonb;
  v_qc_id uuid;
  v_progress erp.v_fg_partial_completion_progress%rowtype;
begin
  perform erp.require_internal();
  if v_mode not in ('ALL_READY','PARTIAL_SELECTION') then
    raise exception 'completion_mode must be ALL_READY or PARTIAL_SELECTION';
  end if;

  v_result := erp.post_fg_partial_completion_v2_legacy_v2610(
    p_payload,
    p_client_request_id,
    p_expected_version
  );
  v_qc_id := nullif(v_result->>'qc_inspection_id','')::uuid;

  update erp.qc_inspections
  set completion_mode = v_mode
  where id = v_qc_id
    and completion_mode is distinct from v_mode;

  select * into v_progress
  from erp.v_fg_partial_completion_progress
  where cutting_group_id = nullif(v_result->>'cutting_group_id','')::uuid;

  return v_result || jsonb_build_object(
    'completion_mode', v_mode,
    'completion_status', v_progress.completion_status,
    'ready_for_qc_qty_pcs', v_progress.ready_for_qc_qty_pcs,
    'laundry_outstanding_qty_pcs', v_progress.laundry_outstanding_qty_pcs,
    'remaining_qc_qty_pcs', v_progress.remaining_qc_qty_pcs
  );
end;
$function$;

alter function "erp"."post_fg_partial_completion_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_fg_partial_completion_v2_legacy_v2610(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'post_fg_partial_completion_v2';
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_group erp.cutting_groups%rowtype;
  v_po_status text;
  v_group_id uuid := nullif(p_payload->>'cutting_group_id', '')::uuid;
  v_destination_location_id uuid := nullif(p_payload->>'destination_location_id', '')::uuid;
  v_physical_at timestamptz := coalesce(
    nullif(p_payload->>'physical_at', '')::timestamptz,
    clock_timestamp()
  );
  v_reason text := nullif(btrim(p_payload->>'reason'), '');
  v_lines jsonb := p_payload->'lines';
  v_qc_id uuid := gen_random_uuid();
  v_inspection_number text;
  v_total_qty bigint;
  v_good_qty bigint;
  v_bs_qty bigint;
  v_effective_qty bigint;
  v_prior_qty bigint;
  v_stock_qty bigint;
  v_stock_event_count bigint;
  v_progress erp.v_fg_partial_completion_progress%rowtype;
begin
  perform erp.require_internal();
  if p_expected_version is null then
    raise exception 'expected_version is required';
  end if;
  if v_group_id is null then
    raise exception 'cutting_group_id is required';
  end if;
  if v_destination_location_id is null then
    raise exception 'destination_location_id is required';
  end if;
  if v_reason is null then
    raise exception 'Completion reason is required';
  end if;
  if v_physical_at > clock_timestamp() + interval '5 minutes' then
    raise exception 'Tanggal/jam penyelesaian FG berada di masa depan';
  end if;
  if jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 then
    raise exception 'Partial FG completion requires at least one line';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'payload', p_payload,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then
    return v_cached;
  end if;

  perform set_config('app.change_reason', v_reason, true);

  select * into v_group
  from erp.cutting_groups
  where id = v_group_id
  for update;
  if v_group.id is null then
    raise exception 'Potongan not found';
  end if;
  if v_group.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',
      p_expected_version, v_group.row_version;
  end if;

  select status into v_po_status
  from erp.production_orders
  where id = v_group.po_id
  for update;
  if v_po_status in ('FINISHED', 'CANCELLED') then
    raise exception 'PO berstatus % dan tidak menerima penyelesaian FG baru', v_po_status;
  end if;

  if not exists (
    select 1 from erp.locations l
    where l.id = v_destination_location_id
      and l.is_active = true
      and l.location_type = 'FG_WAREHOUSE'
  ) then
    raise exception 'Destination must be an active FG warehouse';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_lines) as x(
      final_product_id uuid,
      qty_good_pcs integer,
      qty_bs_pcs integer,
      source_laundry_receipt_line_id uuid,
      notes text
    )
    where coalesce(x.qty_good_pcs, 0) < 0
       or coalesce(x.qty_bs_pcs, 0) < 0
       or coalesce(x.qty_good_pcs, 0) + coalesce(x.qty_bs_pcs, 0) <= 0
       or x.final_product_id is null
  ) then
    raise exception 'Every completion line requires a SKU and a positive GOOD/BS quantity';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_lines) as x(
      final_product_id uuid,
      qty_good_pcs integer,
      qty_bs_pcs integer,
      source_laundry_receipt_line_id uuid,
      notes text
    )
    group by x.final_product_id, x.source_laundry_receipt_line_id
    having count(*) > 1
  ) then
    raise exception 'Duplicate SKU and laundry source lines are not allowed';
  end if;

  select
    sum(coalesce(x.qty_good_pcs, 0) + coalesce(x.qty_bs_pcs, 0))::bigint,
    sum(coalesce(x.qty_good_pcs, 0))::bigint,
    sum(coalesce(x.qty_bs_pcs, 0))::bigint
  into v_total_qty, v_good_qty, v_bs_qty
  from jsonb_to_recordset(v_lines) as x(
    final_product_id uuid,
    qty_good_pcs integer,
    qty_bs_pcs integer,
    source_laundry_receipt_line_id uuid,
    notes text
  );

  select effective_qty_pcs, qc_accounted_qty_pcs
  into v_effective_qty, v_prior_qty
  from erp.v_fg_partial_completion_progress
  where cutting_group_id = v_group.id;
  if coalesce(v_effective_qty, 0) <= 0 then
    raise exception 'Potongan has no effective quantity available for FG';
  end if;
  if coalesce(v_prior_qty, 0) + coalesce(v_total_qty, 0) > v_effective_qty then
    raise exception
      'Qty penyelesaian melebihi sisa Potongan. Efektif %, sudah diposting %, input %.',
      v_effective_qty, coalesce(v_prior_qty, 0), coalesce(v_total_qty, 0);
  end if;

  v_inspection_number := 'FGP-'
    || to_char(v_physical_at, 'YYMMDD') || '-'
    || upper(substr(replace(p_client_request_id::text, '-', ''), 1, 10));

  insert into erp.qc_inspections(
    id, inspection_number, po_id, physical_at, status,
    notes, created_by, destination_location_id
  ) values (
    v_qc_id, v_inspection_number, v_group.po_id, v_physical_at, 'DRAFT',
    'Partial FG completion: ' || v_reason,
    erp.current_app_user_id(), v_destination_location_id
  );

  insert into erp.qc_inspection_items(
    inspection_id, cutting_group_id, source_laundry_receipt_line_id,
    final_product_id, qty_good_pcs, qty_bs_pcs, notes
  )
  select
    v_qc_id,
    v_group.id,
    x.source_laundry_receipt_line_id,
    x.final_product_id,
    coalesce(x.qty_good_pcs, 0),
    coalesce(x.qty_bs_pcs, 0),
    nullif(btrim(x.notes), '')
  from jsonb_to_recordset(v_lines) as x(
    final_product_id uuid,
    qty_good_pcs integer,
    qty_bs_pcs integer,
    source_laundry_receipt_line_id uuid,
    notes text
  );

  perform erp.post_qc(v_qc_id);

  -- Invalidate stale partial-completion drafts after every successful posting.
  update erp.cutting_groups
  set updated_at = clock_timestamp()
  where id = v_group.id
  returning * into v_group;

  select * into v_progress
  from erp.v_fg_partial_completion_progress
  where cutting_group_id = v_group.id;

  select
    coalesce(sum(m.qty_signed), 0)::bigint,
    count(*)::bigint
  into v_stock_qty, v_stock_event_count
  from erp.fg_stock_movements m
  where m.movement_type = 'QC_GOOD'
    and m.source_type = 'QC_ITEM'
    and m.source_id in (
      select i.id from erp.qc_inspection_items i where i.inspection_id = v_qc_id
    );

  v_response := jsonb_build_object(
    'qc_inspection_id', v_qc_id,
    'inspection_number', v_inspection_number,
    'cutting_group_id', v_group.id,
    'po_id', v_group.po_id,
    'completion_status', v_progress.completion_status,
    'posted_qty_pcs', v_total_qty,
    'good_qty_pcs', v_good_qty,
    'bs_qty_pcs', v_bs_qty,
    'fg_stock_in_qty_pcs', v_stock_qty,
    'fg_stock_event_count', v_stock_event_count,
    'cumulative_qc_qty_pcs', v_progress.qc_accounted_qty_pcs,
    'remaining_qc_qty_pcs', v_progress.remaining_qc_qty_pcs,
    'completion_count', v_progress.completion_count,
    'row_version', v_group.row_version,
    'document_status', 'POSTED'
  );

  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."post_fg_partial_completion_v2_legacy_v2610"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_final_sku_allocation_v1(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_declared bigint:=nullif(p_payload->>'good_qty_pcs','')::bigint;
  v_allocated bigint;v_physical_at timestamptz:=coalesce(nullif(p_payload->>'physical_at','')::timestamptz,clock_timestamp());
begin
  perform erp.require_permission('production.final_sku.post');
  if v_declared is null or v_declared<0 then raise exception 'good_qty_pcs is required'; end if;
  if jsonb_typeof(p_payload->'lines')<>'array' then raise exception 'Final SKU lines are required'; end if;
  if exists(
    select 1 from jsonb_to_recordset(p_payload->'lines')
      as x(final_product_id uuid,qty_good_pcs integer,qty_bs_pcs integer)
    where coalesce(x.qty_good_pcs,0)<0 or coalesce(x.qty_bs_pcs,0)<0
  ) then raise exception 'Final SKU quantities cannot be negative'; end if;
  select coalesce(sum(coalesce(x.qty_good_pcs,0)),0)::bigint into v_allocated
  from jsonb_to_recordset(p_payload->'lines') as x(final_product_id uuid,qty_good_pcs integer,qty_bs_pcs integer);
  if v_allocated<>v_declared then
    raise exception 'FINAL_SKU_GOOD_ALLOCATION_MISMATCH declared %, allocated %',v_declared,v_allocated;
  end if;
  if exists(
    select 1
    from jsonb_to_recordset(p_payload->'lines') as x(final_product_id uuid,qty_good_pcs integer,qty_bs_pcs integer)
    left join erp.products p on p.id=x.final_product_id
    where coalesce(x.qty_good_pcs,0)>0 and (
      p.id is null or not p.is_active or p.effective_from>v_physical_at
      or (p.effective_to is not null and p.effective_to<=v_physical_at)
    )
  ) then raise exception 'Every Good allocation requires an active Final SKU at physical_at'; end if;
  return erp.post_fg_partial_completion_v2(p_payload,p_client_request_id,p_expected_version);
end
$function$;

alter function "erp"."post_final_sku_allocation_v1"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_journal(p_source_type text, p_source_id uuid, p_transaction_date date, p_description text, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_entry_id uuid;
  v_number text;
  v_debit numeric(20,2);
  v_credit numeric(20,2);
  r jsonb;
  v_account_id uuid;
  v_gl_date date;
  v_ap_vendor_account uuid;
  v_vendor_id uuid;
  v_vendor_balance numeric(24,6);
  v_vendor_delta numeric(24,6);
begin
  perform erp.require_internal();
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)<2 then raise exception 'Journal requires at least two lines'; end if;
  select coalesce(sum(coalesce((x->>'debit')::numeric,0)),0),coalesce(sum(coalesce((x->>'credit')::numeric,0)),0)
  into v_debit,v_credit from jsonb_array_elements(p_lines) x;
  if round(v_debit,2)<>round(v_credit,2) or v_debit<=0 then raise exception 'Journal is not balanced. Debit %, Credit %',v_debit,v_credit; end if;
  if exists(select 1 from erp.journal_entries where source_type=p_source_type and source_id=p_source_id and status='POSTED') then
    raise exception 'A posted journal already exists for this source';
  end if;

  -- Serialize journal posting with accounting close/reopen. A close that starts
  -- first blocks this journal until the new closed-through date is visible; a
  -- journal that starts first keeps the close waiting until this posting commits.
  perform 1 from erp.accounting_period_control where singleton_id=1 for share;

  -- Vendor AP is allowed to reach zero, but not become negative. Negative AP
  -- means the company has a receivable/advance from the vendor and requires a
  -- separate explicit workflow instead of silently crossing the account sign.
  v_ap_vendor_account:=erp.account_id('AP_VENDOR');
  for v_vendor_id in
    select distinct nullif(x->>'vendor_id','')::uuid
    from jsonb_array_elements(p_lines) x
    where nullif(x->>'vendor_id','') is not null
      and coalesce((x->>'debit')::numeric,0)>coalesce((x->>'credit')::numeric,0)
      and (
        (x ? 'mapping_key' and x->>'mapping_key'='AP_VENDOR')
        or (x ? 'account_id' and nullif(x->>'account_id','')::uuid=v_ap_vendor_account)
      )
    order by 1
  loop
    perform pg_advisory_xact_lock(hashtextextended('VENDOR_AP|'||v_vendor_id::text,0));

    select coalesce(sum(jl.credit-jl.debit),0)
      into v_vendor_balance
    from erp.journal_lines jl
    join erp.journal_entries je on je.id=jl.journal_entry_id
    where je.status in ('POSTED','REVERSED')
      and jl.account_id=v_ap_vendor_account
      and jl.vendor_id=v_vendor_id;

    select coalesce(sum(
      coalesce((x->>'credit')::numeric,0)-coalesce((x->>'debit')::numeric,0)
    ),0)
      into v_vendor_delta
    from jsonb_array_elements(p_lines) x
    where nullif(x->>'vendor_id','')::uuid=v_vendor_id
      and (
        (x ? 'mapping_key' and x->>'mapping_key'='AP_VENDOR')
        or (x ? 'account_id' and nullif(x->>'account_id','')::uuid=v_ap_vendor_account)
      );

    if v_vendor_balance+v_vendor_delta < -0.01 then
      raise exception 'Transaksi ini membuat hutang vendor menjadi negatif. Hutang saat ini %, perubahan %, hasil %. Reverse/koreksi pembayaran, claim, atau invoice terkait dulu; kelebihan bayar/claim vendor harus masuk workflow piutang vendor terpisah.',
        round(v_vendor_balance,2),round(v_vendor_delta,2),round(v_vendor_balance+v_vendor_delta,2);
    end if;
  end loop;

  v_gl_date:=erp.resolve_accounting_transaction_date(p_transaction_date);
  v_number:='JRN-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS')||'-'||substr(gen_random_uuid()::text,1,8);
  insert into erp.journal_entries(journal_number,economic_date,transaction_date,posting_at,source_type,source_id,description,status,created_by)
  values(v_number,p_transaction_date,v_gl_date,now(),p_source_type,p_source_id,p_description,'POSTED',erp.current_app_user_id()) returning id into v_entry_id;

  for r in select * from jsonb_array_elements(p_lines) loop
    if r?'account_id' then v_account_id:=(r->>'account_id')::uuid; else v_account_id:=erp.account_id(r->>'mapping_key'); end if;
    insert into erp.journal_lines(journal_entry_id,account_id,description,debit,credit,customer_id,vendor_id,contractor_id,po_id,product_id)
    values(v_entry_id,v_account_id,r->>'description',coalesce((r->>'debit')::numeric,0),coalesce((r->>'credit')::numeric,0),nullif(r->>'customer_id','')::uuid,nullif(r->>'vendor_id','')::uuid,nullif(r->>'contractor_id','')::uuid,nullif(r->>'po_id','')::uuid,nullif(r->>'product_id','')::uuid);
  end loop;

  insert into erp.account_daily_balances(balance_date,account_id,debit_total,credit_total)
  select v_gl_date,jl.account_id,sum(jl.debit),sum(jl.credit) from erp.journal_lines jl where jl.journal_entry_id=v_entry_id group by jl.account_id
  on conflict(balance_date,account_id) do update set debit_total=erp.account_daily_balances.debit_total+excluded.debit_total,credit_total=erp.account_daily_balances.credit_total+excluded.credit_total,updated_at=now();

  if v_gl_date<>p_transaction_date then
    insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
    values('journal_entries',v_entry_id,'POST',jsonb_build_object('economic_date',p_transaction_date,'transaction_date',v_gl_date,'period_shifted',true,'source_type',p_source_type,'source_id',p_source_id),erp.current_app_user_id(),'Late/backdated posting moved to open accounting period');
  end if;
  return v_entry_id;
end;
$function$;

alter function "erp"."post_journal"(p_source_type text, p_source_id uuid, p_transaction_date date, p_description text, p_lines jsonb) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_laundry_delivery(p_delivery_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare h erp.laundry_deliveries%rowtype; r record; v_group_total bigint; v_already_sent bigint; v_rate numeric(18,2); v_pickup timestamptz;
begin
  perform erp.require_internal();
  select * into h from erp.laundry_deliveries where id=p_delivery_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Laundry delivery must be DRAFT'; end if;
  if not exists(select 1 from erp.laundry_delivery_lines where delivery_id=h.id) then raise exception 'Laundry delivery has no lines'; end if;
  for r in select * from erp.laundry_delivery_lines where delivery_id=h.id loop
    if not exists(select 1 from erp.cutting_groups cg where cg.id=r.cutting_group_id and cg.po_id=h.po_id) then raise exception 'Cutting group does not belong to delivery PO'; end if;
    select picked_up_at into v_pickup from erp.cutting_groups where id=r.cutting_group_id;
    if v_pickup is null then raise exception 'Cutting group % has not been picked up by the mandor yet',r.cutting_group_id; end if;
    if h.physical_at<v_pickup then raise exception 'Tanggal/jam kirim laundry tidak boleh lebih awal dari tanggal/jam potongan diambil mandor'; end if;
    select total_pcs into v_group_total from erp.v_cutting_group_totals where cutting_group_id=r.cutting_group_id;
    select coalesce(sum(ldl2.qty_sent_pcs),0) into v_already_sent
    from erp.laundry_delivery_lines ldl2 join erp.laundry_deliveries ld2 on ld2.id=ldl2.delivery_id
    where ldl2.cutting_group_id=r.cutting_group_id and ld2.id<>h.id and ld2.status not in('DRAFT','REVERSED');
    if coalesce(v_group_total,0)<v_already_sent+r.qty_sent_pcs then
      raise exception 'Laundry qty exceeds effective cutting qty for group %. Effective %, already sent %, requested %. Post a local cutting quantity correction instead of reversing sibling groups.',r.cutting_group_id,coalesce(v_group_total,0),v_already_sent,r.qty_sent_pcs;
    end if;
    v_rate:=r.estimated_rate_snapshot;
    if v_rate is null and h.target_wash_process_id is not null then
      perform pg_advisory_xact_lock(hashtextextended('LRATE:'||h.vendor_id::text||':'||h.target_wash_process_id::text,0));
      select rate_per_pcs into v_rate from erp.laundry_vendor_rate_versions
      where vendor_id=h.vendor_id and wash_process_id=h.target_wash_process_id and effective_from<=h.physical_at and (effective_to is null or effective_to>h.physical_at)
      order by effective_from desc,created_at desc limit 1;
      if v_rate is not null then update erp.laundry_delivery_lines set estimated_rate_snapshot=v_rate,estimated_cost_status='ESTIMATED' where id=r.id; end if;
    end if;
    insert into erp.wip_stage_events(po_id,cutting_group_id,stage_from,stage_to,qty_pcs,contractor_id,source_type,source_id,physical_at,created_by,notes)
    select h.po_id,r.cutting_group_id,'SEWING','LAUNDRY',r.qty_sent_pcs,po.contractor_id,'LAUNDRY_DELIVERY_LINE',r.id,h.physical_at,erp.current_app_user_id(),h.target_dyeing_color
    from erp.production_orders po where po.id=h.po_id;
    update erp.cutting_groups set status='LAUNDRY' where id=r.cutting_group_id;
  end loop;
  update erp.laundry_deliveries set status='SENT',updated_at=now() where id=h.id;
  update erp.production_orders set status='LAUNDRY',current_stage='LAUNDRY',updated_at=now() where id=h.po_id;
  perform erp.sync_laundry_accrual(h.po_id,h.physical_at::date);
end;
$function$;

alter function "erp"."post_laundry_delivery"(p_delivery_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_laundry_receipt(p_receipt_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  h erp.laundry_receipts%rowtype;
  d erp.laundry_deliveries%rowtype;
  r record;
  a record;
  v_sent bigint;
  v_returned bigint;
  v_allocated integer;
  v_bs_number text;
begin
  perform erp.require_internal();
  select * into h from erp.laundry_receipts where id=p_receipt_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Laundry receipt must be DRAFT'; end if;
  select * into d from erp.laundry_deliveries where id=h.delivery_id for update;
  if d.status not in ('SENT','PARTIAL_RETURN') then raise exception 'Laundry delivery must already be sent'; end if;
  if not exists(select 1 from erp.laundry_receipt_lines where receipt_id=h.id) then
    raise exception 'Laundry receipt has no lines';
  end if;

  for r in
    select lrl.*,ldl.cutting_group_id
    from erp.laundry_receipt_lines lrl
    join erp.laundry_delivery_lines ldl on ldl.id=lrl.delivery_line_id
    where lrl.receipt_id=h.id order by lrl.id
  loop
    select coalesce(sum(x.qty_bs),0)::integer into v_allocated
    from erp.laundry_receipt_bs_product_allocations x where x.receipt_line_id=r.id;
    if v_allocated<>r.qty_bs_laundry then
      raise exception 'Laundry BS product allocation % must equal BS qty % for receipt line %',
        v_allocated,r.qty_bs_laundry,r.id;
    end if;

    if r.qty_good_received+r.qty_bs_laundry>0 and exists(
      select 1
      from erp.laundry_claims lc
      left join erp.laundry_receipt_lines prior_line on prior_line.id=lc.receipt_line_id
      where lc.status in ('SETTLED','WRITTEN_OFF')
        and lc.claim_type in ('MISSING','STUCK')
        and (
          prior_line.delivery_line_id=r.delivery_line_id
          or (lc.receipt_line_id is null and lc.delivery_id=d.id)
        )
    ) then
      raise exception 'Late physical return is blocked after a STUCK/MISSING claim is SETTLED/WRITTEN_OFF; reverse the claim resolution first';
    end if;

    if r.qty_good_received+r.qty_bs_laundry>0 then
      insert into erp.wip_stage_events(
        po_id,cutting_group_id,stage_from,stage_to,qty_pcs,
        source_type,source_id,physical_at,created_by,notes
      ) values(
        d.po_id,r.cutting_group_id,'LAUNDRY','QC',r.qty_good_received+r.qty_bs_laundry,
        'LAUNDRY_RECEIPT_LINE',r.id,h.physical_at,erp.current_app_user_id(),
        'Physically returned from laundry'
      );
      update erp.cutting_groups set status='RETURNED' where id=r.cutting_group_id;
    end if;

    for a in
      select * from erp.laundry_receipt_bs_product_allocations
      where receipt_line_id=r.id order by id
    loop
      perform erp.assert_product_identity_time(a.product_id,h.physical_at,'NEW_STOCK');
      v_bs_number:='BS-LAU-'||left(h.receipt_number,28)||'-'||substr(r.id::text,1,8)||'-'||substr(a.id::text,1,6);
      insert into erp.bs_cases(
        bs_number,po_id,cutting_group_id,product_id,
        source_laundry_receipt_line_id,source_laundry_bs_allocation_id,
        detected_at_stage,cause_source,responsible_vendor_id,
        qty_pcs,status,physical_at,notes
      ) values(
        v_bs_number,d.po_id,r.cutting_group_id,a.product_id,r.id,a.id,
        'LAUNDRY','LAUNDRY',d.vendor_id,a.qty_bs,'OPEN',h.physical_at,
        'Auto-created from laundry receipt with product/size lineage'
      ) on conflict(source_laundry_bs_allocation_id) where source_laundry_bs_allocation_id is not null do nothing;
    end loop;
  end loop;

  update erp.laundry_receipts set status='POSTED',updated_at=now() where id=h.id;
  select coalesce(sum(qty_sent_pcs),0) into v_sent
  from erp.laundry_delivery_lines where delivery_id=d.id;
  select coalesce(sum(lrl.qty_good_received+lrl.qty_bs_laundry),0) into v_returned
  from erp.laundry_receipt_lines lrl
  join erp.laundry_receipts lr on lr.id=lrl.receipt_id
  where lr.delivery_id=d.id and lr.status='POSTED';
  update erp.laundry_deliveries
  set status=case when v_returned>=v_sent then 'RETURNED' else 'PARTIAL_RETURN' end,
      updated_at=now()
  where id=d.id;
  if v_returned>0 then
    update erp.production_orders set status='QC',current_stage='QC',updated_at=now() where id=d.po_id;
  end if;
  perform erp.sync_laundry_accrual(d.po_id,h.physical_at::date);
  if exists(select 1 from erp.fg_lots where po_id=d.po_id) then
    perform erp.rebuild_po_hpp(d.po_id,'Laundry receipt posted/corrected');
    perform erp.propagate_conversion_hpp_for_po(d.po_id);
    perform erp.sync_po_hpp_to_gl(d.po_id,h.physical_at::date);
  end if;
end;
$function$;

alter function "erp"."post_laundry_receipt"(p_receipt_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_laundry_receipt_v2(p_receipt_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_receipt erp.laundry_receipts%rowtype;
begin
  perform erp.require_internal();
  if nullif(btrim(p_reason),'') is null then raise exception 'Posting reason is required'; end if;
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'receipt_id',p_receipt_id,'expected_version',p_expected_version,'reason',btrim(p_reason)
  ));
  v_cached:=erp._idempotency_begin('post_laundry_receipt_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  select * into v_receipt from erp.laundry_receipts where id=p_receipt_id for update;
  if v_receipt.id is null then raise exception 'Laundry receipt not found'; end if;
  if v_receipt.row_version<>p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_receipt.row_version;
  end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  perform erp.post_laundry_receipt(p_receipt_id);
  select * into v_receipt from erp.laundry_receipts where id=p_receipt_id;
  v_response:=jsonb_build_object(
    'laundry_receipt_id',v_receipt.id,'status',v_receipt.status,
    'row_version',v_receipt.row_version,
    'bs_case_count',(select count(*) from erp.bs_cases where source_laundry_receipt_line_id in(
      select id from erp.laundry_receipt_lines where receipt_id=v_receipt.id
    ))
  );
  return erp._idempotency_complete('post_laundry_receipt_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."post_laundry_receipt_v2"(p_receipt_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_material_adjustment(p_adjustment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE h erp.material_adjustments%ROWTYPE;r record;v_type varchar(40);v_value numeric(24,6):=0; BEGIN PERFORM erp.require_internal(); SELECT * INTO h FROM erp.material_adjustments WHERE id=p_adjustment_id FOR UPDATE; IF h.id IS NULL OR h.status<>'DRAFT' THEN RAISE EXCEPTION 'Adjustment must be DRAFT'; END IF; IF h.location_id IS NULL THEN RAISE EXCEPTION 'Adjustment location is required'; END IF; v_type:=CASE h.reason_code WHEN 'PERSONAL_USE' THEN 'PERSONAL_USE' WHEN 'INTERNAL_FACTORY_USE' THEN 'INTERNAL_USE' WHEN 'SAMPLE' THEN 'SAMPLE' WHEN 'DAMAGE' THEN 'DAMAGE' WHEN 'LOSS' THEN 'LOSS' ELSE 'ADJUSTMENT' END; FOR r IN SELECT * FROM erp.material_adjustment_items WHERE adjustment_id=p_adjustment_id LOOP IF r.qty_signed>0 AND r.input_unit_cost IS NULL THEN RAISE EXCEPTION 'Positive material adjustment requires input_unit_cost'; END IF; INSERT INTO erp.material_stock_movements(material_id,roll_id,location_id,movement_type,qty_signed,input_unit_cost,source_type,source_id,physical_at,created_by) VALUES (r.material_id,r.roll_id,h.location_id,v_type,r.qty_signed,r.input_unit_cost,'MATERIAL_ADJUSTMENT_ITEM',r.id,h.physical_at,erp.current_app_user_id()); END LOOP; FOR r IN SELECT DISTINCT material_id FROM erp.material_adjustment_items WHERE adjustment_id=p_adjustment_id LOOP PERFORM erp.recalculate_material_cost(r.material_id); END LOOP; SELECT COALESCE(SUM(msm.qty_signed*msm.unit_cost_snapshot),0) INTO v_value FROM erp.material_stock_movements msm JOIN erp.material_adjustment_items mai ON mai.id=msm.source_id WHERE mai.adjustment_id=p_adjustment_id AND msm.source_type='MATERIAL_ADJUSTMENT_ITEM'; IF v_value<0 THEN PERFORM erp.post_journal('MATERIAL_ADJUSTMENT',h.id,h.physical_at::date,'Material usage/adjustment',jsonb_build_array(jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',round(-v_value,2),'credit',0),jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',0,'credit',round(-v_value,2)))); ELSIF v_value>0 THEN PERFORM erp.post_journal('MATERIAL_ADJUSTMENT',h.id,h.physical_at::date,'Positive material adjustment',jsonb_build_array(jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',round(v_value,2),'credit',0),jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',round(v_value,2)))); END IF; UPDATE erp.material_adjustments SET status='POSTED' WHERE id=p_adjustment_id; END; $function$;

alter function "erp"."post_material_adjustment"(p_adjustment_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_material_adjustment_v2(p_adjustment_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare v_hash text; v_cached jsonb; v_response jsonb; h erp.material_adjustments%rowtype;
begin
  perform erp.require_internal();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'Posting reason is required'; end if;
  v_hash := erp._request_hash(jsonb_build_object(
    'id',p_adjustment_id,'expected_version',p_expected_version,'reason',btrim(p_reason)
  ));
  v_cached := erp._idempotency_begin('post_material_adjustment_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  select * into h from erp.material_adjustments where id=p_adjustment_id for update;
  if h.id is null then raise exception 'Material adjustment not found'; end if;
  if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
  perform erp.post_material_adjustment(h.id);
  select * into h from erp.material_adjustments where id=h.id;
  v_response:=jsonb_build_object('material_adjustment_id',h.id,'status',h.status,'row_version',h.row_version);
  return erp._idempotency_complete('post_material_adjustment_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."post_material_adjustment_v2"(p_adjustment_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_material_purchase(p_purchase_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.material_purchase_headers%rowtype;
  r record;
  rr record;
  v_roll_count integer;
  v_roll_qty numeric(18,6);
  v_bad_rolls integer;
  v_total numeric(24,6):=0;
begin
  perform erp.require_internal();
  select * into h from erp.material_purchase_headers where id=p_purchase_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Purchase must be DRAFT'; end if;
  if h.supplier_id is null then raise exception 'Material purchase supplier is required'; end if;
  if h.location_id is null then raise exception 'Purchase location is required'; end if;
  if not exists(select 1 from erp.locations l where l.id=h.location_id and l.is_active=true and l.location_type='RAW_MATERIAL_WAREHOUSE') then raise exception 'Material purchase location must be an active raw-material warehouse'; end if;
  if not exists(select 1 from erp.material_purchase_items where purchase_id=h.id) then raise exception 'Material purchase has no lines'; end if;

  for r in select mpi.*,m.material_type from erp.material_purchase_items mpi join erp.materials m on m.id=mpi.material_id where mpi.purchase_id=p_purchase_id order by mpi.id loop
    select count(*),coalesce(sum(original_qty),0),count(*) filter(where material_id<>r.material_id or supplier_id is distinct from h.supplier_id)
      into v_roll_count,v_roll_qty,v_bad_rolls from erp.material_rolls where purchase_item_id=r.id;
    if r.material_type='FABRIC' then
      if v_roll_count=0 then raise exception 'Native FABRIC purchase item % must have roll records before posting',r.id; end if;
      if v_bad_rolls>0 then raise exception 'Fabric roll material/supplier does not match purchase item/header'; end if;
      if abs(v_roll_qty-r.qty)>0.000001 then raise exception 'Fabric purchase item % qty % does not equal sum of its rolls %',r.id,r.qty,v_roll_qty; end if;
    elsif v_roll_count>0 then
      raise exception 'Only FABRIC purchase items may have material rolls';
    end if;

    if v_roll_count>0 then
      for rr in select * from erp.material_rolls where purchase_item_id=r.id order by roll_number,id loop
        insert into erp.material_stock_movements(material_id,roll_id,location_id,movement_type,qty_signed,input_unit_cost,unit_cost_snapshot,source_type,source_id,physical_at,system_created_at,created_by)
        values(r.material_id,rr.id,h.location_id,'PURCHASE',rr.original_qty,r.unit_price,r.unit_price,'MATERIAL_PURCHASE_ROLL',rr.id,h.physical_at,clock_timestamp(),erp.current_app_user_id());
      end loop;
    else
      insert into erp.material_stock_movements(material_id,location_id,movement_type,qty_signed,input_unit_cost,unit_cost_snapshot,source_type,source_id,physical_at,system_created_at,created_by)
      values(r.material_id,h.location_id,'PURCHASE',r.qty,r.unit_price,r.unit_price,'MATERIAL_PURCHASE_ITEM',r.id,h.physical_at,clock_timestamp(),erp.current_app_user_id());
    end if;
    v_total:=v_total+r.line_total;
  end loop;

  for r in select distinct material_id from erp.material_purchase_items where purchase_id=p_purchase_id loop perform erp.recalculate_material_cost(r.material_id); end loop;
  if v_total>0 then
    perform erp.post_journal('MATERIAL_PURCHASE',h.id,h.physical_at::date,'Material purchase '||h.purchase_number,jsonb_build_array(
      jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',round(v_total,2),'credit',0),
      jsonb_build_object('mapping_key','AP_SUPPLIER','debit',0,'credit',round(v_total,2))));
  end if;
  update erp.material_purchase_headers set status='POSTED' where id=p_purchase_id;
  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason) values('material_purchase_headers',p_purchase_id,'POST',erp.current_app_user_id(),'Purchase posted');
end;
$function$;

alter function "erp"."post_material_purchase"(p_purchase_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_material_purchase_cost_correction(p_correction_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.material_purchase_cost_corrections%rowtype;
  p erp.material_purchase_headers%rowtype;
  m record;
  r record;
  v_delta_payable numeric(24,6);
  v_old_cost numeric(18,6);
  v_material_delta numeric(24,6);
  v_current_payable numeric(24,6);
  v_proposed_payable numeric(24,6);
  v_paid numeric(24,6);
  v_lines jsonb:='[]'::jsonb;
  v_post_seq bigint;
begin
  perform erp.require_owner_admin();
  select * into h from erp.material_purchase_cost_corrections where id=p_correction_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Material purchase cost correction must be DRAFT'; end if;
  select * into p from erp.material_purchase_headers where id=h.purchase_id for update;
  if p.id is null or p.status<>'POSTED' then raise exception 'Source material purchase must be POSTED'; end if;
  if not exists(select 1 from erp.material_purchase_cost_correction_items where correction_id=h.id) then raise exception 'Cost correction has no lines'; end if;

  select coalesce(max(c.post_seq),0)+1 into v_post_seq
  from erp.material_purchase_cost_corrections c
  where c.purchase_id=p.id and c.post_seq is not null;

  select erp.material_purchase_payable_total(p.id) into v_current_payable;
  select coalesce(sum(mpi.qty*(ci.new_unit_price-erp.material_purchase_current_unit_cost(mpi.id))),0)
  into v_delta_payable
  from erp.material_purchase_cost_correction_items ci
  join erp.material_purchase_items mpi on mpi.id=ci.purchase_item_id
  where ci.correction_id=h.id;
  v_proposed_payable:=v_current_payable+v_delta_payable;
  select coalesce(sum(sp.amount),0) into v_paid from erp.supplier_payments sp where sp.purchase_id=p.id and sp.status='POSTED';
  if v_proposed_payable< -0.01 then raise exception 'Corrected purchase payable cannot become negative'; end if;
  if v_paid>v_proposed_payable+0.01 then raise exception 'Cost correction would make supplier payments exceed corrected payable. Use supplier credit/receivable correction flow'; end if;

  for m in
    select distinct mpi.material_id
    from erp.material_purchase_cost_correction_items ci join erp.material_purchase_items mpi on mpi.id=ci.purchase_item_id
    where ci.correction_id=h.id
  loop
    v_material_delta:=0;
    for r in
      select ci.id as correction_item_id,ci.purchase_item_id,ci.new_unit_price,mpi.qty,mpi.material_id
      from erp.material_purchase_cost_correction_items ci
      join erp.material_purchase_items mpi on mpi.id=ci.purchase_item_id
      where ci.correction_id=h.id and mpi.material_id=m.material_id
      order by ci.id
    loop
      v_old_cost:=erp.material_purchase_current_unit_cost(r.purchase_item_id);
      update erp.material_purchase_cost_correction_items
      set old_unit_cost_snapshot=v_old_cost,qty_basis=r.qty,delta_amount=r.qty*(r.new_unit_price-v_old_cost)
      where id=r.correction_item_id;
      v_material_delta:=v_material_delta+(r.qty*(r.new_unit_price-v_old_cost));
      update erp.material_stock_movements msm
      set input_unit_cost=r.new_unit_price
      where msm.movement_type='PURCHASE' and msm.qty_signed>0 and (
        (msm.source_type='MATERIAL_PURCHASE_ITEM' and msm.source_id=r.purchase_item_id)
        or (msm.source_type='MATERIAL_PURCHASE_ROLL' and msm.source_id in(select mr.id from erp.material_rolls mr where mr.purchase_item_id=r.purchase_item_id))
      );
      if not found then raise exception 'Original purchase stock movement not found for purchase item %',r.purchase_item_id; end if;
    end loop;

    perform erp.recalculate_material_cost(m.material_id,p.physical_at);

    if abs(v_material_delta)>0.005 then
      if v_material_delta>0 then
        v_lines:=v_lines||jsonb_build_array(
          jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',round(v_material_delta,2),'credit',0),
          jsonb_build_object('mapping_key','AP_SUPPLIER','debit',0,'credit',round(v_material_delta,2))
        );
      else
        v_lines:=v_lines||jsonb_build_array(
          jsonb_build_object('mapping_key','AP_SUPPLIER','debit',round(abs(v_material_delta),2),'credit',0),
          jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',0,'credit',round(abs(v_material_delta),2))
        );
      end if;
    end if;
  end loop;

  if jsonb_array_length(v_lines)>=2 then
    perform erp.post_journal('MATERIAL_PURCHASE_COST_CORRECTION',h.id,h.invoice_date,'Late/final fabric supplier invoice cost correction',v_lines);
  end if;
  update erp.material_purchase_cost_corrections
  set status='POSTED',posted_at=clock_timestamp(),post_seq=v_post_seq
  where id=h.id;
  select erp.material_purchase_payable_total(p.id) into v_proposed_payable;
  select coalesce(sum(sp.amount),0) into v_paid from erp.supplier_payments sp where sp.purchase_id=p.id and sp.status='POSTED';
  update erp.material_purchase_headers set payment_status=case when v_paid>=v_proposed_payable-0.01 then 'PAID' when v_paid>0 then 'PARTIAL' else 'UNPAID' end where id=p.id;
end;
$function$;

alter function "erp"."post_material_purchase_cost_correction"(p_correction_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_material_purchase_v2(p_purchase_id uuid, p_client_request_id uuid, p_expected_version bigint, p_change_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_header erp.material_purchase_headers%rowtype;
begin
  perform erp.require_internal();
  if coalesce(btrim(p_change_reason), '') = '' then raise exception 'change_reason is required'; end if;
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  v_hash := erp._request_hash(jsonb_build_object(
    'purchase_id', p_purchase_id, 'expected_version', p_expected_version,
    'change_reason', p_change_reason
  ));
  v_cached := erp._idempotency_begin('post_material_purchase_v2', p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_header
  from erp.material_purchase_headers where id = p_purchase_id for update;
  if v_header.id is null or v_header.status <> 'DRAFT' then raise exception 'Purchase must be DRAFT'; end if;
  if v_header.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_header.row_version;
  end if;
  if v_header.supplier_id is null then raise exception 'supplier_id is required before posting'; end if;
  if v_header.location_id is null then raise exception 'location_id is required before posting'; end if;
  if not exists (select 1 from erp.material_purchase_items where purchase_id = p_purchase_id) then
    raise exception 'At least one purchase line is required before posting';
  end if;

  perform set_config('app.change_reason', btrim(p_change_reason), true);
  perform erp.post_material_purchase(p_purchase_id);
  select * into v_header from erp.material_purchase_headers where id = p_purchase_id;
  v_response := jsonb_build_object(
    'purchase_id', p_purchase_id, 'status', v_header.status,
    'row_version', v_header.row_version
  );
  return erp._idempotency_complete('post_material_purchase_v2', p_client_request_id, v_response);
end;
$function$;

alter function "erp"."post_material_purchase_v2"(p_purchase_id uuid, p_client_request_id uuid, p_expected_version bigint, p_change_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_material_supplier_invoice(p_invoice_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  h erp.material_supplier_invoices%rowtype;
  r record;
  v_capacity numeric;
  v_matched numeric;
  v_old_cost numeric;
  v_new_cost numeric;
  v_basis_qty numeric;
  v_delta_before numeric;
  v_delta_after numeric;
  v_inventory_delta numeric;
  v_liability_delta numeric;
  v_bridge numeric;
  v_grni_total numeric(24,6):=0;
  v_ap_total numeric(24,6):=0;
  v_inventory_total numeric(24,6):=0;
  v_bridge_total numeric(24,6):=0;
  v_lines jsonb:='[]'::jsonb;
  v_purchase uuid;
  v_paid numeric;
  v_payable numeric;
begin
  perform erp.require_owner_admin();
  select * into h from erp.material_supplier_invoices where id=p_invoice_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Material supplier invoice must be DRAFT'; end if;
  if h.invoice_date>current_date then raise exception 'Supplier invoice date cannot be in the future'; end if;
  if h.received_at::date>current_date then raise exception 'Supplier invoice received_at cannot be in the future'; end if;
  if not exists(select 1 from erp.material_supplier_invoice_lines where invoice_id=h.id) then
    raise exception 'Material supplier invoice has no lines';
  end if;

  -- Deterministic lock order protects concurrent invoice/payment/return clicks.
  for v_purchase in
    select distinct i.purchase_id
    from erp.material_supplier_invoice_lines l
    join erp.material_purchase_items i on i.id=l.purchase_item_id
    where l.invoice_id=h.id order by i.purchase_id
  loop
    perform 1 from erp.material_purchase_headers where id=v_purchase for update;
  end loop;
  for r in
    select distinct i.id
    from erp.material_supplier_invoice_lines l
    join erp.material_purchase_items i on i.id=l.purchase_item_id
    where l.invoice_id=h.id order by i.id
  loop
    perform 1 from erp.material_purchase_items where id=r.id for update;
  end loop;

  for r in
    select l.*,i.qty as receipt_qty,i.unit_price as estimate_unit_cost,
           i.material_id,i.purchase_id,i.invoice_match_state,
           ph.supplier_id,ph.physical_at
    from erp.material_supplier_invoice_lines l
    join erp.material_purchase_items i on i.id=l.purchase_item_id
    join erp.material_purchase_headers ph on ph.id=i.purchase_id
    where l.invoice_id=h.id order by i.id
  loop
    if r.supplier_id is distinct from h.supplier_id then
      raise exception 'Invoice supplier does not match receipt supplier for item %',r.purchase_item_id;
    end if;
    if r.invoice_match_state='DIRECT_FINAL' then
      raise exception 'Receipt item % was already final-invoiced at physical receipt',r.purchase_item_id;
    end if;
    v_capacity:=erp.material_purchase_invoice_capacity(r.purchase_item_id);
    v_matched:=erp.material_purchase_posted_invoice_qty(r.purchase_item_id);
    if v_matched+r.qty_invoiced>v_capacity+0.000001 then
      raise exception 'Invoice quantity exceeds unmatched receipt quantity for item %. Capacity %, already matched %, requested %',
        r.purchase_item_id,v_capacity,v_matched,r.qty_invoiced;
    end if;

    v_old_cost:=erp.material_purchase_current_unit_cost(r.purchase_item_id);
    v_basis_qty:=v_capacity;
    select coalesce(sum(x.net_amount-(x.qty_invoiced*r.estimate_unit_cost)),0)
    into v_delta_before
    from erp.material_supplier_invoice_lines x
    join erp.material_supplier_invoices xh on xh.id=x.invoice_id
    where x.purchase_item_id=r.purchase_item_id and xh.status='POSTED';
    v_delta_after:=v_delta_before+(r.net_amount-(r.qty_invoiced*r.estimate_unit_cost));
    v_new_cost:=greatest(((v_basis_qty*r.estimate_unit_cost)+v_delta_after)/v_basis_qty,0);
    v_inventory_delta:=r.receipt_qty*(v_new_cost-v_old_cost);
    v_liability_delta:=r.net_amount-(r.qty_invoiced*r.estimate_unit_cost);
    v_bridge:=v_inventory_delta-v_liability_delta;

    update erp.material_supplier_invoice_lines
    set receipt_estimate_unit_cost_snapshot=r.estimate_unit_cost,
        prior_blended_unit_cost_snapshot=v_old_cost,
        posted_blended_unit_cost_snapshot=v_new_cost,
        grni_clear_amount_snapshot=r.qty_invoiced*r.estimate_unit_cost,
        ap_create_amount_snapshot=r.net_amount,
        inventory_revaluation_snapshot=v_inventory_delta,
        bridge_variance_snapshot=v_bridge
    where id=r.id;

    v_grni_total:=v_grni_total+(r.qty_invoiced*r.estimate_unit_cost);
    v_ap_total:=v_ap_total+r.net_amount;
    v_inventory_total:=v_inventory_total+v_inventory_delta;
    v_bridge_total:=v_bridge_total+v_bridge;
  end loop;

  update erp.material_supplier_invoices
  set status='POSTED',posted_at=clock_timestamp(),posting_reason=coalesce(posting_reason,'Supplier invoice posted')
  where id=h.id;

  if v_grni_total>0.005 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','GRNI_MATERIAL','debit',round(v_grni_total,2),'credit',0));
  end if;
  if v_inventory_total>0.005 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','MATERIAL_INVENTORY','debit',round(v_inventory_total,2),'credit',0));
  elsif v_inventory_total< -0.005 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','MATERIAL_INVENTORY','debit',0,'credit',round(abs(v_inventory_total),2)));
  end if;
  if v_bridge_total>0.005 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','MATERIAL_PURCHASE_VARIANCE','debit',0,'credit',round(v_bridge_total,2)));
  elsif v_bridge_total< -0.005 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','MATERIAL_PURCHASE_VARIANCE','debit',round(abs(v_bridge_total),2),'credit',0));
  end if;
  if v_ap_total>0.005 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','AP_SUPPLIER','debit',0,'credit',round(v_ap_total,2)));
  end if;
  if jsonb_array_length(v_lines)>=2 then
    perform erp.post_journal(
      'MATERIAL_SUPPLIER_INVOICE',h.id,h.invoice_date,
      'Final supplier invoice / GRNI matching '||h.invoice_number,v_lines
    );
  end if;

  for r in
    select distinct l.purchase_item_id
    from erp.material_supplier_invoice_lines l
    where l.invoice_id=h.id order by l.purchase_item_id
  loop
    perform erp.refresh_material_purchase_item_cost(r.purchase_item_id);
    perform erp.refresh_material_purchase_item_match_state(r.purchase_item_id);
  end loop;

  for v_purchase in
    select distinct i.purchase_id
    from erp.material_supplier_invoice_lines l
    join erp.material_purchase_items i on i.id=l.purchase_item_id
    where l.invoice_id=h.id order by i.purchase_id
  loop
    select erp.material_purchase_final_ap_total(v_purchase),
           coalesce((select sum(amount) from erp.supplier_payments where purchase_id=v_purchase and status='POSTED'),0)
    into v_payable,v_paid;
    update erp.material_purchase_headers
    set supplier_invoice_number=h.invoice_number,
        due_date=coalesce(h.due_date,due_date),
        payment_status=case when v_paid>=v_payable-0.01 then 'PAID' when v_paid>0 then 'PARTIAL' else 'UNPAID' end
    where id=v_purchase;
  end loop;
end;
$function$;

alter function "erp"."post_material_supplier_invoice"(p_invoice_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_material_supplier_invoice_v2(p_invoice_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare v_hash text;v_cached jsonb;v_response jsonb;h erp.material_supplier_invoices%rowtype;
begin
  perform erp.require_owner_admin();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'posting reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('invoice_id',p_invoice_id,'expected_version',p_expected_version,'reason',btrim(p_reason)));
  v_cached:=erp._idempotency_begin('post_material_supplier_invoice_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  select * into h from erp.material_supplier_invoices where id=p_invoice_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Supplier invoice must be DRAFT'; end if;
  if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
  update erp.material_supplier_invoices set posting_reason=btrim(p_reason) where id=h.id;
  perform erp.post_material_supplier_invoice(h.id);
  select * into h from erp.material_supplier_invoices where id=h.id;
  v_response:=jsonb_build_object(
    'supplier_invoice_id',h.id,'invoice_number',h.invoice_number,'status',h.status,
    'row_version',h.row_version,
    'net_amount',(select coalesce(sum(net_amount),0) from erp.material_supplier_invoice_lines where invoice_id=h.id)
  );
  return erp._idempotency_complete('post_material_supplier_invoice_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."post_material_supplier_invoice_v2"(p_invoice_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_material_supplier_return(p_return_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  h erp.material_supplier_returns%rowtype;
  r record;
  v_purchase uuid;
  v_invoiced_qty numeric;
  v_prior_ap_qty numeric;
  v_ap_qty numeric;
  v_grni_qty numeric;
  v_paid numeric;
  v_payable numeric;
  v_proposed_relief numeric;
  v_carry numeric(24,6):=0;
  v_ap_relief numeric(24,6):=0;
  v_grni_relief numeric(24,6):=0;
  v_line_carry numeric(24,6);
  v_variance numeric(24,6);
  v_lines jsonb:='[]'::jsonb;
begin
  perform erp.require_internal();
  select * into h from erp.material_supplier_returns where id=p_return_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Supplier return must be DRAFT'; end if;
  if h.location_id is null then raise exception 'Supplier return location is required'; end if;
  if not exists(select 1 from erp.material_supplier_return_items where return_id=h.id) then
    raise exception 'Supplier return has no lines';
  end if;

  for v_purchase in
    select distinct i.purchase_id
    from erp.material_supplier_return_items ri
    join erp.material_purchase_items i on i.id=ri.purchase_item_id
    where ri.return_id=h.id order by i.purchase_id
  loop
    perform 1 from erp.material_purchase_headers where id=v_purchase for update;
  end loop;

  -- Allocate each physical return against already-final AP first; any remaining
  -- quantity cancels the receipt estimate in GRNI. These snapshots are immutable
  -- once the document posts and make reversal deterministic.
  for r in
    select ri.*,i.qty as receipt_qty,i.unit_price as estimate_unit_cost,
           i.invoice_match_state,i.purchase_id
    from erp.material_supplier_return_items ri
    join erp.material_purchase_items i on i.id=ri.purchase_item_id
    where ri.return_id=h.id order by i.id,ri.id
  loop
    perform 1 from erp.material_purchase_items where id=r.purchase_item_id for update;
    v_invoiced_qty:=case when r.invoice_match_state='DIRECT_FINAL'
      then r.receipt_qty else erp.material_purchase_posted_invoice_qty(r.purchase_item_id) end;
    select coalesce(sum(coalesce(x.ap_relief_qty_snapshot,0)),0)
    into v_prior_ap_qty
    from erp.material_supplier_return_items x
    join erp.material_supplier_returns xh on xh.id=x.return_id
    where x.purchase_item_id=r.purchase_item_id and xh.status='POSTED';
    v_ap_qty:=least(r.qty,greatest(v_invoiced_qty-v_prior_ap_qty,0));
    v_grni_qty:=r.qty-v_ap_qty;
    update erp.material_supplier_return_items
    set ap_relief_qty_snapshot=v_ap_qty,
        grni_relief_qty_snapshot=v_grni_qty,
        ap_relief_amount_snapshot=v_ap_qty*r.supplier_credit_unit_price,
        grni_relief_amount_snapshot=v_grni_qty*r.estimate_unit_cost
    where id=r.id;
  end loop;

  for v_purchase in
    select distinct i.purchase_id
    from erp.material_supplier_return_items ri
    join erp.material_purchase_items i on i.id=ri.purchase_item_id
    where ri.return_id=h.id order by i.purchase_id
  loop
    select erp.material_purchase_final_ap_total(v_purchase),
           coalesce((select sum(amount) from erp.supplier_payments where purchase_id=v_purchase and status='POSTED'),0),
           coalesce(sum(ri.ap_relief_amount_snapshot),0)
    into v_payable,v_paid,v_proposed_relief
    from erp.material_supplier_return_items ri
    join erp.material_purchase_items i on i.id=ri.purchase_item_id
    where ri.return_id=h.id and i.purchase_id=v_purchase;
    if v_paid>v_payable-v_proposed_relief+0.01 then
      raise exception 'Supplier return would make payment % exceed projected final AP %. Reverse/correct supplier payment first.',
        v_paid,v_payable-v_proposed_relief;
    end if;
  end loop;

  update erp.material_supplier_returns set status='POSTED' where id=h.id;

  for r in
    select ri.*
    from erp.material_supplier_return_items ri
    where ri.return_id=h.id order by ri.material_id,ri.id
  loop
    insert into erp.material_stock_movements(
      material_id,roll_id,location_id,movement_type,qty_signed,
      source_type,source_id,physical_at,created_by,note
    ) values(
      r.material_id,r.roll_id,h.location_id,'SUPPLIER_RETURN',-r.qty,
      'MATERIAL_SUPPLIER_RETURN_ITEM',r.id,h.physical_at,erp.current_app_user_id(),h.reason
    );

    -- GRNI-backed returns reduce the cost-basis quantity. Recompute the source
    -- purchase layer before replaying chronological MA.
    perform erp.refresh_material_purchase_item_cost(r.purchase_item_id);
    select r.qty*coalesce(msm.unit_cost_snapshot,0)
    into v_line_carry
    from erp.material_stock_movements msm
    where msm.source_type='MATERIAL_SUPPLIER_RETURN_ITEM' and msm.source_id=r.id
    order by msm.system_created_at desc,msm.id desc limit 1;
    v_carry:=v_carry+coalesce(v_line_carry,0);
    v_ap_relief:=v_ap_relief+coalesce(r.ap_relief_amount_snapshot,0);
    v_grni_relief:=v_grni_relief+coalesce(r.grni_relief_amount_snapshot,0);
    if r.roll_id is not null then
      update erp.material_rolls
      set status=case when cached_qty=0 then 'RETURNED_SUPPLIER' else status end,updated_at=now()
      where id=r.roll_id;
    end if;
  end loop;

  v_variance:=v_carry-v_ap_relief-v_grni_relief;
  if v_ap_relief>0.005 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','AP_SUPPLIER','debit',round(v_ap_relief,2),'credit',0));
  end if;
  if v_grni_relief>0.005 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','GRNI_MATERIAL','debit',round(v_grni_relief,2),'credit',0));
  end if;
  if v_variance>0.005 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','MATERIAL_PURCHASE_VARIANCE','debit',round(v_variance,2),'credit',0));
  elsif v_variance< -0.005 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','MATERIAL_PURCHASE_VARIANCE','debit',0,'credit',round(abs(v_variance),2)));
  end if;
  if v_carry>0.005 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'mapping_key','MATERIAL_INVENTORY','debit',0,'credit',round(v_carry,2)));
  end if;
  if jsonb_array_length(v_lines)>=2 then
    perform erp.post_journal(
      'MATERIAL_SUPPLIER_RETURN',h.id,h.physical_at::date,
      'Material returned to supplier; AP/GRNI relief split',v_lines
    );
  end if;

  for v_purchase in
    select distinct i.purchase_id
    from erp.material_supplier_return_items ri
    join erp.material_purchase_items i on i.id=ri.purchase_item_id
    where ri.return_id=h.id order by i.purchase_id
  loop
    select erp.material_purchase_final_ap_total(v_purchase),
           coalesce((select sum(amount) from erp.supplier_payments where purchase_id=v_purchase and status='POSTED'),0)
    into v_payable,v_paid;
    update erp.material_purchase_headers
    set payment_status=case when v_paid>=v_payable-0.01 then 'PAID' when v_paid>0 then 'PARTIAL' else 'UNPAID' end
    where id=v_purchase;
  end loop;
end;
$function$;

alter function "erp"."post_material_supplier_return"(p_return_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_material_supplier_return_v2(p_return_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare v_hash text;v_cached jsonb;v_response jsonb;h erp.material_supplier_returns%rowtype;
begin
  perform erp.require_internal();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'Posting reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('id',p_return_id,'expected_version',p_expected_version,'reason',btrim(p_reason)));
  v_cached:=erp._idempotency_begin('post_material_supplier_return_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  select * into h from erp.material_supplier_returns where id=p_return_id for update;
  if h.id is null then raise exception 'Supplier return not found'; end if;
  if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
  perform erp.post_material_supplier_return(h.id);
  select * into h from erp.material_supplier_returns where id=h.id;
  v_response:=jsonb_build_object('material_supplier_return_id',h.id,'status',h.status,'row_version',h.row_version);
  return erp._idempotency_complete('post_material_supplier_return_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."post_material_supplier_return_v2"(p_return_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_material_transfer_v2(p_transfer_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_header erp.material_transfers%rowtype;
  r record;
  v_cost numeric(24,6);
begin
  perform erp.require_internal();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'Posting reason is required'; end if;
  v_hash := erp._request_hash(jsonb_build_object(
    'transfer_id', p_transfer_id, 'expected_version', p_expected_version,
    'reason', btrim(p_reason)
  ));
  v_cached := erp._idempotency_begin(
    'post_material_transfer_v2', p_client_request_id, v_hash
  );
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason', btrim(p_reason), true);

  select * into v_header
  from erp.material_transfers where id = p_transfer_id for update;
  if v_header.id is null then raise exception 'Material transfer not found'; end if;
  if v_header.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_header.row_version;
  end if;
  if v_header.status <> 'DRAFT' then raise exception 'Material transfer must be DRAFT'; end if;
  if v_header.physical_at > clock_timestamp() + interval '5 minutes' then
    raise exception 'Transfer physical_at cannot be in the future';
  end if;
  if not exists (
    select 1 from erp.locations l
    where l.id = v_header.from_location_id and l.is_active
      and l.location_type = 'RAW_MATERIAL_WAREHOUSE'
  ) or not exists (
    select 1 from erp.locations l
    where l.id = v_header.to_location_id and l.is_active
      and l.location_type = 'RAW_MATERIAL_WAREHOUSE'
  ) then
    raise exception 'Both transfer locations must be active raw-material warehouses';
  end if;
  if not exists (
    select 1 from erp.material_transfer_items i where i.transfer_id = v_header.id
  ) then raise exception 'Material transfer requires at least one line'; end if;

  for r in
    select i.*, m.moving_average_cost
    from erp.material_transfer_items i
    join erp.materials m on m.id = i.material_id and m.is_active
    where i.transfer_id = v_header.id
    order by i.material_id, i.roll_id nulls first, i.id
  loop
    perform pg_advisory_xact_lock(hashtextextended(
      'MATTRANSFER|' || r.material_id::text || '|' ||
      coalesce(r.roll_id::text, 'NO_ROLL'), 0
    ));
    v_cost := coalesce(r.moving_average_cost, 0);
    insert into erp.material_stock_movements(
      material_id, roll_id, location_id, movement_type, qty_signed,
      input_unit_cost, source_type, source_id, physical_at, created_by, note
    ) values (
      r.material_id, r.roll_id, v_header.from_location_id, 'TRANSFER_OUT', -r.qty,
      v_cost, 'MATERIAL_TRANSFER', v_header.id, v_header.physical_at,
      erp.current_app_user_id(), coalesce(r.notes, 'Warehouse transfer out')
    );
    insert into erp.material_stock_movements(
      material_id, roll_id, location_id, movement_type, qty_signed,
      input_unit_cost, source_type, source_id, physical_at, created_by, note
    ) values (
      r.material_id, r.roll_id, v_header.to_location_id, 'TRANSFER_IN', r.qty,
      v_cost, 'MATERIAL_TRANSFER', v_header.id, v_header.physical_at,
      erp.current_app_user_id(), coalesce(r.notes, 'Warehouse transfer in')
    );
  end loop;

  for r in
    select distinct material_id
    from erp.material_transfer_items where transfer_id = v_header.id
  loop
    perform erp.recalculate_material_cost(r.material_id);
  end loop;

  update erp.material_transfers
  set status = 'POSTED', posted_at = clock_timestamp()
  where id = v_header.id
  returning * into v_header;

  v_response := jsonb_build_object(
    'material_transfer_id', v_header.id,
    'status', v_header.status,
    'row_version', v_header.row_version,
    'posted_at', v_header.posted_at,
    'movement_count', (
      select count(*) from erp.material_stock_movements m
      where m.source_type = 'MATERIAL_TRANSFER' and m.source_id = v_header.id
    )
  );
  return erp._idempotency_complete(
    'post_material_transfer_v2', p_client_request_id, v_response
  );
end;
$function$;

alter function "erp"."post_material_transfer_v2"(p_transfer_id uuid, p_client_request_id uuid, p_expected_version bigint, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_misc_finance(p_transaction_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare t erp.misc_finance_transactions%rowtype;c erp.misc_finance_categories%rowtype;v_cash uuid;v_account_type text;v_protected boolean;
begin
  perform erp.require_owner_admin();
  select * into t from erp.misc_finance_transactions where id=p_transaction_id for update;
  if t.id is null or t.status<>'DRAFT' then raise exception 'Misc finance transaction must be DRAFT'; end if;
  select * into c from erp.misc_finance_categories where id=t.category_id and is_active=true;
  if c.id is null or c.category_type<>t.transaction_type then raise exception 'Active misc finance category must match transaction type'; end if;
  select account_type into v_account_type from erp.chart_accounts where id=c.default_account_id and is_active=true;
  if (t.transaction_type='OTHER_INCOME' and v_account_type<>'REVENUE') or (t.transaction_type='OTHER_EXPENSE' and v_account_type<>'EXPENSE') then raise exception 'Misc finance category account type is invalid'; end if;
  select exists(select 1 from erp.accounting_account_mappings aam where aam.account_id=c.default_account_id and aam.mapping_key not in('OTHER_INCOME','OTHER_EXPENSE')) into v_protected;
  if v_protected then raise exception 'Misc finance cannot post to an account reserved for a core ERP workflow'; end if;
  select coa_account_id into v_cash from erp.cash_accounts where id=t.cash_account_id and is_active=true;
  if v_cash is null then raise exception 'Active cash/bank account is required'; end if;
  if t.transaction_type='OTHER_INCOME' then
    perform erp.post_journal('MISC_FINANCE',t.id,t.physical_at::date,coalesce(t.notes,'Other income'),jsonb_build_array(
      jsonb_build_object('account_id',v_cash,'debit',t.amount,'credit',0),jsonb_build_object('account_id',c.default_account_id,'debit',0,'credit',t.amount)));
  else
    perform erp.post_journal('MISC_FINANCE',t.id,t.physical_at::date,coalesce(t.notes,'Other expense'),jsonb_build_array(
      jsonb_build_object('account_id',c.default_account_id,'debit',t.amount,'credit',0),jsonb_build_object('account_id',v_cash,'debit',0,'credit',t.amount)));
  end if;
  update erp.misc_finance_transactions set status='POSTED' where id=t.id;
end;$function$;

alter function "erp"."post_misc_finance"(p_transaction_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_opening_balance(p_opening_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.opening_balance_headers%rowtype; r record; v_lot uuid; v_lot_no text; v_value numeric(24,6); v_unit_hpp numeric(20,6);
  v_debits numeric(24,6):=0; v_credits numeric(24,6):=0; v_lines jsonb:='[]'::jsonb; v_default_fg_location uuid; v_fg_count integer;
  v_product_at timestamptz;
begin
  perform erp.require_owner_admin();
  select * into h from erp.opening_balance_headers where id=p_opening_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Opening balance must be DRAFT'; end if;
  if not exists(select 1 from erp.opening_balance_items where opening_id=h.id) then raise exception 'Opening balance has no lines'; end if;
  select count(*),(array_agg(id order by id))[1] into v_fg_count,v_default_fg_location from erp.locations where location_type='FG_WAREHOUSE' and is_active=true;
  for r in select * from erp.opening_balance_items where opening_id=h.id order by id loop
    if r.balance_type='MATERIAL' then
      if r.material_id is null or r.location_id is null or coalesce(r.qty,0)<=0 then raise exception 'Opening material needs material, location and positive qty'; end if;
      if r.unit_cost_snapshot is null or r.unit_cost_snapshot<0 then raise exception 'Opening material unit cost wajib diisi (0 boleh jika memang nilainya nol)'; end if;
      v_value:=r.qty*r.unit_cost_snapshot;
      insert into erp.material_stock_movements(material_id,roll_id,location_id,movement_type,qty_signed,input_unit_cost,unit_cost_snapshot,source_type,source_id,physical_at,created_by)
      values(r.material_id,r.roll_id,r.location_id,'OPENING',r.qty,r.unit_cost_snapshot,r.unit_cost_snapshot,'OPENING_BALANCE_ITEM',r.id,h.opening_date::timestamptz,erp.current_app_user_id());
      perform erp.recalculate_material_cost(r.material_id);
      if v_value>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',round(v_value,2),'credit',0));v_debits:=v_debits+v_value;end if;
    elsif r.balance_type='FINISHED_GOODS' then
      if r.product_id is null or coalesce(r.qty,0)<=0 or trunc(r.qty)<>r.qty then raise exception 'Opening FG needs product and whole positive pcs qty'; end if;
      if r.location_id is null and v_fg_count<>1 then raise exception 'Opening FG requires location when active FG warehouse count is not exactly one'; end if;
      if r.hpp_input_method='MANUAL' and (r.unit_cost_snapshot is null or r.unit_cost_snapshot<0) then raise exception 'Opening FG HPP manual wajib diisi (0 boleh jika memang HPP nol), atau pilih %% dari harga jual'; end if;
      v_product_at:=erp.product_opening_physical_at(r.product_id,h.opening_date);
      v_unit_hpp:=erp.resolve_opening_fg_unit_hpp(r.id,h.opening_date);v_value:=r.qty*v_unit_hpp;
      v_lot_no:='OPEN-'||h.opening_number||'-'||substr(r.id::text,1,8);
      insert into erp.fg_lots(lot_number,po_id,qc_item_id,product_id,initial_qty_pcs,cached_qty_pcs,produced_at,is_open,lot_origin)
      values(v_lot_no,null,null,r.product_id,r.qty::integer,0,v_product_at,true,'OPENING') returning id into v_lot;
      insert into erp.hpp_versions(lot_id,version_no,cost_state,qty_basis_pcs,total_cost,is_current,calculation_reason,created_by)
      values(v_lot,1,'ACTUAL',r.qty::integer,v_value,true,case when r.hpp_input_method='PRICE_PERCENT' then 'Opening FG HPP from selling price percentage snapshot' else 'Opening FG HPP' end,erp.current_app_user_id());
      perform erp.post_fg_movement(r.product_id,v_lot,coalesce(r.location_id,v_default_fg_location),coalesce(r.quality_grade,'GRADE_A'),'OPENING',r.qty::integer,v_unit_hpp,null,'OPENING_BALANCE_ITEM',r.id,v_product_at,'Opening finished goods',false);
      if v_value>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','FG_INVENTORY','debit',round(v_value,2),'credit',0,'product_id',r.product_id));v_debits:=v_debits+v_value;end if;
    elsif r.balance_type='WIP' then v_value:=coalesce(r.amount,coalesce(r.qty,0)*coalesce(r.unit_cost_snapshot,0));if v_value>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','WIP','debit',round(v_value,2),'credit',0));v_debits:=v_debits+v_value;end if;
    elsif r.balance_type='BS' then
      if coalesce(r.qty,0)>0 and trunc(r.qty)=r.qty then
        if r.product_id is not null then v_product_at:=erp.product_opening_physical_at(r.product_id,h.opening_date); else v_product_at:=h.opening_date::timestamp at time zone 'Asia/Jakarta'; end if;
        insert into erp.bs_cases(bs_number,po_id,product_id,detected_at_stage,cause_source,untracked_type,responsible_contractor_id,qty_pcs,status,physical_at,notes)
        values('OBS-'||h.opening_number||'-'||substr(r.id::text,1,8),null,r.product_id,'UNKNOWN','UNKNOWN','LEGACY',r.contractor_id,r.qty::integer,'OPEN',v_product_at,r.notes);
      end if;
    elsif r.balance_type='CONTRACTOR_RECEIVABLE' then v_value:=coalesce(r.amount,0);if v_value<=0 or r.contractor_id is null then raise exception 'Opening contractor receivable requires contractor and positive amount';end if;v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','CONTRACTOR_RECEIVABLE','debit',v_value,'credit',0,'contractor_id',r.contractor_id));v_debits:=v_debits+v_value;insert into erp.opening_subledger_balances(opening_item_id,party_type,direction,contractor_id,original_amount) values(r.id,'CONTRACTOR','RECEIVABLE',r.contractor_id,v_value);
    elsif r.balance_type='CONTRACTOR_PAYABLE' then v_value:=coalesce(r.amount,0);if v_value<=0 or r.contractor_id is null then raise exception 'Opening contractor payable requires contractor and positive amount';end if;v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',0,'credit',v_value,'contractor_id',r.contractor_id));v_credits:=v_credits+v_value;insert into erp.opening_subledger_balances(opening_item_id,party_type,direction,contractor_id,original_amount) values(r.id,'CONTRACTOR','PAYABLE',r.contractor_id,v_value);
    elsif r.balance_type='VENDOR_PAYABLE' then v_value:=coalesce(r.amount,0);if v_value<=0 or r.vendor_id is null then raise exception 'Opening laundry vendor payable requires vendor and positive amount';end if;v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','AP_VENDOR','debit',0,'credit',v_value,'vendor_id',r.vendor_id));v_credits:=v_credits+v_value;insert into erp.opening_subledger_balances(opening_item_id,party_type,direction,vendor_id,original_amount) values(r.id,'VENDOR','PAYABLE',r.vendor_id,v_value);
    elsif r.balance_type='SUPPLIER_PAYABLE' then v_value:=coalesce(r.amount,0);if v_value<=0 or r.supplier_id is null then raise exception 'Opening material supplier payable requires supplier and positive amount';end if;v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','AP_SUPPLIER','debit',0,'credit',v_value));v_credits:=v_credits+v_value;insert into erp.opening_subledger_balances(opening_item_id,party_type,direction,supplier_id,original_amount) values(r.id,'SUPPLIER','PAYABLE',r.supplier_id,v_value);
    elsif r.balance_type='CUSTOMER_RECEIVABLE' then v_value:=coalesce(r.amount,0);if v_value<=0 or r.customer_id is null then raise exception 'Opening customer receivable requires customer and positive amount';end if;v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','AR_CUSTOMER','debit',v_value,'credit',0,'customer_id',r.customer_id));v_debits:=v_debits+v_value;insert into erp.opening_subledger_balances(opening_item_id,party_type,direction,customer_id,original_amount) values(r.id,'CUSTOMER','RECEIVABLE',r.customer_id,v_value);
    elsif r.balance_type='CASH_BANK' then v_value:=coalesce(r.amount,0);if v_value<=0 or r.cash_account_id is null then raise exception 'Opening cash/bank requires cash_account and positive amount';end if;v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',(select coa_account_id from erp.cash_accounts where id=r.cash_account_id),'debit',v_value,'credit',0));v_debits:=v_debits+v_value;
    elsif r.balance_type='OTHER' then raise exception 'Generic OTHER opening balance is intentionally unsupported; use an explicit mapped balance type';
    end if;
  end loop;
  if v_debits>v_credits then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','OPENING_EQUITY','debit',0,'credit',round(v_debits-v_credits,2)));elsif v_credits>v_debits then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','OPENING_EQUITY','debit',round(v_credits-v_debits,2),'credit',0));end if;
  if jsonb_array_length(v_lines)>=2 then perform erp.post_journal('OPENING_BALANCE',h.id,h.opening_date,'ERP go-live opening balance',v_lines);end if;
  update erp.opening_balance_headers set status='POSTED' where id=h.id;
end$function$;

alter function "erp"."post_opening_balance"(p_opening_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_opening_financial_correction(p_opening_item_id uuid, p_corrected_amount numeric, p_reason text, p_effective_date date DEFAULT CURRENT_DATE)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  i erp.opening_balance_items%rowtype;
  h_status text;
  b erp.opening_subledger_balances%rowtype;
  v_old numeric(20,2);
  v_new numeric(20,2);
  v_delta numeric(20,2);
  v_id uuid;
  v_no text;
  v_lines jsonb:='[]'::jsonb;
  v_cash uuid;
  v_abs numeric(20,2);
  v_seq bigint;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan koreksi saldo awal wajib diisi'; end if;
  if p_corrected_amount is null or p_corrected_amount<0 then raise exception 'Saldo awal hasil koreksi tidak boleh negatif'; end if;
  if p_effective_date is null then raise exception 'Tanggal koreksi saldo awal wajib diisi'; end if;

  select * into i from erp.opening_balance_items where id=p_opening_item_id for update;
  if i.id is null then raise exception 'Item saldo awal tidak ditemukan'; end if;
  select status into h_status from erp.opening_balance_headers where id=i.opening_id for update;
  if h_status<>'POSTED' then raise exception 'Saldo awal harus sudah POSTED sebelum dikoreksi'; end if;
  if i.balance_type not in ('WIP','CONTRACTOR_RECEIVABLE','CONTRACTOR_PAYABLE','VENDOR_PAYABLE','SUPPLIER_PAYABLE','CUSTOMER_RECEIVABLE','CASH_BANK') then
    raise exception 'Jenis saldo awal % tidak dikoreksi lewat jalur finansial ini. Stok MATERIAL/FG gunakan stock adjustment agar lineage tetap aman.',i.balance_type;
  end if;

  select coalesce(max(c.correction_seq),0)+1
    into v_seq
  from erp.opening_financial_corrections c
  where c.opening_item_id=i.id;

  if i.balance_type in ('CONTRACTOR_RECEIVABLE','CONTRACTOR_PAYABLE','VENDOR_PAYABLE','SUPPLIER_PAYABLE','CUSTOMER_RECEIVABLE') then
    select * into b from erp.opening_subledger_balances where opening_item_id=i.id for update;
    if b.id is null then raise exception 'Opening subledger untuk item ini tidak ditemukan'; end if;
    v_old:=b.original_amount;
    if p_corrected_amount < b.settled_amount-0.01 then
      raise exception 'Saldo awal tidak boleh dikoreksi menjadi % karena sudah disettle %. Reverse settlement terkait terlebih dahulu.',p_corrected_amount,b.settled_amount;
    end if;
  else
    select coalesce((select c.corrected_amount from erp.opening_financial_corrections c where c.opening_item_id=i.id and c.status='POSTED' order by c.correction_seq desc limit 1),
                    case when i.balance_type='WIP' then coalesce(i.amount,coalesce(i.qty,0)*coalesce(i.unit_cost_snapshot,0)) else coalesce(i.amount,0) end)::numeric(20,2)
    into v_old;
  end if;

  v_new:=round(p_corrected_amount::numeric,2);
  v_delta:=v_new-v_old;
  if abs(v_delta)<=0.005 then raise exception 'Nilai koreksi sama dengan saldo awal efektif saat ini (%)',v_old; end if;
  v_no:='OFC-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS')||'-'||substr(gen_random_uuid()::text,1,6);
  insert into erp.opening_financial_corrections(correction_number,opening_item_id,previous_amount_snapshot,corrected_amount,delta_amount,effective_date,reason,created_by,created_at,correction_seq)
  values(v_no,i.id,v_old,v_new,v_delta,p_effective_date,p_reason,erp.current_app_user_id(),clock_timestamp(),v_seq) returning id into v_id;

  v_abs:=round(abs(v_delta),2);
  if i.balance_type='CASH_BANK' then
    select coa_account_id into v_cash from erp.cash_accounts where id=i.cash_account_id;
    if v_cash is null then raise exception 'Cash/bank account saldo awal tidak ditemukan'; end if;
    if v_delta>0 then v_lines:=jsonb_build_array(
      jsonb_build_object('account_id',v_cash,'debit',v_abs,'credit',0),
      jsonb_build_object('mapping_key','OPENING_EQUITY','debit',0,'credit',v_abs));
    else v_lines:=jsonb_build_array(
      jsonb_build_object('mapping_key','OPENING_EQUITY','debit',v_abs,'credit',0),
      jsonb_build_object('account_id',v_cash,'debit',0,'credit',v_abs)); end if;
  elsif i.balance_type in ('WIP','CUSTOMER_RECEIVABLE','CONTRACTOR_RECEIVABLE') then
    if v_delta>0 then v_lines:=jsonb_build_array(
      case when i.balance_type='WIP' then jsonb_build_object('mapping_key','WIP','debit',v_abs,'credit',0)
           when i.balance_type='CUSTOMER_RECEIVABLE' then jsonb_build_object('mapping_key','AR_CUSTOMER','debit',v_abs,'credit',0,'customer_id',i.customer_id)
           else jsonb_build_object('mapping_key','CONTRACTOR_RECEIVABLE','debit',v_abs,'credit',0,'contractor_id',i.contractor_id) end,
      jsonb_build_object('mapping_key','OPENING_EQUITY','debit',0,'credit',v_abs));
    else v_lines:=jsonb_build_array(
      jsonb_build_object('mapping_key','OPENING_EQUITY','debit',v_abs,'credit',0),
      case when i.balance_type='WIP' then jsonb_build_object('mapping_key','WIP','debit',0,'credit',v_abs)
           when i.balance_type='CUSTOMER_RECEIVABLE' then jsonb_build_object('mapping_key','AR_CUSTOMER','debit',0,'credit',v_abs,'customer_id',i.customer_id)
           else jsonb_build_object('mapping_key','CONTRACTOR_RECEIVABLE','debit',0,'credit',v_abs,'contractor_id',i.contractor_id) end); end if;
  else
    if v_delta>0 then v_lines:=jsonb_build_array(
      jsonb_build_object('mapping_key','OPENING_EQUITY','debit',v_abs,'credit',0),
      case when i.balance_type='SUPPLIER_PAYABLE' then jsonb_build_object('mapping_key','AP_SUPPLIER','debit',0,'credit',v_abs)
           when i.balance_type='VENDOR_PAYABLE' then jsonb_build_object('mapping_key','AP_VENDOR','debit',0,'credit',v_abs,'vendor_id',i.vendor_id)
           else jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',0,'credit',v_abs,'contractor_id',i.contractor_id) end);
    else v_lines:=jsonb_build_array(
      case when i.balance_type='SUPPLIER_PAYABLE' then jsonb_build_object('mapping_key','AP_SUPPLIER','debit',v_abs,'credit',0)
           when i.balance_type='VENDOR_PAYABLE' then jsonb_build_object('mapping_key','AP_VENDOR','debit',v_abs,'credit',0,'vendor_id',i.vendor_id)
           else jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',v_abs,'credit',0,'contractor_id',i.contractor_id) end,
      jsonb_build_object('mapping_key','OPENING_EQUITY','debit',0,'credit',v_abs)); end if;
  end if;

  perform erp.post_journal('OPENING_FINANCIAL_CORRECTION',v_id,p_effective_date,'Correction saldo awal: '||p_reason,v_lines);
  if b.id is not null then
    update erp.opening_subledger_balances
    set original_amount=v_new,
        status=case when settled_amount>=v_new-0.01 then 'SETTLED' when settled_amount>0 then 'PARTIAL' else 'OPEN' end,
        updated_at=now()
    where id=b.id;
  end if;
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('opening_balance_items',i.id,'UPDATE',jsonb_build_object('correction_id',v_id,'previous_amount',v_old,'corrected_amount',v_new,'delta',v_delta,'correction_type','OPENING_FINANCIAL_CORRECTION'),erp.current_app_user_id(),p_reason);
  return v_id;
end;
$function$;

alter function "erp"."post_opening_financial_correction"(p_opening_item_id uuid, p_corrected_amount numeric, p_reason text, p_effective_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_opening_hpp_correction(p_lot_id uuid, p_new_hpp numeric, p_reason text, p_effective_date date DEFAULT CURRENT_DATE)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare l erp.fg_lots%rowtype;v_old_id uuid;v_old_hpp numeric(20,6);v_ver integer;v_new_id uuid;v_corr uuid;v_no text;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan koreksi HPP opening wajib diisi'; end if;
  if p_new_hpp is null or p_new_hpp<0 then raise exception 'HPP opening hasil koreksi tidak boleh negatif'; end if;
  select * into l from erp.fg_lots where id=p_lot_id for update;
  if l.id is null or l.lot_origin<>'OPENING' then raise exception 'Koreksi HPP opening hanya untuk lot saldo awal'; end if;
  if exists(select 1 from erp.product_conversion_allocations pca join erp.product_conversions pc on pc.id=pca.conversion_id where pca.source_lot_id=l.id and pc.status='POSTED') then
    raise exception 'Lot opening sudah pernah dipakai conversion/rebrand. Reverse/correct conversion tersebut dulu sebelum mengubah HPP opening.';
  end if;
  select hpp_version_id,hpp_per_pcs into v_old_id,v_old_hpp from erp.v_current_hpp where lot_id=l.id;
  if v_old_id is null then raise exception 'Current HPP lot opening tidak ditemukan'; end if;
  if abs(v_old_hpp-p_new_hpp)<=0.000001 then raise exception 'HPP baru sama dengan HPP current (%)',v_old_hpp; end if;
  select coalesce(max(version_no),0)+1 into v_ver from erp.hpp_versions where lot_id=l.id;
  update erp.hpp_versions set is_current=false where lot_id=l.id and is_current=true;
  insert into erp.hpp_versions(lot_id,version_no,cost_state,qty_basis_pcs,total_cost,is_current,supersedes_id,calculation_reason,created_by)
  values(l.id,v_ver,'ADJUSTED',l.initial_qty_pcs,l.initial_qty_pcs*p_new_hpp,true,v_old_id,'Controlled opening HPP correction: '||p_reason,erp.current_app_user_id()) returning id into v_new_id;
  v_no:='OHPP-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS')||'-'||substr(gen_random_uuid()::text,1,6);
  insert into erp.opening_hpp_corrections(correction_number,lot_id,previous_hpp_snapshot,corrected_hpp,effective_date,reason,hpp_version_id,created_by)
  values(v_no,l.id,v_old_hpp,p_new_hpp,p_effective_date,p_reason,v_new_id,erp.current_app_user_id()) returning id into v_corr;
  perform erp.sync_opening_lot_hpp_to_gl(l.id,p_effective_date);
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('fg_lots',l.id,'UPDATE',jsonb_build_object('correction_id',v_corr,'previous_hpp',v_old_hpp,'corrected_hpp',p_new_hpp),erp.current_app_user_id(),p_reason);
  return v_corr;
end;$function$;

alter function "erp"."post_opening_hpp_correction"(p_lot_id uuid, p_new_hpp numeric, p_reason text, p_effective_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_opening_hpp_correction_from_price_percent(p_lot_id uuid, p_percent numeric, p_reason text, p_effective_date date DEFAULT CURRENT_DATE)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  l erp.fg_lots%rowtype;
  v_price numeric(20,6);
  v_hpp numeric(20,6);
  v_corr uuid;
begin
  perform erp.require_owner_admin();
  if p_percent is null or p_percent<=0 or p_percent>1000 then raise exception 'Persentase HPP harus >0 dan masuk akal'; end if;
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan koreksi HPP opening wajib diisi'; end if;

  select * into l from erp.fg_lots where id=p_lot_id for update;
  if l.id is null or l.lot_origin<>'OPENING' then raise exception 'Lot opening tidak ditemukan'; end if;

  -- Business rule: percentage-based opening HPP is always based on the selling
  -- price valid at the opening/cutover physical timestamp. A later correction
  -- date changes the correction journal date, not the historical price basis.
  v_price:=erp.resolve_product_price_at(l.product_id,l.produced_at);
  if v_price is null then
    raise exception 'Harga jual historis produk tidak tersedia pada waktu opening/cutover %. Isi histori harga tersebut atau gunakan koreksi HPP manual.',l.produced_at;
  end if;

  v_hpp:=round(v_price*p_percent/100.0,6);
  v_corr:=erp.post_opening_hpp_correction(l.id,v_hpp,p_reason,p_effective_date);
  update erp.opening_hpp_corrections
  set source_method='PRICE_PERCENT',reference_sell_price_snapshot=v_price,percent_of_price=p_percent
  where id=v_corr;
  return v_corr;
end;
$function$;

alter function "erp"."post_opening_hpp_correction_from_price_percent"(p_lot_id uuid, p_percent numeric, p_reason text, p_effective_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_opening_subledger_settlement(p_settlement_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
DECLARE s erp.opening_subledger_settlements%ROWTYPE;b erp.opening_subledger_balances%ROWTYPE;v_cash uuid;v_remaining numeric(20,2);v_lines jsonb;
BEGIN PERFORM erp.require_owner_admin();SELECT * INTO s FROM erp.opening_subledger_settlements WHERE id=p_settlement_id FOR UPDATE;IF s.id IS NULL OR s.status<>'DRAFT' THEN RAISE EXCEPTION 'Opening subledger settlement must be DRAFT';END IF;SELECT * INTO b FROM erp.opening_subledger_balances WHERE id=s.balance_id FOR UPDATE;IF b.id IS NULL OR b.status='SETTLED' THEN RAISE EXCEPTION 'Opening subledger balance is not open';END IF;v_remaining:=b.original_amount-b.settled_amount;IF s.amount>v_remaining+0.01 THEN RAISE EXCEPTION 'Settlement exceeds opening outstanding. Remaining %, requested %',v_remaining,s.amount;END IF;SELECT coa_account_id INTO v_cash FROM erp.cash_accounts WHERE id=s.cash_account_id AND is_active=true;IF v_cash IS NULL THEN RAISE EXCEPTION 'Active cash/bank account is required';END IF;
IF b.direction='RECEIVABLE' AND b.party_type='CUSTOMER' THEN v_lines:=jsonb_build_array(jsonb_build_object('account_id',v_cash,'debit',s.amount,'credit',0,'customer_id',b.customer_id),jsonb_build_object('mapping_key','AR_CUSTOMER','debit',0,'credit',s.amount,'customer_id',b.customer_id));ELSIF b.direction='RECEIVABLE' AND b.party_type='CONTRACTOR' THEN v_lines:=jsonb_build_array(jsonb_build_object('account_id',v_cash,'debit',s.amount,'credit',0,'contractor_id',b.contractor_id),jsonb_build_object('mapping_key','CONTRACTOR_RECEIVABLE','debit',0,'credit',s.amount,'contractor_id',b.contractor_id));ELSIF b.direction='PAYABLE' AND b.party_type='SUPPLIER' THEN v_lines:=jsonb_build_array(jsonb_build_object('mapping_key','AP_SUPPLIER','debit',s.amount,'credit',0),jsonb_build_object('account_id',v_cash,'debit',0,'credit',s.amount));ELSIF b.direction='PAYABLE' AND b.party_type='VENDOR' THEN v_lines:=jsonb_build_array(jsonb_build_object('mapping_key','AP_VENDOR','debit',s.amount,'credit',0,'vendor_id',b.vendor_id),jsonb_build_object('account_id',v_cash,'debit',0,'credit',s.amount,'vendor_id',b.vendor_id));ELSIF b.direction='PAYABLE' AND b.party_type='CONTRACTOR' THEN v_lines:=jsonb_build_array(jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',s.amount,'credit',0,'contractor_id',b.contractor_id),jsonb_build_object('account_id',v_cash,'debit',0,'credit',s.amount,'contractor_id',b.contractor_id));ELSE RAISE EXCEPTION 'Unsupported opening subledger direction/party combination';END IF;
PERFORM erp.post_journal('OPENING_SUBLEDGER_SETTLEMENT',s.id,s.physical_at::date,'Opening subledger settlement '||s.settlement_number,v_lines);UPDATE erp.opening_subledger_settlements SET status='POSTED',updated_at=now() WHERE id=s.id;UPDATE erp.opening_subledger_balances SET settled_amount=settled_amount+s.amount,status=CASE WHEN settled_amount+s.amount>=original_amount-0.01 THEN 'SETTLED' ELSE 'PARTIAL' END,updated_at=now() WHERE id=b.id;END;$function$;

alter function "erp"."post_opening_subledger_settlement"(p_settlement_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_payroll_payment(p_payroll_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.payroll_settlements%rowtype;
  v_cash uuid;
  v_material_deduction numeric(20,2):=0;
  v_other_deduction numeric(20,2):=0;
  v_expected_attendance numeric(20,2):=0;
  v_actual_attendance numeric(20,2):=0;
  v_attendance_journal_count bigint:=0;
  r record;
begin
  perform erp.require_internal();
  select * into p from erp.payroll_settlements where id=p_payroll_id for update;
  if p.id is null or p.status<>'APPROVED' then raise exception 'Payroll must be APPROVED'; end if;
  perform erp._cp3_lock_business_period(p.period_start,p.period_end);
  if p.net_payable<0 then raise exception 'Payroll net payable cannot be negative; carry deductions forward instead'; end if;
  if p.payment_date is null then raise exception 'Payroll payment date is required'; end if;
  if p.payment_date>current_date then raise exception 'Tanggal pembayaran payroll berada di masa depan'; end if;
  if p.net_payable>0 then
    select coa_account_id into v_cash from erp.cash_accounts where id=p.payment_cash_account_id and is_active=true;
    if v_cash is null then raise exception 'Active payroll cash/bank account is required when cash payment is positive'; end if;
  end if;

  v_expected_attendance:=round(coalesce(p.attendance_total,0),2);
  select count(distinct je.id),coalesce(sum(jl.debit),0)
    into v_attendance_journal_count,v_actual_attendance
  from erp.journal_entries je
  join erp.journal_lines jl on jl.journal_entry_id=je.id
  where je.source_type='PAYROLL_ATTENDANCE_ACCRUAL' and je.source_id=p.id and je.status='POSTED'
    and jl.account_id=erp.account_id('WIP') and jl.debit>0;
  if (v_expected_attendance=0 and v_attendance_journal_count<>0)
     or (v_expected_attendance>0 and (v_attendance_journal_count<>1 or round(v_actual_attendance,2) is distinct from v_expected_attendance)) then
    raise exception 'PAYROLL_APPROVAL_ACCRUAL_MISSING_OR_MISMATCH: expected attendance %, journal count %, WIP debit %',
      v_expected_attendance,v_attendance_journal_count,round(v_actual_attendance,2);
  end if;

  select coalesce(sum(amount),0) into v_material_deduction
  from erp.payroll_deductions where payroll_id=p.id and deduction_type='MATERIAL_KASBON';
  select coalesce(sum(amount),0) into v_other_deduction
  from erp.payroll_deductions where payroll_id=p.id and deduction_type<>'MATERIAL_KASBON';
  if v_material_deduction>0 then
    perform erp.post_journal('PAYROLL_MATERIAL_DEDUCTION',p.id,p.payment_date,
      'Physical material/accessory purchase deduction',jsonb_build_array(
        jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',v_material_deduction,'credit',0,'contractor_id',p.contractor_id),
        jsonb_build_object('mapping_key','CONTRACTOR_RECEIVABLE','debit',0,'credit',v_material_deduction,'contractor_id',p.contractor_id)));
  end if;
  if v_other_deduction>0 then
    perform erp.post_journal('PAYROLL_OTHER_DEDUCTION',p.id,p.payment_date,
      'BS/penalty/other payroll deduction',jsonb_build_array(
        jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',v_other_deduction,'credit',0,'contractor_id',p.contractor_id),
        jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',v_other_deduction,'contractor_id',p.contractor_id)));
  end if;
  if p.net_payable>0 then
    perform erp.post_journal('PAYROLL_PAYMENT',p.id,p.payment_date,'Mandor payroll payment',jsonb_build_array(
      jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',p.net_payable,'credit',0,'contractor_id',p.contractor_id),
      jsonb_build_object('account_id',v_cash,'debit',0,'credit',p.net_payable,'contractor_id',p.contractor_id)));
  end if;

  update erp.payroll_settlements set status='PAID',settled_at=now(),updated_at=now() where id=p.id;
  for r in select distinct pd.contractor_issue_item_id id from erp.payroll_deductions pd
           where pd.payroll_id=p.id and pd.contractor_issue_item_id is not null
  loop perform erp.refresh_contractor_issue_payroll_status(r.id); end loop;
  update erp.contractor_accessory_reimbursement_entitlements e set payroll_status='SETTLED'
  where e.id in(select pr.source_id from erp.payroll_reimbursements pr
                where pr.payroll_id=p.id and pr.source_type='ACCESSORY_BOM' and pr.source_id is not null);
  for r in
    select distinct bc.id as bs_case_id from erp.bs_cases bc
    where exists(select 1 from erp.payroll_work_items pwi where pwi.payroll_id=p.id and pwi.po_id=bc.po_id)
       or exists(select 1 from erp.payroll_work_items pwi join erp.rework_component_lines rcl on rcl.id=pwi.source_id
                 join erp.bs_case_components bcc on bcc.id=rcl.bs_case_component_id
                 where pwi.payroll_id=p.id and bcc.bs_case_id=bc.id)
  loop perform erp.rebuild_bs_component_counters(r.bs_case_id); end loop;

  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('payroll_settlements',p.id,'POST',
    jsonb_build_object('lifecycle_action','PAY','payment_settlement_only',true,'attendance_accrual_created_at_payment',false),
    erp.current_app_user_id(),'Payroll payment settled approved payable without recognizing attendance cost again');
end;
$function$;

alter function "erp"."post_payroll_payment"(p_payroll_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_product_conversion(p_conversion_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.product_conversions%rowtype;
  r record;
  v_need integer;
  v_take integer;
  v_source_hpp numeric(18,6);
  v_dest_hpp numeric(18,6);
  v_dest_lot uuid;
  v_dest_lot_no text;
  v_source_value numeric(24,6):=0;
  v_lock_product uuid;
begin
  perform erp.require_internal();
  select * into h from erp.product_conversions where id=p_conversion_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Product conversion must be DRAFT'; end if;
  if coalesce(h.conversion_cost_total,0)<>0 then raise exception 'Non-zero conversion cost requires a sourced accounting workflow; unsafe unsourced HPP capitalization is blocked'; end if;

  -- Old/superseded stock may still be consumed, but a future identity may not.
  perform erp.assert_product_identity_time(h.from_product_id,h.physical_at,'EXISTING_STOCK');
  -- New physical stock must use the identity version effective at the conversion time.
  perform erp.assert_product_identity_time(h.to_product_id,h.physical_at,'NEW_STOCK');

  insert into erp.fg_inventory_balances(product_id,location_id,quality_grade,cached_qty_pcs)
  values(h.from_product_id,h.location_id,'GRADE_A',0)
  on conflict(product_id,location_id,quality_grade) do nothing;
  insert into erp.fg_inventory_balances(product_id,location_id,quality_grade,cached_qty_pcs)
  values(h.to_product_id,h.location_id,'GRADE_A',0)
  on conflict(product_id,location_id,quality_grade) do nothing;
  for v_lock_product in select x from (values(h.from_product_id),(h.to_product_id)) v(x) group by x order by x loop
    perform 1 from erp.fg_inventory_balances
    where product_id=v_lock_product and location_id=h.location_id and quality_grade='GRADE_A'
    for update;
  end loop;

  v_need:=h.qty_pcs;
  delete from erp.product_conversion_allocations where conversion_id=h.id;
  for r in
    select fl.id,fl.po_id,fl.produced_at,sum(fm.qty_signed)::integer as location_qty
    from erp.fg_lots fl
    join erp.fg_stock_movements fm on fm.lot_id=fl.id
    where fl.product_id=h.from_product_id and fm.location_id=h.location_id and fm.quality_grade='GRADE_A'
    group by fl.id,fl.po_id,fl.produced_at
    having sum(fm.qty_signed)>0
    order by fl.produced_at,fl.id
  loop
    exit when v_need<=0;
    v_take:=least(v_need,r.location_qty);
    perform 1 from erp.fg_lots where id=r.id for update;
    v_source_hpp:=coalesce(erp.lock_current_hpp_per_pcs(r.id),0);
    v_dest_hpp:=v_source_hpp;
    v_dest_lot_no:=h.conversion_number||'-'||substr(r.id::text,1,8)||'-'||substr(gen_random_uuid()::text,1,6);
    insert into erp.fg_lots(lot_number,po_id,qc_item_id,product_id,initial_qty_pcs,cached_qty_pcs,produced_at,is_open,lot_origin,source_lot_id)
    values(v_dest_lot_no,r.po_id,null,h.to_product_id,v_take,0,h.physical_at,true,'CONVERSION',r.id) returning id into v_dest_lot;
    insert into erp.hpp_versions(lot_id,version_no,cost_state,qty_basis_pcs,total_cost,is_current,calculation_reason,created_by)
    values(v_dest_lot,1,'ADJUSTED',v_take,v_take*v_dest_hpp,true,'SKU conversion/rebrand carry-forward',erp.current_app_user_id());
    insert into erp.hpp_version_components(hpp_version_id,component_type,description,total_cost,source_type,source_id)
    select hv.id,'OTHER','HPP carried from source lot',v_take*v_source_hpp,'FG_LOT',r.id from erp.hpp_versions hv where hv.lot_id=v_dest_lot and hv.version_no=1;
    perform erp.post_fg_movement(h.from_product_id,r.id,h.location_id,'GRADE_A','REBRAND_OUT',-v_take,v_source_hpp,null,'PRODUCT_CONVERSION',h.id,h.physical_at,'SKU conversion OUT',false);
    perform erp.post_fg_movement(h.to_product_id,v_dest_lot,h.location_id,'GRADE_A','REBRAND_IN',v_take,v_dest_hpp,null,'PRODUCT_CONVERSION',h.id,h.physical_at,'SKU conversion IN',false);
    insert into erp.product_conversion_allocations(conversion_id,source_lot_id,destination_lot_id,qty_pcs,original_hpp_per_pcs,conversion_cost_allocated)
    values(h.id,r.id,v_dest_lot,v_take,v_source_hpp,0);
    v_source_value:=v_source_value+(v_take*v_source_hpp);
    v_need:=v_need-v_take;
  end loop;
  if v_need>0 then raise exception 'Insufficient source stock for conversion; short % pcs',v_need; end if;
  update erp.product_conversions set status='POSTED' where id=h.id;
  if v_source_value>0 then
    perform erp.post_journal('PRODUCT_CONVERSION',h.id,h.physical_at::date,'SKU conversion/rebrand',jsonb_build_array(
      jsonb_build_object('mapping_key','FG_INVENTORY','debit',round(v_source_value,2),'credit',0,'product_id',h.to_product_id),
      jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',round(v_source_value,2),'product_id',h.from_product_id)));
  end if;
end$function$;

alter function "erp"."post_product_conversion"(p_conversion_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_qc(p_qc_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.qc_inspections%rowtype;
  r record;
  v_lot_id uuid;
  v_lot_number text;
begin
  perform erp.require_internal();
  select * into h from erp.qc_inspections where id=p_qc_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'QC must be DRAFT'; end if;
  if h.destination_location_id is null then raise exception 'QC destination FG location is required'; end if;
  if not exists(select 1 from erp.qc_inspection_items where inspection_id=h.id) then raise exception 'QC has no items'; end if;

  -- Validate all SKU identities before creating any FG/BS side effect.
  for r in
    select qi.*,p.sku
    from erp.qc_inspection_items qi
    join erp.products p on p.id=qi.final_product_id
    where qi.inspection_id=h.id
    order by qi.id
  loop
    perform erp.assert_product_identity_time(r.final_product_id,h.physical_at,'NEW_STOCK');
  end loop;

  for r in
    select qi.*,p.sku
    from erp.qc_inspection_items qi
    join erp.products p on p.id=qi.final_product_id
    where qi.inspection_id=h.id
    order by qi.id
  loop
    if r.qty_good_pcs>0 then
      v_lot_number:=h.inspection_number||'-'||regexp_replace(r.sku,'[^A-Za-z0-9]+','','g')||'-'||substr(r.id::text,1,8);
      insert into erp.fg_lots(
        lot_number,po_id,qc_item_id,cutting_group_id,product_id,initial_qty_pcs,cached_qty_pcs,produced_at,lot_origin
      ) values(
        v_lot_number,h.po_id,r.id,r.cutting_group_id,r.final_product_id,r.qty_good_pcs,0,h.physical_at,'PRODUCTION'
      ) returning id into v_lot_id;
      perform erp.post_fg_movement(r.final_product_id,v_lot_id,h.destination_location_id,'GRADE_A','QC_GOOD',r.qty_good_pcs,0,null,'QC_ITEM',r.id,h.physical_at,'QC good output',false);
      perform erp.ensure_fg_accessory_cost_snapshot(v_lot_id);
      perform erp.post_accessory_reimbursement_accrual(v_lot_id);
    end if;

    if r.qty_bs_pcs>0 then
      insert into erp.bs_cases(bs_number,po_id,cutting_group_id,qc_item_id,product_id,detected_at_stage,cause_source,qty_pcs,status,physical_at,notes)
      values('BS-QC-'||h.inspection_number||'-'||substr(r.id::text,1,8),h.po_id,r.cutting_group_id,r.id,r.final_product_id,'QC','UNKNOWN',r.qty_bs_pcs,'OPEN',h.physical_at,'Detected at QC; classify cause when known')
      on conflict(bs_number) do nothing;
    end if;
  end loop;

  update erp.qc_inspections set status='POSTED',updated_at=now() where id=h.id;
  update erp.production_orders set status='QC',current_stage='QC',updated_at=now() where id=h.po_id;
  perform erp.sync_laundry_accrual(h.po_id,h.physical_at::date);
  perform erp.rebuild_po_hpp(h.po_id,'QC posted / batch-lineage HPP snapshot / output lot created');
  perform erp.propagate_conversion_hpp_for_po(h.po_id);
  perform erp.sync_po_hpp_to_gl(h.po_id,h.physical_at::date);
end$function$;

alter function "erp"."post_qc"(p_qc_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_rework_completion(p_rework_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare r erp.rework_orders%rowtype;b erp.bs_cases%rowtype;v_total numeric(20,2):=0;v_location uuid;v_location_count integer:=0;v_lot uuid;v_lot_number text;v_hpp numeric(18,6):=0;v_remaining integer:=0;v_completed_at timestamptz;
begin
  perform erp.require_internal();select * into r from erp.rework_orders where id=p_rework_order_id for update;if r.id is null then raise exception 'Rework order not found';end if;if r.status<>'COMPLETED' then raise exception 'Rework must be COMPLETED before posting';end if;if r.qty_good_returned+r.qty_bs_returned<>r.qty_sent then raise exception 'Rework completion must reconcile exactly: GOOD + BS must equal qty sent';end if;if r.cost_posted then return;end if;
  select * into b from erp.bs_cases where id=r.bs_case_id for update;if b.id is null then raise exception 'BS case not found';end if;v_completed_at:=coalesce(r.completed_at,now());
  if r.qty_good_returned>0 then
    if b.po_id is null or b.product_id is null then raise exception 'GOOD rework return requires native production PO and product lineage';end if;
    if r.return_fg_location_id is not null then select id into v_location from erp.locations where id=r.return_fg_location_id and is_active=true and location_type='FG_WAREHOUSE';if v_location is null then raise exception 'Selected rework return location must be an active FG warehouse';end if;
    else select count(*),(array_agg(id order by id))[1] into v_location_count,v_location from erp.locations where is_active=true and location_type='FG_WAREHOUSE';if v_location_count<>1 then raise exception 'Select return FG warehouse for rework GOOD output; active FG warehouse count is %',v_location_count;end if;end if;
    v_lot_number:='RW-'||r.rework_number||'-'||substr(r.id::text,1,8);
    insert into erp.fg_lots(lot_number,po_id,qc_item_id,cutting_group_id,product_id,initial_qty_pcs,cached_qty_pcs,produced_at,is_open,lot_origin) values(v_lot_number,b.po_id,b.qc_item_id,b.cutting_group_id,b.product_id,r.qty_good_returned,0,v_completed_at,true,'PRODUCTION') returning id into v_lot;
    perform erp.post_fg_movement(b.product_id,v_lot,v_location,'GRADE_A','REWORK_IN',r.qty_good_returned,0,null,'REWORK_ORDER',r.id,v_completed_at,'GOOD returned from rework',false);
    perform erp.ensure_fg_accessory_cost_snapshot(v_lot);perform erp.post_accessory_reimbursement_accrual(v_lot);
    update erp.rework_orders set good_fg_lot_id=v_lot,return_fg_location_id=v_location,completed_at=v_completed_at where id=r.id;
    insert into erp.bs_resolutions(bs_case_id,resolution_type,qty_pcs,compensation_amount,responsible_contractor_id,responsible_vendor_id,source_rework_order_id,physical_at,notes) values(b.id,case when r.destination_type='CONTRACTOR' then 'REWORK_SEWING' else 'REWORK_LAUNDRY' end,r.qty_good_returned,0,r.contractor_id,r.vendor_id,r.id,v_completed_at,'Recovered to GOOD FG from rework');
  else update erp.rework_orders set completed_at=v_completed_at where id=r.id;end if;
  select greatest(b.qty_pcs-coalesce(sum(br.qty_pcs),0),0)::integer into v_remaining from erp.bs_resolutions br where br.bs_case_id=b.id;
  update erp.bs_cases set status=case when v_remaining=0 then 'RESOLVED' else 'PARTIAL' end,updated_at=now() where id=b.id;
  if r.destination_type='CONTRACTOR' then select coalesce(sum(amount_payable),0) into v_total from erp.rework_component_lines where rework_order_id=r.id;if v_total>0 then perform erp.post_journal('REWORK_COMPLETION',r.id,v_completed_at::date,'Rework labor completion',jsonb_build_array(jsonb_build_object('mapping_key','WIP','debit',round(v_total,2),'credit',0,'contractor_id',r.contractor_id,'po_id',b.po_id),jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',0,'credit',round(v_total,2),'contractor_id',r.contractor_id,'po_id',b.po_id)));end if;end if;
  update erp.rework_orders set cost_posted=true where id=r.id;
  if b.po_id is not null and exists(select 1 from erp.fg_lots where po_id=b.po_id) then perform erp.rebuild_po_hpp(b.po_id,'Rework completion posted with physical GOOD return');perform erp.propagate_conversion_hpp_for_po(b.po_id);perform erp.sync_po_hpp_to_gl(b.po_id,v_completed_at::date);if v_lot is not null then select coalesce(hpp_per_pcs,0) into v_hpp from erp.v_current_hpp where lot_id=v_lot;update erp.fg_stock_movements set unit_hpp_snapshot=v_hpp where lot_id=v_lot and movement_type='REWORK_IN' and source_type='REWORK_ORDER' and source_id=r.id;end if;end if;
end;$function$;

alter function "erp"."post_rework_completion"(p_rework_order_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_sale(p_sale_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  h erp.sales_headers%rowtype;
  v_sales numeric(24,6) := 0;
  v_cogs numeric(24,6) := 0;
  v_item_qty bigint;
  v_reserved_qty bigint;
  v_lines jsonb := '[]'::jsonb;
begin
  perform erp.require_internal();
  select * into h from erp.sales_headers where id=p_sale_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Sale must be DRAFT'; end if;
  if h.source_location_id is null then raise exception 'Sale source FG location is required'; end if;
  if not exists(select 1 from erp.sales_items where sale_id=p_sale_id) then raise exception 'Sale has no items'; end if;

  select coalesce(sum(qty_pcs),0),coalesce(sum(line_total),0)
  into v_item_qty,v_sales
  from erp.sales_items where sale_id=h.id;
  select coalesce(sum(abs(m.qty_signed)),0)
  into v_reserved_qty
  from erp.fg_stock_movements m
  join erp.sales_items i on i.id=m.source_id
  where i.sale_id=h.id and m.source_type='SALE_ITEM' and m.movement_type='SALE_RESERVE'
    and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id);

  if v_reserved_qty=0 then
    v_reserved_qty:=erp._reserve_sale_draft(h.id);
  end if;
  if v_reserved_qty<>v_item_qty then
    raise exception 'Sale Draft reservation mismatch. Items %, active reservation %',v_item_qty,v_reserved_qty;
  end if;
  if exists (
    select 1 from erp.sales_items i
    left join (
      select sale_item_id,sum(qty_pcs)::bigint qty_pcs
      from erp.sale_stock_allocations group by sale_item_id
    ) a on a.sale_item_id=i.id
    where i.sale_id=h.id and coalesce(a.qty_pcs,0)<>i.qty_pcs
  ) then raise exception 'Sale allocation does not match Draft line quantity'; end if;

  select coalesce(sum(a.qty_pcs*a.unit_hpp_snapshot),0)
  into v_cogs
  from erp.sale_stock_allocations a
  join erp.sales_items i on i.id=a.sale_item_id
  where i.sale_id=h.id;

  -- This is the key invariant: posting changes classification only. Quantity was
  -- already deducted at Draft time and must not be deducted a second time.
  update erp.fg_stock_movements m
  set movement_type='SALE', notes='Sale posted · quantity already reserved in Draft'
  from erp.sales_items i
  where i.id=m.source_id and i.sale_id=h.id
    and m.source_type='SALE_ITEM' and m.movement_type='SALE_RESERVE'
    and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id);

  update erp.sales_headers set status='POSTED' where id=h.id;
  if abs(v_sales)>0.005 then
    v_lines:=v_lines||jsonb_build_array(
      jsonb_build_object('mapping_key','AR_CUSTOMER','debit',round(v_sales,2),'credit',0,'customer_id',h.customer_id),
      jsonb_build_object('mapping_key','SALES_REVENUE','debit',0,'credit',round(v_sales,2),'customer_id',h.customer_id));
  end if;
  if abs(v_cogs)>0.005 then
    v_lines:=v_lines||jsonb_build_array(
      jsonb_build_object('mapping_key','COGS','debit',round(v_cogs,2),'credit',0,'customer_id',h.customer_id),
      jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',round(v_cogs,2),'customer_id',h.customer_id));
  end if;
  if jsonb_array_length(v_lines)>=2 then
    perform erp.post_journal('SALE',h.id,h.sale_date::date,'Sales to customer/toko',v_lines);
  end if;
end;
$function$;

alter function "erp"."post_sale"(p_sale_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_sale_v2(p_sale_id uuid, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  h erp.sales_headers%rowtype;
  v_before bigint;
  v_after bigint;
  v_qty bigint;
begin
  perform erp.require_internal();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'sale_id',p_sale_id,'expected_version',p_expected_version
  ));
  v_cached:=erp._idempotency_begin('post_sale_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  select * into h from erp.sales_headers where id=p_sale_id for update;
  if h.id is null then raise exception 'Sale not found'; end if;
  if h.status<>'DRAFT' then raise exception 'Sale must be DRAFT'; end if;
  if h.row_version<>p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version;
  end if;
  select coalesce(sum(b.cached_qty_pcs),0) into v_before
  from erp.fg_inventory_balances b
  where b.location_id=h.source_location_id and b.quality_grade='GRADE_A'
    and b.product_id in (select product_id from erp.sales_items where sale_id=h.id);
  select coalesce(sum(qty_pcs),0) into v_qty from erp.sales_items where sale_id=h.id;
  perform erp.post_sale(h.id);
  select * into h from erp.sales_headers where id=h.id;
  select coalesce(sum(b.cached_qty_pcs),0) into v_after
  from erp.fg_inventory_balances b
  where b.location_id=h.source_location_id and b.quality_grade='GRADE_A'
    and b.product_id in (select product_id from erp.sales_items where sale_id=h.id);
  if v_before is distinct from v_after then
    raise exception 'Invariant violation: posting changed FG balance after Draft reservation';
  end if;
  v_response:=jsonb_build_object(
    'sale_id',h.id,'sale_number',h.sale_number,'status',h.status,
    'posted_qty_pcs',v_qty,'post_stock_delta_pcs',0,'row_version',h.row_version
  );
  return erp._idempotency_complete('post_sale_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."post_sale_v2"(p_sale_id uuid, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_sales_payment(p_payment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare p erp.sales_payments%rowtype;h erp.sales_headers%rowtype;v_cash uuid;v_paid numeric(20,2);v_total numeric(20,2);
begin
  perform erp.require_internal();
  select * into p from erp.sales_payments where id=p_payment_id for update;
  if p.id is null or p.status<>'DRAFT' then raise exception 'Sales payment must be DRAFT'; end if;
  select * into h from erp.sales_headers where id=p.sale_id for update;
  if h.status not in('POSTED','PARTIAL_PAID') then raise exception 'Sale must be posted and still unpaid before payment'; end if;
  select erp.sale_net_total(h.id)::numeric(20,2) into v_total;
  select coalesce(sum(sp.amount),0)::numeric(20,2) into v_paid from erp.sales_payments sp where sp.sale_id=h.id and sp.status='POSTED';
  if v_paid>=v_total-0.01 then raise exception 'Sale has no remaining receivable after returns/credits. Net sale %, already paid %',v_total,v_paid; end if;
  if v_paid+p.amount>v_total+0.01 then raise exception 'Customer payment exceeds remaining receivable after returns. Net sale %, already paid %, requested %',v_total,v_paid,p.amount; end if;
  select coa_account_id into v_cash from erp.cash_accounts where id=p.cash_account_id and is_active=true;
  if v_cash is null then raise exception 'Active cash/bank account is required'; end if;
  perform erp.post_journal('SALES_PAYMENT',p_payment_id,p.payment_date::date,'Customer payment',jsonb_build_array(
    jsonb_build_object('account_id',v_cash,'debit',p.amount,'credit',0,'customer_id',h.customer_id),
    jsonb_build_object('mapping_key','AR_CUSTOMER','debit',0,'credit',p.amount,'customer_id',h.customer_id)));
  update erp.sales_payments set status='POSTED' where id=p_payment_id;
  v_paid:=v_paid+p.amount;
  update erp.sales_headers set status=case when v_paid>=v_total-0.01 then 'PAID' else 'PARTIAL_PAID' end where id=h.id;
end;$function$;

alter function "erp"."post_sales_payment"(p_payment_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_sales_return(p_return_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.sales_returns%rowtype;
  s erp.sales_headers%rowtype;
  r record;
  v_refund numeric(24,6):=0;
  v_hpp numeric(24,6):=0;
  v_sold_qty integer;
  v_prior_returned integer;
  v_current_return integer;
  v_product_sale_value numeric(24,6);
  v_prior_product_refund numeric(24,6);
  v_current_product_refund numeric(24,6);
  v_original_hpp numeric(18,6);
  v_unit_hpp numeric(18,6);
  v_net_total numeric(20,2);
  v_paid numeric(20,2);
  v_lines jsonb:='[]'::jsonb;
begin
  perform erp.require_internal();
  select * into h from erp.sales_returns where id=p_return_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Sales return must be DRAFT'; end if;
  if h.sale_id is null then raise exception 'Native sales return must reference the original sale'; end if;
  select * into s from erp.sales_headers where id=h.sale_id for update;
  if s.id is null or s.status not in('POSTED','PARTIAL_PAID','PAID') then raise exception 'Original sale must be active/posted'; end if;
  if s.customer_id is distinct from h.customer_id then raise exception 'Sales return customer does not match original sale customer'; end if;
  if not exists(select 1 from erp.sales_return_items where return_id=h.id) then raise exception 'Sales return has no lines'; end if;

  for r in
    select * from erp.sales_return_items where return_id=h.id
    order by product_id,location_id,quality_grade,lot_id,id
  loop
    if r.lot_id is null then raise exception 'Sales return line requires original FG lot'; end if;
    if not exists(select 1 from erp.fg_lots fl where fl.id=r.lot_id and fl.product_id=r.product_id) then raise exception 'Sales return lot does not belong to selected product'; end if;

    insert into erp.fg_inventory_balances(product_id,location_id,quality_grade,cached_qty_pcs)
    values(r.product_id,r.location_id,r.quality_grade,0)
    on conflict(product_id,location_id,quality_grade) do nothing;
    perform 1 from erp.fg_inventory_balances
    where product_id=r.product_id and location_id=r.location_id and quality_grade=r.quality_grade
    for update;
    perform 1 from erp.fg_lots where id=r.lot_id for update;

    select coalesce(sum(a.qty_pcs),0)::integer,
           case when coalesce(sum(a.qty_pcs),0)>0 then sum(a.qty_pcs*a.unit_hpp_snapshot)/sum(a.qty_pcs) else null end
    into v_sold_qty,v_original_hpp
    from erp.sale_stock_allocations a
    join erp.sales_items si on si.id=a.sale_item_id
    where si.sale_id=h.sale_id and si.product_id=r.product_id and a.lot_id=r.lot_id and a.location_id=r.location_id;
    if v_sold_qty<=0 or v_original_hpp is null then raise exception 'Returned product/lot/location was not allocated on the original sale'; end if;

    v_unit_hpp:=coalesce(erp.lock_current_hpp_per_pcs(r.lot_id),v_original_hpp);

    select coalesce(sum(sri.qty_pcs),0)::integer into v_prior_returned
    from erp.sales_return_items sri join erp.sales_returns sr on sr.id=sri.return_id
    where sr.sale_id=h.sale_id and sr.id<>h.id and sr.status='POSTED'
      and sri.product_id=r.product_id and sri.lot_id=r.lot_id and sri.location_id=r.location_id;
    select coalesce(sum(sri.qty_pcs),0)::integer into v_current_return
    from erp.sales_return_items sri
    where sri.return_id=h.id and sri.product_id=r.product_id and sri.lot_id=r.lot_id and sri.location_id=r.location_id;
    if v_prior_returned+v_current_return>v_sold_qty then
      raise exception 'Sales return exceeds quantity originally sold for this lot/location. Sold %, prior returned %, current return %',v_sold_qty,v_prior_returned,v_current_return;
    end if;

    select coalesce(sum(si.line_total),0) into v_product_sale_value from erp.sales_items si where si.sale_id=h.sale_id and si.product_id=r.product_id;
    select coalesce(sum(sri.refund_amount),0) into v_prior_product_refund
    from erp.sales_return_items sri join erp.sales_returns sr on sr.id=sri.return_id
    where sr.sale_id=h.sale_id and sr.id<>h.id and sr.status='POSTED' and sri.product_id=r.product_id;
    select coalesce(sum(sri.refund_amount),0) into v_current_product_refund
    from erp.sales_return_items sri where sri.return_id=h.id and sri.product_id=r.product_id;
    if v_prior_product_refund+v_current_product_refund>v_product_sale_value+0.01 then
      raise exception 'Refund exceeds original net sale value for product. Sold value %, prior refund %, current refund %',v_product_sale_value,v_prior_product_refund,v_current_product_refund;
    end if;

    update erp.sales_return_items set unit_hpp_snapshot=v_unit_hpp where id=r.id;
    perform erp.post_fg_movement(r.product_id,r.lot_id,r.location_id,r.quality_grade,'SALE_RETURN',r.qty_pcs,v_unit_hpp,h.customer_id,'SALES_RETURN_ITEM',r.id,h.physical_at,'Customer sales return',false);
    v_refund:=v_refund+r.refund_amount;
    v_hpp:=v_hpp+(r.qty_pcs*v_unit_hpp);
  end loop;

  select greatest(erp.sale_net_total(h.sale_id)-v_refund,0)::numeric(20,2) into v_net_total;
  select coalesce(sum(sp.amount),0)::numeric(20,2) into v_paid from erp.sales_payments sp where sp.sale_id=h.sale_id and sp.status='POSTED';
  if v_paid>v_net_total+0.01 then
    raise exception 'Retur ini membuat pembayaran customer melebihi nilai penjualan tersisa. Nilai setelah retur %, sudah dibayar %. Reverse/koreksi pembayaran customer dulu agar kelebihan bayar tidak hilang dari pembukuan.',v_net_total,v_paid;
  end if;

  update erp.sales_returns set status='POSTED' where id=h.id;
  if abs(v_refund)>0.005 then
    v_lines:=v_lines||jsonb_build_array(
      jsonb_build_object('mapping_key','SALES_REVENUE','debit',round(v_refund,2),'credit',0,'customer_id',h.customer_id),
      jsonb_build_object('mapping_key','AR_CUSTOMER','debit',0,'credit',round(v_refund,2),'customer_id',h.customer_id));
  end if;
  if abs(v_hpp)>0.005 then
    v_lines:=v_lines||jsonb_build_array(
      jsonb_build_object('mapping_key','FG_INVENTORY','debit',round(v_hpp,2),'credit',0,'customer_id',h.customer_id),
      jsonb_build_object('mapping_key','COGS','debit',0,'credit',round(v_hpp,2),'customer_id',h.customer_id));
  end if;
  if jsonb_array_length(v_lines)>=2 then perform erp.post_journal('SALES_RETURN',h.id,h.physical_at::date,'Sales return from customer',v_lines); end if;

  update erp.sales_headers
  set status=case when v_paid>=v_net_total-0.01 then 'PAID' when v_paid>0 then 'PARTIAL_PAID' else 'POSTED' end
  where id=h.sale_id;
end;
$function$;

alter function "erp"."post_sales_return"(p_return_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_scrap_sale(p_scrap_sale_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare s erp.scrap_sales%rowtype;b erp.scrap_batches%rowtype;v_cash uuid;v_sold numeric(18,6);
begin
  perform erp.require_internal();select * into s from erp.scrap_sales where id=p_scrap_sale_id for update;
  if s.id is null or s.status<>'DRAFT' then raise exception 'Scrap sale must be DRAFT'; end if;
  if s.physical_at>clock_timestamp()+interval '5 minutes' then raise exception 'Tanggal/jam penjualan scrap berada di masa depan'; end if;
  select * into b from erp.scrap_batches where id=s.scrap_batch_id for update;if b.id is null or b.status<>'AVAILABLE' then raise exception 'Scrap batch must be AVAILABLE before sale';end if;
  select coalesce(sum(weight_kg),0) into v_sold from erp.scrap_sales where scrap_batch_id=b.id and status='POSTED';if v_sold+s.weight_kg>b.weight_kg then raise exception 'Scrap sale exceeds available weight';end if;
  if s.amount>0 then select coa_account_id into v_cash from erp.cash_accounts where id=s.cash_account_id and is_active=true;if v_cash is null then raise exception 'Active cash/bank account required for paid scrap sale';end if;perform erp.post_journal('SCRAP_SALE',s.id,s.physical_at::date,'Scrap/perca sale',jsonb_build_array(jsonb_build_object('account_id',v_cash,'debit',s.amount,'credit',0),jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',s.amount)));end if;
  update erp.scrap_sales set status='POSTED' where id=s.id;update erp.scrap_batches set status=case when v_sold+s.weight_kg>=weight_kg then 'SOLD' else 'AVAILABLE' end where id=b.id;
end$function$;

alter function "erp"."post_scrap_sale"(p_scrap_sale_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_supplier_payment(p_payment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare p erp.supplier_payments%rowtype;h erp.material_purchase_headers%rowtype;v_cash uuid;v_paid numeric(20,2);v_total numeric(20,2);
begin
  perform erp.require_internal();select * into p from erp.supplier_payments where id=p_payment_id for update;
  if p.id is null or p.status<>'DRAFT' then raise exception 'Supplier payment must be DRAFT'; end if;
  select * into h from erp.material_purchase_headers where id=p.purchase_id for update;
  if h.id is null or h.status<>'POSTED' then raise exception 'Material purchase must be POSTED before payment'; end if;
  select erp.material_purchase_payable_total(h.id)::numeric(20,2) into v_total;
  select coalesce(sum(amount),0)::numeric(20,2) into v_paid from erp.supplier_payments where purchase_id=h.id and status='POSTED';
  if v_paid+p.amount>v_total+0.01 then raise exception 'Supplier payment exceeds remaining payable. Net payable %, already paid %, requested %',v_total,v_paid,p.amount; end if;
  select coa_account_id into v_cash from erp.cash_accounts where id=p.cash_account_id and is_active=true;
  if v_cash is null then raise exception 'Active cash/bank account is required'; end if;
  perform erp.post_journal('SUPPLIER_PAYMENT',p.id,p.payment_date::date,'Material supplier payment',jsonb_build_array(
    jsonb_build_object('mapping_key','AP_SUPPLIER','debit',p.amount,'credit',0),jsonb_build_object('account_id',v_cash,'debit',0,'credit',p.amount)));
  update erp.supplier_payments set status='POSTED' where id=p.id;v_paid:=v_paid+p.amount;
  update erp.material_purchase_headers set payment_status=case when v_paid>=v_total-0.01 then 'PAID' else 'PARTIAL' end where id=h.id;
end;$function$;

alter function "erp"."post_supplier_payment"(p_payment_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_vendor_invoice(p_invoice_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.vendor_invoices%rowtype;
  r record;
  v_total numeric(20,2):=0;
  v_old numeric(20,2);
  v_po uuid;
  v_lines jsonb:='[]'::jsonb;
begin
  perform erp.require_internal();
  select * into h from erp.vendor_invoices where id=p_invoice_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Vendor invoice must be DRAFT'; end if;
  if not exists (select 1 from erp.vendor_invoice_items where invoice_id=h.id) then raise exception 'Vendor invoice has no lines'; end if;

  for r in
    select vii.*,lrl.actual_rate_snapshot as previous_rate,lrl.actual_cost_status as previous_status,lrl.actual_cost as previous_cost,
           ld.po_id,ld.vendor_id as source_vendor_id
    from erp.vendor_invoice_items vii
    join erp.laundry_receipt_lines lrl on lrl.id=vii.receipt_line_id
    join erp.laundry_delivery_lines ldl on ldl.id=lrl.delivery_line_id
    join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
    where vii.invoice_id=p_invoice_id
    order by vii.receipt_line_id,vii.id
  loop
    perform 1 from erp.laundry_receipt_lines where id=r.receipt_line_id for update;
    if r.source_vendor_id is distinct from h.vendor_id then raise exception 'Vendor invoice vendor does not match laundry delivery vendor'; end if;
    if not exists (
      select 1 from erp.laundry_receipts lr
      join erp.laundry_receipt_lines x on x.receipt_id=lr.id
      where x.id=r.receipt_line_id and lr.status='POSTED'
    ) then raise exception 'Vendor invoice can only bill POSTED laundry receipt lines'; end if;
    if exists (
      select 1 from erp.vendor_invoice_items vii2
      join erp.vendor_invoices vi2 on vi2.id=vii2.invoice_id
      where vii2.receipt_line_id=r.receipt_line_id and vi2.id<>h.id
        and vi2.status in ('POSTED','PARTIAL_PAID','PAID')
    ) then raise exception 'Laundry receipt line is already billed by another active vendor invoice'; end if;

    update erp.vendor_invoice_items
    set prior_actual_rate_snapshot=r.previous_rate,
        prior_actual_cost_status=r.previous_status,
        prior_actual_cost=r.previous_cost
    where id=r.id;

    v_old:=coalesce(r.previous_cost,0);
    v_total:=v_total+r.actual_amount;

    update erp.laundry_receipt_lines
    set actual_rate_snapshot=coalesce(r.actual_rate,actual_rate_snapshot),
        actual_cost=r.actual_amount,
        actual_cost_status='FINAL'
    where id=r.receipt_line_id;

    insert into erp.cost_adjustments(adjustment_number,po_id,component_type,source_type,source_id,economic_date,old_amount,new_amount,reason,created_by)
    values ('CADJ-'||substr(gen_random_uuid()::text,1,12),r.po_id,'LAUNDRY','VENDOR_INVOICE_ITEM',r.id,h.invoice_date,v_old,r.actual_amount,'Final laundry vendor invoice',erp.current_app_user_id());

    v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','WIP','debit',r.actual_amount,'credit',0,'vendor_id',h.vendor_id,'po_id',r.po_id));
  end loop;

  if round(v_total,2)<>round(h.total_amount,2) then raise exception 'Vendor invoice item total % does not match header total %',v_total,h.total_amount; end if;
  if h.total_amount>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','AP_VENDOR','debit',0,'credit',h.total_amount,'vendor_id',h.vendor_id));
    perform erp.post_journal('VENDOR_INVOICE',h.id,h.invoice_date,'Laundry vendor invoice '||h.invoice_number,v_lines);
  end if;

  update erp.vendor_invoices set status='POSTED',updated_at=now() where id=h.id;

  for v_po in
    select distinct ld.po_id
    from erp.vendor_invoice_items vii
    join erp.laundry_receipt_lines lrl on lrl.id=vii.receipt_line_id
    join erp.laundry_delivery_lines ldl on ldl.id=lrl.delivery_line_id
    join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
    where vii.invoice_id=p_invoice_id
  loop
    perform erp.sync_laundry_accrual(v_po,h.invoice_date);
    if exists (select 1 from erp.fg_lots where po_id=v_po) then
      perform erp.rebuild_po_hpp(v_po,'Final laundry vendor invoice posted');
      perform erp.propagate_conversion_hpp_for_po(v_po);
      perform erp.sync_po_hpp_to_gl(v_po,h.invoice_date);
    end if;
  end loop;
end;
$function$;

alter function "erp"."post_vendor_invoice"(p_invoice_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_vendor_payment(p_payment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare p erp.vendor_payments%rowtype;h erp.vendor_invoices%rowtype;v_cash uuid;v_paid numeric(20,2);
begin
  perform erp.require_internal();
  select * into p from erp.vendor_payments where id=p_payment_id for update;
  if p.id is null or p.status<>'DRAFT' then raise exception 'Vendor payment must be DRAFT'; end if;
  select * into h from erp.vendor_invoices where id=p.vendor_invoice_id for update;
  if h.status not in ('POSTED','PARTIAL_PAID') then raise exception 'Vendor invoice must be posted and still unpaid'; end if;
  select coalesce(sum(amount),0)::numeric(20,2) into v_paid from erp.vendor_payments where vendor_invoice_id=h.id and status='POSTED';
  if v_paid+p.amount>h.total_amount+0.01 then raise exception 'Vendor payment exceeds remaining payable. Invoice total %, already paid %, requested %',h.total_amount,v_paid,p.amount; end if;
  select coa_account_id into v_cash from erp.cash_accounts where id=p.cash_account_id and is_active=true;
  if v_cash is null then raise exception 'Active cash/bank account is required'; end if;
  perform erp.post_journal('VENDOR_PAYMENT',p.id,p.payment_date::date,'Laundry vendor payment',jsonb_build_array(
    jsonb_build_object('mapping_key','AP_VENDOR','debit',p.amount,'credit',0,'vendor_id',h.vendor_id),jsonb_build_object('account_id',v_cash,'debit',0,'credit',p.amount,'vendor_id',h.vendor_id)));
  update erp.vendor_payments set status='POSTED' where id=p.id;v_paid:=v_paid+p.amount;
  update erp.vendor_invoices set status=case when v_paid>=total_amount-0.01 then 'PAID' else 'PARTIAL_PAID' end where id=h.id;
end;$function$;

alter function "erp"."post_vendor_payment"(p_payment_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.post_work_completion(p_completion_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare h erp.work_completion_events%rowtype;v_total numeric(24,6);v_group_count integer;v_only_group uuid;
begin
  perform erp.require_internal();select * into h from erp.work_completion_events where id=p_completion_id for update;if h.id is null or h.status<>'DRAFT' then raise exception 'Work completion must be DRAFT';end if;if not exists(select 1 from erp.production_orders po where po.id=h.po_id and po.contractor_id=h.contractor_id) then raise exception 'Work completion contractor does not match PO contractor';end if;
  if h.cutting_group_id is not null then if not exists(select 1 from erp.cutting_groups cg where cg.id=h.cutting_group_id and cg.po_id=h.po_id) then raise exception 'Work completion cutting group does not belong to PO';end if;
  else select count(*),(array_agg(id order by id))[1] into v_group_count,v_only_group from erp.cutting_groups where po_id=h.po_id;if v_group_count=1 then update erp.work_completion_events set cutting_group_id=v_only_group where id=h.id;h.cutting_group_id:=v_only_group;elsif v_group_count>1 then raise exception 'PO has multiple cutting groups; select the grouping for this work completion so HPP stays on the correct lot';end if;end if;
  if not exists(select 1 from erp.po_work_component_snapshots where po_id=h.po_id) then raise exception 'Work BOM/rate snapshot is not committed for this PO; call ensure_po_work_component_snapshots using the work physical date before entering/posting lines';end if;
  if not exists(select 1 from erp.work_completion_lines where completion_id=h.id) then raise exception 'Work completion has no lines';end if;
  select coalesce(sum(amount_payable),0) into v_total from erp.work_completion_lines where completion_id=p_completion_id;update erp.work_completion_events set status='POSTED' where id=p_completion_id;
  if v_total>0 then perform erp.post_journal('WORK_COMPLETION',p_completion_id,h.physical_at::date,'Mandor work completion accrual',jsonb_build_array(jsonb_build_object('mapping_key','WIP','debit',round(v_total,2),'credit',0,'contractor_id',h.contractor_id,'po_id',h.po_id),jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',0,'credit',round(v_total,2),'contractor_id',h.contractor_id,'po_id',h.po_id)));end if;
end;$function$;

alter function "erp"."post_work_completion"(p_completion_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.prepare_migration_opening_balance(p_batch_id uuid, p_opening_number text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare b erp.migration_batches%rowtype;r record;j jsonb;v_header uuid;v_material uuid;v_roll uuid;v_product uuid;v_model uuid;v_contractor uuid;v_customer uuid;v_location uuid;v_supplier uuid;v_vendor uuid;v_cash uuid;v_type text;v_number text;v_hpp_method text;v_hpp_pct numeric;
begin
  perform erp.require_owner_admin();select * into b from erp.migration_batches where id=p_batch_id for update;if b.id is null then raise exception 'Migration batch not found';end if;if b.status not in('READY','POSTING') then raise exception 'Migration batch must be READY/POSTING';end if;if exists(select 1 from erp.migration_staging_rows where batch_id=p_batch_id and validation_status<>'VALID') then raise exception 'Migration batch contains unvalidated/error rows';end if;
  if exists(select 1 from erp.opening_balance_headers where migration_batch_id=p_batch_id) then select id into v_header from erp.opening_balance_headers where migration_batch_id=p_batch_id order by created_at limit 1;return v_header;end if;
  v_number:=coalesce(nullif(trim(p_opening_number),''),'MIG-'||b.batch_code);insert into erp.opening_balance_headers(opening_number,opening_date,status,notes,created_by,migration_batch_id) values(v_number,b.cutover_at::date,'DRAFT','Prepared from migration batch '||b.batch_code,erp.current_app_user_id(),b.id) returning id into v_header;
  for r in select * from erp.migration_staging_rows where batch_id=p_batch_id and entity_type='MATERIAL_ROLL' and validation_status='VALID' order by source_row_no loop
    j:=r.normalized_payload;select m.id,mr.id into v_material,v_roll from erp.materials m join erp.material_rolls mr on mr.material_id=m.id where m.material_sku=j->>'material_sku' and mr.roll_number=j->>'roll_number';select id into v_location from erp.locations where location_code=j->>'location_code' and location_type='RAW_MATERIAL_WAREHOUSE' and is_active=true;if v_material is null or v_roll is null or v_location is null then raise exception 'MATERIAL_ROLL row % was not applied/resolved safely',r.source_row_no;end if;
    insert into erp.opening_balance_items(opening_id,balance_type,material_id,roll_id,location_id,qty,unit_cost_snapshot,notes) values(v_header,'MATERIAL',v_material,v_roll,v_location,(j->>'opening_qty')::numeric,(j->>'unit_cost')::numeric,coalesce(j->>'notes','Legacy roll opening row '||r.source_row_no));
  end loop;
  for r in select * from erp.migration_staging_rows where batch_id=p_batch_id and entity_type='OPENING_BALANCE_ITEM' and validation_status='VALID' order by source_row_no loop
    j:=r.normalized_payload;v_type:=upper(j->>'balance_type');v_material:=null;v_product:=null;v_model:=null;v_contractor:=null;v_customer:=null;v_location:=null;v_supplier:=null;v_vendor:=null;v_cash:=null;v_hpp_method:=coalesce(nullif(upper(j->>'hpp_input_method'),''),'MANUAL');v_hpp_pct:=nullif(j->>'hpp_percent_of_price','')::numeric;
    if nullif(trim(coalesce(j->>'material_sku','')),'') is not null then select id into v_material from erp.materials where material_sku=j->>'material_sku';if v_material is null then raise exception 'Opening row %: unknown material_sku %',r.source_row_no,j->>'material_sku';end if;end if;
    if nullif(trim(coalesce(j->>'product_sku','')),'') is not null then
      v_product:=erp.resolve_opening_product_identity(j->>'product_sku',b.cutover_at,j->>'color_name',j->>'size_code',j->>'model_code',j->>'brand_code');
    end if;
    if nullif(trim(coalesce(j->>'model_code','')),'') is not null then select id into v_model from erp.product_models where model_code=j->>'model_code';if v_model is null then raise exception 'Opening row %: unknown model_code %',r.source_row_no,j->>'model_code';end if;end if;
    if nullif(trim(coalesce(j->>'contractor_code','')),'') is not null then select id into v_contractor from erp.contractors where contractor_code=j->>'contractor_code';if v_contractor is null then raise exception 'Opening row %: unknown contractor_code %',r.source_row_no,j->>'contractor_code';end if;end if;
    if nullif(trim(coalesce(j->>'customer_code','')),'') is not null then select id into v_customer from erp.customers where customer_code=j->>'customer_code';if v_customer is null then raise exception 'Opening row %: unknown customer_code %',r.source_row_no,j->>'customer_code';end if;end if;
    if nullif(trim(coalesce(j->>'location_code','')),'') is not null then select id into v_location from erp.locations where location_code=j->>'location_code';if v_location is null then raise exception 'Opening row %: unknown location_code %',r.source_row_no,j->>'location_code';end if;end if;
    if nullif(trim(coalesce(j->>'supplier_code','')),'') is not null then select id into v_supplier from erp.suppliers where supplier_code=j->>'supplier_code';if v_supplier is null then raise exception 'Opening row %: unknown supplier_code %',r.source_row_no,j->>'supplier_code';end if;end if;
    if nullif(trim(coalesce(j->>'vendor_code','')),'') is not null then select id into v_vendor from erp.laundry_vendors where vendor_code=j->>'vendor_code';if v_vendor is null then raise exception 'Opening row %: unknown vendor_code %',r.source_row_no,j->>'vendor_code';end if;end if;
    if nullif(trim(coalesce(j->>'cash_account_code','')),'') is not null then select id into v_cash from erp.cash_accounts where cash_account_code=j->>'cash_account_code';if v_cash is null then raise exception 'Opening row %: unknown cash_account_code %',r.source_row_no,j->>'cash_account_code';end if;end if;
    insert into erp.opening_balance_items(opening_id,balance_type,material_id,product_id,model_id,contractor_id,customer_id,location_id,supplier_id,vendor_id,cash_account_id,stage,qty,amount,unit_cost_snapshot,quality_grade,notes,hpp_input_method,hpp_percent_of_price)
    values(v_header,v_type,v_material,v_product,v_model,v_contractor,v_customer,v_location,v_supplier,v_vendor,v_cash,nullif(j->>'stage',''),nullif(j->>'qty','')::numeric,nullif(j->>'amount','')::numeric,nullif(j->>'unit_cost','')::numeric,nullif(j->>'quality_grade',''),coalesce(j->>'notes','Legacy migration row '||r.source_row_no),case when v_type='FINISHED_GOODS' then v_hpp_method else 'MANUAL' end,case when v_type='FINISHED_GOODS' and v_hpp_method='PRICE_PERCENT' then v_hpp_pct else null end);
    update erp.migration_staging_rows set posted_entity_type='OPENING_BALANCE_HEADER',posted_entity_id=v_header,posted_at=now(),updated_at=now() where id=r.id;
  end loop;return v_header;
end$function$;

alter function "erp"."prepare_migration_opening_balance"(p_batch_id uuid, p_opening_number text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.prepare_rework_component_line()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_order erp.rework_orders%rowtype;
  v_case erp.bs_cases%rowtype;
  v_component erp.bs_case_components%rowtype;
  v_model uuid;
  v_original_contractor uuid;
  v_rate_id uuid;
  v_rate numeric(18,2);
  v_po_snapshot uuid;
  v_remaining integer;
begin
  select * into v_order from erp.rework_orders where id=new.rework_order_id for update;
  if v_order.id is null then raise exception 'Rework order not found'; end if;
  if v_order.status not in('OPEN','IN_PROGRESS','PARTIAL') or v_order.cost_posted then
    raise exception 'Rework component lines are editable only before completion/cost posting';
  end if;
  select * into v_component from erp.bs_case_components where id=new.bs_case_component_id for update;
  if v_component.id is null then raise exception 'BS component not found'; end if;
  if v_component.bs_case_id<>v_order.bs_case_id then
    raise exception 'Rework component belongs to a different BS case';
  end if;
  select * into v_case from erp.bs_cases where id=v_order.bs_case_id;
  if new.qty_performed>v_order.qty_sent then
    raise exception 'Rework component qty performed % exceeds rework qty sent %',new.qty_performed,v_order.qty_sent;
  end if;
  v_remaining:=greatest(
    v_case.qty_pcs-v_component.completed_before_bs_qty-v_component.lifetime_newly_completed_qty,0
  );
  new.qty_newly_payable:=least(new.qty_performed,v_remaining);
  new.source_contractor_rate_id:=null;
  new.source_po_component_snapshot_id:=null;

  if v_order.destination_type='LAUNDRY' then
    new.rate_snapshot:=0;
    new.rate_basis:='LAUNDRY_ZERO';
    return new;
  end if;

  select coalesce(po.model_id,p.model_id),coalesce(po.contractor_id,v_case.responsible_contractor_id)
  into v_model,v_original_contractor
  from erp.bs_cases bc
  left join erp.production_orders po on po.id=bc.po_id
  left join erp.products p on p.id=bc.product_id
  where bc.id=v_case.id;
  if v_model is null then
    raise exception 'Contractor rework requires PO or product model lineage for server-side rate resolution';
  end if;

  select r.id,r.rate_per_pcs into v_rate_id,v_rate
  from erp.contractor_work_rates r
  where r.contractor_id=v_order.contractor_id
    and r.model_id=v_model
    and r.work_component_id=v_component.work_component_id
    and r.effective_from<=v_order.physical_sent_at
    and (r.effective_to is null or r.effective_to>v_order.physical_sent_at)
  order by r.effective_from desc,r.id desc limit 1;

  if v_rate_id is not null then
    new.rate_snapshot:=v_rate;
    new.source_contractor_rate_id:=v_rate_id;
    new.rate_basis:='CONTRACTOR_RATE';
    return new;
  end if;

  if v_order.contractor_id is distinct from v_original_contractor then
    raise exception 'Cross-Mandor rework requires an explicit effective contractor rate for this model/component';
  end if;
  select s.id,s.rate_per_pcs_snapshot into v_po_snapshot,v_rate
  from erp.po_work_component_snapshots s
  where s.po_id=v_case.po_id and s.work_component_id=v_component.work_component_id
  order by s.committed_at desc,s.id desc limit 1;
  if v_po_snapshot is null then
    raise exception 'No effective contractor rate or PO component snapshot exists for rework pricing';
  end if;
  new.rate_snapshot:=v_rate;
  new.source_po_component_snapshot_id:=v_po_snapshot;
  new.rate_basis:='PO_SNAPSHOT';
  return new;
end;
$function$;

alter function "erp"."prepare_rework_component_line"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.preview_attendance_hpp_pool_v1(p_period_start date, p_period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_manifest jsonb;
  v_missing_policy_count bigint;
  v_bad_attendance_snapshot_count bigint;
  v_bad_journal_count bigint;
  v_numerator_cents bigint;
  v_denominator_qty bigint;
begin
  perform erp.require_internal();
  if p_period_start is null or p_period_end is null or p_period_end < p_period_start then
    raise exception 'Valid period_start and period_end are required';
  end if;

  select count(*) into v_missing_policy_count
  from erp.payroll_settlements ps
  join erp.contractors c on c.id = ps.contractor_id
  where ps.status in ('APPROVED','PAID')
    and ps.period_start = p_period_start
    and ps.period_end = p_period_end
    and ps.attendance_total > 0
    and c.contractor_type = 'MANDOR'
    and not exists (
      select 1
      from erp.contractor_hpp_policy_versions p
      where p.contractor_id = ps.contractor_id
        and p.effective_from <= p_period_start
        and (p.effective_to is null or p.effective_to >= p_period_end)
    );
  if v_missing_policy_count > 0 then
    raise exception '% approved/paid attendance payroll(s) lack one explicit HPP policy covering the full period', v_missing_policy_count;
  end if;

  select count(*) into v_bad_attendance_snapshot_count
  from erp.payroll_settlements ps
  where ps.status in ('APPROVED','PAID')
    and ps.period_start = p_period_start
    and ps.period_end = p_period_end
    and abs(ps.attendance_total - coalesce((
      select sum(pai.amount) from erp.payroll_attendance_items pai where pai.payroll_id = ps.id
    ), 0)) > 0.01;
  if v_bad_attendance_snapshot_count > 0 then
    raise exception '% payroll attendance total(s) do not reconcile to immutable attendance items', v_bad_attendance_snapshot_count;
  end if;

  select count(*) into v_bad_journal_count
  from erp.payroll_settlements ps
  join lateral (
    select count(*) as line_count, max(jl.debit) as debit_amount
    from erp.journal_entries je
    join erp.journal_lines jl on jl.journal_entry_id = je.id
    where je.source_id = ps.id
      and je.source_type = 'PAYROLL_ATTENDANCE_ACCRUAL'
      and je.status = 'POSTED'
      and jl.account_id = erp.account_id('WIP')
      and jl.debit > 0
  ) x on true
  where ps.status in ('APPROVED','PAID')
    and ps.period_start = p_period_start
    and ps.period_end = p_period_end
    and ps.attendance_total > 0
    and (x.line_count <> 1 or x.debit_amount + 0.01 < ps.attendance_total);
  if v_bad_journal_count > 0 then
    raise exception '% approved/paid attendance payroll(s) lack one unambiguous WIP debit line from PAYROLL_ATTENDANCE_ACCRUAL covering attendance amount', v_bad_journal_count;
  end if;

  v_manifest := erp._build_attendance_hpp_manifest_v1(p_period_start, p_period_end);
  perform erp._assert_attendance_hpp_manifest_v1(v_manifest);
  v_numerator_cents := (v_manifest->>'numerator_cents')::bigint;
  v_denominator_qty := (v_manifest->>'denominator_qty')::bigint;

  if v_numerator_cents <= 0 then
    raise exception 'No eligible normal-Mandor attendance payroll cost exists for this exact period';
  end if;
  if v_denominator_qty <= 0 then
    raise exception 'POSITIVE_POOL_ZERO_SEWING_OUTPUT: attendance cost exists but immutable SELESAI_DIJAHIT denominator is zero; keep cost unassigned/WIP and do not use QC GOOD fallback';
  end if;

  return jsonb_build_object(
    'status', 'READY',
    'manifest', v_manifest,
    'manifest_sha256', erp._cp3_manifest_sha256(v_manifest),
    'numerator_amount', v_numerator_cents / 100.0,
    'denominator_qty', v_denominator_qty,
    'unit_cost_per_sewn_pcs', (v_numerator_cents / 100.0) / v_denominator_qty
  );
end;
$function$;

alter function "erp"."preview_attendance_hpp_pool_v1"(p_period_start date, p_period_end date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.preview_bulk_rate_change(p_rate_type text, p_target_ids uuid[], p_mode text, p_value numeric)
 RETURNS TABLE(target_id uuid, old_value numeric, new_value numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare r record; v_new numeric; v_type text:=upper(trim(p_rate_type)); v_mode text:=upper(trim(p_mode));
begin
  perform erp.require_owner_admin();
  if v_mode not in('SET','DELTA','PERCENT') then raise exception 'Mode perubahan harus SET, DELTA, atau PERCENT'; end if;
  if p_target_ids is null or coalesce(array_length(p_target_ids,1),0)=0 then raise exception 'Pilih minimal satu harga/rate'; end if;
  for r in
    select x.id,
      case v_type
        when 'PRODUCT_PRICE' then (select price from erp.product_price_versions where id=x.id)
        when 'WORK_RATE' then (select rate_per_pcs from erp.contractor_work_rates where id=x.id)
        when 'CONTRACTOR_ACCESSORY_PRICE' then (select selling_price from erp.contractor_accessory_price_versions where id=x.id)
        when 'CONTRACTOR_MATERIAL_PRICE' then (select selling_price from erp.contractor_material_price_versions where id=x.id)
        when 'LAUNDRY_RATE' then (select rate_per_pcs from erp.laundry_vendor_rate_versions where id=x.id)
      end old_value
    from (select distinct unnest(p_target_ids) id) x
  loop
    if r.old_value is null then raise exception 'Target harga/rate % tidak ditemukan untuk tipe %',r.id,v_type; end if;
    v_new:=case v_mode when 'SET' then p_value when 'DELTA' then r.old_value+p_value else r.old_value*(1+p_value/100) end;
    if v_new<0 then raise exception 'Hasil harga/rate tidak boleh negatif. Target %, hasil %',r.id,v_new; end if;
    target_id:=r.id;old_value:=r.old_value;new_value:=round(v_new,6);return next;
  end loop;
end$function$;

alter function "erp"."preview_bulk_rate_change"(p_rate_type text, p_target_ids uuid[], p_mode text, p_value numeric) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.process_cost_recalc_queue(p_limit integer DEFAULT 20)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  r record;
  v_count integer:=0;
  v_attempt integer;
  v_po_status text;
begin
  perform erp.require_internal();
  for r in
    select * from erp.cost_recalc_queue
    where status='PENDING' or (status='FAILED' and attempt_count<3 and coalesce(next_attempt_at,now())<=now())
    order by queued_at,id limit greatest(p_limit,1) for update skip locked
  loop
    v_attempt:=r.attempt_count+1;
    begin
      update erp.cost_recalc_queue set status='RUNNING',started_at=now(),last_attempt_at=now(),attempt_count=v_attempt where id=r.id;
      if r.entity_type='PO' then
        perform erp.rebuild_po_hpp(r.entity_id,r.reason);
        perform erp.propagate_conversion_hpp_for_po(r.entity_id);
        perform erp.sync_po_hpp_to_gl(r.entity_id,current_date);
        select status into v_po_status from erp.production_orders where id=r.entity_id;
        if v_po_status='FINISHED' then perform erp.sync_finished_po_wip_residual(r.entity_id,current_date,'Post-close HPP/material recost residual adjustment'); end if;
      else
        raise exception 'Unsupported cost recalc entity_type %',r.entity_type;
      end if;
      update erp.cost_recalc_queue set status='DONE',completed_at=now(),error_message=null,next_attempt_at=null,last_attempt_at=now(),attempt_count=v_attempt where id=r.id;
      v_count:=v_count+1;
    exception when others then
      update erp.cost_recalc_queue set status='FAILED',completed_at=now(),error_message=sqlerrm,last_attempt_at=now(),attempt_count=v_attempt,
        next_attempt_at=case when v_attempt<3 then now()+(interval '5 minutes'*v_attempt) else null end where id=r.id;
    end;
  end loop;
  return v_count;
end;
$function$;

alter function "erp"."process_cost_recalc_queue"(p_limit integer) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.product_opening_physical_at(p_product_id uuid, p_opening_date date)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.products%rowtype;
  v_day_start timestamptz;
  v_day_end timestamptz;
  v_at timestamptz;
begin
  perform erp.require_internal();
  if p_opening_date is null then raise exception 'Tanggal opening wajib diisi'; end if;
  select * into p from erp.products where id=p_product_id;
  if p.id is null then raise exception 'SKU opening tidak ditemukan'; end if;
  v_day_start:=p_opening_date::timestamp at time zone 'Asia/Jakarta';
  v_day_end:=(p_opening_date+1)::timestamp at time zone 'Asia/Jakarta';

  -- Legacy physical stock may remain after identity expiry, so effective_to does
  -- not invalidate the old SKU for opening. But a version cannot be placed before
  -- the first instant it ever became effective on the opening day.
  v_at:=greatest(v_day_start,p.effective_from);
  if v_at>=v_day_end then
    raise exception 'Versi SKU % belum pernah berlaku pada tanggal opening %. Pilih SKU yang sudah berlaku sebelum/di tanggal opening tersebut.',p.sku,p_opening_date;
  end if;
  return v_at;
end$function$;

alter function "erp"."product_opening_physical_at"(p_product_id uuid, p_opening_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.propagate_conversion_hpp_for_po(p_po_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE r record;v_source_hpp numeric(18,6);v_desired numeric(18,6);v_current numeric(18,6);v_old_id uuid;v_new_id uuid;v_ver integer; BEGIN PERFORM erp.require_internal(); FOR r IN SELECT pca.* FROM erp.product_conversion_allocations pca JOIN erp.fg_lots src ON src.id=pca.source_lot_id JOIN erp.product_conversions pc ON pc.id=pca.conversion_id WHERE src.po_id=p_po_id AND pc.status='POSTED' AND pca.destination_lot_id IS NOT NULL LOOP SELECT hpp_per_pcs INTO v_source_hpp FROM erp.v_current_hpp WHERE lot_id=r.source_lot_id; IF v_source_hpp IS NULL OR r.qty_pcs<=0 THEN CONTINUE; END IF;v_desired:=v_source_hpp+(r.conversion_cost_allocated/r.qty_pcs); SELECT hpp_version_id,hpp_per_pcs INTO v_old_id,v_current FROM erp.v_current_hpp WHERE lot_id=r.destination_lot_id; IF v_old_id IS NULL OR ABS(COALESCE(v_current,0)-v_desired)>0.000001 THEN SELECT COALESCE(MAX(version_no),0)+1 INTO v_ver FROM erp.hpp_versions WHERE lot_id=r.destination_lot_id; UPDATE erp.hpp_versions SET is_current=false WHERE lot_id=r.destination_lot_id AND is_current=true; INSERT INTO erp.hpp_versions(lot_id,version_no,cost_state,qty_basis_pcs,total_cost,is_current,supersedes_id,calculation_reason,created_by) VALUES (r.destination_lot_id,v_ver,'ADJUSTED',r.qty_pcs,r.qty_pcs*v_desired,true,v_old_id,'Propagated source HPP correction through SKU conversion',erp.current_app_user_id()) RETURNING id INTO v_new_id; INSERT INTO erp.hpp_version_components(hpp_version_id,component_type,description,qty_basis,unit_cost,total_cost,source_type,source_id) VALUES (v_new_id,'OTHER','Latest source lot HPP carry-forward',r.qty_pcs,v_source_hpp,r.qty_pcs*v_source_hpp,'FG_LOT',r.source_lot_id),(v_new_id,'CONVERSION','Conversion/relabel cost',r.qty_pcs,r.conversion_cost_allocated/r.qty_pcs,r.conversion_cost_allocated,'PRODUCT_CONVERSION_ALLOCATION',r.id); END IF; END LOOP; END; $function$;

alter function "erp"."propagate_conversion_hpp_for_po"(p_po_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.protect_material_original_cost_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.original_unit_cost_snapshot IS NULL THEN
      IF NEW.input_unit_cost IS NOT NULL THEN
        NEW.original_unit_cost_snapshot:=NEW.input_unit_cost;
      ELSIF COALESCE(NEW.unit_cost_snapshot,0)<>0 THEN
        NEW.original_unit_cost_snapshot:=NEW.unit_cost_snapshot;
      END IF;
    END IF;
  ELSE
    IF OLD.original_unit_cost_snapshot IS NOT NULL
       AND NEW.original_unit_cost_snapshot IS DISTINCT FROM OLD.original_unit_cost_snapshot THEN
      RAISE EXCEPTION 'Original material cost snapshot is immutable';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

alter function "erp"."protect_material_original_cost_snapshot"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.protect_rework_component_line()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if tg_op='UPDATE' and (
    new.rework_order_id is distinct from old.rework_order_id
    or new.bs_case_component_id is distinct from old.bs_case_component_id
    or new.qty_performed is distinct from old.qty_performed
    or new.qty_newly_payable is distinct from old.qty_newly_payable
    or new.rate_snapshot is distinct from old.rate_snapshot
    or new.source_contractor_rate_id is distinct from old.source_contractor_rate_id
    or new.source_po_component_snapshot_id is distinct from old.source_po_component_snapshot_id
    or new.rate_basis is distinct from old.rate_basis
  ) then raise exception 'Rework entitlement/rate provenance is immutable; cancel and create a corrected line'; end if;
  return new;
end;
$function$;

alter function "erp"."protect_rework_component_line"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.rebuild_bs_component_counters(p_bs_case_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  b erp.bs_cases%rowtype;
  c record;
  v_newly integer;
  v_paid_rework integer;
  v_prod_total integer;
  v_prod_paid integer;
  v_base_paid integer;
begin
  perform erp.require_internal();
  select * into b from erp.bs_cases where id=p_bs_case_id for update;
  if b.id is null then return; end if;

  for c in select * from erp.bs_case_components where bs_case_id=b.id for update
  loop
    select coalesce(sum(rcl.qty_newly_payable),0)::integer into v_newly
    from erp.rework_component_lines rcl
    join erp.rework_orders ro on ro.id=rcl.rework_order_id
    where rcl.bs_case_component_id=c.id and ro.status<>'CANCELLED';

    select coalesce(sum(pwi.qty_payable),0)::integer into v_paid_rework
    from erp.payroll_work_items pwi
    join erp.payroll_settlements ps on ps.id=pwi.payroll_id
    join erp.rework_component_lines rcl on rcl.id=pwi.source_id
    where pwi.source_type='REWORK' and rcl.bs_case_component_id=c.id and ps.status='PAID';

    select coalesce(sum(wcl.qty_payable),0)::integer into v_prod_total
    from erp.work_completion_lines wcl
    join erp.work_completion_events wce on wce.id=wcl.completion_id
    where wce.po_id=b.po_id and wcl.work_component_id=c.work_component_id and wce.status='POSTED';

    select coalesce(sum(pwi.qty_payable),0)::integer into v_prod_paid
    from erp.payroll_work_items pwi
    join erp.payroll_settlements ps on ps.id=pwi.payroll_id
    where pwi.source_type='PRODUCTION' and pwi.po_id=b.po_id and pwi.work_component_id=c.work_component_id and ps.status='PAID';

    v_base_paid:=case when v_prod_total>0 and v_prod_paid>=v_prod_total then c.completed_before_bs_qty else 0 end;
    update erp.bs_case_components
    set lifetime_newly_completed_qty=greatest(v_newly,0),
        lifetime_paid_qty=least(b.qty_pcs,greatest(v_base_paid,0)+greatest(v_paid_rework,0))
    where id=c.id;
  end loop;
end;
$function$;

alter function "erp"."rebuild_bs_component_counters"(p_bs_case_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.rebuild_po_hpp(p_po_id uuid, p_reason text DEFAULT 'Recalculate HPP'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_material numeric(24,6):=0;
  v_material_allocated numeric(24,6):=0;
  v_contractor_material numeric(24,6):=0;
  v_accessory numeric(24,6):=0;
  v_labor numeric(24,6):=0;
  v_commission numeric(24,6):=0;
  v_laundry numeric(24,6):=0;
  v_rework numeric(24,6):=0;
  v_other numeric(24,6):=0;
  v_attendance_hpp numeric(24,6):=0;
  v_shared_attendance_hpp numeric(24,6):=0;
  v_shared_labor numeric(24,6):=0;
  v_shared_commission numeric(24,6):=0;
  v_shared_rework numeric(24,6):=0;
  v_shared_other numeric(24,6):=0;
  v_total_current numeric(24,6):=0;
  v_total_qty integer:=0;
  v_pending boolean:=false;
  r record;
  c record;
  v_old_id uuid;
  v_new_id uuid;
  v_version integer;
  v_lot_accessory numeric(24,6);
  v_lot_cost numeric(24,6);
  v_lot_material numeric(24,6);
  v_pool_material numeric(24,6);
  v_pool_qty numeric(24,6);
  v_batch_id uuid;
  v_state varchar(20);
  v_group_fg_qty numeric(24,6);
  v_group_labor numeric(24,6);
  v_group_commission numeric(24,6);
  v_group_laundry numeric(24,6);
  v_group_rework numeric(24,6);
  v_group_attendance_hpp numeric(24,6);
  v_lot_attendance_hpp numeric(24,6);
  v_lot_labor numeric(24,6);
  v_lot_commission numeric(24,6);
  v_lot_laundry numeric(24,6);
  v_lot_rework numeric(24,6);
  v_lot_other numeric(24,6);
begin
  perform erp.require_internal();
  -- Serialize all HPP rebuilds for the same PO (cron recost, late invoice, QC, reversal).
  perform pg_advisory_xact_lock(hashtextextended('PO_HPP:'||p_po_id::text,0));

  select coalesce(sum(-msm.qty_signed*msm.unit_cost_snapshot),0) into v_material
  from erp.material_stock_movements msm
  where (msm.source_type='CUTTING_GROUP' and msm.source_id in (select id from erp.cutting_groups where po_id=p_po_id))
     or (msm.source_type='CUTTING_GROUP_RETURN' and msm.source_id in (select id from erp.cutting_groups where po_id=p_po_id));

  select coalesce(sum(cmii.qty*cmii.unit_cost_snapshot),0) into v_contractor_material
  from erp.contractor_material_issue_items cmii
  join erp.contractor_material_issues cmi on cmi.id=cmii.issue_id
  join erp.materials m on m.id=cmii.material_id
  where cmi.po_id=p_po_id and cmi.status='POSTED' and m.material_type<>'ACCESSORY';

  select
    coalesce(sum(case when wc.component_category='COMMISSION' then wcl.amount_payable else 0 end),0),
    coalesce(sum(case when wc.component_category<>'COMMISSION' then wcl.amount_payable else 0 end),0),
    coalesce(sum(case when wce.cutting_group_id is null and wc.component_category='COMMISSION' then wcl.amount_payable else 0 end),0),
    coalesce(sum(case when wce.cutting_group_id is null and wc.component_category<>'COMMISSION' then wcl.amount_payable else 0 end),0)
  into v_commission,v_labor,v_shared_commission,v_shared_labor
  from erp.work_completion_lines wcl
  join erp.work_completion_events wce on wce.id=wcl.completion_id
  join erp.work_components wc on wc.id=wcl.work_component_id
  where wce.po_id=p_po_id and wce.status='POSTED';

  with dl as (
    select ldl.id,ldl.cutting_group_id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot,
           coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then lrl.qty_good_received+lrl.qty_bs_laundry else 0 end),0) as qty_costed_actual,
           coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then coalesce(lrl.actual_cost,0) else 0 end),0) as actual_cost,
           bool_or(lr.status='POSTED' and lrl.actual_cost_status='PENDING') as has_pending_receipt
    from erp.laundry_delivery_lines ldl
    join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
    left join erp.laundry_receipt_lines lrl on lrl.delivery_line_id=ldl.id
    left join erp.laundry_receipts lr on lr.id=lrl.receipt_id
    where ld.po_id=p_po_id and ld.status<>'REVERSED'
    group by ldl.id,ldl.cutting_group_id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot
  )
  select coalesce(sum(actual_cost+greatest(qty_sent_pcs-qty_costed_actual,0)*coalesce(estimated_rate_snapshot,0)),0),
         coalesce(bool_or(has_pending_receipt or (qty_sent_pcs>qty_costed_actual and estimated_rate_snapshot is null)),false)
  into v_laundry,v_pending from dl;

  select coalesce(sum(rcl.amount_payable),0),
         coalesce(sum(case when bc.cutting_group_id is null then rcl.amount_payable else 0 end),0)
  into v_rework,v_shared_rework
  from erp.rework_component_lines rcl
  join erp.rework_orders ro on ro.id=rcl.rework_order_id
  join erp.bs_cases bc on bc.id=ro.bs_case_id
  where bc.po_id=p_po_id and ro.status<>'CANCELLED' and coalesce(ro.cost_posted,false)=true;

  select coalesce(sum(adjustment_amount),0),coalesce(sum(case when lot_id is null then adjustment_amount else 0 end),0)
  into v_other,v_shared_other
  from erp.cost_adjustments
  where po_id=p_po_id and component_type='OTHER';

  select
    coalesce(sum(a.allocated_amount),0),
    coalesce(sum(case when a.cutting_group_id is null then a.allocated_amount else 0 end),0)
  into v_attendance_hpp,v_shared_attendance_hpp
  from erp.attendance_hpp_pool_allocations a
  join erp.attendance_hpp_pools hp on hp.id=a.pool_id and hp.status='ACTIVE'
  where a.po_id=p_po_id;

  select coalesce(sum(initial_qty_pcs),0) into v_total_qty
  from erp.fg_lots where po_id=p_po_id and lot_origin='PRODUCTION';
  if v_total_qty<=0 then return; end if;

  for r in select id from erp.fg_lots where po_id=p_po_id and lot_origin='PRODUCTION' order by produced_at,id
  loop perform erp.ensure_fg_accessory_cost_snapshot(r.id); end loop;

  select coalesce(sum(facs.total_hpp_cost),0) into v_accessory
  from erp.fg_accessory_cost_snapshots facs join erp.fg_lots fl on fl.id=facs.lot_id
  where fl.po_id=p_po_id and fl.lot_origin='PRODUCTION';

  v_state:=case when v_pending then 'ESTIMATED' when exists (select 1 from erp.cost_adjustments where po_id=p_po_id) then 'ADJUSTED' else 'ACTUAL' end;

  for r in
    select fl.*,coalesce(fl.cutting_group_id,qi.cutting_group_id) as lineage_group_id
    from erp.fg_lots fl left join erp.qc_inspection_items qi on qi.id=fl.qc_item_id
    where fl.po_id=p_po_id and fl.lot_origin='PRODUCTION'
    order by fl.produced_at,fl.id
  loop
    v_lot_material:=0;v_pool_material:=0;v_pool_qty:=0;v_batch_id:=null;
    v_group_fg_qty:=0;v_group_labor:=0;v_group_commission:=0;v_group_laundry:=0;v_group_rework:=0;v_group_attendance_hpp:=0;

    if r.lineage_group_id is not null then
      select cutting_batch_id into v_batch_id from erp.cutting_groups where id=r.lineage_group_id;
      if v_batch_id is not null then
        select coalesce(sum(-msm.qty_signed*msm.unit_cost_snapshot),0) into v_pool_material
        from erp.material_stock_movements msm
        where (msm.source_type='CUTTING_GROUP' and msm.source_id in (select id from erp.cutting_groups where cutting_batch_id=v_batch_id))
           or (msm.source_type='CUTTING_GROUP_RETURN' and msm.source_id in (select id from erp.cutting_groups where cutting_batch_id=v_batch_id));
        select effective_pcs::numeric into v_pool_qty from erp.v_cutting_batch_totals where cutting_batch_id=v_batch_id;
      else
        select coalesce(sum(-msm.qty_signed*msm.unit_cost_snapshot),0) into v_pool_material
        from erp.material_stock_movements msm
        where msm.source_id=r.lineage_group_id and msm.source_type in ('CUTTING_GROUP','CUTTING_GROUP_RETURN');
        select total_pcs::numeric into v_pool_qty from erp.v_cutting_group_totals where cutting_group_id=r.lineage_group_id;
      end if;

      select coalesce(sum(fl2.initial_qty_pcs),0)::numeric into v_group_fg_qty
      from erp.fg_lots fl2 where fl2.po_id=p_po_id and fl2.lot_origin='PRODUCTION' and fl2.cutting_group_id=r.lineage_group_id;

      select
        coalesce(sum(case when wc.component_category<>'COMMISSION' then wcl.amount_payable else 0 end),0),
        coalesce(sum(case when wc.component_category='COMMISSION' then wcl.amount_payable else 0 end),0)
      into v_group_labor,v_group_commission
      from erp.work_completion_lines wcl
      join erp.work_completion_events wce on wce.id=wcl.completion_id
      join erp.work_components wc on wc.id=wcl.work_component_id
      where wce.po_id=p_po_id and wce.status='POSTED' and wce.cutting_group_id=r.lineage_group_id;

      with dl as (
        select ldl.id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot,
               coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then lrl.qty_good_received+lrl.qty_bs_laundry else 0 end),0) as qty_costed_actual,
               coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then coalesce(lrl.actual_cost,0) else 0 end),0) as actual_cost
        from erp.laundry_delivery_lines ldl
        join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
        left join erp.laundry_receipt_lines lrl on lrl.delivery_line_id=ldl.id
        left join erp.laundry_receipts lr on lr.id=lrl.receipt_id
        where ld.po_id=p_po_id and ld.status<>'REVERSED' and ldl.cutting_group_id=r.lineage_group_id
        group by ldl.id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot
      )
      select coalesce(sum(actual_cost+greatest(qty_sent_pcs-qty_costed_actual,0)*coalesce(estimated_rate_snapshot,0)),0)
      into v_group_laundry from dl;

      select coalesce(sum(rcl.amount_payable),0) into v_group_rework
      from erp.rework_component_lines rcl
      join erp.rework_orders ro on ro.id=rcl.rework_order_id
      join erp.bs_cases bc on bc.id=ro.bs_case_id
      where bc.po_id=p_po_id and bc.cutting_group_id=r.lineage_group_id and ro.status<>'CANCELLED' and coalesce(ro.cost_posted,false)=true;

      select coalesce(sum(a.allocated_amount),0) into v_group_attendance_hpp
      from erp.attendance_hpp_pool_allocations a
      join erp.attendance_hpp_pools hp on hp.id=a.pool_id and hp.status='ACTIVE'
      where a.po_id=p_po_id and a.cutting_group_id=r.lineage_group_id;
    end if;

    if coalesce(v_pool_qty,0)>0 then v_lot_material:=v_pool_material*(r.initial_qty_pcs::numeric/v_pool_qty);
    else v_lot_material:=v_material*(r.initial_qty_pcs::numeric/v_total_qty::numeric); end if;
    v_lot_material:=v_lot_material+v_contractor_material*(r.initial_qty_pcs::numeric/v_total_qty::numeric);
    v_material_allocated:=v_material_allocated+v_lot_material;

    if coalesce(v_group_fg_qty,0)>0 then
      v_lot_labor:=v_group_labor*(r.initial_qty_pcs::numeric/v_group_fg_qty)+v_shared_labor*(r.initial_qty_pcs::numeric/v_total_qty);
      v_lot_commission:=v_group_commission*(r.initial_qty_pcs::numeric/v_group_fg_qty)+v_shared_commission*(r.initial_qty_pcs::numeric/v_total_qty);
      v_lot_laundry:=v_group_laundry*(r.initial_qty_pcs::numeric/v_group_fg_qty);
      v_lot_rework:=v_group_rework*(r.initial_qty_pcs::numeric/v_group_fg_qty)+v_shared_rework*(r.initial_qty_pcs::numeric/v_total_qty);
      v_lot_attendance_hpp:=v_group_attendance_hpp*(r.initial_qty_pcs::numeric/v_group_fg_qty)+v_shared_attendance_hpp*(r.initial_qty_pcs::numeric/v_total_qty);
    else
      v_lot_labor:=v_labor*(r.initial_qty_pcs::numeric/v_total_qty);
      v_lot_commission:=v_commission*(r.initial_qty_pcs::numeric/v_total_qty);
      v_lot_laundry:=v_laundry*(r.initial_qty_pcs::numeric/v_total_qty);
      v_lot_rework:=v_rework*(r.initial_qty_pcs::numeric/v_total_qty);
      v_lot_attendance_hpp:=v_shared_attendance_hpp*(r.initial_qty_pcs::numeric/v_total_qty);
    end if;

    select coalesce(sum(total_hpp_cost),0) into v_lot_accessory from erp.fg_accessory_cost_snapshots where lot_id=r.id;
    select coalesce(sum(adjustment_amount),0) into v_lot_other from erp.cost_adjustments where lot_id=r.id and component_type='OTHER';
    v_lot_other:=v_lot_other+v_shared_other*(r.initial_qty_pcs::numeric/v_total_qty);
    v_lot_cost:=v_lot_material+v_lot_labor+v_lot_commission+v_lot_laundry+v_lot_rework+v_lot_attendance_hpp+v_lot_other+v_lot_accessory;
    v_total_current:=v_total_current+v_lot_cost;

    select id into v_old_id from erp.hpp_versions where lot_id=r.id and is_current=true order by version_no desc limit 1;
    select coalesce(max(version_no),0)+1 into v_version from erp.hpp_versions where lot_id=r.id;
    if v_old_id is not null then update erp.hpp_versions set is_current=false where id=v_old_id; end if;

    insert into erp.hpp_versions(lot_id,version_no,cost_state,qty_basis_pcs,total_cost,is_current,supersedes_id,calculation_reason,created_by)
    values (r.id,v_version,v_state,r.initial_qty_pcs,v_lot_cost,true,v_old_id,p_reason,erp.current_app_user_id()) returning id into v_new_id;

    insert into erp.hpp_version_components(hpp_version_id,component_type,description,total_cost,source_type,source_id)
    values
      (v_new_id,'MATERIAL',case when v_batch_id is not null then 'Cutting material by effective batch yield + PO-shared non-accessory contractor material' else 'Cutting/legacy material pool + PO-shared non-accessory contractor material' end,v_lot_material,case when v_batch_id is not null then 'CUTTING_BATCH' else 'PO' end,coalesce(v_batch_id,p_po_id)),
      (v_new_id,'LABOR','Labor allocation: same cutting group + PO-shared fallback',v_lot_labor,case when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,coalesce(r.lineage_group_id,p_po_id)),
      (v_new_id,'COMMISSION','Commission allocation: same cutting group + PO-shared fallback',v_lot_commission,case when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,coalesce(r.lineage_group_id,p_po_id)),
      (v_new_id,'LAUNDRY','Laundry allocation from same cutting group; PENDING uses estimate',v_lot_laundry,case when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,coalesce(r.lineage_group_id,p_po_id)),
      (v_new_id,'REWORK','Rework allocation from same cutting group + legacy shared fallback',v_lot_rework,case when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,coalesce(r.lineage_group_id,p_po_id)),
      (v_new_id,'LABOR','Attendance HPP: ACTIVE pool allocation by immutable sewing lineage',v_lot_attendance_hpp,'ATTENDANCE_HPP_ACTIVE_ALLOCATION',coalesce(r.lineage_group_id,p_po_id)),
      (v_new_id,'OTHER','Other/adjustment allocation',v_lot_other,'PO',p_po_id);

    for c in
      select facs.id,facs.total_hpp_cost,ac.category_name,facs.hpp_method
      from erp.fg_accessory_cost_snapshots facs join erp.accessory_categories ac on ac.id=facs.category_id
      where facs.lot_id=r.id order by ac.category_code
    loop
      insert into erp.hpp_version_components(hpp_version_id,component_type,description,total_cost,source_type,source_id)
      values (v_new_id,'ACCESSORY','Accessory category: '||c.category_name||' ['||c.hpp_method||']',c.total_hpp_cost,'FG_ACCESSORY_SNAPSHOT',c.id);
    end loop;

    update erp.fg_stock_movements set unit_hpp_snapshot=(select hpp_per_pcs from erp.hpp_versions where id=v_new_id)
    where lot_id=r.id and movement_type in ('QC_GOOD','REWORK_IN');
  end loop;

  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values ('production_orders',p_po_id,'RECALCULATE',jsonb_build_object(
    'material_total_issued',v_material+v_contractor_material,'cutting_material_total',v_material,'contractor_nonaccessory_material_total',v_contractor_material,'material_allocated_to_current_fg',v_material_allocated,'material_basis','CUTTING_BATCH_EFFECTIVE_YIELD_PLUS_PO_SHARED_CONTRACTOR_MATERIAL',
    'accessory',v_accessory,'labor',v_labor,'attendance_hpp',v_attendance_hpp,'commission',v_commission,'laundry',v_laundry,'rework',v_rework,'other',v_other,
    'total_current_fg_cost',v_total_current,'cost_state',v_state,'nonmaterial_basis','CUTTING_GROUP_LINEAGE_WITH_PO_SHARED_FALLBACK','accessory_basis','GOOD_FG_X_CATEGORY_BOM'),
    erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."rebuild_po_hpp"(p_po_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.recalculate_material_cost(p_material_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_recalc_from timestamptz;
begin
  -- Operational callers normally arrive here immediately after inserting a new
  -- material movement/reversal. Use the earliest not-yet-recalculated economic
  -- point so a valid closed-period checkpoint can bound the replay. If nothing
  -- is marked dirty, preserve the historical explicit-rebuild behaviour.
  select min(x.recalc_from)
  into v_recalc_from
  from (
    select msm.physical_at as recalc_from
    from erp.material_stock_movements msm
    where msm.material_id=p_material_id
      and msm.is_cost_recalculated=false
      and msm.reversal_of_id is null

    union all

    select src.physical_at as recalc_from
    from erp.material_stock_movements rv
    join erp.material_stock_movements src on src.id=rv.reversal_of_id
    where rv.material_id=p_material_id
      and rv.is_cost_recalculated=false
      and rv.reversal_of_id is not null
  ) x;

  if v_recalc_from is null then
    perform erp._recalculate_material_cost_core(p_material_id,null,false);
  else
    perform erp._recalculate_material_cost_core(p_material_id,v_recalc_from,true);

    -- Reversal rows are audit events excluded from active cost-history replay;
    -- mark them handled only after the full material recalc succeeds.
    update erp.material_stock_movements
    set is_cost_recalculated=true
    where material_id=p_material_id
      and is_cost_recalculated=false
      and reversal_of_id is not null;
  end if;
end;
$function$;

alter function "erp"."recalculate_material_cost"(p_material_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.recalculate_material_cost(p_material_id uuid, p_recalc_from timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  perform erp._recalculate_material_cost_core(p_material_id,p_recalc_from,true);
end;
$function$;

alter function "erp"."recalculate_material_cost"(p_material_id uuid, p_recalc_from timestamp with time zone) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.recalculate_payroll(p_payroll_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE p erp.payroll_settlements%ROWTYPE;v_attendance_required boolean; BEGIN PERFORM erp.require_internal(); SELECT * INTO p FROM erp.payroll_settlements WHERE id=p_payroll_id FOR UPDATE; IF p.id IS NULL OR p.status NOT IN ('DRAFT','CALCULATED','REVIEW') THEN RAISE EXCEPTION 'Payroll cannot be recalculated in current status'; END IF; SELECT attendance_required INTO v_attendance_required FROM erp.contractors WHERE id=p.contractor_id; UPDATE erp.payroll_settlements SET labor_total=COALESCE((SELECT SUM(amount) FROM erp.payroll_work_items WHERE payroll_id=p_payroll_id),0),attendance_total=CASE WHEN v_attendance_required THEN COALESCE((SELECT SUM(amount) FROM erp.payroll_attendance_items WHERE payroll_id=p_payroll_id),0) ELSE 0 END,reimburse_total=COALESCE((SELECT SUM(amount) FROM erp.payroll_reimbursements WHERE payroll_id=p_payroll_id),0),deduction_total=COALESCE((SELECT SUM(amount) FROM erp.payroll_deductions WHERE payroll_id=p_payroll_id),0),status='CALCULATED' WHERE id=p_payroll_id; END; $function$;

alter function "erp"."recalculate_payroll"(p_payroll_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.record_sewing_terminal_v1(p_payload jsonb, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'record_sewing_terminal_v1';
  v_hash text;
  v_cached jsonb;
  v_work_completion_id uuid;
  v_qty integer;
  v_reason text;
  v_work erp.work_completion_events%rowtype;
  v_max_line_qty integer;
  v_cutting_qty bigint;
  v_existing_terminal_qty bigint;
  v_event erp.sewing_terminal_events%rowtype;
  v_response jsonb;
begin
  perform erp.require_internal();
  perform erp._cp3_assert_closed_json_object(
    p_payload,
    array['work_completion_id','qty_pcs','reason'],
    array['work_completion_id','qty_pcs','reason'],
    'SELESAI_DIJAHIT payload'
  );

  if jsonb_typeof(p_payload->'work_completion_id') is distinct from 'string'
     or jsonb_typeof(p_payload->'qty_pcs') is distinct from 'number'
     or jsonb_typeof(p_payload->'reason') is distinct from 'string' then
    raise exception 'SELESAI_DIJAHIT payload has invalid field types';
  end if;

  v_work_completion_id := (p_payload->>'work_completion_id')::uuid;
  v_qty := (p_payload->>'qty_pcs')::integer;
  v_reason := nullif(btrim(p_payload->>'reason'), '');

  if v_qty <= 0 then raise exception 'SELESAI_DIJAHIT qty must be positive'; end if;
  if v_reason is null then raise exception 'SELESAI_DIJAHIT reason is required'; end if;

  v_hash := erp._request_hash(jsonb_build_object('payload', p_payload));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_work
  from erp.work_completion_events
  where id = v_work_completion_id
  for update;

  if v_work.id is null then raise exception 'Work completion not found'; end if;
  if v_work.status <> 'POSTED' then
    raise exception 'SELESAI_DIJAHIT can only reference a POSTED production work completion';
  end if;

  perform erp._cp3_lock_business_date(erp._cp3_business_date(v_work.physical_at));
  if exists (
    select 1 from erp.attendance_hpp_pools p
    where p.status = 'ACTIVE'
      and erp._cp3_business_date(v_work.physical_at) between p.period_start and p.period_end
  ) then
    raise exception 'ACTIVE_ATTENDANCE_HPP_PERIOD_LOCKED: cancel the active pool before recording late/backdated SELESAI_DIJAHIT';
  end if;
  if v_work.cutting_group_id is null then
    raise exception 'SELESAI_DIJAHIT requires cutting-group lineage';
  end if;
  if not exists (
    select 1 from erp.contractors c
    where c.id = v_work.contractor_id and c.contractor_type = 'MANDOR'
  ) then
    raise exception 'SELESAI_DIJAHIT source contractor must have explicit role MANDOR';
  end if;
  if exists (
    select 1 from erp.sewing_terminal_events e
    where e.source_work_completion_id = v_work.id
      and e.event_kind = 'SELESAI_DIJAHIT'
  ) then
    raise exception 'This work completion already has an authoritative SELESAI_DIJAHIT event';
  end if;

  select max(l.qty_completed)::integer into v_max_line_qty
  from erp.work_completion_lines l
  where l.completion_id = v_work.id;

  if coalesce(v_max_line_qty, 0) <= 0 or v_qty > v_max_line_qty then
    raise exception 'SELESAI_DIJAHIT qty % exceeds the maximum completed qty % recorded by the owning work completion',
      v_qty, coalesce(v_max_line_qty, 0);
  end if;

  perform 1 from erp.cutting_groups where id = v_work.cutting_group_id for update;
  select coalesce(v.total_pcs, 0)::bigint into v_cutting_qty
  from erp.v_cutting_group_totals v
  where v.cutting_group_id = v_work.cutting_group_id;

  select coalesce(sum(e.qty_signed), 0)::bigint into v_existing_terminal_qty
  from erp.sewing_terminal_events e
  where e.cutting_group_id = v_work.cutting_group_id;

  if v_existing_terminal_qty + v_qty > coalesce(v_cutting_qty, 0) then
    raise exception 'Cumulative SELESAI_DIJAHIT qty would exceed cutting-group physical qty. Current %, new %, maximum %',
      v_existing_terminal_qty, v_qty, coalesce(v_cutting_qty, 0);
  end if;

  insert into erp.sewing_terminal_events(
    event_number, event_kind, source_work_completion_id,
    contractor_id, po_id, cutting_group_id, physical_at,
    qty_signed, reason, created_by
  ) values (
    'SEW-' || to_char(v_work.physical_at at time zone 'UTC', 'YYYYMMDDHH24MISSUS') || '-' || substr(gen_random_uuid()::text, 1, 8),
    'SELESAI_DIJAHIT', v_work.id,
    v_work.contractor_id, v_work.po_id, v_work.cutting_group_id, v_work.physical_at,
    v_qty, v_reason, erp.current_app_user_id()
  ) returning * into v_event;

  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
  values (
    'sewing_terminal_events', v_event.id, 'POST',
    jsonb_build_object(
      'event_kind', v_event.event_kind,
      'source_work_completion_id', v_event.source_work_completion_id,
      'contractor_id', v_event.contractor_id,
      'po_id', v_event.po_id,
      'cutting_group_id', v_event.cutting_group_id,
      'physical_at_epoch_us', erp._cp3_epoch_microseconds(v_event.physical_at),
      'qty_signed', v_event.qty_signed
    ),
    erp.current_app_user_id(), v_reason
  );

  v_response := jsonb_build_object(
    'sewing_terminal_event_id', v_event.id,
    'event_number', v_event.event_number,
    'event_kind', v_event.event_kind,
    'source_work_completion_id', v_event.source_work_completion_id,
    'physical_at_epoch_us', erp._cp3_epoch_microseconds(v_event.physical_at),
    'qty_pcs', v_event.qty_signed,
    'row_version', v_event.row_version
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."record_sewing_terminal_v1"(p_payload jsonb, p_client_request_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.refresh_accessory_hpp_after_material_recost(p_material_id uuid, p_reason text DEFAULT 'Accessory historical moving-average recost'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_category uuid;
  r record;
  v_new numeric(18,6);
  v_changed integer:=0;
  v_po uuid;
begin
  perform erp.require_internal();
  select accessory_category_id into v_category from erp.materials where id=p_material_id and material_type='ACCESSORY';
  if v_category is null then return 0; end if;
  perform pg_advisory_xact_lock(hashtextextended('ACCESSORY_HPP_CATEGORY|'||v_category::text,0));

  create temporary table if not exists pg_temp.erp_accessory_hpp_changed_pos(po_id uuid primary key) on commit drop;
  truncate pg_temp.erp_accessory_hpp_changed_pos;

  for r in
    select s.id,s.po_id,s.costing_basis_at,s.category_avg_cost_base_snapshot,s.hpp_unit_cost_base_snapshot
    from erp.fg_accessory_cost_snapshots s
    where s.category_id=v_category and s.hpp_method='CATEGORY_MOVING_AVG'
    order by s.costing_basis_at,s.id
    for update
  loop
    v_new:=erp.accessory_category_weighted_avg_cost_at(v_category,r.costing_basis_at);
    if v_new is null then
      raise exception 'Historical accessory recost would remove the valuation basis for FG accessory snapshot %. Correct/reverse the upstream inventory event first.',r.id;
    end if;
    if abs(v_new-r.hpp_unit_cost_base_snapshot)>0.000001 then
      insert into erp.fg_accessory_cost_revisions(snapshot_id,material_id,old_category_avg_cost,new_category_avg_cost,old_hpp_unit_cost,new_hpp_unit_cost,reason,changed_by)
      values(r.id,p_material_id,r.category_avg_cost_base_snapshot,v_new,r.hpp_unit_cost_base_snapshot,v_new,coalesce(nullif(trim(p_reason),''),'Accessory historical moving-average recost'),erp.current_app_user_id());
      update erp.fg_accessory_cost_snapshots
      set category_avg_cost_base_snapshot=v_new,hpp_unit_cost_base_snapshot=v_new
      where id=r.id;
      insert into pg_temp.erp_accessory_hpp_changed_pos(po_id) values(r.po_id) on conflict do nothing;
      v_changed:=v_changed+1;
    end if;
  end loop;

  for v_po in select po_id from pg_temp.erp_accessory_hpp_changed_pos order by po_id loop
    perform erp.rebuild_po_hpp(v_po,'Accessory moving-average recost: '||coalesce(nullif(trim(p_reason),''),'historical material recost'));
    perform erp.propagate_conversion_hpp_for_po(v_po);
    perform erp.sync_po_hpp_to_gl(v_po,current_date);
  end loop;
  return v_changed;
end;
$function$;

alter function "erp"."refresh_accessory_hpp_after_material_recost"(p_material_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.refresh_bs_case_status(p_bs_case_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_case erp.bs_cases%rowtype;
  v_resolved integer;
  v_active boolean;
  v_status text;
begin
  select * into v_case from erp.bs_cases where id=p_bs_case_id for update;
  if v_case.id is null or v_case.status='CANCELLED' then return; end if;
  select coalesce(sum(qty_pcs),0)::integer into v_resolved
  from erp.bs_resolutions where bs_case_id=v_case.id;
  select exists(
    select 1 from erp.rework_orders
    where bs_case_id=v_case.id and status in('OPEN','IN_PROGRESS','PARTIAL')
  ) into v_active;

  if v_resolved>=v_case.qty_pcs then
    if exists(select 1 from erp.bs_resolutions where bs_case_id=v_case.id)
       and not exists(select 1 from erp.bs_resolutions where bs_case_id=v_case.id and resolution_type<>'SCRAP') then
      v_status:='SCRAPPED';
    elsif exists(select 1 from erp.bs_resolutions where bs_case_id=v_case.id)
       and not exists(select 1 from erp.bs_resolutions where bs_case_id=v_case.id and resolution_type<>'WRITE_OFF') then
      v_status:='WRITTEN_OFF';
    else v_status:='RESOLVED'; end if;
  elsif v_active then v_status:='IN_REWORK';
  elsif v_resolved>0 then v_status:='PARTIAL';
  else v_status:='OPEN'; end if;

  if v_case.status is distinct from v_status then
    update erp.bs_cases set status=v_status,updated_at=now() where id=v_case.id;
  end if;
end;
$function$;

alter function "erp"."refresh_bs_case_status"(p_bs_case_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.refresh_contractor_issue_payroll_status(p_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
DECLARE
  v_total numeric(24,6);
  v_paid numeric(24,6):=0;
  v_allocated numeric(24,6):=0;
  v_status varchar(20);
BEGIN
  PERFORM erp.require_internal();
  SELECT COALESCE(total_receivable,0) INTO v_total
  FROM erp.contractor_material_issue_items WHERE id=p_item_id FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT
    COALESCE(SUM(CASE WHEN ps.status='PAID' THEN pd.amount ELSE 0 END),0),
    COALESCE(SUM(CASE WHEN ps.status<>'REVERSED' THEN pd.amount ELSE 0 END),0)
  INTO v_paid,v_allocated
  FROM erp.payroll_deductions pd
  JOIN erp.payroll_settlements ps ON ps.id=pd.payroll_id
  WHERE pd.contractor_issue_item_id=p_item_id
    AND pd.deduction_type='MATERIAL_KASBON';

  v_status:=CASE
    WHEN v_total<=0 OR v_paid>=v_total-0.01 THEN 'SETTLED'
    WHEN v_paid>0 THEN 'PARTIAL'
    WHEN v_allocated>0 THEN 'ALLOCATED'
    ELSE 'UNALLOCATED'
  END;

  UPDATE erp.contractor_material_issue_items
  SET payroll_status=v_status
  WHERE id=p_item_id;
END;
$function$;

alter function "erp"."refresh_contractor_issue_payroll_status"(p_item_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.refresh_hpp_state_after_sale_header()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_po uuid; BEGIN IF NEW.status IN ('POSTED','PARTIAL_PAID','PAID') AND OLD.status IS DISTINCT FROM NEW.status THEN FOR v_po IN SELECT DISTINCT fl.po_id FROM erp.sale_stock_allocations a JOIN erp.sales_items si ON si.id=a.sale_item_id JOIN erp.fg_lots fl ON fl.id=a.lot_id WHERE si.sale_id=NEW.id AND fl.po_id IS NOT NULL LOOP PERFORM erp.refresh_po_hpp_gl_baseline(v_po); END LOOP; END IF; RETURN NEW; END; $function$;

alter function "erp"."refresh_hpp_state_after_sale_header"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.refresh_hpp_state_after_sales_return_header()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_po uuid; BEGIN IF NEW.status='POSTED' AND OLD.status IS DISTINCT FROM NEW.status THEN FOR v_po IN SELECT DISTINCT fl.po_id FROM erp.sales_return_items sri JOIN erp.fg_lots fl ON fl.id=sri.lot_id WHERE sri.return_id=NEW.id AND fl.po_id IS NOT NULL LOOP PERFORM erp.refresh_po_hpp_gl_baseline(v_po); END LOOP; END IF; RETURN NEW; END; $function$;

alter function "erp"."refresh_hpp_state_after_sales_return_header"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.refresh_material_cost_checkpoint(p_material_id uuid, p_checkpoint_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_stock numeric(18,6):=0;
  v_avg numeric(18,6):=0;
  v_last_physical timestamptz;
  v_last_system timestamptz;
  v_last_id uuid;
  v_has_active boolean;
  v_cutoff timestamptz;
begin
  perform erp.require_internal();
  if p_checkpoint_date is null then raise exception 'Checkpoint date is required'; end if;
  v_cutoff:=(p_checkpoint_date+1)::timestamptz;
  perform 1 from erp.materials where id=p_material_id for update;
  if not found then raise exception 'Material not found'; end if;

  select exists(
    select 1 from erp.material_stock_movements msm
    where msm.material_id=p_material_id
      and msm.physical_at<v_cutoff
      and msm.reversal_of_id is null
      and not exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=msm.id)
  ) into v_has_active;

  select h.stock_after,h.average_after,msm.physical_at,msm.system_created_at,msm.id
  into v_stock,v_avg,v_last_physical,v_last_system,v_last_id
  from erp.material_stock_movements msm
  join erp.material_cost_history h on h.movement_id=msm.id and h.material_id=p_material_id
  where msm.material_id=p_material_id
    and msm.physical_at<v_cutoff
    and msm.reversal_of_id is null
    and not exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=msm.id)
  order by msm.physical_at desc,msm.system_created_at desc,msm.id desc
  limit 1;

  if v_has_active and v_last_id is null then
    raise exception 'Cannot checkpoint material %: chronological cost history is incomplete before %',p_material_id,p_checkpoint_date;
  end if;
  if not v_has_active then
    v_stock:=0; v_avg:=0; v_last_physical:=null; v_last_system:=null; v_last_id:=null;
  end if;

  insert into erp.material_cost_checkpoints(material_id,checkpoint_date,stock_qty,moving_average_cost,last_physical_at,last_system_created_at,last_movement_id,checkpoint_created_at)
  values(p_material_id,p_checkpoint_date,coalesce(v_stock,0),coalesce(v_avg,0),v_last_physical,v_last_system,v_last_id,clock_timestamp())
  on conflict(material_id) do update
  set checkpoint_date=excluded.checkpoint_date,
      stock_qty=excluded.stock_qty,
      moving_average_cost=excluded.moving_average_cost,
      last_physical_at=excluded.last_physical_at,
      last_system_created_at=excluded.last_system_created_at,
      last_movement_id=excluded.last_movement_id,
      checkpoint_created_at=excluded.checkpoint_created_at;
end;
$function$;

alter function "erp"."refresh_material_cost_checkpoint"(p_material_id uuid, p_checkpoint_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.refresh_material_purchase_item_cost(p_purchase_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  i erp.material_purchase_items%rowtype;
  h erp.material_purchase_headers%rowtype;
  v_cost numeric;
begin
  perform erp.require_internal();
  select * into i from erp.material_purchase_items where id=p_purchase_item_id for update;
  if i.id is null then raise exception 'Material purchase item not found'; end if;
  select * into h from erp.material_purchase_headers where id=i.purchase_id for update;
  if h.id is null or h.status<>'POSTED' then raise exception 'Source purchase must be POSTED'; end if;
  v_cost:=erp.material_purchase_current_unit_cost(i.id);

  update erp.material_stock_movements msm
  set input_unit_cost=v_cost
  where msm.movement_type='PURCHASE' and msm.qty_signed>0 and(
    (msm.source_type='MATERIAL_PURCHASE_ITEM' and msm.source_id=i.id)
    or
    (msm.source_type='MATERIAL_PURCHASE_ROLL' and msm.source_id in(
      select mr.id from erp.material_rolls mr where mr.purchase_item_id=i.id
    ))
  );
  if not found then raise exception 'Original purchase stock movement not found for item %',i.id; end if;
  perform erp.recalculate_material_cost(i.material_id,h.physical_at);
end;
$function$;

alter function "erp"."refresh_material_purchase_item_cost"(p_purchase_item_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.refresh_material_purchase_item_match_state(p_purchase_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  i erp.material_purchase_items%rowtype;
  v_capacity numeric;
  v_matched numeric;
  v_actual_avg numeric;
  v_last_at timestamptz;
  v_last_by uuid;
begin
  perform erp.require_internal();
  select * into i from erp.material_purchase_items where id=p_purchase_item_id for update;
  if i.id is null then raise exception 'Material purchase item not found'; end if;
  if i.invoice_match_state='DIRECT_FINAL' then return; end if;

  v_capacity:=erp.material_purchase_invoice_capacity(i.id);
  select coalesce(sum(l.qty_invoiced),0),
         case when coalesce(sum(l.qty_invoiced),0)>0 then sum(l.net_amount)/sum(l.qty_invoiced) end,
         max(h.posted_at),
         (array_agg(h.created_by order by h.posted_at desc,h.id desc))[1]
  into v_matched,v_actual_avg,v_last_at,v_last_by
  from erp.material_supplier_invoice_lines l
  join erp.material_supplier_invoices h on h.id=l.invoice_id
  where l.purchase_item_id=i.id and h.status='POSTED';

  if v_matched<=0 then
    update erp.material_purchase_items
    set invoice_match_state='UNMATCHED',price_state='ESTIMATED',
        price_source=receipt_price_source_snapshot,
        supplier_final_unit_price_snapshot=null,
        price_finalized_at=null,price_finalized_by=null
    where id=i.id;
  elsif v_matched<v_capacity-0.000001 then
    update erp.material_purchase_items
    set invoice_match_state='PARTIAL',price_state='PARTIAL',price_source='SUPPLIER_INVOICE',
        supplier_final_unit_price_snapshot=v_actual_avg,
        price_finalized_at=v_last_at,price_finalized_by=v_last_by
    where id=i.id;
  else
    update erp.material_purchase_items
    set invoice_match_state='MATCHED',price_state='FINAL',price_source='SUPPLIER_INVOICE',
        supplier_final_unit_price_snapshot=v_actual_avg,
        price_finalized_at=v_last_at,price_finalized_by=v_last_by
    where id=i.id;
  end if;
end;
$function$;

alter function "erp"."refresh_material_purchase_item_match_state"(p_purchase_item_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.refresh_po_hpp_gl_baseline(p_po_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  t record;
  v_documented_gain numeric(24,6):=0;
begin
  perform erp.require_internal();
  select * into t from erp.compute_po_hpp_gl_targets(p_po_id);
  if t.base_output_qty is null or t.base_output_qty<=0 then return; end if;

  with lot_hpp as (
    select fl.id as lot_id,
           case when coalesce(hv.qty_basis_pcs,0)>0 then hv.total_cost/hv.qty_basis_pcs else 0 end::numeric as hpp_per_pcs
    from erp.fg_lots fl
    left join erp.hpp_versions hv on hv.lot_id=fl.id and hv.is_current=true
    where fl.po_id=p_po_id
  ), adj_net as (
    select fm.lot_id,sum(fm.qty_signed)::numeric as qty
    from erp.fg_stock_movements fm
    join erp.fg_lots fl on fl.id=fm.lot_id
    where fl.po_id=p_po_id
      and (
        (fm.movement_type='ADJUSTMENT' and fm.source_type='FG_ADJUSTMENT_ITEM')
        or (fm.movement_type='REVERSAL' and exists (
          select 1 from erp.fg_stock_movements orig
          where orig.id=fm.reversal_of_id and orig.movement_type='ADJUSTMENT' and orig.source_type='FG_ADJUSTMENT_ITEM'
        ))
      )
    group by fm.lot_id
  )
  select coalesce(sum(greatest(a.qty,0)*lh.hpp_per_pcs),0)
  into v_documented_gain
  from adj_net a join lot_hpp lh on lh.lot_id=a.lot_id;

  if t.other_out_value < -v_documented_gain-0.01 then
    raise exception 'PO HPP allocation inconsistent: current FG + net sold exceeds production output without a matching documented positive FG adjustment';
  end if;

  insert into erp.po_hpp_gl_state(po_id,base_output_qty,hpp_total_cost,fg_value,cogs_value,other_out_value,updated_at)
  values (p_po_id,t.base_output_qty,t.hpp_total_cost,t.fg_value,t.cogs_value,t.other_out_value,now())
  on conflict (po_id) do update set
    base_output_qty=excluded.base_output_qty,
    hpp_total_cost=excluded.hpp_total_cost,
    fg_value=excluded.fg_value,
    cogs_value=excluded.cogs_value,
    other_out_value=excluded.other_out_value,
    updated_at=now();
end;
$function$;

alter function "erp"."refresh_po_hpp_gl_baseline"(p_po_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reopen_accounting_through(p_new_closed_through date, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare v_old date;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan membuka kembali periode wajib diisi'; end if;
  select closed_through into v_old from erp.accounting_period_control where singleton_id=1 for update;
  if v_old is null then return; end if;
  if p_new_closed_through is not null and p_new_closed_through>=v_old then
    raise exception 'Tanggal reopen harus lebih awal dari periode tertutup saat ini % atau NULL untuk membuka seluruh periode',v_old;
  end if;
  if p_new_closed_through is not null and p_new_closed_through>=current_date then
    raise exception 'Tanggal tutup buku baru harus sebelum hari ini';
  end if;
  update erp.accounting_period_control
  set closed_through=p_new_closed_through,updated_at=now(),updated_by=erp.current_app_user_id(),change_reason=p_reason
  where singleton_id=1;
  insert into erp.audit_logs(entity_type,entity_id,action,old_data,new_data,changed_by,change_reason)
  values('accounting_period_control',null,'UPDATE',jsonb_build_object('closed_through',v_old),jsonb_build_object('closed_through',p_new_closed_through),erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reopen_accounting_through"(p_new_closed_through date, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reopen_production_order(p_po_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_status text;
  v_stage text;
  r record;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then
    raise exception 'Alasan reopen PO wajib diisi';
  end if;

  select status into v_status from erp.production_orders where id=p_po_id for update;
  if v_status is null then raise exception 'PO tidak ditemukan'; end if;
  if v_status<>'FINISHED' then
    raise exception 'Hanya PO FINISHED yang dapat direopen. Status saat ini %',v_status;
  end if;

  for r in
    select je.id
    from erp.po_wip_close_events e
    join erp.journal_entries je on je.id=e.journal_entry_id
    where e.po_id=p_po_id and je.source_type='PO_WIP_RESIDUAL_CLOSE' and je.status='POSTED'
    order by je.posting_at desc,je.id desc
  loop
    perform erp.reverse_journal(r.id,'Reopen PO: '||p_reason);
  end loop;

  if exists(select 1 from erp.qc_inspections q where q.po_id=p_po_id and q.status='POSTED')
     or exists(select 1 from erp.laundry_receipts lr join erp.laundry_deliveries ld on ld.id=lr.delivery_id where ld.po_id=p_po_id and lr.status='POSTED' and ld.status<>'REVERSED')
     or exists(select 1 from erp.fg_lots fl where fl.po_id=p_po_id and fl.lot_origin='PRODUCTION') then
    v_stage:='QC';
  elsif exists(select 1 from erp.laundry_deliveries ld where ld.po_id=p_po_id and ld.status not in('DRAFT','REVERSED')) then
    v_stage:='LAUNDRY';
  elsif exists(select 1 from erp.cutting_groups cg where cg.po_id=p_po_id and cg.picked_up_at is not null) then
    v_stage:='SEWING';
  elsif exists(select 1 from erp.cutting_groups cg where cg.po_id=p_po_id) then
    v_stage:='CUTTING';
  else
    v_stage:='DRAFT';
  end if;

  update erp.production_orders
  set status=case when v_stage='DRAFT' then 'DRAFT' else v_stage end,
      current_stage=case when v_stage='DRAFT' then 'CUTTING' else v_stage end,
      updated_at=now()
  where id=p_po_id;

  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('production_orders',p_po_id,'UPDATE',jsonb_build_object('correction_type','PO_REOPEN','previous_status','FINISHED','restored_stage',v_stage),erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reopen_production_order"(p_po_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.replace_material_purchase(p_original_purchase_id uuid, p_replacement_purchase_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  o erp.material_purchase_headers%rowtype;
  n erp.material_purchase_headers%rowtype;
  v_journal uuid;
  v_total numeric(24,6);
  v_material_id uuid;
begin
  perform erp.require_owner_admin();
  if p_original_purchase_id=p_replacement_purchase_id then raise exception 'Pembelian pengganti harus dokumen berbeda'; end if;
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan koreksi/replacement pembelian wajib diisi'; end if;

  select * into o from erp.material_purchase_headers where id=p_original_purchase_id for update;
  select * into n from erp.material_purchase_headers where id=p_replacement_purchase_id for update;
  if o.id is null or o.status<>'POSTED' then raise exception 'Pembelian lama harus POSTED'; end if;
  if n.id is null or n.status<>'DRAFT' then raise exception 'Pembelian pengganti harus sudah disiapkan sebagai DRAFT'; end if;
  if o.supplier_id is distinct from n.supplier_id then raise exception 'Pembelian pengganti harus memakai supplier yang sama; perubahan supplier perlu dokumen reversal/repost terpisah'; end if;
  if o.physical_at is distinct from n.physical_at then raise exception 'Pembelian pengganti harus memakai tanggal/jam fisik yang sama dengan source lama agar chronology stok tidak berubah diam-diam'; end if;
  if exists(select 1 from erp.supplier_payments where purchase_id=o.id and status='POSTED') then raise exception 'Pembelian lama sudah dibayar. Reverse pembayaran supplier terlebih dahulu sebelum replacement.'; end if;
  if exists(select 1 from erp.material_supplier_return_items ri join erp.material_supplier_returns rh on rh.id=ri.return_id join erp.material_purchase_items pi on pi.id=ri.purchase_item_id where pi.purchase_id=o.id and rh.status='POSTED') then raise exception 'Pembelian lama punya retur supplier aktif. Reverse retur terlebih dahulu.'; end if;
  if exists(select 1 from erp.material_purchase_cost_corrections where purchase_id=o.id and status='POSTED') then raise exception 'Pembelian lama punya koreksi harga aktif. Reverse koreksi harga terlebih dahulu.'; end if;

  -- Canonical material locks cover both the old and replacement material sets.
  -- This keeps cross-material replacements deterministic and ensures the final
  -- recost sees the complete old-source reversal + replacement posting.
  for v_material_id in
    select material_id
    from (
      select material_id from erp.material_purchase_items where purchase_id=o.id
      union
      select material_id from erp.material_purchase_items where purchase_id=n.id
    ) s
    order by material_id
  loop
    perform 1 from erp.materials where id=v_material_id for update;
  end loop;

  select coalesce(sum(line_total),0) into v_total from erp.material_purchase_items where purchase_id=o.id;
  select id into v_journal from erp.journal_entries where source_type='MATERIAL_PURCHASE' and source_id=o.id and status='POSTED' order by posting_at desc,id desc limit 1;
  if v_total>0.005 and v_journal is null then raise exception 'Jurnal pembelian lama tidak ditemukan; replacement dibatalkan'; end if;

  update erp.material_purchase_headers set status='REVERSED',updated_at=now() where id=o.id;
  perform set_config('erp.allow_source_replacement_negative','on',true);
  perform erp._stage_reverse_material_purchase_stock_at_source_time(o.id,'Replaced by purchase '||n.purchase_number||': '||p_reason);
  perform set_config('erp.allow_source_replacement_negative','off',true);

  perform erp.post_material_purchase(n.id);

  -- post_material_purchase recalculates replacement materials. Recalculate the
  -- complete union again so materials that existed only on the old purchase are
  -- also brought back in sync with their movement ledger.
  for v_material_id in
    select material_id
    from (
      select material_id from erp.material_purchase_items where purchase_id=o.id
      union
      select material_id from erp.material_purchase_items where purchase_id=n.id
    ) s
    order by material_id
  loop
    perform erp.recalculate_material_cost(v_material_id);
  end loop;

  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;
  update erp.material_purchase_headers set payment_status='UNPAID',updated_at=now() where id=o.id;

  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('material_purchase_headers',o.id,'REVERSE',jsonb_build_object('replacement_purchase_id',n.id,'replacement_purchase_number',n.purchase_number),erp.current_app_user_id(),p_reason);
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('material_purchase_headers',n.id,'UPDATE',jsonb_build_object('replaces_purchase_id',o.id,'replaces_purchase_number',o.purchase_number),erp.current_app_user_id(),'Replacement for corrected posted purchase: '||p_reason);
end;
$function$;

alter function "erp"."replace_material_purchase"(p_original_purchase_id uuid, p_replacement_purchase_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.require_internal()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth'
AS $function$ DECLARE v_app_role text;v_jwt_role text; BEGIN IF session_user IN ('postgres','supabase_admin') THEN RETURN; END IF;BEGIN v_jwt_role:=COALESCE(auth.jwt()->>'role','');EXCEPTION WHEN OTHERS THEN v_jwt_role:='';END; IF v_jwt_role='service_role' THEN RETURN; END IF;v_app_role:=erp.current_app_role(); IF v_app_role NOT IN ('OWNER','ADMIN','STAFF') THEN RAISE EXCEPTION 'Internal ERP access required'; END IF;END; $function$;

alter function "erp"."require_internal"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.require_manual_reminder_actor()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_role text;
begin
  perform erp.require_internal();
  v_actor := erp.current_app_user_id();
  v_role := erp.current_app_role();
  if v_actor is null or v_role not in ('OWNER','ADMIN','STAFF') then
    raise exception 'Mapped active internal ERP user required';
  end if;
  return v_actor;
end;
$function$;

alter function "erp"."require_manual_reminder_actor"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.require_owner_admin()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_jwt_role text;
begin
  if session_user in ('postgres','supabase_admin') then return; end if;
  begin
    v_jwt_role:=coalesce(auth.jwt()->>'role','');
  exception when others then
    v_jwt_role:='';
  end;
  if v_jwt_role='service_role' then return; end if;
  if coalesce(erp.current_app_role(),'') not in ('OWNER','ADMIN') then
    raise exception 'OWNER or ADMIN access required';
  end if;
end
$function$;

alter function "erp"."require_owner_admin"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.require_pattern_identity_on_app_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_jwt_role text;
begin
  begin
    v_jwt_role:=coalesce(auth.jwt()->>'role','');
  exception when others then
    v_jwt_role:='';
  end;
  if v_jwt_role in ('authenticated','service_role') and new.pattern_id is null then
    raise exception using errcode='23502',message='PATTERN_ID_REQUIRED_FOR_CUTTING_TRANSACTION';
  end if;
  return new;
end
$function$;

alter function "erp"."require_pattern_identity_on_app_write"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.require_permission(p_permission_key text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if coalesce(btrim(p_permission_key),'')='' or not erp.has_permission(p_permission_key) then
    raise exception using errcode='42501',message='PERMISSION_DENIED: '||coalesce(p_permission_key,'(missing)');
  end if;
end
$function$;

alter function "erp"."require_permission"(p_permission_key text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.require_rework_cost_before_payroll()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ DECLARE v_posted boolean; BEGIN IF NEW.source_type='REWORK' THEN SELECT ro.cost_posted INTO v_posted FROM erp.rework_component_lines rcl JOIN erp.rework_orders ro ON ro.id=rcl.rework_order_id WHERE rcl.id=NEW.source_id; IF COALESCE(v_posted,false)=false THEN RAISE EXCEPTION 'Rework cost must be posted before it can enter payroll'; END IF; END IF;RETURN NEW;END; $function$;

alter function "erp"."require_rework_cost_before_payroll"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.require_worker_daily_rate_at(p_worker_id uuid, p_effective_date date)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_rate numeric;
begin
  v_rate := erp.worker_daily_rate_at(p_worker_id, p_effective_date);
  if v_rate is null then
    raise exception 'Worker % has no daily-rate version covering %', p_worker_id, p_effective_date;
  end if;
  return v_rate;
end;
$function$;

alter function "erp"."require_worker_daily_rate_at"(p_worker_id uuid, p_effective_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reset_fg_stock_card_order(p_product_id uuid, p_location_id uuid, p_quality_grade text DEFAULT 'GRADE_A'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare r record;
begin
  perform erp.require_internal();
  for r in
    select id from erp.fg_stock_movements
    where product_id=p_product_id and location_id=p_location_id and quality_grade=coalesce(p_quality_grade,'GRADE_A')
    order by physical_at,system_created_at,id
  loop
    update erp.fg_stock_movements set book_order=nextval('erp.fg_stock_book_order_seq') where id=r.id;
  end loop;
end;
$function$;

alter function "erp"."reset_fg_stock_card_order"(p_product_id uuid, p_location_id uuid, p_quality_grade text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reset_fg_stock_mutation_book_order()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare r record;
begin
  perform erp.require_internal();
  perform pg_advisory_xact_lock(hashtextextended('FGBOOK|GLOBAL',0));
  for r in
    select id,row_number() over(order by physical_at,system_created_at,id)::bigint rn
    from erp.fg_stock_movements
    order by physical_at,system_created_at,id
  loop
    update erp.fg_stock_movements set book_order=r.rn*1000000 where id=r.id;
  end loop;
  perform setval('erp.fg_stock_book_order_seq',greatest(coalesce((select max(book_order) from erp.fg_stock_movements),0)+1000000,1),false);
end;
$function$;

alter function "erp"."reset_fg_stock_mutation_book_order"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reset_fg_stock_mutation_order()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare r record;
begin
  perform erp.require_internal();
  perform pg_advisory_xact_lock(hashtextextended('FGBOOK|GLOBAL',0));

  for r in
    select id,row_number() over(order by physical_at,system_created_at,id)::bigint rn
    from erp.fg_stock_movements
    order by physical_at,system_created_at,id
    for update
  loop
    update erp.fg_stock_movements
       set book_order=r.rn*1000000
     where id=r.id;
  end loop;

  perform setval(
    'erp.fg_stock_book_order_seq',
    greatest(coalesce((select max(book_order) from erp.fg_stock_movements),0)+1000000,1),
    false
  );

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason,new_data)
  values('fg_stock_movements',gen_random_uuid(),'UPDATE',erp.current_app_user_id(),
    'Urutan tampilan buku Mutasi Stok FG direset ke kronologi resmi; HPP/FIFO/jurnal tidak berubah',
    jsonb_build_object('presentation_only',true,'scope','GLOBAL_FG_MUTATION_BOOK','reset_to','PHYSICAL_CHRONOLOGY'));
end;
$function$;

alter function "erp"."reset_fg_stock_mutation_order"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.resolve_accounting_transaction_date(p_economic_date date)
 RETURNS date
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare v_closed date;
begin
  if p_economic_date is null then raise exception 'Tanggal transaksi ekonomi wajib diisi'; end if;
  if p_economic_date>current_date then raise exception 'Transaksi/jurnal tidak boleh dipost ke tanggal masa depan: %',p_economic_date; end if;
  select closed_through into v_closed from erp.accounting_period_control where singleton_id=1;
  if v_closed is not null and p_economic_date<=v_closed then
    return greatest(current_date,v_closed+1);
  end if;
  return p_economic_date;
end;
$function$;

alter function "erp"."resolve_accounting_transaction_date"(p_economic_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.resolve_bs_case_disposition_v2(p_bs_case_id uuid, p_resolution_type text, p_qty_pcs integer, p_compensation_amount numeric, p_source_laundry_claim_id uuid, p_physical_at timestamp with time zone, p_notes text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_type text:=upper(coalesce(p_resolution_type,''));
  v_hash text;v_cached jsonb;v_response jsonb;
  v_case erp.bs_cases%rowtype;v_claim erp.laundry_claims%rowtype;
  v_resolved integer;v_in_rework integer;v_remaining integer;
  v_used_amount numeric(20,2);v_used_qty integer;v_resolution uuid;
begin
  perform erp.require_internal();
  if v_type not in('CASH_COMPENSATION','SCRAP','WRITE_OFF','OTHER') then
    raise exception 'Disposition must be CASH_COMPENSATION, SCRAP, WRITE_OFF, or OTHER';
  end if;
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if coalesce(p_qty_pcs,0)<=0 then raise exception 'qty_pcs must be positive'; end if;
  if p_physical_at is null or p_physical_at>clock_timestamp()+interval '5 minutes' then
    raise exception 'Valid non-future physical_at is required';
  end if;
  if nullif(btrim(p_notes),'') is null then raise exception 'Disposition reason/notes are required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'bs_case_id',p_bs_case_id,'type',v_type,'qty',p_qty_pcs,
    'amount',coalesce(p_compensation_amount,0),'claim',p_source_laundry_claim_id,
    'physical_at',p_physical_at,'notes',btrim(p_notes),'expected_version',p_expected_version
  ));
  v_cached:=erp._idempotency_begin('resolve_bs_case_disposition_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  select * into v_case from erp.bs_cases where id=p_bs_case_id for update;
  if v_case.id is null then raise exception 'BS case not found'; end if;
  if v_case.status not in('OPEN','PARTIAL','IN_REWORK') then raise exception 'BS case is already closed/cancelled'; end if;
  if v_case.row_version<>p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_case.row_version;
  end if;
  if p_physical_at<v_case.physical_at then raise exception 'Disposition cannot predate BS detection'; end if;
  select coalesce(sum(qty_pcs),0)::integer into v_resolved from erp.bs_resolutions where bs_case_id=v_case.id;
  select coalesce(sum(qty_sent),0)::integer into v_in_rework from erp.rework_orders
  where bs_case_id=v_case.id and status in('OPEN','IN_PROGRESS','PARTIAL');
  v_remaining:=greatest(v_case.qty_pcs-v_resolved-v_in_rework,0);
  if p_qty_pcs>v_remaining then
    raise exception 'Disposition qty % exceeds currently available unresolved/non-rework qty %',p_qty_pcs,v_remaining;
  end if;

  if v_type='CASH_COMPENSATION' then
    if p_source_laundry_claim_id is null then raise exception 'CASH_COMPENSATION requires a settled laundry claim'; end if;
    if coalesce(p_compensation_amount,0)<=0 then raise exception 'CASH_COMPENSATION amount must be positive'; end if;
    select * into v_claim from erp.laundry_claims where id=p_source_laundry_claim_id for update;
    if v_claim.id is null or v_claim.status<>'SETTLED' then raise exception 'Linked laundry claim must be SETTLED'; end if;
    if v_case.responsible_vendor_id is null or v_claim.vendor_id<>v_case.responsible_vendor_id then
      raise exception 'Linked claim vendor does not match the BS responsible vendor';
    end if;
    if v_case.source_laundry_receipt_line_id is not null and not(
      v_claim.receipt_line_id=v_case.source_laundry_receipt_line_id
      or v_claim.delivery_id=(
        select lr.delivery_id from erp.laundry_receipt_lines l
        join erp.laundry_receipts lr on lr.id=l.receipt_id
        where l.id=v_case.source_laundry_receipt_line_id
      )
    ) then raise exception 'Linked claim does not belong to the BS laundry source'; end if;
    select coalesce(sum(compensation_amount),0),coalesce(sum(qty_pcs),0)::integer
    into v_used_amount,v_used_qty from erp.bs_resolutions
    where source_laundry_claim_id=v_claim.id;
    if v_used_amount+coalesce(p_compensation_amount,0)>v_claim.compensation_amount+0.005 then
      raise exception 'BS cash dispositions exceed settled laundry claim compensation';
    end if;
    if v_used_qty+p_qty_pcs>v_claim.qty_claimed then
      raise exception 'BS cash disposition qty exceeds settled laundry claim qty';
    end if;
  else
    if coalesce(p_compensation_amount,0)<>0 or p_source_laundry_claim_id is not null then
      raise exception 'Only CASH_COMPENSATION may carry claim/compensation amount';
    end if;
  end if;
  perform set_config('app.change_reason',btrim(p_notes),true);
  insert into erp.bs_resolutions(
    bs_case_id,resolution_type,qty_pcs,compensation_amount,
    responsible_contractor_id,responsible_vendor_id,
    source_laundry_claim_id,physical_at,notes
  ) values(
    v_case.id,v_type,p_qty_pcs,coalesce(p_compensation_amount,0),
    v_case.responsible_contractor_id,v_case.responsible_vendor_id,
    p_source_laundry_claim_id,p_physical_at,btrim(p_notes)
  ) returning id into v_resolution;
  perform erp.refresh_bs_case_status(v_case.id);
  select * into v_case from erp.bs_cases where id=v_case.id;
  v_response:=jsonb_build_object(
    'bs_resolution_id',v_resolution,'bs_case_id',v_case.id,'status',v_case.status,
    'row_version',v_case.row_version,'resolution_type',v_type,'qty_pcs',p_qty_pcs
  );
  return erp._idempotency_complete('resolve_bs_case_disposition_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."resolve_bs_case_disposition_v2"(p_bs_case_id uuid, p_resolution_type text, p_qty_pcs integer, p_compensation_amount numeric, p_source_laundry_claim_id uuid, p_physical_at timestamp with time zone, p_notes text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.resolve_laundry_claim(p_claim_id uuid, p_resolution text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare c erp.laundry_claims%rowtype;v_ap_account uuid;v_ap_balance numeric(24,6):=0;v_effective_date date;
begin
  perform erp.require_owner_admin();
  if p_resolution not in ('SETTLED','WRITTEN_OFF') then raise exception 'Claim resolution must be SETTLED or WRITTEN_OFF'; end if;
  if nullif(trim(p_reason),'') is null then raise exception 'Claim resolution reason is required'; end if;
  select * into c from erp.laundry_claims where id=p_claim_id for update;
  if c.id is null then raise exception 'Laundry claim not found'; end if;
  if c.status in ('SETTLED','WRITTEN_OFF') then return; end if;
  if c.status='REJECTED' then raise exception 'Rejected laundry claim cannot be settled/write-off without reopening'; end if;
  if p_resolution='WRITTEN_OFF' and c.compensation_amount>0 then raise exception 'WRITTEN_OFF claim must have zero compensation; set compensation to zero or use SETTLED'; end if;
  v_effective_date:=coalesce(c.resolution_date,current_date);
  if v_effective_date>current_date then raise exception 'Tanggal penyelesaian claim laundry berada di masa depan'; end if;
  if p_resolution='SETTLED' and c.compensation_amount>0 then
    v_ap_account:=erp.account_id('AP_VENDOR');
    select coalesce(sum(jl.credit-jl.debit),0) into v_ap_balance from erp.journal_lines jl join erp.journal_entries je on je.id=jl.journal_entry_id
    where je.status in ('POSTED','REVERSED') and jl.vendor_id=c.vendor_id and jl.account_id=v_ap_account;
    if v_ap_balance+0.01<c.compensation_amount then raise exception 'Claim compensation % exceeds current laundry vendor payable %. Cash/receivable settlement needs a separate receivable workflow',c.compensation_amount,round(v_ap_balance,2); end if;
    perform erp.post_journal('LAUNDRY_CLAIM_SETTLEMENT',c.id,v_effective_date,'Laundry claim compensation offset',jsonb_build_array(
      jsonb_build_object('mapping_key','AP_VENDOR','debit',round(c.compensation_amount,2),'credit',0,'vendor_id',c.vendor_id),
      jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',0,'credit',round(c.compensation_amount,2),'vendor_id',c.vendor_id)));
  end if;
  update erp.laundry_claims set status=p_resolution,resolution_date=v_effective_date,resolved_at=now(),notes=concat_ws(E'\n',notes,'Resolution: '||p_reason) where id=c.id;
end$function$;

alter function "erp"."resolve_laundry_claim"(p_claim_id uuid, p_resolution text, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.resolve_laundry_claim_v2(p_claim_id uuid, p_resolution text, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_claim erp.laundry_claims%rowtype;
begin
  perform erp.require_owner_admin();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'Claim resolution reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'claim_id',p_claim_id,'resolution',upper(p_resolution),'reason',btrim(p_reason),
    'expected_version',p_expected_version
  ));
  v_cached:=erp._idempotency_begin('resolve_laundry_claim_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  select * into v_claim from erp.laundry_claims where id=p_claim_id for update;
  if v_claim.id is null then raise exception 'Laundry claim not found'; end if;
  if v_claim.row_version<>p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_claim.row_version;
  end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  perform erp.resolve_laundry_claim(v_claim.id,upper(p_resolution),btrim(p_reason));
  select * into v_claim from erp.laundry_claims where id=v_claim.id;
  v_response:=jsonb_build_object(
    'laundry_claim_id',v_claim.id,'status',v_claim.status,
    'row_version',v_claim.row_version,'resolved_at',v_claim.resolved_at,
    'resolution_date',v_claim.resolution_date
  );
  return erp._idempotency_complete('resolve_laundry_claim_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."resolve_laundry_claim_v2"(p_claim_id uuid, p_resolution text, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.resolve_opening_fg_unit_hpp(p_item_id uuid, p_opening_date date)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  i erp.opening_balance_items%rowtype;
  v_price numeric(20,6);
  v_hpp numeric(20,6);
  v_asof timestamptz;
begin
  perform erp.require_internal();
  select * into i from erp.opening_balance_items where id=p_item_id for update;
  if i.id is null or i.balance_type<>'FINISHED_GOODS' then raise exception 'Opening FG item tidak ditemukan'; end if;

  -- Opening date is a business date, while versioned SKU identity is timestamped.
  -- Use the first valid instant for this SKU on that opening date so a same-day
  -- effective identity is not incorrectly treated as 'not yet existing at midnight'.
  v_asof:=erp.product_opening_physical_at(i.product_id,p_opening_date);

  if i.hpp_input_method='PRICE_PERCENT' then
    if i.hpp_percent_of_price is null or i.hpp_percent_of_price<=0 or i.hpp_percent_of_price>1000 then
      raise exception 'Persentase HPP dari harga jual wajib >0 dan masuk akal untuk opening FG';
    end if;
    v_price:=erp.resolve_product_price_at(i.product_id,v_asof);
    if v_price is null then
      raise exception 'Harga jual produk belum tersedia pada waktu opening %. Isi harga jual historis/cutover atau gunakan HPP manual.',v_asof;
    end if;
    v_hpp:=round(v_price*i.hpp_percent_of_price/100.0,6);
    update erp.opening_balance_items set reference_sell_price_snapshot=v_price,unit_cost_snapshot=v_hpp where id=i.id;
    return v_hpp;
  end if;

  v_hpp:=coalesce(i.unit_cost_snapshot,0);
  update erp.opening_balance_items set reference_sell_price_snapshot=null where id=i.id;
  return v_hpp;
end;
$function$;

alter function "erp"."resolve_opening_fg_unit_hpp"(p_item_id uuid, p_opening_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.resolve_opening_product_identity(p_sku text, p_cutover_at timestamp with time zone, p_color_name text DEFAULT NULL::text, p_size_code text DEFAULT NULL::text, p_model_code text DEFAULT NULL::text, p_brand_code text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_id uuid;
  v_count integer;
begin
  perform erp.require_internal();
  if nullif(trim(p_sku),'') is null or p_cutover_at is null then
    raise exception 'SKU dan waktu cutover wajib diisi untuk mapping stok opening';
  end if;

  select count(*),(array_agg(p.id order by p.effective_from desc,p.id desc))[1]
  into v_count,v_id
  from erp.products p
  join erp.sizes s on s.id=p.size_id
  join erp.product_models pm on pm.id=p.model_id
  join erp.brands b on b.id=p.brand_id
  where lower(trim(p.sku))=lower(trim(p_sku))
    and p.effective_from<=p_cutover_at
    and (nullif(trim(p_color_name),'') is null or lower(trim(p.color_name))=lower(trim(p_color_name)))
    and (nullif(trim(p_size_code),'') is null or lower(trim(s.size_code))=lower(trim(p_size_code)))
    and (nullif(trim(p_model_code),'') is null or lower(trim(pm.model_code))=lower(trim(p_model_code)))
    and (nullif(trim(p_brand_code),'') is null or lower(trim(b.brand_code))=lower(trim(p_brand_code)));

  if v_count=0 then
    raise exception 'Opening FG SKU % tidak punya identity yang cocok sebelum cutover %. Periksa SKU/warna/size/model/brand.',p_sku,p_cutover_at;
  end if;
  if v_count>1 then
    raise exception 'Opening FG SKU % ambigu: ada % identity lama/current yang cocok sebelum cutover. Isi color_name dan bila perlu size_code/model_code/brand_code agar stok lama tidak salah masuk ke identity baru.',p_sku,v_count;
  end if;
  return v_id;
end$function$;

alter function "erp"."resolve_opening_product_identity"(p_sku text, p_cutover_at timestamp with time zone, p_color_name text, p_size_code text, p_model_code text, p_brand_code text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.resolve_product_id_by_sku_at(p_sku text, p_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_id uuid;v_count integer;
begin
  perform erp.require_internal();
  if nullif(trim(p_sku),'') is null or p_at is null then raise exception 'SKU dan tanggal referensi wajib diisi'; end if;
  select count(*),(array_agg(id order by effective_from desc,id desc))[1]
    into v_count,v_id
  from erp.products
  where lower(trim(sku))=lower(trim(p_sku))
    and effective_from<=p_at
    and (effective_to is null or effective_to>p_at);
  if v_count=0 then raise exception 'SKU % tidak memiliki versi identitas yang berlaku pada %',p_sku,p_at; end if;
  if v_count>1 then raise exception 'SKU % ambigu pada %; ada % versi identitas aktif bersamaan',p_sku,p_at,v_count; end if;
  return v_id;
end$function$;

alter function "erp"."resolve_product_id_by_sku_at"(p_sku text, p_at timestamp with time zone) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.resolve_product_price_at(p_product_id uuid, p_at timestamp with time zone)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_root uuid; v_price numeric;
begin
  perform erp.require_internal();
  select identity_root_id into v_root from erp.products where id=p_product_id;
  if v_root is null then raise exception 'SKU/produk tidak ditemukan'; end if;
  select pp.price into v_price
  from erp.product_price_versions pp
  where pp.product_id=v_root and pp.effective_from<=p_at and (pp.effective_to is null or pp.effective_to>p_at)
  order by pp.effective_from desc,pp.created_at desc,pp.id desc limit 1;
  return v_price;
end;
$function$;

alter function "erp"."resolve_product_price_at"(p_product_id uuid, p_at timestamp with time zone) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.resolve_product_price_version_id_at(p_product_id uuid, p_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_root uuid; v_id uuid;
begin
  perform erp.require_internal();
  select identity_root_id into v_root from erp.products where id=p_product_id;
  if v_root is null then raise exception 'SKU/produk tidak ditemukan'; end if;
  select pp.id into v_id
  from erp.product_price_versions pp
  where pp.product_id=v_root and pp.effective_from<=p_at and (pp.effective_to is null or pp.effective_to>p_at)
  order by pp.effective_from desc,pp.created_at desc,pp.id desc limit 1;
  return v_id;
end;
$function$;

alter function "erp"."resolve_product_price_version_id_at"(p_product_id uuid, p_at timestamp with time zone) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_attendance_period_v1(p_period_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'reverse_attendance_period_v1';
  v_hash text;
  v_cached jsonb;
  v_period erp.attendance_periods%rowtype;
  v_source erp.attendance_periods%rowtype;
  v_response jsonb;
begin
  perform erp.require_owner_admin();
  if p_period_id is null or p_expected_version is null then
    raise exception 'period_id and expected_version are required';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Attendance reversal reason is required';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'period_id', p_period_id,
    'reason', p_reason,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_period
  from erp.attendance_periods
  where id = p_period_id
  for update;

  if v_period.id is null then raise exception 'Attendance period not found'; end if;
  if v_period.status <> 'POSTED' then raise exception 'Only POSTED attendance can be reversed'; end if;
  if v_period.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_period.row_version;
  end if;
  if exists (
    select 1
    from erp.payroll_attendance_items pai
    join erp.payroll_settlements ps on ps.id = pai.payroll_id
    join erp.attendance_records ar on ar.id = pai.attendance_record_id
    where ar.attendance_period_id = v_period.id
      and ps.status <> 'REVERSED'
  ) then
    raise exception 'Attendance reversal requires its consuming payroll to be reversed first';
  end if;

  perform set_config('app.change_reason', p_reason, true);
  perform set_config('app.attendance_period_lifecycle', 'on', true);

  if v_period.correction_of_period_id is not null then
    select * into v_source
    from erp.attendance_periods
    where id = v_period.correction_of_period_id
    for update;
    if v_source.id is null or v_source.status <> 'CORRECTED' then
      raise exception 'Correction source cannot be restored from status %', v_source.status;
    end if;
  end if;

  update erp.attendance_records
  set record_lifecycle = 'REVERSED',
      change_reason = p_reason,
      updated_by = erp.current_app_user_id()
  where attendance_period_id = v_period.id;

  if v_source.id is not null then
    update erp.attendance_records
    set record_lifecycle = 'POSTED',
        change_reason = 'Restored after correction reversal: ' || p_reason,
        updated_by = erp.current_app_user_id()
    where attendance_period_id = v_source.id
      and record_lifecycle = 'CORRECTED';

    update erp.attendance_periods
    set status = 'POSTED',
        posting_reason = 'Restored after correction reversal: ' || p_reason
    where id = v_source.id;
  end if;

  update erp.attendance_periods
  set status = 'REVERSED',
      reversal_reason = p_reason,
      reversed_at = clock_timestamp(),
      reversed_by = erp.current_app_user_id()
  where id = v_period.id
  returning * into v_period;

  v_response := jsonb_build_object(
    'period_id', v_period.id,
    'status', v_period.status,
    'row_version', v_period.row_version,
    'reversed_at', v_period.reversed_at,
    'restored_source_period_id', v_source.id
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."reverse_attendance_period_v1"(p_period_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_bs_disposition_v2(p_resolution_id uuid, p_reason text, p_client_request_id uuid, p_expected_bs_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_resolution erp.bs_resolutions%rowtype;v_case erp.bs_cases%rowtype;
begin
  perform erp.require_owner_admin();
  if nullif(btrim(p_reason),'') is null then raise exception 'Reversal reason is required'; end if;
  if p_expected_bs_version is null then raise exception 'expected_bs_version is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'resolution_id',p_resolution_id,'reason',btrim(p_reason),'expected_version',p_expected_bs_version
  ));
  v_cached:=erp._idempotency_begin('reverse_bs_disposition_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  select * into v_resolution from erp.bs_resolutions where id=p_resolution_id for update;
  if v_resolution.id is null then raise exception 'BS disposition not found'; end if;
  if v_resolution.source_rework_order_id is not null
     or v_resolution.resolution_type in('REWORK_SEWING','REWORK_LAUNDRY') then
    raise exception 'Rework resolution must be reversed through reverse_rework_completion';
  end if;
  select * into v_case from erp.bs_cases where id=v_resolution.bs_case_id for update;
  if v_case.row_version<>p_expected_bs_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_bs_version,v_case.row_version;
  end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  delete from erp.bs_resolutions where id=v_resolution.id;
  perform erp.refresh_bs_case_status(v_case.id);
  insert into erp.audit_logs(entity_type,entity_id,action,old_data,changed_by,change_reason)
  values('bs_resolutions',v_resolution.id,'REVERSE',to_jsonb(v_resolution),erp.current_app_user_id(),btrim(p_reason));
  select * into v_case from erp.bs_cases where id=v_case.id;
  v_response:=jsonb_build_object(
    'bs_resolution_id',v_resolution.id,'status','REVERSED',
    'bs_case_id',v_case.id,'bs_case_status',v_case.status,'row_version',v_case.row_version
  );
  return erp._idempotency_complete('reverse_bs_disposition_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."reverse_bs_disposition_v2"(p_resolution_id uuid, p_reason text, p_client_request_id uuid, p_expected_bs_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_contractor_material_issue(p_issue_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.contractor_material_issues%rowtype;
  r record;
  j record;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal pengambilan material/aksesoris mandor wajib diisi'; end if;

  select * into h from erp.contractor_material_issues where id=p_issue_id for update;
  if h.id is null then raise exception 'Transaksi pengambilan material/aksesoris mandor tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya pengambilan material/aksesoris mandor yang sudah POSTED yang dapat direverse'; end if;

  if exists(
    select 1
    from erp.payroll_deductions pd
    join erp.payroll_settlements ps on ps.id=pd.payroll_id
    join erp.contractor_material_issue_items ii on ii.id=pd.contractor_issue_item_id
    where ii.issue_id=h.id and ps.status<>'REVERSED'
  ) then
    raise exception 'Pengambilan ini sudah masuk payroll/kasbon mandor. Cancel atau reverse payroll yang masih aktif terlebih dahulu agar potongan gaji dan piutang mandor tidak beda.';
  end if;

  for r in
    select msm.id
    from erp.material_stock_movements msm
    join erp.contractor_material_issue_items ii on ii.id=msm.source_id
    where ii.issue_id=h.id
      and msm.source_type='CONTRACTOR_MATERIAL_ISSUE_ITEM'
      and msm.movement_type='CONTRACTOR_ISSUE'
    order by msm.system_created_at desc,msm.id desc
  loop
    perform erp.reverse_material_movement(r.id,p_reason);
  end loop;

  for j in
    select je.id
    from erp.journal_entries je
    where je.source_id=h.id
      and je.source_type in ('CONTRACTOR_ACCESSORY_STOCK_COST','CONTRACTOR_NONACCESSORY_MATERIAL_COST','CONTRACTOR_MATERIAL_RECEIVABLE')
      and je.status='POSTED'
    order by je.posting_at desc,je.id desc
  loop
    perform erp.reverse_journal(j.id,p_reason);
  end loop;

  update erp.contractor_material_issues set status='REVERSED',updated_at=now() where id=h.id;
  update erp.contractor_material_issue_items set payroll_status='UNALLOCATED' where issue_id=h.id;

  if h.po_id is not null and exists(select 1 from erp.fg_lots where po_id=h.po_id) then
    perform erp.rebuild_po_hpp(h.po_id,'Mandor material issue reversed: '||p_reason);
    perform erp.propagate_conversion_hpp_for_po(h.po_id);
    perform erp.sync_po_hpp_to_gl(h.po_id,current_date);
  end if;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values ('contractor_material_issues',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_contractor_material_issue"(p_issue_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_contractor_material_issue_v2(p_issue_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare v_hash text;v_cached jsonb;v_response jsonb;h erp.contractor_material_issues%rowtype;
begin
  perform erp.require_owner_admin();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'Reversal reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('id',p_issue_id,'reason',btrim(p_reason),'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('reverse_contractor_material_issue_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  select * into h from erp.contractor_material_issues where id=p_issue_id for update;
  if h.id is null then raise exception 'Contractor material issue not found'; end if;
  if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
  perform erp.reverse_contractor_material_issue(h.id,btrim(p_reason));
  select * into h from erp.contractor_material_issues where id=h.id;
  v_response:=jsonb_build_object('contractor_material_issue_id',h.id,'status',h.status,'row_version',h.row_version);
  return erp._idempotency_complete('reverse_contractor_material_issue_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."reverse_contractor_material_issue_v2"(p_issue_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_cutting_material_flow_before_sewing_v2(p_cutting_group_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_group erp.cutting_groups%rowtype;
  r record;
  v_reversed_movements integer := 0;
  v_reversed_journals integer := 0;
begin
  perform erp.require_owner_admin();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'Reversal reason is required'; end if;
  v_hash := erp._request_hash(jsonb_build_object(
    'cutting_group_id', p_cutting_group_id,
    'reason', btrim(p_reason),
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(
    'reverse_cutting_material_flow_before_sewing_v2', p_client_request_id, v_hash
  );
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason', btrim(p_reason), true);

  select * into v_group
  from erp.cutting_groups where id = p_cutting_group_id for update;
  if v_group.id is null then raise exception 'Potongan not found'; end if;
  if v_group.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_group.row_version;
  end if;
  if v_group.status not in ('CUT','PICKED_UP') then
    raise exception 'Only CUT/PICKED_UP Potongan can use pre-sewing material reversal';
  end if;
  if erp.cutting_group_has_downstream_after_pickup(v_group.id) then
    raise exception 'Potongan already has sewing/downstream evidence; reverse downstream documents instead';
  end if;
  if not v_group.material_issue_posted
     and not v_group.material_return_posted
     and not exists (
       select 1 from erp.material_stock_movements m
       where m.source_id = v_group.id
         and m.source_type in ('CUTTING_GROUP','CUTTING_GROUP_RETURN')
         and not exists (
           select 1 from erp.material_stock_movements rv where rv.reversal_of_id = m.id
         )
     )
  then raise exception 'Potongan has no active cutting material flow to reverse'; end if;

  -- Reverse posted return journals first, then the original issue journal.
  -- Any later failure rolls this whole function back atomically.
  for r in
    select je.id
    from erp.journal_entries je
    join erp.cutting_group_rolls cgr on cgr.id = je.source_id
    where cgr.cutting_group_id = v_group.id
      and je.source_type = 'CUTTING_MATERIAL_RETURN_LINE'
      and je.status = 'POSTED'
    order by je.posting_at desc, je.id desc
  loop
    perform erp.reverse_journal(r.id, btrim(p_reason));
    v_reversed_journals := v_reversed_journals + 1;
  end loop;

  for r in
    select je.id
    from erp.journal_entries je
    where je.source_type = 'CUTTING_MATERIAL_ISSUE'
      and je.source_id = v_group.id
      and je.status = 'POSTED'
    order by je.posting_at desc, je.id desc
  loop
    perform erp.reverse_journal(r.id, btrim(p_reason));
    v_reversed_journals := v_reversed_journals + 1;
  end loop;

  -- Positive cutting returns are removed from warehouse first. The normal
  -- negative-stock guard blocks reversal if that returned quantity was consumed.
  -- The original issue is then restored to its source warehouse.
  for r in
    select m.*
    from erp.material_stock_movements m
    where m.source_id = v_group.id
      and m.source_type in ('CUTTING_GROUP','CUTTING_GROUP_RETURN')
      and not exists (
        select 1 from erp.material_stock_movements rv where rv.reversal_of_id = m.id
      )
    order by case m.source_type when 'CUTTING_GROUP_RETURN' then 0 else 1 end,
             m.system_created_at, m.id
  loop
    insert into erp.material_stock_movements(
      material_id, roll_id, location_id, movement_type, qty_signed,
      input_unit_cost, source_type, source_id, physical_at, created_by,
      reversal_of_id, note
    ) values (
      r.material_id, r.roll_id, r.location_id, 'REVERSAL', -r.qty_signed,
      r.unit_cost_snapshot, 'CUTTING_PRESEWING_REVERSAL', v_group.id,
      greatest(clock_timestamp(), r.physical_at), erp.current_app_user_id(),
      r.id, btrim(p_reason)
    );
    v_reversed_movements := v_reversed_movements + 1;
  end loop;

  for r in
    select distinct m.material_id
    from erp.material_stock_movements m
    where m.source_id = v_group.id
      and m.source_type in ('CUTTING_GROUP','CUTTING_GROUP_RETURN')
  loop
    perform erp.recalculate_material_cost(r.material_id);
  end loop;

  update erp.cutting_groups
  set material_issue_posted = false,
      material_return_posted = false,
      status = case when picked_up_at is null then 'CUT' else 'PICKED_UP' end,
      updated_at = now()
  where id = v_group.id
  returning * into v_group;

  v_response := jsonb_build_object(
    'cutting_group_id', v_group.id,
    'status', v_group.status,
    'row_version', v_group.row_version,
    'reversed_movement_count', v_reversed_movements,
    'reversed_journal_count', v_reversed_journals,
    'presewing_reversible', erp.is_cutting_group_presewing_reversible(v_group.id)
  );
  return erp._idempotency_complete(
    'reverse_cutting_material_flow_before_sewing_v2',
    p_client_request_id, v_response
  );
end;
$function$;

alter function "erp"."reverse_cutting_material_flow_before_sewing_v2"(p_cutting_group_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_cutting_qty_correction(p_correction_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
DECLARE
  v_batch uuid;
  v_lines jsonb;
BEGIN
  PERFORM erp.require_internal();
  SELECT cutting_batch_id INTO v_batch
  FROM erp.cutting_qty_corrections
  WHERE id=p_correction_id
  FOR UPDATE;
  IF v_batch IS NULL THEN RAISE EXCEPTION 'Correction not found'; END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'cutting_group_id',l.cutting_group_id,
    'size_slot_id',l.size_slot_id,
    'qty_delta_pcs',-l.qty_delta_pcs,
    'notes','Reversal of '||p_correction_id::text
  ))
  INTO v_lines
  FROM erp.cutting_qty_correction_lines l
  WHERE l.correction_id=p_correction_id;

  RETURN erp._post_cutting_qty_correction(
    v_batch,'REVERSAL','REVERSAL',p_reason,v_lines,now(),p_correction_id
  );
END;
$function$;

alter function "erp"."reverse_cutting_qty_correction"(p_correction_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_cutting_qty_correction_v2(p_correction_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_reason text := nullif(btrim(p_reason), '');
  v_source erp.cutting_qty_corrections%rowtype;
  v_batch erp.cutting_batches%rowtype;
  v_reversal_id uuid;
  v_reversal_number text;
  v_net_delta bigint;
  v_totals record;
begin
  perform erp.require_owner_admin();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if p_correction_id is null then raise exception 'correction_id is required'; end if;
  if v_reason is null then raise exception 'Reversal reason is required'; end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'correction_id', p_correction_id,
    'reason', v_reason,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(
    'reverse_cutting_qty_correction_v2', p_client_request_id, v_hash
  );
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason', v_reason, true);

  select * into v_source
  from erp.cutting_qty_corrections
  where id = p_correction_id;
  if v_source.id is null then raise exception 'Correction not found'; end if;
  if v_source.correction_type = 'REVERSAL' then
    raise exception 'A REVERSAL cannot be reversed; post a new reasoned correction instead';
  end if;

  select * into v_batch
  from erp.cutting_batches
  where id = v_source.cutting_batch_id
  for update;
  if v_batch.id is null then raise exception 'Cutting batch not found'; end if;
  if v_batch.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',
      p_expected_version, v_batch.row_version;
  end if;

  select * into v_source
  from erp.cutting_qty_corrections
  where id = p_correction_id
  for update;
  if exists (
    select 1 from erp.cutting_qty_corrections
    where reversal_of_id = p_correction_id
  ) then
    raise exception 'Correction has already been reversed';
  end if;

  v_reversal_id := erp.reverse_cutting_qty_correction(
    p_correction_id, v_reason
  );

  update erp.cutting_batches
  set updated_at = clock_timestamp()
  where id = v_source.cutting_batch_id
  returning * into v_batch;

  select c.correction_number, coalesce(sum(l.qty_delta_pcs), 0)::bigint
  into v_reversal_number, v_net_delta
  from erp.cutting_qty_corrections c
  join erp.cutting_qty_correction_lines l on l.correction_id = c.id
  where c.id = v_reversal_id
  group by c.correction_number;

  select original_pcs, adjustment_pcs, effective_pcs
  into v_totals
  from erp.v_cutting_batch_totals
  where cutting_batch_id = v_source.cutting_batch_id;

  v_response := jsonb_build_object(
    'correction_id', p_correction_id,
    'reversal_id', v_reversal_id,
    'reversal_number', v_reversal_number,
    'cutting_batch_id', v_source.cutting_batch_id,
    'net_delta_pcs', v_net_delta,
    'original_pcs', coalesce(v_totals.original_pcs, 0),
    'adjustment_pcs', coalesce(v_totals.adjustment_pcs, 0),
    'effective_pcs', coalesce(v_totals.effective_pcs, 0),
    'row_version', v_batch.row_version,
    'status', 'REVERSED'
  );
  return erp._idempotency_complete(
    'reverse_cutting_qty_correction_v2', p_client_request_id, v_response
  );
end;
$function$;

alter function "erp"."reverse_cutting_qty_correction_v2"(p_correction_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_fg_adjustment(p_adjustment_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.fg_adjustments%rowtype;
  r record;
  v_journal uuid;
  v_po uuid;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal FG adjustment wajib diisi'; end if;
  select * into h from erp.fg_adjustments where id=p_adjustment_id for update;
  if h.id is null then raise exception 'FG adjustment tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya FG adjustment POSTED yang dapat direverse'; end if;

  for r in
    select fm.id
    from erp.fg_stock_movements fm
    join erp.fg_adjustment_items fai on fai.id=fm.source_id
    where fai.adjustment_id=h.id and fm.source_type='FG_ADJUSTMENT_ITEM' and fm.movement_type='ADJUSTMENT'
    order by fm.physical_at desc,fm.id desc
  loop
    perform erp.reverse_fg_movement(r.id,p_reason);
  end loop;

  select id into v_journal from erp.journal_entries
  where source_type='FG_ADJUSTMENT' and source_id=h.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;

  update erp.fg_adjustments set status='REVERSED' where id=h.id;

  for v_po in
    select distinct fl.po_id
    from erp.fg_adjustment_items fai join erp.fg_lots fl on fl.id=fai.lot_id
    where fai.adjustment_id=h.id and fl.po_id is not null and fl.lot_origin in ('PRODUCTION','CONVERSION')
  loop
    perform erp.sync_po_hpp_to_gl(v_po,current_date);
  end loop;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values ('fg_adjustments',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_fg_adjustment"(p_adjustment_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_fg_adjustment_v2(p_adjustment_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare v_hash text;v_cached jsonb;v_response jsonb;h erp.fg_adjustments%rowtype;
begin
  perform erp.require_owner_admin();
  if p_expected_version is null then raise exception 'expected_version is required';end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'Reversal reason is required';end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'id',p_adjustment_id,'expected_version',p_expected_version,'reason',btrim(p_reason)
  ));
  v_cached:=erp._idempotency_begin('reverse_fg_adjustment_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached;end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  select * into h from erp.fg_adjustments where id=p_adjustment_id for update;
  if h.id is null then raise exception 'FG adjustment not found';end if;
  if h.row_version<>p_expected_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version;
  end if;
  perform erp.reverse_fg_adjustment(h.id,btrim(p_reason));
  select * into h from erp.fg_adjustments where id=h.id;
  v_response:=jsonb_build_object('fg_adjustment_id',h.id,'status',h.status,'row_version',h.row_version);
  return erp._idempotency_complete('reverse_fg_adjustment_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."reverse_fg_adjustment_v2"(p_adjustment_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_fg_movement(p_movement_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  m erp.fg_stock_movements%rowtype;
  v_new uuid;
begin
  perform erp.require_internal();
  select * into m from erp.fg_stock_movements where id=p_movement_id for update;
  if m.id is null then raise exception 'FG movement not found'; end if;
  if m.movement_type='REVERSAL' then raise exception 'Cannot reverse a reversal'; end if;
  if exists (select 1 from erp.fg_stock_movements where reversal_of_id=m.id) then raise exception 'FG movement already reversed'; end if;

  v_new:=erp.post_fg_movement(
    m.product_id,m.lot_id,m.location_id,m.quality_grade,
    'REVERSAL',-m.qty_signed,m.unit_hpp_snapshot,m.customer_id,
    'FG_MOVEMENT_REVERSAL',m.id,clock_timestamp(),p_reason,false
  );
  update erp.fg_stock_movements set reversal_of_id=m.id where id=v_new;
  return v_new;
end;
$function$;

alter function "erp"."reverse_fg_movement"(p_movement_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_journal(p_journal_entry_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_source_type text;
begin
  perform erp.require_internal();
  if nullif(btrim(p_reason),'') is null then raise exception 'Journal reversal reason is required'; end if;
  select source_type into v_source_type
  from erp.journal_entries where id=p_journal_entry_id for update;
  if v_source_type is null then raise exception 'Journal entry not found'; end if;
  if v_source_type in ('ATTENDANCE_HPP_POOL','PAYROLL_ATTENDANCE_ACCRUAL') then
    raise exception 'Protected journal source type % cannot be reversed through generic reverse_journal. Use the owning attendance HPP pool or payroll cancellation/reversal flow.',v_source_type;
  end if;
  return erp._cp3_r4_reverse_journal_internal(p_journal_entry_id,p_reason);
end
$function$;

alter function "erp"."reverse_journal"(p_journal_entry_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_laundry_claim_resolution(p_claim_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  c erp.laundry_claims%rowtype;
  v_journal uuid;
  v_po uuid;
  v_po_status text;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan pembatalan resolusi claim laundry wajib diisi'; end if;

  select * into c from erp.laundry_claims where id=p_claim_id for update;
  if c.id is null then raise exception 'Laundry claim tidak ditemukan'; end if;
  if c.status='REJECTED' then return; end if;
  if c.status not in('SETTLED','WRITTEN_OFF') then raise exception 'Hanya claim yang sudah SETTLED/WRITTEN_OFF yang dapat dibatalkan resolusinya'; end if;

  select je.id into v_journal
  from erp.journal_entries je
  where je.source_type='LAUNDRY_CLAIM_SETTLEMENT' and je.source_id=c.id and je.status='POSTED'
  order by je.posting_at desc,je.id desc limit 1;

  if c.status='SETTLED' and c.compensation_amount>0 and v_journal is null then
    raise exception 'Jurnal settlement claim tidak ditemukan; pembatalan dihentikan agar AP vendor tidak rusak';
  end if;
  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;

  if c.delivery_id is not null and c.claim_type in('MISSING','STUCK') then
    select ld.po_id into v_po from erp.laundry_deliveries ld where ld.id=c.delivery_id;
    if v_po is not null then
      select status into v_po_status from erp.production_orders where id=v_po for update;
      if v_po_status='FINISHED' then
        perform erp.reopen_production_order(v_po,'Laundry claim resolution reversed: '||p_reason);
        update erp.production_orders
        set status='LAUNDRY',current_stage='LAUNDRY',updated_at=now()
        where id=v_po;
      end if;
    end if;
  end if;

  update erp.laundry_claims
  set status='REJECTED',
      notes=concat_ws(E'\n',notes,'Resolution reversed/cancelled: '||p_reason)
  where id=c.id;

  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('laundry_claims',c.id,'REVERSE',jsonb_build_object(
    'previous_status',c.status,
    'new_status','REJECTED',
    'settlement_journal_reversed',v_journal is not null,
    'finished_po_reopened',v_po_status='FINISHED'
  ),erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_laundry_claim_resolution"(p_claim_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_laundry_delivery(p_delivery_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.laundry_deliveries%rowtype;
  r record;
  v_po_status text;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal pengiriman laundry wajib diisi'; end if;

  select * into h from erp.laundry_deliveries where id=p_delivery_id for update;
  if h.id is null then raise exception 'Pengiriman laundry tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status not in ('SENT','PARTIAL_RETURN','RETURNED','CLOSED') then
    raise exception 'Hanya pengiriman laundry yang sudah diposting yang dapat direverse';
  end if;

  select status into v_po_status from erp.production_orders where id=h.po_id for update;
  if v_po_status='FINISHED' then
    raise exception 'PO sudah FINISHED. Jangan reverse pengiriman laundry langsung; koreksi/reopen transaksi downstream terlebih dahulu.';
  end if;

  if exists(select 1 from erp.laundry_receipts where delivery_id=h.id and status<>'REVERSED') then
    raise exception 'Pengiriman laundry ini sudah memiliki penerimaan aktif. Reverse penerimaan laundry terlebih dahulu.';
  end if;
  if exists(select 1 from erp.laundry_claims where delivery_id=h.id and status<>'REJECTED') then
    raise exception 'Pengiriman laundry ini sudah memiliki claim aktif/terselesaikan. Bereskan claim terlebih dahulu sebelum reversal.';
  end if;

  update erp.laundry_deliveries set status='REVERSED',updated_at=now() where id=h.id;

  for r in select distinct cutting_group_id from erp.laundry_delivery_lines where delivery_id=h.id loop
    if exists(
      select 1 from erp.laundry_receipt_lines lrl
      join erp.laundry_receipts lr on lr.id=lrl.receipt_id
      join erp.laundry_delivery_lines ldl on ldl.id=lrl.delivery_line_id
      join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
      where ldl.cutting_group_id=r.cutting_group_id and lr.status='POSTED' and ld.status<>'REVERSED'
    ) then
      update erp.cutting_groups set status='RETURNED' where id=r.cutting_group_id;
    elsif exists(
      select 1 from erp.laundry_delivery_lines ldl join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
      where ldl.cutting_group_id=r.cutting_group_id and ld.status not in('DRAFT','REVERSED')
    ) then
      update erp.cutting_groups set status='LAUNDRY' where id=r.cutting_group_id;
    else
      update erp.cutting_groups
      set status=case when picked_up_at is not null then 'PICKED_UP' else 'CUT' end
      where id=r.cutting_group_id;
    end if;
  end loop;

  if v_po_status not in ('ON_HOLD','CANCELLED') then
    if exists(select 1 from erp.qc_inspections where po_id=h.po_id and status='POSTED')
       or exists(
         select 1 from erp.laundry_receipts lr join erp.laundry_deliveries ld on ld.id=lr.delivery_id
         where ld.po_id=h.po_id and lr.status='POSTED' and ld.status<>'REVERSED'
       ) then
      update erp.production_orders set status='QC',current_stage='QC',updated_at=now() where id=h.po_id;
    elsif exists(select 1 from erp.laundry_deliveries where po_id=h.po_id and status not in('DRAFT','REVERSED')) then
      update erp.production_orders set status='LAUNDRY',current_stage='LAUNDRY',updated_at=now() where id=h.po_id;
    elsif exists(select 1 from erp.cutting_groups where po_id=h.po_id and picked_up_at is not null) then
      update erp.production_orders set status='SEWING',current_stage='SEWING',updated_at=now() where id=h.po_id;
    else
      update erp.production_orders set status='CUTTING',current_stage='CUTTING',updated_at=now() where id=h.po_id;
    end if;
  end if;

  perform erp.sync_laundry_accrual(h.po_id,current_date);
  if exists(select 1 from erp.fg_lots where po_id=h.po_id) then
    perform erp.rebuild_po_hpp(h.po_id,'Laundry delivery reversed: '||p_reason);
    perform erp.propagate_conversion_hpp_for_po(h.po_id);
    perform erp.sync_po_hpp_to_gl(h.po_id,current_date);
  end if;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('laundry_deliveries',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_laundry_delivery"(p_delivery_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_laundry_receipt(p_receipt_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  h erp.laundry_receipts%rowtype;
  d erp.laundry_deliveries%rowtype;
  r record;
  b record;
  v_sent bigint;
  v_returned bigint;
  v_po_status text;
begin
  perform erp.require_owner_admin();
  if nullif(btrim(p_reason),'') is null then raise exception 'Alasan reversal penerimaan laundry wajib diisi'; end if;
  select * into h from erp.laundry_receipts where id=p_receipt_id for update;
  if h.id is null then raise exception 'Penerimaan laundry tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya penerimaan laundry POSTED yang dapat direverse'; end if;
  select * into d from erp.laundry_deliveries where id=h.delivery_id for update;
  if d.id is null or d.status='REVERSED' then raise exception 'Pengiriman laundry sumber tidak aktif'; end if;
  select status into v_po_status from erp.production_orders where id=d.po_id for update;
  if v_po_status='FINISHED' then
    raise exception 'PO sudah FINISHED. Reopen/koreksi transaksi downstream terlebih dahulu sebelum reversal penerimaan laundry.';
  end if;

  perform erp.assert_laundry_receipt_reversal_payroll_safe(h.id);
  if exists(
    select 1 from erp.qc_inspection_items qi
    join erp.qc_inspections qh on qh.id=qi.inspection_id
    where qi.source_laundry_receipt_line_id in(select id from erp.laundry_receipt_lines where receipt_id=h.id)
      and qh.status<>'REVERSED'
  ) then raise exception 'Penerimaan laundry ini sudah dipakai QC. Reverse QC aktif terlebih dahulu.'; end if;
  if exists(
    select 1 from erp.vendor_invoice_items vii join erp.vendor_invoices vi on vi.id=vii.invoice_id
    where vii.receipt_line_id in(select id from erp.laundry_receipt_lines where receipt_id=h.id)
      and vi.status<>'REVERSED'
  ) then raise exception 'Penerimaan laundry ini sudah masuk invoice vendor. Reverse invoice vendor aktif terlebih dahulu.'; end if;
  if exists(
    select 1 from erp.laundry_claims lc
    where (lc.receipt_line_id in(select id from erp.laundry_receipt_lines where receipt_id=h.id) or lc.delivery_id=d.id)
      and lc.status<>'REJECTED'
  ) then raise exception 'Penerimaan/delivery laundry ini sudah memiliki claim aktif/terselesaikan. Bereskan claim terlebih dahulu.'; end if;

  for r in select * from erp.laundry_receipt_lines where receipt_id=h.id and qty_bs_laundry>0
  loop
    for b in
      select * from erp.bs_cases bc
      where bc.source_laundry_receipt_line_id=r.id
         or bc.bs_number='BS-LAU-'||h.receipt_number||'-'||substr(r.id::text,1,8)
      for update
    loop
      if exists(select 1 from erp.rework_orders where bs_case_id=b.id and status<>'CANCELLED')
         or exists(select 1 from erp.bs_resolutions where bs_case_id=b.id) then
        raise exception 'BS dari penerimaan laundry ini sudah diproses/rework. Batalkan downstream BS terlebih dahulu.';
      end if;
      update erp.bs_cases
      set status='CANCELLED',notes=concat_ws(E'\n',notes,'CANCELLED karena source laundry receipt direverse: '||p_reason),updated_at=now()
      where id=b.id;
    end loop;
  end loop;

  update erp.laundry_receipts set status='REVERSED',updated_at=now() where id=h.id;
  select coalesce(sum(qty_sent_pcs),0) into v_sent from erp.laundry_delivery_lines where delivery_id=d.id;
  select coalesce(sum(lrl.qty_good_received+lrl.qty_bs_laundry),0) into v_returned
  from erp.laundry_receipt_lines lrl join erp.laundry_receipts lr on lr.id=lrl.receipt_id
  where lr.delivery_id=d.id and lr.status='POSTED';
  update erp.laundry_deliveries
  set status=case when v_returned>=v_sent and v_sent>0 then 'RETURNED'
                  when v_returned>0 then 'PARTIAL_RETURN' else 'SENT' end,
      updated_at=now()
  where id=d.id;

  for r in
    select distinct ldl.cutting_group_id
    from erp.laundry_receipt_lines lrl
    join erp.laundry_delivery_lines ldl on ldl.id=lrl.delivery_line_id
    where lrl.receipt_id=h.id
  loop
    if exists(
      select 1 from erp.laundry_receipt_lines x
      join erp.laundry_receipts xr on xr.id=x.receipt_id
      join erp.laundry_delivery_lines xdl on xdl.id=x.delivery_line_id
      where xdl.cutting_group_id=r.cutting_group_id and xr.status='POSTED'
    ) then update erp.cutting_groups set status='RETURNED' where id=r.cutting_group_id;
    elsif exists(
      select 1 from erp.laundry_delivery_lines xdl
      join erp.laundry_deliveries xd on xd.id=xdl.delivery_id
      where xdl.cutting_group_id=r.cutting_group_id and xd.status not in('DRAFT','REVERSED')
    ) then update erp.cutting_groups set status='LAUNDRY' where id=r.cutting_group_id;
    else update erp.cutting_groups
      set status=case when picked_up_at is not null then 'PICKED_UP' else 'CUT' end
      where id=r.cutting_group_id;
    end if;
  end loop;

  if v_po_status not in ('ON_HOLD','CANCELLED') then
    if exists(select 1 from erp.qc_inspections where po_id=d.po_id and status='POSTED')
       or exists(select 1 from erp.laundry_receipts lr join erp.laundry_deliveries ld on ld.id=lr.delivery_id
                 where ld.po_id=d.po_id and lr.status='POSTED' and ld.status<>'REVERSED') then
      update erp.production_orders set status='QC',current_stage='QC',updated_at=now() where id=d.po_id;
    elsif exists(select 1 from erp.laundry_deliveries where po_id=d.po_id and status not in('DRAFT','REVERSED')) then
      update erp.production_orders set status='LAUNDRY',current_stage='LAUNDRY',updated_at=now() where id=d.po_id;
    elsif exists(select 1 from erp.cutting_groups where po_id=d.po_id and picked_up_at is not null) then
      update erp.production_orders set status='SEWING',current_stage='SEWING',updated_at=now() where id=d.po_id;
    else update erp.production_orders set status='CUTTING',current_stage='CUTTING',updated_at=now() where id=d.po_id;
    end if;
  end if;

  perform erp.sync_laundry_accrual(d.po_id,current_date);
  if exists(select 1 from erp.fg_lots where po_id=d.po_id) then
    perform erp.rebuild_po_hpp(d.po_id,'Laundry receipt reversed: '||p_reason);
    perform erp.propagate_conversion_hpp_for_po(d.po_id);
    perform erp.sync_po_hpp_to_gl(d.po_id,current_date);
  end if;
  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('laundry_receipts',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_laundry_receipt"(p_receipt_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_material_adjustment(p_adjustment_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare h erp.material_adjustments%rowtype;r record;v_journal uuid;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal adjustment bahan wajib diisi'; end if;
  select * into h from erp.material_adjustments where id=p_adjustment_id for update;
  if h.id is null then raise exception 'Material adjustment tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya material adjustment POSTED yang dapat direverse'; end if;

  for r in
    select msm.id
    from erp.material_stock_movements msm
    join erp.material_adjustment_items mai on mai.id=msm.source_id
    where mai.adjustment_id=h.id and msm.source_type='MATERIAL_ADJUSTMENT_ITEM' and msm.movement_type<>'REVERSAL'
      and not exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=msm.id)
    order by msm.physical_at desc,msm.id desc
  loop perform erp.reverse_material_movement(r.id,p_reason); end loop;

  select id into v_journal from erp.journal_entries where source_type='MATERIAL_ADJUSTMENT' and source_id=h.id and status='POSTED' order by posting_at desc,id desc limit 1;
  if exists(select 1 from erp.material_adjustment_items where adjustment_id=h.id) and v_journal is null
     and exists(select 1 from erp.material_stock_movements msm join erp.material_adjustment_items mai on mai.id=msm.source_id where mai.adjustment_id=h.id and msm.source_type='MATERIAL_ADJUSTMENT_ITEM' and abs(msm.qty_signed*msm.unit_cost_snapshot)>0.005) then
    raise exception 'Jurnal material adjustment tidak ditemukan; reversal dibatalkan agar stok dan pembukuan tidak berbeda';
  end if;
  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;
  update erp.material_adjustments set status='REVERSED',updated_at=now() where id=h.id;
  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('material_adjustments',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;$function$;

alter function "erp"."reverse_material_adjustment"(p_adjustment_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_material_adjustment_v2(p_adjustment_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare v_hash text; v_cached jsonb; v_response jsonb; h erp.material_adjustments%rowtype;
begin
  perform erp.require_owner_admin();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'Reversal reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('id',p_adjustment_id,'reason',btrim(p_reason),'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('reverse_material_adjustment_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  select * into h from erp.material_adjustments where id=p_adjustment_id for update;
  if h.id is null then raise exception 'Material adjustment not found'; end if;
  if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
  perform erp.reverse_material_adjustment(h.id,btrim(p_reason));
  select * into h from erp.material_adjustments where id=h.id;
  v_response:=jsonb_build_object('material_adjustment_id',h.id,'status',h.status,'row_version',h.row_version);
  return erp._idempotency_complete('reverse_material_adjustment_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."reverse_material_adjustment_v2"(p_adjustment_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_material_movement(p_movement_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
DECLARE
  m erp.material_stock_movements%ROWTYPE;
  v_new uuid;
  v_reversal_physical_at timestamptz;
BEGIN
  PERFORM erp.require_internal();
  SELECT * INTO m FROM erp.material_stock_movements WHERE id=p_movement_id FOR UPDATE;
  IF m.id IS NULL THEN RAISE EXCEPTION 'Material movement not found'; END IF;
  IF m.movement_type='REVERSAL' THEN RAISE EXCEPTION 'Cannot reverse a reversal'; END IF;
  IF EXISTS (SELECT 1 FROM erp.material_stock_movements WHERE reversal_of_id=m.id) THEN
    RAISE EXCEPTION 'Material movement already reversed';
  END IF;

  -- A reversal must never sort before the movement it reverses. Using now()
  -- is unsafe because now() is the transaction start timestamp while business
  -- rows may use clock_timestamp() later in the same transaction.
  v_reversal_physical_at := greatest(clock_timestamp(), m.physical_at);

  INSERT INTO erp.material_stock_movements(
    material_id,roll_id,location_id,movement_type,qty_signed,input_unit_cost,
    unit_cost_snapshot,source_type,source_id,physical_at,created_by,reversal_of_id,note
  ) VALUES (
    m.material_id,m.roll_id,m.location_id,'REVERSAL',-m.qty_signed,
    CASE WHEN -m.qty_signed>0 THEN m.unit_cost_snapshot ELSE NULL END,
    m.unit_cost_snapshot,'MATERIAL_MOVEMENT_REVERSAL',m.id,
    v_reversal_physical_at,erp.current_app_user_id(),m.id,p_reason
  ) RETURNING id INTO v_new;

  PERFORM erp.recalculate_material_cost(m.material_id);
  RETURN v_new;
END;
$function$;

alter function "erp"."reverse_material_movement"(p_movement_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_material_purchase(p_purchase_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare h erp.material_purchase_headers%rowtype;v_journal uuid;v_total numeric(24,6);
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal pembelian bahan wajib diisi'; end if;
  select * into h from erp.material_purchase_headers where id=p_purchase_id for update;
  if h.id is null then raise exception 'Pembelian bahan tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya pembelian bahan POSTED yang dapat direverse'; end if;

  if exists(select 1 from erp.supplier_payments where purchase_id=h.id and status='POSTED') then
    raise exception 'Pembelian ini sudah memiliki pembayaran supplier. Reverse pembayaran aktif terlebih dahulu.';
  end if;
  if exists(
    select 1 from erp.material_supplier_return_items ri join erp.material_supplier_returns rh on rh.id=ri.return_id
    join erp.material_purchase_items pi on pi.id=ri.purchase_item_id
    where pi.purchase_id=h.id and rh.status='POSTED'
  ) then raise exception 'Pembelian ini sudah memiliki retur supplier POSTED. Reverse retur terlebih dahulu.'; end if;
  if exists(select 1 from erp.material_purchase_cost_corrections where purchase_id=h.id and status='POSTED') then
    raise exception 'Pembelian ini sudah memiliki koreksi harga POSTED. Reverse koreksi harga terlebih dahulu.';
  end if;

  select coalesce(sum(line_total),0) into v_total from erp.material_purchase_items where purchase_id=h.id;
  select id into v_journal from erp.journal_entries where source_type='MATERIAL_PURCHASE' and source_id=h.id and status='POSTED' order by posting_at desc,id desc limit 1;
  if v_total>0.005 and v_journal is null then raise exception 'Jurnal pembelian bahan tidak ditemukan; reversal dibatalkan agar stok/AP tidak rusak'; end if;

  -- Exact source-time cancellation. Recalculation will reject the whole transaction if
  -- removing this purchase would make historical material/roll stock negative.
  perform erp._reverse_material_purchase_stock_at_source_time(h.id,p_reason);
  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;
  update erp.material_purchase_headers set status='REVERSED',payment_status='UNPAID',updated_at=now() where id=h.id;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('material_purchase_headers',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_material_purchase"(p_purchase_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_material_purchase_cost_correction(p_correction_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.material_purchase_cost_corrections%rowtype;
  p erp.material_purchase_headers%rowtype;
  r record;
  m uuid;
  v_journal uuid;
  v_current_payable numeric(24,6);
  v_delta numeric(24,6);
  v_projected numeric(24,6);
  v_paid numeric(24,6);
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal koreksi harga pembelian wajib diisi'; end if;
  select * into h from erp.material_purchase_cost_corrections where id=p_correction_id for update;
  if h.id is null then raise exception 'Koreksi harga pembelian tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya koreksi harga pembelian POSTED yang dapat direverse'; end if;
  if h.post_seq is null then raise exception 'Urutan posting koreksi harga pembelian tidak ditemukan; reversal dibatalkan'; end if;
  select * into p from erp.material_purchase_headers where id=h.purchase_id for update;
  if p.id is null or p.status<>'POSTED' then raise exception 'Pembelian sumber harus masih POSTED'; end if;

  if exists(
    select 1
    from erp.material_purchase_cost_correction_items ci
    join erp.material_purchase_cost_correction_items ci2 on ci2.purchase_item_id=ci.purchase_item_id
    join erp.material_purchase_cost_corrections c2 on c2.id=ci2.correction_id
    where ci.correction_id=h.id and c2.status='POSTED' and c2.id<>h.id
      and c2.post_seq>h.post_seq
  ) then
    raise exception 'Ada koreksi harga yang lebih baru pada item pembelian ini. Reverse koreksi terbaru terlebih dahulu.';
  end if;

  select erp.material_purchase_payable_total(p.id) into v_current_payable;
  select coalesce(sum(delta_amount),0) into v_delta
  from erp.material_purchase_cost_correction_items where correction_id=h.id;
  v_projected:=v_current_payable-v_delta;
  select coalesce(sum(amount),0) into v_paid from erp.supplier_payments where purchase_id=p.id and status='POSTED';
  if v_paid>v_projected+0.01 then
    raise exception 'Reversal koreksi harga membuat pembayaran supplier melebihi hutang tersisa. Reverse/koreksi pembayaran supplier terlebih dahulu.';
  end if;

  for r in
    select ci.*,mpi.material_id
    from erp.material_purchase_cost_correction_items ci
    join erp.material_purchase_items mpi on mpi.id=ci.purchase_item_id
    where ci.correction_id=h.id order by ci.id
  loop
    if r.old_unit_cost_snapshot is null then
      raise exception 'Snapshot harga sebelum koreksi tidak ditemukan untuk item %; reversal dibatalkan',r.purchase_item_id;
    end if;
    update erp.material_stock_movements msm
    set input_unit_cost=r.old_unit_cost_snapshot
    where msm.movement_type='PURCHASE' and msm.qty_signed>0 and (
      (msm.source_type='MATERIAL_PURCHASE_ITEM' and msm.source_id=r.purchase_item_id)
      or (msm.source_type='MATERIAL_PURCHASE_ROLL' and msm.source_id in (select mr.id from erp.material_rolls mr where mr.purchase_item_id=r.purchase_item_id))
    );
  end loop;

  update erp.material_purchase_cost_corrections set status='REVERSED' where id=h.id;
  for m in
    select distinct mpi.material_id from erp.material_purchase_cost_correction_items ci
    join erp.material_purchase_items mpi on mpi.id=ci.purchase_item_id where ci.correction_id=h.id
  loop
    perform erp.recalculate_material_cost(m,p.physical_at);
  end loop;

  select id into v_journal from erp.journal_entries
  where source_type='MATERIAL_PURCHASE_COST_CORRECTION' and source_id=h.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if abs(v_delta)>0.005 and v_journal is null then
    raise exception 'Jurnal koreksi harga pembelian tidak ditemukan; reversal dibatalkan agar inventory/AP tidak rusak';
  end if;
  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;

  select erp.material_purchase_payable_total(p.id) into v_projected;
  select coalesce(sum(amount),0) into v_paid from erp.supplier_payments where purchase_id=p.id and status='POSTED';
  update erp.material_purchase_headers set payment_status=case when v_paid>=v_projected-0.01 then 'PAID' when v_paid>0 then 'PARTIAL' else 'UNPAID' end where id=p.id;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('material_purchase_cost_corrections',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_material_purchase_cost_correction"(p_correction_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_material_supplier_invoice(p_invoice_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  h erp.material_supplier_invoices%rowtype;
  r record;
  v_purchase uuid;
  v_current_ap numeric;
  v_invoice_ap numeric;
  v_paid numeric;
  v_journal uuid;
  v_latest record;
begin
  perform erp.require_owner_admin();
  if nullif(btrim(p_reason),'') is null then raise exception 'Supplier invoice reversal reason is required'; end if;
  select * into h from erp.material_supplier_invoices where id=p_invoice_id for update;
  if h.id is null then raise exception 'Material supplier invoice not found'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Only a POSTED supplier invoice may be reversed'; end if;

  if exists(
    select 1
    from erp.material_supplier_invoice_lines l
    join erp.material_supplier_return_items ri on ri.purchase_item_id=l.purchase_item_id
    join erp.material_supplier_returns rh on rh.id=ri.return_id
    where l.invoice_id=h.id and rh.status='POSTED'
      and coalesce(ri.ap_relief_qty_snapshot,0)>0
  ) then
    raise exception 'Reverse AP-backed supplier returns before reversing this invoice';
  end if;

  for v_purchase in
    select distinct i.purchase_id
    from erp.material_supplier_invoice_lines l
    join erp.material_purchase_items i on i.id=l.purchase_item_id
    where l.invoice_id=h.id order by i.purchase_id
  loop
    perform 1 from erp.material_purchase_headers where id=v_purchase for update;
    select erp.material_purchase_final_ap_total(v_purchase),
           coalesce(sum(l.net_amount),0),
           coalesce((select sum(amount) from erp.supplier_payments where purchase_id=v_purchase and status='POSTED'),0)
    into v_current_ap,v_invoice_ap,v_paid
    from erp.material_supplier_invoice_lines l
    join erp.material_purchase_items i on i.id=l.purchase_item_id
    where l.invoice_id=h.id and i.purchase_id=v_purchase;
    if v_paid>v_current_ap-v_invoice_ap+0.01 then
      raise exception 'Reverse supplier payments first: payment % would exceed projected final AP %',
        v_paid,v_current_ap-v_invoice_ap;
    end if;
  end loop;

  select id into v_journal from erp.journal_entries
  where source_type='MATERIAL_SUPPLIER_INVOICE' and source_id=h.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if exists(
    select 1 from erp.material_supplier_invoice_lines
    where invoice_id=h.id and(
      coalesce(grni_clear_amount_snapshot,0)<>0
      or coalesce(ap_create_amount_snapshot,0)<>0
      or coalesce(inventory_revaluation_snapshot,0)<>0
    )
  ) and v_journal is null then
    raise exception 'Supplier invoice journal is missing; reversal aborted to protect AP/GRNI/HPP';
  end if;

  update erp.material_supplier_invoices
  set status='REVERSED',reversed_at=clock_timestamp(),reversal_reason=btrim(p_reason)
  where id=h.id;
  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;

  for r in
    select distinct l.purchase_item_id
    from erp.material_supplier_invoice_lines l
    where l.invoice_id=h.id order by l.purchase_item_id
  loop
    perform erp.refresh_material_purchase_item_cost(r.purchase_item_id);
    perform erp.refresh_material_purchase_item_match_state(r.purchase_item_id);
  end loop;

  for v_purchase in
    select distinct i.purchase_id
    from erp.material_supplier_invoice_lines l
    join erp.material_purchase_items i on i.id=l.purchase_item_id
    where l.invoice_id=h.id order by i.purchase_id
  loop
    select ih.invoice_number,ih.due_date into v_latest
    from erp.material_supplier_invoices ih
    join erp.material_supplier_invoice_lines il on il.invoice_id=ih.id
    join erp.material_purchase_items pi on pi.id=il.purchase_item_id
    where pi.purchase_id=v_purchase and ih.status='POSTED'
    order by ih.posted_at desc,ih.id desc limit 1;
    select erp.material_purchase_final_ap_total(v_purchase),
           coalesce((select sum(amount) from erp.supplier_payments where purchase_id=v_purchase and status='POSTED'),0)
    into v_current_ap,v_paid;
    update erp.material_purchase_headers
    set supplier_invoice_number=v_latest.invoice_number,
        due_date=v_latest.due_date,
        payment_status=case when v_paid>=v_current_ap-0.01 then 'PAID' when v_paid>0 then 'PARTIAL' else 'UNPAID' end
    where id=v_purchase;
  end loop;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('material_supplier_invoices',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_material_supplier_invoice"(p_invoice_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_material_supplier_invoice_v2(p_invoice_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare v_hash text;v_cached jsonb;v_response jsonb;h erp.material_supplier_invoices%rowtype;
begin
  perform erp.require_owner_admin();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'reversal reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('invoice_id',p_invoice_id,'expected_version',p_expected_version,'reason',btrim(p_reason)));
  v_cached:=erp._idempotency_begin('reverse_material_supplier_invoice_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  select * into h from erp.material_supplier_invoices where id=p_invoice_id for update;
  if h.id is null then raise exception 'Supplier invoice not found'; end if;
  if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
  perform erp.reverse_material_supplier_invoice(h.id,p_reason);
  select * into h from erp.material_supplier_invoices where id=h.id;
  v_response:=jsonb_build_object(
    'supplier_invoice_id',h.id,'invoice_number',h.invoice_number,'status',h.status,
    'row_version',h.row_version
  );
  return erp._idempotency_complete('reverse_material_supplier_invoice_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."reverse_material_supplier_invoice_v2"(p_invoice_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_material_supplier_return(p_return_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  h erp.material_supplier_returns%rowtype;
  r record;
  v_journal uuid;
  v_purchase uuid;
  v_payable numeric;
  v_paid numeric;
  v_roll_qty numeric;
  v_cost numeric;
begin
  perform erp.require_owner_admin();
  if nullif(btrim(p_reason),'') is null then raise exception 'Alasan reversal retur supplier wajib diisi'; end if;
  select * into h from erp.material_supplier_returns where id=p_return_id for update;
  if h.id is null then raise exception 'Retur supplier tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya retur supplier POSTED yang dapat direverse'; end if;

  perform erp.lock_supplier_return_source_purchases(h.id);
  select id into v_journal from erp.journal_entries
  where source_type='MATERIAL_SUPPLIER_RETURN' and source_id=h.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if exists(
    select 1 from erp.material_supplier_return_items
    where return_id=h.id and(
      coalesce(ap_relief_amount_snapshot,0)<>0
      or coalesce(grni_relief_amount_snapshot,0)<>0
    )
  ) and v_journal is null then
    raise exception 'Jurnal retur supplier tidak ditemukan; reversal dibatalkan agar stok/AP/GRNI tidak rusak';
  end if;

  update erp.material_supplier_returns set status='REVERSED',updated_at=now() where id=h.id;

  -- Recalculate the purchase source input before reverse_material_movement runs,
  -- so its single chronological replay sees the restored GRNI cost-basis.
  for r in
    select distinct ri.purchase_item_id,i.material_id
    from erp.material_supplier_return_items ri
    join erp.material_purchase_items i on i.id=ri.purchase_item_id
    where ri.return_id=h.id order by ri.purchase_item_id
  loop
    v_cost:=erp.material_purchase_current_unit_cost(r.purchase_item_id);
    update erp.material_stock_movements msm
    set input_unit_cost=v_cost
    where msm.movement_type='PURCHASE' and msm.qty_signed>0 and(
      (msm.source_type='MATERIAL_PURCHASE_ITEM' and msm.source_id=r.purchase_item_id)
      or
      (msm.source_type='MATERIAL_PURCHASE_ROLL' and msm.source_id in(
        select mr.id from erp.material_rolls mr where mr.purchase_item_id=r.purchase_item_id
      ))
    );
  end loop;

  for r in
    select msm.id,ri.roll_id,ri.purchase_item_id
    from erp.material_stock_movements msm
    join erp.material_supplier_return_items ri on ri.id=msm.source_id
    where ri.return_id=h.id
      and msm.source_type='MATERIAL_SUPPLIER_RETURN_ITEM'
      and msm.movement_type='SUPPLIER_RETURN'
      and not exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=msm.id)
    order by msm.physical_at desc,msm.id desc
  loop
    perform erp.reverse_material_movement(r.id,p_reason);
    perform erp.refresh_material_purchase_item_match_state(r.purchase_item_id);
    if r.roll_id is not null then
      select coalesce(sum(qty_signed),0) into v_roll_qty
      from erp.material_stock_movements where roll_id=r.roll_id;
      update erp.material_rolls
      set cached_qty=v_roll_qty,
          status=case when v_roll_qty<=0 then 'EXHAUSTED'
                      when v_roll_qty<original_qty then 'HALF_USED' else 'AVAILABLE' end,
          updated_at=now()
      where id=r.roll_id;
    end if;
  end loop;

  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;
  for v_purchase in
    select distinct i.purchase_id
    from erp.material_supplier_return_items ri
    join erp.material_purchase_items i on i.id=ri.purchase_item_id
    where ri.return_id=h.id order by i.purchase_id
  loop
    select erp.material_purchase_final_ap_total(v_purchase),
           coalesce((select sum(amount) from erp.supplier_payments where purchase_id=v_purchase and status='POSTED'),0)
    into v_payable,v_paid;
    update erp.material_purchase_headers
    set payment_status=case when v_paid>=v_payable-0.01 then 'PAID' when v_paid>0 then 'PARTIAL' else 'UNPAID' end
    where id=v_purchase;
  end loop;
  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('material_supplier_returns',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_material_supplier_return"(p_return_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_material_supplier_return_v2(p_return_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare v_hash text;v_cached jsonb;v_response jsonb;h erp.material_supplier_returns%rowtype;
begin
  perform erp.require_owner_admin();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'Reversal reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('id',p_return_id,'reason',btrim(p_reason),'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('reverse_material_supplier_return_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',btrim(p_reason),true);
  select * into h from erp.material_supplier_returns where id=p_return_id for update;
  if h.id is null then raise exception 'Supplier return not found'; end if;
  if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
  perform erp.reverse_material_supplier_return(h.id,btrim(p_reason));
  select * into h from erp.material_supplier_returns where id=h.id;
  v_response:=jsonb_build_object('material_supplier_return_id',h.id,'status',h.status,'row_version',h.row_version);
  return erp._idempotency_complete('reverse_material_supplier_return_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."reverse_material_supplier_return_v2"(p_return_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_material_transfer_v2(p_transfer_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_header erp.material_transfers%rowtype;
  r record;
begin
  perform erp.require_owner_admin();
  if p_expected_version is null then raise exception 'expected_version is required'; end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'Reversal reason is required'; end if;
  v_hash := erp._request_hash(jsonb_build_object(
    'transfer_id', p_transfer_id, 'reason', btrim(p_reason),
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(
    'reverse_material_transfer_v2', p_client_request_id, v_hash
  );
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason', btrim(p_reason), true);

  select * into v_header
  from erp.material_transfers where id = p_transfer_id for update;
  if v_header.id is null then raise exception 'Material transfer not found'; end if;
  if v_header.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_header.row_version;
  end if;
  if v_header.status <> 'POSTED' then raise exception 'Only POSTED transfer can be reversed'; end if;
  if exists (
    select 1
    from erp.material_stock_movements original
    join erp.material_stock_movements rv on rv.reversal_of_id = original.id
    where original.source_type = 'MATERIAL_TRANSFER'
      and original.source_id = v_header.id
  ) then raise exception 'Material transfer already has reversal movements'; end if;

  -- Reverse destination IN first so the normal negative-stock guard proves the
  -- destination still owns the quantity. Only then restore the source OUT.
  for r in
    select original.*
    from erp.material_stock_movements original
    where original.source_type = 'MATERIAL_TRANSFER'
      and original.source_id = v_header.id
    order by case original.movement_type when 'TRANSFER_IN' then 0 else 1 end,
             original.system_created_at, original.id
  loop
    insert into erp.material_stock_movements(
      material_id, roll_id, location_id, movement_type, qty_signed,
      input_unit_cost, source_type, source_id, physical_at, created_by,
      reversal_of_id, note
    ) values (
      r.material_id, r.roll_id, r.location_id, 'REVERSAL', -r.qty_signed,
      r.unit_cost_snapshot, 'MATERIAL_TRANSFER_REVERSAL', v_header.id,
      greatest(clock_timestamp(), r.physical_at), erp.current_app_user_id(),
      r.id, btrim(p_reason)
    );
  end loop;

  for r in
    select distinct material_id
    from erp.material_transfer_items where transfer_id = v_header.id
  loop
    perform erp.recalculate_material_cost(r.material_id);
  end loop;

  update erp.material_transfers
  set status = 'REVERSED', reversed_at = clock_timestamp(),
      reversal_reason = btrim(p_reason)
  where id = v_header.id
  returning * into v_header;

  v_response := jsonb_build_object(
    'material_transfer_id', v_header.id,
    'status', v_header.status,
    'row_version', v_header.row_version,
    'reversed_at', v_header.reversed_at,
    'reversal_movement_count', (
      select count(*)
      from erp.material_stock_movements m
      where m.source_type = 'MATERIAL_TRANSFER_REVERSAL'
        and m.source_id = v_header.id
    )
  );
  return erp._idempotency_complete(
    'reverse_material_transfer_v2', p_client_request_id, v_response
  );
end;
$function$;

alter function "erp"."reverse_material_transfer_v2"(p_transfer_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_misc_finance(p_transaction_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  t erp.misc_finance_transactions%rowtype;
  v_journal uuid;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal pendapatan/pengeluaran lain-lain wajib diisi'; end if;

  select * into t from erp.misc_finance_transactions where id=p_transaction_id for update;
  if t.id is null then raise exception 'Transaksi pendapatan/pengeluaran lain-lain tidak ditemukan'; end if;
  if t.status='REVERSED' then return; end if;
  if t.status<>'POSTED' then raise exception 'Hanya transaksi lain-lain yang sudah POSTED yang dapat direverse'; end if;

  select id into v_journal
  from erp.journal_entries
  where source_type='MISC_FINANCE' and source_id=t.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if v_journal is null then raise exception 'Jurnal transaksi lain-lain tidak ditemukan; reversal dibatalkan agar kas tidak rusak'; end if;

  perform erp.reverse_journal(v_journal,p_reason);
  update erp.misc_finance_transactions set status='REVERSED',updated_at=now() where id=t.id;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values ('misc_finance_transactions',t.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_misc_finance"(p_transaction_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_opening_financial_correction(p_correction_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare c erp.opening_financial_corrections%rowtype;i erp.opening_balance_items%rowtype;b erp.opening_subledger_balances%rowtype;v_journal uuid;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal koreksi saldo awal wajib diisi'; end if;
  select * into c from erp.opening_financial_corrections where id=p_correction_id for update;
  if c.id is null then raise exception 'Koreksi saldo awal tidak ditemukan'; end if;
  if c.status='REVERSED' then return; end if;
  if exists(select 1 from erp.opening_financial_corrections x where x.opening_item_id=c.opening_item_id and x.status='POSTED' and x.id<>c.id and x.correction_seq>c.correction_seq) then
    raise exception 'Ada koreksi saldo awal yang lebih baru. Reverse koreksi terbaru terlebih dahulu.';
  end if;
  select * into i from erp.opening_balance_items where id=c.opening_item_id for update;
  if i.balance_type in ('CONTRACTOR_RECEIVABLE','CONTRACTOR_PAYABLE','VENDOR_PAYABLE','SUPPLIER_PAYABLE','CUSTOMER_RECEIVABLE') then
    select * into b from erp.opening_subledger_balances where opening_item_id=i.id for update;
    if b.settled_amount>c.previous_amount_snapshot+0.01 then
      raise exception 'Reversal koreksi akan menurunkan saldo awal ke %, tetapi sudah disettle %. Reverse settlement terkait terlebih dahulu.',c.previous_amount_snapshot,b.settled_amount;
    end if;
  end if;
  select id into v_journal from erp.journal_entries where source_type='OPENING_FINANCIAL_CORRECTION' and source_id=c.id and status='POSTED' order by posting_at desc,id desc limit 1;
  if v_journal is null then raise exception 'Jurnal koreksi saldo awal tidak ditemukan'; end if;
  perform erp.reverse_journal(v_journal,p_reason);
  if b.id is not null then
    update erp.opening_subledger_balances set original_amount=c.previous_amount_snapshot,
      status=case when settled_amount>=c.previous_amount_snapshot-0.01 then 'SETTLED' when settled_amount>0 then 'PARTIAL' else 'OPEN' end,
      updated_at=now() where id=b.id;
  end if;
  update erp.opening_financial_corrections set status='REVERSED',reversed_at=clock_timestamp(),reversal_reason=p_reason where id=c.id;
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('opening_balance_items',i.id,'REVERSE',jsonb_build_object('correction_id',c.id,'restored_amount',c.previous_amount_snapshot,'correction_type','OPENING_FINANCIAL_CORRECTION'),erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_opening_financial_correction"(p_correction_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_opening_hpp_correction(p_correction_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  c erp.opening_hpp_corrections%rowtype;
  l erp.fg_lots%rowtype;
  v_current_id uuid;
  v_current_hpp numeric(20,6);
  v_ver integer;
  v_new_id uuid;
  v_descends boolean;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal koreksi HPP opening wajib diisi'; end if;
  select * into c from erp.opening_hpp_corrections where id=p_correction_id for update;
  if c.id is null then raise exception 'Koreksi HPP opening tidak ditemukan'; end if;
  if c.status='REVERSED' then return; end if;

  if exists(
    select 1
    from erp.opening_hpp_corrections x
    join erp.hpp_versions hx on hx.id=x.hpp_version_id
    join erp.hpp_versions hc on hc.id=c.hpp_version_id
    where x.lot_id=c.lot_id and x.status='POSTED' and x.id<>c.id
      and hx.version_no>hc.version_no
  ) then
    raise exception 'Ada koreksi HPP opening yang lebih baru. Reverse yang terbaru dulu.';
  end if;

  select * into l from erp.fg_lots where id=c.lot_id for update;
  if exists(
    select 1
    from erp.product_conversion_allocations pca
    join erp.product_conversions pc on pc.id=pca.conversion_id
    where pca.source_lot_id=l.id and pc.status='POSTED'
      and pca.original_hpp_per_pcs is distinct from c.previous_hpp_snapshot
  ) then
    raise exception 'Lot sudah dipakai conversion dengan HPP hasil koreksi. Reverse/correct conversion dulu sebelum reversal HPP.';
  end if;

  select hpp_version_id,hpp_per_pcs into v_current_id,v_current_hpp
  from erp.v_current_hpp where lot_id=l.id;
  if v_current_id is null then raise exception 'Current HPP lot opening tidak ditemukan'; end if;

  if v_current_id is distinct from c.hpp_version_id then
    with recursive chain as (
      select h.id,h.supersedes_id from erp.hpp_versions h where h.id=v_current_id
      union all
      select h.id,h.supersedes_id
      from erp.hpp_versions h
      join chain x on h.id=x.supersedes_id
    )
    select exists(select 1 from chain where id=c.hpp_version_id) into v_descends;

    if not coalesce(v_descends,false) or abs(v_current_hpp-c.corrected_hpp)>0.000001 then
      raise exception 'Current HPP version tidak lagi konsisten dengan correction ini';
    end if;
  end if;

  select coalesce(max(version_no),0)+1 into v_ver from erp.hpp_versions where lot_id=l.id;
  update erp.hpp_versions set is_current=false where lot_id=l.id and is_current=true;
  insert into erp.hpp_versions(lot_id,version_no,cost_state,qty_basis_pcs,total_cost,is_current,supersedes_id,calculation_reason,created_by)
  values(l.id,v_ver,'ADJUSTED',l.initial_qty_pcs,l.initial_qty_pcs*c.previous_hpp_snapshot,true,v_current_id,'Reversal opening HPP correction: '||p_reason,erp.current_app_user_id())
  returning id into v_new_id;

  update erp.opening_hpp_corrections
  set status='REVERSED',reversed_at=now(),reversal_reason=p_reason
  where id=c.id;
  perform erp.sync_opening_lot_hpp_to_gl(l.id,current_date);
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('fg_lots',l.id,'REVERSE',jsonb_build_object('correction_id',c.id,'restored_hpp',c.previous_hpp_snapshot),erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_opening_hpp_correction"(p_correction_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_opening_subledger_settlement(p_settlement_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
DECLARE s erp.opening_subledger_settlements%ROWTYPE;b erp.opening_subledger_balances%ROWTYPE;v_journal uuid;
BEGIN PERFORM erp.require_owner_admin();SELECT * INTO s FROM erp.opening_subledger_settlements WHERE id=p_settlement_id FOR UPDATE;IF s.id IS NULL OR s.status<>'POSTED' THEN RAISE EXCEPTION 'Only POSTED opening settlement can be reversed';END IF;SELECT * INTO b FROM erp.opening_subledger_balances WHERE id=s.balance_id FOR UPDATE;SELECT id INTO v_journal FROM erp.journal_entries WHERE source_type='OPENING_SUBLEDGER_SETTLEMENT' AND source_id=s.id AND status='POSTED' ORDER BY posting_at DESC LIMIT 1;IF v_journal IS NULL THEN RAISE EXCEPTION 'Opening settlement journal not found';END IF;PERFORM erp.reverse_journal(v_journal,COALESCE(NULLIF(trim(p_reason),''),'Opening settlement reversal'));UPDATE erp.opening_subledger_settlements SET status='REVERSED',updated_at=now() WHERE id=s.id;UPDATE erp.opening_subledger_balances SET settled_amount=GREATEST(settled_amount-s.amount,0),status=CASE WHEN GREATEST(settled_amount-s.amount,0)<=0.01 THEN 'OPEN' WHEN GREATEST(settled_amount-s.amount,0)>=original_amount-0.01 THEN 'SETTLED' ELSE 'PARTIAL' END,updated_at=now() WHERE id=b.id;END;$function$;

alter function "erp"."reverse_opening_subledger_settlement"(p_settlement_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_paid_payroll(p_payroll_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.payroll_settlements%rowtype;
  r record;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Payroll reversal reason is required'; end if;
  select * into p from erp.payroll_settlements where id=p_payroll_id for update;
  if p.id is null then raise exception 'Payroll not found'; end if;
  if p.status='REVERSED' then return; end if;
  if p.status<>'PAID' then raise exception 'Only PAID payroll uses reverse_paid_payroll; unpaid payroll uses cancel_unpaid_payroll'; end if;
  perform erp._cp3_lock_business_period(p.period_start,p.period_end);
  if exists(
    select 1 from erp.attendance_hpp_pool_sources s
    join erp.attendance_hpp_pools hp on hp.id=s.pool_id
    where s.payroll_id=p.id and hp.status='ACTIVE'
  ) then
    raise exception 'PAYROLL_CONSUMED_BY_ACTIVE_HPP_POOL: cancel the active attendance HPP pool first';
  end if;

  for r in
    select je.id from erp.journal_entries je
    where je.source_id=p.id
      and je.source_type in ('PAYROLL_ATTENDANCE_ACCRUAL','PAYROLL_EXTRA_ACCRUAL','PAYROLL_MANUAL_REDUCTION',
                             'PAYROLL_MATERIAL_DEDUCTION','PAYROLL_OTHER_DEDUCTION','PAYROLL_PAYMENT')
      and je.status='POSTED'
    order by je.posting_at desc,je.id desc
  loop perform erp._cp3_r4_reverse_journal_internal(r.id,p_reason); end loop;

  update erp.payroll_settlements set status='REVERSED',settled_at=null,updated_at=now() where id=p.id;
  for r in select distinct pd.contractor_issue_item_id id from erp.payroll_deductions pd
           where pd.payroll_id=p.id and pd.contractor_issue_item_id is not null
  loop perform erp.refresh_contractor_issue_payroll_status(r.id); end loop;
  for r in select distinct pr.source_id id from erp.payroll_reimbursements pr
           where pr.payroll_id=p.id and pr.source_type='ACCESSORY_BOM' and pr.source_id is not null
  loop
    update erp.contractor_accessory_reimbursement_entitlements e
    set payroll_status=case
      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id
                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status='PAID') then 'SETTLED'
      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id
                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status<>'REVERSED') then 'ALLOCATED'
      else 'UNALLOCATED' end
    where e.id=r.id;
  end loop;
  for r in
    select distinct bc.id as bs_case_id from erp.bs_cases bc
    where exists(select 1 from erp.payroll_work_items pwi where pwi.payroll_id=p.id and pwi.po_id=bc.po_id)
       or exists(select 1 from erp.payroll_work_items pwi join erp.rework_component_lines rcl on rcl.id=pwi.source_id
                 join erp.bs_case_components bcc on bcc.id=rcl.bs_case_component_id
                 where pwi.payroll_id=p.id and bcc.bs_case_id=bc.id)
  loop perform erp.rebuild_bs_component_counters(r.bs_case_id); end loop;
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('payroll_settlements',p.id,'REVERSE_PAID',jsonb_build_object('previous_status','PAID'),erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_paid_payroll"(p_payroll_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_product_conversion(p_conversion_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.product_conversions%rowtype;
  r record;
  v_journal uuid;
  v_expected numeric(24,6);
  v_po uuid;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal conversion/rebrand wajib diisi'; end if;
  select * into h from erp.product_conversions where id=p_conversion_id for update;
  if h.id is null then raise exception 'Conversion/rebrand tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya conversion/rebrand POSTED yang dapat direverse'; end if;

  if exists(
    select 1
    from erp.product_conversion_allocations a
    where a.conversion_id=h.id
      and erp.fg_lot_has_active_downstream(a.destination_lot_id,'REBRAND_IN','PRODUCT_CONVERSION',h.id)
  ) then raise exception 'Hasil conversion/rebrand masih dipakai transaksi downstream aktif. Reverse transaksi downstream terlebih dahulu.'; end if;

  select coalesce(sum(a.qty_pcs*a.original_hpp_per_pcs),0) into v_expected from erp.product_conversion_allocations a where a.conversion_id=h.id;
  select id into v_journal from erp.journal_entries where source_type='PRODUCT_CONVERSION' and source_id=h.id and status='POSTED' order by posting_at desc,id desc limit 1;
  if v_expected>0.005 and v_journal is null then raise exception 'Jurnal conversion/rebrand tidak ditemukan; reversal dibatalkan agar nilai persediaan tidak rusak'; end if;

  for r in
    select fm.id from erp.fg_stock_movements fm
    join erp.product_conversion_allocations a on a.destination_lot_id=fm.lot_id
    where a.conversion_id=h.id and fm.movement_type='REBRAND_IN' and fm.source_type='PRODUCT_CONVERSION' and fm.source_id=h.id
      and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=fm.id)
    order by fm.physical_at desc,fm.id desc
  loop perform erp.reverse_fg_movement(r.id,p_reason); end loop;

  for r in
    select fm.id from erp.fg_stock_movements fm
    join erp.product_conversion_allocations a on a.source_lot_id=fm.lot_id
    where a.conversion_id=h.id and fm.movement_type='REBRAND_OUT' and fm.source_type='PRODUCT_CONVERSION' and fm.source_id=h.id
      and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=fm.id)
    order by fm.physical_at desc,fm.id desc
  loop perform erp.reverse_fg_movement(r.id,p_reason); end loop;

  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;
  update erp.product_conversions set status='REVERSED' where id=h.id;

  for v_po in
    select distinct fl.po_id from erp.product_conversion_allocations a join erp.fg_lots fl on fl.id=a.source_lot_id where a.conversion_id=h.id and fl.po_id is not null
  loop perform erp.sync_po_hpp_to_gl(v_po,current_date); end loop;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason) values('product_conversions',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_product_conversion"(p_conversion_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_qc(p_qc_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.qc_inspections%rowtype;
  r record; l record; b record;
  v_journal uuid;
  v_po_status text;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal QC wajib diisi'; end if;
  select * into h from erp.qc_inspections where id=p_qc_id for update;
  if h.id is null then raise exception 'QC tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya QC POSTED yang dapat direverse'; end if;
  select status into v_po_status from erp.production_orders where id=h.po_id for update;
  if v_po_status='FINISHED' then raise exception 'PO sudah FINISHED. Reopen/koreksi downstream terlebih dahulu sebelum reversal QC.'; end if;

  for b in select bc.* from erp.bs_cases bc where bc.qc_item_id in (select id from erp.qc_inspection_items where inspection_id=h.id) and bc.status<>'CANCELLED' for update loop
    if exists(select 1 from erp.rework_orders where bs_case_id=b.id and status<>'CANCELLED')
       or exists(select 1 from erp.bs_resolutions where bs_case_id=b.id) then
      raise exception 'BS hasil QC ini sudah diproses/rework. Batalkan downstream BS terlebih dahulu.';
    end if;
  end loop;

  for l in
    select fl.* from erp.fg_lots fl
    where fl.qc_item_id in (select id from erp.qc_inspection_items where inspection_id=h.id)
      and fl.lot_origin='PRODUCTION'
    for update
  loop
    if erp.fg_lot_has_active_downstream(l.id,'QC_GOOD','QC_ITEM',l.qc_item_id) then
      raise exception 'FG hasil QC masih dipakai transaksi downstream aktif. Reverse transaksi downstream terlebih dahulu.';
    end if;
    if exists(select 1 from erp.contractor_accessory_reimbursement_entitlements e where e.lot_id=l.id and e.payroll_status<>'UNALLOCATED') then
      raise exception 'Hak reimbursement aksesori dari QC ini sudah masuk payroll. Cancel/reverse payroll terlebih dahulu.';
    end if;
  end loop;

  for l in
    select fl.* from erp.fg_lots fl
    where fl.qc_item_id in (select id from erp.qc_inspection_items where inspection_id=h.id) and fl.lot_origin='PRODUCTION'
    for update
  loop
    select id into v_journal from erp.journal_entries
    where source_type='ACCESSORY_REIMBURSE_ACCRUAL' and source_id=l.id and status='POSTED'
    order by posting_at desc,id desc limit 1;
    if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;
    update erp.contractor_accessory_reimbursement_entitlements set payroll_status='CANCELLED' where lot_id=l.id and payroll_status='UNALLOCATED';
    for r in select fm.id from erp.fg_stock_movements fm where fm.lot_id=l.id and fm.movement_type='QC_GOOD' and fm.source_type='QC_ITEM' and fm.source_id=l.qc_item_id and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=fm.id) loop
      perform erp.reverse_fg_movement(r.id,p_reason);
    end loop;
    update erp.fg_lots set lot_origin='VOIDED_PRODUCTION',is_open=false where id=l.id;
  end loop;

  update erp.bs_cases set status='CANCELLED',notes=concat_ws(E'\n',notes,'CANCELLED karena source QC direverse: '||p_reason),updated_at=now()
  where qc_item_id in (select id from erp.qc_inspection_items where inspection_id=h.id) and status<>'CANCELLED';
  update erp.qc_inspections set status='REVERSED',updated_at=now() where id=h.id;

  if v_po_status not in ('ON_HOLD','CANCELLED') then
    if exists(select 1 from erp.qc_inspections where po_id=h.po_id and status='POSTED')
       or exists(select 1 from erp.laundry_receipts lr join erp.laundry_deliveries ld on ld.id=lr.delivery_id where ld.po_id=h.po_id and lr.status='POSTED' and ld.status<>'REVERSED') then
      update erp.production_orders set status='QC',current_stage='QC',updated_at=now() where id=h.po_id;
    elsif exists(select 1 from erp.laundry_deliveries where po_id=h.po_id and status not in('DRAFT','REVERSED')) then
      update erp.production_orders set status='LAUNDRY',current_stage='LAUNDRY',updated_at=now() where id=h.po_id;
    elsif exists(select 1 from erp.cutting_groups where po_id=h.po_id and picked_up_at is not null) then
      update erp.production_orders set status='SEWING',current_stage='SEWING',updated_at=now() where id=h.po_id;
    else
      update erp.production_orders set status='CUTTING',current_stage='CUTTING',updated_at=now() where id=h.po_id;
    end if;
  end if;

  perform erp.sync_laundry_accrual(h.po_id,current_date);
  perform erp.rebuild_po_hpp(h.po_id,'QC reversed: '||p_reason);
  perform erp.propagate_conversion_hpp_for_po(h.po_id);
  perform erp.sync_po_hpp_to_gl(h.po_id,current_date);

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('qc_inspections',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_qc"(p_qc_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_rework_completion(p_rework_order_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  r erp.rework_orders%rowtype;
  b erp.bs_cases%rowtype;
  x record;
  v_journal uuid;
  v_total numeric(24,6):=0;
  v_remaining integer:=0;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal hasil rework wajib diisi'; end if;
  select * into r from erp.rework_orders where id=p_rework_order_id for update;
  if r.id is null then raise exception 'Rework order tidak ditemukan'; end if;
  if r.status='CANCELLED' and r.cost_posted then return; end if;
  if r.status<>'COMPLETED' or not r.cost_posted then raise exception 'Hanya rework COMPLETED yang sudah diposting biayanya yang dapat direverse'; end if;
  select * into b from erp.bs_cases where id=r.bs_case_id for update;

  if exists(
    select 1 from erp.payroll_work_items pwi
    join erp.payroll_settlements ps on ps.id=pwi.payroll_id
    join erp.rework_component_lines rcl on rcl.id=pwi.source_id
    where pwi.source_type='REWORK' and rcl.rework_order_id=r.id and ps.status<>'REVERSED'
  ) then raise exception 'Upah rework ini sudah masuk payroll. Cancel/reverse payroll aktif terlebih dahulu.'; end if;

  if r.good_fg_lot_id is not null then
    if erp.fg_lot_has_active_downstream(r.good_fg_lot_id,'REWORK_IN','REWORK_ORDER',r.id) then
      raise exception 'FG hasil rework masih dipakai transaksi downstream aktif. Reverse transaksi downstream terlebih dahulu.';
    end if;
    if exists(select 1 from erp.contractor_accessory_reimbursement_entitlements e where e.lot_id=r.good_fg_lot_id and e.payroll_status<>'UNALLOCATED') then
      raise exception 'Reimbursement aksesori hasil rework sudah masuk payroll. Cancel/reverse payroll terlebih dahulu.';
    end if;
  end if;

  select coalesce(sum(amount_payable),0) into v_total from erp.rework_component_lines where rework_order_id=r.id;
  select id into v_journal from erp.journal_entries where source_type='REWORK_COMPLETION' and source_id=r.id and status='POSTED' order by posting_at desc,id desc limit 1;
  if r.destination_type='CONTRACTOR' and v_total>0.005 and v_journal is null then raise exception 'Jurnal biaya/upah rework tidak ditemukan; reversal dibatalkan agar hutang mandor/HPP tidak rusak'; end if;

  if r.good_fg_lot_id is not null then
    select id into v_journal from erp.journal_entries where source_type='ACCESSORY_REIMBURSE_ACCRUAL' and source_id=r.good_fg_lot_id and status='POSTED' order by posting_at desc,id desc limit 1;
    if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;
    update erp.contractor_accessory_reimbursement_entitlements set payroll_status='CANCELLED' where lot_id=r.good_fg_lot_id and payroll_status='UNALLOCATED';
    for x in select fm.id from erp.fg_stock_movements fm where fm.lot_id=r.good_fg_lot_id and fm.movement_type='REWORK_IN' and fm.source_type='REWORK_ORDER' and fm.source_id=r.id and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=fm.id)
    loop perform erp.reverse_fg_movement(x.id,p_reason); end loop;
    update erp.fg_lots set lot_origin='VOIDED_PRODUCTION',is_open=false where id=r.good_fg_lot_id and lot_origin='PRODUCTION';
  end if;

  select id into v_journal from erp.journal_entries where source_type='REWORK_COMPLETION' and source_id=r.id and status='POSTED' order by posting_at desc,id desc limit 1;
  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;
  delete from erp.bs_resolutions where source_rework_order_id=r.id;
  update erp.rework_orders set status='CANCELLED',updated_at=now(),notes=concat_ws(E'\n',notes,'CANCELLED after posted completion reversal: '||p_reason) where id=r.id;

  select greatest(b.qty_pcs-coalesce(sum(br.qty_pcs),0),0)::integer into v_remaining from erp.bs_resolutions br where br.bs_case_id=b.id;
  if v_remaining<=0 then update erp.bs_cases set status='RESOLVED',updated_at=now() where id=b.id;
  elsif exists(select 1 from erp.rework_orders ro where ro.bs_case_id=b.id and ro.id<>r.id and ro.status in ('OPEN','IN_PROGRESS','PARTIAL')) then update erp.bs_cases set status='IN_REWORK',updated_at=now() where id=b.id;
  elsif v_remaining<b.qty_pcs then update erp.bs_cases set status='PARTIAL',updated_at=now() where id=b.id;
  else update erp.bs_cases set status='OPEN',updated_at=now() where id=b.id; end if;

  if b.po_id is not null then
    perform erp.rebuild_po_hpp(b.po_id,'Rework completion reversed: '||p_reason);
    perform erp.propagate_conversion_hpp_for_po(b.po_id);
    perform erp.sync_po_hpp_to_gl(b.po_id,current_date);
  end if;
  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason) values('rework_orders',r.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_rework_completion"(p_rework_order_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_sale(p_sale_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.sales_headers%rowtype;
  r record;
  v_journal uuid;
  v_expected numeric(24,6);
  v_po uuid;
  v_reversal_hpp numeric(24,6);
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal penjualan wajib diisi'; end if;

  select * into h from erp.sales_headers where id=p_sale_id for update;
  if h.id is null then raise exception 'Penjualan tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status not in ('POSTED','PARTIAL_PAID','PAID') then
    raise exception 'Hanya penjualan yang sudah POSTED/aktif yang dapat direverse';
  end if;

  if exists(select 1 from erp.sales_payments where sale_id=h.id and status='POSTED') then
    raise exception 'Penjualan ini sudah memiliki pembayaran customer. Reverse pembayaran aktif terlebih dahulu.';
  end if;
  if exists(select 1 from erp.sales_returns where sale_id=h.id and status='POSTED') then
    raise exception 'Penjualan ini sudah memiliki retur POSTED. Reverse retur aktif terlebih dahulu.';
  end if;

  select coalesce((select sum(line_total) from erp.sales_items where sale_id=h.id),0)
       + coalesce((select sum(a.qty_pcs*a.unit_hpp_snapshot) from erp.sale_stock_allocations a join erp.sales_items si on si.id=a.sale_item_id where si.sale_id=h.id),0)
  into v_expected;

  select id into v_journal
  from erp.journal_entries
  where source_type='SALE' and source_id=h.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if v_expected>0.005 and v_journal is null then
    raise exception 'Jurnal penjualan tidak ditemukan; reversal dibatalkan agar piutang/HPP tidak rusak';
  end if;

  for r in
    select fm.id
    from erp.fg_stock_movements fm
    join erp.sales_items si on si.id=fm.source_id
    where si.sale_id=h.id
      and fm.source_type='SALE_ITEM' and fm.movement_type='SALE'
      and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=fm.id)
    order by fm.physical_at desc,fm.id desc
  loop
    perform erp.reverse_fg_movement(r.id,p_reason);
  end loop;

  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;
  update erp.sales_headers set status='REVERSED' where id=h.id;

  for v_po in
    select distinct fl.po_id
    from erp.sale_stock_allocations a
    join erp.sales_items si on si.id=a.sale_item_id
    join erp.fg_lots fl on fl.id=a.lot_id
    where si.sale_id=h.id and fl.po_id is not null
    order by fl.po_id
  loop
    select coalesce(sum(a.qty_pcs*a.unit_hpp_snapshot),0)
    into v_reversal_hpp
    from erp.sale_stock_allocations a
    join erp.sales_items si on si.id=a.sale_item_id
    join erp.fg_lots fl on fl.id=a.lot_id
    where si.sale_id=h.id and fl.po_id=v_po;

    -- The compensating journal has already moved this historical snapshot
    -- from COGS back to FG. Advance the state by that same movement first;
    -- sync_po_hpp_to_gl must post only the remaining current-HPP chronology delta.
    update erp.po_hpp_gl_state
    set fg_value=fg_value+v_reversal_hpp,
        cogs_value=cogs_value-v_reversal_hpp,
        updated_at=now()
    where po_id=v_po;
    if not found then
      raise exception 'PO HPP GL state missing for sale reversal; reversal aborted to protect FG/COGS';
    end if;

    perform erp.sync_po_hpp_to_gl(v_po,current_date);
  end loop;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('sales_headers',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_sale"(p_sale_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_sales_payment(p_payment_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  p erp.sales_payments%rowtype;
  h erp.sales_headers%rowtype;
  v_journal uuid;
  v_paid numeric(20,2);
  v_total numeric(20,2);
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal pembayaran customer wajib diisi'; end if;
  select * into p from erp.sales_payments where id=p_payment_id for update;
  if p.id is null then raise exception 'Pembayaran customer tidak ditemukan'; end if;
  if p.status='REVERSED' then return; end if;
  if p.status<>'POSTED' then raise exception 'Hanya pembayaran customer yang sudah POSTED yang dapat direverse'; end if;
  select * into h from erp.sales_headers where id=p.sale_id for update;
  if h.id is null then raise exception 'Penjualan sumber pembayaran tidak ditemukan'; end if;

  select id into v_journal from erp.journal_entries
  where source_type='SALES_PAYMENT' and source_id=p.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if v_journal is null then raise exception 'Jurnal pembayaran customer tidak ditemukan; reversal dibatalkan agar kas/piutang tidak rusak'; end if;

  perform erp.reverse_journal(v_journal,p_reason);
  update erp.sales_payments set status='REVERSED' where id=p.id;

  select erp.sale_net_total(h.id)::numeric(20,2) into v_total;
  select coalesce(sum(amount),0)::numeric(20,2) into v_paid from erp.sales_payments where sale_id=h.id and status='POSTED';
  update erp.sales_headers set status=case when v_paid>=v_total-0.01 then 'PAID' when v_paid>0 then 'PARTIAL_PAID' else 'POSTED' end where id=h.id;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values ('sales_payments',p.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_sales_payment"(p_payment_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_sales_return(p_return_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.sales_returns%rowtype;
  s erp.sales_headers%rowtype;
  r record;
  v_journal uuid;
  v_expected numeric(24,6);
  v_paid numeric(20,2);
  v_total numeric(20,2);
  v_po uuid;
  v_reversal_hpp numeric(24,6);
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal retur penjualan wajib diisi'; end if;

  select * into h from erp.sales_returns where id=p_return_id for update;
  if h.id is null then raise exception 'Retur penjualan tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya retur penjualan POSTED yang dapat direverse'; end if;

  select * into s from erp.sales_headers where id=h.sale_id for update;
  if s.id is null or s.status='REVERSED' then raise exception 'Penjualan sumber retur tidak aktif'; end if;

  select coalesce(sum(sri.refund_amount+sri.qty_pcs*sri.unit_hpp_snapshot),0)
  into v_expected
  from erp.sales_return_items sri where sri.return_id=h.id;

  select id into v_journal
  from erp.journal_entries
  where source_type='SALES_RETURN' and source_id=h.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if v_expected>0.005 and v_journal is null then
    raise exception 'Jurnal retur penjualan tidak ditemukan; reversal dibatalkan agar piutang/HPP tidak rusak';
  end if;

  -- A return reversal removes the returned stock again. If that stock has already
  -- been consumed/sold, reverse the downstream transaction first.
  for r in
    select fm.id,fm.lot_id,fm.location_id,fm.quality_grade,fm.qty_signed,fl.cached_qty_pcs
    from erp.fg_stock_movements fm
    join erp.sales_return_items sri on sri.id=fm.source_id
    join erp.fg_lots fl on fl.id=fm.lot_id
    where sri.return_id=h.id
      and fm.source_type='SALES_RETURN_ITEM'
      and fm.movement_type='SALE_RETURN'
      and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=fm.id)
    order by fm.physical_at desc,fm.id desc
  loop
    if r.cached_qty_pcs<r.qty_signed then
      raise exception 'Barang dari retur ini sudah dipakai/dijual lagi. Reverse transaksi downstream dulu sebelum membatalkan retur.';
    end if;
    perform erp.reverse_fg_movement(r.id,p_reason);
  end loop;

  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;
  update erp.sales_returns set status='REVERSED' where id=h.id;

  select erp.sale_net_total(s.id)::numeric(20,2) into v_total;
  select coalesce(sum(amount),0)::numeric(20,2) into v_paid
  from erp.sales_payments where sale_id=s.id and status='POSTED';
  update erp.sales_headers
  set status=case when v_paid>=v_total-0.01 then 'PAID' when v_paid>0 then 'PARTIAL_PAID' else 'POSTED' end
  where id=s.id;

  for v_po in
    select distinct fl.po_id
    from erp.sales_return_items sri
    join erp.fg_lots fl on fl.id=sri.lot_id
    where sri.return_id=h.id and fl.po_id is not null
    order by fl.po_id
  loop
    select coalesce(sum(sri.qty_pcs*sri.unit_hpp_snapshot),0)
    into v_reversal_hpp
    from erp.sales_return_items sri
    join erp.fg_lots fl on fl.id=sri.lot_id
    where sri.return_id=h.id and fl.po_id=v_po;

    -- The compensating journal has already removed this historical snapshot
    -- from FG and restored it to COGS. Move the baseline by the same amount so
    -- the following sync only records any later HPP-version difference.
    update erp.po_hpp_gl_state
    set fg_value=fg_value-v_reversal_hpp,
        cogs_value=cogs_value+v_reversal_hpp,
        updated_at=now()
    where po_id=v_po;
    if not found then
      raise exception 'PO HPP GL state missing for sales-return reversal; reversal aborted to protect FG/COGS';
    end if;

    perform erp.sync_po_hpp_to_gl(v_po,current_date);
  end loop;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('sales_returns',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_sales_return"(p_return_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_scrap_sale(p_scrap_sale_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare s erp.scrap_sales%rowtype;b erp.scrap_batches%rowtype;v_journal uuid;v_sold numeric(18,6);
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal penjualan scrap wajib diisi'; end if;
  select * into s from erp.scrap_sales where id=p_scrap_sale_id for update;
  if s.id is null then raise exception 'Penjualan scrap tidak ditemukan'; end if;
  if s.status='REVERSED' then return; end if;
  if s.status<>'POSTED' then raise exception 'Hanya penjualan scrap POSTED yang dapat direverse'; end if;
  select * into b from erp.scrap_batches where id=s.scrap_batch_id for update;
  if b.status='DISPOSED' then raise exception 'Batch scrap sudah DISPOSED. Koreksi/disposal harus dibereskan terlebih dahulu sebelum reversal sale.'; end if;
  if s.amount>0 then
    select id into v_journal from erp.journal_entries where source_type='SCRAP_SALE' and source_id=s.id and status='POSTED' order by posting_at desc,id desc limit 1;
    if v_journal is null then raise exception 'Jurnal penjualan scrap tidak ditemukan; reversal dibatalkan'; end if;
    perform erp.reverse_journal(v_journal,p_reason);
  end if;
  update erp.scrap_sales set status='REVERSED' where id=s.id;
  select coalesce(sum(weight_kg),0) into v_sold from erp.scrap_sales where scrap_batch_id=b.id and status='POSTED';
  update erp.scrap_batches set status=case when v_sold>=weight_kg then 'SOLD' else 'AVAILABLE' end where id=b.id;
  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('scrap_sales',s.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;$function$;

alter function "erp"."reverse_scrap_sale"(p_scrap_sale_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_sewing_terminal_v1(p_event_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'reverse_sewing_terminal_v1';
  v_hash text;
  v_cached jsonb;
  v_original erp.sewing_terminal_events%rowtype;
  v_reversal erp.sewing_terminal_events%rowtype;
  v_response jsonb;
begin
  perform erp.require_owner_admin();
  if p_event_id is null or p_expected_version is null then
    raise exception 'event_id and expected_version are required';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'SELESAI_DIJAHIT reversal reason is required';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'event_id', p_event_id,
    'reason', btrim(p_reason),
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_original
  from erp.sewing_terminal_events
  where id = p_event_id
  for update;

  if v_original.id is null or v_original.event_kind <> 'SELESAI_DIJAHIT' then
    raise exception 'Original SELESAI_DIJAHIT event not found';
  end if;
  if v_original.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_original.row_version;
  end if;

  perform erp._cp3_lock_business_date(erp._cp3_business_date(v_original.physical_at));
  if exists (select 1 from erp.sewing_terminal_events where reversal_of_id = v_original.id) then
    raise exception 'SELESAI_DIJAHIT event is already reversed';
  end if;
  if exists (
    select 1
    from erp.attendance_hpp_pool_allocations a
    join erp.attendance_hpp_pools p on p.id = a.pool_id
    where a.sewing_terminal_event_id = v_original.id
      and p.status = 'ACTIVE'
  ) then
    raise exception 'SELESAI_DIJAHIT is consumed by an ACTIVE attendance HPP pool; cancel that pool first';
  end if;

  insert into erp.sewing_terminal_events(
    event_number, event_kind, reversal_of_id,
    contractor_id, po_id, cutting_group_id, physical_at,
    qty_signed, reason, created_by
  ) values (
    'SEW-RV-' || to_char(clock_timestamp() at time zone 'UTC', 'YYYYMMDDHH24MISSUS') || '-' || substr(gen_random_uuid()::text, 1, 8),
    'REVERSAL', v_original.id,
    v_original.contractor_id, v_original.po_id, v_original.cutting_group_id,
    v_original.physical_at, -v_original.qty_signed,
    btrim(p_reason), erp.current_app_user_id()
  ) returning * into v_reversal;

  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
  values (
    'sewing_terminal_events', v_original.id, 'REVERSE',
    jsonb_build_object(
      'reversal_event_id', v_reversal.id,
      'qty_signed', v_reversal.qty_signed,
      'original_physical_at_epoch_us', erp._cp3_epoch_microseconds(v_original.physical_at)
    ),
    erp.current_app_user_id(), btrim(p_reason)
  );

  v_response := jsonb_build_object(
    'original_event_id', v_original.id,
    'reversal_event_id', v_reversal.id,
    'status', 'REVERSED',
    'qty_reversed', v_original.qty_signed
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."reverse_sewing_terminal_v1"(p_event_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_supplier_payment(p_payment_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  p erp.supplier_payments%rowtype;
  h erp.material_purchase_headers%rowtype;
  v_journal uuid;
  v_paid numeric(20,2);
  v_total numeric(20,2);
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal pembayaran supplier wajib diisi'; end if;
  select * into p from erp.supplier_payments where id=p_payment_id for update;
  if p.id is null then raise exception 'Pembayaran supplier tidak ditemukan'; end if;
  if p.status='REVERSED' then return; end if;
  if p.status<>'POSTED' then raise exception 'Hanya pembayaran supplier yang sudah POSTED yang dapat direverse'; end if;
  select * into h from erp.material_purchase_headers where id=p.purchase_id for update;
  if h.id is null then raise exception 'Pembelian sumber pembayaran tidak ditemukan'; end if;

  select id into v_journal from erp.journal_entries
  where source_type='SUPPLIER_PAYMENT' and source_id=p.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if v_journal is null then raise exception 'Jurnal pembayaran supplier tidak ditemukan; reversal dibatalkan agar kas/hutang tidak rusak'; end if;

  perform erp.reverse_journal(v_journal,p_reason);
  update erp.supplier_payments set status='REVERSED' where id=p.id;

  select erp.material_purchase_payable_total(h.id)::numeric(20,2) into v_total;
  select coalesce(sum(amount),0)::numeric(20,2) into v_paid from erp.supplier_payments where purchase_id=h.id and status='POSTED';
  update erp.material_purchase_headers set payment_status=case when v_paid>=v_total-0.01 then 'PAID' when v_paid>0 then 'PARTIAL' else 'UNPAID' end where id=h.id;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values ('supplier_payments',p.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_supplier_payment"(p_payment_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_vendor_invoice(p_invoice_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.vendor_invoices%rowtype;
  r record;
  v_journal uuid;
  v_po uuid;
  v_prior_cost numeric(24,6);
  v_prior_rate numeric(18,6);
  v_prior_status varchar(20);
  v_qty integer;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal invoice vendor laundry wajib diisi'; end if;

  select * into h from erp.vendor_invoices where id=p_invoice_id for update;
  if h.id is null then raise exception 'Invoice vendor laundry tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status in ('PARTIAL_PAID','PAID') or exists(select 1 from erp.vendor_payments vp where vp.vendor_invoice_id=h.id and vp.status='POSTED') then
    raise exception 'Invoice vendor laundry sudah memiliki pembayaran. Reverse pembayaran vendor yang masih POSTED terlebih dahulu agar kas dan hutang tetap cocok.';
  end if;
  if h.status<>'POSTED' then raise exception 'Hanya invoice vendor laundry yang sudah POSTED yang dapat direverse'; end if;

  select id into v_journal
  from erp.journal_entries
  where source_type='VENDOR_INVOICE' and source_id=h.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if h.total_amount>0 and v_journal is null then
    raise exception 'Jurnal invoice vendor laundry tidak ditemukan; reversal dibatalkan agar hutang/HPP tidak rusak';
  end if;

  for r in
    select vii.*,lrl.qty_good_received,lrl.qty_bs_laundry,ld.po_id,ldl.estimated_rate_snapshot,
           ca.old_amount as legacy_old_amount
    from erp.vendor_invoice_items vii
    join erp.laundry_receipt_lines lrl on lrl.id=vii.receipt_line_id
    join erp.laundry_delivery_lines ldl on ldl.id=lrl.delivery_line_id
    join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
    left join lateral (
      select x.old_amount
      from erp.cost_adjustments x
      where x.source_type='VENDOR_INVOICE_ITEM' and x.source_id=vii.id
      order by x.entered_at desc,x.id desc limit 1
    ) ca on true
    where vii.invoice_id=h.id
    order by vii.id
  loop
    perform 1 from erp.laundry_receipt_lines where id=r.receipt_line_id for update;
    v_qty:=coalesce(r.qty_good_received,0)+coalesce(r.qty_bs_laundry,0);
    v_prior_cost:=coalesce(r.prior_actual_cost,r.legacy_old_amount);
    v_prior_status:=r.prior_actual_cost_status;
    v_prior_rate:=r.prior_actual_rate_snapshot;

    if v_prior_status is null then
      if v_prior_cost is null or (abs(v_prior_cost)<=0.000001 and r.estimated_rate_snapshot is null) then
        v_prior_status:='PENDING';
        v_prior_cost:=null;
        v_prior_rate:=null;
      else
        v_prior_status:='ESTIMATED';
        if v_prior_cost is null and r.estimated_rate_snapshot is not null then v_prior_cost:=v_qty*r.estimated_rate_snapshot; end if;
        if v_prior_rate is null and v_qty>0 and v_prior_cost is not null then v_prior_rate:=v_prior_cost/v_qty; end if;
      end if;
    end if;

    if v_prior_status='PENDING' then
      v_prior_cost:=null;
      v_prior_rate:=null;
    elsif v_prior_rate is null and v_qty>0 and v_prior_cost is not null then
      v_prior_rate:=v_prior_cost/v_qty;
    end if;

    update erp.laundry_receipt_lines
    set actual_rate_snapshot=v_prior_rate,
        actual_cost=v_prior_cost,
        actual_cost_status=v_prior_status
    where id=r.receipt_line_id;

    insert into erp.cost_adjustments(adjustment_number,po_id,component_type,source_type,source_id,economic_date,old_amount,new_amount,reason,created_by)
    values ('CADJ-REV-'||substr(gen_random_uuid()::text,1,8),r.po_id,'LAUNDRY','VENDOR_INVOICE_REVERSAL',r.id,current_date,
            r.actual_amount,coalesce(v_prior_cost,0),'Reversal vendor invoice: '||p_reason,erp.current_app_user_id());
  end loop;

  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;
  update erp.vendor_invoices set status='REVERSED',updated_at=now() where id=h.id;

  for v_po in
    select distinct ld.po_id
    from erp.vendor_invoice_items vii
    join erp.laundry_receipt_lines lrl on lrl.id=vii.receipt_line_id
    join erp.laundry_delivery_lines ldl on ldl.id=lrl.delivery_line_id
    join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
    where vii.invoice_id=h.id
  loop
    perform erp.sync_laundry_accrual(v_po,current_date);
    if exists(select 1 from erp.fg_lots where po_id=v_po) then
      perform erp.rebuild_po_hpp(v_po,'Vendor laundry invoice reversed: '||p_reason);
      perform erp.propagate_conversion_hpp_for_po(v_po);
      perform erp.sync_po_hpp_to_gl(v_po,current_date);
    end if;
  end loop;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values ('vendor_invoices',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_vendor_invoice"(p_invoice_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_vendor_payment(p_payment_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  p erp.vendor_payments%rowtype;
  h erp.vendor_invoices%rowtype;
  v_journal uuid;
  v_paid numeric(20,2);
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal pembayaran vendor laundry wajib diisi'; end if;
  select * into p from erp.vendor_payments where id=p_payment_id for update;
  if p.id is null then raise exception 'Pembayaran vendor laundry tidak ditemukan'; end if;
  if p.status='REVERSED' then return; end if;
  if p.status<>'POSTED' then raise exception 'Hanya pembayaran vendor laundry yang sudah POSTED yang dapat direverse'; end if;
  select * into h from erp.vendor_invoices where id=p.vendor_invoice_id for update;
  if h.id is null then raise exception 'Invoice vendor laundry sumber pembayaran tidak ditemukan'; end if;

  select id into v_journal from erp.journal_entries
  where source_type='VENDOR_PAYMENT' and source_id=p.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if v_journal is null then raise exception 'Jurnal pembayaran vendor laundry tidak ditemukan; reversal dibatalkan agar kas/hutang tidak rusak'; end if;

  perform erp.reverse_journal(v_journal,p_reason);
  update erp.vendor_payments set status='REVERSED' where id=p.id;

  select coalesce(sum(amount),0)::numeric(20,2) into v_paid from erp.vendor_payments where vendor_invoice_id=h.id and status='POSTED';
  update erp.vendor_invoices set status=case when v_paid>=h.total_amount-0.01 then 'PAID' when v_paid>0 then 'PARTIAL_PAID' else 'POSTED' end where id=h.id;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values ('vendor_payments',p.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_vendor_payment"(p_payment_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.reverse_work_completion(p_completion_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.work_completion_events%rowtype;
  v_journal uuid;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal hasil kerja mandor wajib diisi'; end if;

  select * into h from erp.work_completion_events where id=p_completion_id for update;
  if h.id is null then raise exception 'Transaksi hasil kerja mandor tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya hasil kerja mandor yang sudah POSTED yang dapat direverse'; end if;

  perform erp._cp3_lock_business_date(erp._cp3_business_date(h.physical_at));
  if exists(
    select 1
    from erp.sewing_terminal_events e
    where e.source_work_completion_id=h.id
      and e.event_kind='SELESAI_DIJAHIT'
      and not exists(
        select 1 from erp.sewing_terminal_events rv where rv.reversal_of_id=e.id
      )
  ) then
    raise exception 'Work completion masih memiliki SELESAI_DIJAHIT aktif. Reverse melalui reverse_sewing_terminal_v1() terlebih dahulu; jika sudah dikonsumsi ACTIVE pool, cancel pool tersebut lebih dulu.';
  end if;

  if exists(
    select 1
    from erp.payroll_work_items pwi
    join erp.payroll_settlements ps on ps.id=pwi.payroll_id
    join erp.work_completion_lines wcl on wcl.id=pwi.source_id
    where wcl.completion_id=h.id and pwi.source_type='PRODUCTION' and ps.status<>'REVERSED'
  ) then
    raise exception 'Hasil kerja ini sudah masuk payroll mandor. Cancel atau reverse payroll yang masih aktif terlebih dahulu supaya upah tidak dibayar/dicabut dua kali.';
  end if;

  select id into v_journal
  from erp.journal_entries
  where source_type='WORK_COMPLETION' and source_id=h.id and status='POSTED'
  order by posting_at desc,id desc limit 1;

  if exists(select 1 from erp.work_completion_lines where completion_id=h.id and amount_payable>0) and v_journal is null then
    raise exception 'Jurnal hasil kerja mandor tidak ditemukan; reversal dibatalkan agar hutang upah/HPP tidak rusak';
  end if;
  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;

  update erp.work_completion_events set status='REVERSED',updated_at=now() where id=h.id;

  if exists(select 1 from erp.fg_lots where po_id=h.po_id) then
    perform erp.rebuild_po_hpp(h.po_id,'Work completion reversed: '||p_reason);
    perform erp.propagate_conversion_hpp_for_po(h.po_id);
    perform erp.sync_po_hpp_to_gl(h.po_id,current_date);
  end if;

  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values ('work_completion_events',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
end;
$function$;

alter function "erp"."reverse_work_completion"(p_completion_id uuid, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
BEGIN
  PERFORM erp.require_owner_admin();

  RETURN QUERY SELECT 'UNBALANCED_POSTED_JOURNALS','ERROR',COUNT(*)::bigint,'Posted journals where total debit differs from total credit'
  FROM (SELECT je.id FROM erp.journal_entries je JOIN erp.journal_lines jl ON jl.journal_entry_id=je.id WHERE je.status='POSTED' GROUP BY je.id HAVING ABS(SUM(jl.debit)-SUM(jl.credit))>0.01) x;

  RETURN QUERY SELECT 'NEGATIVE_MATERIAL_LOCATION_BALANCE','ERROR',COUNT(*)::bigint,'Material/location/roll balances below zero'
  FROM (SELECT material_id,location_id,roll_id FROM erp.material_stock_movements GROUP BY material_id,location_id,roll_id HAVING SUM(qty_signed)<-0.000001) x;

  RETURN QUERY SELECT 'NEGATIVE_FG_BALANCE','ERROR',COUNT(*)::bigint,'Finished-goods product/location/grade balances below zero'
  FROM (SELECT product_id,location_id,quality_grade FROM erp.fg_stock_movements GROUP BY product_id,location_id,quality_grade HAVING SUM(qty_signed)<0) x;

  RETURN QUERY SELECT 'FG_CACHE_MISMATCH','ERROR',COUNT(*)::bigint,'FG cache differs from ledger source of truth'
  FROM (SELECT COALESCE(l.product_id,c.product_id) product_id,COALESCE(l.location_id,c.location_id) location_id,COALESCE(l.quality_grade,c.quality_grade) quality_grade FROM (SELECT product_id,location_id,quality_grade,SUM(qty_signed)::bigint qty FROM erp.fg_stock_movements GROUP BY product_id,location_id,quality_grade) l FULL JOIN erp.fg_inventory_balances c ON c.product_id=l.product_id AND c.location_id=l.location_id AND c.quality_grade=l.quality_grade WHERE COALESCE(l.qty,0)<>COALESCE(c.cached_qty_pcs,0)) x;

  RETURN QUERY SELECT 'DUPLICATE_CURRENT_HPP','ERROR',COUNT(*)::bigint,'Lots with more than one current HPP version'
  FROM (SELECT lot_id FROM erp.hpp_versions WHERE is_current GROUP BY lot_id HAVING COUNT(*)>1) x;

  RETURN QUERY SELECT 'LAUNDRY_OVER_RETURN','ERROR',COUNT(*)::bigint,'Cumulative GOOD+BS laundry returns exceed sent quantity'
  FROM (SELECT ldl.id FROM erp.laundry_delivery_lines ldl LEFT JOIN erp.laundry_receipt_lines lrl ON lrl.delivery_line_id=ldl.id LEFT JOIN erp.laundry_receipts lr ON lr.id=lrl.receipt_id AND lr.status<>'REVERSED' GROUP BY ldl.id,ldl.qty_sent_pcs HAVING COALESCE(SUM(CASE WHEN lr.id IS NOT NULL THEN lrl.qty_good_received+lrl.qty_bs_laundry ELSE 0 END),0)>ldl.qty_sent_pcs) x;

  RETURN QUERY SELECT 'QC_SOURCE_OVER_ALLOCATION','ERROR',COUNT(*)::bigint,'QC GOOD+BS exceeds its posted laundry GOOD source'
  FROM (SELECT lrl.id FROM erp.laundry_receipt_lines lrl JOIN erp.laundry_receipts lr ON lr.id=lrl.receipt_id LEFT JOIN erp.qc_inspection_items qii ON qii.source_laundry_receipt_line_id=lrl.id LEFT JOIN erp.qc_inspections qi ON qi.id=qii.inspection_id AND qi.status<>'REVERSED' WHERE lr.status='POSTED' GROUP BY lrl.id,lrl.qty_good_received HAVING COALESCE(SUM(CASE WHEN qi.id IS NOT NULL THEN qii.qty_good_pcs+qii.qty_bs_pcs ELSE 0 END),0)>lrl.qty_good_received) x;

  RETURN QUERY SELECT 'PAYROLL_ATTENDANCE_DUPLICATE','ERROR',COUNT(*)::bigint,'Same attendance record allocated to multiple non-reversed payrolls'
  FROM (SELECT pai.attendance_record_id FROM erp.payroll_attendance_items pai JOIN erp.payroll_settlements ps ON ps.id=pai.payroll_id WHERE ps.status<>'REVERSED' GROUP BY pai.attendance_record_id HAVING COUNT(*)>1) x;

  RETURN QUERY SELECT 'REWORK_PAYROLL_BEFORE_COST_POST','ERROR',COUNT(*)::bigint,'Rework payroll item references rework whose production cost is not posted'
  FROM erp.payroll_work_items pwi JOIN erp.rework_component_lines rcl ON rcl.id=pwi.source_id JOIN erp.rework_orders ro ON ro.id=rcl.rework_order_id JOIN erp.payroll_settlements ps ON ps.id=pwi.payroll_id WHERE pwi.source_type='REWORK' AND ps.status<>'REVERSED' AND COALESCE(ro.cost_posted,false)=false;

  RETURN QUERY SELECT 'PAYROLL_PAID_NEGATIVE_NET','ERROR',COUNT(*)::bigint,'A paid payroll must never have negative net payable'
  FROM erp.payroll_settlements WHERE status='PAID' AND net_payable<0;

  RETURN QUERY SELECT 'KASBON_PAID_OVERSETTLED','ERROR',COUNT(*)::bigint,'Paid payroll deductions exceed original contractor receivable'
  FROM (
    SELECT cmii.id
    FROM erp.contractor_material_issue_items cmii
    LEFT JOIN erp.payroll_deductions pd ON pd.contractor_issue_item_id=cmii.id AND pd.deduction_type='MATERIAL_KASBON'
    LEFT JOIN erp.payroll_settlements ps ON ps.id=pd.payroll_id AND ps.status='PAID'
    GROUP BY cmii.id,cmii.total_receivable
    HAVING COALESCE(SUM(CASE WHEN ps.id IS NOT NULL THEN pd.amount ELSE 0 END),0)>COALESCE(cmii.total_receivable,0)+0.01
  ) x;

  RETURN QUERY SELECT 'KASBON_STATUS_MISMATCH','ERROR',COUNT(*)::bigint,'Kasbon status differs from amount actually paid/allocated'
  FROM (
    SELECT cmii.id,cmii.payroll_status,COALESCE(cmii.total_receivable,0) total_receivable,
      COALESCE(SUM(CASE WHEN ps.status='PAID' THEN pd.amount ELSE 0 END),0) paid_amt,
      COALESCE(SUM(CASE WHEN ps.status<>'REVERSED' THEN pd.amount ELSE 0 END),0) allocated_amt
    FROM erp.contractor_material_issue_items cmii
    LEFT JOIN erp.payroll_deductions pd ON pd.contractor_issue_item_id=cmii.id AND pd.deduction_type='MATERIAL_KASBON'
    LEFT JOIN erp.payroll_settlements ps ON ps.id=pd.payroll_id
    GROUP BY cmii.id,cmii.payroll_status,cmii.total_receivable
  ) s
  WHERE s.payroll_status IS DISTINCT FROM CASE
    WHEN s.total_receivable<=0 OR s.paid_amt>=s.total_receivable-0.01 THEN 'SETTLED'
    WHEN s.paid_amt>0 THEN 'PARTIAL'
    WHEN s.allocated_amt>0 THEN 'ALLOCATED'
    ELSE 'UNALLOCATED' END;

  RETURN QUERY SELECT 'REWORK_COMPLETION_UNRECONCILED','ERROR',COUNT(*)::bigint,'Completed rework must have GOOD + BS exactly equal to qty sent'
  FROM erp.rework_orders WHERE status='COMPLETED' AND qty_good_returned+qty_bs_returned<>qty_sent;

  RETURN QUERY SELECT 'REWORK_GOOD_WITHOUT_FG','ERROR',COUNT(*)::bigint,'Posted completed rework with GOOD output must have an FG lot'
  FROM erp.rework_orders WHERE status='COMPLETED' AND cost_posted=true AND qty_good_returned>0 AND good_fg_lot_id IS NULL;

  RETURN QUERY SELECT 'REWORK_FG_QTY_MISMATCH','ERROR',COUNT(*)::bigint,'Rework GOOD qty must equal REWORK_IN FG ledger qty'
  FROM erp.rework_orders ro
  WHERE ro.cost_posted=true AND ro.qty_good_returned>0
    AND COALESCE((SELECT SUM(fsm.qty_signed) FROM erp.fg_stock_movements fsm WHERE fsm.lot_id=ro.good_fg_lot_id AND fsm.movement_type='REWORK_IN'),0)<>ro.qty_good_returned;

  RETURN QUERY SELECT 'BS_RESOLUTION_OVER_QTY','ERROR',COUNT(*)::bigint,'Resolved BS quantity cannot exceed original BS case quantity'
  FROM (SELECT bc.id FROM erp.bs_cases bc LEFT JOIN erp.bs_resolutions br ON br.bs_case_id=bc.id GROUP BY bc.id,bc.qty_pcs HAVING COALESCE(SUM(br.qty_pcs),0)>bc.qty_pcs) x;

  RETURN QUERY SELECT 'STALE_RECOST_QUEUE','WARN',COUNT(*)::bigint,'Recost queue has PENDING/RUNNING work older than 10 minutes'
  FROM erp.cost_recalc_queue WHERE status IN ('PENDING','RUNNING') AND queued_at<now()-interval '10 minutes';

  RETURN QUERY SELECT 'FAILED_RECOST_QUEUE','WARN',COUNT(*)::bigint,'Cost recalculation jobs exhausted or awaiting retry'
  FROM erp.cost_recalc_queue WHERE status='FAILED';
END;
$function$;

alter function "erp"."run_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_security_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth'
AS $function$
begin
  perform erp.require_owner_admin();

  return query
  select 'AUDIT_LOG_WRITE_POLICIES','ERROR',count(*)::bigint,
         'audit_logs must have SELECT-only application policies'
  from pg_policies
  where schemaname='erp' and tablename='audit_logs' and cmd<>'SELECT';

  return query
  select 'AUDIT_LOG_AUTHENTICATED_DML','ERROR',
         case when has_table_privilege('authenticated','erp.audit_logs','INSERT')
                or has_table_privilege('authenticated','erp.audit_logs','UPDATE')
                or has_table_privilege('authenticated','erp.audit_logs','DELETE')
              then 1::bigint else 0::bigint end,
         'authenticated must not mutate audit_logs directly'
  where exists (select 1 from pg_roles where rolname='authenticated');

  return query
  select 'PUBLIC_FUNCTION_EXECUTE','ERROR',count(*)::bigint,
         'PUBLIC must not execute ERP routines'
  from pg_proc p
  join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='erp' and has_function_privilege('public',p.oid,'EXECUTE');

  return query
  select 'AUTH_DANGEROUS_FUNCTION_EXECUTE','ERROR',count(*)::bigint,
         'authenticated must not execute low-level ledger/journal/cost helpers'
  from pg_proc p
  join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='erp'
    and p.proname=any(array[
      'account_id','post_journal','create_journal','finalize_journal',
      'post_fg_movement','rebuild_po_hpp','sync_po_hpp_to_gl',
      'refresh_po_hpp_gl_baseline','sync_laundry_accrual',
      'desired_laundry_accrual','propagate_conversion_hpp_for_po',
      'ensure_fg_accessory_cost_snapshot','commit_accessory_bom_for_lot',
      'post_accessory_reimbursement_accrual','accessory_uom_factor',
      'reverse_fg_movement','reverse_material_movement'
    ])
    and has_function_privilege('authenticated',p.oid,'EXECUTE');

  return query
  select 'UNTRUSTED_MATERIAL_PURCHASE_STAGE_REVERSAL_EXECUTE','ERROR',count(*)::bigint,
         'anon/authenticated/PUBLIC must not execute the internal material-purchase stock reversal staging helper'
  from pg_proc p
  join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='erp'
    and p.proname='_stage_reverse_material_purchase_stock_at_source_time'
    and (
      has_function_privilege('public',p.oid,'EXECUTE')
      or has_function_privilege('anon',p.oid,'EXECUTE')
      or has_function_privilege('authenticated',p.oid,'EXECUTE')
    );

  return query
  select 'RLS_DISABLED_TABLES','ERROR',count(*)::bigint,
         'Every ERP base table must have RLS enabled'
  from pg_class c
  join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='erp' and c.relkind='r' and c.relrowsecurity=false;
end;
$function$;

alter function "erp"."run_security_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v24_accessory_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  perform erp.require_owner_admin();

  return query
  select 'ACCESSORY_WITHOUT_CATEGORY','ERROR',count(*)::bigint,
         'Active ACCESSORY materials must map to a broad accessory category'
  from erp.materials
  where material_type='ACCESSORY' and is_active=true and accessory_category_id is null;

  return query
  select 'ACCESSORY_CATEGORY_UOM_MISMATCH','ERROR',count(*)::bigint,
         'Accessory variant base UOM must equal category base UOM'
  from erp.materials m
  join erp.accessory_categories c on c.id=m.accessory_category_id
  where m.material_type='ACCESSORY' and m.unit_code<>c.base_uom_code;

  return query
  select 'ACCESSORY_ISSUE_UOM_MISMATCH','ERROR',count(*)::bigint,
         'Physical base quantity differs from transaction quantity x snapshotted conversion'
  from erp.contractor_material_issue_items cmii
  join erp.materials m on m.id=cmii.material_id
  where m.material_type='ACCESSORY'
    and abs(cmii.qty-(cmii.transaction_qty*cmii.base_qty_per_transaction_uom))>0.000001;

  return query
  select 'ACCESSORY_REIMBURSE_DUPLICATE_PAYROLL','ERROR',count(*)::bigint,
         'One GOOD-FG accessory reimbursement entitlement appears in multiple non-reversed payrolls'
  from (
    select pr.source_id
    from erp.payroll_reimbursements pr
    join erp.payroll_settlements ps on ps.id=pr.payroll_id
    where pr.source_type='ACCESSORY_BOM' and ps.status<>'REVERSED'
    group by pr.source_id
    having count(*)>1
  ) x;

  return query
  select 'ACCESSORY_HPP_PHYSICAL_ISSUE_LINK','ERROR',count(*)::bigint,
         'Current HPP must never source ACCESSORY cost directly from contractor physical issue items'
  from erp.hpp_version_components hvc
  join erp.hpp_versions hv on hv.id=hvc.hpp_version_id and hv.is_current=true
  where hvc.component_type='ACCESSORY'
    and hvc.source_type in ('CONTRACTOR_MATERIAL_ISSUE_ITEM','CONTRACTOR_MATERIAL_ISSUE');

  return query
  select 'ACCESSORY_SNAPSHOT_REIMBURSE_MISMATCH','ERROR',count(*)::bigint,
         'Reimbursement entitlement must equal frozen GOOD-FG snapshot reimbursement'
  from erp.fg_accessory_cost_snapshots s
  join erp.contractor_accessory_reimbursement_entitlements e on e.snapshot_id=s.id
  where abs(e.amount-s.total_reimbursement)>0.01;

  return query
  select 'ACCESSORY_BOM_SNAPSHOT_MISSING','WARN',count(*)::bigint,
         'Production lots with a non-empty effective accessory BOM but no frozen accessory snapshot'
  from erp.fg_lots fl
  join erp.production_orders po on po.id=fl.po_id
  where fl.lot_origin='PRODUCTION'
    and exists (
      select 1
      from erp.accessory_bom_versions abv
      where abv.product_id=fl.product_id
        and abv.is_active=true
        and abv.effective_from<=coalesce(po.physical_start_at,fl.produced_at)
        and (abv.effective_to is null or abv.effective_to>coalesce(po.physical_start_at,fl.produced_at))
        and exists(select 1 from erp.accessory_bom_items abi where abi.bom_version_id=abv.id)
    )
    and not exists(select 1 from erp.fg_accessory_cost_snapshots s where s.lot_id=fl.id);
end;
$function$;

alter function "erp"."run_v24_accessory_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v251_cutting_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
BEGIN
  PERFORM erp.require_owner_admin();

  RETURN QUERY
  SELECT 'CUTTING_BATCH_PO_MISMATCH','ERROR',COUNT(*)::bigint,
         'Cutting group and parent cutting batch must belong to the same PO'
  FROM erp.cutting_groups g
  JOIN erp.cutting_batches b ON b.id=g.cutting_batch_id
  WHERE g.po_id<>b.po_id;

  RETURN QUERY
  SELECT 'CUTTING_EFFECTIVE_NEGATIVE','ERROR',COUNT(*)::bigint,
         'Original cutting yield plus posted corrections may not be negative'
  FROM erp.v_cutting_group_quantity_detail q
  WHERE q.effective_pcs<0;

  RETURN QUERY
  SELECT 'CUTTING_EFFECTIVE_BELOW_DOWNSTREAM','ERROR',COUNT(*)::bigint,
         'Effective cutting quantity may not be lower than quantity already committed to laundry/QC/FG'
  FROM erp.v_cutting_group_quantity_detail q
  WHERE q.effective_pcs < erp.cutting_group_downstream_committed_qty(q.cutting_group_id);

  RETURN QUERY
  SELECT 'CUTTING_REDISTRIBUTION_NOT_ZERO','ERROR',COUNT(*)::bigint,
         'Redistribution corrections must net to zero within a cutting batch'
  FROM (
    SELECT c.id
    FROM erp.cutting_qty_corrections c
    JOIN erp.cutting_qty_correction_lines l ON l.correction_id=c.id
    WHERE c.correction_type='REDISTRIBUTION'
    GROUP BY c.id
    HAVING SUM(l.qty_delta_pcs)<>0
  ) x;

  RETURN QUERY
  SELECT 'FG_CUTTING_LINEAGE_MISSING','ERROR',COUNT(*)::bigint,
         'Production FG created from QC must retain cutting-group lineage'
  FROM erp.fg_lots fl
  WHERE fl.lot_origin='PRODUCTION' AND fl.qc_item_id IS NOT NULL AND fl.cutting_group_id IS NULL;

  RETURN QUERY
  SELECT 'CUTTING_BATCH_FG_OVER_EFFECTIVE_YIELD','ERROR',COUNT(*)::bigint,
         'Production FG quantity from a cutting batch may not exceed its effective cutting yield'
  FROM (
    SELECT b.id
    FROM erp.cutting_batches b
    JOIN erp.cutting_groups g ON g.cutting_batch_id=b.id
    LEFT JOIN erp.fg_lots fl ON fl.cutting_group_id=g.id AND fl.lot_origin='PRODUCTION'
    JOIN erp.v_cutting_batch_totals bt ON bt.cutting_batch_id=b.id
    GROUP BY b.id,bt.effective_pcs
    HAVING COALESCE(SUM(fl.initial_qty_pcs),0)>bt.effective_pcs
  ) x;
END;
$function$;

alter function "erp"."run_v251_cutting_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v253_financial_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  perform erp.require_owner_admin();
  return query select 'SALES_PAYMENT_OVERPAY','ERROR',count(*)::bigint,'Posted customer payments exceed net sale value after posted returns' from (
    select sh.id from erp.sales_headers sh left join erp.sales_items si on si.sale_id=sh.id
    group by sh.id having coalesce((select sum(sp.amount) from erp.sales_payments sp where sp.sale_id=sh.id and sp.status='POSTED'),0) >
      coalesce(sum(si.line_total),0)-coalesce((select sum(sri.refund_amount) from erp.sales_return_items sri join erp.sales_returns sr on sr.id=sri.return_id where sr.sale_id=sh.id and sr.status='POSTED'),0)+0.01
  ) x;
  return query select 'SUPPLIER_PAYMENT_OVERPAY','ERROR',count(*)::bigint,'Posted supplier payments exceed purchase document total' from (
    select mph.id from erp.material_purchase_headers mph left join erp.material_purchase_items mpi on mpi.purchase_id=mph.id
    group by mph.id having coalesce((select sum(sp.amount) from erp.supplier_payments sp where sp.purchase_id=mph.id and sp.status='POSTED'),0)>coalesce(sum(mpi.line_total),0)+0.01
  ) x;
  return query select 'VENDOR_PAYMENT_OVERPAY','ERROR',count(*)::bigint,'Posted laundry vendor payments exceed vendor invoice total' from erp.vendor_invoices vi where coalesce((select sum(vp.amount) from erp.vendor_payments vp where vp.vendor_invoice_id=vi.id and vp.status='POSTED'),0)>vi.total_amount+0.01;
  return query select 'SALES_RETURN_OVER_ALLOCATION','ERROR',count(*)::bigint,'Posted return qty exceeds original sold lot allocation' from (
    select ssa.id from erp.sale_stock_allocations ssa left join erp.sales_return_items sri on sri.sale_stock_allocation_id=ssa.id left join erp.sales_returns sr on sr.id=sri.return_id and sr.status='POSTED'
    group by ssa.id,ssa.qty_pcs having coalesce(sum(case when sr.id is not null then sri.qty_pcs else 0 end),0)>ssa.qty_pcs
  ) x;
end;
$function$;

alter function "erp"."run_v253_financial_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v255_material_cost_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  perform erp.require_owner_admin();
  return query
  select 'MATERIAL_RECOST_GL_STATE_DRIFT','ERROR',count(*)::bigint,'Material movement recost target differs from applied automatic GL revaluation'
  from (
    select msm.id
    from erp.material_stock_movements msm
    left join erp.material_cost_revaluation_state s on s.movement_id=msm.id
    where msm.movement_type<>'REVERSAL'
      and msm.source_type in('CUTTING_GROUP','CUTTING_GROUP_RETURN','CONTRACTOR_MATERIAL_ISSUE_ITEM','MATERIAL_ADJUSTMENT_ITEM','MATERIAL_SUPPLIER_RETURN_ITEM')
      and abs((case when exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=msm.id) then 0
                    else round(msm.qty_signed*(msm.unit_cost_snapshot-coalesce(msm.original_unit_cost_snapshot,msm.unit_cost_snapshot)),2) end)
              -coalesce(s.applied_inventory_delta,0))>0.01
  ) x;

  return query
  select 'MATERIAL_GL_VALUATION_MISMATCH','ERROR',
    case when abs(v.ledger_value-v.gl_value)>0.05 then 1 else 0 end::bigint,
    'Material moving-average ledger value differs from Material Inventory GL by more than 0.05'
  from (
    select
      coalesce((select sum(coalesce(m.cached_stock_qty,0)*coalesce(m.moving_average_cost,0)) from erp.materials m),0)::numeric as ledger_value,
      coalesce((select sum(adb.debit_total-adb.credit_total) from erp.account_daily_balances adb where adb.account_id=erp.account_id('MATERIAL_INVENTORY')),0)::numeric as gl_value
  ) v;
end;
$function$;

alter function "erp"."run_v255_material_cost_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v256_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  perform erp.require_owner_admin();

  return query
  with ledger as (
    select je.transaction_date balance_date,jl.account_id,
           round(sum(jl.debit),2) debit_total,round(sum(jl.credit),2) credit_total
    from erp.journal_entries je
    join erp.journal_lines jl on jl.journal_entry_id=je.id
    where je.status in ('POSTED','REVERSED')
    group by je.transaction_date,jl.account_id
  ), cmp as (
    select coalesce(l.balance_date,a.balance_date) balance_date,
           coalesce(l.account_id,a.account_id) account_id
    from ledger l full join erp.account_daily_balances a
      on a.balance_date=l.balance_date and a.account_id=l.account_id
    where abs(coalesce(l.debit_total,0)-coalesce(a.debit_total,0))>0.01
       or abs(coalesce(l.credit_total,0)-coalesce(a.credit_total,0))>0.01
  )
  select 'ACCOUNT_DAILY_BALANCE_MISMATCH','ERROR',count(*)::bigint,
         'P&L/Balance Sheet cache differs from journal ledger (original REVERSED journals plus POSTED reversals are both part of accounting history)'
  from cmp;

  return query select 'FUTURE_MATERIAL_MOVEMENT','ERROR',count(*)::bigint,
    'Material physical movement dated more than 5 minutes in the future'
  from erp.material_stock_movements where physical_at>clock_timestamp()+interval '5 minutes';

  return query select 'FUTURE_FG_MOVEMENT','ERROR',count(*)::bigint,
    'Finished-goods physical movement dated more than 5 minutes in the future'
  from erp.fg_stock_movements where physical_at>clock_timestamp()+interval '5 minutes';

  return query select 'FUTURE_WIP_EVENT','ERROR',count(*)::bigint,
    'WIP stage event dated more than 5 minutes in the future'
  from erp.wip_stage_events where physical_at>clock_timestamp()+interval '5 minutes';

  return query select 'FUTURE_JOURNAL_DATE','ERROR',count(*)::bigint,
    'Journal economic/accounting date is in the future'
  from erp.journal_entries where economic_date>current_date or transaction_date>current_date;

  return query
  with ctl as (select closed_through,updated_at from erp.accounting_period_control where singleton_id=1)
  select 'CLOSED_PERIOD_LATE_POSTING_LEAK','ERROR',count(*)::bigint,
    'Journal posted after the current close operation has an economic date in the closed period but was not shifted to an open accounting date'
  from erp.journal_entries je cross join ctl
  where ctl.closed_through is not null
    and je.posting_at>ctl.updated_at
    and je.economic_date<=ctl.closed_through
    and je.transaction_date<=ctl.closed_through;
end;
$function$;

alter function "erp"."run_v256_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v257_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  perform erp.require_owner_admin();

  return query
  select 'WORK_COMPLETION_OVER_EFFECTIVE_QTY','ERROR',count(*)::bigint,
         'Posted work component completed/payable qty exceeds effective Potongan qty'
  from (
    select e.cutting_group_id,l.work_component_id
    from erp.work_completion_events e
    join erp.work_completion_lines l on l.completion_id=e.id
    join erp.v_cutting_group_totals v on v.cutting_group_id=e.cutting_group_id
    where e.status='POSTED'
    group by e.cutting_group_id,l.work_component_id,v.total_pcs
    having sum(l.qty_completed)>v.total_pcs or sum(l.qty_payable)>v.total_pcs
  ) x;

  return query
  select 'WORK_COMPLETION_BEFORE_PICKUP','ERROR',count(*)::bigint,
         'Posted mandor work event has no pickup source or is dated before Potongan pickup'
  from erp.work_completion_events e
  left join erp.cutting_groups cg on cg.id=e.cutting_group_id
  where e.status='POSTED' and (e.cutting_group_id is null or cg.picked_up_at is null or e.physical_at<cg.picked_up_at);

  return query
  select 'FUTURE_WORK_COMPLETION','ERROR',count(*)::bigint,
         'Posted mandor work event is dated more than 5 minutes in the future'
  from erp.work_completion_events e
  where e.status='POSTED' and e.physical_at>clock_timestamp()+interval '5 minutes';

  return query
  select 'QC_OVER_EFFECTIVE_CUTTING_QTY','ERROR',count(*)::bigint,
         'Posted QC GOOD+BS exceeds effective Potongan quantity'
  from (
    select i.cutting_group_id
    from erp.qc_inspection_items i
    join erp.qc_inspections q on q.id=i.inspection_id
    join erp.v_cutting_group_totals v on v.cutting_group_id=i.cutting_group_id
    where q.status='POSTED'
    group by i.cutting_group_id,v.total_pcs
    having sum(i.qty_good_pcs+i.qty_bs_pcs)>v.total_pcs
  ) x;

  return query
  select 'QC_POSTED_WITHOUT_CUTTING_LINEAGE','ERROR',count(*)::bigint,
         'Posted production QC item has no Potongan lineage'
  from erp.qc_inspection_items i join erp.qc_inspections q on q.id=i.inspection_id
  where q.status='POSTED' and i.cutting_group_id is null;

  return query
  select 'FUTURE_QC','ERROR',count(*)::bigint,
         'Posted QC is dated more than 5 minutes in the future'
  from erp.qc_inspections q where q.status='POSTED' and q.physical_at>clock_timestamp()+interval '5 minutes';

  return query select 'FUTURE_OPENING_BALANCE','ERROR',count(*)::bigint,
    'Posted opening balance has a future opening date'
  from erp.opening_balance_headers where status='POSTED' and opening_date>current_date;

  return query select 'FUTURE_MATERIAL_COST_CORRECTION','ERROR',count(*)::bigint,
    'Posted material cost correction has a future supplier invoice date'
  from erp.material_purchase_cost_corrections where status='POSTED' and invoice_date>current_date;

  return query select 'FUTURE_OPENING_HPP_CORRECTION','ERROR',count(*)::bigint,
    'Opening HPP correction has a future effective date'
  from erp.opening_hpp_corrections where effective_date>current_date;

  return query
  with wip as (
    select po.id,
           coalesce(sum(case when jl.account_id=erp.account_id('WIP') then jl.debit-jl.credit else 0 end),0) as residual
    from erp.production_orders po
    left join erp.journal_lines jl on jl.po_id=po.id
    left join erp.journal_entries je on je.id=jl.journal_entry_id and je.status in('POSTED','REVERSED')
    where po.status='FINISHED'
    group by po.id
  )
  select 'FINISHED_PO_WIP_RESIDUAL','ERROR',count(*)::bigint,
         'FINISHED PO still has non-zero WIP balance after final residual close'
  from wip where abs(residual)>0.01;

  return query
  select 'FINISHED_PO_OPEN_BS','ERROR',count(*)::bigint,
         'FINISHED PO still has unresolved BS case(s)'
  from erp.production_orders po
  where po.status='FINISHED' and exists(
    select 1 from erp.bs_cases b where b.po_id=po.id and b.status in('OPEN','IN_REWORK','PARTIAL')
  );

  return query
  select 'FINISHED_PO_WITHOUT_FG','ERROR',count(*)::bigint,
         'FINISHED PO has no active production finished-goods output'
  from erp.production_orders po
  where po.status='FINISHED' and not exists(
    select 1 from erp.fg_lots fl where fl.po_id=po.id and fl.lot_origin='PRODUCTION'
  );

  return query
  with sent as (
    select po.id,
      coalesce((select sum(ldl.qty_sent_pcs) from erp.laundry_delivery_lines ldl join erp.laundry_deliveries ld on ld.id=ldl.delivery_id where ld.po_id=po.id and ld.status not in('DRAFT','REVERSED')),0) sent_qty,
      coalesce((select sum(lrl.qty_good_received+lrl.qty_bs_laundry) from erp.laundry_receipt_lines lrl join erp.laundry_receipts lr on lr.id=lrl.receipt_id join erp.laundry_deliveries ld on ld.id=lr.delivery_id where ld.po_id=po.id and lr.status='POSTED' and ld.status<>'REVERSED'),0) returned_qty,
      coalesce((select sum(lc.qty_claimed) from erp.laundry_claims lc where lc.delivery_id in(select id from erp.laundry_deliveries where po_id=po.id) and lc.claim_type in('MISSING','STUCK') and lc.status in('SETTLED','WRITTEN_OFF')),0) claimed_qty
    from erp.production_orders po where po.status='FINISHED'
  )
  select 'FINISHED_PO_LAUNDRY_OUTSTANDING','ERROR',count(*)::bigint,
         'FINISHED PO still has unresolved laundry quantity'
  from sent where returned_qty+claimed_qty<sent_qty;
end;
$function$;

alter function "erp"."run_v257_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v258_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  perform erp.require_owner_admin();

  return query
  select 'ACTIVE_FINAL_WIP_CLOSE_ON_NONFINISHED_PO','ERROR',count(*)::bigint,
         'Non-FINISHED PO still has an active PO_WIP_RESIDUAL_CLOSE journal; reopen/correction path did not restore WIP accounting'
  from (
    select distinct e.po_id
    from erp.po_wip_close_events e
    join erp.journal_entries je on je.id=e.journal_entry_id
    join erp.production_orders po on po.id=e.po_id
    where je.source_type='PO_WIP_RESIDUAL_CLOSE' and je.status='POSTED' and po.status<>'FINISHED'
  ) x;
end;
$function$;

alter function "erp"."run_v258_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v259_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  perform erp.require_owner_admin();
  return query select 'PRODUCT_IDENTITY_SAME_ROOT_OVERLAP','ERROR',count(*)::bigint,'One logical SKU root must not have overlapping identity periods' from erp.products a join erp.products b on a.id<b.id and a.identity_root_id=b.identity_root_id and tstzrange(a.effective_from,coalesce(a.effective_to,'infinity'::timestamptz),'[)') && tstzrange(b.effective_from,coalesce(b.effective_to,'infinity'::timestamptz),'[)');
  return query select 'PRODUCT_IDENTITY_SKU_CROSS_ROOT_OVERLAP','ERROR',count(*)::bigint,'Same SKU code must not belong to different logical SKU roots at the same time' from erp.products a join erp.products b on a.id<b.id and a.identity_root_id<>b.identity_root_id and lower(trim(a.sku))=lower(trim(b.sku)) and tstzrange(a.effective_from,coalesce(a.effective_to,'infinity'::timestamptz),'[)') && tstzrange(b.effective_from,coalesce(b.effective_to,'infinity'::timestamptz),'[)');
  return query select 'PRODUCT_IDENTITY_COMBO_CROSS_ROOT_OVERLAP','ERROR',count(*)::bigint,'Model/brand/color/size combination must not map to different logical SKU roots at the same time' from erp.products a join erp.products b on a.id<b.id and a.identity_root_id<>b.identity_root_id and a.model_id=b.model_id and a.brand_id=b.brand_id and lower(trim(a.color_name))=lower(trim(b.color_name)) and a.size_id=b.size_id and tstzrange(a.effective_from,coalesce(a.effective_to,'infinity'::timestamptz),'[)') && tstzrange(b.effective_from,coalesce(b.effective_to,'infinity'::timestamptz),'[)');
  return query select 'PRODUCT_IDENTITY_ROOT_INVALID','ERROR',count(*)::bigint,'Every identity_root_id must point to a root product whose identity_root_id points to itself' from erp.products p join erp.products r on r.id=p.identity_root_id where r.identity_root_id<>r.id;
  return query select 'PRODUCT_SUCCESSOR_CHAIN_MISMATCH','ERROR',count(*)::bigint,'Successor products must stay in the same identity root and start exactly when predecessor ends' from erp.products p join erp.products old on old.id=p.supersedes_product_id where p.identity_root_id<>old.identity_root_id or old.effective_to is distinct from p.effective_from;
  return query select 'PRODUCT_PRICE_OVERLAP','ERROR',count(*)::bigint,'Selling-price versions for one product must not overlap' from erp.product_price_versions a join erp.product_price_versions b on a.id<b.id and a.product_id=b.product_id and tstzrange(a.effective_from,coalesce(a.effective_to,'infinity'::timestamptz),'[)') && tstzrange(b.effective_from,coalesce(b.effective_to,'infinity'::timestamptz),'[)');
  return query select 'WORK_RATE_OVERLAP','ERROR',count(*)::bigint,'Contractor work-rate versions for the same contractor/model/component must not overlap' from erp.contractor_work_rates a join erp.contractor_work_rates b on a.id<b.id and a.contractor_id=b.contractor_id and a.model_id=b.model_id and a.work_component_id=b.work_component_id and tstzrange(a.effective_from,coalesce(a.effective_to,'infinity'::timestamptz),'[)') && tstzrange(b.effective_from,coalesce(b.effective_to,'infinity'::timestamptz),'[)');
  return query select 'CONTRACTOR_ACCESSORY_PRICE_OVERLAP','ERROR',count(*)::bigint,'Accessory selling-price versions for the same contractor/category must not overlap' from erp.contractor_accessory_price_versions a join erp.contractor_accessory_price_versions b on a.id<b.id and a.contractor_id is not distinct from b.contractor_id and a.category_id=b.category_id and tstzrange(a.effective_from,coalesce(a.effective_to,'infinity'::timestamptz),'[)') && tstzrange(b.effective_from,coalesce(b.effective_to,'infinity'::timestamptz),'[)');
  return query select 'CONTRACTOR_MATERIAL_PRICE_OVERLAP','ERROR',count(*)::bigint,'Material selling-price versions for the same contractor/material must not overlap' from erp.contractor_material_price_versions a join erp.contractor_material_price_versions b on a.id<b.id and a.contractor_id is not distinct from b.contractor_id and a.material_id=b.material_id and tstzrange(a.effective_from,coalesce(a.effective_to,'infinity'::timestamptz),'[)') && tstzrange(b.effective_from,coalesce(b.effective_to,'infinity'::timestamptz),'[)');
  return query select 'LAUNDRY_RATE_OVERLAP','ERROR',count(*)::bigint,'Laundry rate versions for the same vendor/process must not overlap' from erp.laundry_vendor_rate_versions a join erp.laundry_vendor_rate_versions b on a.id<b.id and a.vendor_id=b.vendor_id and a.wash_process_id=b.wash_process_id and tstzrange(a.effective_from,coalesce(a.effective_to,'infinity'::timestamptz),'[)') && tstzrange(b.effective_from,coalesce(b.effective_to,'infinity'::timestamptz),'[)');
  return query select 'ACCESSORY_BOM_OVERLAP','ERROR',count(*)::bigint,'Active accessory BOM versions for one SKU must not overlap' from erp.accessory_bom_versions a join erp.accessory_bom_versions b on a.id<b.id and a.product_id=b.product_id and a.is_active and b.is_active and tstzrange(a.effective_from,coalesce(a.effective_to,'infinity'::timestamptz),'[)') && tstzrange(b.effective_from,coalesce(b.effective_to,'infinity'::timestamptz),'[)');
  return query select 'WORK_BOM_OVERLAP','ERROR',count(*)::bigint,'Active Work BOM versions for one model must not overlap' from erp.work_bom_versions a join erp.work_bom_versions b on a.id<b.id and a.model_id=b.model_id and a.is_active and b.is_active and tstzrange(a.effective_from,coalesce(a.effective_to,'infinity'::timestamptz),'[)') && tstzrange(b.effective_from,coalesce(b.effective_to,'infinity'::timestamptz),'[)');
end$function$;

alter function "erp"."run_v259_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v25_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  perform erp.require_owner_admin();

  return query
  select 'BOM_COMMIT_PRODUCT_MISMATCH','ERROR',count(*)::bigint,
         'Committed accessory BOM must belong to the same logical SKU identity root as the committed PO/SKU product'
  from erp.po_accessory_bom_commitments c
  join erp.accessory_bom_versions b on b.id=c.bom_version_id
  join erp.products cp on cp.id=c.product_id
  join erp.products bp on bp.id=b.product_id
  where cp.identity_root_id is distinct from bp.identity_root_id;

  return query
  select 'PO_LOGICAL_SKU_MULTIPLE_BOM_COMMITMENTS','ERROR',count(*)::bigint,
         'One PO + logical SKU identity root must not freeze more than one accessory BOM economics version'
  from (
    select c.po_id,p.identity_root_id
    from erp.po_accessory_bom_commitments c
    join erp.products p on p.id=c.product_id
    group by c.po_id,p.identity_root_id
    having count(distinct c.bom_version_id)>1
  ) x;

  return query
  select 'BOM_COMMIT_PO_MODEL_MISMATCH','ERROR',count(*)::bigint,
         'Committed final SKU model must match production-order model'
  from erp.po_accessory_bom_commitments c
  join erp.production_orders po on po.id=c.po_id
  join erp.products p on p.id=c.product_id
  where p.model_id<>po.model_id;

  return query
  select 'ACCESSORY_SNAPSHOT_COMMIT_MISMATCH','ERROR',count(*)::bigint,
         'Historical accessory snapshot must use the PO/SKU committed BOM version'
  from erp.fg_accessory_cost_snapshots s
  join erp.po_accessory_bom_commitments c on c.po_id=s.po_id and c.product_id=s.product_id
  where s.bom_version_id<>c.bom_version_id;

  return query
  select 'BOM_COMMITTED_BY_PO_START_ONLY','ERROR',count(*)::bigint,
         'Non-empty V2.5 commitments may not be created merely because PO physically started'
  from erp.po_accessory_bom_commitments c
  where c.commit_source='FIRST_FINANCIAL_USE'
    and exists(select 1 from erp.accessory_bom_items abi where abi.bom_version_id=c.bom_version_id)
    and not exists(
      select 1
      from erp.fg_accessory_cost_snapshots s
      where s.po_id=c.po_id and s.product_id=c.product_id and s.bom_version_id=c.bom_version_id
    );

  return query
  select 'MIGRATION_BATCH_ERRORS','WARN',count(*)::bigint,
         'Migration batches currently contain validation-error staging rows'
  from erp.migration_batches b
  where exists(
    select 1 from erp.migration_staging_rows s
    where s.batch_id=b.id and s.validation_status='ERROR'
  );

  return query
  select 'POSTED_MIGRATION_UNAPPLIED_ROWS','ERROR',count(*)::bigint,
         'POSTED migration batches must not retain valid unapplied rows'
  from erp.migration_batches b
  where b.status='POSTED'
    and exists(
      select 1 from erp.migration_staging_rows s
      where s.batch_id=b.id and s.validation_status='VALID' and s.posted_entity_id is null
    );
end;
$function$;

alter function "erp"."run_v25_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v268_financial_report_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_catalog', 'information_schema', 'pg_temp'
AS $function$
begin
  perform erp.require_owner_admin();
  return query
  select r.check_name,r.severity,r.issue_count,r.details
  from erp._v268_financial_report_checks_pre_scope() r
  where r.check_name not in(
    'V268_BROWSER_DIRECT_FINANCIAL_WRITE',
    'V268_BROWSER_DIRECT_LEDGER_OR_INVOICE_WRITE'
  )

  union all
  select 'V268_BROWSER_DIRECT_LEDGER_OR_INVOICE_WRITE','CRITICAL',count(*)::bigint,
         'Browser roles must not directly mutate the ledger or supplier-invoice aggregate; operational DRAFT tables are protected separately by RLS and posted-state guards'
  from information_schema.role_table_grants g
  where g.table_schema='erp'
    and g.table_name in(
      'journal_entries','journal_lines','account_daily_balances',
      'material_supplier_invoices','material_supplier_invoice_lines'
    )
    and g.grantee in('PUBLIC','anon','authenticated')
    and g.privilege_type in('INSERT','UPDATE','DELETE');
end;
$function$;

alter function "erp"."run_v268_financial_report_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v269_cutting_correction_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_catalog', 'information_schema', 'pg_temp'
AS $function$
begin
  perform erp.require_owner_admin();

  return query
  select
    'V269_EFFECTIVE_QTY_NEGATIVE', 'CRITICAL', count(*)::bigint,
    'Effective Potongan quantity may never be negative'
  from erp.v_cutting_group_quantity_detail q
  where q.effective_pcs < 0

  union all
  select
    'V269_EFFECTIVE_BELOW_DOWNSTREAM', 'CRITICAL', count(*)::bigint,
    'Effective Potongan quantity must cover sewing/WIP/laundry/QC/FG/BS evidence'
  from erp.v_cutting_group_quantity_detail q
  where q.effective_pcs < erp.cutting_group_downstream_committed_qty(q.cutting_group_id)

  union all
  select
    'V269_CORRECTION_WITHOUT_LINES', 'CRITICAL', count(*)::bigint,
    'Every posted quantity correction must retain at least one immutable line'
  from erp.cutting_qty_corrections c
  where not exists (
    select 1 from erp.cutting_qty_correction_lines l
    where l.correction_id = c.id
  )

  union all
  select
    'V269_REVERSAL_LINE_MISMATCH', 'CRITICAL', count(*)::bigint,
    'Every reversal must exactly negate its source by Potongan and size slot'
  from (
    select src.id
    from erp.cutting_qty_corrections src
    join erp.cutting_qty_corrections rv on rv.reversal_of_id = src.id
    where exists (
      select 1
      from (
        select
          coalesce(a.cutting_group_id, b.cutting_group_id) as cutting_group_id,
          coalesce(a.size_slot_id, b.size_slot_id) as size_slot_id,
          coalesce(a.qty, 0) + coalesce(b.qty, 0) as net_qty
        from (
          select cutting_group_id, size_slot_id, sum(qty_delta_pcs)::bigint as qty
          from erp.cutting_qty_correction_lines
          where correction_id = src.id
          group by cutting_group_id, size_slot_id
        ) a
        full join (
          select cutting_group_id, size_slot_id, sum(qty_delta_pcs)::bigint as qty
          from erp.cutting_qty_correction_lines
          where correction_id = rv.id
          group by cutting_group_id, size_slot_id
        ) b
          on b.cutting_group_id = a.cutting_group_id
         and b.size_slot_id is not distinct from a.size_slot_id
      ) mismatch
      where mismatch.net_qty <> 0
    )
  ) bad

  union all
  select
    'V269_FUTURE_PHYSICAL_TIME', 'ERROR', count(*)::bigint,
    'Koreksi Potongan physical_at may not be more than five minutes in the future'
  from erp.cutting_qty_corrections c
  where c.physical_at > clock_timestamp() + interval '5 minutes'

  union all
  select
    'V269_LEGACY_RPC_BROWSER_EXECUTE', 'CRITICAL', count(*)::bigint,
    'Browser roles must use idempotent and optimistically locked v2 correction RPCs'
  from information_schema.routine_privileges p
  where p.routine_schema = 'erp'
    and p.routine_name in (
      'post_cutting_qty_correction', 'reverse_cutting_qty_correction'
    )
    and p.grantee in ('PUBLIC','anon','authenticated')
    and p.privilege_type = 'EXECUTE'

  union all
  select
    'V269_DIRECT_CORRECTION_WRITE', 'CRITICAL', count(*)::bigint,
    'Browser roles must not directly mutate append-only cutting correction tables'
  from information_schema.role_table_grants g
  where g.table_schema = 'erp'
    and g.table_name in (
      'cutting_qty_corrections', 'cutting_qty_correction_lines'
    )
    and g.grantee in ('PUBLIC','anon','authenticated')
    and g.privilege_type in ('INSERT','UPDATE','DELETE');
end;
$function$;

alter function "erp"."run_v269_cutting_correction_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v269a_cutting_correction_performance_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_catalog', 'pg_temp'
AS $function$
begin
  perform erp.require_owner_admin();
  return query
  select
    'V269A_REQUIRED_INDEX_MISSING', 'ERROR', count(*)::bigint,
    'Koreksi Potongan downstream floor requires four cutting-group lookup indexes'
  from unnest(array[
    'erp.idx_wip_stage_events_cutting_group_stage',
    'erp.idx_work_completion_events_cutting_group_status',
    'erp.idx_qc_inspection_items_cutting_group_inspection',
    'erp.idx_bs_cases_cutting_group_status'
  ]) expected(index_name)
  where to_regclass(expected.index_name) is null;
end;
$function$;

alter function "erp"."run_v269a_cutting_correction_performance_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_accessory_bom_edit(p_bom_version_id uuid, p_items jsonb, p_effective_from timestamp with time zone DEFAULT clock_timestamp(), p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare b erp.accessory_bom_versions%rowtype;v_last_commit timestamptz;v_eff timestamptz:=coalesce(p_effective_from,clock_timestamp());v_next timestamptz;v_new_end timestamptz;v_new uuid;j jsonb;
begin
  perform erp.require_owner_admin();
  if jsonb_typeof(p_items)<>'array' then raise exception 'BOM accessory items harus berupa array; gunakan [] untuk deklarasi produk tanpa aksesori'; end if;
  select * into b from erp.accessory_bom_versions where id=p_bom_version_id for update;
  if b.id is null then raise exception 'BOM accessory tidak ditemukan'; end if;
  v_last_commit:=erp.accessory_bom_last_committed_at(b.id);
  if v_last_commit is null and not exists(select 1 from erp.po_accessory_bom_commitments where bom_version_id=b.id) then
    delete from erp.accessory_bom_items where bom_version_id=b.id;
    for j in select value from jsonb_array_elements(p_items) loop
      insert into erp.accessory_bom_items(bom_version_id,category_id,qty_per_good_fg_base,hpp_method,hpp_standard_rate,hpp_uom_code,reimbursement_rate,reimbursement_uom_code,notes)
      values(b.id,(j->>'category_id')::uuid,(j->>'qty_per_good_fg_base')::numeric,coalesce(nullif(j->>'hpp_method',''),'CATEGORY_MOVING_AVG'),nullif(j->>'hpp_standard_rate','')::numeric,nullif(j->>'hpp_uom_code',''),coalesce(nullif(j->>'reimbursement_rate','')::numeric,0),nullif(j->>'reimbursement_uom_code',''),j->>'notes');
    end loop;
    update erp.accessory_bom_versions set notes=coalesce(p_notes,notes) where id=b.id;
    insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason,new_data) values('accessory_bom_versions',b.id,'UPDATE',erp.current_app_user_id(),'BOM accessory edited before financial commitment',jsonb_build_object('item_count',jsonb_array_length(p_items),'in_place',true,'explicit_no_accessory',jsonb_array_length(p_items)=0));
    return b.id;
  end if;
  if v_eff<=coalesce(v_last_commit,b.effective_from) or v_eff<=b.effective_from then raise exception 'Tanggal mulai BOM baru harus setelah penggunaan finansial terakhir dan setelah awal versi lama'; end if;
  if b.effective_to is not null and v_eff>=b.effective_to then raise exception 'Tanggal mulai BOM baru harus sebelum akhir versi lama'; end if;
  select min(x.effective_from) into v_next from erp.accessory_bom_versions x where x.product_id=b.product_id and x.id<>b.id and x.effective_from>v_eff;
  v_new_end:=case when b.effective_to is null then v_next when v_next is null then b.effective_to else least(b.effective_to,v_next) end;
  update erp.accessory_bom_versions set effective_to=v_eff where id=b.id;
  insert into erp.accessory_bom_versions(product_id,version_label,effective_from,effective_to,is_active,notes,created_by)
  values(b.product_id,concat(coalesce(b.version_label,'BOM'),' / ',to_char(v_eff,'YYYYMMDD-HH24MI')),v_eff,v_new_end,true,coalesce(p_notes,'Successor BOM from Edit'),erp.current_app_user_id()) returning id into v_new;
  for j in select value from jsonb_array_elements(p_items) loop
    insert into erp.accessory_bom_items(bom_version_id,category_id,qty_per_good_fg_base,hpp_method,hpp_standard_rate,hpp_uom_code,reimbursement_rate,reimbursement_uom_code,notes)
    values(v_new,(j->>'category_id')::uuid,(j->>'qty_per_good_fg_base')::numeric,coalesce(nullif(j->>'hpp_method',''),'CATEGORY_MOVING_AVG'),nullif(j->>'hpp_standard_rate','')::numeric,nullif(j->>'hpp_uom_code',''),coalesce(nullif(j->>'reimbursement_rate','')::numeric,0),nullif(j->>'reimbursement_uom_code',''),j->>'notes');
  end loop;
  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason,new_data) values('accessory_bom_versions',b.id,'UPDATE',erp.current_app_user_id(),'Committed BOM edited by creating successor',jsonb_build_object('successor_bom_version_id',v_new,'effective_from',v_eff,'item_count',jsonb_array_length(p_items),'explicit_no_accessory',jsonb_array_length(p_items)=0));
  return v_new;
end;
$function$;

alter function "erp"."save_accessory_bom_edit"(p_bom_version_id uuid, p_items jsonb, p_effective_from timestamp with time zone, p_notes text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_accessory_category_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_row erp.accessory_categories%rowtype;
  v_active boolean:=coalesce((p_payload->>'is_active')::boolean,true);
begin
  perform erp.require_owner_admin();
  if v_reason is null then raise exception 'change_reason is required';end if;
  if coalesce(btrim(p_payload->>'category_code'),'')='' then raise exception 'category_code is required';end if;
  if coalesce(btrim(p_payload->>'category_name'),'')='' then raise exception 'category_name is required';end if;
  if coalesce(btrim(p_payload->>'base_uom_code'),'')='' then raise exception 'base_uom_code is required';end if;

  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('save_accessory_category_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached;end if;
  perform set_config('app.change_reason',v_reason,true);

  if v_id is null then
    if p_expected_version is not null then raise exception 'expected_version must be null on create';end if;
    insert into erp.accessory_categories(
      category_code,category_name,base_uom_code,is_active,notes
    ) values(
      upper(btrim(p_payload->>'category_code')),
      btrim(p_payload->>'category_name'),
      upper(btrim(p_payload->>'base_uom_code')),
      v_active,nullif(btrim(p_payload->>'notes'),'')
    ) returning * into v_row;
  else
    if p_expected_version is null then raise exception 'expected_version is required on update';end if;
    select * into v_row from erp.accessory_categories where id=v_id for update;
    if v_row.id is null then raise exception 'Accessory category not found';end if;
    if v_row.row_version<>p_expected_version then
      raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_row.row_version;
    end if;
    if not v_active and exists(
      select 1 from erp.materials m
      where m.accessory_category_id=v_id and m.is_active
    ) then raise exception 'Accessory category with active material variants cannot be deactivated';end if;
    update erp.accessory_categories
    set category_code=upper(btrim(p_payload->>'category_code')),
        category_name=btrim(p_payload->>'category_name'),
        base_uom_code=upper(btrim(p_payload->>'base_uom_code')),
        is_active=v_active,
        notes=case when p_payload?'notes' then nullif(btrim(p_payload->>'notes'),'') else notes end,
        updated_at=now()
    where id=v_id returning * into v_row;
  end if;

  v_response:=jsonb_build_object(
    'accessory_category_id',v_row.id,'row_version',v_row.row_version,
    'category_code',v_row.category_code,
    'status',case when v_row.is_active then 'ACTIVE' else 'INACTIVE' end
  );
  return erp._idempotency_complete('save_accessory_category_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."save_accessory_category_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_accessory_material_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_category uuid:=nullif(p_payload->>'accessory_category_id','')::uuid;
  v_base_uom text;
  v_row erp.materials%rowtype;
  v_active boolean:=coalesce((p_payload->>'is_active')::boolean,true);
begin
  perform erp.require_owner_admin();
  if v_reason is null then raise exception 'change_reason is required';end if;
  if coalesce(btrim(p_payload->>'material_sku'),'')='' then raise exception 'material_sku is required';end if;
  if coalesce(btrim(p_payload->>'material_name'),'')='' then raise exception 'material_name is required';end if;
  if v_category is null then raise exception 'accessory_category_id is required';end if;
  select base_uom_code into v_base_uom
  from erp.accessory_categories
  where id=v_category and is_active;
  if v_base_uom is null then raise exception 'Active accessory category is required';end if;

  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('save_accessory_material_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached;end if;
  perform set_config('app.change_reason',v_reason,true);

  if v_id is null then
    if p_expected_version is not null then raise exception 'expected_version must be null on create';end if;
    insert into erp.materials(
      material_sku,material_name,material_type,unit_code,accessory_category_id,is_active
    ) values(
      upper(btrim(p_payload->>'material_sku')),btrim(p_payload->>'material_name'),
      'ACCESSORY',v_base_uom,v_category,v_active
    ) returning * into v_row;
  else
    if p_expected_version is null then raise exception 'expected_version is required on update';end if;
    select * into v_row from erp.materials where id=v_id for update;
    if v_row.id is null or v_row.material_type<>'ACCESSORY' then
      raise exception 'Accessory material not found';
    end if;
    if v_row.row_version<>p_expected_version then
      raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_row.row_version;
    end if;
    if not v_active and abs(v_row.cached_stock_qty)>0.000001 then
      raise exception 'Accessory with non-zero stock cannot be deactivated';
    end if;
    update erp.materials
    set material_sku=upper(btrim(p_payload->>'material_sku')),
        material_name=btrim(p_payload->>'material_name'),
        unit_code=v_base_uom,
        accessory_category_id=v_category,
        is_active=v_active,
        updated_at=now()
    where id=v_id returning * into v_row;
  end if;

  v_response:=jsonb_build_object(
    'material_id',v_row.id,'row_version',v_row.row_version,
    'material_sku',v_row.material_sku,'accessory_category_id',v_row.accessory_category_id,
    'base_uom_code',v_row.unit_code,
    'status',case when v_row.is_active then 'ACTIVE' else 'INACTIVE' end
  );
  return erp._idempotency_complete('save_accessory_material_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."save_accessory_material_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_app_user_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;v_old jsonb;
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_target erp.app_users%rowtype;v_role erp.app_roles%rowtype;
  v_new_active boolean:=coalesce((p_payload->>'is_active')::boolean,true);
  v_new_auth_user_id uuid;v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_actor uuid:=erp.current_app_user_id();
begin
  perform erp.require_permission('settings.access.manage');
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if coalesce(btrim(p_payload->>'full_name'),'')='' then raise exception 'full_name is required'; end if;
  if p_payload ? 'role_id' then
    select * into v_role from erp.app_roles where id=nullif(p_payload->>'role_id','')::uuid;
  else
    select * into v_role from erp.app_roles where role_code=upper(coalesce(
      nullif(btrim(p_payload->>'role_code'),''),nullif(btrim(p_payload->>'role'),'')
    ));
  end if;
  if v_role.id is null or not v_role.is_active then raise exception 'Active app role is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('save_app_user_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;

  if v_id is null then
    if p_expected_version is not null then raise exception 'expected_version must be null when creating a user'; end if;
    v_new_auth_user_id:=nullif(p_payload->>'auth_user_id','')::uuid;
    insert into erp.app_users(auth_user_id,full_name,role,role_id,is_active)
    values(v_new_auth_user_id,btrim(p_payload->>'full_name'),v_role.role_code,v_role.id,v_new_active)
    returning * into v_target;
    v_old:=null;
  else
    if p_expected_version is null then raise exception 'expected_version is required when updating a user'; end if;
    select * into v_target from erp.app_users where id=v_id for update;
    if v_target.id is null then raise exception 'App user not found'; end if;
    if v_target.row_version<>p_expected_version then
      raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_target.row_version;
    end if;
    v_old:=to_jsonb(v_target);
    v_new_auth_user_id:=case when p_payload ? 'auth_user_id'
      then nullif(p_payload->>'auth_user_id','')::uuid else v_target.auth_user_id end;
    update erp.app_users set
      auth_user_id=v_new_auth_user_id,full_name=btrim(p_payload->>'full_name'),
      role=v_role.role_code,role_id=v_role.id,is_active=v_new_active,updated_at=clock_timestamp()
    where id=v_id returning * into v_target;
  end if;
  insert into erp.app_access_audit(entity_type,entity_id,action,old_data,new_data,change_reason,client_request_id,actor_app_user_id)
  values('USER_ACCESS',v_target.id,case when v_old is null then 'ASSIGN' else 'UPDATE' end,
    v_old,to_jsonb(v_target),v_reason,p_client_request_id,v_actor);
  v_response:=jsonb_build_object(
    'app_user_id',v_target.id,'role_id',v_target.role_id,'role',v_target.role,
    'is_active',v_target.is_active,'mapped',v_target.auth_user_id is not null,'row_version',v_target.row_version
  );
  return erp._idempotency_complete('save_app_user_v2',p_client_request_id,v_response);
end
$function$;

alter function "erp"."save_app_user_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_attendance_period_v1(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint, p_preview_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'save_attendance_period_v1';
  v_hash text;
  v_cached jsonb;
  v_period_id uuid := nullif(p_payload->>'period_id', '')::uuid;
  v_contractor_id uuid := nullif(p_payload->>'contractor_id', '')::uuid;
  v_period_number text := nullif(btrim(p_payload->>'period_number'), '');
  v_period_start date := nullif(p_payload->>'period_start', '')::date;
  v_period_end date := nullif(p_payload->>'period_end', '')::date;
  v_pay_date date := nullif(p_payload->>'pay_date', '')::date;
  v_correction_of uuid := nullif(p_payload->>'correction_of_period_id', '')::uuid;
  v_reason text := nullif(btrim(p_payload->>'reason'), '');
  v_lines jsonb := coalesce(p_payload->'attendance', '[]'::jsonb);
  v_period erp.attendance_periods%rowtype;
  v_original erp.attendance_periods%rowtype;
  v_preview jsonb;
  v_response jsonb;
  v_duplicate_count integer;
  r record;
begin
  perform erp.require_internal();

  if v_contractor_id is null or v_period_number is null
     or v_period_start is null or v_period_end is null or v_pay_date is null then
    raise exception 'contractor_id, period_number, period_start, period_end, and pay_date are required';
  end if;
  if v_period_end < v_period_start then raise exception 'period_end cannot precede period_start'; end if;
  if v_reason is null then raise exception 'Attendance change reason is required'; end if;
  if jsonb_typeof(v_lines) <> 'array' then raise exception 'attendance must be a JSON array'; end if;
  if v_correction_of is not null then perform erp.require_owner_admin(); end if;
  if not exists (
    select 1 from erp.contractors c
    where c.id = v_contractor_id and c.contractor_type = 'MANDOR'
  ) then
    raise exception 'Attendance contractor must be an existing MANDOR';
  end if;

  select count(*) - count(distinct (x.worker_id::text || '|' || x.attendance_date::text))
  into v_duplicate_count
  from jsonb_to_recordset(v_lines) as x(
    worker_id uuid,
    attendance_date date,
    status text,
    paid_fraction numeric,
    notes text,
    supersedes_attendance_record_id uuid
  );
  if v_duplicate_count > 0 then
    raise exception 'Duplicate worker/date exists in attendance payload';
  end if;

  for r in
    select *
    from jsonb_to_recordset(v_lines) as x(
      worker_id uuid,
      attendance_date date,
      status text,
      paid_fraction numeric,
      notes text,
      supersedes_attendance_record_id uuid
    )
  loop
    if r.worker_id is null or r.attendance_date is null then
      raise exception 'Each attendance line requires worker_id and attendance_date';
    end if;
    if upper(coalesce(r.status, 'PRESENT')) not in
       ('PRESENT','ABSENT','HALF_DAY','SICK','LEAVE','OFF') then
      raise exception 'Unsupported attendance status %', r.status;
    end if;
    if r.paid_fraction is not null and (r.paid_fraction < 0 or r.paid_fraction > 1) then
      raise exception 'paid_fraction must be between 0 and 1';
    end if;
    if upper(coalesce(r.status, 'PRESENT')) = 'HALF_DAY'
       and coalesce(r.paid_fraction, 0.5) > 0.5 then
      raise exception 'HALF_DAY paid_fraction cannot exceed 0.5';
    end if;
    if r.attendance_date not between v_period_start and v_period_end then
      raise exception 'Attendance date % is outside period', r.attendance_date;
    end if;
    if not exists (
      select 1
      from erp.contractor_workers w
      where w.id = r.worker_id
        and w.contractor_id = v_contractor_id
        and erp.worker_is_employed_on(w.id, r.attendance_date)
    ) then
      raise exception 'Worker % is not eligible on %', r.worker_id, r.attendance_date;
    end if;
  end loop;

  select jsonb_build_object(
    'line_count', count(*),
    'paid_day_equivalent', coalesce(sum(
      case
        when upper(coalesce(x.status, 'PRESENT')) in ('ABSENT','OFF') then 0
        when upper(coalesce(x.status, 'PRESENT')) = 'HALF_DAY' then least(coalesce(x.paid_fraction, 0.5), 0.5)
        else coalesce(x.paid_fraction, 1)
      end
    ), 0),
    'estimated_amount', coalesce(sum(
      erp.require_worker_daily_rate_at(x.worker_id, x.attendance_date) *
      case
        when upper(coalesce(x.status, 'PRESENT')) in ('ABSENT','OFF') then 0
        when upper(coalesce(x.status, 'PRESENT')) = 'HALF_DAY' then least(coalesce(x.paid_fraction, 0.5), 0.5)
        else coalesce(x.paid_fraction, 1)
      end
    ), 0),
    'preview_only', p_preview_only
  ) into v_preview
  from jsonb_to_recordset(v_lines) as x(
    worker_id uuid,
    attendance_date date,
    status text,
    paid_fraction numeric,
    notes text,
    supersedes_attendance_record_id uuid
  );

  if p_preview_only then return v_preview; end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'payload', p_payload,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  perform set_config('app.change_reason', v_reason, true);

  if v_period_id is null then
    if p_expected_version is not null then
      raise exception 'expected_version must be null when creating an attendance period';
    end if;

    if v_correction_of is not null then
      select * into v_original
      from erp.attendance_periods
      where id = v_correction_of
      for update;

      if v_original.id is null or v_original.status <> 'POSTED' then
        raise exception 'Correction source must be a POSTED attendance period';
      end if;
      if v_original.contractor_id <> v_contractor_id
         or v_original.period_start <> v_period_start
         or v_original.period_end <> v_period_end then
        raise exception 'Correction must keep contractor and attendance date range';
      end if;
      if exists (
        select 1
        from erp.payroll_attendance_items pai
        join erp.payroll_settlements ps on ps.id = pai.payroll_id
        join erp.attendance_records ar on ar.id = pai.attendance_record_id
        where ar.attendance_period_id = v_original.id
          and ps.status <> 'REVERSED'
      ) then
        raise exception 'Attendance correction requires its consuming payroll to be reversed first';
      end if;
      if exists (
        select 1
        from erp.attendance_records source_row
        where source_row.attendance_period_id = v_original.id
          and not exists (
            select 1
            from jsonb_to_recordset(v_lines) as x(
              worker_id uuid,
              attendance_date date,
              status text,
              paid_fraction numeric,
              notes text,
              supersedes_attendance_record_id uuid
            )
            where x.worker_id = source_row.worker_id
              and x.attendance_date = source_row.attendance_date
              and x.supersedes_attendance_record_id = source_row.id
          )
      ) then
        raise exception 'Correction must explicitly supersede every source attendance row';
      end if;
    end if;

    insert into erp.attendance_periods(
      period_number, contractor_id, period_start, period_end, pay_date,
      correction_of_period_id, notes, created_by
    ) values (
      v_period_number, v_contractor_id, v_period_start, v_period_end, v_pay_date,
      v_correction_of, nullif(btrim(p_payload->>'notes'), ''), erp.current_app_user_id()
    ) returning * into v_period;
    v_period_id := v_period.id;
  else
    select * into v_period
    from erp.attendance_periods
    where id = v_period_id
    for update;

    if v_period.id is null then raise exception 'Attendance period not found'; end if;
    if v_period.status <> 'DRAFT' then
      raise exception 'Only DRAFT attendance can be saved';
    end if;
    if p_expected_version is null or v_period.row_version <> p_expected_version then
      raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_period.row_version;
    end if;
    if v_period.contractor_id <> v_contractor_id then
      raise exception 'Attendance contractor cannot be changed';
    end if;
    if v_period.correction_of_period_id is not null then
      perform erp.require_owner_admin();
      if v_correction_of is distinct from v_period.correction_of_period_id then
        raise exception 'correction_of_period_id cannot change or be omitted while editing a correction';
      end if;
    end if;
    if exists (
      select 1
      from erp.attendance_records a
      where a.attendance_period_id = v_period.id
        and a.attendance_date not between v_period_start and v_period_end
    ) then
      raise exception 'Attendance period cannot shrink while DRAFT rows exist outside the new date range';
    end if;

    update erp.attendance_periods
    set period_number = v_period_number,
        period_start = v_period_start,
        period_end = v_period_end,
        pay_date = v_pay_date,
        notes = nullif(btrim(p_payload->>'notes'), '')
    where id = v_period_id
    returning * into v_period;
  end if;

  if v_period.correction_of_period_id is null and exists (
    select 1
    from jsonb_to_recordset(v_lines) as x(
      worker_id uuid,
      attendance_date date,
      status text,
      paid_fraction numeric,
      notes text,
      supersedes_attendance_record_id uuid
    )
    where x.supersedes_attendance_record_id is not null
  ) then
    raise exception 'Non-correction attendance cannot declare supersedes lineage';
  end if;

  if v_period.correction_of_period_id is not null and exists (
    select 1
    from erp.attendance_records source_row
    where source_row.attendance_period_id = v_period.correction_of_period_id
      and not exists (
        select 1
        from jsonb_to_recordset(v_lines) as x(
          worker_id uuid,
          attendance_date date,
          status text,
          paid_fraction numeric,
          notes text,
          supersedes_attendance_record_id uuid
        )
        where x.worker_id = source_row.worker_id
          and x.attendance_date = source_row.attendance_date
          and x.supersedes_attendance_record_id = source_row.id
      )
  ) then
    raise exception 'Correction must explicitly supersede every source attendance row';
  end if;

  if v_period.correction_of_period_id is not null and exists (
    select 1
    from jsonb_to_recordset(v_lines) as x(
      worker_id uuid,
      attendance_date date,
      status text,
      paid_fraction numeric,
      notes text,
      supersedes_attendance_record_id uuid
    )
    where not exists (
      select 1
      from erp.attendance_records source_row
      where source_row.attendance_period_id = v_period.correction_of_period_id
        and source_row.id = x.supersedes_attendance_record_id
        and source_row.worker_id = x.worker_id
        and source_row.attendance_date = x.attendance_date
    )
  ) then
    raise exception 'Every correction line must supersede its exact source worker/date row';
  end if;

  for r in
    select *
    from jsonb_to_recordset(v_lines) as x(
      worker_id uuid,
      attendance_date date,
      status text,
      paid_fraction numeric,
      notes text,
      supersedes_attendance_record_id uuid
    )
  loop
    insert into erp.attendance_records(
      contractor_id, worker_id, attendance_date, status, paid_fraction, notes,
      attendance_period_id, record_lifecycle, supersedes_attendance_record_id,
      created_by, updated_by, change_reason
    ) values (
      v_contractor_id, r.worker_id, r.attendance_date,
      upper(coalesce(r.status, 'PRESENT')),
      case
        when upper(coalesce(r.status, 'PRESENT')) in ('ABSENT','OFF') then 0
        when upper(coalesce(r.status, 'PRESENT')) = 'HALF_DAY'
          then least(coalesce(r.paid_fraction, 0.5), 0.5)
        else coalesce(r.paid_fraction, 1)
      end,
      r.notes,
      v_period_id, 'DRAFT', r.supersedes_attendance_record_id,
      erp.current_app_user_id(), erp.current_app_user_id(), v_reason
    )
    on conflict (attendance_period_id, worker_id, attendance_date)
      where attendance_period_id is not null
    do update set
      status = excluded.status,
      paid_fraction = excluded.paid_fraction,
      notes = excluded.notes,
      supersedes_attendance_record_id = excluded.supersedes_attendance_record_id,
      updated_by = erp.current_app_user_id(),
      change_reason = v_reason;
  end loop;

  -- The payload is a full DRAFT matrix snapshot. A missing cell is unrecorded,
  -- never silently inferred as ABSENT/OFF. DRAFT-only removal is audited by the
  -- existing row audit trigger; POSTED history remains undeletable.
  delete from erp.attendance_records a
  where a.attendance_period_id = v_period_id
    and a.record_lifecycle = 'DRAFT'
    and not exists (
      select 1
      from jsonb_to_recordset(v_lines) as x(
        worker_id uuid,
        attendance_date date,
        status text,
        paid_fraction numeric,
        notes text,
        supersedes_attendance_record_id uuid
      )
      where x.worker_id = a.worker_id
        and x.attendance_date = a.attendance_date
    );

  -- Detail writes are part of the period document and advance its optimistic
  -- lock even when header fields did not change.
  if v_period.row_version = coalesce(p_expected_version, v_period.row_version) then
    update erp.attendance_periods
    set updated_at = clock_timestamp()
    where id = v_period_id
    returning * into v_period;
  else
    select * into v_period from erp.attendance_periods where id = v_period_id;
  end if;

  v_response := jsonb_build_object(
    'period_id', v_period.id,
    'period_number', v_period.period_number,
    'status', v_period.status,
    'row_version', v_period.row_version,
    'preview', v_preview - 'preview_only',
    'attendance_required', (
      select c.attendance_required from erp.contractors c where c.id = v_contractor_id
    )
  );

  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."save_attendance_period_v1"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint, p_preview_only boolean) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_contractor_material_issue_draft_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_action text:=upper(coalesce(nullif(btrim(p_payload->>'action'),''),'SAVE'));
  v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  h erp.contractor_material_issues%rowtype;v_line jsonb;v_type text;v_roll uuid;v_qty numeric;
begin
  perform erp.require_internal();
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if v_action not in('SAVE','DELETE') then raise exception 'action must be SAVE or DELETE'; end if;
  if v_action='SAVE' and coalesce(jsonb_typeof(p_payload->'items'),'null')<>'array' then raise exception 'items must be a JSON array'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('save_contractor_material_issue_draft_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',v_reason,true);
  if v_id is null then
    if v_action='DELETE' then raise exception 'Issue id is required for DELETE'; end if;
    if p_expected_version is not null then raise exception 'expected_version must be null on create'; end if;
    insert into erp.contractor_material_issues(
      issue_number,contractor_id,po_id,physical_at,status,notes,created_by,location_id
    ) values(
      btrim(p_payload->>'issue_number'),(p_payload->>'contractor_id')::uuid,
      nullif(p_payload->>'po_id','')::uuid,(p_payload->>'physical_at')::timestamptz,
      'DRAFT',nullif(btrim(p_payload->>'notes'),''),erp.current_app_user_id(),
      (p_payload->>'location_id')::uuid
    ) returning * into h;v_id:=h.id;
  else
    if p_expected_version is null then raise exception 'expected_version is required'; end if;
    select * into h from erp.contractor_material_issues where id=v_id for update;
    if h.id is null then raise exception 'Contractor material issue not found'; end if;
    if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
    if h.status<>'DRAFT' then raise exception 'Only DRAFT contractor issue can be saved/deleted'; end if;
    if v_action='DELETE' then
      delete from erp.contractor_material_issues where id=v_id;
      v_response:=jsonb_build_object('contractor_material_issue_id',v_id,'status','DELETED');
      return erp._idempotency_complete('save_contractor_material_issue_draft_v2',p_client_request_id,v_response);
    end if;
    update erp.contractor_material_issues
    set issue_number=coalesce(nullif(btrim(p_payload->>'issue_number'),''),h.issue_number),
        contractor_id=case when p_payload?'contractor_id' then (p_payload->>'contractor_id')::uuid else h.contractor_id end,
        po_id=case when p_payload?'po_id' then nullif(p_payload->>'po_id','')::uuid else h.po_id end,
        physical_at=coalesce(nullif(p_payload->>'physical_at','')::timestamptz,h.physical_at),
        location_id=case when p_payload?'location_id' then (p_payload->>'location_id')::uuid else h.location_id end,
        notes=case when p_payload?'notes' then nullif(btrim(p_payload->>'notes'),'') else h.notes end
    where id=v_id returning * into h;
  end if;
  if jsonb_array_length(p_payload->'items')=0 then raise exception 'At least one contractor issue line is required'; end if;
  if not exists(select 1 from erp.locations l where l.id=h.location_id and l.is_active and l.location_type='RAW_MATERIAL_WAREHOUSE') then
    raise exception 'Contractor issue location must be an active raw-material warehouse';
  end if;
  delete from erp.contractor_material_issue_items where issue_id=v_id;
  for v_line in select value from jsonb_array_elements(p_payload->'items') loop
    select material_type into v_type from erp.materials
    where id=(v_line->>'material_id')::uuid and is_active;
    if v_type is null then raise exception 'Active material is required'; end if;
    v_roll:=nullif(v_line->>'roll_id','')::uuid;
    if v_type='FABRIC' and v_roll is null then raise exception 'FABRIC contractor issue requires roll_id'; end if;
    if v_type<>'FABRIC' and v_roll is not null then raise exception 'Only FABRIC may use roll_id'; end if;
    v_qty:=coalesce(nullif(v_line->>'qty','')::numeric,nullif(v_line->>'transaction_qty','')::numeric);
    -- The normalizer overwrites selling price/version and reconciles transaction
    -- UOM to base quantity. Client-supplied price fields are never accepted.
    insert into erp.contractor_material_issue_items(
      id,issue_id,material_id,roll_id,qty,unit_sale_price_snapshot,
      notes,transaction_qty
    ) values(
      coalesce(nullif(v_line->>'id','')::uuid,gen_random_uuid()),v_id,
      (v_line->>'material_id')::uuid,v_roll,v_qty,0,
      nullif(btrim(v_line->>'notes'),''),nullif(v_line->>'transaction_qty','')::numeric
    );
  end loop;
  select * into h from erp.contractor_material_issues where id=v_id;
  v_response:=jsonb_build_object(
    'contractor_material_issue_id',h.id,'status',h.status,'row_version',h.row_version,
    'item_count',(select count(*) from erp.contractor_material_issue_items i where i.issue_id=v_id),
    'base_qty_total',(select sum(i.qty) from erp.contractor_material_issue_items i where i.issue_id=v_id),
    'receivable_total',(select sum(i.total_receivable) from erp.contractor_material_issue_items i where i.issue_id=v_id)
  );
  return erp._idempotency_complete('save_contractor_material_issue_draft_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."save_contractor_material_issue_draft_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_cutting_batch_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_id uuid := nullif(p_payload->>'id', '')::uuid;
  v_action text := upper(coalesce(nullif(btrim(p_payload->>'action'), ''), 'SAVE'));
  v_reason text := nullif(btrim(p_payload->>'change_reason'), '');
  v_batch erp.cutting_batches%rowtype;
begin
  perform erp.require_internal();
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if v_action not in ('SAVE','DELETE') then raise exception 'Invalid cutting batch action'; end if;

  v_hash := erp._request_hash(jsonb_build_object('payload', p_payload, 'expected_version', p_expected_version));
  v_cached := erp._idempotency_begin('save_cutting_batch_v2', p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason', v_reason, true);

  if v_id is null then
    if v_action = 'DELETE' then raise exception 'Batch id is required for DELETE'; end if;
    if p_expected_version is not null then raise exception 'expected_version must be null when creating a batch'; end if;
    if nullif(p_payload->>'po_id', '')::uuid is null then raise exception 'po_id is required'; end if;
    if coalesce(btrim(p_payload->>'batch_number'), '') = '' then raise exception 'batch_number is required'; end if;
    if nullif(p_payload->>'cut_at', '')::timestamptz is null then raise exception 'cut_at is required'; end if;
    insert into erp.cutting_batches(
      po_id, batch_number, cut_at, status, notes, created_by
    ) values (
      (p_payload->>'po_id')::uuid, btrim(p_payload->>'batch_number'),
      (p_payload->>'cut_at')::timestamptz,
      upper(coalesce(nullif(btrim(p_payload->>'status'), ''), 'OPEN')),
      nullif(btrim(p_payload->>'notes'), ''), erp.current_app_user_id()
    ) returning * into v_batch;
  else
    if p_expected_version is null then raise exception 'expected_version is required'; end if;
    select * into v_batch from erp.cutting_batches where id = v_id for update;
    if v_batch.id is null then raise exception 'Cutting batch not found'; end if;
    if v_batch.row_version <> p_expected_version then
      raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_batch.row_version;
    end if;
    if v_action = 'DELETE' then
      if exists(select 1 from erp.cutting_groups where cutting_batch_id = v_id) then
        raise exception 'Delete or reassign eligible Potongan before deleting the batch';
      end if;
      if exists(select 1 from erp.cutting_qty_corrections where cutting_batch_id = v_id) then
        raise exception 'Batch with posted quantity corrections cannot be deleted';
      end if;
      delete from erp.cutting_batches where id = v_id;
      v_response := jsonb_build_object('cutting_batch_id', v_id, 'status', 'DELETED');
      return erp._idempotency_complete('save_cutting_batch_v2', p_client_request_id, v_response);
    end if;

    update erp.cutting_batches
    set po_id = case when p_payload ? 'po_id' then nullif(p_payload->>'po_id', '')::uuid else v_batch.po_id end,
        batch_number = coalesce(nullif(btrim(p_payload->>'batch_number'), ''), v_batch.batch_number),
        cut_at = coalesce(nullif(p_payload->>'cut_at', '')::timestamptz, v_batch.cut_at),
        status = upper(coalesce(nullif(btrim(p_payload->>'status'), ''), v_batch.status)),
        notes = case when p_payload ? 'notes' then nullif(btrim(p_payload->>'notes'), '') else v_batch.notes end,
        updated_at = now()
    where id = v_id
    returning * into v_batch;
  end if;

  v_response := jsonb_build_object(
    'cutting_batch_id', v_batch.id, 'status', v_batch.status,
    'row_version', v_batch.row_version
  );
  return erp._idempotency_complete('save_cutting_batch_v2', p_client_request_id, v_response);
end;
$function$;

alter function "erp"."save_cutting_batch_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_cutting_group_before_sewing_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_id uuid := nullif(p_payload->>'id', '')::uuid;
  v_action text := upper(coalesce(nullif(btrim(p_payload->>'action'), ''), 'SAVE'));
  v_reason text := nullif(btrim(p_payload->>'change_reason'), '');
  v_group erp.cutting_groups%rowtype;
  v_slot jsonb;
begin
  perform erp.require_internal();
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if v_action not in ('SAVE','DELETE') then raise exception 'Invalid cutting group action'; end if;

  v_hash := erp._request_hash(jsonb_build_object('payload', p_payload, 'expected_version', p_expected_version));
  v_cached := erp._idempotency_begin('save_cutting_group_before_sewing_v2', p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason', v_reason, true);

  if v_id is null then
    if v_action = 'DELETE' then raise exception 'Potongan id is required for DELETE'; end if;
    if p_expected_version is not null then raise exception 'expected_version must be null when creating Potongan'; end if;
    if nullif(p_payload->>'po_id', '')::uuid is null then raise exception 'po_id is required'; end if;
    if coalesce(btrim(p_payload->>'group_number'), '') = '' then raise exception 'group_number is required'; end if;
    if nullif(p_payload->>'cut_at', '')::timestamptz is null then raise exception 'cut_at is required'; end if;
    insert into erp.cutting_groups(
      po_id, group_number, cut_at, executor_name, picked_up_at, status,
      code, pattern_type, notes, cutting_batch_id
    ) values (
      (p_payload->>'po_id')::uuid, btrim(p_payload->>'group_number'),
      (p_payload->>'cut_at')::timestamptz,
      nullif(btrim(p_payload->>'executor_name'), ''),
      nullif(p_payload->>'picked_up_at', '')::timestamptz,
      case when nullif(p_payload->>'picked_up_at', '')::timestamptz is null then 'CUT' else 'PICKED_UP' end,
      nullif(btrim(p_payload->>'code'), ''), nullif(btrim(p_payload->>'pattern_type'), ''),
      nullif(btrim(p_payload->>'notes'), ''), nullif(p_payload->>'cutting_batch_id', '')::uuid
    ) returning * into v_group;
    v_id := v_group.id;
  else
    if p_expected_version is null then raise exception 'expected_version is required'; end if;
    select * into v_group from erp.cutting_groups where id = v_id for update;
    if v_group.id is null then raise exception 'Potongan not found'; end if;
    if v_group.row_version <> p_expected_version then
      raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_group.row_version;
    end if;
    if not erp.is_cutting_group_presewing_reversible(v_id) then
      raise exception 'Potongan sudah dijahit/dipakai fisik atau finansial; gunakan correction/reversal';
    end if;

    if v_action = 'DELETE' then
      delete from erp.cutting_groups where id = v_id;
      v_response := jsonb_build_object('cutting_group_id', v_id, 'status', 'DELETED');
      return erp._idempotency_complete('save_cutting_group_before_sewing_v2', p_client_request_id, v_response);
    end if;

    update erp.cutting_groups
    set po_id = case when p_payload ? 'po_id' then nullif(p_payload->>'po_id', '')::uuid else v_group.po_id end,
        group_number = coalesce(nullif(btrim(p_payload->>'group_number'), ''), v_group.group_number),
        cut_at = coalesce(nullif(p_payload->>'cut_at', '')::timestamptz, v_group.cut_at),
        executor_name = case when p_payload ? 'executor_name' then nullif(btrim(p_payload->>'executor_name'), '') else v_group.executor_name end,
        picked_up_at = case when p_payload ? 'picked_up_at' then nullif(p_payload->>'picked_up_at', '')::timestamptz else v_group.picked_up_at end,
        status = case
          when (case when p_payload ? 'picked_up_at' then nullif(p_payload->>'picked_up_at', '')::timestamptz else v_group.picked_up_at end) is null
            then 'CUT' else 'PICKED_UP' end,
        code = case when p_payload ? 'code' then nullif(btrim(p_payload->>'code'), '') else v_group.code end,
        pattern_type = case when p_payload ? 'pattern_type' then nullif(btrim(p_payload->>'pattern_type'), '') else v_group.pattern_type end,
        notes = case when p_payload ? 'notes' then nullif(btrim(p_payload->>'notes'), '') else v_group.notes end,
        cutting_batch_id = case when p_payload ? 'cutting_batch_id' then nullif(p_payload->>'cutting_batch_id', '')::uuid else v_group.cutting_batch_id end,
        updated_at = now()
    where id = v_id
    returning * into v_group;
  end if;

  if p_payload ? 'size_slots' then
    if jsonb_typeof(p_payload->'size_slots') <> 'array' then raise exception 'size_slots must be an array'; end if;
    delete from erp.cutting_group_size_slots where cutting_group_id = v_id;
    for v_slot in select value from jsonb_array_elements(p_payload->'size_slots') loop
      insert into erp.cutting_group_size_slots(
        id, cutting_group_id, slot_no, size_id, drawing_no, label_override
      ) values (
        coalesce(nullif(v_slot->>'id', '')::uuid, gen_random_uuid()),
        v_id, (v_slot->>'slot_no')::integer, (v_slot->>'size_id')::uuid,
        (v_slot->>'drawing_no')::integer, nullif(btrim(v_slot->>'label_override'), '')
      );
    end loop;
    update erp.cutting_groups set updated_at = now() where id = v_id returning * into v_group;
  end if;

  v_response := jsonb_build_object(
    'cutting_group_id', v_group.id,
    'status', v_group.status,
    'row_version', v_group.row_version,
    'presewing_reversible', erp.is_cutting_group_presewing_reversible(v_group.id)
  );
  return erp._idempotency_complete('save_cutting_group_before_sewing_v2', p_client_request_id, v_response);
end;
$function$;

alter function "erp"."save_cutting_group_before_sewing_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_fabric_master_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_id uuid := nullif(p_payload->>'id', '')::uuid;
  v_material erp.materials%rowtype;
  v_profile jsonb := coalesce(p_payload->'profile', '{}'::jsonb);
  v_reason text := nullif(btrim(p_payload->>'change_reason'), '');
  v_is_active boolean := coalesce((p_payload->>'is_active')::boolean, true);
begin
  perform erp.require_owner_admin();
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if coalesce(btrim(p_payload->>'material_sku'), '') = '' then raise exception 'material_sku is required'; end if;
  if coalesce(btrim(p_payload->>'material_name'), '') = '' then raise exception 'material_name is required'; end if;
  if coalesce(btrim(p_payload->>'unit_code'), '') = '' then raise exception 'unit_code is required'; end if;

  v_hash := erp._request_hash(jsonb_build_object('payload', p_payload, 'expected_version', p_expected_version));
  v_cached := erp._idempotency_begin('save_fabric_master_v2', p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason', v_reason, true);

  if v_id is null then
    if p_expected_version is not null then
      raise exception 'expected_version must be null when creating a fabric';
    end if;
    insert into erp.materials(
      material_sku, material_name, material_type, unit_code, is_active
    ) values (
      btrim(p_payload->>'material_sku'), btrim(p_payload->>'material_name'),
      'FABRIC', upper(btrim(p_payload->>'unit_code')), v_is_active
    ) returning * into v_material;
    v_id := v_material.id;
  else
    if p_expected_version is null then raise exception 'expected_version is required when updating a fabric'; end if;
    select * into v_material from erp.materials where id = v_id for update;
    if v_material.id is null then raise exception 'Fabric material not found'; end if;
    if v_material.material_type <> 'FABRIC' then raise exception 'Material is not FABRIC'; end if;
    if v_material.row_version <> p_expected_version then
      raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_material.row_version;
    end if;
    if not v_is_active and abs(v_material.cached_stock_qty) > 0.000001 then
      raise exception 'Fabric with non-zero stock cannot be deactivated';
    end if;
    update erp.materials
    set material_sku = btrim(p_payload->>'material_sku'),
        material_name = btrim(p_payload->>'material_name'),
        unit_code = upper(btrim(p_payload->>'unit_code')),
        is_active = v_is_active,
        updated_at = now()
    where id = v_id
    returning * into v_material;
  end if;

  insert into erp.fabric_master_profiles(
    material_id, fabric_category, composition, construction, color_name,
    width_cm, gsm, minimum_stock_qty, preferred_supplier_id, notes,
    created_by, updated_by
  ) values (
    v_id,
    nullif(btrim(v_profile->>'fabric_category'), ''),
    nullif(btrim(v_profile->>'composition'), ''),
    nullif(btrim(v_profile->>'construction'), ''),
    nullif(btrim(v_profile->>'color_name'), ''),
    nullif(v_profile->>'width_cm', '')::numeric,
    nullif(v_profile->>'gsm', '')::numeric,
    coalesce(nullif(v_profile->>'minimum_stock_qty', '')::numeric, 0),
    nullif(v_profile->>'preferred_supplier_id', '')::uuid,
    nullif(btrim(v_profile->>'notes'), ''),
    erp.current_app_user_id(), erp.current_app_user_id()
  )
  on conflict (material_id) do update
  set fabric_category = excluded.fabric_category,
      composition = excluded.composition,
      construction = excluded.construction,
      color_name = excluded.color_name,
      width_cm = excluded.width_cm,
      gsm = excluded.gsm,
      minimum_stock_qty = excluded.minimum_stock_qty,
      preferred_supplier_id = excluded.preferred_supplier_id,
      notes = excluded.notes,
      updated_by = erp.current_app_user_id(),
      updated_at = now();

  select * into v_material from erp.materials where id = v_id;
  v_response := jsonb_build_object(
    'material_id', v_id,
    'row_version', v_material.row_version,
    'material_sku', v_material.material_sku,
    'status', case when v_material.is_active then 'ACTIVE' else 'INACTIVE' end
  );
  return erp._idempotency_complete('save_fabric_master_v2', p_client_request_id, v_response);
end;
$function$;

alter function "erp"."save_fabric_master_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_fg_adjustment_draft_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_action text:=upper(coalesce(nullif(btrim(p_payload->>'action'),''),'SAVE'));
  v_change_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_header erp.fg_adjustments%rowtype;
  v_line jsonb;v_lot erp.fg_lots%rowtype;v_qty integer;v_quality text;
begin
  perform erp.require_owner_admin();
  if v_change_reason is null then raise exception 'change_reason is required';end if;
  if v_action not in('SAVE','DELETE') then raise exception 'action must be SAVE or DELETE';end if;
  if v_action='SAVE' and coalesce(jsonb_typeof(p_payload->'items'),'null')<>'array' then
    raise exception 'items must be a JSON array';
  end if;

  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('save_fg_adjustment_draft_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached;end if;
  perform set_config('app.change_reason',v_change_reason,true);

  if v_id is null then
    if v_action='DELETE' then raise exception 'FG adjustment id is required for DELETE';end if;
    if p_expected_version is not null then raise exception 'expected_version must be null on create';end if;
    insert into erp.fg_adjustments(
      adjustment_number,location_id,physical_at,reason_code,reason,status,notes,created_by
    ) values(
      btrim(p_payload->>'adjustment_number'),(p_payload->>'location_id')::uuid,
      (p_payload->>'physical_at')::timestamptz,upper(btrim(p_payload->>'reason_code')),
      btrim(p_payload->>'reason'),'DRAFT',nullif(btrim(p_payload->>'notes'),''),
      erp.current_app_user_id()
    ) returning * into v_header;
    v_id:=v_header.id;
  else
    if p_expected_version is null then raise exception 'expected_version is required on update';end if;
    select * into v_header from erp.fg_adjustments where id=v_id for update;
    if v_header.id is null then raise exception 'FG adjustment not found';end if;
    if v_header.row_version<>p_expected_version then
      raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_header.row_version;
    end if;
    if v_header.status<>'DRAFT' then raise exception 'Only DRAFT FG adjustment can be saved/deleted';end if;
    if v_action='DELETE' then
      delete from erp.fg_adjustments where id=v_id;
      v_response:=jsonb_build_object('fg_adjustment_id',v_id,'status','DELETED');
      return erp._idempotency_complete('save_fg_adjustment_draft_v2',p_client_request_id,v_response);
    end if;
    update erp.fg_adjustments
    set adjustment_number=coalesce(nullif(btrim(p_payload->>'adjustment_number'),''),v_header.adjustment_number),
        location_id=case when p_payload?'location_id' then (p_payload->>'location_id')::uuid else v_header.location_id end,
        physical_at=coalesce(nullif(p_payload->>'physical_at','')::timestamptz,v_header.physical_at),
        reason_code=upper(coalesce(nullif(btrim(p_payload->>'reason_code'),''),v_header.reason_code)),
        reason=coalesce(nullif(btrim(p_payload->>'reason'),''),v_header.reason),
        notes=case when p_payload?'notes' then nullif(btrim(p_payload->>'notes'),'') else v_header.notes end
    where id=v_id returning * into v_header;
  end if;

  if nullif(btrim(v_header.reason),'') is null then raise exception 'reason is required';end if;
  if not exists(
    select 1 from erp.locations l
    where l.id=v_header.location_id and l.is_active and l.location_type='FG_WAREHOUSE'
  ) then raise exception 'FG adjustment location must be an active FG warehouse';end if;
  if jsonb_array_length(p_payload->'items')=0 then raise exception 'At least one FG adjustment line is required';end if;

  delete from erp.fg_adjustment_items where adjustment_id=v_id;
  for v_line in select value from jsonb_array_elements(p_payload->'items') loop
    select * into v_lot from erp.fg_lots where id=(v_line->>'lot_id')::uuid;
    if v_lot.id is null then raise exception 'FG lot not found';end if;
    if v_line?'product_id' and nullif(v_line->>'product_id','')::uuid is distinct from v_lot.product_id then
      raise exception 'FG adjustment product must match the lot product';
    end if;
    v_qty:=(v_line->>'qty_signed')::integer;
    if v_qty=0 then raise exception 'qty_signed cannot be zero';end if;
    v_quality:=upper(coalesce(nullif(btrim(v_line->>'quality_grade'),''),'GRADE_A'));
    insert into erp.fg_adjustment_items(
      id,adjustment_id,lot_id,product_id,quality_grade,qty_signed,unit_hpp_snapshot,notes
    ) values(
      coalesce(nullif(v_line->>'id','')::uuid,gen_random_uuid()),v_id,v_lot.id,
      v_lot.product_id,v_quality,v_qty,0,nullif(btrim(v_line->>'notes'),'')
    );
  end loop;

  select * into v_header from erp.fg_adjustments where id=v_id;
  v_response:=jsonb_build_object(
    'fg_adjustment_id',v_header.id,'status',v_header.status,
    'row_version',v_header.row_version,
    'item_count',(select count(*) from erp.fg_adjustment_items where adjustment_id=v_id),
    'net_qty_pcs',(select sum(qty_signed) from erp.fg_adjustment_items where adjustment_id=v_id)
  );
  return erp._idempotency_complete('save_fg_adjustment_draft_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."save_fg_adjustment_draft_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_laundry_claim_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_action text:=upper(coalesce(nullif(p_payload->>'action',''),'SAVE'));
  v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_claim erp.laundry_claims%rowtype;
  v_target_status text;
begin
  perform erp.require_internal();
  if v_action not in('SAVE','REJECT','REOPEN') then
    raise exception 'Claim action must be SAVE, REJECT, or REOPEN';
  end if;
  if v_reason is null then raise exception 'change_reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('save_laundry_claim_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',v_reason,true);

  if v_id is null then
    if v_action<>'SAVE' then raise exception 'Create a claim with SAVE first'; end if;
    if p_expected_version is not null then raise exception 'expected_version must be null when creating a claim'; end if;
    if coalesce(btrim(p_payload->>'claim_number'),'')='' then raise exception 'claim_number is required'; end if;
    if nullif(p_payload->>'opened_at','')::timestamptz>clock_timestamp()+interval '5 minutes' then
      raise exception 'Claim opened_at cannot be in the future';
    end if;
    insert into erp.laundry_claims(
      claim_number,vendor_id,delivery_id,receipt_line_id,qty_claimed,claim_type,
      compensation_amount,status,opened_at,resolution_date,notes
    ) values(
      btrim(p_payload->>'claim_number'),(p_payload->>'vendor_id')::uuid,
      nullif(p_payload->>'delivery_id','')::uuid,nullif(p_payload->>'receipt_line_id','')::uuid,
      (p_payload->>'qty_claimed')::integer,upper(p_payload->>'claim_type'),
      coalesce(nullif(p_payload->>'compensation_amount','')::numeric,0),'OPEN',
      coalesce(nullif(p_payload->>'opened_at','')::timestamptz,now()),
      nullif(p_payload->>'resolution_date','')::date,nullif(btrim(p_payload->>'notes'),'')
    ) returning * into v_claim;
  else
    if p_expected_version is null then raise exception 'expected_version is required'; end if;
    select * into v_claim from erp.laundry_claims where id=v_id for update;
    if v_claim.id is null then raise exception 'Laundry claim not found'; end if;
    if v_claim.row_version<>p_expected_version then
      raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_claim.row_version;
    end if;
    if v_claim.status in('SETTLED','WRITTEN_OFF') then
      raise exception 'Final claim is locked; use reverse_laundry_claim_resolution first';
    end if;
    if v_action='REOPEN' then
      perform erp.require_owner_admin();v_target_status:='OPEN';
    elsif v_action='REJECT' then v_target_status:='REJECTED';
    else
      if v_claim.status='REJECTED' then raise exception 'Rejected claim requires REOPEN by OWNER/ADMIN'; end if;
      v_target_status:=case when upper(coalesce(nullif(p_payload->>'status',''),v_claim.status))='ACCEPTED'
        then 'ACCEPTED' else 'OPEN' end;
    end if;
    update erp.laundry_claims
    set claim_number=coalesce(nullif(btrim(p_payload->>'claim_number'),''),v_claim.claim_number),
        vendor_id=case when p_payload?'vendor_id' then (p_payload->>'vendor_id')::uuid else v_claim.vendor_id end,
        delivery_id=case when p_payload?'delivery_id' then nullif(p_payload->>'delivery_id','')::uuid else v_claim.delivery_id end,
        receipt_line_id=case when p_payload?'receipt_line_id' then nullif(p_payload->>'receipt_line_id','')::uuid else v_claim.receipt_line_id end,
        qty_claimed=coalesce(nullif(p_payload->>'qty_claimed','')::integer,v_claim.qty_claimed),
        claim_type=upper(coalesce(nullif(p_payload->>'claim_type',''),v_claim.claim_type)),
        compensation_amount=coalesce(nullif(p_payload->>'compensation_amount','')::numeric,v_claim.compensation_amount),
        status=v_target_status,
        opened_at=coalesce(nullif(p_payload->>'opened_at','')::timestamptz,v_claim.opened_at),
        resolution_date=case when p_payload?'resolution_date' then nullif(p_payload->>'resolution_date','')::date else v_claim.resolution_date end,
        notes=case when p_payload?'notes' then nullif(btrim(p_payload->>'notes'),'') else v_claim.notes end
    where id=v_claim.id returning * into v_claim;
  end if;
  v_response:=jsonb_build_object(
    'laundry_claim_id',v_claim.id,'claim_number',v_claim.claim_number,
    'status',v_claim.status,'row_version',v_claim.row_version,
    'qty_claimed',v_claim.qty_claimed,'compensation_amount',v_claim.compensation_amount
  );
  return erp._idempotency_complete('save_laundry_claim_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."save_laundry_claim_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_laundry_receipt_draft_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_receipt erp.laundry_receipts%rowtype;
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_action text:=upper(coalesce(nullif(btrim(p_payload->>'action'),''),'SAVE'));
  v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_line jsonb;
  v_allocation jsonb;
  v_line_id uuid;
begin
  perform erp.require_internal();
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if v_action not in ('SAVE','DELETE') then raise exception 'Invalid laundry receipt action'; end if;
  v_hash:=erp._request_hash(jsonb_build_object(
    'payload',p_payload,'expected_version',p_expected_version
  ));
  v_cached:=erp._idempotency_begin('save_laundry_receipt_draft_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',v_reason,true);

  if v_id is null then
    if v_action='DELETE' then raise exception 'Laundry receipt id is required for DELETE'; end if;
    if p_expected_version is not null then raise exception 'expected_version must be null when creating a receipt'; end if;
    if coalesce(btrim(p_payload->>'receipt_number'),'')='' then raise exception 'receipt_number is required'; end if;
    insert into erp.laundry_receipts(
      receipt_number,delivery_id,physical_at,status,created_by
    ) values(
      btrim(p_payload->>'receipt_number'),(p_payload->>'delivery_id')::uuid,
      (p_payload->>'physical_at')::timestamptz,'DRAFT',erp.current_app_user_id()
    ) returning * into v_receipt;
    v_id:=v_receipt.id;
  else
    if p_expected_version is null then raise exception 'expected_version is required'; end if;
    select * into v_receipt from erp.laundry_receipts where id=v_id for update;
    if v_receipt.id is null then raise exception 'Laundry receipt not found'; end if;
    if v_receipt.status<>'DRAFT' then raise exception 'Posted receipt is locked; use reversal/correction'; end if;
    if v_receipt.row_version<>p_expected_version then
      raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_receipt.row_version;
    end if;
    if v_action='DELETE' then
      delete from erp.laundry_receipts where id=v_id;
      v_response:=jsonb_build_object('laundry_receipt_id',v_id,'status','DELETED');
      return erp._idempotency_complete('save_laundry_receipt_draft_v2',p_client_request_id,v_response);
    end if;
    update erp.laundry_receipts
    set receipt_number=coalesce(nullif(btrim(p_payload->>'receipt_number'),''),v_receipt.receipt_number),
        delivery_id=case when p_payload?'delivery_id' then (p_payload->>'delivery_id')::uuid else v_receipt.delivery_id end,
        physical_at=case when p_payload?'physical_at' then (p_payload->>'physical_at')::timestamptz else v_receipt.physical_at end,
        updated_at=now()
    where id=v_id returning * into v_receipt;
  end if;

  if p_payload?'lines' then
    if jsonb_typeof(p_payload->'lines')<>'array' then raise exception 'lines must be an array'; end if;
    delete from erp.laundry_receipt_lines where receipt_id=v_id;
    for v_line in select value from jsonb_array_elements(p_payload->'lines')
    loop
      v_line_id:=coalesce(nullif(v_line->>'id','')::uuid,gen_random_uuid());
      insert into erp.laundry_receipt_lines(
        id,receipt_id,delivery_line_id,actual_wash_process_id,
        qty_good_received,qty_bs_laundry,qty_stuck,qty_missing,
        actual_rate_snapshot,actual_cost_status,actual_cost,notes
      ) values(
        v_line_id,v_id,(v_line->>'delivery_line_id')::uuid,
        nullif(v_line->>'actual_wash_process_id','')::uuid,
        coalesce(nullif(v_line->>'qty_good_received','')::integer,0),
        coalesce(nullif(v_line->>'qty_bs_laundry','')::integer,0),
        coalesce(nullif(v_line->>'qty_stuck','')::integer,0),
        coalesce(nullif(v_line->>'qty_missing','')::integer,0),
        nullif(v_line->>'actual_rate_snapshot','')::numeric,
        upper(coalesce(nullif(v_line->>'actual_cost_status',''),'PENDING')),
        nullif(v_line->>'actual_cost','')::numeric,
        nullif(btrim(v_line->>'notes'),'')
      );
      if v_line?'bs_allocations' then
        if jsonb_typeof(v_line->'bs_allocations')<>'array' then
          raise exception 'bs_allocations must be an array';
        end if;
        for v_allocation in select value from jsonb_array_elements(v_line->'bs_allocations')
        loop
          insert into erp.laundry_receipt_bs_product_allocations(
            id,receipt_line_id,product_id,qty_bs,notes,created_by
          ) values(
            coalesce(nullif(v_allocation->>'id','')::uuid,gen_random_uuid()),
            v_line_id,(v_allocation->>'product_id')::uuid,
            (v_allocation->>'qty_bs')::integer,
            nullif(btrim(v_allocation->>'notes'),''),erp.current_app_user_id()
          );
        end loop;
      end if;
    end loop;
    update erp.laundry_receipts set updated_at=now() where id=v_id returning * into v_receipt;
  end if;

  select * into v_receipt from erp.laundry_receipts where id=v_id;
  v_response:=jsonb_build_object(
    'laundry_receipt_id',v_receipt.id,'status',v_receipt.status,
    'row_version',v_receipt.row_version,
    'line_count',(select count(*) from erp.laundry_receipt_lines where receipt_id=v_receipt.id),
    'lines',coalesce((
      select jsonb_agg(jsonb_build_object(
        'receipt_line_id',l.id,'delivery_line_id',l.delivery_line_id,
        'qty_good_received',l.qty_good_received,'qty_bs_laundry',l.qty_bs_laundry,
        'qty_stuck',l.qty_stuck,'qty_missing',l.qty_missing,
        'bs_allocations',coalesce((select jsonb_agg(jsonb_build_object(
          'allocation_id',a.id,'product_id',a.product_id,'qty_bs',a.qty_bs
        ) order by a.id) from erp.laundry_receipt_bs_product_allocations a
        where a.receipt_line_id=l.id),'[]'::jsonb)
      ) order by l.id) from erp.laundry_receipt_lines l where l.receipt_id=v_receipt.id
    ),'[]'::jsonb)
  );
  return erp._idempotency_complete('save_laundry_receipt_draft_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."save_laundry_receipt_draft_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_material_adjustment_draft_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text; v_cached jsonb; v_response jsonb;
  v_id uuid := nullif(p_payload->>'id', '')::uuid;
  v_action text := upper(coalesce(nullif(btrim(p_payload->>'action'), ''), 'SAVE'));
  v_reason text := nullif(btrim(p_payload->>'change_reason'), '');
  v_header erp.material_adjustments%rowtype;
  v_line jsonb; v_type text; v_roll uuid; v_material uuid;
begin
  perform erp.require_internal();
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if v_action not in ('SAVE','DELETE') then raise exception 'action must be SAVE or DELETE'; end if;
  if v_action = 'SAVE' and coalesce(jsonb_typeof(p_payload->'items'), 'null') <> 'array' then
    raise exception 'items must be a JSON array';
  end if;
  v_hash := erp._request_hash(jsonb_build_object(
    'payload', p_payload, 'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(
    'save_material_adjustment_draft_v2', p_client_request_id, v_hash
  );
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason', v_reason, true);

  if v_id is null then
    if v_action = 'DELETE' then raise exception 'Adjustment id is required for DELETE'; end if;
    if p_expected_version is not null then raise exception 'expected_version must be null on create'; end if;
    insert into erp.material_adjustments(
      adjustment_number, reason_code, physical_at, status, notes, created_by, location_id
    ) values(
      btrim(p_payload->>'adjustment_number'), upper(p_payload->>'reason_code'),
      (p_payload->>'physical_at')::timestamptz, 'DRAFT',
      nullif(btrim(p_payload->>'notes'), ''), erp.current_app_user_id(),
      (p_payload->>'location_id')::uuid
    ) returning * into v_header;
    v_id := v_header.id;
  else
    if p_expected_version is null then raise exception 'expected_version is required'; end if;
    select * into v_header from erp.material_adjustments where id = v_id for update;
    if v_header.id is null then raise exception 'Material adjustment not found'; end if;
    if v_header.row_version <> p_expected_version then
      raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_header.row_version;
    end if;
    if v_header.status <> 'DRAFT' then raise exception 'Only DRAFT adjustment can be saved/deleted'; end if;
    if v_action = 'DELETE' then
      delete from erp.material_adjustments where id = v_id;
      v_response := jsonb_build_object('material_adjustment_id', v_id, 'status', 'DELETED');
      return erp._idempotency_complete(
        'save_material_adjustment_draft_v2', p_client_request_id, v_response
      );
    end if;
    update erp.material_adjustments
    set adjustment_number = coalesce(
          nullif(btrim(p_payload->>'adjustment_number'), ''), v_header.adjustment_number
        ),
        reason_code = upper(coalesce(nullif(p_payload->>'reason_code', ''), v_header.reason_code)),
        physical_at = coalesce(
          nullif(p_payload->>'physical_at', '')::timestamptz, v_header.physical_at
        ),
        location_id = case when p_payload ? 'location_id'
          then (p_payload->>'location_id')::uuid else v_header.location_id end,
        notes = case when p_payload ? 'notes'
          then nullif(btrim(p_payload->>'notes'), '') else v_header.notes end
    where id = v_id returning * into v_header;
  end if;

  if jsonb_array_length(p_payload->'items') = 0 then
    raise exception 'At least one adjustment line is required';
  end if;
  if not exists(
    select 1 from erp.locations l where l.id = v_header.location_id
      and l.is_active and l.location_type = 'RAW_MATERIAL_WAREHOUSE'
  ) then raise exception 'Adjustment location must be an active raw-material warehouse'; end if;
  delete from erp.material_adjustment_items where adjustment_id = v_id;
  for v_line in select value from jsonb_array_elements(p_payload->'items') loop
    v_material := (v_line->>'material_id')::uuid;
    v_roll := nullif(v_line->>'roll_id', '')::uuid;
    select material_type into v_type from erp.materials
    where id = v_material and is_active;
    if v_type is null then raise exception 'Active material is required'; end if;
    if v_type = 'FABRIC' and v_roll is null then raise exception 'FABRIC adjustment requires roll_id'; end if;
    if v_type <> 'FABRIC' and v_roll is not null then raise exception 'Only FABRIC may use roll_id'; end if;
    if v_roll is not null and not exists(
      select 1 from erp.material_rolls r where r.id = v_roll and r.material_id = v_material
    ) then raise exception 'Adjustment roll does not belong to material'; end if;
    insert into erp.material_adjustment_items(
      id, adjustment_id, material_id, roll_id, qty_signed, input_unit_cost, notes
    ) values(
      coalesce(nullif(v_line->>'id', '')::uuid, gen_random_uuid()),
      v_id, v_material, v_roll, (v_line->>'qty_signed')::numeric,
      nullif(v_line->>'input_unit_cost', '')::numeric,
      nullif(btrim(v_line->>'notes'), '')
    );
  end loop;
  select * into v_header from erp.material_adjustments where id = v_id;
  v_response := jsonb_build_object(
    'material_adjustment_id', v_header.id, 'status', v_header.status,
    'row_version', v_header.row_version,
    'item_count', (select count(*) from erp.material_adjustment_items i where i.adjustment_id = v_id),
    'net_qty', (select sum(i.qty_signed) from erp.material_adjustment_items i where i.adjustment_id = v_id)
  );
  return erp._idempotency_complete(
    'save_material_adjustment_draft_v2', p_client_request_id, v_response
  );
end;
$function$;

alter function "erp"."save_material_adjustment_draft_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_material_purchase_draft_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_purchase_id uuid := nullif(p_payload->>'id', '')::uuid;
  v_header erp.material_purchase_headers%rowtype;
  v_line jsonb;
  v_roll jsonb;
  v_material erp.materials%rowtype;
  v_item_id uuid;
  v_roll_id uuid;
  v_qty numeric;
  v_unit_price numeric;
  v_effective_unit_price numeric;
  v_benchmark_id uuid;
  v_benchmark_price numeric;
  v_price_state text;
  v_price_source text;
  v_roll_total numeric;
  v_roll_count integer;
  v_reason text := nullif(btrim(p_payload->>'change_reason'), '');
  v_physical_at timestamptz := nullif(p_payload->>'physical_at', '')::timestamptz;
begin
  perform erp.require_internal();
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if coalesce(btrim(p_payload->>'purchase_number'), '') = '' then raise exception 'purchase_number is required'; end if;
  if v_physical_at is null then raise exception 'physical_at is required'; end if;
  if v_physical_at > clock_timestamp() + interval '5 minutes' then raise exception 'physical_at cannot be in the future'; end if;
  if p_payload ? 'lines' and jsonb_typeof(p_payload->'lines') <> 'array' then raise exception 'lines must be an array'; end if;

  v_hash := erp._request_hash(jsonb_build_object('payload', p_payload, 'expected_version', p_expected_version));
  v_cached := erp._idempotency_begin('save_material_purchase_draft_v2', p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason', v_reason, true);

  if v_purchase_id is null then
    if p_expected_version is not null then raise exception 'expected_version must be null when creating a purchase'; end if;
    insert into erp.material_purchase_headers(
      purchase_number, supplier_id, physical_at, status, notes, created_by,
      location_id, supplier_invoice_number, due_date
    ) values (
      btrim(p_payload->>'purchase_number'),
      nullif(p_payload->>'supplier_id', '')::uuid,
      v_physical_at, 'DRAFT', nullif(btrim(p_payload->>'notes'), ''),
      erp.current_app_user_id(), nullif(p_payload->>'location_id', '')::uuid,
      nullif(btrim(p_payload->>'supplier_invoice_number'), ''),
      nullif(p_payload->>'due_date', '')::date
    ) returning * into v_header;
    v_purchase_id := v_header.id;
  else
    if p_expected_version is null then raise exception 'expected_version is required when updating a purchase'; end if;
    select * into v_header
    from erp.material_purchase_headers where id = v_purchase_id for update;
    if v_header.id is null then raise exception 'Material purchase not found'; end if;
    if v_header.status <> 'DRAFT' then raise exception 'Only DRAFT material purchases can be saved'; end if;
    if v_header.row_version <> p_expected_version then
      raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_header.row_version;
    end if;
    update erp.material_purchase_headers
    set purchase_number = btrim(p_payload->>'purchase_number'),
        supplier_id = nullif(p_payload->>'supplier_id', '')::uuid,
        physical_at = v_physical_at,
        notes = nullif(btrim(p_payload->>'notes'), ''),
        location_id = nullif(p_payload->>'location_id', '')::uuid,
        supplier_invoice_number = nullif(btrim(p_payload->>'supplier_invoice_number'), ''),
        due_date = nullif(p_payload->>'due_date', '')::date,
        updated_at = now()
    where id = v_purchase_id
    returning * into v_header;
  end if;

  delete from erp.material_rolls r
  using erp.material_purchase_items i
  where r.purchase_item_id = i.id and i.purchase_id = v_purchase_id;
  delete from erp.material_purchase_items where purchase_id = v_purchase_id;

  for v_line in
    select value from jsonb_array_elements(coalesce(p_payload->'lines', '[]'::jsonb))
  loop
    if coalesce(nullif(v_line->>'material_id', ''), '') = '' then raise exception 'Each purchase line requires material_id'; end if;
    select * into v_material
    from erp.materials where id = (v_line->>'material_id')::uuid;
    if v_material.id is null then raise exception 'Purchase material not found'; end if;
    if not v_material.is_active then raise exception 'Inactive material % cannot be purchased', v_material.material_sku; end if;

    v_qty := coalesce(
      nullif(v_line->>'qty', '')::numeric,
      nullif(v_line->>'purchase_qty_entered', '')::numeric
        * coalesce(nullif(v_line->>'purchase_uom_factor_snapshot', '')::numeric, 1)
    );
    if v_qty is null or v_qty <= 0 then raise exception 'Purchase quantity must be positive'; end if;

    v_benchmark_id := null;
    v_benchmark_price := null;
    v_unit_price := nullif(v_line->>'unit_price', '')::numeric;
    v_price_source := upper(coalesce(nullif(btrim(v_line->>'price_source'), ''), 'MANUAL_ESTIMATE'));
    v_price_state := upper(coalesce(nullif(btrim(v_line->>'price_state'), ''),
      case when v_price_source = 'SUPPLIER_INVOICE' then 'FINAL' else 'ESTIMATED' end));

    if v_unit_price is null and v_material.material_type = 'FABRIC' then
      select id, benchmark_price_per_base_uom
      into v_benchmark_id, v_benchmark_price
      from erp.fabric_benchmark_price_versions
      where material_id = v_material.id
        and effective_from <= v_physical_at
        and (effective_to is null or v_physical_at < effective_to)
      order by effective_from desc
      limit 1;
      if v_benchmark_id is null then
        raise exception 'Fabric % has no benchmark price effective at receipt time', v_material.material_sku;
      end if;
      v_unit_price := v_benchmark_price;
      v_price_source := 'BENCHMARK';
      v_price_state := 'ESTIMATED';
    elsif v_price_source = 'BENCHMARK' then
      select id, benchmark_price_per_base_uom
      into v_benchmark_id, v_benchmark_price
      from erp.fabric_benchmark_price_versions
      where material_id = v_material.id
        and effective_from <= v_physical_at
        and (effective_to is null or v_physical_at < effective_to)
      order by effective_from desc
      limit 1;
      if v_benchmark_id is null then raise exception 'Benchmark source has no effective benchmark version'; end if;
      if abs(v_unit_price - v_benchmark_price) > 0.000001 then
        raise exception 'Benchmark source price must match the effective benchmark snapshot';
      end if;
    end if;

    if v_price_state not in ('ESTIMATED','FINAL') then raise exception 'Invalid price_state'; end if;
    if v_price_source not in ('BENCHMARK','SUPPLIER_QUOTE','SUPPLIER_INVOICE','MANUAL_ESTIMATE','MIGRATION') then
      raise exception 'Invalid price_source';
    end if;
    if v_price_state = 'FINAL' and v_price_source not in ('SUPPLIER_INVOICE','MIGRATION') then
      raise exception 'FINAL purchase price must come from SUPPLIER_INVOICE or MIGRATION';
    end if;
    if v_unit_price is null and v_line->>'purchase_price_per_uom_snapshot' is null then
      raise exception 'unit_price or purchase_price_per_uom_snapshot is required';
    end if;
    if v_unit_price is not null and v_unit_price < 0 then raise exception 'unit_price cannot be negative'; end if;

    v_item_id := coalesce(nullif(v_line->>'id', '')::uuid, gen_random_uuid());
    insert into erp.material_purchase_items(
      id, purchase_id, material_id, qty, unit_price, lot_number, notes,
      purchase_qty_entered, purchase_uom_code, purchase_uom_factor_snapshot,
      purchase_price_per_uom_snapshot, price_state, price_source,
      benchmark_price_version_id, benchmark_unit_price_snapshot,
      supplier_final_unit_price_snapshot, price_finalized_at, price_finalized_by
    ) values (
      v_item_id, v_purchase_id, v_material.id, v_qty, v_unit_price,
      nullif(btrim(v_line->>'lot_number'), ''), nullif(btrim(v_line->>'notes'), ''),
      nullif(v_line->>'purchase_qty_entered', '')::numeric,
      nullif(upper(btrim(v_line->>'purchase_uom_code')), ''),
      nullif(v_line->>'purchase_uom_factor_snapshot', '')::numeric,
      nullif(v_line->>'purchase_price_per_uom_snapshot', '')::numeric,
      v_price_state, v_price_source, v_benchmark_id,
      v_benchmark_price,
      case when v_price_state = 'FINAL' then v_unit_price else null end,
      case when v_price_state = 'FINAL' then now() else null end,
      case when v_price_state = 'FINAL' then erp.current_app_user_id() else null end
    ) returning unit_price into v_effective_unit_price;

    if v_price_state = 'FINAL' and v_unit_price is null then
      update erp.material_purchase_items
      set supplier_final_unit_price_snapshot = v_effective_unit_price
      where id = v_item_id;
    end if;

    v_roll_total := 0;
    v_roll_count := 0;
    if v_line ? 'rolls' and jsonb_typeof(v_line->'rolls') <> 'array' then raise exception 'rolls must be an array'; end if;
    for v_roll in
      select value from jsonb_array_elements(coalesce(v_line->'rolls', '[]'::jsonb))
    loop
      if coalesce(btrim(v_roll->>'roll_number'), '') = '' then raise exception 'roll_number is required'; end if;
      if nullif(v_roll->>'qty', '')::numeric is null or nullif(v_roll->>'qty', '')::numeric <= 0 then
        raise exception 'Roll quantity must be positive';
      end if;
      v_roll_id := coalesce(nullif(v_roll->>'id', '')::uuid, gen_random_uuid());
      insert into erp.material_rolls(
        id, material_id, purchase_item_id, supplier_id, roll_number,
        original_qty, cached_qty, status, received_at, notes
      ) values (
        v_roll_id, v_material.id, v_item_id, v_header.supplier_id,
        btrim(v_roll->>'roll_number'), (v_roll->>'qty')::numeric,
        (v_roll->>'qty')::numeric, 'AVAILABLE', v_physical_at,
        nullif(btrim(v_roll->>'notes'), '')
      );
      v_roll_total := v_roll_total + (v_roll->>'qty')::numeric;
      v_roll_count := v_roll_count + 1;
    end loop;
    if v_roll_count > 0 and abs(v_roll_total - v_qty) > 0.000001 then
      raise exception 'Line quantity % does not equal roll total %', v_qty, v_roll_total;
    end if;
  end loop;

  select * into v_header from erp.material_purchase_headers where id = v_purchase_id;
  v_response := jsonb_build_object(
    'purchase_id', v_purchase_id,
    'status', v_header.status,
    'row_version', v_header.row_version,
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', i.id, 'material_id', i.material_id, 'qty', i.qty,
        'unit_price', i.unit_price, 'price_state', i.price_state,
        'price_source', i.price_source
      ) order by i.id)
      from erp.material_purchase_items i where i.purchase_id = v_purchase_id
    ), '[]'::jsonb)
  );
  return erp._idempotency_complete('save_material_purchase_draft_v2', p_client_request_id, v_response);
end;
$function$;

alter function "erp"."save_material_purchase_draft_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_material_supplier_invoice_draft_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_action text:=upper(coalesce(nullif(p_payload->>'action',''),'SAVE'));
  h erp.material_supplier_invoices%rowtype;
  j jsonb;v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
begin
  perform erp.require_owner_admin();
  if v_reason is null then raise exception 'change_reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('save_material_supplier_invoice_draft_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',v_reason,true);

  if v_action='DELETE' then
    if v_id is null or p_expected_version is null then raise exception 'id and expected_version are required for delete'; end if;
    select * into h from erp.material_supplier_invoices where id=v_id for update;
    if h.id is null then raise exception 'Supplier invoice draft not found'; end if;
    if h.status<>'DRAFT' then raise exception 'Only a DRAFT supplier invoice may be deleted'; end if;
    if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
    delete from erp.material_supplier_invoices where id=h.id;
    v_response:=jsonb_build_object('supplier_invoice_id',v_id,'deleted',true);
    return erp._idempotency_complete('save_material_supplier_invoice_draft_v2',p_client_request_id,v_response);
  elsif v_action<>'SAVE' then
    raise exception 'Unsupported action %',v_action;
  end if;

  if nullif(btrim(p_payload->>'invoice_number'),'') is null then raise exception 'invoice_number is required'; end if;
  if nullif(p_payload->>'supplier_id','') is null then raise exception 'supplier_id is required'; end if;
  if nullif(p_payload->>'invoice_date','') is null then raise exception 'invoice_date is required'; end if;
  if (p_payload->>'invoice_date')::date>current_date then raise exception 'invoice_date cannot be in the future'; end if;
  if coalesce(jsonb_typeof(p_payload->'lines'),'null')<>'array'
     or jsonb_array_length(p_payload->'lines')=0 then raise exception 'At least one invoice line is required'; end if;

  if v_id is null then
    v_id:=gen_random_uuid();
    insert into erp.material_supplier_invoices(
      id,invoice_number,supplier_id,invoice_date,received_at,due_date,notes,created_by
    ) values(
      v_id,btrim(p_payload->>'invoice_number'),(p_payload->>'supplier_id')::uuid,
      (p_payload->>'invoice_date')::date,
      coalesce(nullif(p_payload->>'received_at','')::timestamptz,clock_timestamp()),
      nullif(p_payload->>'due_date','')::date,nullif(btrim(p_payload->>'notes'),''),
      erp.current_app_user_id()
    );
  else
    if p_expected_version is null then raise exception 'expected_version is required for update'; end if;
    select * into h from erp.material_supplier_invoices where id=v_id for update;
    if h.id is null or h.status<>'DRAFT' then raise exception 'Supplier invoice must be DRAFT'; end if;
    if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
    update erp.material_supplier_invoices
    set invoice_number=btrim(p_payload->>'invoice_number'),
        supplier_id=(p_payload->>'supplier_id')::uuid,
        invoice_date=(p_payload->>'invoice_date')::date,
        received_at=coalesce(nullif(p_payload->>'received_at','')::timestamptz,received_at),
        due_date=nullif(p_payload->>'due_date','')::date,
        notes=nullif(btrim(p_payload->>'notes'),'')
    where id=v_id;
    delete from erp.material_supplier_invoice_lines where invoice_id=v_id;
  end if;

  for j in select value from jsonb_array_elements(p_payload->'lines') loop
    insert into erp.material_supplier_invoice_lines(
      invoice_id,purchase_item_id,qty_invoiced,unit_price,discount_amount,notes
    ) values(
      v_id,(j->>'purchase_item_id')::uuid,(j->>'qty_invoiced')::numeric,
      (j->>'unit_price')::numeric,coalesce(nullif(j->>'discount_amount','')::numeric,0),
      nullif(btrim(j->>'notes'),'')
    );
  end loop;
  update erp.material_supplier_invoices set updated_at=clock_timestamp() where id=v_id;
  select * into h from erp.material_supplier_invoices where id=v_id;
  v_response:=jsonb_build_object(
    'supplier_invoice_id',h.id,'invoice_number',h.invoice_number,'status',h.status,
    'row_version',h.row_version,
    'line_count',(select count(*) from erp.material_supplier_invoice_lines where invoice_id=h.id),
    'gross_amount',(select coalesce(sum(gross_amount),0) from erp.material_supplier_invoice_lines where invoice_id=h.id),
    'discount_amount',(select coalesce(sum(discount_amount),0) from erp.material_supplier_invoice_lines where invoice_id=h.id),
    'net_amount',(select coalesce(sum(net_amount),0) from erp.material_supplier_invoice_lines where invoice_id=h.id)
  );
  return erp._idempotency_complete('save_material_supplier_invoice_draft_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."save_material_supplier_invoice_draft_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_material_supplier_return_draft_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text; v_cached jsonb; v_response jsonb;
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_action text:=upper(coalesce(nullif(btrim(p_payload->>'action'),''),'SAVE'));
  v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  h erp.material_supplier_returns%rowtype; v_line jsonb;
begin
  perform erp.require_internal();
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if v_action not in('SAVE','DELETE') then raise exception 'action must be SAVE or DELETE'; end if;
  if v_action='SAVE' and coalesce(jsonb_typeof(p_payload->'items'),'null')<>'array' then raise exception 'items must be a JSON array'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('save_material_supplier_return_draft_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',v_reason,true);
  if v_id is null then
    if v_action='DELETE' then raise exception 'Return id is required for DELETE'; end if;
    if p_expected_version is not null then raise exception 'expected_version must be null on create'; end if;
    insert into erp.material_supplier_returns(
      return_number,supplier_id,location_id,physical_at,status,reason,created_by
    ) values(
      btrim(p_payload->>'return_number'),(p_payload->>'supplier_id')::uuid,
      (p_payload->>'location_id')::uuid,(p_payload->>'physical_at')::timestamptz,
      'DRAFT',coalesce(nullif(btrim(p_payload->>'reason'),''),v_reason),erp.current_app_user_id()
    ) returning * into h; v_id:=h.id;
  else
    if p_expected_version is null then raise exception 'expected_version is required'; end if;
    select * into h from erp.material_supplier_returns where id=v_id for update;
    if h.id is null then raise exception 'Supplier return not found'; end if;
    if h.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version; end if;
    if h.status<>'DRAFT' then raise exception 'Only DRAFT supplier return can be saved/deleted'; end if;
    if v_action='DELETE' then
      delete from erp.material_supplier_returns where id=v_id;
      v_response:=jsonb_build_object('material_supplier_return_id',v_id,'status','DELETED');
      return erp._idempotency_complete('save_material_supplier_return_draft_v2',p_client_request_id,v_response);
    end if;
    update erp.material_supplier_returns
    set return_number=coalesce(nullif(btrim(p_payload->>'return_number'),''),h.return_number),
        supplier_id=case when p_payload?'supplier_id' then (p_payload->>'supplier_id')::uuid else h.supplier_id end,
        location_id=case when p_payload?'location_id' then (p_payload->>'location_id')::uuid else h.location_id end,
        physical_at=coalesce(nullif(p_payload->>'physical_at','')::timestamptz,h.physical_at),
        reason=case when p_payload?'reason' then coalesce(nullif(btrim(p_payload->>'reason'),''),v_reason) else h.reason end
    where id=v_id returning * into h;
  end if;
  if jsonb_array_length(p_payload->'items')=0 then raise exception 'At least one supplier return line is required'; end if;
  if not exists(select 1 from erp.locations l where l.id=h.location_id and l.is_active and l.location_type='RAW_MATERIAL_WAREHOUSE') then
    raise exception 'Supplier return location must be an active raw-material warehouse';
  end if;
  delete from erp.material_supplier_return_items where return_id=v_id;
  for v_line in select value from jsonb_array_elements(p_payload->'items') loop
    -- supplier_credit_unit_price is deliberately omitted: the source validator
    -- resolves it from the authoritative current purchase cost.
    insert into erp.material_supplier_return_items(
      id,return_id,material_id,roll_id,qty,notes,purchase_item_id
    ) values(
      coalesce(nullif(v_line->>'id','')::uuid,gen_random_uuid()),v_id,
      (v_line->>'material_id')::uuid,nullif(v_line->>'roll_id','')::uuid,
      (v_line->>'qty')::numeric,nullif(btrim(v_line->>'notes'),''),
      nullif(v_line->>'purchase_item_id','')::uuid
    );
  end loop;
  select * into h from erp.material_supplier_returns where id=v_id;
  v_response:=jsonb_build_object(
    'material_supplier_return_id',h.id,'status',h.status,'row_version',h.row_version,
    'item_count',(select count(*) from erp.material_supplier_return_items i where i.return_id=v_id),
    'total_qty',(select sum(i.qty) from erp.material_supplier_return_items i where i.return_id=v_id),
    'credit_total',(select sum(i.qty*i.supplier_credit_unit_price) from erp.material_supplier_return_items i where i.return_id=v_id)
  );
  return erp._idempotency_complete('save_material_supplier_return_draft_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."save_material_supplier_return_draft_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_material_transfer_draft_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_id uuid := nullif(p_payload->>'id', '')::uuid;
  v_action text := upper(coalesce(nullif(btrim(p_payload->>'action'), ''), 'SAVE'));
  v_reason text := nullif(btrim(p_payload->>'change_reason'), '');
  v_header erp.material_transfers%rowtype;
  v_line jsonb;
begin
  perform erp.require_internal();
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if v_action not in ('SAVE','DELETE') then raise exception 'action must be SAVE or DELETE'; end if;
  if v_action = 'SAVE' and coalesce(jsonb_typeof(p_payload->'items'), 'null') <> 'array' then
    raise exception 'items must be a JSON array';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'payload', p_payload, 'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(
    'save_material_transfer_draft_v2', p_client_request_id, v_hash
  );
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason', v_reason, true);

  if v_id is null then
    if v_action = 'DELETE' then raise exception 'Transfer id is required for DELETE'; end if;
    if p_expected_version is not null then
      raise exception 'expected_version must be null when creating a transfer';
    end if;
    if coalesce(btrim(p_payload->>'transfer_number'), '') = '' then
      raise exception 'transfer_number is required';
    end if;
    insert into erp.material_transfers(
      transfer_number, from_location_id, to_location_id, physical_at,
      status, notes, created_by
    ) values (
      btrim(p_payload->>'transfer_number'),
      (p_payload->>'from_location_id')::uuid,
      (p_payload->>'to_location_id')::uuid,
      (p_payload->>'physical_at')::timestamptz,
      'DRAFT', nullif(btrim(p_payload->>'notes'), ''), erp.current_app_user_id()
    ) returning * into v_header;
    v_id := v_header.id;
  else
    if p_expected_version is null then raise exception 'expected_version is required'; end if;
    select * into v_header from erp.material_transfers where id = v_id for update;
    if v_header.id is null then raise exception 'Material transfer not found'; end if;
    if v_header.row_version <> p_expected_version then
      raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_header.row_version;
    end if;
    if v_header.status <> 'DRAFT' then
      raise exception 'Only DRAFT material transfer can be saved/deleted';
    end if;
    if v_action = 'DELETE' then
      delete from erp.material_transfers where id = v_id;
      v_response := jsonb_build_object('material_transfer_id', v_id, 'status', 'DELETED');
      return erp._idempotency_complete(
        'save_material_transfer_draft_v2', p_client_request_id, v_response
      );
    end if;
    update erp.material_transfers
    set transfer_number = coalesce(
          nullif(btrim(p_payload->>'transfer_number'), ''), v_header.transfer_number
        ),
        from_location_id = case when p_payload ? 'from_location_id'
          then (p_payload->>'from_location_id')::uuid else v_header.from_location_id end,
        to_location_id = case when p_payload ? 'to_location_id'
          then (p_payload->>'to_location_id')::uuid else v_header.to_location_id end,
        physical_at = coalesce(
          nullif(p_payload->>'physical_at', '')::timestamptz, v_header.physical_at
        ),
        notes = case when p_payload ? 'notes'
          then nullif(btrim(p_payload->>'notes'), '') else v_header.notes end
    where id = v_id
    returning * into v_header;
  end if;

  if jsonb_array_length(p_payload->'items') = 0 then
    raise exception 'At least one transfer item is required';
  end if;
  delete from erp.material_transfer_items where transfer_id = v_id;
  for v_line in select value from jsonb_array_elements(p_payload->'items') loop
    insert into erp.material_transfer_items(
      id, transfer_id, material_id, roll_id, qty, notes
    ) values (
      coalesce(nullif(v_line->>'id', '')::uuid, gen_random_uuid()),
      v_id, (v_line->>'material_id')::uuid,
      nullif(v_line->>'roll_id', '')::uuid,
      (v_line->>'qty')::numeric,
      nullif(btrim(v_line->>'notes'), '')
    );
  end loop;
  select * into v_header from erp.material_transfers where id = v_id;
  v_response := jsonb_build_object(
    'material_transfer_id', v_header.id,
    'transfer_number', v_header.transfer_number,
    'status', v_header.status,
    'row_version', v_header.row_version,
    'item_count', (select count(*) from erp.material_transfer_items i where i.transfer_id = v_id),
    'total_qty', (select sum(i.qty) from erp.material_transfer_items i where i.transfer_id = v_id)
  );
  return erp._idempotency_complete(
    'save_material_transfer_draft_v2', p_client_request_id, v_response
  );
end;
$function$;

alter function "erp"."save_material_transfer_draft_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_my_reminder_v1(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'save_my_reminder_v1';
  v_actor uuid := erp.require_manual_reminder_actor();
  v_id uuid;
  v_title text;
  v_note text;
  v_due_text text;
  v_due_at timestamptz;
  v_priority text;
  v_module text;
  v_hash text;
  v_cached jsonb;
  v_row erp.manual_reminders%rowtype;
  v_response jsonb;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Reminder payload must be a JSON object';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_payload) k
    where k not in ('id','title','note','due_at','priority','module')
  ) then
    raise exception 'Reminder payload contains unsupported fields';
  end if;
  if exists (
    select 1
    from jsonb_each(p_payload) item
    where item.key in ('id','title','note','due_at','priority','module')
      and jsonb_typeof(item.value) not in ('string','null')
  ) then
    raise exception 'Reminder payload fields must be strings or null';
  end if;

  begin
    v_id := nullif(btrim(p_payload->>'id'), '')::uuid;
  exception when invalid_text_representation then
    raise exception 'Reminder id must be a UUID';
  end;

  v_title := btrim(coalesce(p_payload->>'title', ''));
  v_note := coalesce(p_payload->>'note', '');
  v_due_text := btrim(coalesce(p_payload->>'due_at', ''));
  v_priority := upper(coalesce(nullif(btrim(p_payload->>'priority'), ''), 'NORMAL'));
  v_module := coalesce(nullif(btrim(p_payload->>'module'), ''), 'Operasional');

  if v_title = '' or char_length(v_title) > 200 then
    raise exception 'Reminder title must contain 1 to 200 characters';
  end if;
  if char_length(v_note) > 4000 then
    raise exception 'Reminder note cannot exceed 4000 characters';
  end if;
  if char_length(v_module) > 80 then
    raise exception 'Reminder module cannot exceed 80 characters';
  end if;
  if v_priority not in ('URGENT','NORMAL','LOW') then
    raise exception 'Reminder priority must be URGENT, NORMAL, or LOW';
  end if;
  if v_due_text = '' or v_due_text !~* '(Z|[+-][0-9]{2}:[0-9]{2})$' then
    raise exception 'Reminder due_at must be ISO-8601 with an explicit UTC offset';
  end if;
  begin
    v_due_at := v_due_text::timestamptz;
  exception when others then
    raise exception 'Reminder due_at is invalid';
  end;
  if not isfinite(v_due_at) then
    raise exception 'Reminder due_at must be finite';
  end if;

  if v_id is null and p_expected_version is not null then
    raise exception 'expected_version must be null when creating a reminder';
  end if;
  if v_id is not null and (p_expected_version is null or p_expected_version < 1) then
    raise exception 'A positive expected_version is required when updating a reminder';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'id', v_id,
    'title', v_title,
    'note', v_note,
    'due_at', v_due_at,
    'priority', v_priority,
    'module', v_module,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  if v_id is null then
    perform set_config('app.manual_reminder_write', 'on', true);
    perform set_config('app.manual_reminder_action', 'CREATE', true);
    insert into erp.manual_reminders(
      owner_user_id, title, note, due_at, priority, module,
      created_by, updated_by, last_client_request_id
    ) values (
      v_actor, v_title, v_note, v_due_at, v_priority, v_module,
      v_actor, v_actor, p_client_request_id
    ) returning * into v_row;
  else
    select * into v_row
    from erp.manual_reminders r
    where r.id = v_id and r.owner_user_id = v_actor
    for update;

    if v_row.id is null then raise exception 'Reminder not found'; end if;
    if v_row.row_version <> p_expected_version then
      raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_row.row_version;
    end if;
    if v_row.status <> 'OPEN' then
      raise exception 'Only OPEN reminders can be edited; reopen DONE reminders first';
    end if;

    if (v_row.title, v_row.note, v_row.due_at, v_row.priority, v_row.module)
       is distinct from
       (v_title, v_note, v_due_at, v_priority, v_module) then
      perform set_config('app.manual_reminder_write', 'on', true);
      perform set_config('app.manual_reminder_action', 'EDIT', true);
      update erp.manual_reminders r
      set title = v_title,
          note = v_note,
          due_at = v_due_at,
          priority = v_priority,
          module = v_module,
          updated_at = clock_timestamp(),
          updated_by = v_actor,
          last_client_request_id = p_client_request_id
      where r.id = v_id and r.owner_user_id = v_actor
      returning * into v_row;
    end if;
  end if;

  perform set_config('app.manual_reminder_write', 'off', true);
  perform set_config('app.manual_reminder_action', '', true);

  v_response := jsonb_build_object(
    'reminder', jsonb_build_object(
      'id', v_row.id,
      'title', v_row.title,
      'note', v_row.note,
      'due_at', v_row.due_at,
      'priority', v_row.priority,
      'module', v_row.module,
      'status', v_row.status,
      'completed_at', v_row.completed_at,
      'cancelled_at', v_row.cancelled_at,
      'cancellation_reason', v_row.cancellation_reason,
      'created_at', v_row.created_at,
      'updated_at', v_row.updated_at,
      'row_version', v_row.row_version
    ),
    'client_request_id', p_client_request_id
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."save_my_reminder_v1"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_pattern_v1(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_code text:=upper(nullif(btrim(p_payload->>'code'),''));
  v_revision text:=upper(coalesce(nullif(btrim(p_payload->>'revision'),''),'R1'));
  v_name text:=nullif(btrim(p_payload->>'name'),'');
  v_sort integer:=nullif(p_payload->>'sort_order','')::integer;
  v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_hash text;v_cached jsonb;v_response jsonb;v_old jsonb;
  v_pattern erp.production_patterns%rowtype;v_actor uuid:=erp.current_app_user_id();
begin
  perform erp.require_permission('master.pattern.manage');
  if v_code is null or v_code !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$' then raise exception 'invalid pattern code'; end if;
  if v_revision !~ '^[A-Z0-9][A-Z0-9._-]{0,15}$' then raise exception 'invalid pattern revision'; end if;
  if v_name is null or length(v_name)>100 then raise exception 'invalid pattern name'; end if;
  if v_sort is null or v_sort<0 or v_sort>999999 then raise exception 'invalid pattern sort_order'; end if;
  if v_reason is null then raise exception 'change_reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('save_pattern_v1',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  if v_id is null then
    if p_expected_version is not null then raise exception 'expected_version must be null when creating a pattern'; end if;
    begin
      insert into erp.production_patterns(pattern_code,revision,pattern_name,sort_order,created_by,updated_by)
      values(v_code,v_revision,v_name,v_sort,v_actor,v_actor) returning * into v_pattern;
    exception when unique_violation then
      raise exception using errcode='23505',message='PATTERN_CODE_REVISION_OR_NAME_REVISION_ALREADY_EXISTS';
    end;
    v_old:=null;
  else
    if p_expected_version is null then raise exception 'expected_version is required when updating a pattern'; end if;
    select * into v_pattern from erp.production_patterns where id=v_id for update;
    if v_pattern.id is null then raise exception 'Pattern not found'; end if;
    if v_pattern.row_version<>p_expected_version then
      raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_pattern.row_version;
    end if;
    if not v_pattern.is_active then raise exception 'Inactive pattern cannot be edited'; end if;
    if v_code<>v_pattern.pattern_code then raise exception 'pattern code is immutable; create a new pattern identity'; end if;
    if v_revision<>v_pattern.revision then raise exception 'pattern revision is immutable; create a new revision'; end if;
    v_old:=to_jsonb(v_pattern);
    begin
      update erp.production_patterns set pattern_name=v_name,sort_order=v_sort,
        updated_by=v_actor,updated_at=clock_timestamp()
      where id=v_pattern.id returning * into v_pattern;
    exception when unique_violation then
      raise exception using errcode='23505',message='PATTERN_CODE_REVISION_OR_NAME_REVISION_ALREADY_EXISTS';
    end;
  end if;
  insert into erp.production_pattern_audit(
    entity_type,entity_id,pattern_id,action,old_data,new_data,change_reason,client_request_id,actor_app_user_id
  ) values(
    'PATTERN',v_pattern.id,v_pattern.id,case when v_old is null then 'CREATE' else 'UPDATE' end,
    v_old,to_jsonb(v_pattern),v_reason,p_client_request_id,v_actor
  );
  v_response:=jsonb_build_object(
    'pattern_id',v_pattern.id,'code',v_pattern.pattern_code,'revision',v_pattern.revision,'name',v_pattern.pattern_name,
    'sort_order',v_pattern.sort_order,'is_active',v_pattern.is_active,'row_version',v_pattern.row_version
  );
  return erp._idempotency_complete('save_pattern_v1',p_client_request_id,v_response);
end
$function$;

alter function "erp"."save_pattern_v1"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_rework_order_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_action text:=upper(coalesce(nullif(p_payload->>'action',''),'SAVE'));
  v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_order erp.rework_orders%rowtype;
  v_component jsonb;v_total_return integer;
begin
  perform erp.require_internal();
  if v_action not in('SAVE','CANCEL') then raise exception 'Rework action must be SAVE or CANCEL'; end if;
  if v_reason is null then raise exception 'change_reason is required'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('save_rework_order_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',v_reason,true);

  if v_id is null then
    if v_action='CANCEL' then raise exception 'Rework id is required for CANCEL'; end if;
    if p_expected_version is not null then raise exception 'expected_version must be null when creating rework'; end if;
    v_total_return:=coalesce(nullif(p_payload->>'qty_good_returned','')::integer,0)
      +coalesce(nullif(p_payload->>'qty_bs_returned','')::integer,0);
    if v_total_return>=coalesce(nullif(p_payload->>'qty_sent','')::integer,0) then
      raise exception 'Fully reconciled return must use complete_rework_order_v2 after creating the active order';
    end if;
    insert into erp.rework_orders(
      rework_number,bs_case_id,destination_type,contractor_id,vendor_id,
      qty_sent,qty_good_returned,qty_bs_returned,physical_sent_at,status,
      return_fg_location_id,notes
    ) values(
      btrim(p_payload->>'rework_number'),(p_payload->>'bs_case_id')::uuid,
      upper(p_payload->>'destination_type'),nullif(p_payload->>'contractor_id','')::uuid,
      nullif(p_payload->>'vendor_id','')::uuid,(p_payload->>'qty_sent')::integer,
      coalesce(nullif(p_payload->>'qty_good_returned','')::integer,0),
      coalesce(nullif(p_payload->>'qty_bs_returned','')::integer,0),
      (p_payload->>'physical_sent_at')::timestamptz,
      case when v_total_return>0 then 'PARTIAL'
           when upper(coalesce(nullif(p_payload->>'status',''),'OPEN'))='IN_PROGRESS' then 'IN_PROGRESS'
           else 'OPEN' end,
      nullif(p_payload->>'return_fg_location_id','')::uuid,nullif(btrim(p_payload->>'notes'),'')
    ) returning * into v_order;
    v_id:=v_order.id;
  else
    if p_expected_version is null then raise exception 'expected_version is required'; end if;
    select * into v_order from erp.rework_orders where id=v_id for update;
    if v_order.id is null then raise exception 'Rework order not found'; end if;
    if v_order.row_version<>p_expected_version then
      raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_order.row_version;
    end if;
    if v_order.cost_posted or v_order.status in('COMPLETED','CANCELLED') then
      raise exception 'Completed/cancelled rework is locked; use reversal/correction';
    end if;
    if v_action='CANCEL' then
      if v_order.qty_good_returned+v_order.qty_bs_returned>0 then
        raise exception 'Partially returned rework must be fully reconciled before cancellation';
      end if;
      update erp.rework_orders set status='CANCELLED',notes=concat_ws(E'\n',notes,'CANCELLED: '||v_reason),updated_at=now()
      where id=v_id returning * into v_order;
      perform erp.refresh_bs_case_status(v_order.bs_case_id);
      v_response:=jsonb_build_object(
        'rework_order_id',v_order.id,'status',v_order.status,'row_version',v_order.row_version
      );
      return erp._idempotency_complete('save_rework_order_v2',p_client_request_id,v_response);
    end if;
    v_total_return:=coalesce(nullif(p_payload->>'qty_good_returned','')::integer,v_order.qty_good_returned)
      +coalesce(nullif(p_payload->>'qty_bs_returned','')::integer,v_order.qty_bs_returned);
    if v_total_return>=coalesce(nullif(p_payload->>'qty_sent','')::integer,v_order.qty_sent) then
      raise exception 'Fully reconciled return must use complete_rework_order_v2';
    end if;
    update erp.rework_orders
    set rework_number=coalesce(nullif(btrim(p_payload->>'rework_number'),''),v_order.rework_number),
        bs_case_id=case when p_payload?'bs_case_id' then (p_payload->>'bs_case_id')::uuid else v_order.bs_case_id end,
        destination_type=upper(coalesce(nullif(p_payload->>'destination_type',''),v_order.destination_type)),
        contractor_id=case when p_payload?'contractor_id' then nullif(p_payload->>'contractor_id','')::uuid else v_order.contractor_id end,
        vendor_id=case when p_payload?'vendor_id' then nullif(p_payload->>'vendor_id','')::uuid else v_order.vendor_id end,
        qty_sent=coalesce(nullif(p_payload->>'qty_sent','')::integer,v_order.qty_sent),
        qty_good_returned=coalesce(nullif(p_payload->>'qty_good_returned','')::integer,v_order.qty_good_returned),
        qty_bs_returned=coalesce(nullif(p_payload->>'qty_bs_returned','')::integer,v_order.qty_bs_returned),
        physical_sent_at=coalesce(nullif(p_payload->>'physical_sent_at','')::timestamptz,v_order.physical_sent_at),
        status=case when v_total_return>0 then 'PARTIAL'
                    when upper(coalesce(nullif(p_payload->>'status',''),'OPEN'))='IN_PROGRESS' then 'IN_PROGRESS'
                    else 'OPEN' end,
        return_fg_location_id=case when p_payload?'return_fg_location_id' then nullif(p_payload->>'return_fg_location_id','')::uuid else v_order.return_fg_location_id end,
        notes=case when p_payload?'notes' then nullif(btrim(p_payload->>'notes'),'') else v_order.notes end,
        updated_at=now()
    where id=v_id returning * into v_order;
  end if;

  if p_payload?'components' then
    if jsonb_typeof(p_payload->'components')<>'array' then raise exception 'components must be an array'; end if;
    delete from erp.rework_component_lines where rework_order_id=v_id;
    for v_component in select value from jsonb_array_elements(p_payload->'components') loop
      insert into erp.rework_component_lines(
        rework_order_id,bs_case_component_id,qty_performed,qty_newly_payable,
        rate_snapshot,notes
      ) values(
        v_id,(v_component->>'bs_case_component_id')::uuid,
        (v_component->>'qty_performed')::integer,0,0,
        nullif(btrim(v_component->>'notes'),'')
      );
    end loop;
    update erp.rework_orders set updated_at=now() where id=v_id returning * into v_order;
  end if;
  if v_order.destination_type='CONTRACTOR' and not exists(
    select 1 from erp.rework_component_lines where rework_order_id=v_order.id
  ) then raise exception 'Contractor rework requires at least one component line'; end if;
  perform erp.refresh_bs_case_status(v_order.bs_case_id);
  select * into v_order from erp.rework_orders where id=v_order.id;
  v_response:=jsonb_build_object(
    'rework_order_id',v_order.id,'status',v_order.status,'row_version',v_order.row_version,
    'bs_case_id',v_order.bs_case_id,'components',coalesce((
      select jsonb_agg(jsonb_build_object(
        'rework_component_line_id',l.id,'bs_case_component_id',l.bs_case_component_id,
        'qty_performed',l.qty_performed,'qty_newly_payable',l.qty_newly_payable,
        'rate_snapshot',l.rate_snapshot,'rate_basis',l.rate_basis,
        'source_contractor_rate_id',l.source_contractor_rate_id,
        'source_po_component_snapshot_id',l.source_po_component_snapshot_id
      ) order by l.id) from erp.rework_component_lines l where l.rework_order_id=v_order.id
    ),'[]'::jsonb)
  );
  return erp._idempotency_complete('save_rework_order_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."save_rework_order_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_role_v1(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation constant text:='save_role_v1';
  v_hash text;v_cached jsonb;v_response jsonb;v_old jsonb;
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_code text:=upper(nullif(btrim(p_payload->>'code'),''));
  v_name text:=nullif(btrim(p_payload->>'name'),'');
  v_description text:=nullif(btrim(p_payload->>'description'),'');
  v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_permissions jsonb:=coalesce(p_payload->'permission_keys','[]'::jsonb);
  v_role erp.app_roles%rowtype;v_actor uuid:=erp.current_app_user_id();
begin
  perform erp.require_permission('settings.access.manage');
  if v_reason is null then raise exception 'change_reason is required'; end if;
  if v_name is null then raise exception 'role name is required'; end if;
  if jsonb_typeof(v_permissions)<>'array' then raise exception 'permission_keys must be an array'; end if;
  if exists(
    select 1 from jsonb_array_elements_text(v_permissions) x(key)
    left join erp.app_permissions p on p.permission_key=x.key and p.is_active
    where p.permission_key is null
  ) then raise exception 'Unknown or inactive permission key'; end if;
  if exists(
    select 1 from jsonb_array_elements_text(v_permissions) x(key)
    join erp.app_permissions p on p.permission_key=x.key
    where p.high_risk
  ) and coalesce((p_payload->>'confirm_high_risk')::boolean,false) is not true then
    raise exception 'HIGH_RISK_PERMISSION_CONFIRMATION_REQUIRED';
  end if;
  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin(v_operation,p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;

  if v_id is null then
    if p_expected_version is not null then raise exception 'expected_version must be null when creating a role'; end if;
    if v_code is null or v_code !~ '^[A-Z][A-Z0-9_]{1,31}$' then raise exception 'invalid role code'; end if;
    insert into erp.app_roles(role_code,role_name,description,is_system,is_protected,is_active,created_by,updated_by)
    values(v_code,v_name,v_description,false,false,true,v_actor,v_actor)
    returning * into v_role;
    v_old:=null;
  else
    select * into v_role from erp.app_roles where id=v_id for update;
    if v_role.id is null then raise exception 'App role not found'; end if;
    if v_role.is_system or v_role.is_protected then raise exception 'SYSTEM_ROLE_MUST_BE_DUPLICATED_BEFORE_EDIT'; end if;
    if p_expected_version is null then raise exception 'expected_version is required when updating a role'; end if;
    if v_role.row_version<>p_expected_version then
      raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_role.row_version;
    end if;
    if v_code is not null and v_code<>v_role.role_code then raise exception 'role code is immutable'; end if;
    v_old:=to_jsonb(v_role)||jsonb_build_object('permissions',erp.role_permission_keys(v_role.id));
    update erp.app_roles set role_name=v_name,description=v_description,updated_by=v_actor,updated_at=clock_timestamp()
    where id=v_role.id returning * into v_role;
    delete from erp.app_role_permissions where role_id=v_role.id;
  end if;

  insert into erp.app_role_permissions(role_id,permission_key,granted_by)
  select v_role.id,x.key,v_actor
  from (select distinct value as key from jsonb_array_elements_text(v_permissions)) x;
  insert into erp.app_access_audit(
    entity_type,entity_id,action,old_data,new_data,change_reason,client_request_id,actor_app_user_id
  ) values(
    'ROLE',v_role.id,case when v_old is null then 'CREATE' else 'UPDATE' end,v_old,
    to_jsonb(v_role)||jsonb_build_object('permissions',erp.role_permission_keys(v_role.id)),
    v_reason,p_client_request_id,v_actor
  );
  v_response:=jsonb_build_object(
    'role_id',v_role.id,'role_code',v_role.role_code,'role_name',v_role.role_name,
    'is_active',v_role.is_active,'row_version',v_role.row_version,
    'permissions',erp.role_permission_keys(v_role.id)
  );
  return erp._idempotency_complete(v_operation,p_client_request_id,v_response);
end
$function$;

alter function "erp"."save_role_v1"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_sale_draft_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'save_sale_draft_v2';
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_sale_id uuid := nullif(p_payload->>'sale_id','')::uuid;
  v_sale_number text := nullif(btrim(p_payload->>'sale_number'),'');
  v_customer_id uuid := nullif(p_payload->>'customer_id','')::uuid;
  v_location_id uuid := nullif(p_payload->>'source_location_id','')::uuid;
  v_sale_date timestamptz := nullif(p_payload->>'sale_date','')::timestamptz;
  v_due_date date := nullif(p_payload->>'due_date','')::date;
  v_payment_terms text := nullif(btrim(p_payload->>'payment_terms'),'');
  v_notes text := nullif(btrim(p_payload->>'notes'),'');
  v_reason text := nullif(btrim(p_payload->>'reason'),'');
  v_items jsonb := p_payload->'items';
  h erp.sales_headers%rowtype;
  v_reserved bigint;
  v_released bigint := 0;
  v_total numeric(24,6);
begin
  perform erp.require_internal();
  if v_sale_number is null or v_customer_id is null or v_location_id is null or v_sale_date is null then
    raise exception 'sale_number, customer_id, source_location_id, and sale_date are required';
  end if;
  if v_reason is null then raise exception 'Draft save reason is required'; end if;
  if v_sale_date > clock_timestamp() + interval '5 minutes' then
    raise exception 'Tanggal/jam invoice berada di masa depan';
  end if;
  if jsonb_typeof(v_items) <> 'array' or jsonb_array_length(v_items) = 0 then
    raise exception 'Sale Draft requires at least one item';
  end if;
  if not exists (select 1 from erp.customers where id=v_customer_id and is_active=true) then
    raise exception 'Active customer is required';
  end if;
  if not exists (
    select 1 from erp.locations
    where id=v_location_id and is_active=true and location_type='FG_WAREHOUSE'
  ) then raise exception 'Active FG warehouse is required'; end if;
  if exists (
    select 1 from jsonb_to_recordset(v_items) as x(
      product_id uuid,qty_pcs integer,unit_price_snapshot numeric,discount_amount numeric,notes text
    )
    where x.product_id is null or coalesce(x.qty_pcs,0)<=0
      or coalesce(x.unit_price_snapshot,0)<0 or coalesce(x.discount_amount,0)<0
      or coalesce(x.discount_amount,0)>coalesce(x.qty_pcs,0)*coalesce(x.unit_price_snapshot,0)
  ) then raise exception 'Every sale line requires valid product, qty, price, and discount'; end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'payload',p_payload,'expected_version',p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation,p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  perform set_config('app.change_reason',v_reason,true);

  if v_sale_id is null then
    if p_expected_version is not null then
      raise exception 'expected_version must be null when creating a Sale Draft';
    end if;
    insert into erp.sales_headers(
      sale_number,customer_id,sale_date,due_date,status,payment_terms,notes,created_by,source_location_id
    ) values (
      v_sale_number,v_customer_id,v_sale_date,v_due_date,'DRAFT',v_payment_terms,v_notes,
      erp.current_app_user_id(),v_location_id
    ) returning * into h;
    v_sale_id := h.id;
  else
    if p_expected_version is null then raise exception 'expected_version is required when editing a Sale Draft'; end if;
    select * into h from erp.sales_headers where id=v_sale_id for update;
    if h.id is null then raise exception 'Sale Draft not found'; end if;
    if h.status <> 'DRAFT' then raise exception 'Only a DRAFT sale can be edited'; end if;
    if h.row_version <> p_expected_version then
      raise exception 'STALE_VERSION expected %, current %',p_expected_version,h.row_version;
    end if;
    v_released := erp._release_sale_draft_reservations(v_sale_id,'Edit Draft · release previous reservation');
    delete from erp.sales_items where sale_id=v_sale_id;
    update erp.sales_headers set
      sale_number=v_sale_number,customer_id=v_customer_id,sale_date=v_sale_date,
      due_date=v_due_date,payment_terms=v_payment_terms,notes=v_notes,
      source_location_id=v_location_id
    where id=v_sale_id
    returning * into h;
  end if;

  insert into erp.sales_items(
    sale_id,product_id,qty_pcs,unit_price_snapshot,discount_amount,notes
  )
  select v_sale_id,x.product_id,x.qty_pcs,x.unit_price_snapshot,
    coalesce(x.discount_amount,0),nullif(btrim(x.notes),'')
  from jsonb_to_recordset(v_items) as x(
    product_id uuid,qty_pcs integer,unit_price_snapshot numeric,discount_amount numeric,notes text
  );

  v_reserved := erp._reserve_sale_draft(v_sale_id);
  select * into h from erp.sales_headers where id=v_sale_id;
  select coalesce(sum(line_total),0) into v_total from erp.sales_items where sale_id=v_sale_id;
  v_response := jsonb_build_object(
    'sale_id',v_sale_id,'sale_number',h.sale_number,'status',h.status,
    'reserved_qty_pcs',v_reserved,'released_previous_qty_pcs',v_released,
    'sellable_stock_delta_pcs',-v_reserved,'invoice_total',v_total,
    'row_version',h.row_version
  );
  return erp._idempotency_complete(v_operation,p_client_request_id,v_response);
end;
$function$;

alter function "erp"."save_sale_draft_v2"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_work_bom_edit(p_bom_version_id uuid, p_items jsonb, p_effective_from timestamp with time zone DEFAULT clock_timestamp(), p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  b erp.work_bom_versions%rowtype;
  v_last_commit timestamptz;
  v_eff timestamptz:=coalesce(p_effective_from,clock_timestamp());
  v_next timestamptz;
  v_new_end timestamptz;
  v_ver integer;
  v_new uuid;
  j jsonb;
begin
  perform erp.require_owner_admin();
  if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Work BOM harus memiliki minimal satu komponen'; end if;
  select * into b from erp.work_bom_versions where id=p_bom_version_id for update;
  if b.id is null then raise exception 'Work BOM tidak ditemukan'; end if;
  select max(committed_at) into v_last_commit from erp.po_work_component_snapshots where source_bom_version_id=b.id;

  if v_last_commit is null then
    delete from erp.work_bom_items where bom_version_id=b.id;
    for j in select value from jsonb_array_elements(p_items) loop
      insert into erp.work_bom_items(bom_version_id,work_component_id,sequence_no,default_rate)
      values(b.id,(j->>'work_component_id')::uuid,coalesce(nullif(j->>'sequence_no','')::integer,0),coalesce(nullif(j->>'default_rate','')::numeric,0));
    end loop;
    update erp.work_bom_versions set notes=coalesce(p_notes,notes) where id=b.id;
    insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason,new_data)
    values('work_bom_versions',b.id,'UPDATE',erp.current_app_user_id(),'Work BOM edited before commitment',jsonb_build_object('item_count',jsonb_array_length(p_items),'in_place',true));
    return b.id;
  end if;

  if v_eff<=v_last_commit or v_eff<=b.effective_from then raise exception 'Tanggal mulai Work BOM baru harus setelah penggunaan terakhir dan setelah awal versi lama'; end if;
  if b.effective_to is not null and v_eff>=b.effective_to then raise exception 'Tanggal mulai Work BOM baru harus sebelum akhir versi lama'; end if;
  select min(x.effective_from) into v_next from erp.work_bom_versions x where x.model_id=b.model_id and x.id<>b.id and x.effective_from>v_eff;
  v_new_end:=case when b.effective_to is null then v_next when v_next is null then b.effective_to else least(b.effective_to,v_next) end;
  select coalesce(max(version_no),0)+1 into v_ver from erp.work_bom_versions where model_id=b.model_id;

  update erp.work_bom_versions set effective_to=v_eff where id=b.id;
  insert into erp.work_bom_versions(model_id,version_no,effective_from,effective_to,is_active,notes)
  values(b.model_id,v_ver,v_eff,v_new_end,true,coalesce(p_notes,'Successor Work BOM from Edit')) returning id into v_new;
  for j in select value from jsonb_array_elements(p_items) loop
    insert into erp.work_bom_items(bom_version_id,work_component_id,sequence_no,default_rate)
    values(v_new,(j->>'work_component_id')::uuid,coalesce(nullif(j->>'sequence_no','')::integer,0),coalesce(nullif(j->>'default_rate','')::numeric,0));
  end loop;
  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason,new_data)
  values('work_bom_versions',b.id,'UPDATE',erp.current_app_user_id(),'Committed Work BOM edited by creating successor',
         jsonb_build_object('successor_bom_version_id',v_new,'effective_from',v_eff,'item_count',jsonb_array_length(p_items)));
  return v_new;
end$function$;

alter function "erp"."save_work_bom_edit"(p_bom_version_id uuid, p_items jsonb, p_effective_from timestamp with time zone, p_notes text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.save_worker_roster_v1(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'save_worker_roster_v1';
  v_hash text;
  v_cached jsonb;
  v_worker_id uuid := nullif(p_payload->>'worker_id', '')::uuid;
  v_contractor_id uuid := nullif(p_payload->>'contractor_id', '')::uuid;
  v_worker_name text := nullif(btrim(p_payload->>'worker_name'), '');
  v_job_description text := nullif(btrim(p_payload->>'job_description'), '');
  v_pay_scheme text := upper(coalesce(nullif(btrim(p_payload->>'pay_scheme'), ''), 'DAILY'));
  v_joined_at date := nullif(p_payload->>'joined_at', '')::date;
  v_left_at date := nullif(p_payload->>'left_at', '')::date;
  v_reactivated_on date := nullif(p_payload->>'reactivated_at', '')::date;
  v_is_active boolean := coalesce((p_payload->>'is_active')::boolean, true);
  v_initial_rate numeric := coalesce((p_payload->>'initial_daily_rate')::numeric, 0);
  v_rate_from date := coalesce(nullif(p_payload->>'rate_effective_from', '')::date, v_joined_at, current_date);
  v_reason text := nullif(btrim(p_payload->>'reason'), '');
  v_existing erp.contractor_workers%rowtype;
  v_response jsonb;
begin
  perform erp.require_owner_admin();

  if v_contractor_id is null or v_worker_name is null
     or v_job_description is null or v_joined_at is null then
    raise exception 'contractor_id, worker_name, job_description, and joined_at are required';
  end if;
  if not exists (
    select 1 from erp.contractors c
    where c.id = v_contractor_id and c.contractor_type = 'MANDOR'
  ) then
    raise exception 'Worker roster contractor must be an existing MANDOR';
  end if;
  if v_reason is null then raise exception 'Worker change reason is required'; end if;
  if v_pay_scheme not in ('DAILY','PIECE','HYBRID','NONE') then
    raise exception 'Unsupported pay_scheme';
  end if;
  if v_left_at is not null and v_is_active then
    raise exception 'An active worker cannot have a stop date; clear left_at or deactivate the worker';
  end if;
  if not v_is_active and v_left_at is null then
    raise exception 'A deactivated worker requires left_at';
  end if;
  if not v_is_active and v_left_at > current_date then
    raise exception 'A worker stop date cannot be in the future because roster status changes immediately';
  end if;
  if v_reactivated_on > current_date then
    raise exception 'reactivated_at cannot be in the future because roster status changes immediately';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'payload', p_payload,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  perform set_config('app.change_reason', v_reason, true);

  if v_worker_id is null then
    if p_expected_version is not null then
      raise exception 'expected_version must be null when creating a worker';
    end if;
    if v_initial_rate < 0 then
      raise exception 'initial_daily_rate cannot be negative';
    end if;
    if v_rate_from > v_joined_at then
      raise exception 'Initial daily rate must cover the worker start date';
    end if;
    if exists (
      select 1
      from erp.attendance_periods p
      where p.contractor_id = v_contractor_id
        and p.status in ('POSTED','CORRECTED')
        and daterange(p.period_start, p.period_end + 1, '[)')
            && daterange(v_joined_at, coalesce(v_left_at + 1, 'infinity'::date), '[)')
    ) then
      raise exception 'A new worker start cannot overlap posted attendance history; reverse/correct roster chronology first';
    end if;

    insert into erp.contractor_workers(
      contractor_id, worker_code, worker_name, job_description, pay_scheme,
      daily_rate, is_active, joined_at, left_at, notes, created_by, updated_by
    ) values (
      v_contractor_id, nullif(btrim(p_payload->>'worker_code'), ''), v_worker_name,
      v_job_description, v_pay_scheme,
      v_initial_rate, v_is_active, v_joined_at, v_left_at,
      nullif(btrim(p_payload->>'notes'), ''),
      erp.current_app_user_id(), erp.current_app_user_id()
    ) returning id into v_worker_id;

    perform set_config('app.worker_rate_write', 'on', true);
    insert into erp.worker_daily_rate_versions(
      worker_id, daily_rate, effective_from, change_reason, created_by
    ) values (
      v_worker_id, v_initial_rate, v_rate_from, v_reason, erp.current_app_user_id()
    );

    perform set_config('app.worker_employment_write', 'on', true);
    insert into erp.worker_employment_periods(
      worker_id, started_on, ended_on, start_reason, end_reason,
      created_by, ended_by, ended_at
    ) values (
      v_worker_id, v_joined_at, v_left_at, v_reason,
      case when v_left_at is null then null else v_reason end,
      erp.current_app_user_id(),
      case when v_left_at is null then null else erp.current_app_user_id() end,
      case when v_left_at is null then null else clock_timestamp() end
    );
  else
    select * into v_existing
    from erp.contractor_workers
    where id = v_worker_id
    for update;

    if v_existing.id is null then raise exception 'Worker not found'; end if;
    if p_expected_version is null or v_existing.row_version <> p_expected_version then
      raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_existing.row_version;
    end if;
    if v_existing.contractor_id <> v_contractor_id then
      raise exception 'A worker cannot be moved between contractors; create a new roster identity';
    end if;
    if v_pay_scheme is distinct from v_existing.pay_scheme and exists (
      select 1
      from erp.attendance_periods p
      join erp.worker_employment_periods e on e.worker_id = v_worker_id
      where p.contractor_id = v_contractor_id
        and p.status in ('POSTED','CORRECTED')
        and daterange(p.period_start, p.period_end + 1, '[)')
            && daterange(e.started_on, coalesce(e.ended_on + 1, 'infinity'::date), '[)')
    ) then
      raise exception 'Worker pay_scheme cannot change across posted attendance history';
    end if;
    if v_joined_at is distinct from v_existing.joined_at then
      raise exception 'Original worker start date is immutable; use employment episodes for reactivation';
    end if;
    if v_joined_at is not null and v_joined_at < (
      select min(r.effective_from)
      from erp.worker_daily_rate_versions r
      where r.worker_id = v_worker_id
    ) then
      raise exception 'Worker start date cannot precede the first daily-rate version';
    end if;
    if exists (
      select 1
      from erp.attendance_records a
      where a.worker_id = v_worker_id
        and (a.attendance_date < v_joined_at
          or (v_left_at is not null and a.attendance_date > v_left_at))
    ) then
      raise exception 'Worker start/stop dates cannot exclude existing attendance history';
    end if;

    perform set_config('app.worker_employment_write', 'on', true);
    if v_existing.is_active and not v_is_active then
      update erp.worker_employment_periods e
      set ended_on = v_left_at,
          end_reason = v_reason,
          ended_by = erp.current_app_user_id(),
          ended_at = clock_timestamp()
      where e.worker_id = v_worker_id and e.ended_on is null;
      if not found then
        raise exception 'Active worker has no open employment episode';
      end if;
    elsif not v_existing.is_active and v_is_active then
      if v_reactivated_on is null then
        raise exception 'reactivated_at is required when activating a stopped worker';
      end if;
      if v_reactivated_on <= coalesce((
        select max(e.ended_on) from erp.worker_employment_periods e where e.worker_id = v_worker_id
      ), '-infinity'::date) then
        raise exception 'reactivated_at must be after the previous employment stop date';
      end if;
      if exists (
        select 1
        from erp.attendance_periods p
        where p.contractor_id = v_contractor_id
          and p.status in ('POSTED','CORRECTED')
          and daterange(p.period_start, p.period_end + 1, '[)')
              && daterange(v_reactivated_on, 'infinity'::date, '[)')
      ) then
        raise exception 'A reactivation start cannot overlap posted attendance history; reverse/correct roster chronology first';
      end if;
      perform erp.require_worker_daily_rate_at(v_worker_id, v_reactivated_on);
      insert into erp.worker_employment_periods(
        worker_id, started_on, start_reason, created_by
      ) values (
        v_worker_id, v_reactivated_on, v_reason, erp.current_app_user_id()
      );
    elsif not v_existing.is_active and not v_is_active
          and v_left_at is distinct from v_existing.left_at then
      raise exception 'Stopped employment date is historical; reactivate then create a new episode';
    end if;

    update erp.contractor_workers
    set worker_code = nullif(btrim(p_payload->>'worker_code'), ''),
        worker_name = v_worker_name,
        job_description = v_job_description,
        pay_scheme = v_pay_scheme,
        is_active = v_is_active,
        joined_at = v_joined_at,
        left_at = v_left_at,
        notes = nullif(btrim(p_payload->>'notes'), ''),
        updated_by = erp.current_app_user_id()
    where id = v_worker_id;
  end if;

  select jsonb_build_object(
    'worker_id', w.id,
    'contractor_id', w.contractor_id,
    'worker_name', w.worker_name,
    'job_description', w.job_description,
    'pay_scheme', w.pay_scheme,
    'daily_rate', erp.worker_daily_rate_at(w.id, current_date),
    'is_active', w.is_active,
    'joined_at', w.joined_at,
    'left_at', w.left_at,
    'reactivated_at', (
      select max(e.started_on) from erp.worker_employment_periods e where e.worker_id = w.id
    ),
    'notes', w.notes,
    'row_version', w.row_version
  ) into v_response
  from erp.contractor_workers w
  where w.id = v_worker_id;

  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."save_worker_roster_v1"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.seed_bs_case_component_baseline()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if new.po_id is null then return new; end if;
  insert into erp.bs_case_components(
    bs_case_id,po_component_snapshot_id,work_component_id,
    completed_before_bs_qty,notes
  )
  select
    new.id,s.id,s.work_component_id,
    least(
      new.qty_pcs,
      coalesce((
        select sum(wcl.qty_completed)::integer
        from erp.work_completion_lines wcl
        join erp.work_completion_events wce on wce.id=wcl.completion_id
        where wce.po_id=new.po_id
          and wcl.work_component_id=s.work_component_id
          and wce.status='POSTED'
          and wce.physical_at<=new.physical_at
          and (new.cutting_group_id is null or wce.cutting_group_id=new.cutting_group_id)
      ),0)
    ),
    'Auto baseline from posted work history at BS detection'
  from erp.po_work_component_snapshots s
  where s.po_id=new.po_id
  on conflict(bs_case_id,work_component_id) do nothing;
  return new;
end;
$function$;

alter function "erp"."seed_bs_case_component_baseline"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.seed_standard_accessory_count_uoms()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ BEGIN IF NEW.base_uom_code='PCS' THEN INSERT INTO erp.accessory_category_uom_conversions(category_id,uom_code,base_qty_per_uom,effective_from,notes) VALUES (NEW.id,'LUSIN',12,'1900-01-01 00:00:00+00','System default: 1 lusin = 12 pcs'),(NEW.id,'GROSS',144,'1900-01-01 00:00:00+00','System default: 1 gross = 144 pcs') ON CONFLICT DO NOTHING; END IF;RETURN NEW;END; $function$;

alter function "erp"."seed_standard_accessory_count_uoms"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.set_accessory_selling_price_v2(p_category_id uuid, p_contractor_id uuid, p_selling_price numeric, p_selling_uom_code text, p_effective_from timestamp with time zone, p_notes text, p_change_reason text, p_client_request_id uuid, p_expected_current_version_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_prev erp.contractor_accessory_price_versions%rowtype;
  v_next_at timestamptz;v_new_id uuid;
  v_uom text:=upper(btrim(p_selling_uom_code));
begin
  perform erp.require_owner_admin();
  if nullif(btrim(p_change_reason),'') is null then raise exception 'change_reason is required';end if;
  if p_effective_from is null then raise exception 'effective_from is required';end if;
  if p_selling_price is null or p_selling_price<0 then raise exception 'selling_price cannot be negative';end if;
  if not exists(select 1 from erp.accessory_categories where id=p_category_id and is_active) then
    raise exception 'Active accessory category not found';
  end if;
  if p_contractor_id is not null and not exists(
    select 1 from erp.contractors where id=p_contractor_id and is_active
  ) then raise exception 'Active contractor not found';end if;

  v_hash:=erp._request_hash(jsonb_build_object(
    'category_id',p_category_id,'contractor_id',p_contractor_id,
    'selling_price',p_selling_price,'selling_uom_code',v_uom,
    'effective_from',p_effective_from,'notes',p_notes,
    'reason',btrim(p_change_reason),
    'expected_current_version_id',p_expected_current_version_id
  ));
  v_cached:=erp._idempotency_begin('set_accessory_selling_price_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached;end if;
  perform set_config('app.change_reason',btrim(p_change_reason),true);
  perform pg_advisory_xact_lock(hashtextextended(
    'ACCPRICE:'||coalesce(p_contractor_id::text,'GLOBAL')||':'||p_category_id::text,0
  ));
  perform erp.accessory_uom_factor(p_category_id,v_uom,p_effective_from);

  if exists(
    select 1 from erp.contractor_accessory_price_versions
    where category_id=p_category_id
      and contractor_id is not distinct from p_contractor_id
      and effective_from=p_effective_from
  ) then raise exception 'A selling-price version already starts at this effective_from';end if;

  select * into v_prev
  from erp.contractor_accessory_price_versions
  where category_id=p_category_id
    and contractor_id is not distinct from p_contractor_id
    and effective_from<p_effective_from
    and (effective_to is null or effective_to>p_effective_from)
  order by effective_from desc limit 1 for update;

  if v_prev.id is null then
    if p_expected_current_version_id is not null then
      raise exception 'STALE_VERSION expected current %, but no predecessor covers effective_from',
        p_expected_current_version_id;
    end if;
  elsif p_expected_current_version_id is null or v_prev.id<>p_expected_current_version_id then
    raise exception 'STALE_VERSION expected current %, actual %',
      p_expected_current_version_id,v_prev.id;
  end if;

  select min(effective_from) into v_next_at
  from erp.contractor_accessory_price_versions
  where category_id=p_category_id
    and contractor_id is not distinct from p_contractor_id
    and effective_from>p_effective_from;

  if v_prev.id is not null then
    update erp.contractor_accessory_price_versions
    set effective_to=p_effective_from
    where id=v_prev.id;
  end if;

  insert into erp.contractor_accessory_price_versions(
    contractor_id,category_id,selling_price,selling_uom_code,
    effective_from,effective_to,notes
  ) values(
    p_contractor_id,p_category_id,p_selling_price,v_uom,
    p_effective_from,v_next_at,nullif(btrim(p_notes),'')
  ) returning id into v_new_id;

  v_response:=jsonb_build_object(
    'accessory_price_version_id',v_new_id,'predecessor_version_id',v_prev.id,
    'category_id',p_category_id,'contractor_id',p_contractor_id,
    'selling_price',p_selling_price,'selling_uom_code',v_uom,
    'effective_from',p_effective_from,'effective_to',v_next_at
  );
  return erp._idempotency_complete('set_accessory_selling_price_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."set_accessory_selling_price_v2"(p_category_id uuid, p_contractor_id uuid, p_selling_price numeric, p_selling_uom_code text, p_effective_from timestamp with time zone, p_notes text, p_change_reason text, p_client_request_id uuid, p_expected_current_version_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.set_accessory_uom_conversion_v2(p_category_id uuid, p_uom_code text, p_base_qty_per_uom numeric, p_effective_from timestamp with time zone, p_notes text, p_change_reason text, p_client_request_id uuid, p_expected_category_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;v_cached jsonb;v_response jsonb;
  v_category erp.accessory_categories%rowtype;
  v_prev erp.accessory_category_uom_conversions%rowtype;
  v_next_at timestamptz;v_new_id uuid;
  v_uom text:=upper(btrim(p_uom_code));
begin
  perform erp.require_owner_admin();
  if nullif(btrim(p_change_reason),'') is null then raise exception 'change_reason is required';end if;
  if p_expected_category_version is null then raise exception 'expected_category_version is required';end if;
  if p_effective_from is null then raise exception 'effective_from is required';end if;
  if coalesce(p_base_qty_per_uom,0)<=0 then raise exception 'base_qty_per_uom must be positive';end if;

  v_hash:=erp._request_hash(jsonb_build_object(
    'category_id',p_category_id,'uom_code',v_uom,'factor',p_base_qty_per_uom,
    'effective_from',p_effective_from,'notes',p_notes,
    'reason',btrim(p_change_reason),'expected_category_version',p_expected_category_version
  ));
  v_cached:=erp._idempotency_begin('set_accessory_uom_conversion_v2',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached;end if;
  perform set_config('app.change_reason',btrim(p_change_reason),true);
  perform pg_advisory_xact_lock(hashtextextended('ACCUOM:'||p_category_id::text||':'||v_uom,0));

  select * into v_category from erp.accessory_categories where id=p_category_id for update;
  if v_category.id is null or not v_category.is_active then raise exception 'Active accessory category not found';end if;
  if v_category.row_version<>p_expected_category_version then
    raise exception 'STALE_VERSION expected %, current %',p_expected_category_version,v_category.row_version;
  end if;
  if v_uom=v_category.base_uom_code then
    raise exception 'Base UOM always has factor 1 and must not be versioned';
  end if;
  if not exists(select 1 from erp.uom_definitions where unit_code=v_uom) then
    raise exception 'UOM % is not registered',v_uom;
  end if;
  if exists(
    select 1 from erp.accessory_category_uom_conversions
    where category_id=p_category_id and uom_code=v_uom and effective_from=p_effective_from
  ) then raise exception 'A conversion version already starts at this effective_from';end if;

  select * into v_prev
  from erp.accessory_category_uom_conversions
  where category_id=p_category_id and uom_code=v_uom
    and effective_from<p_effective_from
    and (effective_to is null or effective_to>p_effective_from)
  order by effective_from desc limit 1 for update;

  select min(effective_from) into v_next_at
  from erp.accessory_category_uom_conversions
  where category_id=p_category_id and uom_code=v_uom
    and effective_from>p_effective_from;

  if v_prev.id is not null then
    update erp.accessory_category_uom_conversions
    set effective_to=p_effective_from
    where id=v_prev.id;
  end if;

  insert into erp.accessory_category_uom_conversions(
    category_id,uom_code,base_qty_per_uom,effective_from,effective_to,notes
  ) values(
    p_category_id,v_uom,p_base_qty_per_uom,p_effective_from,v_next_at,nullif(btrim(p_notes),'')
  ) returning id into v_new_id;

  update erp.accessory_categories set updated_at=now() where id=p_category_id
  returning * into v_category;

  v_response:=jsonb_build_object(
    'accessory_uom_conversion_id',v_new_id,'category_id',p_category_id,
    'uom_code',v_uom,'base_qty_per_uom',p_base_qty_per_uom,
    'effective_from',p_effective_from,'effective_to',v_next_at,
    'category_row_version',v_category.row_version
  );
  return erp._idempotency_complete('set_accessory_uom_conversion_v2',p_client_request_id,v_response);
end;
$function$;

alter function "erp"."set_accessory_uom_conversion_v2"(p_category_id uuid, p_uom_code text, p_base_qty_per_uom numeric, p_effective_from timestamp with time zone, p_notes text, p_change_reason text, p_client_request_id uuid, p_expected_category_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.set_change_reason(p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ BEGIN PERFORM erp.require_internal(); PERFORM set_config('app.change_reason',COALESCE(p_reason,''),true); END; $function$;

alter function "erp"."set_change_reason"(p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.set_contractor_hpp_policy_v1(p_payload jsonb, p_client_request_id uuid, p_expected_policy_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'set_contractor_hpp_policy_v1';
  v_hash text;
  v_cached jsonb;
  v_contractor_id uuid;
  v_effective_from date;
  v_is_special boolean;
  v_attendance_required boolean;
  v_reason text;
  v_contractor erp.contractors%rowtype;
  v_current erp.contractor_hpp_policy_versions%rowtype;
  v_next_from date;
  v_new erp.contractor_hpp_policy_versions%rowtype;
  v_response jsonb;
begin
  perform erp.require_owner_admin();
  perform erp._cp3_assert_closed_json_object(
    p_payload,
    array['contractor_id','effective_from','is_special','attendance_required','reason'],
    array['contractor_id','effective_from','is_special','attendance_required','reason'],
    'contractor HPP policy payload'
  );

  if jsonb_typeof(p_payload->'contractor_id') is distinct from 'string'
     or jsonb_typeof(p_payload->'effective_from') is distinct from 'string'
     or jsonb_typeof(p_payload->'is_special') is distinct from 'boolean'
     or jsonb_typeof(p_payload->'attendance_required') is distinct from 'boolean'
     or jsonb_typeof(p_payload->'reason') is distinct from 'string' then
    raise exception 'contractor HPP policy payload has invalid field types';
  end if;

  v_contractor_id := (p_payload->>'contractor_id')::uuid;
  v_effective_from := erp._cp3_parse_canonical_date(p_payload->>'effective_from', 'contractor HPP policy effective_from');
  v_is_special := (p_payload->>'is_special')::boolean;
  v_attendance_required := (p_payload->>'attendance_required')::boolean;
  v_reason := nullif(btrim(p_payload->>'reason'), '');

  if v_reason is null then raise exception 'HPP policy reason is required'; end if;
  if v_effective_from is null then raise exception 'effective_from is required'; end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'payload', p_payload,
    'expected_policy_id', p_expected_policy_id
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  perform pg_advisory_xact_lock(hashtextextended('CONTRACTOR_HPP_POLICY|' || v_contractor_id::text, 0));

  select * into v_contractor
  from erp.contractors
  where id = v_contractor_id
  for update;

  if v_contractor.id is null then raise exception 'Contractor not found'; end if;
  if v_contractor.contractor_type <> 'MANDOR' then
    raise exception 'Attendance HPP policy is only valid for role MANDOR';
  end if;
  if v_contractor.attendance_required is distinct from v_attendance_required then
    raise exception 'attendance_required payload must explicitly match contractor master; update master first, then write a new HPP policy version';
  end if;

  select * into v_current
  from erp.contractor_hpp_policy_versions p
  where p.contractor_id = v_contractor_id
    and v_effective_from >= p.effective_from
    and (p.effective_to is null or v_effective_from <= p.effective_to)
  order by p.effective_from desc, p.id desc
  limit 1
  for update;

  if v_current.id is distinct from p_expected_policy_id then
    raise exception 'STALE_POLICY expected %, current %', p_expected_policy_id, v_current.id;
  end if;
  if v_current.effective_from = v_effective_from then
    raise exception 'A contractor HPP policy already starts on this date';
  end if;

  select min(p.effective_from) into v_next_from
  from erp.contractor_hpp_policy_versions p
  where p.contractor_id = v_contractor_id
    and p.effective_from > v_effective_from;

  if erp._cp3_r4_active_pool_affects_contractor(v_contractor_id,v_effective_from,v_next_from) then
    raise exception 'Contractor HPP policy effective from % overlaps an ACTIVE attendance HPP pool. Cancel the ACTIVE pool first, then write the new policy version.',v_effective_from;
  end if;

  update erp.contractor_hpp_policy_versions p
  set effective_to = v_effective_from - 1,
      row_version = row_version + 1
  where p.contractor_id = v_contractor_id
    and p.effective_from < v_effective_from
    and (p.effective_to is null or p.effective_to >= v_effective_from);

  insert into erp.contractor_hpp_policy_versions(
    contractor_id, effective_from, effective_to,
    contractor_role_snapshot, attendance_required_snapshot,
    is_special, reason, created_by
  ) values (
    v_contractor_id, v_effective_from,
    case when v_next_from is null then null else v_next_from - 1 end,
    'MANDOR', v_attendance_required,
    v_is_special, v_reason, erp.current_app_user_id()
  ) returning * into v_new;

  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
  values (
    'contractor_hpp_policy_versions', v_new.id, 'INSERT',
    jsonb_build_object(
      'contractor_id', v_new.contractor_id,
      'effective_from', v_new.effective_from,
      'effective_to', v_new.effective_to,
      'contractor_role_snapshot', v_new.contractor_role_snapshot,
      'attendance_required_snapshot', v_new.attendance_required_snapshot,
      'is_special', v_new.is_special
    ),
    erp.current_app_user_id(), v_reason
  );

  v_response := jsonb_build_object(
    'policy_version_id', v_new.id,
    'contractor_id', v_new.contractor_id,
    'effective_from', v_new.effective_from,
    'effective_to', v_new.effective_to,
    'contractor_role_snapshot', v_new.contractor_role_snapshot,
    'attendance_required_snapshot', v_new.attendance_required_snapshot,
    'is_special', v_new.is_special,
    'row_version', v_new.row_version
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."set_contractor_hpp_policy_v1"(p_payload jsonb, p_client_request_id uuid, p_expected_policy_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.set_fabric_benchmark_price_v2(p_material_id uuid, p_benchmark_price numeric, p_effective_from timestamp with time zone, p_change_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_hash text;
  v_cached jsonb;
  v_response jsonb;
  v_material erp.materials%rowtype;
  v_open erp.fabric_benchmark_price_versions%rowtype;
  v_version_id uuid;
begin
  perform erp.require_owner_admin();
  if p_material_id is null or p_benchmark_price is null or p_benchmark_price <= 0 then
    raise exception 'Material and positive benchmark price are required';
  end if;
  if p_effective_from is null then raise exception 'effective_from is required'; end if;
  if coalesce(btrim(p_change_reason), '') = '' then raise exception 'change_reason is required'; end if;
  if p_expected_version is null then raise exception 'expected_version is required'; end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'material_id', p_material_id, 'benchmark_price', p_benchmark_price,
    'effective_from', p_effective_from, 'change_reason', p_change_reason,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin('set_fabric_benchmark_price_v2', p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  perform pg_advisory_xact_lock(hashtextextended('fabric-benchmark:' || p_material_id::text, 0));
  select * into v_material from erp.materials where id = p_material_id for update;
  if v_material.id is null or v_material.material_type <> 'FABRIC' then
    raise exception 'FABRIC material not found';
  end if;
  if v_material.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_material.row_version;
  end if;

  select * into v_open
  from erp.fabric_benchmark_price_versions
  where material_id = p_material_id and effective_to is null
  for update;

  if v_open.id is not null then
    if p_effective_from <= v_open.effective_from then
      raise exception 'New benchmark effective_from must be later than the current version';
    end if;
    update erp.fabric_benchmark_price_versions
    set effective_to = p_effective_from
    where id = v_open.id;
  elsif exists (
    select 1 from erp.fabric_benchmark_price_versions
    where material_id = p_material_id and effective_from >= p_effective_from
  ) then
    raise exception 'Backdated benchmark would overlap existing history';
  end if;

  perform set_config('app.change_reason', btrim(p_change_reason), true);
  insert into erp.fabric_benchmark_price_versions(
    material_id, benchmark_price_per_base_uom, base_uom_code_snapshot,
    effective_from, change_reason, created_by
  ) values (
    p_material_id, p_benchmark_price, v_material.unit_code,
    p_effective_from, btrim(p_change_reason), erp.current_app_user_id()
  ) returning id into v_version_id;

  update erp.materials set updated_at = now() where id = p_material_id
  returning * into v_material;

  v_response := jsonb_build_object(
    'material_id', p_material_id,
    'benchmark_version_id', v_version_id,
    'benchmark_price', p_benchmark_price,
    'effective_from', p_effective_from,
    'row_version', v_material.row_version
  );
  return erp._idempotency_complete('set_fabric_benchmark_price_v2', p_client_request_id, v_response);
end;
$function$;

alter function "erp"."set_fabric_benchmark_price_v2"(p_material_id uuid, p_benchmark_price numeric, p_effective_from timestamp with time zone, p_change_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.set_fg_stock_policy_v1(p_product_id uuid, p_location_id uuid, p_basis_source text, p_manual_reorder_point_qty numeric, p_manual_target_stock_qty numeric, p_minimum_sample_days integer, p_effective_from date, p_reason text, p_expected_policy_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'set_fg_stock_policy_v1';
  v_basis text := upper(coalesce(nullif(btrim(p_basis_source), ''), 'BELUM_DIATUR'));
  v_hash text;
  v_cached jsonb;
  v_current erp.stock_policy_versions%rowtype;
  v_next_from date;
  v_new erp.stock_policy_versions%rowtype;
  v_response jsonb;
begin
  perform erp.require_owner_admin();

  if p_product_id is null or p_effective_from is null then
    raise exception 'product_id and effective_from are required';
  end if;
  if not exists (select 1 from erp.products p where p.id = p_product_id) then
    raise exception 'Finished-good product not found';
  end if;
  if p_location_id is not null and not exists (
    select 1 from erp.locations l
    where l.id = p_location_id and l.location_type = 'FG_WAREHOUSE'
  ) then
    raise exception 'FG stock policy location must be an FG warehouse';
  end if;
  if v_basis not in ('BELUM_DIATUR','MANUAL') then
    raise exception 'REKOMENDASI_SISTEM cannot be selected by a user before an authoritative recommendation snapshot exists';
  end if;
  if v_basis = 'MANUAL' and (
    p_manual_reorder_point_qty is null or p_manual_target_stock_qty is null
    or p_manual_reorder_point_qty < 0
    or p_manual_target_stock_qty < p_manual_reorder_point_qty
  ) then
    raise exception 'Manual policy requires target_stock >= reorder_point >= 0';
  end if;
  if v_basis = 'BELUM_DIATUR' and (
    p_manual_reorder_point_qty is not null or p_manual_target_stock_qty is not null
  ) then
    raise exception 'BELUM_DIATUR cannot carry manual threshold values';
  end if;
  if coalesce(p_minimum_sample_days, 30) <= 0 then
    raise exception 'minimum_sample_days must be positive';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Stock policy reason is required';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'product_id', p_product_id,
    'location_id', p_location_id,
    'basis_source', v_basis,
    'manual_reorder_point_qty', p_manual_reorder_point_qty,
    'manual_target_stock_qty', p_manual_target_stock_qty,
    'minimum_sample_days', coalesce(p_minimum_sample_days, 30),
    'effective_from', p_effective_from,
    'reason', p_reason,
    'expected_policy_id', p_expected_policy_id
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'STOCK_POLICY|FG|' || p_product_id::text || '|' || coalesce(p_location_id::text, '*'), 0
  ));

  select * into v_current
  from erp.stock_policy_versions p
  where p.subject_type = 'FG'
    and p.product_id = p_product_id
    and p.location_id is not distinct from p_location_id
    and p_effective_from >= p.effective_from
    and (p.effective_to is null or p_effective_from <= p.effective_to)
  order by p.effective_from desc, p.id desc
  limit 1
  for update;

  if v_current.id is distinct from p_expected_policy_id then
    raise exception 'STALE_POLICY expected %, current %', p_expected_policy_id, v_current.id;
  end if;
  if v_current.effective_from = p_effective_from then
    raise exception 'A stock policy already starts on this date; create a later effective version';
  end if;

  perform set_config('app.change_reason', p_reason, true);
  perform set_config('app.stock_policy_write', 'on', true);

  select min(p.effective_from) into v_next_from
  from erp.stock_policy_versions p
  where p.subject_type = 'FG'
    and p.product_id = p_product_id
    and p.location_id is not distinct from p_location_id
    and p.effective_from > p_effective_from;

  update erp.stock_policy_versions p
  set effective_to = p_effective_from - 1
  where p.subject_type = 'FG'
    and p.product_id = p_product_id
    and p.location_id is not distinct from p_location_id
    and p.effective_from < p_effective_from
    and (p.effective_to is null or p.effective_to >= p_effective_from);

  insert into erp.stock_policy_versions(
    subject_type, product_id, location_id, basis_source,
    manual_reorder_point_qty, manual_target_stock_qty, minimum_sample_days,
    effective_from, effective_to, reason, approved_by, created_by
  ) values (
    'FG', p_product_id, p_location_id, v_basis,
    case when v_basis = 'MANUAL' then p_manual_reorder_point_qty else null end,
    case when v_basis = 'MANUAL' then p_manual_target_stock_qty else null end,
    coalesce(p_minimum_sample_days, 30), p_effective_from,
    case when v_next_from is null then null else v_next_from - 1 end,
    p_reason, erp.current_app_user_id(), erp.current_app_user_id()
  ) returning * into v_new;

  v_response := jsonb_build_object(
    'policy_version_id', v_new.id,
    'product_id', v_new.product_id,
    'location_id', v_new.location_id,
    'basis_source', v_new.basis_source,
    'manual_reorder_point_qty', v_new.manual_reorder_point_qty,
    'manual_target_stock_qty', v_new.manual_target_stock_qty,
    'minimum_sample_days', v_new.minimum_sample_days,
    'effective_from', v_new.effective_from,
    'effective_to', v_new.effective_to,
    'formula_version', v_new.formula_version
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."set_fg_stock_policy_v1"(p_product_id uuid, p_location_id uuid, p_basis_source text, p_manual_reorder_point_qty numeric, p_manual_target_stock_qty numeric, p_minimum_sample_days integer, p_effective_from date, p_reason text, p_expected_policy_id uuid, p_client_request_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.set_my_reminder_done_v1(p_reminder_id uuid, p_done boolean, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'set_my_reminder_done_v1';
  v_actor uuid := erp.require_manual_reminder_actor();
  v_hash text;
  v_cached jsonb;
  v_row erp.manual_reminders%rowtype;
  v_target_status text;
  v_response jsonb;
begin
  if p_reminder_id is null or p_done is null or p_expected_version is null or p_expected_version < 1 then
    raise exception 'reminder_id, done, and a positive expected_version are required';
  end if;
  v_target_status := case when p_done then 'DONE' else 'OPEN' end;
  v_hash := erp._request_hash(jsonb_build_object(
    'reminder_id', p_reminder_id,
    'done', p_done,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_row
  from erp.manual_reminders r
  where r.id = p_reminder_id and r.owner_user_id = v_actor
  for update;

  if v_row.id is null then raise exception 'Reminder not found'; end if;
  if v_row.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_row.row_version;
  end if;
  if v_row.status = 'CANCELLED' then raise exception 'Cancelled reminders are terminal'; end if;

  if v_row.status <> v_target_status then
    perform set_config('app.manual_reminder_write', 'on', true);
    perform set_config('app.manual_reminder_action', case when p_done then 'COMPLETE' else 'REOPEN' end, true);
    update erp.manual_reminders r
    set status = v_target_status,
        completed_at = case when p_done then clock_timestamp() else null end,
        completed_by = case when p_done then v_actor else null end,
        updated_at = clock_timestamp(),
        updated_by = v_actor,
        last_client_request_id = p_client_request_id
    where r.id = p_reminder_id and r.owner_user_id = v_actor
    returning * into v_row;
  end if;

  perform set_config('app.manual_reminder_write', 'off', true);
  perform set_config('app.manual_reminder_action', '', true);

  v_response := jsonb_build_object(
    'reminder_id', v_row.id,
    'status', v_row.status,
    'completed_at', v_row.completed_at,
    'row_version', v_row.row_version,
    'client_request_id', p_client_request_id
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."set_my_reminder_done_v1"(p_reminder_id uuid, p_done boolean, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.set_opening_fg_hpp_percent(p_opening_id uuid, p_percent numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare v_status text;v_count integer;
begin
  perform erp.require_owner_admin();
  if p_percent is null or p_percent<=0 or p_percent>1000 then raise exception 'Persentase HPP opening harus > 0 dan <= 1000'; end if;
  select status into v_status from erp.opening_balance_headers where id=p_opening_id for update;
  if v_status is null then raise exception 'Opening balance tidak ditemukan'; end if;
  if v_status<>'DRAFT' then raise exception 'Default HPP persen hanya dapat diubah saat opening balance masih DRAFT'; end if;
  update erp.opening_balance_items set hpp_input_method='PRICE_PERCENT',hpp_percent_of_price=p_percent,reference_sell_price_snapshot=null
  where opening_id=p_opening_id and balance_type='FINISHED_GOODS';
  get diagnostics v_count=row_count;
  if v_count=0 then raise exception 'Opening balance belum memiliki item FINISHED_GOODS'; end if;
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('opening_balance_headers',p_opening_id,'UPDATE',jsonb_build_object('fg_hpp_input_method','PRICE_PERCENT','hpp_percent_of_price',p_percent,'affected_fg_lines',v_count),erp.current_app_user_id(),'Set default opening FG HPP from selling price percentage');
end;$function$;

alter function "erp"."set_opening_fg_hpp_percent"(p_opening_id uuid, p_percent numeric) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.set_wip_control_flag_v1(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid:=nullif(p_payload->>'id','')::uuid;v_group uuid:=nullif(p_payload->>'cutting_group_id','')::uuid;
  v_type text:=upper(nullif(btrim(p_payload->>'flag_type'),''));v_status text:=upper(coalesce(nullif(btrim(p_payload->>'status'),''),'OPEN'));
  v_note text:=nullif(btrim(p_payload->>'note'),'');v_reason text:=nullif(btrim(p_payload->>'change_reason'),'');
  v_hash text;v_cached jsonb;v_response jsonb;v_flag erp.wip_control_flags%rowtype;v_actor uuid:=erp.current_app_user_id();
begin
  perform erp.require_permission('production.wip.adjust');
  if v_reason is null or v_note is null then raise exception 'note and change_reason are required'; end if;
  if v_type not in ('PENDING_CORRECTION','PENDING_REVERSAL','PENDING_HANDOFF','OPERATOR_ACTION') then raise exception 'invalid WIP flag type'; end if;
  if v_status not in ('OPEN','RESOLVED') then raise exception 'invalid WIP flag status'; end if;
  v_hash:=erp._request_hash(jsonb_build_object('payload',p_payload,'expected_version',p_expected_version));
  v_cached:=erp._idempotency_begin('set_wip_control_flag_v1',p_client_request_id,v_hash);
  if v_cached is not null then return v_cached; end if;
  if v_id is null then
    if p_expected_version is not null or v_status<>'OPEN' then raise exception 'new WIP flag must be OPEN without expected_version'; end if;
    if not exists(select 1 from erp.cutting_groups where id=v_group) then raise exception 'Potongan not found'; end if;
    insert into erp.wip_control_flags(cutting_group_id,flag_type,status,note,created_by)
    values(v_group,v_type,'OPEN',v_note,v_actor) returning * into v_flag;
  else
    if p_expected_version is null then raise exception 'expected_version is required when resolving a WIP flag'; end if;
    select * into v_flag from erp.wip_control_flags where id=v_id for update;
    if v_flag.id is null then raise exception 'WIP flag not found'; end if;
    if v_flag.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_flag.row_version; end if;
    if v_flag.status<>'OPEN' or v_status<>'RESOLVED' then raise exception 'Only an OPEN flag can transition to RESOLVED'; end if;
    update erp.wip_control_flags set status='RESOLVED',note=v_note,resolved_by=v_actor,
      resolved_at=clock_timestamp(),updated_at=clock_timestamp()
    where id=v_flag.id returning * into v_flag;
  end if;
  insert into erp.audit_logs(entity_type,entity_id,action,old_data,new_data,changed_by,change_reason)
  values('wip_control_flags',v_flag.id,case when v_flag.row_version=1 then 'INSERT' else 'UPDATE' end,
    null,to_jsonb(v_flag),v_actor,v_reason);
  v_response:=jsonb_build_object('flag_id',v_flag.id,'status',v_flag.status,'row_version',v_flag.row_version);
  return erp._idempotency_complete('set_wip_control_flag_v1',p_client_request_id,v_response);
end
$function$;

alter function "erp"."set_wip_control_flag_v1"(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.set_worker_daily_rate_v1(p_worker_id uuid, p_daily_rate numeric, p_effective_from date, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'set_worker_daily_rate_v1';
  v_hash text;
  v_cached jsonb;
  v_worker erp.contractor_workers%rowtype;
  v_next_from date;
  v_new_id uuid;
  v_response jsonb;
begin
  perform erp.require_owner_admin();

  if p_worker_id is null or p_effective_from is null or p_expected_version is null then
    raise exception 'worker_id, effective_from, and expected_version are required';
  end if;
  if p_daily_rate is null or p_daily_rate < 0 then
    raise exception 'daily_rate must be zero or positive';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Rate change reason is required';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'worker_id', p_worker_id,
    'daily_rate', p_daily_rate,
    'effective_from', p_effective_from,
    'reason', p_reason,
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_worker
  from erp.contractor_workers
  where id = p_worker_id
  for update;

  if v_worker.id is null then raise exception 'Worker not found'; end if;
  if v_worker.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_worker.row_version;
  end if;
  if v_worker.joined_at is not null and p_effective_from < v_worker.joined_at then
    raise exception 'Rate effective date cannot be earlier than worker start date';
  end if;
  if exists (
    select 1 from erp.worker_daily_rate_versions r
    where r.worker_id = p_worker_id and r.effective_from = p_effective_from
  ) then
    raise exception 'A worker rate version already starts on this date; use a later effective date';
  end if;

  perform set_config('app.change_reason', p_reason, true);
  perform set_config('app.worker_rate_write', 'on', true);
  perform pg_advisory_xact_lock(hashtextextended('WORKER_RATE|' || p_worker_id::text, 0));

  select min(r.effective_from) into v_next_from
  from erp.worker_daily_rate_versions r
  where r.worker_id = p_worker_id and r.effective_from > p_effective_from;

  update erp.worker_daily_rate_versions r
  set effective_to = p_effective_from - 1
  where r.worker_id = p_worker_id
    and r.effective_from < p_effective_from
    and (r.effective_to is null or r.effective_to >= p_effective_from);

  insert into erp.worker_daily_rate_versions(
    worker_id, daily_rate, effective_from, effective_to, change_reason, created_by
  ) values (
    p_worker_id, p_daily_rate, p_effective_from,
    case when v_next_from is null then null else v_next_from - 1 end,
    p_reason, erp.current_app_user_id()
  ) returning id into v_new_id;

  update erp.contractor_workers w
  set daily_rate = coalesce(erp.worker_daily_rate_at(w.id, current_date), w.daily_rate),
      updated_by = erp.current_app_user_id()
  where w.id = p_worker_id;

  select jsonb_build_object(
    'worker_id', w.id,
    'rate_version_id', v_new_id,
    'daily_rate', p_daily_rate,
    'effective_from', p_effective_from,
    'effective_to', case when v_next_from is null then null else v_next_from - 1 end,
    'current_daily_rate', w.daily_rate,
    'row_version', w.row_version
  ) into v_response
  from erp.contractor_workers w
  where w.id = p_worker_id;

  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$;

alter function "erp"."set_worker_daily_rate_v1"(p_worker_id uuid, p_daily_rate numeric, p_effective_from date, p_reason text, p_client_request_id uuid, p_expected_version bigint) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.stage_migration_row(p_batch_id uuid, p_entity_type text, p_source_row_no integer, p_legacy_key text, p_source_payload jsonb, p_normalized_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare v_status text; v_id uuid; v_type text:=upper(trim(p_entity_type));
begin
  perform erp.require_owner_admin();
  select status into v_status from erp.migration_batches where id=p_batch_id for update;
  if v_status is null then raise exception 'Migration batch not found'; end if;
  if v_status not in ('DRAFT','VALIDATING','READY') then raise exception 'Migration batch % cannot be staged while status is %',p_batch_id,v_status; end if;
  if p_source_row_no is null or p_source_row_no<=0 then raise exception 'source_row_no must be positive'; end if;
  if v_type not in ('BRAND','SIZE','MODEL','PRODUCT','CUSTOMER','SUPPLIER','CONTRACTOR','ACCESSORY_CATEGORY','MATERIAL','MATERIAL_ROLL','OPENING_BALANCE_ITEM','OPEN_PO') then
    raise exception 'Unsupported migration entity_type %',v_type;
  end if;
  insert into erp.migration_staging_rows(batch_id,entity_type,source_row_no,legacy_key,source_payload,normalized_payload,validation_status,validation_errors,updated_at)
  values (p_batch_id,v_type,p_source_row_no,nullif(trim(p_legacy_key),''),coalesce(p_source_payload,'{}'::jsonb),coalesce(p_normalized_payload,'{}'::jsonb),'PENDING','[]'::jsonb,now())
  on conflict (batch_id,entity_type,source_row_no) do update set
    legacy_key=excluded.legacy_key,source_payload=excluded.source_payload,normalized_payload=excluded.normalized_payload,
    validation_status='PENDING',validation_errors='[]'::jsonb,posted_entity_type=null,posted_entity_id=null,posted_at=null,updated_at=now()
  returning id into v_id;
  update erp.migration_batches set status='DRAFT',validated_at=null,error_message=null where id=p_batch_id;
  return v_id;
end;$function$;

alter function "erp"."stage_migration_row"(p_batch_id uuid, p_entity_type text, p_source_row_no integer, p_legacy_key text, p_source_payload jsonb, p_normalized_payload jsonb) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.sync_app_user_role_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role erp.app_roles%rowtype;
begin
  if tg_op='INSERT' then
    if new.role_id is not null then
      select * into v_role from erp.app_roles where id=new.role_id;
    elsif nullif(btrim(new.role),'') is not null then
      select * into v_role from erp.app_roles where role_code=upper(btrim(new.role));
    end if;
  elsif new.role_id is distinct from old.role_id then
    select * into v_role from erp.app_roles where id=new.role_id;
  elsif new.role is distinct from old.role then
    select * into v_role from erp.app_roles where role_code=upper(btrim(new.role));
  else
    select * into v_role from erp.app_roles where id=new.role_id;
  end if;
  if v_role.id is null then
    raise exception using errcode='23503',message='APP_ROLE_NOT_FOUND';
  end if;
  new.role_id:=v_role.id;
  new.role:=v_role.role_code;
  return new;
end
$function$;

alter function "erp"."sync_app_user_role_assignment"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.sync_bs_case_status_from_resolution()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if tg_op='DELETE' then
    perform erp.refresh_bs_case_status(old.bs_case_id);return old;
  end if;
  perform erp.refresh_bs_case_status(new.bs_case_id);
  if tg_op='UPDATE' and old.bs_case_id is distinct from new.bs_case_id then
    perform erp.refresh_bs_case_status(old.bs_case_id);
  end if;
  return new;
end;
$function$;

alter function "erp"."sync_bs_case_status_from_resolution"() owner to "postgres";

