 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  if old.status is distinct from new.status then perform erp.rebuild_bs_component_counters(new.bs_case_id); end if;
  return new;
end;
