CREATE OR REPLACE FUNCTION erp.sync_direct_final_cost_correction_item_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if old.status='DRAFT' and new.status='POSTED' then
    update erp.material_purchase_items i
    set supplier_final_unit_price_snapshot=ci.new_unit_price,
        price_finalized_at=clock_timestamp(),
        price_finalized_by=erp.current_app_user_id()
    from erp.material_purchase_cost_correction_items ci
    where ci.correction_id=new.id and i.id=ci.purchase_item_id;
  elsif old.status='POSTED' and new.status='REVERSED' then
    update erp.material_purchase_items i
    set supplier_final_unit_price_snapshot=ci.item_supplier_final_price_before,
        price_finalized_at=ci.item_price_finalized_at_before,
        price_finalized_by=ci.item_price_finalized_by_before
    from erp.material_purchase_cost_correction_items ci
    where ci.correction_id=new.id and i.id=ci.purchase_item_id;
  end if;
  return new;
end;
$function$;

alter function "erp"."sync_direct_final_cost_correction_item_state"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.sync_finished_po_wip_residual(p_po_id uuid, p_effective_date date DEFAULT CURRENT_DATE, p_reason text DEFAULT 'Finished PO residual WIP close'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_status text;
  v_wip_account uuid;
  v_residual numeric(24,6):=0;
  v_event uuid;
  v_journal uuid;
  v_lines jsonb;
begin
  perform erp.require_internal();
  select status into v_status from erp.production_orders where id=p_po_id for update;
  if v_status is null then raise exception 'PO not found'; end if;
  if v_status<>'FINISHED' then return; end if;
  v_wip_account:=erp.account_id('WIP');

  select coalesce(sum(jl.debit-jl.credit),0) into v_residual
  from erp.journal_lines jl
  join erp.journal_entries je on je.id=jl.journal_entry_id
  where je.status in ('POSTED','REVERSED')
    and jl.po_id=p_po_id and jl.account_id=v_wip_account;

  if abs(v_residual)<=0.005 then return; end if;
  insert into erp.po_wip_close_events(po_id,effective_date,residual_amount,reason)
  values (p_po_id,p_effective_date,v_residual,p_reason) returning id into v_event;

  if v_residual>0 then
    v_lines:=jsonb_build_array(
      jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',round(v_residual,2),'credit',0,'po_id',p_po_id),
      jsonb_build_object('mapping_key','WIP','debit',0,'credit',round(v_residual,2),'po_id',p_po_id));
  else
    v_lines:=jsonb_build_array(
      jsonb_build_object('mapping_key','WIP','debit',round(abs(v_residual),2),'credit',0,'po_id',p_po_id),
      jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',0,'credit',round(abs(v_residual),2),'po_id',p_po_id));
  end if;
  v_journal:=erp.post_journal('PO_WIP_RESIDUAL_CLOSE',v_event,p_effective_date,p_reason,v_lines);
  update erp.po_wip_close_events set journal_entry_id=v_journal where id=v_event;
end;
$function$;

alter function "erp"."sync_finished_po_wip_residual"(p_po_id uuid, p_effective_date date, p_reason text) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.sync_laundry_accrual(p_po_id uuid, p_effective_date date DEFAULT CURRENT_DATE)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_old numeric(24,6):=0;v_new numeric(24,6):=0;v_delta numeric(24,6):=0;v_event uuid;v_journal uuid;v_abs numeric(24,2); BEGIN PERFORM erp.require_internal(); SELECT accrued_amount INTO v_old FROM erp.laundry_cost_accrual_state WHERE po_id=p_po_id FOR UPDATE;v_old:=COALESCE(v_old,0);v_new:=COALESCE(erp.desired_laundry_accrual(p_po_id),0);v_delta:=v_new-v_old; IF ABS(v_delta)<=0.005 THEN INSERT INTO erp.laundry_cost_accrual_state(po_id,accrued_amount,updated_at) VALUES (p_po_id,v_new,now()) ON CONFLICT (po_id) DO UPDATE SET accrued_amount=EXCLUDED.accrued_amount,updated_at=now();RETURN;END IF; INSERT INTO erp.laundry_cost_accrual_events(po_id,old_amount,new_amount,delta_amount,effective_date) VALUES (p_po_id,v_old,v_new,v_delta,p_effective_date) RETURNING id INTO v_event;v_abs:=ROUND(ABS(v_delta),2); IF v_delta>0 THEN v_journal:=erp.post_journal('LAUNDRY_ESTIMATE_ACCRUAL',v_event,p_effective_date,'Laundry estimate accrual',jsonb_build_array(jsonb_build_object('mapping_key','WIP','debit',v_abs,'credit',0,'po_id',p_po_id),jsonb_build_object('mapping_key','ACCRUED_MANUFACTURING','debit',0,'credit',v_abs,'po_id',p_po_id))); ELSE v_journal:=erp.post_journal('LAUNDRY_ESTIMATE_ACCRUAL',v_event,p_effective_date,'Laundry estimate accrual reduction',jsonb_build_array(jsonb_build_object('mapping_key','ACCRUED_MANUFACTURING','debit',v_abs,'credit',0,'po_id',p_po_id),jsonb_build_object('mapping_key','WIP','debit',0,'credit',v_abs,'po_id',p_po_id))); END IF; UPDATE erp.laundry_cost_accrual_events SET journal_entry_id=v_journal WHERE id=v_event; INSERT INTO erp.laundry_cost_accrual_state(po_id,accrued_amount,updated_at) VALUES (p_po_id,v_new,now()) ON CONFLICT (po_id) DO UPDATE SET accrued_amount=EXCLUDED.accrued_amount,updated_at=now(); END; $function$;

alter function "erp"."sync_laundry_accrual"(p_po_id uuid, p_effective_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.sync_laundry_accrual_after_rate_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ DECLARE v_po uuid;v_status text;v_date date; BEGIN IF NEW.estimated_rate_snapshot IS NOT DISTINCT FROM OLD.estimated_rate_snapshot THEN RETURN NEW; END IF; SELECT ld.po_id,ld.status,ld.physical_at::date INTO v_po,v_status,v_date FROM erp.laundry_deliveries ld WHERE ld.id=NEW.delivery_id; IF v_status NOT IN ('DRAFT','REVERSED') THEN PERFORM erp.sync_laundry_accrual(v_po,COALESCE(v_date,CURRENT_DATE)); IF EXISTS (SELECT 1 FROM erp.fg_lots WHERE po_id=v_po) THEN PERFORM erp.rebuild_po_hpp(v_po,'Laundry estimate rate corrected'); PERFORM erp.propagate_conversion_hpp_for_po(v_po); PERFORM erp.sync_po_hpp_to_gl(v_po,COALESCE(v_date,CURRENT_DATE)); END IF; END IF;RETURN NEW;END; $function$;

alter function "erp"."sync_laundry_accrual_after_rate_change"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.sync_material_cost_revaluation(p_material_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  r record;
  v_target numeric(24,2);
  v_old numeric(24,2);
  v_diff numeric(24,2);
  v_counterpart text;
  v_po uuid;
  v_contractor uuid;
  v_material_type text;
  v_lines jsonb;
  v_event uuid;
  v_journal uuid;
begin
  perform erp.require_internal();

  for r in
    select msm.*
    from erp.material_stock_movements msm
    where msm.material_id=p_material_id
      and msm.movement_type<>'REVERSAL'
      and msm.source_type in ('CUTTING_GROUP','CUTTING_GROUP_RETURN','CONTRACTOR_MATERIAL_ISSUE_ITEM','MATERIAL_ADJUSTMENT_ITEM','MATERIAL_SUPPLIER_RETURN_ITEM')
    order by msm.physical_at,msm.system_created_at,msm.id
    for update
  loop
    v_counterpart:=null; v_po:=null; v_contractor:=null; v_material_type:=null;

    if r.source_type in ('CUTTING_GROUP','CUTTING_GROUP_RETURN') then
      v_counterpart:='WIP';
      select cg.po_id into v_po from erp.cutting_groups cg where cg.id=r.source_id;
    elsif r.source_type='CONTRACTOR_MATERIAL_ISSUE_ITEM' then
      select cmi.po_id,cmi.contractor_id,m.material_type
      into v_po,v_contractor,v_material_type
      from erp.contractor_material_issue_items ii
      join erp.contractor_material_issues cmi on cmi.id=ii.issue_id
      join erp.materials m on m.id=ii.material_id
      where ii.id=r.source_id;
      v_counterpart:=case when v_material_type='ACCESSORY' then 'ACCESSORY_RECOVERY_COGS' else 'WIP' end;
    elsif r.source_type='MATERIAL_ADJUSTMENT_ITEM' then
      v_counterpart:=case when r.qty_signed<0 then 'OTHER_EXPENSE' else 'OTHER_INCOME' end;
    elsif r.source_type='MATERIAL_SUPPLIER_RETURN_ITEM' then
      v_counterpart:='MATERIAL_PURCHASE_VARIANCE';
    end if;

    if v_counterpart is null then continue; end if;

    if exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=r.id) then
      v_target:=0;
    else
      v_target:=round((r.qty_signed*(r.unit_cost_snapshot-coalesce(r.original_unit_cost_snapshot,r.unit_cost_snapshot)))::numeric,2);
    end if;

    select s.applied_inventory_delta into v_old
    from erp.material_cost_revaluation_state s where s.movement_id=r.id for update;
    v_old:=coalesce(v_old,0);
    v_diff:=round(v_target-v_old,2);

    if abs(v_diff)>0.005 then
      if v_diff>0 then
        v_lines:=jsonb_build_array(
          jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',v_diff,'credit',0,'po_id',v_po,'contractor_id',v_contractor),
          jsonb_build_object('mapping_key',v_counterpart,'debit',0,'credit',v_diff,'po_id',v_po,'contractor_id',v_contractor)
        );
      else
        v_lines:=jsonb_build_array(
          jsonb_build_object('mapping_key',v_counterpart,'debit',abs(v_diff),'credit',0,'po_id',v_po,'contractor_id',v_contractor),
          jsonb_build_object('mapping_key','MATERIAL_INVENTORY','debit',0,'credit',abs(v_diff),'po_id',v_po,'contractor_id',v_contractor)
        );
      end if;

      insert into erp.material_cost_revaluation_events(material_id,movement_id,effective_date,old_inventory_delta,new_inventory_delta,delta_amount,counterpart_mapping_key,po_id,contractor_id)
      values(p_material_id,r.id,current_date,v_old,v_target,v_diff,v_counterpart,v_po,v_contractor)
      returning id into v_event;

      v_journal:=erp.post_journal('MATERIAL_COST_REVALUATION',v_event,current_date,
        'Automatic material moving-average recost: '||r.source_type,v_lines);
      update erp.material_cost_revaluation_events set journal_entry_id=v_journal where id=v_event;
    end if;

    insert into erp.material_cost_revaluation_state(movement_id,applied_inventory_delta,updated_at)
    values(r.id,v_target,now())
    on conflict(movement_id) do update set applied_inventory_delta=excluded.applied_inventory_delta,updated_at=now();
  end loop;
end;
$function$;

alter function "erp"."sync_material_cost_revaluation"(p_material_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.sync_material_purchase_grni_on_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_estimated numeric(24,6);v_journal uuid;v_reason text;
begin
  if old.status='DRAFT' and new.status='POSTED' then
    select coalesce(sum(i.line_total),0) into v_estimated
    from erp.material_purchase_items i
    where i.purchase_id=new.id and i.invoice_match_state<>'DIRECT_FINAL';
    if v_estimated>0.005 then
      perform erp.post_journal(
        'MATERIAL_PURCHASE_GRNI_RECLASS',new.id,new.physical_at::date,
        'Receipt without final supplier invoice: AP reclassified to GRNI',
        jsonb_build_array(
          jsonb_build_object('mapping_key','AP_SUPPLIER','debit',round(v_estimated,2),'credit',0),
          jsonb_build_object('mapping_key','GRNI_MATERIAL','debit',0,'credit',round(v_estimated,2))
        )
      );
    end if;
  elsif old.status='POSTED' and new.status='REVERSED' then
    select id into v_journal from erp.journal_entries
    where source_type='MATERIAL_PURCHASE_GRNI_RECLASS' and source_id=new.id and status='POSTED'
    order by posting_at desc,id desc limit 1;
    if v_journal is not null then
      v_reason:=coalesce(nullif(current_setting('app.change_reason',true),''),'Material purchase reversal');
      perform erp.reverse_journal(v_journal,v_reason);
    end if;
  end if;
  return new;
end;
$function$;

alter function "erp"."sync_material_purchase_grni_on_status"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.sync_opening_hpp_after_fg_adjustment_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare r record;
begin
  if new.status is not distinct from old.status then return new; end if;
  for r in select distinct fai.lot_id from erp.fg_adjustment_items fai join erp.fg_lots fl on fl.id=fai.lot_id where fai.adjustment_id=new.id and fl.lot_origin='OPENING' and exists(select 1 from erp.opening_lot_hpp_gl_state s where s.lot_id=fl.id)
  loop perform erp.sync_opening_lot_hpp_to_gl(r.lot_id,current_date); end loop;
  return new;
end;$function$;

