CREATE OR REPLACE FUNCTION erp.sync_opening_lot_hpp_to_gl(p_lot_id uuid, p_effective_date date DEFAULT CURRENT_DATE)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  l erp.fg_lots%rowtype;
  s erp.opening_lot_hpp_gl_state%rowtype;
  v_current_hpp numeric(20,6);
  v_baseline_hpp numeric(20,6);
  v_current_qty numeric(20,6);
  v_base_fg numeric(24,6);
  v_net_sold_qty numeric(20,6);
  v_actual_cogs numeric(24,6);
  v_target_fg numeric(24,6);
  v_target_cogs numeric(24,6);
  v_target_expense numeric(24,6):=0;
  v_target_income numeric(24,6):=0;
  v_target_equity numeric(24,6);
  v_df numeric(24,6);v_dc numeric(24,6);v_de numeric(24,6);v_di numeric(24,6);v_dq numeric(24,6);
  v_lines jsonb:='[]'::jsonb;v_event uuid;
begin
  perform erp.require_internal();
  select * into l from erp.fg_lots where id=p_lot_id for update;
  if l.id is null or l.lot_origin<>'OPENING' then return; end if;
  select hpp_per_pcs into v_current_hpp from erp.v_current_hpp where lot_id=l.id;
  if v_current_hpp is null then return; end if;
  select fm.unit_hpp_snapshot into v_baseline_hpp
  from erp.fg_stock_movements fm
  where fm.lot_id=l.id and fm.movement_type='OPENING'
  order by fm.physical_at,fm.system_created_at,fm.id limit 1;
  if v_baseline_hpp is null then raise exception 'Opening lot % tidak memiliki movement OPENING yang valid',l.lot_number; end if;

  select coalesce(sum(fm.qty_signed),0),coalesce(sum(fm.qty_signed*fm.unit_hpp_snapshot),0)
  into v_current_qty,v_base_fg from erp.fg_stock_movements fm where fm.lot_id=l.id;

  select coalesce(sum(a.qty_pcs),0),coalesce(sum(a.qty_pcs*a.unit_hpp_snapshot),0)
  into v_net_sold_qty,v_actual_cogs
  from erp.sale_stock_allocations a
  join erp.sales_items si on si.id=a.sale_item_id
  join erp.sales_headers sh on sh.id=si.sale_id
  where a.lot_id=l.id and sh.status in('POSTED','PARTIAL_PAID','PAID');

  select v_net_sold_qty-coalesce(sum(sri.qty_pcs),0),
         v_actual_cogs-coalesce(sum(sri.qty_pcs*sri.unit_hpp_snapshot),0)
  into v_net_sold_qty,v_actual_cogs
  from erp.sales_return_items sri
  join erp.sales_returns sr on sr.id=sri.return_id
  where sri.lot_id=l.id and sr.status='POSTED';

  -- Existing posted conversion before an opening-HPP correction requires lineage recost across destination lots.
  -- Keep this correction flow narrow and safe rather than silently misstate converted inventory.
  if abs(v_current_hpp-v_baseline_hpp)>0.000001 and exists(
    select 1 from erp.product_conversion_allocations pca join erp.product_conversions pc on pc.id=pca.conversion_id
    where pca.source_lot_id=l.id and pc.status='POSTED'
      and pca.original_hpp_per_pcs is distinct from v_current_hpp
  ) then
    raise exception 'Opening HPP lot % tidak dapat disinkron karena ada conversion lama yang memakai HPP sebelumnya. Reverse/correct conversion terkait dulu.',l.lot_number;
  end if;

  -- Revalue posted FG adjustments that were booked before the current HPP.
  select coalesce(sum(case when fai.qty_signed<0 then (-fai.qty_signed)*(v_current_hpp-fai.unit_hpp_snapshot) else 0 end),0),
         coalesce(sum(case when fai.qty_signed>0 then fai.qty_signed*(v_current_hpp-fai.unit_hpp_snapshot) else 0 end),0)
  into v_target_expense,v_target_income
  from erp.fg_adjustment_items fai
  join erp.fg_adjustments fa on fa.id=fai.adjustment_id
  where fai.lot_id=l.id and fa.status='POSTED';

  v_target_fg:=v_current_qty*v_current_hpp-v_base_fg;
  v_target_cogs:=v_net_sold_qty*v_current_hpp-v_actual_cogs;
  v_target_equity:=l.initial_qty_pcs*(v_current_hpp-v_baseline_hpp);

  -- Identity: FG + COGS + expense - income must equal opening-equity restatement.
  if abs((v_target_fg+v_target_cogs+v_target_expense-v_target_income)-v_target_equity)>0.02 then
    raise exception 'Opening HPP revaluation for lot % tidak reconcile. FG %, COGS %, expense %, income %, equity %. Ada movement yang perlu ditelusuri dulu.',l.lot_number,v_target_fg,v_target_cogs,v_target_expense,v_target_income,v_target_equity;
  end if;

  select * into s from erp.opening_lot_hpp_gl_state where lot_id=l.id for update;
  v_df:=v_target_fg-coalesce(s.fg_revaluation,0);
  v_dc:=v_target_cogs-coalesce(s.cogs_revaluation,0);
  v_de:=v_target_expense-coalesce(s.expense_revaluation,0);
  v_di:=v_target_income-coalesce(s.income_revaluation,0);
  v_dq:=v_target_equity-coalesce(s.equity_revaluation,0);

  if abs(v_df)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_df>0 then jsonb_build_object('mapping_key','FG_INVENTORY','debit',round(v_df,2),'credit',0,'product_id',l.product_id) else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',round(abs(v_df),2),'product_id',l.product_id) end); end if;
  if abs(v_dc)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_dc>0 then jsonb_build_object('mapping_key','COGS','debit',round(v_dc,2),'credit',0,'product_id',l.product_id) else jsonb_build_object('mapping_key','COGS','debit',0,'credit',round(abs(v_dc),2),'product_id',l.product_id) end); end if;
  if abs(v_de)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_de>0 then jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',round(v_de,2),'credit',0,'product_id',l.product_id) else jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',0,'credit',round(abs(v_de),2),'product_id',l.product_id) end); end if;
  if abs(v_di)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_di>0 then jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',round(v_di,2),'product_id',l.product_id) else jsonb_build_object('mapping_key','OTHER_INCOME','debit',round(abs(v_di),2),'credit',0,'product_id',l.product_id) end); end if;
  if abs(v_dq)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_dq>0 then jsonb_build_object('mapping_key','OPENING_EQUITY','debit',0,'credit',round(v_dq,2)) else jsonb_build_object('mapping_key','OPENING_EQUITY','debit',round(abs(v_dq),2),'credit',0) end); end if;

  if jsonb_array_length(v_lines)>=2 then
    v_event:=gen_random_uuid();
    perform erp.post_journal('OPENING_HPP_GL_SYNC',v_event,p_effective_date,'Opening FG HPP revaluation for lot '||l.lot_number,v_lines);
  end if;
  insert into erp.opening_lot_hpp_gl_state(lot_id,current_hpp,fg_revaluation,cogs_revaluation,expense_revaluation,income_revaluation,equity_revaluation,updated_at)
  values(l.id,v_current_hpp,v_target_fg,v_target_cogs,v_target_expense,v_target_income,v_target_equity,now())
  on conflict(lot_id) do update set current_hpp=excluded.current_hpp,fg_revaluation=excluded.fg_revaluation,cogs_revaluation=excluded.cogs_revaluation,expense_revaluation=excluded.expense_revaluation,income_revaluation=excluded.income_revaluation,equity_revaluation=excluded.equity_revaluation,updated_at=now();
end;$function$;

alter function "erp"."sync_opening_lot_hpp_to_gl"(p_lot_id uuid, p_effective_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.sync_po_hpp_to_gl(p_po_id uuid, p_effective_date date DEFAULT CURRENT_DATE)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  t record;
  s erp.po_hpp_gl_state%rowtype;
  v_target_qty integer:=0;
  v_target_hpp numeric(24,6):=0;
  v_target_fg numeric(24,6):=0;
  v_target_cogs numeric(24,6):=0;
  v_target_other numeric(24,6):=0;
  v_df numeric(24,6);v_dc numeric(24,6);v_do numeric(24,6);v_sum numeric(24,6);
  v_lines jsonb:='[]'::jsonb;v_event uuid;v_journal uuid;v_documented_gain numeric(24,6):=0;
begin
  perform erp.require_internal();
  select * into t from erp.compute_po_hpp_gl_targets(p_po_id);
  select * into s from erp.po_hpp_gl_state where po_id=p_po_id for update;

  if coalesce(t.base_output_qty,0)>0 then
    v_target_qty:=t.base_output_qty;
    v_target_hpp:=coalesce(t.hpp_total_cost,0);
    v_target_fg:=coalesce(t.fg_value,0);
    v_target_cogs:=coalesce(t.cogs_value,0);
    v_target_other:=coalesce(t.other_out_value,0);

    with lot_hpp as (
      select fl.id lot_id,case when coalesce(hv.qty_basis_pcs,0)>0 then hv.total_cost/hv.qty_basis_pcs else 0 end::numeric hpp_per_pcs
      from erp.fg_lots fl left join erp.hpp_versions hv on hv.lot_id=fl.id and hv.is_current=true
      where fl.po_id=p_po_id and fl.lot_origin<>'VOIDED_PRODUCTION'
    ), adj_net as (
      select fm.lot_id,sum(fm.qty_signed)::numeric qty
      from erp.fg_stock_movements fm join erp.fg_lots fl on fl.id=fm.lot_id
      where fl.po_id=p_po_id and fl.lot_origin<>'VOIDED_PRODUCTION'
        and ((fm.movement_type='ADJUSTMENT' and fm.source_type='FG_ADJUSTMENT_ITEM')
          or (fm.movement_type='REVERSAL' and exists(select 1 from erp.fg_stock_movements orig where orig.id=fm.reversal_of_id and orig.movement_type='ADJUSTMENT' and orig.source_type='FG_ADJUSTMENT_ITEM')))
      group by fm.lot_id
    )
    select coalesce(sum(greatest(a.qty,0)*lh.hpp_per_pcs),0) into v_documented_gain
    from adj_net a join lot_hpp lh on lh.lot_id=a.lot_id;

    if v_target_other < -v_documented_gain-0.01 then
      raise exception 'PO HPP allocation inconsistent: current FG + net sold exceeds production output without a matching documented positive FG adjustment';
    end if;
  else
    -- Important reversal boundary: when the last active production output is voided,
    -- unwind any prior HPP allocation instead of returning early and leaving FG/COGS stranded.
    v_target_qty:=0;v_target_hpp:=0;v_target_fg:=0;v_target_cogs:=0;v_target_other:=0;
    if s.po_id is null then return; end if;
  end if;

  v_df:=v_target_fg-coalesce(s.fg_value,0);
  v_dc:=v_target_cogs-coalesce(s.cogs_value,0);
  v_do:=v_target_other-coalesce(s.other_out_value,0);
  v_sum:=v_df+v_dc+v_do;

  if abs(v_df)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_df>0 then jsonb_build_object('mapping_key','FG_INVENTORY','debit',round(v_df,2),'credit',0,'po_id',p_po_id) else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',round(abs(v_df),2),'po_id',p_po_id) end); end if;
  if abs(v_dc)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_dc>0 then jsonb_build_object('mapping_key','COGS','debit',round(v_dc,2),'credit',0,'po_id',p_po_id) else jsonb_build_object('mapping_key','COGS','debit',0,'credit',round(abs(v_dc),2),'po_id',p_po_id) end); end if;
  if abs(v_do)>0.005 then
    if v_do>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',round(v_do,2),'credit',0,'po_id',p_po_id));
    else v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',round(abs(v_do),2),'po_id',p_po_id)); end if;
  end if;
  if abs(v_sum)>0.005 then v_lines:=v_lines||jsonb_build_array(case when v_sum>0 then jsonb_build_object('mapping_key','WIP','debit',0,'credit',round(v_sum,2),'po_id',p_po_id) else jsonb_build_object('mapping_key','WIP','debit',round(abs(v_sum),2),'credit',0,'po_id',p_po_id) end); end if;

  if jsonb_array_length(v_lines)>=2 then
    insert into erp.po_hpp_gl_events(po_id,effective_date,old_hpp_total,new_hpp_total,fg_delta,cogs_delta,other_delta)
    values(p_po_id,p_effective_date,coalesce(s.hpp_total_cost,0),v_target_hpp,v_df,v_dc,v_do) returning id into v_event;
    v_journal:=erp.post_journal('PO_HPP_GL_SYNC',v_event,p_effective_date,'Latest corrected HPP allocation',v_lines);
    update erp.po_hpp_gl_events set journal_entry_id=v_journal where id=v_event;
  end if;

  insert into erp.po_hpp_gl_state(po_id,base_output_qty,hpp_total_cost,fg_value,cogs_value,other_out_value,updated_at)
  values(p_po_id,v_target_qty,v_target_hpp,v_target_fg,v_target_cogs,v_target_other,now())
  on conflict(po_id) do update set base_output_qty=excluded.base_output_qty,hpp_total_cost=excluded.hpp_total_cost,fg_value=excluded.fg_value,cogs_value=excluded.cogs_value,other_out_value=excluded.other_out_value,updated_at=now();
end;
$function$;

alter function "erp"."sync_po_hpp_to_gl"(p_po_id uuid, p_effective_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.touch_laundry_receipt_from_bs_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_line uuid:=case when tg_op='DELETE' then old.receipt_line_id else new.receipt_line_id end;
begin
  update erp.laundry_receipts lr
  set updated_at=now()
  from erp.laundry_receipt_lines lrl
  where lrl.id=v_line and lr.id=lrl.receipt_id and lr.status='DRAFT';
  if tg_op='DELETE' then return old; else return new; end if;
end;
$function$;

