alter function "erp"."validate_fabric_profile"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_laundry_bs_product_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_status text;
  v_physical_at timestamptz;
  v_po_model uuid;
  v_product_model uuid;
  v_product_size uuid;
  v_group uuid;
begin
  select lr.status,lr.physical_at,po.model_id,p.model_id,p.size_id,ldl.cutting_group_id
  into v_status,v_physical_at,v_po_model,v_product_model,v_product_size,v_group
  from erp.laundry_receipt_lines lrl
  join erp.laundry_receipts lr on lr.id=lrl.receipt_id
  join erp.laundry_delivery_lines ldl on ldl.id=lrl.delivery_line_id
  join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
  join erp.production_orders po on po.id=ld.po_id
  join erp.products p on p.id=new.product_id
  where lrl.id=new.receipt_line_id;

  if v_status is null then raise exception 'Laundry receipt line/product not found'; end if;
  if v_status<>'DRAFT' then raise exception 'Laundry BS product allocation is editable only while receipt is DRAFT'; end if;
  if v_product_model is distinct from v_po_model then
    raise exception 'Laundry BS product model does not match the production order model';
  end if;
  if not exists(
    select 1 from erp.cutting_group_size_slots s
    where s.cutting_group_id=v_group and s.size_id=v_product_size
  ) then
    raise exception 'Laundry BS product size is not present in the source Potongan';
  end if;
  perform erp.assert_product_identity_time(new.product_id,v_physical_at,'NEW_STOCK');
  new.created_by:=coalesce(new.created_by,erp.current_app_user_id());
  return new;
end;
$function$;

alter function "erp"."validate_laundry_bs_product_allocation"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_laundry_claim_lineage()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_delivery_vendor uuid;
  v_line_delivery uuid;
  v_bs integer;
  v_sent integer;
  v_returned integer;
  v_other_claimed integer;
begin
  if new.delivery_id is null then
    if new.receipt_line_id is null then raise exception 'Laundry claim requires delivery or receipt line'; end if;
    select lr.delivery_id into new.delivery_id
    from erp.laundry_receipt_lines lrl join erp.laundry_receipts lr on lr.id=lrl.receipt_id
    where lrl.id=new.receipt_line_id;
  end if;

  perform 1 from erp.laundry_deliveries where id=new.delivery_id for update;
  select vendor_id into v_delivery_vendor from erp.laundry_deliveries where id=new.delivery_id;
  if v_delivery_vendor is null then raise exception 'Laundry delivery not found'; end if;
  if new.vendor_id is distinct from v_delivery_vendor then raise exception 'Laundry claim vendor must match delivery vendor'; end if;

  if new.receipt_line_id is not null then
    perform 1 from erp.laundry_receipt_lines where id=new.receipt_line_id for update;
    select lr.delivery_id,lrl.qty_bs_laundry into v_line_delivery,v_bs
    from erp.laundry_receipt_lines lrl join erp.laundry_receipts lr on lr.id=lrl.receipt_id
    where lrl.id=new.receipt_line_id;
    if v_line_delivery is distinct from new.delivery_id then raise exception 'Laundry claim receipt line does not belong to delivery'; end if;
  end if;

  if new.claim_type in ('MISSING','STUCK') then
    select coalesce(sum(ldl.qty_sent_pcs),0) into v_sent from erp.laundry_delivery_lines ldl where ldl.delivery_id=new.delivery_id;
    select coalesce(sum(lrl.qty_good_received+lrl.qty_bs_laundry),0) into v_returned
    from erp.laundry_receipt_lines lrl join erp.laundry_receipts lr on lr.id=lrl.receipt_id
    where lr.delivery_id=new.delivery_id and lr.status='POSTED';
    select coalesce(sum(lc.qty_claimed),0) into v_other_claimed
    from erp.laundry_claims lc
    where lc.delivery_id=new.delivery_id and lc.id<>new.id and lc.claim_type in ('MISSING','STUCK') and lc.status not in ('REJECTED');
    if v_other_claimed+new.qty_claimed>greatest(v_sent-v_returned,0) then
      raise exception 'Laundry missing/stuck claims exceed currently unreturned quantity. Outstanding %, other claims %, requested %',greatest(v_sent-v_returned,0),v_other_claimed,new.qty_claimed;
    end if;
  elsif new.claim_type='DAMAGE' then
    if new.receipt_line_id is null then raise exception 'Laundry DAMAGE claim must reference the receipt line where damaged/BS pieces returned'; end if;
    select coalesce(sum(lc.qty_claimed),0) into v_other_claimed from erp.laundry_claims lc
    where lc.receipt_line_id=new.receipt_line_id and lc.id<>new.id and lc.claim_type='DAMAGE' and lc.status<>'REJECTED';
    if v_other_claimed+new.qty_claimed>coalesce(v_bs,0) then raise exception 'Laundry DAMAGE claim exceeds BS quantity on receipt line'; end if;
  end if;
  return new;
end;
$function$;

alter function "erp"."validate_laundry_claim_lineage"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_laundry_receipt_line()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ DECLARE v_sent integer;v_other integer;v_receipt_delivery uuid;v_line_delivery uuid;v_remaining integer; BEGIN SELECT lr.delivery_id INTO v_receipt_delivery FROM erp.laundry_receipts lr WHERE lr.id=NEW.receipt_id; SELECT ldl.delivery_id,ldl.qty_sent_pcs INTO v_line_delivery,v_sent FROM erp.laundry_delivery_lines ldl WHERE ldl.id=NEW.delivery_line_id; IF v_sent IS NULL THEN RAISE EXCEPTION 'Laundry delivery line not found'; END IF; IF v_receipt_delivery IS NULL OR v_receipt_delivery<>v_line_delivery THEN RAISE EXCEPTION 'Receipt and receipt line belong to different laundry deliveries'; END IF; SELECT COALESCE(SUM(lrl.qty_good_received+lrl.qty_bs_laundry),0) INTO v_other FROM erp.laundry_receipt_lines lrl JOIN erp.laundry_receipts lr ON lr.id=lrl.receipt_id WHERE lrl.delivery_line_id=NEW.delivery_line_id AND lrl.id<>NEW.id AND lr.status<>'REVERSED'; IF v_other+NEW.qty_good_received+NEW.qty_bs_laundry>v_sent THEN RAISE EXCEPTION 'Cumulative laundry physical return exceeds quantity sent'; END IF; v_remaining:=v_sent-v_other-NEW.qty_good_received-NEW.qty_bs_laundry; IF NEW.qty_stuck+NEW.qty_missing>v_remaining THEN RAISE EXCEPTION 'STUCK + MISSING exceeds remaining unreturned quantity'; END IF; IF NEW.actual_cost_status='FINAL' AND NEW.actual_cost IS NOT NULL THEN RETURN NEW; END IF; IF NEW.actual_rate_snapshot IS NULL THEN NEW.actual_cost:=NULL; IF NEW.actual_cost_status='FINAL' THEN RAISE EXCEPTION 'FINAL laundry cost requires actual_cost or actual_rate_snapshot'; END IF; NEW.actual_cost_status:='PENDING'; ELSE NEW.actual_cost:=(NEW.qty_good_received+NEW.qty_bs_laundry)*NEW.actual_rate_snapshot; IF NEW.actual_cost_status='PENDING' THEN NEW.actual_cost_status:='ESTIMATED'; END IF; END IF; RETURN NEW; END; $function$;

alter function "erp"."validate_laundry_receipt_line"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_material_accessory_category()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ DECLARE v_base_uom varchar(20); BEGIN IF NEW.accessory_category_id IS NULL THEN RETURN NEW; END IF; IF NEW.material_type<>'ACCESSORY' THEN RAISE EXCEPTION 'Only ACCESSORY materials may be assigned to an accessory category'; END IF;SELECT base_uom_code INTO v_base_uom FROM erp.accessory_categories WHERE id=NEW.accessory_category_id; IF v_base_uom IS NULL THEN RAISE EXCEPTION 'Accessory category not found'; END IF; IF NEW.unit_code<>v_base_uom THEN RAISE EXCEPTION 'Accessory variant base UOM % must match category base UOM %',NEW.unit_code,v_base_uom; END IF;RETURN NEW;END; $function$;

alter function "erp"."validate_material_accessory_category"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_material_kasbon_deduction()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_payroll_contractor uuid;v_issue_contractor uuid;v_total numeric(24,6);v_already_item numeric(24,6):=0;
  v_labor numeric(24,6):=0;v_attendance numeric(24,6):=0;v_reimburse numeric(24,6):=0;v_manual numeric(24,6):=0;
  v_other_deduction numeric(24,6):=0;v_material_current numeric(24,6):=0;v_available numeric(24,6):=0;
begin
  if new.deduction_type<>'MATERIAL_KASBON' then return new; end if;
  if new.contractor_issue_item_id is null then raise exception 'MATERIAL_KASBON deduction requires contractor issue item'; end if;
  if new.amount is null or new.amount<=0 then raise exception 'MATERIAL_KASBON deduction amount must be positive'; end if;
  perform pg_advisory_xact_lock(hashtextextended('PAYKASBON|'||new.contractor_issue_item_id::text,0));
  select ps.contractor_id,ps.manual_adjustment into v_payroll_contractor,v_manual from erp.payroll_settlements ps where ps.id=new.payroll_id;
  select cmi.contractor_id,coalesce(cmii.total_receivable,0) into v_issue_contractor,v_total
  from erp.contractor_material_issue_items cmii join erp.contractor_material_issues cmi on cmi.id=cmii.issue_id
  where cmii.id=new.contractor_issue_item_id;
  if v_issue_contractor is null or v_issue_contractor is distinct from v_payroll_contractor then raise exception 'Kasbon item contractor does not match payroll contractor'; end if;
  select coalesce(sum(pd.amount),0) into v_already_item
  from erp.payroll_deductions pd join erp.payroll_settlements ps on ps.id=pd.payroll_id
  where pd.contractor_issue_item_id=new.contractor_issue_item_id and pd.deduction_type='MATERIAL_KASBON'
    and pd.id<>new.id and ps.status<>'REVERSED';
  if v_already_item+new.amount>v_total+0.01 then raise exception 'Kasbon deduction exceeds outstanding receivable. Total %, already allocated %, requested %',v_total,v_already_item,new.amount; end if;
  select coalesce(sum(amount),0) into v_labor from erp.payroll_work_items where payroll_id=new.payroll_id;
  select coalesce(sum(amount),0) into v_attendance from erp.payroll_attendance_items where payroll_id=new.payroll_id;
  select coalesce(sum(amount),0) into v_reimburse from erp.payroll_reimbursements where payroll_id=new.payroll_id;
  select coalesce(sum(amount),0) into v_other_deduction from erp.payroll_deductions where payroll_id=new.payroll_id and deduction_type<>'MATERIAL_KASBON' and id<>new.id;
  select coalesce(sum(amount),0) into v_material_current from erp.payroll_deductions where payroll_id=new.payroll_id and deduction_type='MATERIAL_KASBON' and id<>new.id;
  v_available:=greatest(v_labor+v_attendance+v_reimburse+coalesce(v_manual,0)-v_other_deduction-v_material_current,0);
  if new.amount>v_available+0.01 then raise exception 'Kasbon deduction is capped by available payroll earnings. Available %, requested %',v_available,new.amount; end if;
  return new;
end;
$function$;

alter function "erp"."validate_material_kasbon_deduction"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_material_purchase_cost_correction_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_purchase uuid;
  v_item_purchase uuid;
  v_material_type text;
  v_purchase_status text;
begin
  select purchase_id into v_purchase from erp.material_purchase_cost_corrections where id=new.correction_id;
  if v_purchase is null then raise exception 'Cost correction header not found'; end if;
  select mpi.purchase_id,m.material_type,mph.status into v_item_purchase,v_material_type,v_purchase_status
  from erp.material_purchase_items mpi
  join erp.materials m on m.id=mpi.material_id
  join erp.material_purchase_headers mph on mph.id=mpi.purchase_id
  where mpi.id=new.purchase_item_id;
  if v_item_purchase is null or v_item_purchase<>v_purchase then raise exception 'Cost correction item does not belong to correction purchase'; end if;
  if v_purchase_status<>'POSTED' then raise exception 'Only a POSTED material purchase can receive a late invoice cost correction'; end if;
  if v_material_type<>'FABRIC' then raise exception 'Late invoice cost correction is enabled only for FABRIC; accessory costing uses its separate policy'; end if;
  if exists (
    select 1 from erp.material_supplier_return_items msri
    join erp.material_supplier_returns msr on msr.id=msri.return_id
    where msri.purchase_item_id=new.purchase_item_id and msr.status='POSTED'
  ) then raise exception 'Purchase item already has a posted supplier return; correct/reverse that return before changing historical fabric purchase cost'; end if;
  return new;
end;
$function$;

alter function "erp"."validate_material_purchase_cost_correction_item"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_material_stock_movement_lineage()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if new.location_id is null then raise exception 'Material stock movement requires a location'; end if;
  if not exists (select 1 from erp.locations l where l.id=new.location_id and l.is_active=true and l.location_type='RAW_MATERIAL_WAREHOUSE') then
    raise exception 'Material stock movement location must be an active raw-material warehouse';
  end if;
  if new.roll_id is not null and not exists (select 1 from erp.material_rolls mr where mr.id=new.roll_id and mr.material_id=new.material_id) then
    raise exception 'Material movement roll does not belong to the selected material';
  end if;
  return new;
end;
$function$;

alter function "erp"."validate_material_stock_movement_lineage"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_material_supplier_invoice_line()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_invoice_supplier uuid;v_purchase_supplier uuid;v_status text;
begin
  select supplier_id,status into v_invoice_supplier,v_status
  from erp.material_supplier_invoices where id=new.invoice_id;
  if v_status is null then raise exception 'Supplier invoice header not found'; end if;
  if v_status<>'DRAFT' then raise exception 'Supplier invoice lines may only change while DRAFT'; end if;

  select h.supplier_id into v_purchase_supplier
  from erp.material_purchase_items i
  join erp.material_purchase_headers h on h.id=i.purchase_id
  where i.id=new.purchase_item_id and h.status='POSTED';
  if v_purchase_supplier is null then raise exception 'Invoice line must reference a POSTED material receipt'; end if;
  if v_purchase_supplier is distinct from v_invoice_supplier then
    raise exception 'Invoice supplier does not match receipt supplier';
  end if;
  return new;
end;
$function$;

alter function "erp"."validate_material_supplier_invoice_line"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_migration_batch(p_batch_id uuid)
 RETURNS TABLE(total_rows bigint, valid_rows bigint, error_rows bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
begin
  return query select * from erp._validate_migration_batch_base(p_batch_id);
  perform erp.validate_migration_opening_stock_costs(p_batch_id);
end;$function$;

alter function "erp"."validate_migration_batch"(p_batch_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_migration_opening_stock_costs(p_batch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  r record;j jsonb;v_bt text;v_method text;v_product uuid;
begin
  perform erp.require_owner_admin();
  for r in select * from erp.migration_staging_rows where batch_id=p_batch_id and entity_type='OPENING_BALANCE_ITEM' and validation_status='VALID' loop
    j:=r.normalized_payload;v_bt:=upper(coalesce(j->>'balance_type',''));v_method:=coalesce(nullif(upper(j->>'hpp_input_method'),''),'MANUAL');
    if v_bt='MATERIAL' and nullif(j->>'unit_cost','') is null then raise exception 'Migration opening MATERIAL row % wajib punya unit_cost (0 boleh)',r.source_row_no; end if;
    if v_bt='FINISHED_GOODS' then
      if v_method not in('MANUAL','PRICE_PERCENT') then raise exception 'Migration opening FG row % hpp_input_method harus MANUAL atau PRICE_PERCENT',r.source_row_no; end if;
      if v_method='MANUAL' and nullif(j->>'unit_cost','') is null then raise exception 'Migration opening FG row % wajib punya unit_cost atau PRICE_PERCENT',r.source_row_no; end if;
      if v_method='PRICE_PERCENT' and (nullif(j->>'hpp_percent_of_price','') is null or (j->>'hpp_percent_of_price')::numeric<=0) then raise exception 'Migration opening FG row % wajib punya hpp_percent_of_price > 0',r.source_row_no; end if;
      begin
        v_product:=erp.resolve_opening_product_identity(
          j->>'product_sku',
          (select cutover_at from erp.migration_batches where id=p_batch_id),
          j->>'color_name',j->>'size_code',j->>'model_code',j->>'brand_code'
        );
      exception when others then
        raise exception 'Migration opening FG row %: %',r.source_row_no,sqlerrm;
      end;
    end if;
  end loop;
end$function$;

alter function "erp"."validate_migration_opening_stock_costs"(p_batch_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_misc_category_type()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ DECLARE v_type varchar(20); BEGIN SELECT category_type INTO v_type FROM erp.misc_finance_categories WHERE id=NEW.category_id; IF v_type IS NULL OR v_type<>NEW.transaction_type THEN RAISE EXCEPTION 'Finance category type does not match transaction type'; END IF; RETURN NEW; END; $function$;

alter function "erp"."validate_misc_category_type"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_misc_finance_category_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_type text;v_active boolean;v_protected boolean;
begin
  select account_type,is_active into v_type,v_active from erp.chart_accounts where id=new.default_account_id;
  if v_type is null or coalesce(v_active,false)=false then raise exception 'Misc finance category requires an active chart account'; end if;
  if new.category_type='OTHER_INCOME' and v_type<>'REVENUE' then raise exception 'OTHER_INCOME category must use a revenue account'; end if;
  if new.category_type='OTHER_EXPENSE' and v_type<>'EXPENSE' then raise exception 'OTHER_EXPENSE category must use an expense account'; end if;
  select exists(
    select 1 from erp.accounting_account_mappings aam
    where aam.account_id=new.default_account_id
      and aam.mapping_key not in ('OTHER_INCOME','OTHER_EXPENSE')
  ) into v_protected;
  if v_protected then raise exception 'This account is reserved for a core ERP workflow and cannot be used by Pendapatan/Pengeluaran Lain-lain'; end if;
  return new;
end;$function$;

alter function "erp"."validate_misc_finance_category_account"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_payroll_attendance_unique()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended('PAYATT|'||new.attendance_record_id::text,0));
  if exists (
    select 1 from erp.payroll_attendance_items pai
    join erp.payroll_settlements ps on ps.id=pai.payroll_id
    where pai.attendance_record_id=new.attendance_record_id and pai.id<>new.id and ps.status<>'REVERSED'
  ) then raise exception 'Attendance record is already allocated to another payroll'; end if;
  return new;
end;
$function$;

alter function "erp"."validate_payroll_attendance_unique"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_payroll_reimbursement_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_contractor uuid;v_ent_contractor uuid;v_amount numeric(24,6);v_po_id uuid;
begin
  if new.source_type='ACCESSORY_BOM' then
    if new.source_id is null then raise exception 'ACCESSORY_BOM reimbursement requires source_id'; end if;
    perform pg_advisory_xact_lock(hashtextextended('PAYREIMB|'||new.source_id::text,0));
    select contractor_id,amount,po_id into v_ent_contractor,v_amount,v_po_id
    from erp.contractor_accessory_reimbursement_entitlements where id=new.source_id;
    select contractor_id into v_contractor from erp.payroll_settlements where id=new.payroll_id;
    if v_ent_contractor is null or v_contractor is distinct from v_ent_contractor then raise exception 'Accessory reimbursement entitlement contractor does not match payroll'; end if;
    new.amount:=round(v_amount,2);new.po_id:=v_po_id;
    if exists (
      select 1 from erp.payroll_reimbursements pr join erp.payroll_settlements ps on ps.id=pr.payroll_id
      where pr.source_type='ACCESSORY_BOM' and pr.source_id=new.source_id and pr.id<>new.id and ps.status<>'REVERSED'
    ) then raise exception 'Accessory reimbursement entitlement already allocated to another payroll'; end if;
  else new.source_id:=null; end if;
  return new;
end;
$function$;

alter function "erp"."validate_payroll_reimbursement_source"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_payroll_work_item_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_source_qty integer;
  v_source_component uuid;
  v_source_po uuid;
  v_source_contractor uuid;
  v_payroll_contractor uuid;
  v_already integer;
begin
  perform pg_advisory_xact_lock(hashtextextended(
    'PAYWORK|'||new.source_type||'|'||new.source_id::text||'|'||new.work_component_id::text,0
  ));
  select contractor_id into v_payroll_contractor
  from erp.payroll_settlements where id=new.payroll_id;

  if new.source_type='PRODUCTION' then
    select eligible_after_laundry_qty,work_component_id,po_id,contractor_id
    into v_source_qty,v_source_component,v_source_po,v_source_contractor
    from erp.v_payroll_production_work_eligibility
    where source_id=new.source_id;
  elsif new.source_type='REWORK' then
    select rcl.qty_newly_payable,bcc.work_component_id,bc.po_id,ro.contractor_id
    into v_source_qty,v_source_component,v_source_po,v_source_contractor
    from erp.rework_component_lines rcl
    join erp.bs_case_components bcc on bcc.id=rcl.bs_case_component_id
    join erp.bs_cases bc on bc.id=bcc.bs_case_id
    join erp.rework_orders ro on ro.id=rcl.rework_order_id
    where rcl.id=new.source_id
      and ro.destination_type='CONTRACTOR'
      and ro.status='COMPLETED'
      and ro.cost_posted
      and bc.status='RESOLVED';
  else
    raise exception 'Payroll source_type must be PRODUCTION or REWORK';
  end if;

  if v_source_qty is null then raise exception 'Payroll source is not currently eligible'; end if;
  if new.work_component_id<>v_source_component then raise exception 'Payroll work component does not match source'; end if;
  if new.po_id is distinct from v_source_po then raise exception 'Payroll PO does not match source'; end if;
  if v_source_contractor is not null and v_payroll_contractor<>v_source_contractor then
    raise exception 'Payroll contractor does not match work source';
  end if;

  select coalesce(sum(pwi.qty_payable),0) into v_already
  from erp.payroll_work_items pwi
  join erp.payroll_settlements ps on ps.id=pwi.payroll_id
  where pwi.source_type=new.source_type and pwi.source_id=new.source_id
    and pwi.work_component_id=new.work_component_id and pwi.id<>new.id
    and ps.status<>'REVERSED';
  if v_already+new.qty_payable>v_source_qty then
    raise exception 'Payroll would overpay/early-pay work source. Eligible %, already %, new %',
      v_source_qty,v_already,new.qty_payable;
  end if;
  return new;
end;
$function$;

alter function "erp"."validate_payroll_work_item_source"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_product_identity_period()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_end timestamptz:=coalesce(new.effective_to,'infinity'::timestamptz);
begin
  if new.identity_root_id is null then new.identity_root_id:=new.id; end if;
  if new.effective_from is null then new.effective_from:=clock_timestamp(); end if;
  if new.effective_to is not null and new.effective_to<=new.effective_from then
    raise exception 'Tanggal akhir identitas SKU harus setelah tanggal mulai berlaku';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('SKU:'||lower(trim(new.sku)),0));
  perform pg_advisory_xact_lock(hashtextextended('SKUCOMBO:'||new.model_id::text||':'||new.brand_id::text||':'||lower(trim(new.color_name))||':'||new.size_id::text,0));

  if exists(
    select 1 from erp.products p
    where p.id<>new.id
      and p.identity_root_id=new.identity_root_id
      and tstzrange(p.effective_from,coalesce(p.effective_to,'infinity'::timestamptz),'[)')
          && tstzrange(new.effective_from,v_end,'[)')
  ) then
    raise exception 'Periode perubahan SKU bertumpuk dengan versi SKU yang sama. Koreksi tanggal berlaku terlebih dahulu.';
  end if;

  if exists(
    select 1 from erp.products p
    where p.id<>new.id
      and p.identity_root_id<>new.identity_root_id
      and lower(trim(p.sku))=lower(trim(new.sku))
      and tstzrange(p.effective_from,coalesce(p.effective_to,'infinity'::timestamptz),'[)')
          && tstzrange(new.effective_from,v_end,'[)')
  ) then
    raise exception 'Kode SKU % sudah dipakai SKU lain pada periode yang sama',new.sku;
  end if;

  if exists(
    select 1 from erp.products p
    where p.id<>new.id
      and p.identity_root_id<>new.identity_root_id
      and p.model_id=new.model_id and p.brand_id=new.brand_id
      and lower(trim(p.color_name))=lower(trim(new.color_name)) and p.size_id=new.size_id
      and tstzrange(p.effective_from,coalesce(p.effective_to,'infinity'::timestamptz),'[)')
          && tstzrange(new.effective_from,v_end,'[)')
  ) then
    raise exception 'Kombinasi model/merek/warna/size sudah dipakai SKU lain pada periode yang sama';
  end if;
  return new;
end$function$;

alter function "erp"."validate_product_identity_period"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_qc_product_model()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ DECLARE v_po_model uuid;v_product_model uuid;v_size_id uuid; BEGIN SELECT po.model_id INTO v_po_model FROM erp.qc_inspections qi JOIN erp.production_orders po ON po.id=qi.po_id WHERE qi.id=NEW.inspection_id; SELECT model_id,size_id INTO v_product_model,v_size_id FROM erp.products WHERE id=NEW.final_product_id; IF v_po_model IS NULL OR v_product_model IS NULL OR v_po_model<>v_product_model THEN RAISE EXCEPTION 'Final SKU model does not match PO model'; END IF; IF NOT EXISTS (SELECT 1 FROM erp.product_model_sizes pms WHERE pms.model_id=v_po_model AND pms.size_id=v_size_id) THEN RAISE EXCEPTION 'Final SKU size is not allowed for this model'; END IF; RETURN NEW; END; $function$;

alter function "erp"."validate_qc_product_model"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_qc_source_quantity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_qc_po uuid;v_qc_at timestamptz;v_group_po uuid;v_group_cut_at timestamptz;v_group_pickup timestamptz;
  v_source_po uuid;v_source_good integer;v_already integer;v_receipt_status text;v_receipt_at timestamptz;
begin
  select po_id,physical_at into v_qc_po,v_qc_at from erp.qc_inspections where id=new.inspection_id;
  if v_qc_po is null then raise exception 'QC inspection not found'; end if;
  if new.qty_good_pcs+new.qty_bs_pcs<=0 then raise exception 'QC item must account for at least 1 piece'; end if;
  if new.cutting_group_id is not null then
    select po_id,cut_at,picked_up_at into v_group_po,v_group_cut_at,v_group_pickup from erp.cutting_groups where id=new.cutting_group_id;
    if v_group_po is distinct from v_qc_po then raise exception 'QC cutting group does not belong to QC PO'; end if;
    if v_qc_at<v_group_cut_at then raise exception 'Tanggal/jam QC tidak boleh lebih awal dari tanggal/jam potong'; end if;
    if v_group_pickup is not null and v_qc_at<v_group_pickup then raise exception 'Tanggal/jam QC tidak boleh lebih awal dari tanggal/jam potongan diambil mandor'; end if;
  end if;
  if new.source_laundry_receipt_line_id is not null then
    select ld.po_id,lrl.qty_good_received,lr.status,lr.physical_at
      into v_source_po,v_source_good,v_receipt_status,v_receipt_at
    from erp.laundry_receipt_lines lrl
    join erp.laundry_receipts lr on lr.id=lrl.receipt_id
    join erp.laundry_delivery_lines ldl on ldl.id=lrl.delivery_line_id
    join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
    where lrl.id=new.source_laundry_receipt_line_id;
    if v_source_po is distinct from v_qc_po or v_receipt_status<>'POSTED' then raise exception 'QC laundry source must be a POSTED receipt from the same PO'; end if;
    if v_qc_at<v_receipt_at then raise exception 'Tanggal/jam QC tidak boleh lebih awal dari barang diterima kembali dari laundry'; end if;
    select coalesce(sum(qii.qty_good_pcs+qii.qty_bs_pcs),0) into v_already
    from erp.qc_inspection_items qii join erp.qc_inspections qi on qi.id=qii.inspection_id
    where qii.source_laundry_receipt_line_id=new.source_laundry_receipt_line_id and qii.id<>new.id and qi.status<>'REVERSED';
    if v_already+new.qty_good_pcs+new.qty_bs_pcs>coalesce(v_source_good,0) then raise exception 'QC accounted quantity exceeds GOOD quantity physically returned from laundry'; end if;
  end if;
  return new;
end;
$function$;

alter function "erp"."validate_qc_source_quantity"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_rework_quantity_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_bs_qty integer;v_bs_status text;v_bs_at timestamptz;
  v_resolved integer:=0;v_other_active integer:=0;v_available integer:=0;
  v_require_active_source boolean:=false;
begin
  select qty_pcs,status,physical_at into v_bs_qty,v_bs_status,v_bs_at from erp.bs_cases where id=new.bs_case_id;
  if v_bs_qty is null then raise exception 'BS case not found'; end if;
  v_require_active_source := new.status<>'CANCELLED' and (
       tg_op='INSERT' or new.bs_case_id is distinct from old.bs_case_id or new.qty_sent is distinct from old.qty_sent
       or new.physical_sent_at is distinct from old.physical_sent_at or new.status is distinct from old.status);
  if v_require_active_source and v_bs_status not in ('OPEN','IN_REWORK','PARTIAL') then
    raise exception 'BS case status % tidak dapat memulai/diubah menjadi rework aktif',v_bs_status;
  end if;
  if new.physical_sent_at<v_bs_at then raise exception 'Tanggal/jam kirim rework tidak boleh lebih awal dari waktu BS terdeteksi'; end if;
  if new.physical_sent_at>clock_timestamp()+interval '5 minutes' then raise exception 'Tanggal/jam kirim rework berada di masa depan'; end if;
  if new.completed_at is not null and new.completed_at<new.physical_sent_at then raise exception 'Tanggal/jam selesai rework tidak boleh lebih awal dari waktu kirim rework'; end if;
  if new.completed_at is not null and new.completed_at>clock_timestamp()+interval '5 minutes' then raise exception 'Tanggal/jam selesai rework berada di masa depan'; end if;
  if new.qty_sent<=0 or new.qty_good_returned<0 or new.qty_bs_returned<0 then raise exception 'Rework quantities must be positive/non-negative'; end if;
  if new.qty_good_returned+new.qty_bs_returned>new.qty_sent then raise exception 'Returned GOOD + BS cannot exceed qty sent'; end if;
  if new.status='COMPLETED' and new.qty_good_returned+new.qty_bs_returned<>new.qty_sent then raise exception 'Completed rework must reconcile exactly: GOOD + BS must equal qty sent'; end if;
  if new.status='PARTIAL' and (new.qty_good_returned+new.qty_bs_returned<=0 or new.qty_good_returned+new.qty_bs_returned>=new.qty_sent) then raise exception 'PARTIAL rework must have some returned qty but still leave outstanding qty'; end if;
  if (tg_op='INSERT' or new.bs_case_id is distinct from old.bs_case_id or new.qty_sent is distinct from old.qty_sent) and new.status<>'CANCELLED' then
    select coalesce(sum(br.qty_pcs),0) into v_resolved from erp.bs_resolutions br where br.bs_case_id=new.bs_case_id;
    select coalesce(sum(ro.qty_sent),0) into v_other_active from erp.rework_orders ro
    where ro.bs_case_id=new.bs_case_id and ro.id<>new.id and ro.status in ('OPEN','IN_PROGRESS','PARTIAL');
    v_available:=greatest(v_bs_qty-v_resolved-v_other_active,0);
    if new.qty_sent>v_available then raise exception 'Rework qty sent % exceeds currently available unresolved BS qty %',new.qty_sent,v_available; end if;
  end if;
  return new;
end$function$;

alter function "erp"."validate_rework_quantity_state"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_supplier_return_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_header_supplier uuid;
  v_purchase_supplier uuid;
  v_purchase_material uuid;
  v_purchase_qty numeric(18,6);
  v_purchase_price numeric(18,6);
  v_roll_purchase_item uuid;
  v_prior numeric(18,6);
  v_current numeric(18,6);
begin
  select supplier_id into v_header_supplier from erp.material_supplier_returns where id=new.return_id;
  if v_header_supplier is null then raise exception 'Supplier return header not found'; end if;
  if new.roll_id is not null then
    select purchase_item_id into v_roll_purchase_item from erp.material_rolls where id=new.roll_id;
    if v_roll_purchase_item is null then raise exception 'Returned roll has no source purchase item'; end if;
    if new.purchase_item_id is not null and new.purchase_item_id is distinct from v_roll_purchase_item then raise exception 'Return purchase item does not match roll source purchase'; end if;
    new.purchase_item_id:=v_roll_purchase_item;
  end if;
  if new.purchase_item_id is null then raise exception 'Supplier return line must reference the source purchase item'; end if;
  select mph.supplier_id,mpi.material_id,mpi.qty into v_purchase_supplier,v_purchase_material,v_purchase_qty
  from erp.material_purchase_items mpi join erp.material_purchase_headers mph on mph.id=mpi.purchase_id
  where mpi.id=new.purchase_item_id and mph.status='POSTED';
  if v_purchase_material is null then raise exception 'Source purchase item must belong to a POSTED purchase'; end if;
  if v_purchase_supplier is distinct from v_header_supplier then raise exception 'Supplier return source purchase belongs to a different supplier'; end if;
  if v_purchase_material is distinct from new.material_id then raise exception 'Supplier return material does not match source purchase item'; end if;
  v_purchase_price:=erp.material_purchase_current_unit_cost(new.purchase_item_id);
  new.supplier_credit_unit_price:=coalesce(new.supplier_credit_unit_price,v_purchase_price);
  select coalesce(sum(msri.qty),0) into v_prior from erp.material_supplier_return_items msri join erp.material_supplier_returns msr on msr.id=msri.return_id
  where msri.purchase_item_id=new.purchase_item_id and msri.id<>new.id and msr.status='POSTED';
  select coalesce(sum(msri.qty),0) into v_current from erp.material_supplier_return_items msri
  where msri.return_id=new.return_id and msri.purchase_item_id=new.purchase_item_id and msri.id<>new.id;
  if v_prior+v_current+new.qty>v_purchase_qty+0.000001 then raise exception 'Supplier return exceeds quantity from source purchase item. Purchased %, prior returned %, current draft incl line %',v_purchase_qty,v_prior,v_current+new.qty; end if;
  return new;
end;
$function$;

alter function "erp"."validate_supplier_return_source"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_vendor_invoice_item_lineage()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_header_vendor uuid;
  v_delivery_vendor uuid;
begin
  select vendor_id into v_header_vendor from erp.vendor_invoices where id=new.invoice_id;
  select ld.vendor_id into v_delivery_vendor
  from erp.laundry_receipt_lines lrl
  join erp.laundry_delivery_lines ldl on ldl.id=lrl.delivery_line_id
  join erp.laundry_deliveries ld on ld.id=ldl.delivery_id
  where lrl.id=new.receipt_line_id;
  if v_header_vendor is null then raise exception 'Vendor invoice header not found'; end if;
  if v_delivery_vendor is null then raise exception 'Laundry receipt line not found'; end if;
  if v_header_vendor is distinct from v_delivery_vendor then raise exception 'Vendor invoice vendor does not match laundry delivery vendor'; end if;
  return new;
end;
$function$;

alter function "erp"."validate_vendor_invoice_item_lineage"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.validate_work_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$ DECLARE v_event_po uuid;v_event_contractor uuid;v_po_contractor uuid;v_snapshot_po uuid;v_snapshot_component uuid;v_snapshot_rate numeric(18,2); BEGIN SELECT po_id,contractor_id INTO v_event_po,v_event_contractor FROM erp.work_completion_events WHERE id=NEW.completion_id; SELECT contractor_id INTO v_po_contractor FROM erp.production_orders WHERE id=v_event_po; SELECT po_id,work_component_id,rate_per_pcs_snapshot INTO v_snapshot_po,v_snapshot_component,v_snapshot_rate FROM erp.po_work_component_snapshots WHERE id=NEW.po_component_snapshot_id; IF v_event_po IS NULL THEN RAISE EXCEPTION 'Completion event not found'; END IF; IF v_po_contractor IS DISTINCT FROM v_event_contractor THEN RAISE EXCEPTION 'Completion contractor must match PO contractor'; END IF; IF v_snapshot_po<>v_event_po OR v_snapshot_component<>NEW.work_component_id THEN RAISE EXCEPTION 'Work component snapshot does not match completion PO/component'; END IF; NEW.rate_snapshot:=v_snapshot_rate; RETURN NEW; END; $function$;

alter function "erp"."validate_work_completion"() owner to "postgres";

