CREATE OR REPLACE FUNCTION public.erp_list_patterns_v1(p_status text DEFAULT 'ACTIVE'::text, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
