 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
  select r.id
  from erp.worker_daily_rate_versions r
  where r.worker_id = p_worker_id
    and p_effective_date >= r.effective_from
    and (r.effective_to is null or p_effective_date <= r.effective_to)
  order by r.effective_from desc, r.created_at desc, r.id desc
  limit 1
$function$;

alter function "erp"."worker_daily_rate_version_id_at"(p_worker_id uuid, p_effective_date date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.worker_is_employed_on(p_worker_id uuid, p_effective_date date)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
  select exists (
    select 1
    from erp.worker_employment_periods e
    where e.worker_id = p_worker_id
      and p_effective_date >= e.started_on
      and (e.ended_on is null or p_effective_date <= e.ended_on)
  )
$function$;

alter function "erp"."worker_is_employed_on"(p_worker_id uuid, p_effective_date date) owner to "postgres";

