create or replace view "erp"."v_accessory_category_current_cost" with (security_invoker=true) as
 SELECT id AS category_id,
    category_code,
    category_name,
    base_uom_code,
    erp.accessory_category_weighted_avg_cost_at(id, now()) AS weighted_avg_cost_per_base_uom
   FROM erp.accessory_categories c
  WHERE is_active = true;;

alter view "erp"."v_accessory_category_current_cost" owner to "postgres";

create or replace view "erp"."v_accessory_price_browser" with (security_invoker=true) as
 SELECT p.id AS price_version_id,
    p.category_id,
    ac.category_code,
    ac.category_name,
    p.contractor_id,
    c.contractor_code,
    c.contractor_name,
    p.selling_price,
    p.selling_uom_code,
    p.effective_from,
    p.effective_to,
    p.notes,
    p.effective_from <= now() AND (p.effective_to IS NULL OR p.effective_to > now()) AS is_current,
    concat_ws(' '::text, ac.category_code, ac.category_name, c.contractor_code, c.contractor_name, p.selling_uom_code) AS search_text
   FROM erp.contractor_accessory_price_versions p
     JOIN erp.accessory_categories ac ON ac.id = p.category_id
     LEFT JOIN erp.contractors c ON c.id = p.contractor_id;;

alter view "erp"."v_accessory_price_browser" owner to "postgres";

create or replace view "erp"."v_attendance_hpp_active_allocation_by_po" with (security_invoker=true) as
 SELECT p.id AS pool_id,
    p.period_start,
    p.period_end,
    a.po_id,
    sum(a.sewing_qty) AS sewing_qty,
    sum(a.allocated_amount)::numeric(20,2) AS attendance_hpp_amount
   FROM erp.attendance_hpp_pools p
     JOIN erp.attendance_hpp_pool_allocations a ON a.pool_id = p.id
  WHERE p.status::text = 'ACTIVE'::text
  GROUP BY p.id, p.period_start, p.period_end, a.po_id;;

alter view "erp"."v_attendance_hpp_active_allocation_by_po" owner to "postgres";

create or replace view "erp"."v_attendance_hpp_active_allocation_by_po_group" with (security_invoker=true) as
 SELECT p.id AS pool_id,
    p.period_start,
    p.period_end,
    a.po_id,
    a.cutting_group_id,
    sum(a.sewing_qty) AS sewing_qty,
    sum(a.allocated_amount)::numeric(20,2) AS attendance_hpp_amount
   FROM erp.attendance_hpp_pools p
     JOIN erp.attendance_hpp_pool_allocations a ON a.pool_id = p.id
  WHERE p.status::text = 'ACTIVE'::text
  GROUP BY p.id, p.period_start, p.period_end, a.po_id, a.cutting_group_id;;

alter view "erp"."v_attendance_hpp_active_allocation_by_po_group" owner to "postgres";

create or replace view "erp"."v_current_hpp" with (security_invoker=true) as
 SELECT DISTINCT ON (lot_id) lot_id,
    id AS hpp_version_id,
    version_no,
    cost_state,
    qty_basis_pcs,
    total_cost,
    hpp_per_pcs,
    calculated_at
   FROM erp.hpp_versions hv
  WHERE is_current = true
  ORDER BY lot_id, version_no DESC;;

alter view "erp"."v_current_hpp" owner to "postgres";

create or replace view "erp"."v_current_product_prices" with (security_invoker=true) as
 SELECT DISTINCT ON (product_id) product_id,
    price,
    effective_from
   FROM erp.product_price_versions ppv
  WHERE effective_from <= now() AND (effective_to IS NULL OR effective_to > now())
  ORDER BY product_id, effective_from DESC, created_at DESC;;

alter view "erp"."v_current_product_prices" owner to "postgres";

create or replace view "erp"."v_customer_receivables" with (security_invoker=true) as
 WITH invoice AS (
         SELECT sh_1.id AS sale_id,
            COALESCE(sum(si.line_total), 0::numeric)::numeric(20,2) AS gross_amount
           FROM erp.sales_headers sh_1
             JOIN erp.sales_items si ON si.sale_id = sh_1.id
          GROUP BY sh_1.id
        ), payment AS (
         SELECT sp.sale_id,
            COALESCE(sum(sp.amount), 0::numeric)::numeric(20,2) AS paid_amount
           FROM erp.sales_payments sp
          WHERE sp.status::text = 'POSTED'::text
          GROUP BY sp.sale_id
        ), returned AS (
         SELECT sr.sale_id,
            COALESCE(sum(sri.refund_amount), 0::numeric)::numeric(20,2) AS return_amount
           FROM erp.sales_returns sr
             JOIN erp.sales_return_items sri ON sri.return_id = sr.id
          WHERE sr.status::text = 'POSTED'::text
          GROUP BY sr.sale_id
        )
 SELECT sh.customer_id,
    c.customer_name,
    sh.id AS sale_id,
    sh.sale_number,
    sh.sale_date,
    sh.due_date,
    i.gross_amount AS invoice_amount,
    COALESCE(p.paid_amount, 0::numeric)::numeric(20,2) AS paid_amount,
    GREATEST(i.gross_amount - COALESCE(r.return_amount, 0::numeric) - COALESCE(p.paid_amount, 0::numeric), 0::numeric)::numeric(20,2) AS outstanding_amount,
    COALESCE(r.return_amount, 0::numeric)::numeric(20,2) AS posted_return_amount,
    GREATEST(i.gross_amount - COALESCE(r.return_amount, 0::numeric), 0::numeric)::numeric(20,2) AS net_invoice_amount,
    GREATEST(COALESCE(p.paid_amount, 0::numeric) - (i.gross_amount - COALESCE(r.return_amount, 0::numeric)), 0::numeric)::numeric(20,2) AS credit_amount
   FROM erp.sales_headers sh
     JOIN erp.customers c ON c.id = sh.customer_id
     JOIN invoice i ON i.sale_id = sh.id
     LEFT JOIN payment p ON p.sale_id = sh.id
     LEFT JOIN returned r ON r.sale_id = sh.id
  WHERE sh.status::text = ANY (ARRAY['POSTED'::character varying, 'PARTIAL_PAID'::character varying, 'PAID'::character varying]::text[]);;

alter view "erp"."v_customer_receivables" owner to "postgres";

create or replace view "erp"."v_cutting_group_size_totals" with (security_invoker=true) as
 SELECT cgs.cutting_group_id,
    cgs.size_id,
    s.size_code,
    sum(cry.qty_pcs) AS total_pcs
   FROM erp.cutting_group_size_slots cgs
     JOIN erp.sizes s ON s.id = cgs.size_id
     JOIN erp.cutting_roll_yields cry ON cry.size_slot_id = cgs.id
  GROUP BY cgs.cutting_group_id, cgs.size_id, s.size_code;;

alter view "erp"."v_cutting_group_size_totals" owner to "postgres";

create or replace view "erp"."v_cutting_qty_correction_history" with (security_invoker=true) as
 SELECT c.id AS correction_id,
    c.correction_number,
    c.cutting_batch_id,
    b.batch_number,
    b.row_version AS batch_row_version,
    b.po_id,
    po.po_number,
    pm.model_code,
    pm.model_name,
    c.correction_type,
    c.reason_code,
    c.reason,
    c.physical_at,
    c.created_at,
    c.posted_by,
    u.full_name AS posted_by_name,
    COALESCE(l.line_count, 0::bigint) AS line_count,
    COALESCE(l.net_delta_pcs, 0::bigint) AS net_delta_pcs,
    c.reversal_of_id,
    src.correction_number AS reversal_of_number,
    rv.id AS reversed_by_id,
    rv.correction_number AS reversed_by_number,
    rv.physical_at AS reversed_at,
        CASE
            WHEN c.correction_type::text = 'REVERSAL'::text THEN 'REVERSAL'::text
            WHEN rv.id IS NOT NULL THEN 'REVERSED'::text
            ELSE 'POSTED'::text
        END AS correction_status
   FROM erp.cutting_qty_corrections c
     JOIN erp.cutting_batches b ON b.id = c.cutting_batch_id
     JOIN erp.production_orders po ON po.id = b.po_id
     JOIN erp.product_models pm ON pm.id = po.model_id
     LEFT JOIN erp.app_users u ON u.id = c.posted_by
     LEFT JOIN erp.cutting_qty_corrections src ON src.id = c.reversal_of_id
     LEFT JOIN erp.cutting_qty_corrections rv ON rv.reversal_of_id = c.id
     LEFT JOIN LATERAL ( SELECT count(*) AS line_count,
            COALESCE(sum(cl.qty_delta_pcs), 0::bigint) AS net_delta_pcs
           FROM erp.cutting_qty_correction_lines cl
          WHERE cl.correction_id = c.id) l ON true;;

alter view "erp"."v_cutting_qty_correction_history" owner to "postgres";

create or replace view "erp"."v_cutting_roll_totals" with (security_invoker=true) as
 SELECT cgr.id AS cutting_group_roll_id,
    cgr.cutting_group_id,
    cgr.roll_id,
    COALESCE(sum(cry.qty_pcs), 0::bigint) AS total_pcs
   FROM erp.cutting_group_rolls cgr
     LEFT JOIN erp.cutting_roll_yields cry ON cry.cutting_group_roll_id = cgr.id
  GROUP BY cgr.id, cgr.cutting_group_id, cgr.roll_id;;

alter view "erp"."v_cutting_roll_totals" owner to "postgres";

create or replace view "erp"."v_fabric_master_current_benchmark" with (security_invoker=true) as
 SELECT m.id AS material_id,
    m.material_sku,
    m.material_name,
    m.unit_code AS base_uom_code,
    m.is_active,
    m.cached_stock_qty,
    m.moving_average_cost,
    m.row_version,
    fp.fabric_category,
    fp.composition,
    fp.construction,
    fp.color_name,
    fp.width_cm,
    fp.gsm,
    fp.minimum_stock_qty,
    fp.preferred_supplier_id,
    s.supplier_name AS preferred_supplier_name,
    bp.id AS benchmark_version_id,
    bp.benchmark_price_per_base_uom,
    bp.effective_from AS benchmark_effective_from,
    bp.effective_to AS benchmark_effective_to,
    bp.benchmark_price_per_base_uom - m.moving_average_cost AS benchmark_vs_moving_average_delta,
        CASE
            WHEN m.moving_average_cost = 0::numeric THEN NULL::numeric
            ELSE round((bp.benchmark_price_per_base_uom - m.moving_average_cost) / m.moving_average_cost * 100::numeric, 4)
        END AS benchmark_vs_moving_average_pct
   FROM erp.materials m
     LEFT JOIN erp.fabric_master_profiles fp ON fp.material_id = m.id
     LEFT JOIN erp.suppliers s ON s.id = fp.preferred_supplier_id
     LEFT JOIN LATERAL ( SELECT x.id,
            x.material_id,
            x.benchmark_price_per_base_uom,
            x.base_uom_code_snapshot,
            x.effective_from,
            x.effective_to,
            x.change_reason,
            x.created_by,
            x.created_at
           FROM erp.fabric_benchmark_price_versions x
          WHERE x.material_id = m.id AND x.effective_from <= now() AND (x.effective_to IS NULL OR now() < x.effective_to)
          ORDER BY x.effective_from DESC
         LIMIT 1) bp ON true
  WHERE m.material_type::text = 'FABRIC'::text;;

alter view "erp"."v_fabric_master_current_benchmark" owner to "postgres";

create or replace view "erp"."v_fg_stock_balance" with (security_invoker=true) as
 SELECT product_id,
    location_id,
    quality_grade,
    sum(qty_signed) AS qty_pcs
   FROM erp.fg_stock_movements m
  GROUP BY product_id, location_id, quality_grade;;

alter view "erp"."v_fg_stock_balance" owner to "postgres";

create or replace view "erp"."v_fg_stock_card" with (security_invoker=true) as
 SELECT id,
    product_id,
    lot_id,
    location_id,
    quality_grade,
    movement_type,
    qty_signed,
    GREATEST(qty_signed, 0) AS qty_in_pcs,
    GREATEST(- qty_signed, 0) AS qty_out_pcs,
    unit_hpp_snapshot,
    customer_id,
    source_type,
    source_id,
    physical_at,
    system_created_at,
    notes,
    sum(qty_signed) OVER (PARTITION BY product_id, location_id, quality_grade ORDER BY physical_at, system_created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance_pcs
   FROM erp.fg_stock_movements m;;

alter view "erp"."v_fg_stock_card" owner to "postgres";

create or replace view "erp"."v_fg_stock_mutations" with (security_invoker=true) as
 SELECT m.id AS movement_id,
    m.book_order,
    row_number() OVER (ORDER BY m.book_order, m.id) AS book_row_no_global,
    m.physical_at,
    m.system_created_at,
    m.location_id,
    loc.location_code,
    loc.location_name,
    loc.location_type,
    m.product_id,
    p.sku,
    p.product_name,
    p.brand_id,
    b.brand_code,
    b.brand_name,
    p.model_id,
    pm.model_code,
    pm.model_name,
    p.color_name,
    p.size_id,
    sz.size_code,
    m.quality_grade,
    m.lot_id,
    fl.lot_number,
    m.movement_type,
    GREATEST(m.qty_signed, 0) AS qty_in_pcs,
    GREATEST(- m.qty_signed, 0) AS qty_out_pcs,
    sum(m.qty_signed) OVER (PARTITION BY m.product_id, m.location_id, m.quality_grade ORDER BY m.book_order, m.id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS stock_after_pcs,
    sum(m.qty_signed) OVER (PARTITION BY m.product_id, m.location_id, m.quality_grade ORDER BY m.physical_at, m.system_created_at, m.id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS official_chronological_stock_after_pcs,
    m.unit_hpp_snapshot,
    m.customer_id AS toko_customer_id,
    cust.customer_code AS toko_customer_code,
    cust.customer_name AS toko_customer_name,
    m.source_type,
    m.source_id,
    m.notes
   FROM erp.fg_stock_movements m
     JOIN erp.products p ON p.id = m.product_id
     JOIN erp.brands b ON b.id = p.brand_id
     JOIN erp.product_models pm ON pm.id = p.model_id
     JOIN erp.sizes sz ON sz.id = p.size_id
     JOIN erp.locations loc ON loc.id = m.location_id
     LEFT JOIN erp.fg_lots fl ON fl.id = m.lot_id
     LEFT JOIN erp.customers cust ON cust.id = m.customer_id;;

alter view "erp"."v_fg_stock_mutations" owner to "postgres";

create or replace view "erp"."v_fg_stock_position_v1" with (security_invoker=true) as
 WITH active_reservations AS (
         SELECT m.product_id,
            m.location_id,
            m.quality_grade,
            sum(abs(m.qty_signed)) AS reserved_qty_pcs
           FROM erp.fg_stock_movements m
          WHERE m.movement_type::text = 'SALE_RESERVE'::text AND NOT (EXISTS ( SELECT 1
                   FROM erp.fg_stock_movements rv
                  WHERE rv.reversal_of_id = m.id))
          GROUP BY m.product_id, m.location_id, m.quality_grade
        )
 SELECT b.product_id,
    b.location_id,
    b.quality_grade,
    b.cached_qty_pcs + COALESCE(r.reserved_qty_pcs, 0::bigint) AS physical_stock_qty_pcs,
    COALESCE(r.reserved_qty_pcs, 0::bigint) AS reserved_qty_pcs,
    b.cached_qty_pcs::bigint AS available_stock_qty_pcs,
    b.updated_at AS stock_updated_at
   FROM erp.fg_inventory_balances b
     LEFT JOIN active_reservations r ON r.product_id = b.product_id AND r.location_id = b.location_id AND r.quality_grade::text = b.quality_grade::text;;

alter view "erp"."v_fg_stock_position_v1" owner to "postgres";

create or replace view "erp"."v_gudang_contractor_material_issue_browser" with (security_invoker=true) as
 SELECT h.id AS issue_id,
    h.issue_number,
    h.contractor_id,
    c.contractor_code,
    c.contractor_name,
    h.po_id,
    po.po_number,
    h.location_id,
    l.location_code,
    l.location_name,
    h.physical_at,
    h.status,
    count(i.id) AS item_count,
    COALESCE(sum(i.qty), 0::numeric) AS base_qty_total,
    COALESCE(sum(i.total_receivable), 0::numeric) AS receivable_total,
    COALESCE(sum(i.qty * i.unit_cost_snapshot), 0::numeric) AS inventory_cost_total,
    h.notes,
    h.row_version,
    h.created_at,
    h.updated_at,
    concat_ws(' '::text, h.issue_number, c.contractor_code, c.contractor_name, po.po_number, h.status, l.location_code, h.notes) AS search_text
   FROM erp.contractor_material_issues h
     JOIN erp.contractors c ON c.id = h.contractor_id
     JOIN erp.locations l ON l.id = h.location_id
     LEFT JOIN erp.production_orders po ON po.id = h.po_id
     LEFT JOIN erp.contractor_material_issue_items i ON i.issue_id = h.id
  GROUP BY h.id, c.id, l.id, po.id;;

alter view "erp"."v_gudang_contractor_material_issue_browser" owner to "postgres";

create or replace view "erp"."v_gudang_fg_adjustment_browser" with (security_invoker=true) as
 SELECT h.id AS adjustment_id,
    h.adjustment_number,
    h.physical_at,
    h.status,
    h.location_id,
    l.location_code,
    l.location_name,
    h.reason_code,
    h.reason,
    h.notes,
    count(i.id) AS item_count,
    COALESCE(sum(i.qty_signed), 0::bigint) AS net_qty_pcs,
    COALESCE(sum(abs(i.qty_signed::numeric * i.unit_hpp_snapshot)), 0::numeric) AS absolute_value,
    h.row_version,
    h.created_at,
    h.updated_at,
    concat_ws(' '::text, h.adjustment_number, l.location_code, l.location_name, h.reason_code, h.reason, h.status) AS search_text
   FROM erp.fg_adjustments h
     JOIN erp.locations l ON l.id = h.location_id
     LEFT JOIN erp.fg_adjustment_items i ON i.adjustment_id = h.id
  GROUP BY h.id, l.id;;

alter view "erp"."v_gudang_fg_adjustment_browser" owner to "postgres";

create or replace view "erp"."v_gudang_material_adjustment_browser" with (security_invoker=true) as
 SELECT h.id AS adjustment_id,
    h.adjustment_number,
    h.reason_code,
    h.physical_at,
    h.status,
    h.location_id,
    l.location_code,
    l.location_name,
    count(i.id) AS item_count,
    COALESCE(sum(i.qty_signed), 0::numeric) AS net_qty,
    COALESCE(sum(abs(i.qty_signed)), 0::numeric) AS absolute_qty,
    h.notes,
    h.row_version,
    h.created_at,
    h.updated_at,
    concat_ws(' '::text, h.adjustment_number, h.reason_code, h.status, l.location_code, l.location_name, h.notes) AS search_text
   FROM erp.material_adjustments h
     JOIN erp.locations l ON l.id = h.location_id
     LEFT JOIN erp.material_adjustment_items i ON i.adjustment_id = h.id
  GROUP BY h.id, l.id;;

alter view "erp"."v_gudang_material_adjustment_browser" owner to "postgres";

create or replace view "erp"."v_gudang_supplier_return_browser" with (security_invoker=true) as
 SELECT h.id AS return_id,
    h.return_number,
    h.supplier_id,
    s.supplier_code,
    s.supplier_name,
    h.location_id,
    l.location_code,
    l.location_name,
    h.physical_at,
    h.status,
    h.reason,
    count(i.id) AS item_count,
    COALESCE(sum(i.qty), 0::numeric) AS total_qty,
    COALESCE(sum(i.qty * i.supplier_credit_unit_price), 0::numeric) AS credit_total,
    h.row_version,
    h.created_at,
    h.updated_at,
    concat_ws(' '::text, h.return_number, s.supplier_code, s.supplier_name, h.status, l.location_code, h.reason) AS search_text
   FROM erp.material_supplier_returns h
     JOIN erp.suppliers s ON s.id = h.supplier_id
     JOIN erp.locations l ON l.id = h.location_id
     LEFT JOIN erp.material_supplier_return_items i ON i.return_id = h.id
  GROUP BY h.id, s.id, l.id;;

alter view "erp"."v_gudang_supplier_return_browser" owner to "postgres";

create or replace view "erp"."v_laundry_po_operational_progress" with (security_invoker=true) as
 WITH sent AS (
         SELECT d.po_id,
            sum(l.qty_sent_pcs) AS sent_qty_pcs
           FROM erp.laundry_deliveries d
             JOIN erp.laundry_delivery_lines l ON l.delivery_id = d.id
          WHERE d.status::text <> ALL (ARRAY['DRAFT'::character varying, 'REVERSED'::character varying]::text[])
          GROUP BY d.po_id
        ), returned AS (
         SELECT d.po_id,
            sum(rl.qty_good_received) AS good_returned_qty_pcs,
            sum(rl.qty_bs_laundry) AS bs_returned_qty_pcs,
            sum(rl.qty_good_received + rl.qty_bs_laundry) AS returned_qty_pcs
           FROM erp.laundry_deliveries d
             JOIN erp.laundry_receipts r_1 ON r_1.delivery_id = d.id AND r_1.status::text = 'POSTED'::text
             JOIN erp.laundry_receipt_lines rl ON rl.receipt_id = r_1.id
          WHERE d.status::text <> 'REVERSED'::text
          GROUP BY d.po_id
        ), resolved AS (
         SELECT d.po_id,
            sum(c.qty_claimed) AS resolved_claim_qty_pcs
           FROM erp.laundry_claims c
             JOIN erp.laundry_deliveries d ON d.id = c.delivery_id
          WHERE (c.claim_type::text = ANY (ARRAY['MISSING'::character varying, 'STUCK'::character varying]::text[])) AND (c.status::text = ANY (ARRAY['SETTLED'::character varying, 'WRITTEN_OFF'::character varying]::text[])) AND d.status::text <> 'REVERSED'::text
          GROUP BY d.po_id
        )
 SELECT po.id AS po_id,
    po.po_number,
    po.status AS po_status,
    COALESCE(s.sent_qty_pcs, 0::bigint) AS sent_qty_pcs,
    COALESCE(r.good_returned_qty_pcs, 0::bigint) AS good_returned_qty_pcs,
    COALESCE(r.bs_returned_qty_pcs, 0::bigint) AS bs_returned_qty_pcs,
    COALESCE(r.returned_qty_pcs, 0::bigint) AS returned_qty_pcs,
    COALESCE(x.resolved_claim_qty_pcs, 0::bigint) AS resolved_claim_qty_pcs,
    GREATEST(COALESCE(s.sent_qty_pcs, 0::bigint) - COALESCE(r.returned_qty_pcs, 0::bigint) - COALESCE(x.resolved_claim_qty_pcs, 0::bigint), 0::bigint) AS laundry_outstanding_qty_pcs
   FROM erp.production_orders po
     JOIN sent s ON s.po_id = po.id
     LEFT JOIN returned r ON r.po_id = po.id
     LEFT JOIN resolved x ON x.po_id = po.id;;

alter view "erp"."v_laundry_po_operational_progress" owner to "postgres";

create or replace view "erp"."v_material_purchase_price_status" with (security_invoker=true) as
 SELECT h.id AS purchase_id,
    h.purchase_number,
    h.status AS purchase_status,
    h.physical_at,
    h.supplier_id,
    s.supplier_name,
    h.supplier_invoice_number,
    h.due_date,
    i.id AS purchase_item_id,
    i.material_id,
    m.material_sku,
    m.material_name,
    m.material_type,
    m.unit_code,
    i.qty,
    i.unit_price AS receipt_unit_price_snapshot,
    i.price_state,
    i.price_source,
    i.benchmark_price_version_id,
    i.benchmark_unit_price_snapshot,
    i.supplier_final_unit_price_snapshot,
    erp.material_purchase_current_unit_cost(i.id) AS current_payable_and_cost_unit_price,
    round(i.qty * erp.material_purchase_current_unit_cost(i.id), 6) AS current_line_total,
    i.price_finalized_at
   FROM erp.material_purchase_headers h
     JOIN erp.material_purchase_items i ON i.purchase_id = h.id
     JOIN erp.materials m ON m.id = i.material_id
     LEFT JOIN erp.suppliers s ON s.id = h.supplier_id;;

alter view "erp"."v_material_purchase_price_status" owner to "postgres";

create or replace view "erp"."v_material_roll_availability" with (security_invoker=true) as
 SELECT r.id AS roll_id,
    r.material_id,
    m.material_sku,
    m.material_name,
    m.unit_code,
    r.roll_number,
    r.original_qty,
    r.cached_qty,
    COALESCE(sum(sm.qty_signed), 0::numeric)::numeric(24,6) AS ledger_qty,
    r.status,
    r.supplier_id,
    s.supplier_name,
    r.purchase_item_id,
    pi.purchase_id,
    ph.purchase_number,
    ph.physical_at AS received_physical_at,
    r.received_at,
    r.updated_at
   FROM erp.material_rolls r
     JOIN erp.materials m ON m.id = r.material_id
     LEFT JOIN erp.suppliers s ON s.id = r.supplier_id
     LEFT JOIN erp.material_purchase_items pi ON pi.id = r.purchase_item_id
     LEFT JOIN erp.material_purchase_headers ph ON ph.id = pi.purchase_id
     LEFT JOIN erp.material_stock_movements sm ON sm.roll_id = r.id
  GROUP BY r.id, r.material_id, m.material_sku, m.material_name, m.unit_code, r.roll_number, r.original_qty, r.cached_qty, r.status, r.supplier_id, s.supplier_name, r.purchase_item_id, pi.purchase_id, ph.purchase_number, ph.physical_at, r.received_at, r.updated_at;;

alter view "erp"."v_material_roll_availability" owner to "postgres";

create or replace view "erp"."v_material_stock_balance" with (security_invoker=true) as
 SELECT m.id AS material_id,
    m.material_sku,
    m.material_name,
    m.material_type,
    m.unit_code,
    sm.location_id,
    l.location_code,
    l.location_name,
    COALESCE(sum(sm.qty_signed), 0::numeric)::numeric(24,6) AS stock_qty,
    m.moving_average_cost,
    round(COALESCE(sum(sm.qty_signed), 0::numeric) * m.moving_average_cost, 6) AS stock_value_at_current_ma,
    max(sm.physical_at) AS last_movement_at
   FROM erp.materials m
     JOIN erp.material_stock_movements sm ON sm.material_id = m.id
     LEFT JOIN erp.locations l ON l.id = sm.location_id
  GROUP BY m.id, m.material_sku, m.material_name, m.material_type, m.unit_code, m.moving_average_cost, sm.location_id, l.location_code, l.location_name;;

alter view "erp"."v_material_stock_balance" owner to "postgres";

create or replace view "erp"."v_material_stock_card" with (security_invoker=true) as
 SELECT sm.id AS movement_id,
    sm.material_id,
    m.material_sku,
    m.material_name,
    m.unit_code,
    sm.roll_id,
    r.roll_number,
    sm.location_id,
    l.location_code,
    l.location_name,
    sm.movement_type,
    sm.qty_signed,
    sum(sm.qty_signed) OVER (PARTITION BY sm.material_id, sm.location_id ORDER BY sm.physical_at, sm.system_created_at, sm.id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_qty,
    sm.input_unit_cost,
    sm.unit_cost_snapshot,
    round(sm.qty_signed * sm.unit_cost_snapshot, 6) AS movement_value,
    sm.source_type,
    sm.source_id,
    sm.physical_at,
    sm.system_created_at,
    sm.reversal_of_id,
    sm.note
   FROM erp.material_stock_movements sm
     JOIN erp.materials m ON m.id = sm.material_id
     LEFT JOIN erp.material_rolls r ON r.id = sm.roll_id
     LEFT JOIN erp.locations l ON l.id = sm.location_id;;

alter view "erp"."v_material_stock_card" owner to "postgres";

create or replace view "erp"."v_material_stock_mutations" with (security_invoker=true) as
 SELECT sm.id AS mutation_id,
    sm.physical_at,
    sm.system_created_at,
    sm.material_id,
    m.material_sku,
    m.material_name,
    m.material_type,
    m.unit_code,
    sm.roll_id,
    r.roll_number,
    sm.location_id,
    l.location_code,
    sm.movement_type,
    sm.qty_signed,
    sm.unit_cost_snapshot,
    sm.source_type,
    sm.source_id,
    sm.reversal_of_id,
    sm.note
   FROM erp.material_stock_movements sm
     JOIN erp.materials m ON m.id = sm.material_id
     LEFT JOIN erp.material_rolls r ON r.id = sm.roll_id
     LEFT JOIN erp.locations l ON l.id = sm.location_id;;

alter view "erp"."v_material_stock_mutations" owner to "postgres";

create or replace view "erp"."v_material_supplier_invoice_browser" with (security_invoker=true) as
 SELECT h.id AS supplier_invoice_id,
    h.invoice_number,
    h.supplier_id,
    s.supplier_code,
    s.supplier_name,
    h.invoice_date,
    h.received_at,
    h.due_date,
    h.status,
    h.notes,
    h.posting_reason,
    h.reversal_reason,
    count(l.id) AS line_count,
    count(DISTINCT i.purchase_id) AS receipt_count,
    COALESCE(sum(l.qty_invoiced), 0::numeric) AS matched_qty,
    COALESCE(sum(l.gross_amount), 0::numeric) AS gross_amount,
    COALESCE(sum(l.discount_amount), 0::numeric) AS discount_amount,
    COALESCE(sum(l.net_amount), 0::numeric) AS net_amount,
    min(ph.physical_at) AS oldest_receipt_at,
        CASE
            WHEN min(ph.physical_at) IS NULL THEN 0
            ELSE GREATEST(h.received_at::date - min(ph.physical_at)::date, 0)
        END AS invoice_delay_days,
    h.row_version,
    h.created_at,
    h.updated_at,
    h.posted_at,
    h.reversed_at,
    concat_ws(' '::text, h.invoice_number, s.supplier_code, s.supplier_name, h.status, h.notes) AS search_text
   FROM erp.material_supplier_invoices h
     JOIN erp.suppliers s ON s.id = h.supplier_id
     LEFT JOIN erp.material_supplier_invoice_lines l ON l.invoice_id = h.id
     LEFT JOIN erp.material_purchase_items i ON i.id = l.purchase_item_id
     LEFT JOIN erp.material_purchase_headers ph ON ph.id = i.purchase_id
  GROUP BY h.id, s.id;;

alter view "erp"."v_material_supplier_invoice_browser" owner to "postgres";

create or replace view "erp"."v_material_transfer_browser" with (security_invoker=true) as
 SELECT h.id AS transfer_id,
    h.transfer_number,
    h.physical_at,
    h.status,
    h.from_location_id,
    f.location_code AS from_location_code,
    f.location_name AS from_location_name,
    h.to_location_id,
    t.location_code AS to_location_code,
    t.location_name AS to_location_name,
    count(i.id) AS item_count,
    COALESCE(sum(i.qty), 0::numeric)::numeric(24,6) AS total_qty,
    count(DISTINCT i.material_id) AS material_count,
    count(i.roll_id) AS roll_line_count,
    h.notes,
    h.posted_at,
    h.reversed_at,
    h.reversal_reason,
    h.row_version,
    h.created_at,
    h.updated_at,
    concat_ws(' '::text, h.transfer_number, f.location_code, f.location_name, t.location_code, t.location_name, h.status, h.notes) AS search_text
   FROM erp.material_transfers h
     JOIN erp.locations f ON f.id = h.from_location_id
     JOIN erp.locations t ON t.id = h.to_location_id
     LEFT JOIN erp.material_transfer_items i ON i.transfer_id = h.id
  GROUP BY h.id, f.id, t.id;;

alter view "erp"."v_material_transfer_browser" owner to "postgres";

create or replace view "erp"."v_migration_reconciliation" with (security_invoker=true) as
 SELECT b.id AS batch_id,
    b.batch_code,
    b.cutover_at,
    b.status,
    count(s.id) AS staged_rows,
    count(s.id) FILTER (WHERE s.validation_status::text = 'VALID'::text) AS valid_rows,
    count(s.id) FILTER (WHERE s.validation_status::text = 'ERROR'::text) AS error_rows,
    count(s.id) FILTER (WHERE s.posted_entity_id IS NOT NULL) AS applied_rows,
    count(s.id) FILTER (WHERE s.validation_status::text = 'VALID'::text AND s.posted_entity_id IS NULL) AS valid_unapplied_rows
   FROM erp.migration_batches b
     LEFT JOIN erp.migration_staging_rows s ON s.batch_id = b.id
  GROUP BY b.id, b.batch_code, b.cutover_at, b.status;;

alter view "erp"."v_migration_reconciliation" owner to "postgres";

create or replace view "erp"."v_payroll_production_work_eligibility" with (security_invoker=true) as
 WITH laundry_sent AS (
         SELECT ldl.cutting_group_id,
            sum(ldl.qty_sent_pcs) AS sent_qty
           FROM erp.laundry_delivery_lines ldl
             JOIN erp.laundry_deliveries ld ON ld.id = ldl.delivery_id
          WHERE ld.status::text <> ALL (ARRAY['DRAFT'::character varying, 'REVERSED'::character varying]::text[])
          GROUP BY ldl.cutting_group_id
        ), laundry_returned AS (
         SELECT ldl.cutting_group_id,
            sum(lrl.qty_good_received + lrl.qty_bs_laundry) AS physically_returned_qty
           FROM erp.laundry_receipt_lines lrl
             JOIN erp.laundry_receipts lr ON lr.id = lrl.receipt_id AND lr.status::text = 'POSTED'::text
             JOIN erp.laundry_delivery_lines ldl ON ldl.id = lrl.delivery_line_id
          GROUP BY ldl.cutting_group_id
        ), base AS (
         SELECT wcl.id AS source_id,
            wce.id AS completion_id,
            wce.po_id,
            wce.contractor_id,
            wce.cutting_group_id,
            wcl.work_component_id,
            wce.physical_at,
            wcl.qty_payable,
            wcl.rate_snapshot,
            COALESCE(ls.sent_qty, 0::bigint) AS laundry_sent_qty,
            COALESCE(lr.physically_returned_qty, 0::bigint) AS laundry_returned_qty,
            ls.cutting_group_id IS NOT NULL AS laundry_required
           FROM erp.work_completion_lines wcl
             JOIN erp.work_completion_events wce ON wce.id = wcl.completion_id AND wce.status::text = 'POSTED'::text
             LEFT JOIN laundry_sent ls ON ls.cutting_group_id = wce.cutting_group_id
             LEFT JOIN laundry_returned lr ON lr.cutting_group_id = wce.cutting_group_id
        ), allocated AS (
         SELECT pwi.source_id,
            pwi.work_component_id,
            sum(pwi.qty_payable)::integer AS allocated_qty
           FROM erp.payroll_work_items pwi
             JOIN erp.payroll_settlements ps ON ps.id = pwi.payroll_id
          WHERE pwi.source_type::text = 'PRODUCTION'::text AND ps.status::text <> 'REVERSED'::text
          GROUP BY pwi.source_id, pwi.work_component_id
        )
 SELECT b.source_id,
    b.completion_id,
    b.po_id,
    b.contractor_id,
    b.cutting_group_id,
    b.work_component_id,
    b.physical_at,
    b.qty_payable AS source_qty_payable,
    b.rate_snapshot,
    b.laundry_required,
    b.laundry_sent_qty,
    b.laundry_returned_qty,
    b.qty_payable AS eligible_after_laundry_qty,
    0 AS held_for_laundry_qty,
    COALESCE(a.allocated_qty, 0) AS allocated_to_nonreversed_payroll_qty,
    GREATEST(b.qty_payable - COALESCE(a.allocated_qty, 0), 0) AS remaining_eligible_qty,
    round(GREATEST(b.qty_payable - COALESCE(a.allocated_qty, 0), 0)::numeric * b.rate_snapshot, 2) AS remaining_eligible_amount,
        CASE
            WHEN NOT b.laundry_required THEN 'COMPONENT_PAYABLE_NO_LAUNDRY'::text
            WHEN b.laundry_sent_qty > 0 AND b.laundry_returned_qty >= b.laundry_sent_qty THEN 'COMPONENT_PAYABLE_LAUNDRY_COMPLETE'::text
            ELSE 'COMPONENT_PAYABLE_LAUNDRY_OUTSTANDING'::text
        END AS eligibility_state
   FROM base b
     LEFT JOIN allocated a ON a.source_id = b.source_id AND a.work_component_id = b.work_component_id;;

alter view "erp"."v_payroll_production_work_eligibility" owner to "postgres";

create or replace view "erp"."v_product_identity_history" with (security_invoker=true) as
 SELECT identity_root_id,
    id AS product_id,
    supersedes_product_id,
    effective_from,
    effective_to,
    sku,
    model_id,
    brand_id,
    color_name,
    size_id,
    product_name,
    is_active,
    is_portal_visible
   FROM erp.products p;;

alter view "erp"."v_product_identity_history" owner to "postgres";

create or replace view "erp"."v_products_current" with (security_invoker=true) as
 SELECT id,
    sku,
    model_id,
    brand_id,
    color_name,
    size_id,
    product_name,
    is_portal_visible,
    is_active,
    created_at,
    updated_at,
    identity_root_id,
    effective_from,
    effective_to,
    supersedes_product_id
   FROM erp.products p
  WHERE is_active = true AND effective_from <= clock_timestamp() AND (effective_to IS NULL OR effective_to > clock_timestamp());;

alter view "erp"."v_products_current" owner to "postgres";

create or replace view "erp"."v_products_sellable" with (security_invoker=true) as
 WITH stock AS (
         SELECT fg_inventory_balances.product_id,
            COALESCE(sum(fg_inventory_balances.cached_qty_pcs), 0::bigint) AS stock_pcs
           FROM erp.fg_inventory_balances
          GROUP BY fg_inventory_balances.product_id
        )
 SELECT p.id,
    p.sku,
    p.model_id,
    p.brand_id,
    p.color_name,
    p.size_id,
    p.product_name,
    p.is_portal_visible,
    p.is_active,
    p.created_at,
    p.updated_at,
    p.identity_root_id,
    p.effective_from,
    p.effective_to,
    p.supersedes_product_id,
    COALESCE(s.stock_pcs, 0::bigint) AS stock_pcs,
    p.is_active = true AND p.effective_from <= clock_timestamp() AND (p.effective_to IS NULL OR p.effective_to > clock_timestamp()) AS is_current_identity
   FROM erp.products p
     LEFT JOIN stock s ON s.product_id = p.id
  WHERE p.is_active = true AND p.effective_from <= clock_timestamp() AND (p.effective_to IS NULL OR p.effective_to > clock_timestamp()) OR COALESCE(s.stock_pcs, 0::bigint) > 0;;

alter view "erp"."v_products_sellable" owner to "postgres";

create or replace view "erp"."v_sale_reservation_progress" with (security_invoker=true) as
 WITH items AS (
         SELECT sales_items.sale_id,
            sum(sales_items.qty_pcs) AS item_qty_pcs
           FROM erp.sales_items
          GROUP BY sales_items.sale_id
        ), allocations AS (
         SELECT i_1.sale_id,
            sum(a_1.qty_pcs) AS allocated_qty_pcs
           FROM erp.sales_items i_1
             JOIN erp.sale_stock_allocations a_1 ON a_1.sale_item_id = i_1.id
          GROUP BY i_1.sale_id
        ), reservations AS (
         SELECT i_1.sale_id,
            sum(abs(m.qty_signed)) AS active_reserved_qty_pcs
           FROM erp.sales_items i_1
             JOIN erp.fg_stock_movements m ON m.source_id = i_1.id
          WHERE m.source_type::text = 'SALE_ITEM'::text AND m.movement_type::text = 'SALE_RESERVE'::text AND NOT (EXISTS ( SELECT 1
                   FROM erp.fg_stock_movements rv
                  WHERE rv.reversal_of_id = m.id))
          GROUP BY i_1.sale_id
        )
 SELECT h.id AS sale_id,
    h.sale_number,
    h.customer_id,
    h.source_location_id,
    h.sale_date,
    h.status,
    h.row_version,
    COALESCE(i.item_qty_pcs, 0::bigint) AS item_qty_pcs,
    COALESCE(a.allocated_qty_pcs, 0::bigint) AS allocated_qty_pcs,
    COALESCE(r.active_reserved_qty_pcs, 0::bigint) AS active_reserved_qty_pcs,
        CASE
            WHEN h.status::text = 'DRAFT'::text AND COALESCE(i.item_qty_pcs, 0::bigint) = COALESCE(a.allocated_qty_pcs, 0::bigint) AND COALESCE(i.item_qty_pcs, 0::bigint) = COALESCE(r.active_reserved_qty_pcs, 0::bigint) AND COALESCE(i.item_qty_pcs, 0::bigint) > 0 THEN 'RESERVED'::character varying
            WHEN h.status::text = 'DRAFT'::text THEN 'RESERVATION_MISMATCH'::character varying
            ELSE h.status
        END::text AS reservation_status
   FROM erp.sales_headers h
     LEFT JOIN items i ON i.sale_id = h.id
     LEFT JOIN allocations a ON a.sale_id = h.id
     LEFT JOIN reservations r ON r.sale_id = h.id;;

alter view "erp"."v_sale_reservation_progress" owner to "postgres";

create or replace view "erp"."v_sales_detail" with (security_invoker=true) as
 SELECT sh.id AS sale_id,
    sh.sale_number,
    sh.sale_date,
    sh.status,
    c.id AS customer_id,
    c.customer_name,
    p.id AS product_id,
    p.sku,
    p.product_name,
    b.brand_name,
    p.color_name,
    s.size_code,
    si.qty_pcs,
    si.unit_price_snapshot,
    si.discount_amount,
    si.line_total
   FROM erp.sales_headers sh
     JOIN erp.customers c ON c.id = sh.customer_id
     JOIN erp.sales_items si ON si.sale_id = sh.id
     JOIN erp.products p ON p.id = si.product_id
     JOIN erp.brands b ON b.id = p.brand_id
     JOIN erp.sizes s ON s.id = p.size_id
  WHERE sh.status::text = ANY (ARRAY['POSTED'::character varying::text, 'PARTIAL_PAID'::character varying::text, 'PAID'::character varying::text]);;

alter view "erp"."v_sales_detail" owner to "postgres";

create or replace view "public"."v_erp_my_profile" with (security_invoker=true,security_barrier=true,check_option=local) as
 SELECT id,
    auth_user_id,
    full_name,
    role,
    is_active,
    row_version
   FROM erp.app_users u
  WHERE auth_user_id = (( SELECT auth.uid() AS uid));;

alter view "public"."v_erp_my_profile" owner to "postgres";

CREATE OR REPLACE FUNCTION erp._build_attendance_hpp_manifest_v1(p_period_start date, p_period_end date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
with eligible_payrolls as (
  select
    ps.id as payroll_id,
    ps.contractor_id,
    ps.attendance_total::numeric(20,2) as attendance_amount,
    pol.id as policy_version_id,
    pol.contractor_role_snapshot,
    pol.attendance_required_snapshot,
    pol.is_special,
    pol.effective_from as policy_effective_from,
    pol.effective_to as policy_effective_to,
    jl.id as original_debit_journal_line_id,
    jl.debit::numeric(20,2) as original_debit_amount
  from erp.payroll_settlements ps
  join lateral (
    select p.*
    from erp.contractor_hpp_policy_versions p
    where p.contractor_id = ps.contractor_id
      and p.effective_from <= p_period_start
      and (p.effective_to is null or p.effective_to >= p_period_end)
    order by p.effective_from desc, p.id desc
    limit 1
  ) pol on true
  join lateral (
    select jl.*
    from erp.journal_entries je
    join erp.journal_lines jl on jl.journal_entry_id = je.id
    where je.source_id = ps.id
      and je.source_type = 'PAYROLL_ATTENDANCE_ACCRUAL'
      and je.status = 'POSTED'
      and jl.account_id = erp.account_id('WIP')
      and jl.debit > 0
    order by je.posting_at, je.id, jl.id
    limit 1
  ) jl on true
  where ps.status in ('APPROVED','PAID')
    and ps.period_start = p_period_start
    and ps.period_end = p_period_end
    and ps.attendance_total > 0
    and pol.contractor_role_snapshot = 'MANDOR'
    and pol.attendance_required_snapshot
    and not pol.is_special
), eligible_sewing as (
  select
    e.id as sewing_terminal_event_id,
    e.source_work_completion_id,
    e.contractor_id,
    e.po_id,
    e.cutting_group_id,
    e.physical_at,
    e.qty_signed as sewing_qty,
    pol.id as policy_version_id,
    pol.contractor_role_snapshot,
    pol.attendance_required_snapshot,
    pol.is_special
  from erp.sewing_terminal_events e
  join erp.work_completion_events w on w.id = e.source_work_completion_id
  join lateral (
    select p.*
    from erp.contractor_hpp_policy_versions p
    where p.contractor_id = e.contractor_id
      and p.effective_from <= p_period_start
      and (p.effective_to is null or p.effective_to >= p_period_end)
    order by p.effective_from desc, p.id desc
    limit 1
  ) pol on true
  where e.event_kind = 'SELESAI_DIJAHIT'
    and erp._cp3_business_date(e.physical_at) between p_period_start and p_period_end
    and w.status = 'POSTED'
    and pol.contractor_role_snapshot = 'MANDOR'
    and pol.attendance_required_snapshot
    and not pol.is_special
    and not exists (
      select 1 from erp.sewing_terminal_events rv
      where rv.event_kind = 'REVERSAL' and rv.reversal_of_id = e.id
    )
), source_json as (
  select coalesce(jsonb_agg(jsonb_build_object(
    'payroll_id', payroll_id,
    'contractor_id', contractor_id,
    'policy_version_id', policy_version_id,
    'contractor_role_snapshot', contractor_role_snapshot,
    'attendance_required_snapshot', attendance_required_snapshot,
    'is_special_snapshot', is_special,
    'policy_effective_from', erp._cp3_canonical_date(policy_effective_from),
    'policy_effective_to', case when policy_effective_to is null then null else erp._cp3_canonical_date(policy_effective_to) end,
    'original_debit_journal_line_id', original_debit_journal_line_id,
    'original_debit_amount_cents', round(original_debit_amount * 100)::bigint,
    'attendance_amount_cents', round(attendance_amount * 100)::bigint
  ) order by contractor_id, payroll_id, original_debit_journal_line_id), '[]'::jsonb) value,
  coalesce(sum(round(attendance_amount * 100)::bigint), 0)::bigint numerator_cents
  from eligible_payrolls
), destination_json as (
  select coalesce(jsonb_agg(jsonb_build_object(
    'sewing_terminal_event_id', sewing_terminal_event_id,
    'source_work_completion_id', source_work_completion_id,
    'contractor_id', contractor_id,
    'po_id', po_id,
    'cutting_group_id', cutting_group_id,
    'policy_version_id', policy_version_id,
    'contractor_role_snapshot', contractor_role_snapshot,
    'attendance_required_snapshot', attendance_required_snapshot,
    'is_special_snapshot', is_special,
    'physical_at_epoch_us', erp._cp3_epoch_microseconds(physical_at),
    'sewing_qty', sewing_qty
  ) order by physical_at, sewing_terminal_event_id), '[]'::jsonb) value,
  coalesce(sum(sewing_qty), 0)::bigint denominator_qty
  from eligible_sewing
)
select jsonb_build_object(
  'contract_version', 'ATTENDANCE_HPP_SEWING_TERMINAL_V1',
  'operation_type', 'ATTENDANCE_HPP_POOL',
  'period_start', erp._cp3_canonical_date(p_period_start),
  'period_end', erp._cp3_canonical_date(p_period_end),
  'numerator_cents', source_json.numerator_cents,
  'denominator_qty', destination_json.denominator_qty,
  'sources', source_json.value,
  'destinations', destination_json.value
)
from source_json, destination_json
$function$;

alter function "erp"."_build_attendance_hpp_manifest_v1"(p_period_start date, p_period_end date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp._idempotency_actor_key()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'pg_temp'
AS $function$
  select coalesce(
    erp.current_app_user_id()::text,
    auth.uid()::text,
    'database:' || session_user
  )
$function$;

alter function "erp"."_idempotency_actor_key"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.attendance_hpp_exclusion_summary_v1(p_period_start date, p_period_end date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
with payroll_exclusions as (
  select
    ps.id payroll_id,
    ps.contractor_id,
    ps.attendance_total,
    case
      when pol.id is null then 'MISSING_EXPLICIT_POLICY'
      when pol.contractor_role_snapshot <> 'MANDOR' then 'ROLE_NOT_MANDOR'
      when not pol.attendance_required_snapshot then 'ATTENDANCE_NOT_REQUIRED'
      when pol.is_special then 'SPECIAL'
      else null
    end exclusion_reason
  from erp.payroll_settlements ps
  left join lateral (
    select p.*
    from erp.contractor_hpp_policy_versions p
    where p.contractor_id=ps.contractor_id
      and p.effective_from<=p_period_start
      and (p.effective_to is null or p.effective_to>=p_period_end)
    order by p.effective_from desc,p.id desc
    limit 1
  ) pol on true
  where ps.status in ('APPROVED','PAID')
    and ps.period_start=p_period_start
    and ps.period_end=p_period_end
    and ps.attendance_total>0
), sewing_exclusions as (
  select
    e.id sewing_terminal_event_id,
    e.contractor_id,
    e.po_id,
    e.qty_signed sewing_qty,
    erp._cp3_epoch_microseconds(e.physical_at) physical_at_epoch_us,
    case
      when pol.id is null then 'MISSING_EXPLICIT_POLICY'
      when pol.contractor_role_snapshot <> 'MANDOR' then 'ROLE_NOT_MANDOR'
      when not pol.attendance_required_snapshot then 'ATTENDANCE_NOT_REQUIRED'
      when pol.is_special then 'SPECIAL'
      else null
    end exclusion_reason
  from erp.sewing_terminal_events e
  left join lateral (
    select p.*
    from erp.contractor_hpp_policy_versions p
    where p.contractor_id=e.contractor_id
      and p.effective_from<=p_period_start
      and (p.effective_to is null or p.effective_to>=p_period_end)
    order by p.effective_from desc,p.id desc
    limit 1
  ) pol on true
  where e.event_kind='SELESAI_DIJAHIT'
    and erp._cp3_business_date(e.physical_at) between p_period_start and p_period_end
    and not exists(select 1 from erp.sewing_terminal_events rv where rv.reversal_of_id=e.id)
)
select jsonb_build_object(
  'excluded_payrolls',coalesce((
    select jsonb_agg(jsonb_build_object(
      'payroll_id',payroll_id,
      'contractor_id',contractor_id,
      'attendance_amount_cents',round(attendance_total*100)::bigint,
      'reason',exclusion_reason
    ) order by contractor_id,payroll_id)
    from payroll_exclusions where exclusion_reason is not null
  ),'[]'::jsonb),
  'excluded_sewing_events',coalesce((
    select jsonb_agg(jsonb_build_object(
      'sewing_terminal_event_id',sewing_terminal_event_id,
      'contractor_id',contractor_id,
      'po_id',po_id,
      'sewing_qty',sewing_qty,
      'physical_at_epoch_us',physical_at_epoch_us,
      'reason',exclusion_reason
    ) order by physical_at_epoch_us,sewing_terminal_event_id)
    from sewing_exclusions where exclusion_reason is not null
  ),'[]'::jsonb)
)
$function$;

alter function "erp"."attendance_hpp_exclusion_summary_v1"(p_period_start date, p_period_end date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.customer_purchase_history(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(sale_number character varying, sale_date timestamp with time zone, sku character varying, product_name character varying, brand_name character varying, color_name character varying, size_code character varying, qty_pcs integer, unit_price numeric, line_total numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
  SELECT sh.sale_number,sh.sale_date,p.sku,p.product_name,b.brand_name,p.color_name,s.size_code,
         si.qty_pcs,si.unit_price_snapshot,si.line_total
  FROM erp.sales_headers sh
  JOIN erp.sales_items si ON si.sale_id=sh.id
  JOIN erp.products p ON p.id=si.product_id
  JOIN erp.brands b ON b.id=p.brand_id
  JOIN erp.sizes s ON s.id=p.size_id
  WHERE sh.customer_id=erp.current_customer_id()
    AND EXISTS (
      SELECT 1 FROM erp.customer_user_access cua
      WHERE cua.app_user_id=erp.current_app_user_id()
        AND cua.customer_id=sh.customer_id
        AND cua.can_view_purchases=true
    )
    AND sh.status IN ('POSTED','PARTIAL_PAID','PAID')
    AND (p_from IS NULL OR sh.sale_date>=p_from)
    AND (p_to IS NULL OR sh.sale_date<p_to)
  ORDER BY sh.sale_date DESC,sh.sale_number,p.sku
$function$;

alter function "erp"."customer_purchase_history"(p_from timestamp with time zone, p_to timestamp with time zone) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.customer_stock_catalog()
 RETURNS TABLE(sku character varying, product_name character varying, brand_name character varying, color_name character varying, size_code character varying, qty_pcs bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
  select p.sku,p.product_name,b.brand_name,p.color_name,s.size_code,p.stock_pcs::bigint
  from erp.v_products_sellable p
  join erp.brands b on b.id=p.brand_id
  join erp.sizes s on s.id=p.size_id
  where p.is_active=true and p.is_portal_visible=true
    and exists(
      select 1 from erp.customer_user_access cua
      where cua.app_user_id=erp.current_app_user_id()
        and cua.customer_id=erp.current_customer_id()
        and cua.can_view_stock=true
    )
  order by b.brand_name,p.product_name,s.size_code,p.effective_from;
$function$;

alter function "erp"."customer_stock_catalog"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.customer_wip_status()
 RETURNS TABLE(po_number character varying, model_code character varying, model_name character varying, current_stage character varying, contractor_name character varying, laundry_vendor_name character varying, target_dyeing_color character varying, laundry_status character varying)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
  WITH access AS (
    SELECT cua.can_view_wip,cua.can_view_laundry,cua.customer_id
    FROM erp.customer_user_access cua
    WHERE cua.app_user_id=erp.current_app_user_id()
      AND cua.customer_id=erp.current_customer_id()
    LIMIT 1
  )
  SELECT DISTINCT po.po_number,pm.model_code,pm.model_name,po.current_stage,c.contractor_name,
    CASE WHEN a.can_view_laundry THEN lv.vendor_name ELSE NULL END,
    CASE WHEN a.can_view_laundry THEN ld.target_dyeing_color ELSE NULL END,
    CASE WHEN a.can_view_laundry THEN ld.status ELSE NULL END
  FROM erp.production_orders po
  CROSS JOIN access a
  JOIN erp.product_models pm ON pm.id=po.model_id
  LEFT JOIN erp.contractors c ON c.id=po.contractor_id
  LEFT JOIN erp.laundry_deliveries ld ON ld.po_id=po.id AND ld.status<>'REVERSED' AND ld.portal_visible=true
  LEFT JOIN erp.laundry_vendors lv ON lv.id=ld.vendor_id
  WHERE po.status NOT IN ('CANCELLED')
    AND a.can_view_wip=true
    AND (
      po.portal_visibility='ALL_CUSTOMERS'
      OR (
        po.portal_visibility='SELECTED_CUSTOMERS'
        AND EXISTS (
          SELECT 1 FROM erp.po_customer_visibility pcv
          WHERE pcv.po_id=po.id AND pcv.customer_id=a.customer_id
        )
      )
    )
  ORDER BY po.po_number
$function$;

alter function "erp"."customer_wip_status"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.get_fg_mutation_book(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_product_ids uuid[] DEFAULT NULL::uuid[], p_customer_ids uuid[] DEFAULT NULL::uuid[], p_movement_types text[] DEFAULT NULL::text[], p_location_ids uuid[] DEFAULT NULL::uuid[], p_brand_ids uuid[] DEFAULT NULL::uuid[], p_size_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(movement_id uuid, physical_at timestamp with time zone, sku character varying, product_name character varying, brand_name character varying, color_name character varying, size_code character varying, customer_name character varying, movement_type character varying, qty_in integer, qty_out integer, qty_signed integer, running_balance bigint, source_type character varying, source_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ WITH card AS (SELECT m.*,SUM(m.qty_signed) OVER (PARTITION BY m.product_id,m.location_id,m.quality_grade ORDER BY m.physical_at,m.system_created_at,m.id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)::bigint AS physical_running_balance FROM erp.fg_stock_movements m) SELECT m.id,m.physical_at,p.sku,p.product_name,b.brand_name,p.color_name,sz.size_code,c.customer_name,m.movement_type,CASE WHEN m.qty_signed>0 THEN m.qty_signed ELSE 0 END,CASE WHEN m.qty_signed<0 THEN -m.qty_signed ELSE 0 END,m.qty_signed,m.physical_running_balance,m.source_type,m.source_id FROM card m JOIN erp.products p ON p.id=m.product_id JOIN erp.brands b ON b.id=p.brand_id JOIN erp.sizes sz ON sz.id=p.size_id LEFT JOIN erp.customers c ON c.id=m.customer_id WHERE erp.current_app_role() IN ('OWNER','ADMIN','STAFF') AND (p_from IS NULL OR m.physical_at>=p_from) AND (p_to IS NULL OR m.physical_at<p_to) AND (p_product_ids IS NULL OR m.product_id=ANY(p_product_ids)) AND (p_customer_ids IS NULL OR m.customer_id=ANY(p_customer_ids)) AND (p_movement_types IS NULL OR m.movement_type=ANY(p_movement_types)) AND (p_location_ids IS NULL OR m.location_id=ANY(p_location_ids)) AND (p_brand_ids IS NULL OR p.brand_id=ANY(p_brand_ids)) AND (p_size_ids IS NULL OR p.size_id=ANY(p_size_ids)) ORDER BY m.physical_at,m.system_created_at,m.id $function$;

alter function "erp"."get_fg_mutation_book"(p_from timestamp with time zone, p_to timestamp with time zone, p_product_ids uuid[], p_customer_ids uuid[], p_movement_types text[], p_location_ids uuid[], p_brand_ids uuid[], p_size_ids uuid[]) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.get_hpp_completeness(p_po_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(po_id uuid, po_number text, po_status text, current_hpp_total numeric, qty_basis_pcs bigint, hpp_per_pcs numeric, engine_cost_state text, display_status text, is_adjusted boolean, pending_reason_count integer, pending_reasons text[], latest_hpp_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
with po as (
  select p.id,p.po_number::text,p.status::text,p.contractor_id
  from erp.production_orders p
  where (p_po_id is null or p.id=p_po_id)
    and erp.current_app_role() in ('OWNER','ADMIN','STAFF')
), h as (
  select fl.po_id,
         count(*) filter(where fl.lot_origin='PRODUCTION')::int active_lots,
         count(hv.hpp_version_id) filter(where fl.lot_origin='PRODUCTION')::int hpp_lots,
         coalesce(sum(hv.total_cost) filter(where fl.lot_origin='PRODUCTION'),0)::numeric total_cost,
         coalesce(sum(hv.qty_basis_pcs) filter(where fl.lot_origin='PRODUCTION'),0)::bigint qty_basis,
         max(hv.calculated_at) filter(where fl.lot_origin='PRODUCTION') latest_at,
         bool_or(hv.cost_state='ESTIMATED') filter(where fl.lot_origin='PRODUCTION') any_estimated,
         bool_or(hv.cost_state='ADJUSTED') filter(where fl.lot_origin='PRODUCTION') any_adjusted
  from erp.fg_lots fl
  left join erp.v_current_hpp hv on hv.lot_id=fl.id
  where fl.lot_origin='PRODUCTION'
  group by fl.po_id
), flags as (
 select p.id po_id,
        coalesce(h.active_lots,0) active_lots,
        coalesce(h.hpp_lots,0) hpp_lots,
        coalesce(h.total_cost,0) total_cost,
        coalesce(h.qty_basis,0) qty_basis,
        h.latest_at,
        coalesce(h.any_estimated,false) any_estimated,
        coalesce(h.any_adjusted,false) any_adjusted,
        array_remove(array[
          case when coalesce(h.active_lots,0)=0 then 'BELUM_ADA_FG' end,
          case when coalesce(h.active_lots,0)>coalesce(h.hpp_lots,0) then 'HPP_CURRENT_BELUM_TERBENTUK' end,
          case when p.status<>'FINISHED' then 'PRODUKSI_BELUM_FINISHED' end,
          case when coalesce(erp.desired_laundry_accrual(p.id),0)>0.005 then 'BIAYA_LAUNDRY_MASIH_ESTIMASI/BELUM_FINAL' end,
          case when coalesce(h.any_estimated,false) then 'HPP_ENGINE_MASIH_ESTIMATED' end,
          case when exists(select 1 from erp.cost_recalc_queue q where q.entity_type='PO' and q.entity_id=p.id and q.status in('PENDING','RUNNING','FAILED')) then 'RECOST_BELUM_SELESAI' end,
          case when exists(select 1 from erp.bs_cases b where b.po_id=p.id and b.status in('OPEN','IN_REWORK','PARTIAL')) then 'BS/REWORK_BELUM_SELESAI' end,
          case when p.contractor_id is not null and coalesce(h.active_lots,0)>0 and not exists(select 1 from erp.po_work_component_snapshots s where s.po_id=p.id) then 'BIAYA_KERJA/BOM_BELUM_DIKONFIRMASI' end,
          case when exists(
            select 1 from erp.po_work_component_snapshots s
            where s.po_id=p.id and not exists(
              select 1 from erp.work_completion_lines wcl join erp.work_completion_events wce on wce.id=wcl.completion_id
              where wcl.po_component_snapshot_id=s.id and wce.status='POSTED'
            )
          ) then 'ADA_KOMPONEN_KERJA_BELUM_PERNAH_DIPOST' end,
          case when exists(
            select 1 from erp.fg_lots fl
            where fl.po_id=p.id and fl.lot_origin='PRODUCTION'
              and exists(select 1 from erp.accessory_bom_versions abv join erp.accessory_bom_items abi on abi.bom_version_id=abv.id where abv.product_id=fl.product_id and abv.is_active=true and abv.effective_from<=fl.produced_at and (abv.effective_to is null or abv.effective_to>fl.produced_at))
              and not exists(select 1 from erp.fg_accessory_cost_snapshots s where s.lot_id=fl.id)
          ) then 'SNAPSHOT_BIAYA_AKSESORI_BELUM_ADA' end
        ]::text[],null) reasons
 from po p left join h on h.po_id=p.id
)
select p.id,
       p.po_number,
       p.status,
       f.total_cost,
       f.qty_basis,
       case when f.qty_basis>0 then f.total_cost/f.qty_basis else null end,
       case when f.any_estimated then 'ESTIMATED' when f.any_adjusted then 'ADJUSTED' when f.hpp_lots>0 then 'ACTUAL' else null end,
       case
         when f.active_lots=0 or f.hpp_lots=0 then 'BELUM_ADA_HPP'
         when p.status<>'FINISHED' then 'SEMENTARA'
         when cardinality(f.reasons)>0 then 'BELUM_LENGKAP'
         else 'LENGKAP_BERDASARKAN_DATA_SAAT_INI'
       end,
       f.any_adjusted,
       cardinality(f.reasons),
       f.reasons,
       f.latest_at
from po p join flags f on f.po_id=p.id
order by p.po_number;
$function$;

alter function "erp"."get_hpp_completeness"(p_po_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.get_profit_loss(p_from date, p_to date)
 RETURNS TABLE(report_group character varying, account_code character varying, account_name character varying, amount numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$ SELECT ca.report_group,ca.account_code,ca.account_name,CASE WHEN ca.normal_balance='CREDIT' THEN SUM(adb.credit_total-adb.debit_total) ELSE SUM(adb.debit_total-adb.credit_total) END AS amount FROM erp.account_daily_balances adb JOIN erp.chart_accounts ca ON ca.id=adb.account_id WHERE erp.current_app_role() IN ('OWNER','ADMIN','STAFF') AND adb.balance_date BETWEEN p_from AND p_to AND ca.account_type IN ('REVENUE','EXPENSE') GROUP BY ca.report_group,ca.account_code,ca.account_name,ca.normal_balance ORDER BY ca.account_code $function$;

alter function "erp"."get_profit_loss"(p_from date, p_to date) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.is_cutting_group_presewing_reversible(p_cutting_group_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
  select coalesce((
    select
      cg.status in ('CUT','PICKED_UP')
      and not cg.material_issue_posted
      and not cg.material_return_posted
      and not exists (
        select 1 from erp.material_stock_movements m
        where m.source_id = cg.id
          and m.source_type in ('CUTTING_GROUP','CUTTING_GROUP_RETURN')
          and not exists (
            select 1 from erp.material_stock_movements rv
            where rv.reversal_of_id = m.id
          )
      )
      and not erp.cutting_group_has_downstream_after_pickup(cg.id)
    from erp.cutting_groups cg
    where cg.id = p_cutting_group_id
  ), false);
$function$;

alter function "erp"."is_cutting_group_presewing_reversible"(p_cutting_group_id uuid) owner to "postgres";

