alter function "erp"."material_purchase_payable_total"(p_purchase_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v263a_payroll_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
  select
    'production_payroll_exceeds_component_entitlement',
    'CRITICAL',
    count(*)::bigint,
    'Allocated production payroll qty must not exceed posted per-component qty_payable'
  from erp.v_payroll_production_work_eligibility e
  where e.allocated_to_nonreversed_payroll_qty > e.source_qty_payable

  union all
  select
    'rework_payroll_before_case_resolution',
    'CRITICAL',
    count(*)::bigint,
    'Rework Nota lines require COMPLETED+cost_posted rework and a RESOLVED BS case'
  from erp.payroll_work_items pwi
  join erp.payroll_settlements ps
    on ps.id = pwi.payroll_id
   and ps.status <> 'REVERSED'
  join erp.rework_component_lines rcl
    on pwi.source_type = 'REWORK'
   and rcl.id = pwi.source_id
  join erp.rework_orders ro on ro.id = rcl.rework_order_id
  join erp.bs_case_components bcc on bcc.id = rcl.bs_case_component_id
  join erp.bs_cases bc on bc.id = bcc.bs_case_id
  where ro.status <> 'COMPLETED'
     or not ro.cost_posted
     or bc.status <> 'RESOLVED'

  union all
  select
    'payroll_work_wrong_contractor',
    'CRITICAL',
    count(*)::bigint,
    'Every Nota work line must belong to the Nota Mandor'
  from erp.payroll_work_items pwi
  join erp.payroll_settlements ps on ps.id = pwi.payroll_id
  left join erp.work_completion_lines wcl
    on pwi.source_type = 'PRODUCTION'
   and wcl.id = pwi.source_id
  left join erp.work_completion_events wce on wce.id = wcl.completion_id
  left join erp.rework_component_lines rcl
    on pwi.source_type = 'REWORK'
   and rcl.id = pwi.source_id
  left join erp.rework_orders ro on ro.id = rcl.rework_order_id
  where ps.status <> 'REVERSED'
    and ps.contractor_id is distinct from coalesce(wce.contractor_id, ro.contractor_id);
$function$;

alter function "erp"."run_v263a_payroll_integrity_checks"() owner to "postgres";

create or replace view "erp"."v_accessory_hpp_setup" with (security_invoker=true) as
 SELECT p.id AS product_id,
    p.sku,
    p.product_name,
    abv.id AS bom_version_id,
    abv.effective_from,
    abv.effective_to,
    ac.category_code,
    ac.category_name,
    ac.base_uom_code,
    abi.qty_per_good_fg_base,
    abi.hpp_method,
    abi.hpp_standard_rate,
    abi.hpp_uom_code,
    abi.reimbursement_rate,
    abi.reimbursement_uom_code,
        CASE
            WHEN abv.id IS NULL THEN 'MISSING_BOM'::text
            WHEN abi.id IS NULL THEN 'NO_ACCESSORY'::text
            ELSE 'CONFIGURED'::text
        END AS setup_state,
    count(abi.id) OVER (PARTITION BY p.id, abv.id) AS bom_item_count
   FROM erp.v_products_current p
     LEFT JOIN erp.accessory_bom_versions abv ON abv.product_id = p.identity_root_id AND abv.is_active = true AND abv.effective_from <= clock_timestamp() AND (abv.effective_to IS NULL OR abv.effective_to > clock_timestamp())
     LEFT JOIN erp.accessory_bom_items abi ON abi.bom_version_id = abv.id
     LEFT JOIN erp.accessory_categories ac ON ac.id = abi.category_id;;

alter view "erp"."v_accessory_hpp_setup" owner to "postgres";

create or replace view "erp"."v_accessory_master_browser" with (security_invoker=true) as
 WITH stock AS (
         SELECT v_material_stock_balance.material_id,
            sum(v_material_stock_balance.stock_qty) AS stock_qty,
            sum(v_material_stock_balance.stock_value_at_current_ma) AS stock_value,
            max(v_material_stock_balance.last_movement_at) AS last_movement_at
           FROM erp.v_material_stock_balance
          GROUP BY v_material_stock_balance.material_id
        )
 SELECT m.id AS material_id,
    m.material_sku,
    m.material_name,
    m.is_active,
    m.unit_code AS base_uom_code,
    m.row_version,
    m.cached_stock_qty,
    m.moving_average_cost,
    ac.id AS category_id,
    ac.category_code,
    ac.category_name,
    ac.row_version AS category_row_version,
    cc.weighted_avg_cost_per_base_uom AS category_weighted_avg_cost,
    COALESCE(s.stock_qty, 0::numeric) AS ledger_stock_qty,
    COALESCE(s.stock_value, 0::numeric) AS stock_value,
    s.last_movement_at,
    gp.id AS global_price_version_id,
    gp.selling_price AS global_selling_price,
    gp.selling_uom_code AS global_selling_uom_code,
    gp.effective_from AS global_price_effective_from,
    gp.effective_to AS global_price_effective_to,
    concat_ws(' '::text, m.material_sku, m.material_name, ac.category_code, ac.category_name) AS search_text
   FROM erp.materials m
     JOIN erp.accessory_categories ac ON ac.id = m.accessory_category_id
     LEFT JOIN erp.v_accessory_category_current_cost cc ON cc.category_id = ac.id
     LEFT JOIN stock s ON s.material_id = m.id
     LEFT JOIN LATERAL ( SELECT p.id,
            p.contractor_id,
            p.category_id,
            p.selling_price,
            p.selling_uom_code,
            p.effective_from,
            p.effective_to,
            p.notes,
            p.created_at
           FROM erp.contractor_accessory_price_versions p
          WHERE p.category_id = ac.id AND p.contractor_id IS NULL AND p.effective_from <= now() AND (p.effective_to IS NULL OR p.effective_to > now())
          ORDER BY p.effective_from DESC
         LIMIT 1) gp ON true
  WHERE m.material_type::text = 'ACCESSORY'::text;;

alter view "erp"."v_accessory_master_browser" owner to "postgres";

create or replace view "erp"."v_cutting_group_original_totals" with (security_invoker=true) as
 SELECT cg.id AS cutting_group_id,
    cg.po_id,
    COALESCE(sum(vrt.total_pcs), 0::numeric)::bigint AS total_pcs
   FROM erp.cutting_groups cg
     LEFT JOIN erp.v_cutting_roll_totals vrt ON vrt.cutting_group_id = cg.id
  GROUP BY cg.id, cg.po_id;;

alter view "erp"."v_cutting_group_original_totals" owner to "postgres";

create or replace view "erp"."v_payroll_eligible_work_lines" with (security_invoker=true) as
 SELECT 'PRODUCTION'::text AS source_type,
    p.source_id,
    p.contractor_id,
    p.po_id,
    p.cutting_group_id,
    NULL::uuid AS bs_case_id,
    p.work_component_id,
    p.physical_at AS eligible_at,
    p.source_qty_payable AS source_qty,
    p.eligible_after_laundry_qty AS eligible_qty,
    p.allocated_to_nonreversed_payroll_qty AS allocated_qty,
    p.remaining_eligible_qty AS remaining_qty,
    p.held_for_laundry_qty AS held_qty,
    p.rate_snapshot,
    p.remaining_eligible_amount AS remaining_amount,
    p.eligibility_state AS eligibility_reason
   FROM erp.v_payroll_production_work_eligibility p
  WHERE p.remaining_eligible_qty > 0
UNION ALL
 SELECT 'REWORK'::text AS source_type,
    rcl.id AS source_id,
    ro.contractor_id,
    bc.po_id,
    bc.cutting_group_id,
    bc.id AS bs_case_id,
    bcc.work_component_id,
    COALESCE(ro.completed_at, ro.physical_sent_at) AS eligible_at,
    rcl.qty_newly_payable AS source_qty,
    rcl.qty_newly_payable AS eligible_qty,
    COALESCE(a.allocated_qty, 0) AS allocated_qty,
    GREATEST(rcl.qty_newly_payable - COALESCE(a.allocated_qty, 0), 0) AS remaining_qty,
    0 AS held_qty,
    rcl.rate_snapshot,
    round(GREATEST(rcl.qty_newly_payable - COALESCE(a.allocated_qty, 0), 0)::numeric * rcl.rate_snapshot, 2) AS remaining_amount,
    'BS_CASE_RESOLVED'::text AS eligibility_reason
   FROM erp.rework_component_lines rcl
     JOIN erp.rework_orders ro ON ro.id = rcl.rework_order_id
     JOIN erp.bs_case_components bcc ON bcc.id = rcl.bs_case_component_id
     JOIN erp.bs_cases bc ON bc.id = bcc.bs_case_id
     LEFT JOIN LATERAL ( SELECT sum(pwi.qty_payable)::integer AS allocated_qty
           FROM erp.payroll_work_items pwi
             JOIN erp.payroll_settlements ps ON ps.id = pwi.payroll_id
          WHERE pwi.source_type::text = 'REWORK'::text AND pwi.source_id = rcl.id AND ps.status::text <> 'REVERSED'::text) a ON true
  WHERE ro.destination_type::text = 'CONTRACTOR'::text AND ro.status::text = 'COMPLETED'::text AND ro.cost_posted AND bc.status::text = 'RESOLVED'::text AND GREATEST(rcl.qty_newly_payable - COALESCE(a.allocated_qty, 0), 0) > 0;;

alter view "erp"."v_payroll_eligible_work_lines" owner to "postgres";

create or replace view "erp"."v_product_price_current" with (security_invoker=true) as
 SELECT p.id AS product_id,
    p.identity_root_id,
    p.sku,
    p.product_name,
    p.color_name,
    p.size_id,
    pp.id AS price_version_id,
    pp.price,
    pp.effective_from AS price_effective_from,
    pp.effective_to AS price_effective_to
   FROM erp.v_products_current p
     LEFT JOIN LATERAL ( SELECT x.id,
            x.product_id,
            x.price,
            x.effective_from,
            x.effective_to,
            x.change_note,
            x.created_by,
            x.created_at
           FROM erp.product_price_versions x
          WHERE x.product_id = p.identity_root_id AND x.effective_from <= clock_timestamp() AND (x.effective_to IS NULL OR x.effective_to > clock_timestamp())
          ORDER BY x.effective_from DESC, x.created_at DESC, x.id DESC
         LIMIT 1) pp ON true;;

alter view "erp"."v_product_price_current" owner to "postgres";

create or replace view "erp"."v_supplier_ap_aging" with (security_invoker=true) as
 WITH ap AS (
         SELECT h.id AS purchase_id,
            h.purchase_number,
            h.supplier_id,
            s.supplier_name,
            COALESCE(( SELECT string_agg(DISTINCT ih.invoice_number::text, ', '::text ORDER BY (ih.invoice_number::text)) AS string_agg
                   FROM erp.material_supplier_invoice_lines il
                     JOIN erp.material_supplier_invoices ih ON ih.id = il.invoice_id
                     JOIN erp.material_purchase_items pi ON pi.id = il.purchase_item_id
                  WHERE pi.purchase_id = h.id AND ih.status::text = 'POSTED'::text), h.supplier_invoice_number::text)::character varying(100) AS supplier_invoice_number,
            h.physical_at,
            COALESCE(( SELECT min(ih.due_date) AS min
                   FROM erp.material_supplier_invoice_lines il
                     JOIN erp.material_supplier_invoices ih ON ih.id = il.invoice_id
                     JOIN erp.material_purchase_items pi ON pi.id = il.purchase_item_id
                  WHERE pi.purchase_id = h.id AND ih.status::text = 'POSTED'::text), h.due_date) AS due_date,
            erp.material_purchase_final_ap_total(h.id) AS payable_amount,
            COALESCE(( SELECT sum(sp.amount) AS sum
                   FROM erp.supplier_payments sp
                  WHERE sp.purchase_id = h.id AND sp.status::text = 'POSTED'::text), 0::numeric) AS paid_amount
           FROM erp.material_purchase_headers h
             LEFT JOIN erp.suppliers s ON s.id = h.supplier_id
          WHERE h.status::text = 'POSTED'::text
        )
 SELECT purchase_id,
    purchase_number,
    supplier_id,
    supplier_name,
    supplier_invoice_number,
    physical_at,
    due_date,
    payable_amount,
    paid_amount,
    GREATEST(payable_amount - paid_amount, 0::numeric) AS outstanding_amount,
        CASE
            WHEN due_date IS NULL OR payable_amount <= paid_amount THEN 0
            ELSE GREATEST(CURRENT_DATE - due_date, 0)
        END AS days_overdue,
        CASE
            WHEN payable_amount <= paid_amount THEN 'PAID'::text
            WHEN due_date IS NULL OR CURRENT_DATE <= due_date THEN 'CURRENT'::text
            WHEN (CURRENT_DATE - due_date) <= 30 THEN '1_30'::text
            WHEN (CURRENT_DATE - due_date) <= 60 THEN '31_60'::text
            WHEN (CURRENT_DATE - due_date) <= 90 THEN '61_90'::text
            ELSE '90_PLUS'::text
        END AS aging_bucket
   FROM ap
  WHERE payable_amount > 0.005 OR paid_amount > 0.005;;

alter view "erp"."v_supplier_ap_aging" owner to "postgres";

CREATE OR REPLACE FUNCTION erp.material_purchase_grni_total(p_purchase_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
select coalesce(sum(
  case when i.invoice_match_state='DIRECT_FINAL' then 0
  else greatest(
    erp.material_purchase_invoice_capacity(i.id)
      - erp.material_purchase_posted_invoice_qty(i.id),0
  )*i.unit_price end
),0)::numeric
from erp.material_purchase_items i where i.purchase_id=$1
$function$;

alter function "erp"."material_purchase_grni_total"(p_purchase_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v260_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
  select 'PRODUCT_IDENTITY_CHAIN_GAP','P1',count(*)::bigint,'Version SKU aktif berakhir tanpa successor yang menyambung tepat waktu.' from erp.products p where p.is_active=true and p.effective_to is not null and not exists (select 1 from erp.products s where s.supersedes_product_id=p.id and s.identity_root_id=p.identity_root_id and s.effective_from=p.effective_to)
  union all select 'FG_STOCK_BEFORE_PRODUCT_IDENTITY_EFFECTIVE','P1',count(*)::bigint,'Ada stok FG masuk sebelum versi SKU mulai berlaku.' from erp.fg_stock_movements fm join erp.products p on p.id=fm.product_id where fm.qty_signed>0 and fm.physical_at<p.effective_from
  union all select 'NEW_FG_AFTER_PRODUCT_IDENTITY_EXPIRED','P1',count(*)::bigint,'QC/conversion menciptakan stok baru ke versi SKU yang sudah berakhir.' from erp.fg_stock_movements fm join erp.products p on p.id=fm.product_id where fm.qty_signed>0 and fm.movement_type in ('QC_GOOD','CONVERSION_IN') and p.effective_to is not null and fm.physical_at>=p.effective_to
  union all select 'PRODUCT_ECONOMICS_ON_NONROOT_IDENTITY','P0',((select count(*) from erp.product_price_versions pp join erp.products p on p.id=pp.product_id where pp.product_id<>p.identity_root_id)+(select count(*) from erp.accessory_bom_versions ab join erp.products p on p.id=ab.product_id where ab.product_id<>p.identity_root_id))::bigint,'Harga jual/accessory BOM harus hidup di logical SKU root agar edit identitas tidak membuat ekonomi basi.'
  union all select 'PO_LOGICAL_SKU_MULTIPLE_ACCESSORY_BOM_ECONOMICS','P0',count(*)::bigint,'Satu PO + logical SKU root memakai lebih dari satu frozen accessory BOM economics.' from (select c.po_id,p.identity_root_id from erp.po_accessory_bom_commitments c join erp.products p on p.id=c.product_id group by c.po_id,p.identity_root_id having count(distinct c.bom_version_id)>1) x
  union all select 'POSTED_NONACCESSORY_ISSUE_MISSING_PRICE_VERSION','P0',count(*)::bigint,'Material non-accessory mandor POSTED tanpa price-version provenance.' from erp.contractor_material_issue_items i join erp.contractor_material_issues h on h.id=i.issue_id join erp.materials m on m.id=i.material_id where h.status='POSTED' and m.material_type<>'ACCESSORY' and i.material_price_version_id is null
  union all select 'POSTED_OPENING_PERCENT_HPP_SNAPSHOT_MISMATCH','P0',count(*)::bigint,'Opening FG % harga jual tidak reconcile dengan snapshot harga dan persentasenya.' from erp.opening_balance_items i join erp.opening_balance_headers h on h.id=i.opening_id where h.status='POSTED' and i.balance_type='FINISHED_GOODS' and i.hpp_input_method='PRICE_PERCENT' and (i.reference_sell_price_snapshot is null or i.hpp_percent_of_price is null or i.unit_cost_snapshot is null or abs(i.unit_cost_snapshot-(i.reference_sell_price_snapshot*i.hpp_percent_of_price/100.0))>0.0001)
  union all select 'OPENING_HPP_CORRECTION_CUTOVER_PRICE_BASIS_MISMATCH','P0',count(*)::bigint,'Koreksi HPP opening berbasis persen tidak lagi memakai harga jual historis pada timestamp opening/cutover.' from erp.opening_hpp_corrections c join erp.fg_lots l on l.id=c.lot_id join erp.products p on p.id=l.product_id left join lateral (select pp.price from erp.product_price_versions pp where pp.product_id=p.identity_root_id and pp.effective_from<=l.produced_at and (pp.effective_to is null or pp.effective_to>l.produced_at) order by pp.effective_from desc,pp.created_at desc,pp.id desc limit 1) px on true where c.source_method='PRICE_PERCENT' and (c.reference_sell_price_snapshot is null or c.percent_of_price is null or px.price is null or abs(c.reference_sell_price_snapshot-px.price)>0.0001 or abs(c.corrected_hpp-(c.reference_sell_price_snapshot*c.percent_of_price/100.0))>0.0001)
  union all select 'POSITIVE_FG_STOCK_HIDDEN_FROM_SELLABLE','P1',count(*)::bigint,'Ada stok FG positif yang tidak tampil di sumber data SKU sellable.' from erp.fg_inventory_balances b where b.cached_qty_pcs>0 and not exists(select 1 from erp.v_products_sellable s where s.id=b.product_id)
  union all select 'NEGATIVE_VENDOR_AP_BALANCE','P0',count(*)::bigint,'Saldo AP vendor menjadi negatif; payment/claim/reversal melampaui hutang vendor.' from (select jl.vendor_id,sum(jl.credit-jl.debit) bal from erp.journal_lines jl join erp.journal_entries je on je.id=jl.journal_entry_id where jl.vendor_id is not null and jl.account_id=(select account_id from erp.accounting_account_mappings where mapping_key='AP_VENDOR') and je.status in ('POSTED','REVERSED') group by jl.vendor_id having sum(jl.credit-jl.debit)<-0.01) x
  union all select 'SUPPLIER_PAYMENT_EXCEEDS_CURRENT_PAYABLE','P0',count(*)::bigint,'Pembayaran supplier POSTED melebihi hutang pembelian current setelah koreksi harga/retur.' from erp.material_purchase_headers mph where mph.status='POSTED' and coalesce((select sum(sp.amount) from erp.supplier_payments sp where sp.purchase_id=mph.id and sp.status='POSTED'),0)>erp.material_purchase_payable_total(mph.id)+0.01;
$function$;

alter function "erp"."run_v260_integrity_checks"() owner to "postgres";

create or replace view "erp"."v_case_browser" with (security_invoker=true) as
 SELECT 'BS:'::text || b.id::text AS case_key,
    'BS'::text AS case_type,
    'bs_cases'::text AS source_table,
    b.id AS source_id,
    b.bs_number AS case_number,
    b.physical_at AS opened_at,
    b.status::text AS status,
    b.row_version,
    b.qty_pcs,
    b.po_id,
    po.po_number,
    po.model_id,
    pm.model_name,
    b.cutting_group_id,
    cg.group_number,
    b.product_id,
    p.sku,
    p.product_name,
    b.responsible_contractor_id,
    ct.contractor_name,
    b.responsible_vendor_id,
    lv.vendor_name,
    b.detected_at_stage::text AS detected_stage,
    b.cause_source::text AS cause_source,
    b.untracked_type::text AS untracked_type,
    b.source_laundry_receipt_line_id,
    b.qc_item_id,
    NULL::uuid AS laundry_delivery_id,
    0 AS held_payroll_qty,
    COALESCE(( SELECT sum(e.remaining_qty)::integer AS sum
           FROM erp.v_payroll_eligible_work_lines e
             JOIN erp.rework_component_lines rcl ON e.source_type = 'REWORK'::text AND rcl.id = e.source_id
             JOIN erp.bs_case_components bcc ON bcc.id = rcl.bs_case_component_id
          WHERE bcc.bs_case_id = b.id), 0) AS nota_eligible_rework_qty,
    COALESCE(( SELECT sum(r.qty_pcs)::integer AS sum
           FROM erp.bs_resolutions r
          WHERE r.bs_case_id = b.id), 0) AS resolved_qty,
    b.status::text = ANY (ARRAY['RESOLVED'::character varying, 'SCRAPPED'::character varying, 'WRITTEN_OFF'::character varying, 'CANCELLED'::character varying]::text[]) AS is_closed,
        CASE
            WHEN b.status::text = ANY (ARRAY['OPEN'::character varying, 'PARTIAL'::character varying]::text[]) THEN 'START_REWORK_OR_DISPOSITION'::text
            WHEN b.status::text = 'IN_REWORK'::text THEN 'COMPLETE_REWORK'::text
            ELSE 'VIEW_OR_REVERSE'::text
        END AS next_action,
    concat_ws(' '::text, b.bs_number, po.po_number, pm.model_name, cg.group_number, p.sku, p.product_name, ct.contractor_name, lv.vendor_name, b.status, b.cause_source, b.untracked_type, b.legacy_reference, b.notes) AS search_text,
    b.notes
   FROM erp.bs_cases b
     LEFT JOIN erp.production_orders po ON po.id = b.po_id
     LEFT JOIN erp.product_models pm ON pm.id = po.model_id
     LEFT JOIN erp.cutting_groups cg ON cg.id = b.cutting_group_id
     LEFT JOIN erp.products p ON p.id = b.product_id
     LEFT JOIN erp.contractors ct ON ct.id = b.responsible_contractor_id
     LEFT JOIN erp.laundry_vendors lv ON lv.id = b.responsible_vendor_id
UNION ALL
 SELECT 'LAUNDRY:'::text || c.id::text AS case_key,
    c.claim_type::text AS case_type,
    'laundry_claims'::text AS source_table,
    c.id AS source_id,
    c.claim_number AS case_number,
    c.opened_at,
    c.status::text AS status,
    c.row_version,
    c.qty_claimed AS qty_pcs,
    ld.po_id,
    po.po_number,
    po.model_id,
    pm.model_name,
    NULL::uuid AS cutting_group_id,
    NULL::character varying AS group_number,
    NULL::uuid AS product_id,
    NULL::character varying AS sku,
    NULL::character varying AS product_name,
    NULL::uuid AS responsible_contractor_id,
    NULL::character varying AS contractor_name,
    c.vendor_id AS responsible_vendor_id,
    lv.vendor_name,
    'LAUNDRY'::text AS detected_stage,
    'LAUNDRY'::text AS cause_source,
    NULL::text AS untracked_type,
    c.receipt_line_id AS source_laundry_receipt_line_id,
    NULL::uuid AS qc_item_id,
    c.delivery_id AS laundry_delivery_id,
        CASE
            WHEN (c.claim_type::text = ANY (ARRAY['STUCK'::character varying, 'MISSING'::character varying]::text[])) AND c.status::text <> 'REJECTED'::text THEN c.qty_claimed
            ELSE 0
        END AS held_payroll_qty,
    0 AS nota_eligible_rework_qty,
        CASE
            WHEN c.status::text = ANY (ARRAY['SETTLED'::character varying, 'WRITTEN_OFF'::character varying]::text[]) THEN c.qty_claimed
            ELSE 0
        END AS resolved_qty,
    c.status::text = ANY (ARRAY['SETTLED'::character varying, 'WRITTEN_OFF'::character varying, 'REJECTED'::character varying]::text[]) AS is_closed,
        CASE
            WHEN c.status::text = ANY (ARRAY['OPEN'::character varying, 'ACCEPTED'::character varying]::text[]) THEN 'RESOLVE_CLAIM'::text
            ELSE 'VIEW_OR_REVERSE'::text
        END AS next_action,
    concat_ws(' '::text, c.claim_number, c.claim_type, c.status, ld.delivery_number, po.po_number, pm.model_name, lv.vendor_name, c.qty_claimed, c.compensation_amount, c.notes) AS search_text,
    c.notes
   FROM erp.laundry_claims c
     JOIN erp.laundry_deliveries ld ON ld.id = c.delivery_id
     JOIN erp.production_orders po ON po.id = ld.po_id
     LEFT JOIN erp.product_models pm ON pm.id = po.model_id
     JOIN erp.laundry_vendors lv ON lv.id = c.vendor_id;;

alter view "erp"."v_case_browser" owner to "postgres";

create or replace view "erp"."v_cutting_group_quantity_detail" with (security_invoker=true) as
 WITH a AS (
         SELECT l.cutting_group_id,
            COALESCE(sum(l.qty_delta_pcs), 0::bigint) AS adjustment_pcs
           FROM erp.cutting_qty_correction_lines l
          GROUP BY l.cutting_group_id
        )
 SELECT cg.id AS cutting_group_id,
    cg.po_id,
    cg.cutting_batch_id,
    COALESCE(o.total_pcs, 0::bigint) AS original_pcs,
    COALESCE(a.adjustment_pcs, 0::bigint) AS adjustment_pcs,
    COALESCE(o.total_pcs, 0::bigint) + COALESCE(a.adjustment_pcs, 0::bigint) AS effective_pcs
   FROM erp.cutting_groups cg
     LEFT JOIN erp.v_cutting_group_original_totals o ON o.cutting_group_id = cg.id
     LEFT JOIN a ON a.cutting_group_id = cg.id;;

alter view "erp"."v_cutting_group_quantity_detail" owner to "postgres";

create or replace view "erp"."v_payroll_nota_browser" with (security_invoker=true) as
 SELECT n.id AS payroll_id,
    n.payroll_number,
    n.contractor_id,
    c.contractor_code,
    c.contractor_name,
    n.period_start,
    n.period_end,
    n.status,
    n.row_version,
    n.payment_date,
    n.settled_at,
    n.labor_total,
    n.attendance_total,
    n.reimburse_total,
    n.deduction_total,
    n.manual_adjustment,
    n.net_payable,
    COALESCE(x.work_line_count, 0::bigint) AS work_line_count,
    COALESCE(x.work_qty, 0::bigint) AS work_qty,
    COALESCE(e.eligible_line_count, 0::bigint) AS eligible_line_count,
    COALESCE(e.eligible_qty, 0::bigint) AS eligible_qty,
    COALESCE(e.eligible_amount, 0::numeric)::numeric(24,2) AS eligible_amount,
    n.status::text = ANY (ARRAY['DRAFT'::character varying, 'CALCULATED'::character varying, 'REVIEW'::character varying]::text[]) AS can_merge,
    n.status::text = ANY (ARRAY['APPROVED'::character varying, 'PAID'::character varying, 'REVERSED'::character varying]::text[]) AS is_locked,
    n.notes,
    n.created_at,
    n.updated_at
   FROM erp.payroll_settlements n
     JOIN erp.contractors c ON c.id = n.contractor_id
     LEFT JOIN LATERAL ( SELECT count(*) AS work_line_count,
            COALESCE(sum(w.qty_payable), 0::bigint) AS work_qty
           FROM erp.payroll_work_items w
          WHERE w.payroll_id = n.id) x ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS eligible_line_count,
            COALESCE(sum(q.remaining_qty), 0::bigint) AS eligible_qty,
            COALESCE(sum(q.remaining_qty::numeric * q.rate_snapshot), 0::numeric) AS eligible_amount
           FROM erp.v_payroll_eligible_work_lines q
          WHERE q.contractor_id = n.contractor_id AND q.eligible_at::date <= n.period_end) e ON true;;

alter view "erp"."v_payroll_nota_browser" owner to "postgres";

CREATE OR REPLACE FUNCTION erp.material_purchase_total_liability(p_purchase_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
select erp.material_purchase_final_ap_total($1)+erp.material_purchase_grni_total($1)
$function$;

alter function "erp"."material_purchase_total_liability"(p_purchase_id uuid) owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v263d_case_claim_read_integrity_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
  select 'browser_direct_laundry_claim_write_grant','CRITICAL',count(*)::bigint,
         'Authenticated browser must mutate laundry claims only through domain RPCs'
  from information_schema.role_table_grants g
  where g.table_schema='erp' and g.table_name='laundry_claims' and g.grantee='authenticated'
    and g.privilege_type in('INSERT','UPDATE','DELETE')

  union all
  select 'settled_claim_compensation_without_journal','CRITICAL',count(*)::bigint,
         'Positive SETTLED claim compensation must have a posted/reversed settlement journal'
  from erp.laundry_claims c
  where c.status='SETTLED' and c.compensation_amount>0
    and not exists(select 1 from erp.journal_entries j
      where j.source_type='LAUNDRY_CLAIM_SETTLEMENT' and j.source_id=c.id and j.status in('POSTED','REVERSED'))

  union all
  select 'active_case_missing_from_browser','CRITICAL',count(*)::bigint,
         'Every BS and laundry claim must appear exactly once in Case Browser'
  from(
    select 'BS:'||id::text key from erp.bs_cases
    union all select 'LAUNDRY:'||id::text from erp.laundry_claims
  ) s
  where (select count(*) from erp.v_case_browser b where b.case_key=s.key)<>1

  union all
  select 'empty_accessory_bom_hidden','CRITICAL',count(*)::bigint,
         'An active empty BOM must be visible as explicit NO_ACCESSORY'
  from erp.accessory_bom_versions b
  where b.is_active and b.effective_from<=clock_timestamp()
    and (b.effective_to is null or b.effective_to>clock_timestamp())
    and not exists(select 1 from erp.accessory_bom_items i where i.bom_version_id=b.id)
    and not exists(select 1 from erp.v_accessory_hpp_setup v
      where v.bom_version_id=b.id and v.setup_state='NO_ACCESSORY')

  union all
  select 'receivable_formula_mismatch','CRITICAL',count(*)::bigint,
         'Outstanding/credit must reconcile gross invoice less posted returns and payments'
  from erp.v_customer_receivables v
  where abs(v.outstanding_amount-greatest(v.net_invoice_amount-v.paid_amount,0))>0.005
     or abs(v.credit_amount-greatest(v.paid_amount-v.net_invoice_amount,0))>0.005;
$function$;

alter function "erp"."run_v263d_case_claim_read_integrity_checks"() owner to "postgres";

CREATE OR REPLACE FUNCTION erp.run_v267_financial_truth_checks()
 RETURNS TABLE(check_name text, severity text, issue_count bigint, details text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_catalog', 'information_schema', 'pg_temp'
AS $function$
  select 'V267_GRNI_MAPPING_INVALID','CRITICAL',count(*)::bigint,
         'GRNI_MATERIAL must map to an active CREDIT liability account'
  from erp.accounting_account_mappings m
  join erp.chart_accounts a on a.id=m.account_id
  where m.mapping_key='GRNI_MATERIAL'
    and not(a.account_type='LIABILITY' and a.normal_balance='CREDIT' and a.is_active and a.is_postable)

  union all
  select 'V267_MISSING_GRNI_MAPPING','CRITICAL',case when exists(
    select 1 from erp.accounting_account_mappings where mapping_key='GRNI_MATERIAL'
  ) then 0 else 1 end::bigint,'GRNI mapping is required'

  union all
  select 'V267_ESTIMATED_RECEIPT_MISSING_GRNI_RECLASS','CRITICAL',count(*)::bigint,
         'Posted estimated receipts require an AP-to-GRNI reclassification journal'
  from erp.material_purchase_headers h
  where h.status='POSTED' and erp.material_purchase_grni_total(h.id)>0.005
    and not exists(
      select 1 from erp.journal_entries j
      where j.source_type='MATERIAL_PURCHASE_GRNI_RECLASS' and j.source_id=h.id
        and j.status in('POSTED','REVERSED')
    )

  union all
  select 'V267_POSTED_INVOICE_MISSING_JOURNAL','CRITICAL',count(*)::bigint,
         'Every non-zero posted supplier invoice requires an AP/GRNI journal'
  from erp.material_supplier_invoices h
  where h.status='POSTED'
    and exists(select 1 from erp.material_supplier_invoice_lines l where l.invoice_id=h.id and(l.net_amount<>0 or l.grni_clear_amount_snapshot<>0))
    and not exists(
      select 1 from erp.journal_entries j
      where j.source_type='MATERIAL_SUPPLIER_INVOICE' and j.source_id=h.id and j.status='POSTED'
    )

  union all
  select 'V267_INVOICE_MATCH_OVER_RECEIPT','CRITICAL',count(*)::bigint,
         'Posted supplier-invoice quantity exceeds receipt quantity net of GRNI-backed returns'
  from erp.material_purchase_items i
  where erp.material_purchase_posted_invoice_qty(i.id)>erp.material_purchase_invoice_capacity(i.id)+0.000001

  union all
  select 'V267_PAYMENT_EXCEEDS_FINAL_AP','CRITICAL',count(*)::bigint,
         'Supplier payment must never consume GRNI or exceed final AP'
  from erp.material_purchase_headers h
  where coalesce((select sum(p.amount) from erp.supplier_payments p where p.purchase_id=h.id and p.status='POSTED'),0)
        >erp.material_purchase_final_ap_total(h.id)+0.01

  union all
  select 'V267_LEGACY_CORRECTION_ON_GRNI','CRITICAL',count(*)::bigint,
         'Legacy price corrections may only touch DIRECT_FINAL receipt items'
  from erp.material_purchase_cost_correction_items ci
  join erp.material_purchase_cost_corrections c on c.id=ci.correction_id
  join erp.material_purchase_items i on i.id=ci.purchase_item_id
  where c.status='POSTED' and i.invoice_match_state<>'DIRECT_FINAL'

  union all
  select 'V267_POSTED_RETURN_MISSING_LIABILITY_SNAPSHOT','CRITICAL',count(*)::bigint,
         'Posted supplier returns require AP/GRNI quantity and amount snapshots'
  from erp.material_supplier_return_items ri
  join erp.material_supplier_returns rh on rh.id=ri.return_id
  where rh.status='POSTED' and(
    ri.ap_relief_qty_snapshot is null or ri.grni_relief_qty_snapshot is null
    or ri.ap_relief_amount_snapshot is null or ri.grni_relief_amount_snapshot is null
  )

  union all
  select 'V267_GRNI_GL_SUBLEDGER_MISMATCH','CRITICAL',case when abs(
    coalesce((select sum(a.credit_total-a.debit_total)
      from erp.account_daily_balances a
      where a.account_id=erp.account_id('GRNI_MATERIAL')),0)
    -coalesce((select sum(erp.material_purchase_grni_total(h.id))
      from erp.material_purchase_headers h where h.status='POSTED'),0)
  )>0.01 then 1 else 0 end::bigint,
  'GRNI general ledger must equal estimated unmatched receipt liability'

  union all
  select 'V267_AP_GL_SUBLEDGER_MISMATCH','CRITICAL',case when abs(
    coalesce((select sum(a.credit_total-a.debit_total)
      from erp.account_daily_balances a
      where a.account_id=erp.account_id('AP_SUPPLIER')),0)
    -coalesce((select sum(greatest(
      erp.material_purchase_final_ap_total(h.id)
      -coalesce((select sum(p.amount) from erp.supplier_payments p where p.purchase_id=h.id and p.status='POSTED'),0),0
    )) from erp.material_purchase_headers h where h.status='POSTED'),0)
  )>0.01 then 1 else 0 end::bigint,
  'Supplier AP general ledger must equal final-invoice subledger net of payment/returns'

  union all
  select 'V267_BROWSER_ROLE_DIRECT_INVOICE_WRITE','CRITICAL',count(*)::bigint,
         'Supplier invoice aggregate must be writable only through v2 RPCs'
  from information_schema.role_table_grants g
  where g.table_schema='erp' and g.table_name in('material_supplier_invoices','material_supplier_invoice_lines')
    and g.grantee in('PUBLIC','anon','authenticated')
    and g.privilege_type in('INSERT','UPDATE','DELETE');
$function$;

alter function "erp"."run_v267_financial_truth_checks"() owner to "postgres";

create or replace view "erp"."v_cutting_batch_totals" with (security_invoker=true) as
 SELECT b.id AS cutting_batch_id,
    b.po_id,
    COALESCE(sum(q.original_pcs), 0::numeric)::bigint AS original_pcs,
    COALESCE(sum(q.adjustment_pcs), 0::numeric)::bigint AS adjustment_pcs,
    COALESCE(sum(q.effective_pcs), 0::numeric)::bigint AS effective_pcs
   FROM erp.cutting_batches b
     LEFT JOIN erp.v_cutting_group_quantity_detail q ON q.cutting_batch_id = b.id
  GROUP BY b.id, b.po_id;;

alter view "erp"."v_cutting_batch_totals" owner to "postgres";

create or replace view "erp"."v_cutting_group_totals" with (security_invoker=true) as
 SELECT cutting_group_id,
    po_id,
    effective_pcs AS total_pcs
   FROM erp.v_cutting_group_quantity_detail;;

alter view "erp"."v_cutting_group_totals" owner to "postgres";

create or replace view "erp"."v_cutting_qty_correction_batch_browser" with (security_invoker=true) as
 SELECT b.id AS cutting_batch_id,
    b.batch_number,
    b.cut_at,
    b.status AS batch_status,
    b.row_version,
    b.po_id,
    po.po_number,
    po.status AS po_status,
    po.current_stage,
    pm.model_code,
    pm.model_name,
    COALESCE(g.group_count, 0::bigint) AS group_count,
    COALESCE(g.original_pcs, 0::bigint) AS original_pcs,
    COALESCE(g.adjustment_pcs, 0::bigint) AS adjustment_pcs,
    COALESCE(g.effective_pcs, 0::bigint) AS effective_pcs,
    COALESCE(g.downstream_committed_pcs, 0::bigint) AS downstream_committed_pcs,
    COALESCE(g.presewing_editable_group_count, 0::bigint) AS presewing_editable_group_count,
    COALESCE(c.correction_count, 0::bigint) AS correction_count,
    c.last_correction_at,
    COALESCE(c.correction_count, 0::bigint) > 0 AS has_correction_history
   FROM erp.cutting_batches b
     JOIN erp.production_orders po ON po.id = b.po_id
     JOIN erp.product_models pm ON pm.id = po.model_id
     LEFT JOIN LATERAL ( SELECT count(*) AS group_count,
            COALESCE(sum(q.original_pcs), 0::numeric)::bigint AS original_pcs,
            COALESCE(sum(q.adjustment_pcs), 0::numeric)::bigint AS adjustment_pcs,
            COALESCE(sum(q.effective_pcs), 0::numeric)::bigint AS effective_pcs,
            COALESCE(sum(erp.cutting_group_downstream_committed_qty(cg.id)), 0::numeric)::bigint AS downstream_committed_pcs,
            count(*) FILTER (WHERE erp.is_cutting_group_presewing_reversible(cg.id)) AS presewing_editable_group_count
           FROM erp.cutting_groups cg
             LEFT JOIN erp.v_cutting_group_quantity_detail q ON q.cutting_group_id = cg.id
          WHERE cg.cutting_batch_id = b.id) g ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS correction_count,
            max(cq.physical_at) AS last_correction_at
           FROM erp.cutting_qty_corrections cq
          WHERE cq.cutting_batch_id = b.id) c ON true;;

alter view "erp"."v_cutting_qty_correction_batch_browser" owner to "postgres";

create or replace view "erp"."v_fg_partial_completion_progress" with (security_invoker=true) as
 WITH qc AS (
         SELECT i.cutting_group_id,
            COALESCE(sum(i.qty_good_pcs), 0::bigint) AS qc_good_qty_pcs,
            COALESCE(sum(i.qty_bs_pcs), 0::bigint) AS qc_bs_qty_pcs,
            COALESCE(sum(i.qty_good_pcs + i.qty_bs_pcs), 0::bigint) AS qc_accounted_qty_pcs,
            COALESCE(sum(i.qty_good_pcs + i.qty_bs_pcs) FILTER (WHERE i.source_laundry_receipt_line_id IS NOT NULL), 0::bigint) AS laundry_qc_accounted_qty_pcs,
            COALESCE(sum(i.qty_good_pcs + i.qty_bs_pcs) FILTER (WHERE i.source_laundry_receipt_line_id IS NULL), 0::bigint) AS direct_qc_accounted_qty_pcs,
            count(DISTINCT q.id) AS completion_count,
            max(q.physical_at) AS last_completion_at
           FROM erp.qc_inspection_items i
             JOIN erp.qc_inspections q ON q.id = i.inspection_id
          WHERE q.status::text = 'POSTED'::text
          GROUP BY i.cutting_group_id
        ), latest_completion AS (
         SELECT DISTINCT ON (i.cutting_group_id) i.cutting_group_id,
            q.completion_mode
           FROM erp.qc_inspection_items i
             JOIN erp.qc_inspections q ON q.id = i.inspection_id
          WHERE q.status::text = 'POSTED'::text AND q.completion_mode IS NOT NULL
          ORDER BY i.cutting_group_id, q.physical_at DESC, q.id DESC
        ), laundry AS (
         SELECT l.cutting_group_id,
            COALESCE(sum(l.qty_sent_pcs), 0::bigint) AS laundry_sent_qty_pcs
           FROM erp.laundry_delivery_lines l
             JOIN erp.laundry_deliveries d ON d.id = l.delivery_id
          WHERE d.status::text <> ALL (ARRAY['DRAFT'::character varying, 'REVERSED'::character varying]::text[])
          GROUP BY l.cutting_group_id
        ), laundry_returned AS (
         SELECT dl.cutting_group_id,
            COALESCE(sum(rl.qty_good_received), 0::bigint) AS laundry_good_returned_qty_pcs,
            COALESCE(sum(rl.qty_bs_laundry), 0::bigint) AS laundry_bs_returned_qty_pcs,
            COALESCE(sum(rl.qty_good_received + rl.qty_bs_laundry), 0::bigint) AS laundry_returned_qty_pcs
           FROM erp.laundry_receipt_lines rl
             JOIN erp.laundry_receipts r ON r.id = rl.receipt_id
             JOIN erp.laundry_delivery_lines dl ON dl.id = rl.delivery_line_id
             JOIN erp.laundry_deliveries d ON d.id = dl.delivery_id
          WHERE r.status::text = 'POSTED'::text AND d.status::text <> 'REVERSED'::text
          GROUP BY dl.cutting_group_id
        ), resolved_claim AS (
         SELECT dl.cutting_group_id,
            COALESCE(sum(c.qty_claimed), 0::bigint) AS resolved_claim_qty_pcs
           FROM erp.laundry_claims c
             JOIN erp.laundry_receipt_lines rl ON rl.id = c.receipt_line_id
             JOIN erp.laundry_delivery_lines dl ON dl.id = rl.delivery_line_id
          WHERE (c.claim_type::text = ANY (ARRAY['MISSING'::character varying, 'STUCK'::character varying]::text[])) AND (c.status::text = ANY (ARRAY['SETTLED'::character varying, 'WRITTEN_OFF'::character varying]::text[]))
          GROUP BY dl.cutting_group_id
        ), progress AS (
         SELECT g.id AS cutting_group_id,
            g.po_id,
            g.group_number,
            g.row_version,
            po.status AS po_status,
            COALESCE(t.total_pcs, 0::bigint) AS effective_qty_pcs,
            COALESCE(q.qc_good_qty_pcs, 0::bigint) AS qc_good_qty_pcs,
            COALESCE(q.qc_bs_qty_pcs, 0::bigint) AS qc_bs_qty_pcs,
            COALESCE(q.qc_accounted_qty_pcs, 0::bigint) AS qc_accounted_qty_pcs,
            GREATEST(COALESCE(t.total_pcs, 0::bigint) - COALESCE(q.qc_accounted_qty_pcs, 0::bigint), 0::bigint) AS remaining_qc_qty_pcs,
            COALESCE(q.direct_qc_accounted_qty_pcs, 0::bigint) AS direct_qc_accounted_qty_pcs,
            COALESCE(q.laundry_qc_accounted_qty_pcs, 0::bigint) AS laundry_qc_accounted_qty_pcs,
            COALESCE(l.laundry_sent_qty_pcs, 0::bigint) AS laundry_sent_qty_pcs,
            COALESCE(lr.laundry_good_returned_qty_pcs, 0::bigint) AS laundry_good_returned_qty_pcs,
            COALESCE(lr.laundry_bs_returned_qty_pcs, 0::bigint) AS laundry_bs_returned_qty_pcs,
            COALESCE(lr.laundry_returned_qty_pcs, 0::bigint) AS laundry_returned_qty_pcs,
            COALESCE(rc.resolved_claim_qty_pcs, 0::bigint) AS resolved_claim_qty_pcs,
            GREATEST(COALESCE(lr.laundry_returned_qty_pcs, 0::bigint) - COALESCE(q.laundry_qc_accounted_qty_pcs, 0::bigint), 0::bigint) AS ready_for_qc_qty_pcs,
            GREATEST(COALESCE(l.laundry_sent_qty_pcs, 0::bigint) - COALESCE(lr.laundry_returned_qty_pcs, 0::bigint) - COALESCE(rc.resolved_claim_qty_pcs, 0::bigint), 0::bigint) AS laundry_outstanding_qty_pcs,
            COALESCE(q.direct_qc_accounted_qty_pcs, 0::bigint) + COALESCE(l.laundry_sent_qty_pcs, 0::bigint) AS source_accounted_qty_pcs,
            GREATEST(COALESCE(t.total_pcs, 0::bigint) - COALESCE(q.direct_qc_accounted_qty_pcs, 0::bigint) - COALESCE(l.laundry_sent_qty_pcs, 0::bigint), 0::bigint) AS remaining_source_qty_pcs,
            COALESCE(q.completion_count, 0::bigint) AS completion_count,
            q.last_completion_at,
            lc.completion_mode AS last_completion_mode
           FROM erp.cutting_groups g
             JOIN erp.production_orders po ON po.id = g.po_id
             LEFT JOIN erp.v_cutting_group_totals t ON t.cutting_group_id = g.id
             LEFT JOIN qc q ON q.cutting_group_id = g.id
             LEFT JOIN latest_completion lc ON lc.cutting_group_id = g.id
             LEFT JOIN laundry l ON l.cutting_group_id = g.id
             LEFT JOIN laundry_returned lr ON lr.cutting_group_id = g.id
             LEFT JOIN resolved_claim rc ON rc.cutting_group_id = g.id
        )
 SELECT cutting_group_id,
    po_id,
    group_number,
    row_version,
    po_status,
    effective_qty_pcs,
    qc_good_qty_pcs,
    qc_bs_qty_pcs,
    qc_accounted_qty_pcs,
    remaining_qc_qty_pcs,
    direct_qc_accounted_qty_pcs,
    laundry_sent_qty_pcs,
    source_accounted_qty_pcs,
    remaining_source_qty_pcs,
    completion_count,
    last_completion_at,
        CASE
            WHEN po_status::text = 'FINISHED'::text THEN 'FINISHED'::text
            WHEN qc_accounted_qty_pcs = 0 THEN 'OPEN'::text
            WHEN ready_for_qc_qty_pcs > 0 AND last_completion_mode::text = 'PARTIAL_SELECTION'::text THEN 'PARTIAL_SELECTION'::text
            WHEN ready_for_qc_qty_pcs > 0 THEN 'READY_FOR_QC'::text
            WHEN laundry_outstanding_qty_pcs > 0 THEN 'WAITING_LAUNDRY'::text
            WHEN remaining_qc_qty_pcs > 0 AND last_completion_mode::text = 'PARTIAL_SELECTION'::text THEN 'PARTIAL_SELECTION'::text
            WHEN remaining_qc_qty_pcs > 0 THEN 'OPEN_SOURCE'::text
            ELSE 'QC_COMPLETE'::text
        END AS completion_status,
    laundry_qc_accounted_qty_pcs,
    laundry_good_returned_qty_pcs,
    laundry_bs_returned_qty_pcs,
    laundry_returned_qty_pcs,
    resolved_claim_qty_pcs,
    ready_for_qc_qty_pcs,
    laundry_outstanding_qty_pcs,
    last_completion_mode
   FROM progress p;;

alter view "erp"."v_fg_partial_completion_progress" owner to "postgres";

create or replace view "erp"."v_material_purchase_liability_status" with (security_invoker=true) as
 SELECT h.id AS purchase_id,
    h.purchase_number,
    h.supplier_id,
    s.supplier_code,
    s.supplier_name,
    h.physical_at,
    h.status,
    h.payment_status,
    COALESCE(sum(i.line_total), 0::numeric) AS receipt_estimate_amount,
    erp.material_purchase_final_ap_total(h.id) AS final_ap_amount,
    erp.material_purchase_grni_total(h.id) AS grni_estimated_amount,
    erp.material_purchase_total_liability(h.id) AS total_liability_amount,
    COALESCE(( SELECT sum(p.amount) AS sum
           FROM erp.supplier_payments p
          WHERE p.purchase_id = h.id AND p.status::text = 'POSTED'::text), 0::numeric) AS paid_amount,
    GREATEST(erp.material_purchase_final_ap_total(h.id) - COALESCE(( SELECT sum(p.amount) AS sum
           FROM erp.supplier_payments p
          WHERE p.purchase_id = h.id AND p.status::text = 'POSTED'::text), 0::numeric), 0::numeric) AS final_ap_outstanding,
        CASE
            WHEN erp.material_purchase_grni_total(h.id) > 0.005 AND erp.material_purchase_final_ap_total(h.id) > 0.005 THEN 'PARTIAL_INVOICE'::text
            WHEN erp.material_purchase_grni_total(h.id) > 0.005 THEN 'KASBON_BELUM_DITERIMA_ESTIMASI_KEWAJIBAN'::text
            WHEN erp.material_purchase_final_ap_total(h.id) > 0.005 THEN 'FINAL_AP'::text
            ELSE 'NO_LIABILITY'::text
        END AS liability_state,
    ( SELECT string_agg(DISTINCT ih.invoice_number::text, ', '::text ORDER BY (ih.invoice_number::text)) AS string_agg
           FROM erp.material_supplier_invoice_lines il
             JOIN erp.material_supplier_invoices ih ON ih.id = il.invoice_id
             JOIN erp.material_purchase_items pi ON pi.id = il.purchase_item_id
          WHERE pi.purchase_id = h.id AND ih.status::text = 'POSTED'::text) AS active_invoice_numbers,
    ( SELECT min(ih.due_date) AS min
           FROM erp.material_supplier_invoice_lines il
             JOIN erp.material_supplier_invoices ih ON ih.id = il.invoice_id
             JOIN erp.material_purchase_items pi ON pi.id = il.purchase_item_id
          WHERE pi.purchase_id = h.id AND ih.status::text = 'POSTED'::text) AS earliest_due_date,
        CASE
            WHEN erp.material_purchase_grni_total(h.id) > 0.005 THEN GREATEST(CURRENT_DATE - h.physical_at::date, 0)
            ELSE 0
        END AS unfinalized_days,
    h.row_version,
    h.created_at,
    h.updated_at,
    concat_ws(' '::text, h.purchase_number, s.supplier_code, s.supplier_name, h.status) AS search_text
   FROM erp.material_purchase_headers h
     LEFT JOIN erp.suppliers s ON s.id = h.supplier_id
     LEFT JOIN erp.material_purchase_items i ON i.purchase_id = h.id
  GROUP BY h.id, s.id;;

alter view "erp"."v_material_purchase_liability_status" owner to "postgres";

create or replace view "erp"."v_material_grni_aging" with (security_invoker=true) as
 SELECT purchase_id,
    purchase_number,
    supplier_id,
    supplier_code,
    supplier_name,
    physical_at,
    status,
    payment_status,
    receipt_estimate_amount,
    final_ap_amount,
    grni_estimated_amount,
    total_liability_amount,
    paid_amount,
    final_ap_outstanding,
    liability_state,
    active_invoice_numbers,
    earliest_due_date,
    unfinalized_days,
    row_version,
    created_at,
    updated_at,
    search_text
   FROM erp.v_material_purchase_liability_status
  WHERE status::text = 'POSTED'::text AND grni_estimated_amount > 0.005;;

alter view "erp"."v_material_grni_aging" owner to "postgres";

create or replace view "erp"."v_wip_control_status_v1" with (security_invoker=true) as
 WITH sewing AS (
         SELECT e.cutting_group_id,
            COALESCE(sum(e.qty_signed), 0::bigint) AS sewn_qty_pcs
           FROM erp.sewing_terminal_events e
          WHERE e.cutting_group_id IS NOT NULL
          GROUP BY e.cutting_group_id
        ), laundry AS (
         SELECT l.cutting_group_id,
            COALESCE(sum(l.qty_sent_pcs) FILTER (WHERE d.status::text = 'DRAFT'::text), 0::bigint) AS laundry_draft_qty_pcs,
            COALESCE(sum(l.qty_sent_pcs) FILTER (WHERE d.status::text <> ALL (ARRAY['DRAFT'::character varying, 'REVERSED'::character varying]::text[])), 0::bigint) AS laundry_sent_qty_pcs
           FROM erp.laundry_delivery_lines l
             JOIN erp.laundry_deliveries d ON d.id = l.delivery_id
          GROUP BY l.cutting_group_id
        ), receipt AS (
         SELECT dl.cutting_group_id,
            COALESCE(sum(rl.qty_good_received + rl.qty_bs_laundry), 0::bigint) AS laundry_good_bs_qty_pcs,
            COALESCE(sum(rl.qty_stuck), 0::bigint) AS laundry_stuck_qty_pcs,
            COALESCE(sum(rl.qty_missing), 0::bigint) AS laundry_missing_qty_pcs,
            COALESCE(sum(rl.qty_good_received + rl.qty_bs_laundry + rl.qty_stuck + rl.qty_missing), 0::bigint) AS laundry_accounted_qty_pcs
           FROM erp.laundry_receipt_lines rl
             JOIN erp.laundry_receipts rr ON rr.id = rl.receipt_id AND rr.status::text = 'POSTED'::text
             JOIN erp.laundry_delivery_lines dl ON dl.id = rl.delivery_line_id
             JOIN erp.laundry_deliveries d ON d.id = dl.delivery_id AND d.status::text <> 'REVERSED'::text
          GROUP BY dl.cutting_group_id
        ), resolved_claim AS (
         SELECT dl.cutting_group_id,
            COALESCE(sum(c.qty_claimed), 0::bigint) AS resolved_issue_qty_pcs
           FROM erp.laundry_claims c
             JOIN erp.laundry_receipt_lines rl ON rl.id = c.receipt_line_id
             JOIN erp.laundry_delivery_lines dl ON dl.id = rl.delivery_line_id
          WHERE (c.claim_type::text = ANY (ARRAY['MISSING'::character varying, 'STUCK'::character varying]::text[])) AND (c.status::text = ANY (ARRAY['SETTLED'::character varying, 'WRITTEN_OFF'::character varying]::text[]))
          GROUP BY dl.cutting_group_id
        ), bs AS (
         SELECT b.cutting_group_id,
            count(*) AS open_bs_count
           FROM erp.bs_cases b
          WHERE b.cutting_group_id IS NOT NULL AND (b.status::text <> ALL (ARRAY['RESOLVED'::character varying, 'SCRAPPED'::character varying, 'WRITTEN_OFF'::character varying, 'CANCELLED'::character varying]::text[]))
          GROUP BY b.cutting_group_id
        ), rework AS (
         SELECT b.cutting_group_id,
            count(*) AS open_rework_count
           FROM erp.rework_orders r
             JOIN erp.bs_cases b ON b.id = r.bs_case_id
          WHERE b.cutting_group_id IS NOT NULL AND (r.status::text <> ALL (ARRAY['COMPLETED'::character varying, 'CANCELLED'::character varying]::text[]))
          GROUP BY b.cutting_group_id
        ), blocker AS (
         SELECT f.cutting_group_id,
            count(*) AS open_flag_count,
            COALESCE(jsonb_agg(jsonb_build_object('id', f.id, 'type', f.flag_type, 'note', f.note, 'row_version', f.row_version) ORDER BY f.flag_type, f.id), '[]'::jsonb) AS open_flags
           FROM erp.wip_control_flags f
          WHERE f.status = 'OPEN'::text
          GROUP BY f.cutting_group_id
        ), measured AS (
         SELECT g.id AS cutting_group_id,
            g.po_id,
            g.cutting_batch_id,
            g.group_number,
            g.status AS group_status,
            g.row_version,
            g.updated_at,
            po.po_number,
            po.status AS po_status,
            po.current_stage,
            m.model_code,
            m.model_name,
            g.executor_name,
            g.picked_up_at,
            g.notes,
            g.pattern_id,
            COALESCE(g.pattern_code_snapshot, p.pattern_code) AS pattern_code,
            COALESCE(g.pattern_revision_snapshot, p.revision) AS pattern_revision,
            COALESCE(g.pattern_name_snapshot, p.pattern_name, g.pattern_type::text) AS pattern_name,
            p.sort_order AS pattern_sort_order,
            p.is_active AS pattern_is_active,
            COALESCE(q.total_pcs, 0::bigint) AS effective_qty_pcs,
            GREATEST(COALESCE(s.sewn_qty_pcs, 0::bigint), 0::bigint) AS sewn_qty_pcs,
            GREATEST(COALESCE(q.total_pcs, 0::bigint) - GREATEST(COALESCE(s.sewn_qty_pcs, 0::bigint), COALESCE(l.laundry_sent_qty_pcs, 0::bigint), COALESCE(fg.qc_accounted_qty_pcs, 0::bigint)), 0::bigint) AS unfinished_sewing_qty_pcs,
            GREATEST(COALESCE(s.sewn_qty_pcs, 0::bigint) - COALESCE(l.laundry_sent_qty_pcs, 0::bigint) - COALESCE(fg.direct_qc_accounted_qty_pcs, 0::bigint), 0::bigint) AS unsent_ready_qty_pcs,
            COALESCE(l.laundry_draft_qty_pcs, 0::bigint) AS laundry_draft_qty_pcs,
            COALESCE(l.laundry_sent_qty_pcs, 0::bigint) AS laundry_sent_qty_pcs,
            GREATEST(COALESCE(l.laundry_sent_qty_pcs, 0::bigint) - COALESCE(rr.laundry_accounted_qty_pcs, 0::bigint), 0::bigint) AS laundry_in_transit_qty_pcs,
            COALESCE(rr.laundry_good_bs_qty_pcs, 0::bigint) AS laundry_good_bs_qty_pcs,
            GREATEST(COALESCE(rr.laundry_stuck_qty_pcs, 0::bigint) + COALESCE(rr.laundry_missing_qty_pcs, 0::bigint) - COALESCE(rc.resolved_issue_qty_pcs, 0::bigint), 0::bigint) AS unresolved_laundry_issue_qty_pcs,
            COALESCE(fg.ready_for_qc_qty_pcs, 0::bigint) AS pending_final_sku_handoff_qty_pcs,
            COALESCE(fg.remaining_qc_qty_pcs, COALESCE(q.total_pcs, 0::bigint)) AS remaining_final_sku_qty_pcs,
            COALESCE(bs.open_bs_count, 0::bigint) AS open_bs_count,
            COALESCE(rw.open_rework_count, 0::bigint) AS open_rework_count,
            COALESCE(bl.open_flag_count, 0::bigint) AS open_flag_count,
            COALESCE(bl.open_flags, '[]'::jsonb) AS open_flags
           FROM erp.cutting_groups g
             JOIN erp.production_orders po ON po.id = g.po_id
             JOIN erp.product_models m ON m.id = po.model_id
             LEFT JOIN erp.production_patterns p ON p.id = g.pattern_id
             LEFT JOIN erp.v_cutting_group_totals q ON q.cutting_group_id = g.id
             LEFT JOIN sewing s ON s.cutting_group_id = g.id
             LEFT JOIN laundry l ON l.cutting_group_id = g.id
             LEFT JOIN receipt rr ON rr.cutting_group_id = g.id
             LEFT JOIN resolved_claim rc ON rc.cutting_group_id = g.id
             LEFT JOIN erp.v_fg_partial_completion_progress fg ON fg.cutting_group_id = g.id
             LEFT JOIN bs ON bs.cutting_group_id = g.id
             LEFT JOIN rework rw ON rw.cutting_group_id = g.id
             LEFT JOIN blocker bl ON bl.cutting_group_id = g.id
        )
 SELECT cutting_group_id,
    po_id,
    cutting_batch_id,
    group_number,
    group_status,
    row_version,
    updated_at,
    po_number,
    po_status,
    current_stage,
    model_code,
    model_name,
    executor_name,
    picked_up_at,
    notes,
    pattern_id,
    pattern_code,
    pattern_revision,
    pattern_name,
    pattern_sort_order,
    pattern_is_active,
    effective_qty_pcs,
    sewn_qty_pcs,
    unfinished_sewing_qty_pcs,
    unsent_ready_qty_pcs,
    laundry_draft_qty_pcs,
    laundry_sent_qty_pcs,
    laundry_in_transit_qty_pcs,
    laundry_good_bs_qty_pcs,
    unresolved_laundry_issue_qty_pcs,
    pending_final_sku_handoff_qty_pcs,
    remaining_final_sku_qty_pcs,
    open_bs_count,
    open_rework_count,
    open_flag_count,
    open_flags,
        CASE
            WHEN po_status::text = 'CANCELLED'::text AND unsent_ready_qty_pcs = 0 AND laundry_draft_qty_pcs = 0 AND laundry_in_transit_qty_pcs = 0 AND unresolved_laundry_issue_qty_pcs = 0 AND pending_final_sku_handoff_qty_pcs = 0 AND open_bs_count = 0 AND open_rework_count = 0 AND open_flag_count = 0 THEN 'COMPLETED'::text
            WHEN effective_qty_pcs > 0 AND unfinished_sewing_qty_pcs = 0 AND unsent_ready_qty_pcs = 0 AND laundry_draft_qty_pcs = 0 AND laundry_in_transit_qty_pcs = 0 AND unresolved_laundry_issue_qty_pcs = 0 AND pending_final_sku_handoff_qty_pcs = 0 AND remaining_final_sku_qty_pcs = 0 AND open_bs_count = 0 AND open_rework_count = 0 AND open_flag_count = 0 THEN 'COMPLETED'::text
            ELSE 'ACTIVE'::text
        END AS control_status,
    jsonb_build_object('unfinished_sewing', unfinished_sewing_qty_pcs > 0, 'unsent_ready', unsent_ready_qty_pcs > 0, 'laundry_draft', laundry_draft_qty_pcs > 0, 'laundry_in_transit', laundry_in_transit_qty_pcs > 0, 'laundry_issue', unresolved_laundry_issue_qty_pcs > 0, 'pending_final_sku_handoff', pending_final_sku_handoff_qty_pcs > 0, 'remaining_final_sku', remaining_final_sku_qty_pcs > 0, 'open_bs', open_bs_count > 0, 'open_rework', open_rework_count > 0, 'operator_flag', open_flag_count > 0) AS blockers
   FROM measured;;

