insert into "erp"."system_release_info" ("singleton_id","release_name","release_version","installed_at","notes") select "singleton_id","release_name","release_version","installed_at","notes" from jsonb_populate_recordset(null::"erp"."system_release_info",$cp45a_snapshot_20260903$[{"notes":"v2.6.1 FINAL BACKEND FREEZE FOR UX. ERP Garment and ERP Enteng are runtime-equivalent. Freeze gate: 93 integrity checks clean, Security Advisor clean, material checkpoint replay matched full replay, AP/material regression passed, HPP/FG/COGS/return/reversal financial stress passed, GL/daily balance/P&L/balance sheet reconciled, and all synthetic fixtures rolled back. Backend workflow/schema is locked for UX work; unfreeze only for an explicitly approved P0/P1 correction or a planned versioned release. This is a release marker, not a database read-only lock.\n[v2.6.11a/UAT_PRECONNECT] Public self-profile Auth facade created; broad ERP schema remains unexposed; unguarded v2.6.0 diagnostics and direct legacy sale posting removed from authenticated execution.","installed_at":"2026-08-29T20:46:32+00:00","release_name":"ERP GARMENT / KONVEKSI BACKEND","singleton_id":1,"release_version":"2.6.11"}]$cp45a_snapshot_20260903$::jsonb);

insert into "erp"."schema_migrations" ("version","description","installed_at") select "version","description","installed_at" from jsonb_populate_recordset(null::"erp"."schema_migrations",$cp45a_snapshot_20260903$[{"version":"v2.0.0","description":"ERP backend V2 core + production + payroll + laundry + FG + HPP + accounting + security","installed_at":"2026-08-26T10:31:39.007374+00:00"},{"version":"v2.5.0","description":"First-financial-use accessory BOM commitment, safe migration staging/apply framework, accessory category HPP, UOM, mandor settlement, HPP/GL and security hardening","installed_at":"2026-08-26T10:31:39.007374+00:00"},{"version":"v2.5.1","description":"Cutting quantity correction, lineage and integrity hardening","installed_at":"2026-08-26T10:31:39.007374+00:00"},{"version":"v2.5.2","description":"Payroll/rework/recost queue and material cost snapshot hardening","installed_at":"2026-08-26T10:31:39.007374+00:00"},{"version":"v2.5.3","description":"Financial overpayment, sales return and settlement integrity hardening","installed_at":"2026-08-26T10:31:39.007374+00:00"},{"version":"v2.5.4","description":"Controlled reversals/corrections across payments, laundry, QC, rework, conversion, purchasing, opening balances and FG adjustment","installed_at":"2026-08-26T10:31:39.007374+00:00"},{"version":"v2.5.5","description":"Chronological stock safety, moving-average GL revaluation, opening HPP controls, migration validation, deterministic sale locking and final integrity hardening","installed_at":"2026-08-26T10:31:39.007374+00:00"},{"version":"v2.5.6","description":"Final production audit: panic-delete/correction boundaries, period/future-date protection, PO/Potongan identity safeguards, HPP concurrency/completeness, financial cache integrity, supplier-return chronology, material roll/costing preserved, and FG Global Mutasi drag separated from chronological SKU Stock Card.","installed_at":"2026-08-26T10:31:39.007374+00:00"},{"version":"v2.5.7","description":"Fifth-pass red-team hardening: work-completion and QC entitlement caps, zero-ledger future-date guards, payroll source concurrency locks, upstream reversal recovery after downstream reversal, FG statement-clock ordering, controlled reopen of FINISHED production orders with WIP-close reversal, finished-PO integrity checks, and trigger-function ACL hardening.","installed_at":"2026-08-26T10:31:39.007374+00:00"},{"version":"v2.5.8","description":"Sixth-pass freeze audit: controlled laundry-claim reversal now restores FINISHED PO WIP close accounting, physical-stage posting is blocked on FINISHED POs until controlled reopen, claim reversal preserves ON_HOLD/nonfinished lifecycle state, vendor invoice/payment/replacement, cutting redistribution/reversal/downstream limits, accounting period close/reopen and freeze regressions stress-tested.","installed_at":"2026-08-26T10:31:39.007374+00:00"},{"version":"v2.5.9","description":"Audit-8 / v2.5.9 hardening: concurrency, reversal, HPP, supplier/vendor AP, finished-PO lifecycle, effective-dated SKU identity, BOM/rate versioning and bulk-rate safeguards.","installed_at":"2026-08-26T10:31:40.79949+00:00"},{"version":"v2.6.0","description":"v2.6.0 FINAL FREEZE: two consecutive post-patch red-team clean passes; final material-reversal chronology valuation fix plus supplier/AP, SKU/BOM, HPP, opening/migration, account-mapping and security hardening verified.","installed_at":"2026-08-26T10:31:40.83245+00:00"},{"version":"v2.6.10","description":"Partial Finished Goods completion through immutable QC postings","installed_at":"2026-08-29T18:58:30+00:00"},{"version":"v2.6.11","description":"Operational truth for partial FG, Laundry outstanding, and all-day sales drafts","installed_at":"2026-08-29T20:46:32+00:00"},{"version":"v2.6.11a","description":"UAT phase-0 public self-profile facade and direct legacy RPC closure","installed_at":"2026-08-30T09:04:14.63828+00:00"},{"version":"v2.6.14a","description":"Private no-hook/no-grant attendance HPP foundation using immutable SELESAI_DIJAHIT, explicit normal-Mandor policy, exact debit-line journal lineage, deterministic manifest, and active-pool cancellation","installed_at":"2026-09-02T05:28:28.255316+00:00"},{"version":"v2.6.14b","description":"Candidate hardening: nullable open-ended policy manifest key, one direct correction lineage, deterministic visible exclusion summary","installed_at":"2026-09-02T05:29:02.479913+00:00"},{"version":"v2.6.14c","description":"CP3 R3 UAT alignment: approval-time attendance WIP accrual, settlement-only payment, Asia/Jakarta canonical dates, strict nested JSON types, allowed audit vocabulary, and shared source/pool locks","installed_at":"2026-09-02T05:29:06.772306+00:00"},{"version":"v2.6.14d","description":"CP3 R4 active-pool race, owning reversal, protected journal, and strict-proof hardening","installed_at":"2026-09-02T05:29:11.027594+00:00"},{"version":"v2.6.16","description":"CP4 persistent attendance-HPP lot/GL route and null-safe least-privilege owner/admin Data API boundary","installed_at":"2026-09-02T05:29:58.587106+00:00"},{"version":"v2.6.17","description":"Pre-CP5 dynamic role access, Master Pola, authoritative WIP control, and Final-SKU brand boundary","installed_at":"2026-09-02T14:49:11.827931+00:00"},{"version":"v2.6.17a","description":"CP4.5 initial-only immutable pattern assignment and downstream/race guard","installed_at":"2026-09-02T18:51:06.85919+00:00"},{"version":"v2.6.2","description":"Safe CRUD foundation, fabric benchmark, material Gudang read models, and pre-sewing cutting correction","installed_at":"2026-08-28T07:04:29.462925+00:00"},{"version":"v2.6.2a","description":"Close residual direct materials writes and PUBLIC trigger-function execution found by post-migration red-team smoke test","installed_at":"2026-08-28T07:05:24.17884+00:00"},{"version":"v2.6.2b","description":"Generic audit entity resolver supports UUID id or material_id keys","installed_at":"2026-08-28T07:10:56.341178+00:00"},{"version":"v2.6.2c","description":"Explicit idempotency deny policy, consolidated app-user read policy, and targeted new FK indexes","installed_at":"2026-08-28T07:12:39.585449+00:00"},{"version":"v2.6.3a","description":"Laundry-aware payroll hold/release, eligible Nota read model, atomic merge, and work snapshot wrapper","installed_at":"2026-08-28T07:23:32.509446+00:00"},{"version":"v2.6.3a1","description":"Increment an existing unlocked Nota source line when a late receipt releases additional eligible quantity","installed_at":"2026-08-28T07:24:51.447663+00:00"},{"version":"v2.6.3b","description":"Laundry receipt aggregate CRUD, BS product lineage, late claim lock, payroll-safe reversal","installed_at":"2026-08-28T07:36:40.001071+00:00"},{"version":"v2.6.3c","description":"Controlled manual BS/classification/disposition plus server-priced cross-Mandor rework aggregate RPCs","installed_at":"2026-08-28T07:46:29.164295+00:00"},{"version":"v2.6.3d","description":"Safe laundry claim mutations, Case/Nota browser views, return-netted AR, visible NO ACCESSORY setup","installed_at":"2026-08-28T07:53:25.547836+00:00"},{"version":"v2.6.3e","description":"Red-team closure for private triggers, lifecycle inserts, master cascade delete, audit coverage and hot indexes","installed_at":"2026-08-28T08:04:11.030103+00:00"},{"version":"v2.6.4","description":"Atomic material and roll warehouse transfer with safe draft, post, reversal and browser model","installed_at":"2026-08-28T08:09:21.34846+00:00"},{"version":"v2.6.4a","description":"Controlled cutting material reversal before sewing, preserving stock and journal lineage","installed_at":"2026-08-28T08:14:26.253458+00:00"},{"version":"v2.6.4b","description":"Make temporary ERP export storage private and add platform storage checks","installed_at":"2026-08-28T08:21:02.465227+00:00"},{"version":"v2.6.5","description":"Safe aggregate Gudang writes for material adjustment, supplier return and contractor issue","installed_at":"2026-08-28T08:27:04.446695+00:00"},{"version":"v2.6.5a","description":"Complete row-audit coverage for browser-writable ERP tables","installed_at":"2026-08-28T08:31:29.737741+00:00"},{"version":"v2.6.6","description":"Safe accessory category/material/UOM/price successors and idempotent FG adjustment aggregate","installed_at":"2026-08-28T09:00:17.625651+00:00"},{"version":"v2.6.7","description":"GRNI versus final AP, multi-receipt partial supplier invoices, discount/reversal history, and AP/GRNI supplier-return split","installed_at":"2026-08-28T09:36:17.141099+00:00"},{"version":"v2.6.7a","description":"Keep cross-receipt supplier invoice identity in the v2.6.7 aggregate without violating the legacy receipt-header uniqueness rule","installed_at":"2026-08-28T09:40:48.95311+00:00"},{"version":"v2.6.7b","description":"Check AP-backed supplier-return dependency before supplier-payment projection during invoice reversal","installed_at":"2026-08-28T09:42:32.246697+00:00"},{"version":"v2.6.7c","description":"Fix legacy invoice-finalization alias ambiguity and revoke PUBLIC EXECUTE from v2.6.7 trigger functions","installed_at":"2026-08-28T09:56:33.559096+00:00"},{"version":"v2.6.8","description":"Balanced SOFP current earnings, owner financial/performance/quality snapshot, report confidence and GL-subledger controls","installed_at":"2026-08-28T09:49:07.269554+00:00"},{"version":"v2.6.8a","description":"Scope browser direct-write control to ledger and supplier-invoice aggregate while preserving guarded DRAFT CRUD","installed_at":"2026-08-28T09:50:08.198486+00:00"},{"version":"v2.6.8b","description":"Move obsolete pre-scope control body outside run-check discovery and retain one authoritative v2.6.8 suite","installed_at":"2026-08-28T09:59:01.290854+00:00"},{"version":"v2.6.8c","description":"Return one authoritative direct ledger/invoice write control on both upgrade and fresh-install paths","installed_at":"2026-08-28T10:01:05.720117+00:00"},{"version":"v2.6.9","description":"Safe cutting correction v2, sewing-aware quantity floor, immutable history read models, and legacy RPC closure","installed_at":"2026-08-28T15:33:34.777442+00:00"},{"version":"v2.6.9a","description":"Targeted downstream indexes for the sewing-aware cutting correction quantity floor","installed_at":"2026-08-28T15:36:01.472496+00:00"}]$cp45a_snapshot_20260903$::jsonb);

insert into "erp"."cp3_r4_rollback_capsule" ("function_identity","function_definition","definition_sha256","acl_snapshot","owner_snapshot","captured_at") select "function_identity","function_definition","definition_sha256","acl_snapshot","owner_snapshot","captured_at" from jsonb_populate_recordset(null::"erp"."cp3_r4_rollback_capsule",$cp45a_snapshot_20260903$[{"captured_at":"2026-09-02T05:29:11.050789+00:00","acl_snapshot":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"939b893a17ad243847de894d56b6258e9e8fb9dc6366d5e139f679622066512a","function_identity":"erp.approve_payroll(p_payroll_id uuid)","function_definition":"CREATE OR REPLACE FUNCTION erp.approve_payroll(p_payroll_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'erp', 'public', 'pg_temp'\nAS $function$\ndeclare\n  p erp.payroll_settlements%rowtype;\n  v_manual_reimburse numeric(20,2) := 0;\n  v_extra_accrual numeric(20,2) := 0;\n  v_negative_manual numeric(20,2) := 0;\n  v_attendance numeric(20,2) := 0;\nbegin\n  perform erp.require_owner_admin();\n  perform erp.recalculate_payroll(p_payroll_id);\n  select * into p from erp.payroll_settlements where id=p_payroll_id for update;\n  if p.id is null or p.status not in ('CALCULATED','REVIEW') then\n    raise exception 'Payroll must be CALCULATED/REVIEW before approval, current status %',p.status;\n  end if;\n\n  perform erp._cp3_lock_business_period(p.period_start,p.period_end);\n  if exists (\n    select 1 from erp.journal_entries je\n    where je.source_id=p.id\n      and je.source_type in ('PAYROLL_ATTENDANCE_ACCRUAL','PAYROLL_EXTRA_ACCRUAL','PAYROLL_MANUAL_REDUCTION')\n      and je.status='POSTED'\n  ) then\n    raise exception 'Payroll approval accrual already exists; inspect duplicate/ambiguous approval state';\n  end if;\n\n  select coalesce(sum(amount),0) into v_manual_reimburse\n  from erp.payroll_reimbursements\n  where payroll_id=p.id and source_type<>'ACCESSORY_BOM';\n  v_attendance:=round(coalesce(p.attendance_total,0),2);\n  v_extra_accrual:=round(v_manual_reimburse+greatest(p.manual_adjustment,0),2);\n  v_negative_manual:=round(greatest(-p.manual_adjustment,0),2);\n\n  update erp.payroll_settlements set status='APPROVED',updated_at=now() where id=p.id;\n\n  if v_attendance>0 then\n    perform erp.post_journal(\n      'PAYROLL_ATTENDANCE_ACCRUAL',p.id,p.period_end,\n      'Attendance payroll approved into unassigned WIP',\n      jsonb_build_array(\n        jsonb_build_object('mapping_key','WIP','debit',v_attendance,'credit',0,'contractor_id',p.contractor_id,\n                           'description','Approved attendance cost awaiting SELESAI_DIJAHIT allocation'),\n        jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',0,'credit',v_attendance,'contractor_id',p.contractor_id,\n                           'description','Approved attendance payable')\n      )\n    );\n  end if;\n  if v_extra_accrual>0 then\n    perform erp.post_journal(\n      'PAYROLL_EXTRA_ACCRUAL',p.id,p.period_end,\n      'Approved manual reimbursement/manual payroll accrual',\n      jsonb_build_array(\n        jsonb_build_object('mapping_key','LABOR_COST','debit',v_extra_accrual,'credit',0,'contractor_id',p.contractor_id),\n        jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',0,'credit',v_extra_accrual,'contractor_id',p.contractor_id)\n      )\n    );\n  end if;\n  if v_negative_manual>0 then\n    perform erp.post_journal(\n      'PAYROLL_MANUAL_REDUCTION',p.id,p.period_end,\n      'Approved negative manual payroll adjustment',\n      jsonb_build_array(\n        jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',v_negative_manual,'credit',0,'contractor_id',p.contractor_id),\n        jsonb_build_object('mapping_key','LABOR_COST','debit',0,'credit',v_negative_manual,'contractor_id',p.contractor_id)\n      )\n    );\n  end if;\n\n  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)\n  values(\n    'payroll_settlements',p.id,'POST',\n    jsonb_build_object('lifecycle_action','APPROVE','attendance_accrual',v_attendance,\n                       'extra_accrual',v_extra_accrual,'manual_reduction',v_negative_manual),\n    erp.current_app_user_id(),'Payroll approved; cost recognition completed before payment'\n  );\nend;\n$function$\n"},{"captured_at":"2026-09-02T05:29:11.05581+00:00","acl_snapshot":["postgres=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"b182b73982d55ccd5b1d5e96c4e8622970a16f29dbb11317ba4b89c73e3a6b54","function_identity":"erp.cancel_attendance_hpp_pool_v1(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)","function_definition":"CREATE OR REPLACE FUNCTION erp.cancel_attendance_hpp_pool_v1(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'\nAS $function$\ndeclare\n  v_operation constant text := 'cancel_attendance_hpp_pool_v1';\n  v_hash text;\n  v_cached jsonb;\n  v_pool erp.attendance_hpp_pools%rowtype;\n  v_reversal_journal_id uuid;\n  v_response jsonb;\nbegin\n  perform erp.require_owner_admin();\n  if p_pool_id is null or p_expected_version is null then\n    raise exception 'pool_id and expected_version are required';\n  end if;\n  if coalesce(btrim(p_reason), '') = '' then\n    raise exception 'Attendance HPP cancellation reason is required';\n  end if;\n\n  v_hash := erp._request_hash(jsonb_build_object(\n    'pool_id', p_pool_id,\n    'reason', btrim(p_reason),\n    'expected_version', p_expected_version\n  ));\n  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);\n  if v_cached is not null then return v_cached; end if;\n\n  select * into v_pool\n  from erp.attendance_hpp_pools\n  where id = p_pool_id\n  for update;\n\n  if v_pool.id is null then raise exception 'Attendance HPP pool not found'; end if;\n  if v_pool.status not in ('DRAFT','ACTIVE') then\n    raise exception 'Only DRAFT or ACTIVE attendance HPP pool can be cancelled';\n  end if;\n  if v_pool.row_version <> p_expected_version then\n    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_pool.row_version;\n  end if;\n\n  perform erp._cp3_lock_business_period(v_pool.period_start, v_pool.period_end);\n\n  if v_pool.status = 'DRAFT' then\n    update erp.attendance_hpp_pools\n    set status = 'VOIDED',\n        cancellation_reason = btrim(p_reason),\n        cancelled_by = erp.current_app_user_id(),\n        cancelled_at = clock_timestamp(),\n        row_version = row_version + 1\n    where id = v_pool.id\n    returning * into v_pool;\n\n    insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)\n    values (\n      'attendance_hpp_pools', v_pool.id, 'UPDATE',\n      jsonb_build_object('previous_status','DRAFT','new_status','VOIDED','lifecycle_action','VOID_DRAFT'),\n      erp.current_app_user_id(), btrim(p_reason)\n    );\n\n    v_response := jsonb_build_object(\n      'pool_id', v_pool.id,\n      'status', v_pool.status,\n      'row_version', v_pool.row_version,\n      'reversal_journal_entry_id', null,\n      'residue_expected', 0\n    );\n    return erp._idempotency_complete(v_operation, p_client_request_id, v_response);\n  end if;\n\n  if v_pool.post_journal_entry_id is null then\n    raise exception 'ACTIVE attendance HPP pool has no source journal; cancellation stopped to avoid residue';\n  end if;\n\n  if not exists (\n    select 1 from erp.journal_entries je\n    where je.id = v_pool.post_journal_entry_id\n      and je.status = 'POSTED'\n      and je.source_type = 'ATTENDANCE_HPP_POOL'\n      and je.source_id = v_pool.id\n  ) then\n    raise exception 'Pool journal is not an active posted ATTENDANCE_HPP_POOL journal';\n  end if;\n\n  v_reversal_journal_id := erp.reverse_journal(v_pool.post_journal_entry_id, btrim(p_reason));\n\n  update erp.attendance_hpp_pools\n  set status = 'CANCELLED',\n      cancellation_journal_entry_id = v_reversal_journal_id,\n      cancellation_reason = btrim(p_reason),\n      cancelled_by = erp.current_app_user_id(),\n      cancelled_at = clock_timestamp(),\n      row_version = row_version + 1\n  where id = v_pool.id\n  returning * into v_pool;\n\n  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)\n  values (\n    'attendance_hpp_pools', v_pool.id, 'REVERSE',\n    jsonb_build_object(\n      'post_journal_entry_id', v_pool.post_journal_entry_id,\n      'cancellation_journal_entry_id', v_pool.cancellation_journal_entry_id,\n      'previous_status', 'ACTIVE',\n      'new_status', 'CANCELLED',\n      'lifecycle_action', 'CANCEL_ACTIVE'\n    ),\n    erp.current_app_user_id(), btrim(p_reason)\n  );\n\n  v_response := jsonb_build_object(\n    'pool_id', v_pool.id,\n    'status', v_pool.status,\n    'row_version', v_pool.row_version,\n    'reversal_journal_entry_id', v_pool.cancellation_journal_entry_id,\n    'residue_expected', 0\n  );\n  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);\nend;\n$function$\n"},{"captured_at":"2026-09-02T05:29:11.056074+00:00","acl_snapshot":["postgres=X/postgres","authenticated=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"c4e28a87b6931dced0560ef969d820546563316ba148a19e81a3768d8f38bef0","function_identity":"erp.cancel_unpaid_payroll(p_payroll_id uuid, p_reason text)","function_definition":"CREATE OR REPLACE FUNCTION erp.cancel_unpaid_payroll(p_payroll_id uuid, p_reason text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'erp', 'public', 'pg_temp'\nAS $function$\ndeclare\n  p erp.payroll_settlements%rowtype;\n  r record;\nbegin\n  perform erp.require_owner_admin();\n  if nullif(trim(p_reason),'') is null then raise exception 'Cancellation reason is required'; end if;\n  select * into p from erp.payroll_settlements where id=p_payroll_id for update;\n  if p.id is null then raise exception 'Payroll not found'; end if;\n  if p.status='PAID' then raise exception 'Paid payroll requires a dedicated financial reversal, not unpaid cancellation'; end if;\n  if p.status='REVERSED' then return; end if;\n  if p.status not in ('DRAFT','CALCULATED','REVIEW','APPROVED') then raise exception 'Payroll cannot be cancelled in status %',p.status; end if;\n  perform erp._cp3_lock_business_period(p.period_start,p.period_end);\n\n  if exists(\n    select 1 from erp.attendance_hpp_pool_sources s\n    join erp.attendance_hpp_pools hp on hp.id=s.pool_id\n    where s.payroll_id=p.id and hp.status='ACTIVE'\n  ) then\n    raise exception 'PAYROLL_CONSUMED_BY_ACTIVE_HPP_POOL: cancel the active attendance HPP pool first';\n  end if;\n\n  for r in\n    select je.id from erp.journal_entries je\n    where je.source_id=p.id\n      and je.source_type in ('PAYROLL_ATTENDANCE_ACCRUAL','PAYROLL_EXTRA_ACCRUAL','PAYROLL_MANUAL_REDUCTION')\n      and je.status='POSTED'\n    order by je.posting_at desc,je.id desc\n  loop perform erp.reverse_journal(r.id,p_reason); end loop;\n\n  update erp.payroll_settlements set status='REVERSED',settled_at=null,updated_at=now() where id=p.id;\n  for r in select distinct pd.contractor_issue_item_id id from erp.payroll_deductions pd\n           where pd.payroll_id=p.id and pd.contractor_issue_item_id is not null\n  loop perform erp.refresh_contractor_issue_payroll_status(r.id); end loop;\n  for r in select distinct pr.source_id id from erp.payroll_reimbursements pr\n           where pr.payroll_id=p.id and pr.source_type='ACCESSORY_BOM' and pr.source_id is not null\n  loop\n    update erp.contractor_accessory_reimbursement_entitlements e\n    set payroll_status=case\n      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id\n                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status='PAID') then 'SETTLED'\n      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id\n                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status<>'REVERSED') then 'ALLOCATED'\n      else 'UNALLOCATED' end\n    where e.id=r.id;\n  end loop;\n  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)\n  values('payroll_settlements',p.id,'CANCEL_UNPAID',jsonb_build_object('previous_status',p.status),erp.current_app_user_id(),p_reason);\nend;\n$function$\n"},{"captured_at":"2026-09-02T05:29:11.056208+00:00","acl_snapshot":["postgres=X/postgres","service_role=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"62e17c717ffee520edf2a89d8d3bf1dcb7fd5fcbedf25407e2e85da713be9efb","function_identity":"erp.reverse_journal(p_journal_entry_id uuid, p_reason text)","function_definition":"CREATE OR REPLACE FUNCTION erp.reverse_journal(p_journal_entry_id uuid, p_reason text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'erp', 'public'\nAS $function$ DECLARE v_old erp.journal_entries%ROWTYPE;v_new_id uuid;v_lines jsonb; BEGIN PERFORM erp.require_internal(); SELECT * INTO v_old FROM erp.journal_entries WHERE id=p_journal_entry_id FOR UPDATE; IF v_old.id IS NULL OR v_old.status<>'POSTED' THEN RAISE EXCEPTION 'Only posted journal can be reversed'; END IF; SELECT jsonb_agg(jsonb_build_object('account_id',jl.account_id,'debit',jl.credit,'credit',jl.debit,'description','Reversal: '||COALESCE(jl.description,''),'customer_id',jl.customer_id,'vendor_id',jl.vendor_id,'contractor_id',jl.contractor_id,'po_id',jl.po_id,'product_id',jl.product_id)) INTO v_lines FROM erp.journal_lines jl WHERE jl.journal_entry_id=p_journal_entry_id; v_new_id:=erp.post_journal('JOURNAL_REVERSAL',p_journal_entry_id,CURRENT_DATE,'Reversal: '||v_old.description||' | '||p_reason,v_lines); UPDATE erp.journal_entries SET status='REVERSED' WHERE id=p_journal_entry_id; UPDATE erp.journal_entries SET reversal_of_id=p_journal_entry_id WHERE id=v_new_id; RETURN v_new_id; END; $function$\n"},{"captured_at":"2026-09-02T05:29:11.056288+00:00","acl_snapshot":["postgres=X/postgres","authenticated=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"f5407b896cec50a153ab43297d63b7758ced2b2a17ede10300e1e467c11be05a","function_identity":"erp.reverse_paid_payroll(p_payroll_id uuid, p_reason text)","function_definition":"CREATE OR REPLACE FUNCTION erp.reverse_paid_payroll(p_payroll_id uuid, p_reason text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'erp', 'public', 'pg_temp'\nAS $function$\ndeclare\n  p erp.payroll_settlements%rowtype;\n  r record;\nbegin\n  perform erp.require_owner_admin();\n  if nullif(trim(p_reason),'') is null then raise exception 'Payroll reversal reason is required'; end if;\n  select * into p from erp.payroll_settlements where id=p_payroll_id for update;\n  if p.id is null then raise exception 'Payroll not found'; end if;\n  if p.status='REVERSED' then return; end if;\n  if p.status<>'PAID' then raise exception 'Only PAID payroll uses reverse_paid_payroll; unpaid payroll uses cancel_unpaid_payroll'; end if;\n  perform erp._cp3_lock_business_period(p.period_start,p.period_end);\n  if exists(\n    select 1 from erp.attendance_hpp_pool_sources s\n    join erp.attendance_hpp_pools hp on hp.id=s.pool_id\n    where s.payroll_id=p.id and hp.status='ACTIVE'\n  ) then\n    raise exception 'PAYROLL_CONSUMED_BY_ACTIVE_HPP_POOL: cancel the active attendance HPP pool first';\n  end if;\n\n  for r in\n    select je.id from erp.journal_entries je\n    where je.source_id=p.id\n      and je.source_type in ('PAYROLL_ATTENDANCE_ACCRUAL','PAYROLL_EXTRA_ACCRUAL','PAYROLL_MANUAL_REDUCTION',\n                             'PAYROLL_MATERIAL_DEDUCTION','PAYROLL_OTHER_DEDUCTION','PAYROLL_PAYMENT')\n      and je.status='POSTED'\n    order by je.posting_at desc,je.id desc\n  loop perform erp.reverse_journal(r.id,p_reason); end loop;\n\n  update erp.payroll_settlements set status='REVERSED',settled_at=null,updated_at=now() where id=p.id;\n  for r in select distinct pd.contractor_issue_item_id id from erp.payroll_deductions pd\n           where pd.payroll_id=p.id and pd.contractor_issue_item_id is not null\n  loop perform erp.refresh_contractor_issue_payroll_status(r.id); end loop;\n  for r in select distinct pr.source_id id from erp.payroll_reimbursements pr\n           where pr.payroll_id=p.id and pr.source_type='ACCESSORY_BOM' and pr.source_id is not null\n  loop\n    update erp.contractor_accessory_reimbursement_entitlements e\n    set payroll_status=case\n      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id\n                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status='PAID') then 'SETTLED'\n      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id\n                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status<>'REVERSED') then 'ALLOCATED'\n      else 'UNALLOCATED' end\n    where e.id=r.id;\n  end loop;\n  for r in\n    select distinct bc.id as bs_case_id from erp.bs_cases bc\n    where exists(select 1 from erp.payroll_work_items pwi where pwi.payroll_id=p.id and pwi.po_id=bc.po_id)\n       or exists(select 1 from erp.payroll_work_items pwi join erp.rework_component_lines rcl on rcl.id=pwi.source_id\n                 join erp.bs_case_components bcc on bcc.id=rcl.bs_case_component_id\n                 where pwi.payroll_id=p.id and bcc.bs_case_id=bc.id)\n  loop perform erp.rebuild_bs_component_counters(r.bs_case_id); end loop;\n  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)\n  values('payroll_settlements',p.id,'REVERSE_PAID',jsonb_build_object('previous_status','PAID'),erp.current_app_user_id(),p_reason);\nend;\n$function$\n"},{"captured_at":"2026-09-02T05:29:11.062304+00:00","acl_snapshot":["postgres=X/postgres","authenticated=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"210153e28fc23e509b316da8648338d5585eb550251dde46e0a69ad523c99124","function_identity":"erp.reverse_work_completion(p_completion_id uuid, p_reason text)","function_definition":"CREATE OR REPLACE FUNCTION erp.reverse_work_completion(p_completion_id uuid, p_reason text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'erp', 'public'\nAS $function$\ndeclare\n  h erp.work_completion_events%rowtype;\n  v_journal uuid;\nbegin\n  perform erp.require_owner_admin();\n  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal hasil kerja mandor wajib diisi'; end if;\n\n  select * into h from erp.work_completion_events where id=p_completion_id for update;\n  if h.id is null then raise exception 'Transaksi hasil kerja mandor tidak ditemukan'; end if;\n  if h.status='REVERSED' then return; end if;\n  if h.status<>'POSTED' then raise exception 'Hanya hasil kerja mandor yang sudah POSTED yang dapat direverse'; end if;\n\n  if exists(\n    select 1\n    from erp.payroll_work_items pwi\n    join erp.payroll_settlements ps on ps.id=pwi.payroll_id\n    join erp.work_completion_lines wcl on wcl.id=pwi.source_id\n    where wcl.completion_id=h.id and pwi.source_type='PRODUCTION' and ps.status<>'REVERSED'\n  ) then\n    raise exception 'Hasil kerja ini sudah masuk payroll mandor. Cancel atau reverse payroll yang masih aktif terlebih dahulu supaya upah tidak dibayar/dicabut dua kali.';\n  end if;\n\n  select id into v_journal\n  from erp.journal_entries\n  where source_type='WORK_COMPLETION' and source_id=h.id and status='POSTED'\n  order by posting_at desc,id desc limit 1;\n\n  if exists(select 1 from erp.work_completion_lines where completion_id=h.id and amount_payable>0) and v_journal is null then\n    raise exception 'Jurnal hasil kerja mandor tidak ditemukan; reversal dibatalkan agar hutang upah/HPP tidak rusak';\n  end if;\n  if v_journal is not null then perform erp.reverse_journal(v_journal,p_reason); end if;\n\n  update erp.work_completion_events set status='REVERSED',updated_at=now() where id=h.id;\n\n  if exists(select 1 from erp.fg_lots where po_id=h.po_id) then\n    perform erp.rebuild_po_hpp(h.po_id,'Work completion reversed: '||p_reason);\n    perform erp.propagate_conversion_hpp_for_po(h.po_id);\n    perform erp.sync_po_hpp_to_gl(h.po_id,current_date);\n  end if;\n\n  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)\n  values ('work_completion_events',h.id,'REVERSE',erp.current_app_user_id(),p_reason);\nend;\n$function$\n"},{"captured_at":"2026-09-02T05:29:11.062516+00:00","acl_snapshot":["postgres=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"4a420b35f86eb5d091c7f9569b157122a40e033175716681e3dd2d3b84f5fb5b","function_identity":"erp.set_contractor_hpp_policy_v1(p_payload jsonb, p_client_request_id uuid, p_expected_policy_id uuid)","function_definition":"CREATE OR REPLACE FUNCTION erp.set_contractor_hpp_policy_v1(p_payload jsonb, p_client_request_id uuid, p_expected_policy_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'\nAS $function$\ndeclare\n  v_operation constant text := 'set_contractor_hpp_policy_v1';\n  v_hash text;\n  v_cached jsonb;\n  v_contractor_id uuid;\n  v_effective_from date;\n  v_is_special boolean;\n  v_attendance_required boolean;\n  v_reason text;\n  v_contractor erp.contractors%rowtype;\n  v_current erp.contractor_hpp_policy_versions%rowtype;\n  v_next_from date;\n  v_new erp.contractor_hpp_policy_versions%rowtype;\n  v_response jsonb;\nbegin\n  perform erp.require_owner_admin();\n  perform erp._cp3_assert_closed_json_object(\n    p_payload,\n    array['contractor_id','effective_from','is_special','attendance_required','reason'],\n    array['contractor_id','effective_from','is_special','attendance_required','reason'],\n    'contractor HPP policy payload'\n  );\n\n  if jsonb_typeof(p_payload->'contractor_id') is distinct from 'string'\n     or jsonb_typeof(p_payload->'effective_from') is distinct from 'string'\n     or jsonb_typeof(p_payload->'is_special') is distinct from 'boolean'\n     or jsonb_typeof(p_payload->'attendance_required') is distinct from 'boolean'\n     or jsonb_typeof(p_payload->'reason') is distinct from 'string' then\n    raise exception 'contractor HPP policy payload has invalid field types';\n  end if;\n\n  v_contractor_id := (p_payload->>'contractor_id')::uuid;\n  v_effective_from := erp._cp3_parse_canonical_date(p_payload->>'effective_from', 'contractor HPP policy effective_from');\n  v_is_special := (p_payload->>'is_special')::boolean;\n  v_attendance_required := (p_payload->>'attendance_required')::boolean;\n  v_reason := nullif(btrim(p_payload->>'reason'), '');\n\n  if v_reason is null then raise exception 'HPP policy reason is required'; end if;\n  if v_effective_from is null then raise exception 'effective_from is required'; end if;\n\n  v_hash := erp._request_hash(jsonb_build_object(\n    'payload', p_payload,\n    'expected_policy_id', p_expected_policy_id\n  ));\n  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);\n  if v_cached is not null then return v_cached; end if;\n\n  select * into v_contractor\n  from erp.contractors\n  where id = v_contractor_id\n  for update;\n\n  if v_contractor.id is null then raise exception 'Contractor not found'; end if;\n  if v_contractor.contractor_type <> 'MANDOR' then\n    raise exception 'Attendance HPP policy is only valid for role MANDOR';\n  end if;\n  if v_contractor.attendance_required is distinct from v_attendance_required then\n    raise exception 'attendance_required payload must explicitly match contractor master; update master first, then write a new HPP policy version';\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended('CONTRACTOR_HPP_POLICY|' || v_contractor_id::text, 0));\n\n  select * into v_current\n  from erp.contractor_hpp_policy_versions p\n  where p.contractor_id = v_contractor_id\n    and v_effective_from >= p.effective_from\n    and (p.effective_to is null or v_effective_from <= p.effective_to)\n  order by p.effective_from desc, p.id desc\n  limit 1\n  for update;\n\n  if v_current.id is distinct from p_expected_policy_id then\n    raise exception 'STALE_POLICY expected %, current %', p_expected_policy_id, v_current.id;\n  end if;\n  if v_current.effective_from = v_effective_from then\n    raise exception 'A contractor HPP policy already starts on this date';\n  end if;\n\n  select min(p.effective_from) into v_next_from\n  from erp.contractor_hpp_policy_versions p\n  where p.contractor_id = v_contractor_id\n    and p.effective_from > v_effective_from;\n\n  update erp.contractor_hpp_policy_versions p\n  set effective_to = v_effective_from - 1,\n      row_version = row_version + 1\n  where p.contractor_id = v_contractor_id\n    and p.effective_from < v_effective_from\n    and (p.effective_to is null or p.effective_to >= v_effective_from);\n\n  insert into erp.contractor_hpp_policy_versions(\n    contractor_id, effective_from, effective_to,\n    contractor_role_snapshot, attendance_required_snapshot,\n    is_special, reason, created_by\n  ) values (\n    v_contractor_id, v_effective_from,\n    case when v_next_from is null then null else v_next_from - 1 end,\n    'MANDOR', v_attendance_required,\n    v_is_special, v_reason, erp.current_app_user_id()\n  ) returning * into v_new;\n\n  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)\n  values (\n    'contractor_hpp_policy_versions', v_new.id, 'INSERT',\n    jsonb_build_object(\n      'contractor_id', v_new.contractor_id,\n      'effective_from', v_new.effective_from,\n      'effective_to', v_new.effective_to,\n      'contractor_role_snapshot', v_new.contractor_role_snapshot,\n      'attendance_required_snapshot', v_new.attendance_required_snapshot,\n      'is_special', v_new.is_special\n    ),\n    erp.current_app_user_id(), v_reason\n  );\n\n  v_response := jsonb_build_object(\n    'policy_version_id', v_new.id,\n    'contractor_id', v_new.contractor_id,\n    'effective_from', v_new.effective_from,\n    'effective_to', v_new.effective_to,\n    'contractor_role_snapshot', v_new.contractor_role_snapshot,\n    'attendance_required_snapshot', v_new.attendance_required_snapshot,\n    'is_special', v_new.is_special,\n    'row_version', v_new.row_version\n  );\n  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);\nend;\n$function$\n"}]$cp45a_snapshot_20260903$::jsonb);

insert into "erp"."cp4_v2616_rollback_capsule" ("function_identity","function_definition","definition_sha256","acl_snapshot","owner_snapshot","captured_at") select "function_identity","function_definition","definition_sha256","acl_snapshot","owner_snapshot","captured_at" from jsonb_populate_recordset(null::"erp"."cp4_v2616_rollback_capsule",$cp45a_snapshot_20260903$[{"captured_at":"2026-09-02T05:29:58.607671+00:00","acl_snapshot":["postgres=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"1958ca3384edf0219352030a40e79f3f458e3a9aca8437cb0f646b1d0f87f205","function_identity":"erp.activate_attendance_hpp_pool_v1(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)","function_definition":"CREATE OR REPLACE FUNCTION erp.activate_attendance_hpp_pool_v1(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'\nAS $function$\ndeclare\n  v_operation constant text := 'activate_attendance_hpp_pool_v1';\n  v_hash text;\n  v_cached jsonb;\n  v_pool erp.attendance_hpp_pools%rowtype;\n  v_lines jsonb := '[]'::jsonb;\n  v_journal_id uuid;\n  v_line record;\n  v_response jsonb;\nbegin\n  perform erp.require_owner_admin();\n  if p_pool_id is null or p_expected_version is null then\n    raise exception 'pool_id and expected_version are required';\n  end if;\n  if coalesce(btrim(p_reason), '') = '' then\n    raise exception 'Attendance HPP activation reason is required';\n  end if;\n\n  v_hash := erp._request_hash(jsonb_build_object(\n    'pool_id', p_pool_id,\n    'reason', btrim(p_reason),\n    'expected_version', p_expected_version\n  ));\n  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);\n  if v_cached is not null then return v_cached; end if;\n\n  select * into v_pool\n  from erp.attendance_hpp_pools\n  where id = p_pool_id\n  for update;\n\n  if v_pool.id is null then raise exception 'Attendance HPP pool not found'; end if;\n  if v_pool.status <> 'DRAFT' then raise exception 'Only DRAFT attendance HPP pool can be activated'; end if;\n  if v_pool.row_version <> p_expected_version then\n    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_pool.row_version;\n  end if;\n  if v_pool.numerator_amount <= 0 or v_pool.denominator_qty <= 0 then\n    raise exception 'Attendance HPP activation requires positive numerator and immutable SELESAI_DIJAHIT denominator';\n  end if;\n\n  perform erp._cp3_lock_business_period(v_pool.period_start, v_pool.period_end);\n  perform erp._cp3_lock_manifest_contractors(v_pool.period_start, v_pool.period_end);\n\n  if exists (\n    select 1 from erp.attendance_hpp_pools p\n    where p.id <> v_pool.id\n      and p.period_start = v_pool.period_start\n      and p.period_end = v_pool.period_end\n      and p.status = 'ACTIVE'\n  ) then\n    raise exception 'Another ACTIVE attendance HPP pool already owns this exact period';\n  end if;\n\n  perform erp.validate_attendance_hpp_pool_v1(v_pool.id);\n\n  select coalesce(jsonb_agg(jsonb_build_object(\n    'mapping_key', 'WIP',\n    'debit', amount,\n    'credit', 0,\n    'contractor_id', contractor_id,\n    'po_id', po_id,\n    'description', 'Attendance HPP destination PO ' || po_id::text\n  ) order by po_id, contractor_id), '[]'::jsonb)\n  into v_lines\n  from (\n    select po_id, contractor_id, round(sum(allocated_amount),2) amount\n    from erp.attendance_hpp_pool_allocations\n    where pool_id = v_pool.id\n    group by po_id, contractor_id\n    having round(sum(allocated_amount),2) > 0\n  ) d;\n\n  v_lines := v_lines || coalesce((\n    select jsonb_agg(jsonb_build_object(\n      'account_id', jl.account_id,\n      'debit', 0,\n      'credit', round(s.attendance_amount,2),\n      'contractor_id', s.contractor_id,\n      'description', 'Attendance HPP source debit line ' || s.original_debit_journal_line_id::text\n    ) order by s.original_debit_journal_line_id)\n    from erp.attendance_hpp_pool_sources s\n    join erp.journal_lines jl on jl.id = s.original_debit_journal_line_id\n    where s.pool_id = v_pool.id\n  ), '[]'::jsonb);\n\n  v_journal_id := erp.post_journal(\n    'ATTENDANCE_HPP_POOL', v_pool.id, v_pool.period_end,\n    'Allocate normal-Mandor attendance cost by immutable SELESAI_DIJAHIT',\n    v_lines\n  );\n\n  for v_line in\n    select jl.id, jl.po_id, jl.debit\n    from erp.journal_lines jl\n    where jl.journal_entry_id = v_journal_id\n      and jl.debit > 0\n      and jl.po_id is not null\n  loop\n    insert into erp.attendance_hpp_journal_line_links(\n      pool_id, journal_line_id, link_type, po_id, amount\n    ) values (\n      v_pool.id, v_line.id, 'DESTINATION_DEBIT', v_line.po_id, v_line.debit\n    );\n  end loop;\n\n  for v_line in\n    select s.id as pool_source_id, s.original_debit_journal_line_id,\n           s.attendance_amount, jl2.id as journal_line_id\n    from erp.attendance_hpp_pool_sources s\n    join erp.journal_lines jl2\n      on jl2.journal_entry_id = v_journal_id\n     and jl2.credit = round(s.attendance_amount,2)\n     and jl2.description = 'Attendance HPP source debit line ' || s.original_debit_journal_line_id::text\n    where s.pool_id = v_pool.id\n    order by s.original_debit_journal_line_id\n  loop\n    insert into erp.attendance_hpp_journal_line_links(\n      pool_id, journal_line_id, link_type,\n      pool_source_id, original_debit_journal_line_id, amount\n    ) values (\n      v_pool.id, v_line.journal_line_id, 'SOURCE_CREDIT',\n      v_line.pool_source_id, v_line.original_debit_journal_line_id,\n      v_line.attendance_amount\n    );\n  end loop;\n\n  update erp.attendance_hpp_pools\n  set status = 'ACTIVE',\n      post_journal_entry_id = v_journal_id,\n      activated_by = erp.current_app_user_id(),\n      activated_at = clock_timestamp(),\n      row_version = row_version + 1\n  where id = v_pool.id\n  returning * into v_pool;\n\n  perform erp.validate_attendance_hpp_pool_v1(v_pool.id);\n\n  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)\n  values (\n    'attendance_hpp_pools', v_pool.id, 'POST',\n    jsonb_build_object(\n      'journal_entry_id', v_journal_id,\n      'numerator_amount', v_pool.numerator_amount,\n      'denominator_qty', v_pool.denominator_qty,\n      'manifest_sha256', v_pool.source_manifest_sha256,\n      'lifecycle_action', 'ACTIVATE'\n    ),\n    erp.current_app_user_id(), btrim(p_reason)\n  );\n\n  v_response := jsonb_build_object(\n    'pool_id', v_pool.id,\n    'status', v_pool.status,\n    'row_version', v_pool.row_version,\n    'journal_entry_id', v_pool.post_journal_entry_id,\n    'validation', 'PASS'\n  );\n  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);\nend;\n$function$\n"},{"captured_at":"2026-09-02T05:29:58.616339+00:00","acl_snapshot":["postgres=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"a11f053e3403e70e6898ca4d2049edd97cfaa66b5c545b76628d7d77691b727d","function_identity":"erp.cancel_attendance_hpp_pool_v1(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)","function_definition":"CREATE OR REPLACE FUNCTION erp.cancel_attendance_hpp_pool_v1(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'\nAS $function$\ndeclare\n  v_operation constant text := 'cancel_attendance_hpp_pool_v1';\n  v_hash text;\n  v_cached jsonb;\n  v_pool erp.attendance_hpp_pools%rowtype;\n  v_reversal_journal_id uuid;\n  v_response jsonb;\nbegin\n  perform erp.require_owner_admin();\n  if p_pool_id is null or p_expected_version is null then\n    raise exception 'pool_id and expected_version are required';\n  end if;\n  if coalesce(btrim(p_reason), '') = '' then\n    raise exception 'Attendance HPP cancellation reason is required';\n  end if;\n\n  v_hash := erp._request_hash(jsonb_build_object(\n    'pool_id', p_pool_id,\n    'reason', btrim(p_reason),\n    'expected_version', p_expected_version\n  ));\n  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);\n  if v_cached is not null then return v_cached; end if;\n\n  select * into v_pool\n  from erp.attendance_hpp_pools\n  where id = p_pool_id\n  for update;\n\n  if v_pool.id is null then raise exception 'Attendance HPP pool not found'; end if;\n  if v_pool.status not in ('DRAFT','ACTIVE') then\n    raise exception 'Only DRAFT or ACTIVE attendance HPP pool can be cancelled';\n  end if;\n  if v_pool.row_version <> p_expected_version then\n    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_pool.row_version;\n  end if;\n\n  perform erp._cp3_lock_business_period(v_pool.period_start, v_pool.period_end);\n\n  if v_pool.status = 'DRAFT' then\n    update erp.attendance_hpp_pools\n    set status = 'VOIDED',\n        cancellation_reason = btrim(p_reason),\n        cancelled_by = erp.current_app_user_id(),\n        cancelled_at = clock_timestamp(),\n        row_version = row_version + 1\n    where id = v_pool.id\n    returning * into v_pool;\n\n    insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)\n    values (\n      'attendance_hpp_pools', v_pool.id, 'UPDATE',\n      jsonb_build_object('previous_status','DRAFT','new_status','VOIDED','lifecycle_action','VOID_DRAFT'),\n      erp.current_app_user_id(), btrim(p_reason)\n    );\n\n    v_response := jsonb_build_object(\n      'pool_id', v_pool.id,\n      'status', v_pool.status,\n      'row_version', v_pool.row_version,\n      'reversal_journal_entry_id', null,\n      'residue_expected', 0\n    );\n    return erp._idempotency_complete(v_operation, p_client_request_id, v_response);\n  end if;\n\n  if v_pool.post_journal_entry_id is null then\n    raise exception 'ACTIVE attendance HPP pool has no source journal; cancellation stopped to avoid residue';\n  end if;\n\n  if not exists (\n    select 1 from erp.journal_entries je\n    where je.id = v_pool.post_journal_entry_id\n      and je.status = 'POSTED'\n      and je.source_type = 'ATTENDANCE_HPP_POOL'\n      and je.source_id = v_pool.id\n  ) then\n    raise exception 'Pool journal is not an active posted ATTENDANCE_HPP_POOL journal';\n  end if;\n\n  v_reversal_journal_id := erp._cp3_r4_reverse_journal_internal(v_pool.post_journal_entry_id, btrim(p_reason));\n\n  update erp.attendance_hpp_pools\n  set status = 'CANCELLED',\n      cancellation_journal_entry_id = v_reversal_journal_id,\n      cancellation_reason = btrim(p_reason),\n      cancelled_by = erp.current_app_user_id(),\n      cancelled_at = clock_timestamp(),\n      row_version = row_version + 1\n  where id = v_pool.id\n  returning * into v_pool;\n\n  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)\n  values (\n    'attendance_hpp_pools', v_pool.id, 'REVERSE',\n    jsonb_build_object(\n      'post_journal_entry_id', v_pool.post_journal_entry_id,\n      'cancellation_journal_entry_id', v_pool.cancellation_journal_entry_id,\n      'previous_status', 'ACTIVE',\n      'new_status', 'CANCELLED',\n      'lifecycle_action', 'CANCEL_ACTIVE'\n    ),\n    erp.current_app_user_id(), btrim(p_reason)\n  );\n\n  v_response := jsonb_build_object(\n    'pool_id', v_pool.id,\n    'status', v_pool.status,\n    'row_version', v_pool.row_version,\n    'reversal_journal_entry_id', v_pool.cancellation_journal_entry_id,\n    'residue_expected', 0\n  );\n  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);\nend;\n$function$\n"},{"captured_at":"2026-09-02T05:29:58.616629+00:00","acl_snapshot":["postgres=X/postgres","service_role=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"6eb307b0985dac3a7249a32471efe1ba21ee1a5e7b0d49977c8e823413669ec0","function_identity":"erp.rebuild_po_hpp(p_po_id uuid, p_reason text)","function_definition":"CREATE OR REPLACE FUNCTION erp.rebuild_po_hpp(p_po_id uuid, p_reason text DEFAULT 'Recalculate HPP'::text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'erp', 'public'\nAS $function$\ndeclare\n  v_material numeric(24,6):=0;\n  v_material_allocated numeric(24,6):=0;\n  v_contractor_material numeric(24,6):=0;\n  v_accessory numeric(24,6):=0;\n  v_labor numeric(24,6):=0;\n  v_commission numeric(24,6):=0;\n  v_laundry numeric(24,6):=0;\n  v_rework numeric(24,6):=0;\n  v_other numeric(24,6):=0;\n  v_shared_labor numeric(24,6):=0;\n  v_shared_commission numeric(24,6):=0;\n  v_shared_rework numeric(24,6):=0;\n  v_shared_other numeric(24,6):=0;\n  v_total_current numeric(24,6):=0;\n  v_total_qty integer:=0;\n  v_pending boolean:=false;\n  r record;\n  c record;\n  v_old_id uuid;\n  v_new_id uuid;\n  v_version integer;\n  v_lot_accessory numeric(24,6);\n  v_lot_cost numeric(24,6);\n  v_lot_material numeric(24,6);\n  v_pool_material numeric(24,6);\n  v_pool_qty numeric(24,6);\n  v_batch_id uuid;\n  v_state varchar(20);\n  v_group_fg_qty numeric(24,6);\n  v_group_labor numeric(24,6);\n  v_group_commission numeric(24,6);\n  v_group_laundry numeric(24,6);\n  v_group_rework numeric(24,6);\n  v_lot_labor numeric(24,6);\n  v_lot_commission numeric(24,6);\n  v_lot_laundry numeric(24,6);\n  v_lot_rework numeric(24,6);\n  v_lot_other numeric(24,6);\nbegin\n  perform erp.require_internal();\n  -- Serialize all HPP rebuilds for the same PO (cron recost, late invoice, QC, reversal).\n  perform pg_advisory_xact_lock(hashtextextended('PO_HPP:'||p_po_id::text,0));\n\n  select coalesce(sum(-msm.qty_signed*msm.unit_cost_snapshot),0) into v_material\n  from erp.material_stock_movements msm\n  where (msm.source_type='CUTTING_GROUP' and msm.source_id in (select id from erp.cutting_groups where po_id=p_po_id))\n     or (msm.source_type='CUTTING_GROUP_RETURN' and msm.source_id in (select id from erp.cutting_groups where po_id=p_po_id));\n\n  select coalesce(sum(cmii.qty*cmii.unit_cost_snapshot),0) into v_contractor_material\n  from erp.contractor_material_issue_items cmii\n  join erp.contractor_material_issues cmi on cmi.id=cmii.issue_id\n  join erp.materials m on m.id=cmii.material_id\n  where cmi.po_id=p_po_id and cmi.status='POSTED' and m.material_type<>'ACCESSORY';\n\n  select\n    coalesce(sum(case when wc.component_category='COMMISSION' then wcl.amount_payable else 0 end),0),\n    coalesce(sum(case when wc.component_category<>'COMMISSION' then wcl.amount_payable else 0 end),0),\n    coalesce(sum(case when wce.cutting_group_id is null and wc.component_category='COMMISSION' then wcl.amount_payable else 0 end),0),\n    coalesce(sum(case when wce.cutting_group_id is null and wc.component_category<>'COMMISSION' then wcl.amount_payable else 0 end),0)\n  into v_commission,v_labor,v_shared_commission,v_shared_labor\n  from erp.work_completion_lines wcl\n  join erp.work_completion_events wce on wce.id=wcl.completion_id\n  join erp.work_components wc on wc.id=wcl.work_component_id\n  where wce.po_id=p_po_id and wce.status='POSTED';\n\n  with dl as (\n    select ldl.id,ldl.cutting_group_id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot,\n           coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then lrl.qty_good_received+lrl.qty_bs_laundry else 0 end),0) as qty_costed_actual,\n           coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then coalesce(lrl.actual_cost,0) else 0 end),0) as actual_cost,\n           bool_or(lr.status='POSTED' and lrl.actual_cost_status='PENDING') as has_pending_receipt\n    from erp.laundry_delivery_lines ldl\n    join erp.laundry_deliveries ld on ld.id=ldl.delivery_id\n    left join erp.laundry_receipt_lines lrl on lrl.delivery_line_id=ldl.id\n    left join erp.laundry_receipts lr on lr.id=lrl.receipt_id\n    where ld.po_id=p_po_id and ld.status<>'REVERSED'\n    group by ldl.id,ldl.cutting_group_id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot\n  )\n  select coalesce(sum(actual_cost+greatest(qty_sent_pcs-qty_costed_actual,0)*coalesce(estimated_rate_snapshot,0)),0),\n         coalesce(bool_or(has_pending_receipt or (qty_sent_pcs>qty_costed_actual and estimated_rate_snapshot is null)),false)\n  into v_laundry,v_pending from dl;\n\n  select coalesce(sum(rcl.amount_payable),0),\n         coalesce(sum(case when bc.cutting_group_id is null then rcl.amount_payable else 0 end),0)\n  into v_rework,v_shared_rework\n  from erp.rework_component_lines rcl\n  join erp.rework_orders ro on ro.id=rcl.rework_order_id\n  join erp.bs_cases bc on bc.id=ro.bs_case_id\n  where bc.po_id=p_po_id and ro.status<>'CANCELLED' and coalesce(ro.cost_posted,false)=true;\n\n  select coalesce(sum(adjustment_amount),0),coalesce(sum(case when lot_id is null then adjustment_amount else 0 end),0)\n  into v_other,v_shared_other\n  from erp.cost_adjustments\n  where po_id=p_po_id and component_type='OTHER';\n\n  select coalesce(sum(initial_qty_pcs),0) into v_total_qty\n  from erp.fg_lots where po_id=p_po_id and lot_origin='PRODUCTION';\n  if v_total_qty<=0 then return; end if;\n\n  for r in select id from erp.fg_lots where po_id=p_po_id and lot_origin='PRODUCTION' order by produced_at,id\n  loop perform erp.ensure_fg_accessory_cost_snapshot(r.id); end loop;\n\n  select coalesce(sum(facs.total_hpp_cost),0) into v_accessory\n  from erp.fg_accessory_cost_snapshots facs join erp.fg_lots fl on fl.id=facs.lot_id\n  where fl.po_id=p_po_id and fl.lot_origin='PRODUCTION';\n\n  v_state:=case when v_pending then 'ESTIMATED' when exists (select 1 from erp.cost_adjustments where po_id=p_po_id) then 'ADJUSTED' else 'ACTUAL' end;\n\n  for r in\n    select fl.*,coalesce(fl.cutting_group_id,qi.cutting_group_id) as lineage_group_id\n    from erp.fg_lots fl left join erp.qc_inspection_items qi on qi.id=fl.qc_item_id\n    where fl.po_id=p_po_id and fl.lot_origin='PRODUCTION'\n    order by fl.produced_at,fl.id\n  loop\n    v_lot_material:=0;v_pool_material:=0;v_pool_qty:=0;v_batch_id:=null;\n    v_group_fg_qty:=0;v_group_labor:=0;v_group_commission:=0;v_group_laundry:=0;v_group_rework:=0;\n\n    if r.lineage_group_id is not null then\n      select cutting_batch_id into v_batch_id from erp.cutting_groups where id=r.lineage_group_id;\n      if v_batch_id is not null then\n        select coalesce(sum(-msm.qty_signed*msm.unit_cost_snapshot),0) into v_pool_material\n        from erp.material_stock_movements msm\n        where (msm.source_type='CUTTING_GROUP' and msm.source_id in (select id from erp.cutting_groups where cutting_batch_id=v_batch_id))\n           or (msm.source_type='CUTTING_GROUP_RETURN' and msm.source_id in (select id from erp.cutting_groups where cutting_batch_id=v_batch_id));\n        select effective_pcs::numeric into v_pool_qty from erp.v_cutting_batch_totals where cutting_batch_id=v_batch_id;\n      else\n        select coalesce(sum(-msm.qty_signed*msm.unit_cost_snapshot),0) into v_pool_material\n        from erp.material_stock_movements msm\n        where msm.source_id=r.lineage_group_id and msm.source_type in ('CUTTING_GROUP','CUTTING_GROUP_RETURN');\n        select total_pcs::numeric into v_pool_qty from erp.v_cutting_group_totals where cutting_group_id=r.lineage_group_id;\n      end if;\n\n      select coalesce(sum(fl2.initial_qty_pcs),0)::numeric into v_group_fg_qty\n      from erp.fg_lots fl2 where fl2.po_id=p_po_id and fl2.lot_origin='PRODUCTION' and fl2.cutting_group_id=r.lineage_group_id;\n\n      select\n        coalesce(sum(case when wc.component_category<>'COMMISSION' then wcl.amount_payable else 0 end),0),\n        coalesce(sum(case when wc.component_category='COMMISSION' then wcl.amount_payable else 0 end),0)\n      into v_group_labor,v_group_commission\n      from erp.work_completion_lines wcl\n      join erp.work_completion_events wce on wce.id=wcl.completion_id\n      join erp.work_components wc on wc.id=wcl.work_component_id\n      where wce.po_id=p_po_id and wce.status='POSTED' and wce.cutting_group_id=r.lineage_group_id;\n\n      with dl as (\n        select ldl.id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot,\n               coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then lrl.qty_good_received+lrl.qty_bs_laundry else 0 end),0) as qty_costed_actual,\n               coalesce(sum(case when lr.status='POSTED' and lrl.actual_cost_status in ('ESTIMATED','FINAL') then coalesce(lrl.actual_cost,0) else 0 end),0) as actual_cost\n        from erp.laundry_delivery_lines ldl\n        join erp.laundry_deliveries ld on ld.id=ldl.delivery_id\n        left join erp.laundry_receipt_lines lrl on lrl.delivery_line_id=ldl.id\n        left join erp.laundry_receipts lr on lr.id=lrl.receipt_id\n        where ld.po_id=p_po_id and ld.status<>'REVERSED' and ldl.cutting_group_id=r.lineage_group_id\n        group by ldl.id,ldl.qty_sent_pcs,ldl.estimated_rate_snapshot\n      )\n      select coalesce(sum(actual_cost+greatest(qty_sent_pcs-qty_costed_actual,0)*coalesce(estimated_rate_snapshot,0)),0)\n      into v_group_laundry from dl;\n\n      select coalesce(sum(rcl.amount_payable),0) into v_group_rework\n      from erp.rework_component_lines rcl\n      join erp.rework_orders ro on ro.id=rcl.rework_order_id\n      join erp.bs_cases bc on bc.id=ro.bs_case_id\n      where bc.po_id=p_po_id and bc.cutting_group_id=r.lineage_group_id and ro.status<>'CANCELLED' and coalesce(ro.cost_posted,false)=true;\n    end if;\n\n    if coalesce(v_pool_qty,0)>0 then v_lot_material:=v_pool_material*(r.initial_qty_pcs::numeric/v_pool_qty);\n    else v_lot_material:=v_material*(r.initial_qty_pcs::numeric/v_total_qty::numeric); end if;\n    v_lot_material:=v_lot_material+v_contractor_material*(r.initial_qty_pcs::numeric/v_total_qty::numeric);\n    v_material_allocated:=v_material_allocated+v_lot_material;\n\n    if coalesce(v_group_fg_qty,0)>0 then\n      v_lot_labor:=v_group_labor*(r.initial_qty_pcs::numeric/v_group_fg_qty)+v_shared_labor*(r.initial_qty_pcs::numeric/v_total_qty);\n      v_lot_commission:=v_group_commission*(r.initial_qty_pcs::numeric/v_group_fg_qty)+v_shared_commission*(r.initial_qty_pcs::numeric/v_total_qty);\n      v_lot_laundry:=v_group_laundry*(r.initial_qty_pcs::numeric/v_group_fg_qty);\n      v_lot_rework:=v_group_rework*(r.initial_qty_pcs::numeric/v_group_fg_qty)+v_shared_rework*(r.initial_qty_pcs::numeric/v_total_qty);\n    else\n      v_lot_labor:=v_labor*(r.initial_qty_pcs::numeric/v_total_qty);\n      v_lot_commission:=v_commission*(r.initial_qty_pcs::numeric/v_total_qty);\n      v_lot_laundry:=v_laundry*(r.initial_qty_pcs::numeric/v_total_qty);\n      v_lot_rework:=v_rework*(r.initial_qty_pcs::numeric/v_total_qty);\n    end if;\n\n    select coalesce(sum(total_hpp_cost),0) into v_lot_accessory from erp.fg_accessory_cost_snapshots where lot_id=r.id;\n    select coalesce(sum(adjustment_amount),0) into v_lot_other from erp.cost_adjustments where lot_id=r.id and component_type='OTHER';\n    v_lot_other:=v_lot_other+v_shared_other*(r.initial_qty_pcs::numeric/v_total_qty);\n    v_lot_cost:=v_lot_material+v_lot_labor+v_lot_commission+v_lot_laundry+v_lot_rework+v_lot_other+v_lot_accessory;\n    v_total_current:=v_total_current+v_lot_cost;\n\n    select id into v_old_id from erp.hpp_versions where lot_id=r.id and is_current=true order by version_no desc limit 1;\n    select coalesce(max(version_no),0)+1 into v_version from erp.hpp_versions where lot_id=r.id;\n    if v_old_id is not null then update erp.hpp_versions set is_current=false where id=v_old_id; end if;\n\n    insert into erp.hpp_versions(lot_id,version_no,cost_state,qty_basis_pcs,total_cost,is_current,supersedes_id,calculation_reason,created_by)\n    values (r.id,v_version,v_state,r.initial_qty_pcs,v_lot_cost,true,v_old_id,p_reason,erp.current_app_user_id()) returning id into v_new_id;\n\n    insert into erp.hpp_version_components(hpp_version_id,component_type,description,total_cost,source_type,source_id)\n    values\n      (v_new_id,'MATERIAL',case when v_batch_id is not null then 'Cutting material by effective batch yield + PO-shared non-accessory contractor material' else 'Cutting/legacy material pool + PO-shared non-accessory contractor material' end,v_lot_material,case when v_batch_id is not null then 'CUTTING_BATCH' else 'PO' end,coalesce(v_batch_id,p_po_id)),\n      (v_new_id,'LABOR','Labor allocation: same cutting group + PO-shared fallback',v_lot_labor,case when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,coalesce(r.lineage_group_id,p_po_id)),\n      (v_new_id,'COMMISSION','Commission allocation: same cutting group + PO-shared fallback',v_lot_commission,case when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,coalesce(r.lineage_group_id,p_po_id)),\n      (v_new_id,'LAUNDRY','Laundry allocation from same cutting group; PENDING uses estimate',v_lot_laundry,case when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,coalesce(r.lineage_group_id,p_po_id)),\n      (v_new_id,'REWORK','Rework allocation from same cutting group + legacy shared fallback',v_lot_rework,case when r.lineage_group_id is not null then 'CUTTING_GROUP' else 'PO' end,coalesce(r.lineage_group_id,p_po_id)),\n      (v_new_id,'OTHER','Other/adjustment allocation',v_lot_other,'PO',p_po_id);\n\n    for c in\n      select facs.id,facs.total_hpp_cost,ac.category_name,facs.hpp_method\n      from erp.fg_accessory_cost_snapshots facs join erp.accessory_categories ac on ac.id=facs.category_id\n      where facs.lot_id=r.id order by ac.category_code\n    loop\n      insert into erp.hpp_version_components(hpp_version_id,component_type,description,total_cost,source_type,source_id)\n      values (v_new_id,'ACCESSORY','Accessory category: '||c.category_name||' ['||c.hpp_method||']',c.total_hpp_cost,'FG_ACCESSORY_SNAPSHOT',c.id);\n    end loop;\n\n    update erp.fg_stock_movements set unit_hpp_snapshot=(select hpp_per_pcs from erp.hpp_versions where id=v_new_id)\n    where lot_id=r.id and movement_type in ('QC_GOOD','REWORK_IN');\n  end loop;\n\n  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)\n  values ('production_orders',p_po_id,'RECALCULATE',jsonb_build_object(\n    'material_total_issued',v_material+v_contractor_material,'cutting_material_total',v_material,'contractor_nonaccessory_material_total',v_contractor_material,'material_allocated_to_current_fg',v_material_allocated,'material_basis','CUTTING_BATCH_EFFECTIVE_YIELD_PLUS_PO_SHARED_CONTRACTOR_MATERIAL',\n    'accessory',v_accessory,'labor',v_labor,'commission',v_commission,'laundry',v_laundry,'rework',v_rework,'other',v_other,\n    'total_current_fg_cost',v_total_current,'cost_state',v_state,'nonmaterial_basis','CUTTING_GROUP_LINEAGE_WITH_PO_SHARED_FALLBACK','accessory_basis','GOOD_FG_X_CATEGORY_BOM'),\n    erp.current_app_user_id(),p_reason);\nend;\n$function$\n"},{"captured_at":"2026-09-02T05:29:58.616982+00:00","acl_snapshot":["postgres=X/postgres","service_role=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"209ea3a2cf2ad26e22ba388b34c041c95b05b704a95ba8674db3c48b768a16a8","function_identity":"erp.require_owner_admin()","function_definition":"CREATE OR REPLACE FUNCTION erp.require_owner_admin()\n RETURNS void\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'erp', 'public', 'auth'\nAS $function$ DECLARE v_jwt_role text; BEGIN IF session_user IN ('postgres','supabase_admin') THEN RETURN; END IF;BEGIN v_jwt_role:=COALESCE(auth.jwt()->>'role','');EXCEPTION WHEN OTHERS THEN v_jwt_role:='';END; IF v_jwt_role='service_role' THEN RETURN; END IF; IF erp.current_app_role() NOT IN ('OWNER','ADMIN') THEN RAISE EXCEPTION 'OWNER or ADMIN access required'; END IF;END; $function$\n"}]$cp45a_snapshot_20260903$::jsonb);

insert into "erp"."cp45_v2617_rollback_capsule" ("function_identity","function_definition","definition_sha256","acl_snapshot","owner_snapshot","captured_at") select "function_identity","function_definition","definition_sha256","acl_snapshot","owner_snapshot","captured_at" from jsonb_populate_recordset(null::"erp"."cp45_v2617_rollback_capsule",$cp45a_snapshot_20260903$[{"captured_at":"2026-09-02T14:49:11.978731+00:00","acl_snapshot":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"f34882868e0d28144c5a5ba683ef73c8ac24353a9a6148182c2140455f2a5de9","function_identity":"erp.current_app_role()","function_definition":"CREATE OR REPLACE FUNCTION erp.current_app_role()\n RETURNS text\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'erp', 'public', 'auth'\nAS $function$ SELECT au.role FROM erp.app_users au WHERE au.auth_user_id=auth.uid() AND au.is_active=true LIMIT 1 $function$\n"},{"captured_at":"2026-09-02T14:49:11.98256+00:00","acl_snapshot":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"16194135f1f9940cfc12ac14393948447527ccc21644161532516d3bf778786b","function_identity":"erp.current_app_user_id()","function_definition":"CREATE OR REPLACE FUNCTION erp.current_app_user_id()\n RETURNS uuid\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'erp', 'public', 'auth'\nAS $function$ SELECT au.id FROM erp.app_users au WHERE au.auth_user_id=auth.uid() AND au.is_active=true LIMIT 1 $function$\n"},{"captured_at":"2026-09-02T14:49:11.98266+00:00","acl_snapshot":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"b98a40e6d2f5c7f1ee1409886444a8b0452ae7171ac68b92eaf9e6c3a6a9b628","function_identity":"erp.save_app_user_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint)","function_definition":"CREATE OR REPLACE FUNCTION erp.save_app_user_v2(p_payload jsonb, p_client_request_id uuid, p_expected_version bigint DEFAULT NULL::bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'\nAS $function$\ndeclare\n  v_hash text;\n  v_cached jsonb;\n  v_response jsonb;\n  v_id uuid := nullif(p_payload->>'id', '')::uuid;\n  v_target erp.app_users%rowtype;\n  v_actor_role text := erp.current_app_role();\n  v_new_role text := upper(coalesce(nullif(btrim(p_payload->>'role'), ''), 'STAFF'));\n  v_new_active boolean := coalesce((p_payload->>'is_active')::boolean, true);\n  v_new_auth_user_id uuid;\n  v_reason text := nullif(btrim(p_payload->>'change_reason'), '');\nbegin\n  perform erp.require_owner_admin();\n  if v_actor_role is null and session_user in ('postgres', 'supabase_admin') then\n    v_actor_role := 'OWNER';\n  end if;\n  if v_reason is null then raise exception 'change_reason is required'; end if;\n  if coalesce(btrim(p_payload->>'full_name'), '') = '' then raise exception 'full_name is required'; end if;\n  if v_new_role not in ('OWNER','ADMIN','STAFF','CUSTOMER') then raise exception 'Invalid app role'; end if;\n\n  v_hash := erp._request_hash(jsonb_build_object('payload', p_payload, 'expected_version', p_expected_version));\n  v_cached := erp._idempotency_begin('save_app_user_v2', p_client_request_id, v_hash);\n  if v_cached is not null then return v_cached; end if;\n  perform set_config('app.change_reason', v_reason, true);\n\n  if v_id is null then\n    if p_expected_version is not null then raise exception 'expected_version must be null when creating a user'; end if;\n    if v_actor_role = 'ADMIN' and v_new_role in ('OWNER','ADMIN') then\n      raise exception 'ADMIN cannot create OWNER or ADMIN';\n    end if;\n    v_new_auth_user_id := nullif(p_payload->>'auth_user_id', '')::uuid;\n    insert into erp.app_users(auth_user_id, full_name, role, is_active)\n    values (v_new_auth_user_id, btrim(p_payload->>'full_name'), v_new_role, v_new_active)\n    returning * into v_target;\n  else\n    if p_expected_version is null then raise exception 'expected_version is required when updating a user'; end if;\n    select * into v_target from erp.app_users where id = v_id for update;\n    if v_target.id is null then raise exception 'App user not found'; end if;\n    if v_target.row_version <> p_expected_version then\n      raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_target.row_version;\n    end if;\n    if v_actor_role = 'ADMIN' and (v_target.role in ('OWNER','ADMIN') or v_new_role in ('OWNER','ADMIN')) then\n      raise exception 'ADMIN cannot mutate OWNER or ADMIN';\n    end if;\n    if v_target.role = 'OWNER' and v_target.is_active\n       and (v_new_role <> 'OWNER' or not v_new_active)\n       and not exists (\n         select 1 from erp.app_users\n         where id <> v_target.id and role = 'OWNER' and is_active\n       ) then\n      raise exception 'The last active OWNER cannot be demoted or deactivated';\n    end if;\n    v_new_auth_user_id := case\n      when p_payload ? 'auth_user_id' then nullif(p_payload->>'auth_user_id', '')::uuid\n      else v_target.auth_user_id\n    end;\n    update erp.app_users\n    set auth_user_id = v_new_auth_user_id,\n        full_name = btrim(p_payload->>'full_name'),\n        role = v_new_role,\n        is_active = v_new_active,\n        updated_at = now()\n    where id = v_id\n    returning * into v_target;\n  end if;\n\n  v_response := jsonb_build_object(\n    'app_user_id', v_target.id,\n    'role', v_target.role,\n    'is_active', v_target.is_active,\n    'row_version', v_target.row_version\n  );\n  return erp._idempotency_complete('save_app_user_v2', p_client_request_id, v_response);\nend;\n$function$\n"}]$cp45a_snapshot_20260903$::jsonb);

insert into "erp"."cp45_v2617a_rollback_capsule" ("function_identity","function_definition","definition_sha256","acl_snapshot","owner_snapshot","captured_at") select "function_identity","function_definition","definition_sha256","acl_snapshot","owner_snapshot","captured_at" from jsonb_populate_recordset(null::"erp"."cp45_v2617a_rollback_capsule",$cp45a_snapshot_20260903$[{"captured_at":"2026-09-02T18:51:06.990235+00:00","acl_snapshot":["postgres=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"33a4c960e49c796dd5c79ad067e75511f6b6c165744469ae6ade8dc863055368","function_identity":"erp.guard_pattern_assignment_snapshot()","function_definition":"CREATE OR REPLACE FUNCTION erp.guard_pattern_assignment_snapshot()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_pattern erp.production_patterns%rowtype;\nbegin\n  if tg_op='UPDATE' and new.pattern_id is not distinct from old.pattern_id then\n    if new.pattern_code_snapshot is distinct from old.pattern_code_snapshot\n       or new.pattern_name_snapshot is distinct from old.pattern_name_snapshot\n       or new.pattern_revision_snapshot is distinct from old.pattern_revision_snapshot\n       or new.pattern_type is distinct from old.pattern_type then\n      raise exception using errcode='42501',message='PATTERN_ASSIGNMENT_SNAPSHOT_IMMUTABLE';\n    end if;\n    return new;\n  end if;\n  if new.pattern_id is null then\n    new.pattern_code_snapshot:=null;\n    new.pattern_name_snapshot:=null;\n    new.pattern_revision_snapshot:=null;\n    new.pattern_type:=null;\n    return new;\n  end if;\n  select * into v_pattern from erp.production_patterns where id=new.pattern_id and is_active;\n  if v_pattern.id is null then\n    raise exception using errcode='23503',message='ACTIVE_PATTERN_REQUIRED_FOR_NEW_ASSIGNMENT';\n  end if;\n  new.pattern_code_snapshot:=v_pattern.pattern_code;\n  new.pattern_name_snapshot:=v_pattern.pattern_name;\n  new.pattern_revision_snapshot:=v_pattern.revision;\n  new.pattern_type:=v_pattern.pattern_name;\n  return new;\nend\n$function$\n"},{"captured_at":"2026-09-02T18:51:06.994814+00:00","acl_snapshot":["postgres=X/postgres"],"owner_snapshot":"postgres","definition_sha256":"69b54f9ab0ae5f82614ae6ded472918a93a1805a328ab3ecb8b595634feff398","function_identity":"erp.assign_pattern_v1(p_cutting_group_id uuid, p_pattern_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)","function_definition":"CREATE OR REPLACE FUNCTION erp.assign_pattern_v1(p_cutting_group_id uuid, p_pattern_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_group erp.cutting_groups%rowtype;v_pattern erp.production_patterns%rowtype;\n  v_hash text;v_cached jsonb;v_response jsonb;v_actor uuid:=erp.current_app_user_id();v_old_snapshot jsonb;\nbegin\n  if not erp.has_permission('production.cutting.edit_draft')\n     and not erp.has_permission('production.wip.adjust') then\n    raise exception using errcode='42501',message='PERMISSION_DENIED: production pattern assignment';\n  end if;\n  if nullif(btrim(p_reason),'') is null then raise exception 'reason is required'; end if;\n  if p_pattern_id is null then\n    raise exception using errcode='23502',message='PATTERN_ID_REQUIRED_FOR_CUTTING_TRANSACTION';\n  end if;\n  v_hash:=erp._request_hash(jsonb_build_object(\n    'cutting_group_id',p_cutting_group_id,'pattern_id',p_pattern_id,\n    'reason',btrim(p_reason),'expected_version',p_expected_version\n  ));\n  v_cached:=erp._idempotency_begin('assign_pattern_v1',p_client_request_id,v_hash);\n  if v_cached is not null then return v_cached; end if;\n  select * into v_group from erp.cutting_groups where id=p_cutting_group_id for update;\n  if v_group.id is null then raise exception 'Potongan not found'; end if;\n  if v_group.row_version<>p_expected_version then raise exception 'STALE_VERSION expected %, current %',p_expected_version,v_group.row_version; end if;\n  select * into v_pattern from erp.production_patterns where id=p_pattern_id;\n  if v_pattern.id is null or not v_pattern.is_active then raise exception 'Active pattern is required for new assignment'; end if;\n  v_old_snapshot:=jsonb_build_object(\n    'pattern_id',v_group.pattern_id,'code',v_group.pattern_code_snapshot,\n    'revision',v_group.pattern_revision_snapshot,'name',v_group.pattern_name_snapshot\n  );\n  update erp.cutting_groups set pattern_id=p_pattern_id,updated_at=clock_timestamp()\n  where id=v_group.id returning * into v_group;\n  insert into erp.production_pattern_audit(\n    entity_type,entity_id,pattern_id,action,old_data,new_data,change_reason,client_request_id,actor_app_user_id\n  ) values(\n    'ASSIGNMENT',v_group.id,p_pattern_id,'ASSIGN',\n    v_old_snapshot,\n    jsonb_build_object(\n      'pattern_id',v_group.pattern_id,'code',v_group.pattern_code_snapshot,\n      'revision',v_group.pattern_revision_snapshot,'name',v_group.pattern_name_snapshot,\n      'pattern_type_snapshot',v_group.pattern_type,'row_version',v_group.row_version\n    ),\n    btrim(p_reason),p_client_request_id,v_actor\n  );\n  v_response:=jsonb_build_object(\n    'cutting_group_id',v_group.id,'pattern_id',v_group.pattern_id,\n    'code_snapshot',v_group.pattern_code_snapshot,'revision_snapshot',v_group.pattern_revision_snapshot,\n    'name_snapshot',v_group.pattern_name_snapshot,'pattern_type_snapshot',v_group.pattern_type,\n    'row_version',v_group.row_version\n  );\n  return erp._idempotency_complete('assign_pattern_v1',p_client_request_id,v_response);\nend\n$function$\n"}]$cp45a_snapshot_20260903$::jsonb);

